const api = "\n\nconst STORAGE_KEY = \"spk_suivi_optimisation_v1\";\nconst LEGACY_KEY = \"spk_op10_bilan_v3\"; // ancien format mono-reference, repris automatiquement\n\n/* Identifiants uniques : prefix + timestamp base36 + aleatoire. Date.now() seul collisionne\n   des qu'un meme geste cr\u00e9e plusieurs objets dans la meme milliseconde (double-clic,\n   import, scripts) \u2014 la collision ecrase silencieusement des donnees (audit v4.4.0).\n   Pattern deja utilise pour e/p/t/g, etendu a s/l/r/o. pj reste gere par normalizeProjet. */\nfunction uid(prefix){ return prefix + Date.now().toString(36) + Math.random().toString(36).slice(2,6); }\n\n/* ---- dialogues in-app + focus des panneaux (v4.6) ----\n   Derniers vestiges de fenetres natives : 27 alert(), 20 confirm() et 4 prompt() s'affichaient\n   en fenetres systeme grises. Deux problemes : elles cassaient l'identite visuelle (et le mode\n   nuit), et leur texte ne supportait aucune mise en forme \u2014 les messages les plus importants\n   de l'outil (panne de stockage, garde-fou double comptage) etaient des murs de texte brut.\n   Ces dialogues gardent la semantique du natif : Echap / clic hors panneau = Annuler,\n   Entree = valider, promesse resolue avec la valeur (booleen, ou texte saisi / null).\n   Plac\u00e9 ici, avant loadAll() : le garde-fou anti-arbre-vide peut poser sa question des\n   le chargement \u2014 les declarations \"let\" du bloc seraient en zone morte plus bas. */\nlet panneauPile = [];\nlet focusAvantPanneau = null;\nlet dialogEnAttente = null;\nconst SELECTEUR_FOCUSABLE = 'button:not([disabled]), input:not([disabled]):not([type=\"file\"]), select:not([disabled]), textarea:not([disabled]), a[href], [tabindex]:not([tabindex=\"-1\"])';\n\nfunction dlgTexte(t){\n  return String(t ?? \"\").replace(/&/g,\"&amp;\").replace(/</g,\"&lt;\").replace(/>/g,\"&gt;\").replace(/\"/g,\"&quot;\").replace(/\\n/g,\"<br>\");\n}\nfunction ouvrirDialogue(opts){\n  return new Promise(resolve => {\n    fermerDialogue(); // un dialogue oublie ouvert ne doit pas laisser sa promesse en suspens\n    const row = document.getElementById(\"dialogInputRow\");\n    const input = document.getElementById(\"dialogInput\");\n    const avecSaisie = Object.prototype.hasOwnProperty.call(opts, \"saisie\");\n    document.getElementById(\"dialogTitle\").textContent = opts.titre || \"Information\";\n    document.getElementById(\"dialogBody\").innerHTML = opts.html || \"\";\n    row.hidden = !avecSaisie;\n    if(avecSaisie){ input.value = opts.saisie || \"\"; input.placeholder = opts.placeholder || \"\"; }\n    const annuler = document.getElementById(\"dialogCancel\");\n    const ok = document.getElementById(\"dialogOk\");\n    annuler.hidden = opts.sansAnnuler === true;\n    ok.textContent = opts.okLabel || (opts.sansAnnuler ? \"Fermer\" : \"Confirmer\");\n    ok.classList.toggle(\"danger\", opts.danger === true);\n    dialogEnAttente = { resolve, avecSaisie };\n    ouvrirPanneau(\"dialogPanel\");\n    if(avecSaisie){ input.focus(); input.select(); }\n    else if(!annuler.hidden) annuler.focus(); // defaut au clavier : le geste reversible\n    else ok.focus();\n  });\n}\nfunction fermerDialogue(valeur){\n  const pan = document.getElementById(\"dialogPanel\");\n  if(!pan || pan.hidden) return;\n  pan.hidden = true;\n  panneauPile = panneauPile.filter(id => id !== \"dialogPanel\");\n  if(!panneauPile.length){\n    document.getElementById(\"panelBackdrop\").hidden = true;\n    restaurerFocusPanneau();\n  }\n  if(dialogEnAttente){\n    const d = dialogEnAttente; dialogEnAttente = null;\n    d.resolve(valeur === undefined ? (d.avecSaisie ? null : false) : valeur);\n  }\n}\nfunction dialogueAlerte(texte, titre){\n  return ouvrirDialogue({ titre: titre || \"Information\", html: dlgTexte(texte), sansAnnuler: true });\n}\nfunction dialogueConfirmer(texte, opts){\n  opts = opts || {};\n  return ouvrirDialogue({ titre: opts.titre || \"Confirmer ?\", html: opts.html || dlgTexte(texte), danger: opts.danger, okLabel: opts.okLabel }).then(ok => !!ok);\n}\nfunction dialogueDemander(texte, valeur, opts){\n  opts = opts || {};\n  return ouvrirDialogue({ titre: opts.titre || \"Saisie\", html: dlgTexte(texte), saisie: valeur, placeholder: opts.placeholder, okLabel: opts.okLabel || \"Valider\", danger: opts.danger });\n}\nfunction restaurerFocusPanneau(){\n  if(focusAvantPanneau && document.contains(focusAvantPanneau)){\n    try{ focusAvantPanneau.focus({ preventScroll:true }); }catch(e){}\n  }\n  focusAvantPanneau = null;\n}\ndocument.getElementById(\"dialogOk\").addEventListener(\"click\", () => {\n  if(!dialogEnAttente) return;\n  fermerDialogue(dialogEnAttente.avecSaisie ? document.getElementById(\"dialogInput\").value : true);\n});\ndocument.getElementById(\"dialogCancel\").addEventListener(\"click\", () => fermerDialogue(false));\ndocument.getElementById(\"dialogInput\").addEventListener(\"keydown\", e => {\n  if(e.key === \"Enter\"){ e.preventDefault(); fermerDialogue(document.getElementById(\"dialogInput\").value); }\n});\n/* Tab reste piege dans le panneau du dessus : sans cela, le focus s'echappe derriere\n   le voile \u2014 on tabule dans une page invisible, et Echap devient le seul recours. */\ndocument.addEventListener(\"keydown\", e => {\n  if(e.key !== \"Tab\") return;\n  const idPan = panneauPile[panneauPile.length - 1];\n  if(!idPan) return;\n  const pan = document.getElementById(idPan);\n  if(!pan || pan.hidden) return;\n  const items = Array.from(pan.querySelectorAll(SELECTEUR_FOCUSABLE)).filter(el => el.getClientRects().length > 0);\n  if(!items.length) return;\n  const dedans = pan.contains(document.activeElement);\n  if(e.shiftKey){\n    if(!dedans || document.activeElement === items[0]){ e.preventDefault(); items[items.length - 1].focus(); }\n  } else {\n    if(!dedans || document.activeElement === items[items.length - 1]){ e.preventDefault(); items[0].focus(); }\n  }\n});\n\n/* ---- dossier local (photos + backup) ----\n   Les photos ne doivent JAMAIS gonfler le localStorage/JSON echange entre collegues : elles\n   sont ecrites comme de vrais fichiers dans un dossier choisi sur le disque (API File System\n   Access, Edge/Chrome uniquement, necessite https:// ou localhost). Seule une reference legere\n   (nom de fichier) est gardee dans les donnees. Disponible seulement depuis la version en ligne\n   (Surge) ou un serveur local \u2014 pas depuis le fichier ouvert en file://. */\nlet photosDirHandle = null;\nfunction fsPhotosSupported(){ return typeof window.showDirectoryPicker === \"function\"; }\nfunction idbOpenFs(){\n  return new Promise((resolve, reject) => {\n    const req = indexedDB.open(\"spk_suivi_fs\", 1);\n    req.onupgradeneeded = () => req.result.createObjectStore(\"handles\");\n    req.onsuccess = () => resolve(req.result);\n    req.onerror = () => reject(req.error);\n  });\n}\nasync function idbSetHandle(key, handle){\n  const db = await idbOpenFs();\n  return new Promise((resolve, reject) => {\n    const tx = db.transaction(\"handles\", \"readwrite\");\n    tx.objectStore(\"handles\").put(handle, key);\n    tx.oncomplete = () => resolve();\n    tx.onerror = () => reject(tx.error);\n  });\n}\nasync function idbGetHandle(key){\n  const db = await idbOpenFs();\n  return new Promise((resolve, reject) => {\n    const tx = db.transaction(\"handles\", \"readonly\");\n    const req = tx.objectStore(\"handles\").get(key);\n    req.onsuccess = () => resolve(req.result || null);\n    req.onerror = () => reject(req.error);\n  });\n}\nfunction slugify(txt){\n  return String(txt||\"\").normalize(\"NFD\").replace(/[\\u0300-\\u036f]/g,\"\")\n    .replace(/[^a-zA-Z0-9]+/g,\"-\").replace(/^-+|-+$/g,\"\").slice(0,40) || \"x\";\n}\n/* redimensionne cote client avant ecriture : une photo de telephone peut peser plusieurs\n   Mo, inutile de la garder brute pour une consultation a l'ecran */\nfunction compressImageFile(file, maxDim, quality){\n  return new Promise((resolve, reject) => {\n    // ObjectURL plutot qu'un data URL base64 : evite de doubler la photo en memoire\n    // (base64 gonfle ~33%, plus la decompression de l'<img>) \u2014 sensible sur un JPEG de\n    // telephone a 8+ Mo, potentiellement OOM sur mobile/Safari\n    const img = new Image();\n    const url = URL.createObjectURL(file);\n    img.onload = () => {\n      const scale = Math.min(1, maxDim / Math.max(img.width, img.height));\n      const canvas = document.createElement(\"canvas\");\n      canvas.width = Math.round(img.width * scale);\n      canvas.height = Math.round(img.height * scale);\n      canvas.getContext(\"2d\").drawImage(img, 0, 0, canvas.width, canvas.height);\n      URL.revokeObjectURL(url);\n      canvas.toBlob(blob => blob ? resolve(blob) : reject(new Error(\"compression \u00e9chou\u00e9e\")), \"image/jpeg\", quality);\n    };\n    img.onerror = () => { URL.revokeObjectURL(url); reject(new Error(\"lecture image \u00e9chou\u00e9e\")); };\n    img.src = url;\n  });\n}\nasync function connectPhotosDir(){\n  if(!fsPhotosSupported()){\n    dialogueAlerte(\"Cette fonction (dossier photos local) n\u00e9cessite Edge ou Chrome sur ordinateur, et d'ouvrir l'outil via son adresse en ligne (https://...) plut\u00f4t que le fichier local.\", \"Dossier local indisponible\");\n    return;\n  }\n  try{\n    const handle = await window.showDirectoryPicker({ id: \"spk-photos\", mode: \"readwrite\" });\n    photosDirHandle = handle;\n    await idbSetHandle(\"photosDir\", handle);\n    updatePhotosDirUI();\n    render();\n  }catch(e){ /* utilisateur a annul\u00e9 la s\u00e9lection */ }\n}\nasync function tryReconnectPhotosDir(){\n  if(!fsPhotosSupported()) return;\n  try{\n    const handle = await idbGetHandle(\"photosDir\");\n    if(!handle) return;\n    const perm = await handle.queryPermission({ mode: \"readwrite\" });\n    if(perm === \"granted\"){ photosDirHandle = handle; }\n    updatePhotosDirUI();\n  }catch(e){}\n}\nfunction updatePhotosDirUI(){\n  const el = document.getElementById(\"photosDirStatus\");\n  if(!el) return;\n  if(!fsPhotosSupported()){ el.textContent = \"\"; return; }\n  el.textContent = photosDirHandle ? \"\ud83d\udcc1 Dossier photos connect\u00e9 (\" + photosDirHandle.name + \")\" : \"\ud83d\udcc1 Dossier photos non connect\u00e9\";\n  el.className = \"save-status\" + (photosDirHandle ? \" saved\" : \"\");\n}\nasync function writePhotoBlob(filename, blob){\n  const fh = await photosDirHandle.getFileHandle(filename, { create: true });\n  const w = await fh.createWritable();\n  await w.write(blob);\n  await w.close();\n}\nasync function readPhotoURL(filename){\n  try{\n    const fh = await photosDirHandle.getFileHandle(filename);\n    const file = await fh.getFile();\n    return URL.createObjectURL(file);\n  }catch(e){\n    // l'echec peut venir d'une permission revoquee en cours de session (parametres du\n    // navigateur) : sans ce controle, ca restait invisible \u2014 la prochaine lecture photo\n    // echouait silencieusement, sans indication a l'utilisateur\n    checkPhotosDirPermission();\n    return null;\n  }\n}\nasync function checkPhotosDirPermission(){\n  if(!photosDirHandle) return;\n  try{\n    const perm = await photosDirHandle.queryPermission({ mode:\"readwrite\" });\n    if(perm !== \"granted\"){ photosDirHandle = null; updatePhotosDirUI(); }\n  }catch(e){ photosDirHandle = null; updatePhotosDirUI(); }\n}\nasync function deletePhotoFile(filename){\n  try{ await photosDirHandle.removeEntry(filename); }catch(e){}\n}\n/* v4.16 \u2014 lecture d'une photo quel que soit son mode. Version de base ici (dossier\n   local, photos cloud indisponibles) : le bloc cloud, charg\u00e9 juste apr\u00e8s, R\u00c9D\u00c9FINIT\n   cette fonction avec le t\u00e9l\u00e9chargement + cache. Un stub est n\u00e9cessaire parce que\n   loadPhotoThumbnails tourne au premier rendu, AVANT que le bloc cloud n'existe. */\nlet cloudPhotoErreurDerniere = \"\";\nfunction photoObjectURL(p){\n  if(!p) return null;\n  if(p.stockage === \"cloud\") return null; // le bloc cloud apporte le vrai chargement\n  return readPhotoURL(p.filename);\n}\n/* backup general dans le meme dossier (sous-dossier backups/), independant du localStorage :\n   filet de securite supplementaire, au plus 1 ecriture toutes les 5 minutes, 20 fichiers gardes */\nlet lastFolderBackupAt = 0;\nasync function writeBackupToFolder(){\n  if(!photosDirHandle) return;\n  const now = Date.now();\n  if(now - lastFolderBackupAt < 5*60*1000) return;\n  lastFolderBackupAt = now;\n  try{\n    const backupsDir = await photosDirHandle.getDirectoryHandle(\"backups\", { create: true });\n    const stamp = new Date().toISOString().replace(/[:.]/g,\"-\");\n    const payload = { outil:\"SPK Suivi optimisation\", format:8, toolVersion:TOOL_VERSION, revision, exporteLe:new Date().toISOString(), exportePar:auteurNom, lignes, projets, activeProjetId, responsables, backlog };\n    const fh = await backupsDir.getFileHandle(stamp + \".json\", { create: true });\n    const w = await fh.createWritable();\n    await w.write(JSON.stringify(payload));\n    await w.close();\n    // purge : ne garde que les 20 plus recents (tri par nom = tri chronologique, stamp ISO)\n    const noms = [];\n    for await (const [name] of backupsDir.entries()) noms.push(name);\n    noms.sort();\n    const trop = noms.length - 20;\n    for(let i=0;i<trop;i++){ try{ await backupsDir.removeEntry(noms[i]); }catch(e){} }\n  }catch(e){}\n}\n\n/* Modules optionnels \u2014 activ\u00e9s seulement si le besoin s'en fait sentir */\nconst defaultConfig = {\n  limitLabel: \"Battement (mm)\", // grandeur suivie sur toute la campagne\n  limitValue: 0.12,             // tol\u00e9rance de r\u00e9f\u00e9rence, commune \u00e0 tous les sc\u00e9narios\n  coutRebutActif: false,   // int\u00e8gre le co\u00fbt des disques rebut\u00e9s au co\u00fbt pi\u00e8ce\n  coutDisque: \"\",          // \u20ac perdus par disque rebut\u00e9 (mati\u00e8re + valeur ajout\u00e9e)\n  cycleSecActif: false,    // convertit l'indice de cycle en secondes r\u00e9elles\n  cycleRefSec: \"\",         // temps de cycle du sc\u00e9nario de r\u00e9f\u00e9rence, en secondes\n  coutMachineActif: false, // convertit l'ecart de temps de cycle en euros (co\u00fbt horaire de la ligne)\n  partCoupante: 100,       // % du cycle de reference reellement en coupe (le reste \u2014 chargement,\n                           // approche, retrait \u2014 ne bouge pas quand Vc/f changent)\n  cycleDetailActif: false, // temps coupe + deplacement mesures machine, par logement, au lieu\n                           // d'un indice base 100 global (voir cycleDetailStatus)\n  piecesActif: false,      // pieces detachees amorties par porte-outil\n  volumeActif: false,      // volume annuel de la reference -> gains en \u20ac/an\n  forceRatioActif: false,  // affiche Fr/Fa (effort radial/axial) : specifique a certaines references (bruts peu matures...), pas systematique\n  ecartCharniereTolerance: 0.5 // marge (pieces) avant qu'un ecart de charniere soit signale ; etait fige en dur\n};\n\nconst OUTIL_COLORS = [\"#3b82f6\",\"#14b8a6\",\"#a78bfa\",\"#f59e0b\",\"#22c55e\",\"#94a3b8\",\"#ec4899\",\"#0ea5e9\"];\n\n/* Donnees fictives : le nom, les references plaquette et les mesures ne doivent JAMAIS\n   provenir d'une saisie reelle client \u2014 ce jeu tourne au premier lancement et apres\n   Reinitialiser, et voyage donc dans le depot Git et sur tout deploiement (Surge). Un\n   ancien jeu reprenait par erreur des donnees reelles d'essai (memes references, memes\n   mesures qu'un export terrain) : corrige, plus aucune valeur ci-dessous n'est reelle. */\nconst defaultScenarios = [\n  { id: \"s1\", name: \"[Exemple] Process actuel\", baseline: true, cycle: 100,\n    emag1: true, limitOverride: false, limitLabel: \"Battement (mm)\", limitValue: 0.12, validationThreshold: 5,\n    outils: [ { id: \"t1\", numero: \"T-EX1\", logements: [\n      { id: \"g1\", nom: \"Bol\",   ref: \"Plaquette exemple A\", prix: 30, aretes: 8, charniere: 100, vc: \"\", f: \"\" },\n      { id: \"g2\", nom: \"Piste\", ref: \"Plaquette exemple A\", prix: 30, aretes: 8, charniere: 100, vc: 800, f: 0.40 }\n    ] } ],\n    essais: [ { id: \"e1\", titre: \"Essai 1\", date: \"2026-01-15\", equipe: \"\", operateur: \"\", observations: \"\",\n      params: { logements: [ { outilId:\"t1\", logementId:\"g2\", outilNumero:\"T-EX1\", logementNom:\"Piste\", vc:800, f:0.40, charniere:100 } ] },\n      prelevements: [ { id: \"p1\", piece: 100, batt: 0.08, battD: \"\", battG: \"\" } ] } ],\n    scrapLog: [] },\n  { id: \"s2\", name: \"[Exemple] Sc\u00e9nario alternatif A\", baseline: false, cycle: \"\",\n    emag1: true, limitOverride: false, limitLabel: \"Battement (mm)\", limitValue: 0.12, validationThreshold: 5,\n    outils: [ { id: \"t2\", numero: \"T-EX2\", logements: [\n      { id: \"g3\", nom: \"Bol\",   ref: \"Plaquette exemple A\", prix: 30, aretes: 8, charniere: 100, vc: \"\", f: \"\" },\n      { id: \"g4\", nom: \"Piste\", ref: \"Plaquette exemple B\", prix: 15, aretes: 8, charniere: 150, vc: 650, f: 0.30 }\n    ] } ],\n    essais: [ { id: \"e1\", titre: \"Essai 1\", date: \"2026-01-15\", equipe: \"\", operateur: \"\", observations: \"\",\n      params: { logements: [ { outilId:\"t2\", logementId:\"g4\", outilNumero:\"T-EX2\", logementNom:\"Piste\", vc:650, f:0.30, charniere:150 } ] },\n      prelevements: [ { id: \"p1\", piece: 150, batt: 0.09, battD: \"\", battG: \"\" } ] } ],\n    scrapLog: [] },\n  { id: \"s3\", name: \"[Exemple] Sc\u00e9nario alternatif B\", baseline: false, cycle: \"\",\n    emag1: true, limitOverride: false, limitLabel: \"Battement (mm)\", limitValue: 0.12, validationThreshold: 5,\n    outils: [ { id: \"t3\", numero: \"T-EX2\", logements: [\n      { id: \"g5\", nom: \"Bol\",   ref: \"Plaquette exemple B\", prix: 15, aretes: 8, charniere: 150, vc: \"\", f: \"\" },\n      { id: \"g6\", nom: \"Piste\", ref: \"Plaquette exemple B\", prix: 15, aretes: 8, charniere: 150, vc: 650, f: 0.30 }\n    ] } ],\n    essais: [ { id: \"e1\", titre: \"Essai 1\", date: \"2026-01-15\", equipe: \"\", operateur: \"\", observations: \"\",\n      params: { logements: [ { outilId:\"t3\", logementId:\"g6\", outilNumero:\"T-EX2\", logementNom:\"Piste\", vc:650, f:0.30, charniere:150 } ] },\n      prelevements: [ { id: \"p1\", piece: 150, batt: 0.09, battD: \"\", battG: \"\" } ] } ],\n    scrapLog: [] }\n];\n\nfunction defaultLignes(){\n  return [{\n    id: \"l1\", nom: \"EMAG 1\",\n    references: [{\n      id: \"r1\", nom: \"[Exemple] R\u00e9f\u00e9rence disque\",\n      ops: [{\n        id: \"o1\", nom: \"OP10\", ordre: 10,\n        config: Object.assign({}, defaultConfig, { forceRatioActif: true }),\n        // normalizeScenario meme sur les donnees de depart : sans lui elles n'heritent pas des\n        // migrations (ex. batt -> battD/battG en mode EMAG 1), et le graphique restait vide a\n        // la premiere ouverture sur les scenarios EMAG 1.\n        scenarios: JSON.parse(JSON.stringify(defaultScenarios)).map(normalizeScenario)\n      }]\n    }]\n  }];\n}\n\n/* ---- hierarchie Ligne de production > Reference disque > OP > Scenario > Essai > Prelevement ---- */\n/* Projets (v4.1) : liste d'etiquettes posees sur des scenarios de `lignes`. Racine au\n   meme titre que `lignes`, jamais imbriques l'un dans l'autre. */\nlet projets = [];\nlet activeProjetId = null; // null = aucun filtre actif (\"Tous les projets\")\n/* Responsables (v4.2) : liste geree de personnes, chacune avec une couleur, referencee par\n   projet.responsableId. Racine, comme projets -- une personne existe independamment des\n   projets qu'elle pilote (elle peut ne plus en piloter aucun sans etre supprimee). */\nlet responsables = [];\nlet lignes = [];\nlet backlog = [];\nlet revision = 0;\nlet activeLigneId = null;\nlet activeReferenceId = null;\nlet activeOpId = null;\n// data/config pointent toujours sur les tableaux/objets de l'OP active (memes references\n// memoire) : muter data/config mute directement l'arbre lignes, sans recopie.\nlet data = [];\nlet config = {};\nlet activeId = null;\n// essais repli\u00e9s en tuiles : quels id restent \"d\u00e9pli\u00e9s\" d'un render() a l'autre\n// (chaque saisie de mesure regenere tout le HTML - sans ca, une tuile ouverte se\n// refermerait a chaque champ valide).\nlet essaisOuverts = new Set();\n/* v4.14 \u2014 d\u00e9clar\u00e9 avant loadAll() (rituel anti-TDZ : loadAll avale ses exceptions, une\n   globale lue au chargement et d\u00e9clar\u00e9e trop tard repliquerait en silence sur l'exemple). */\nlet repriseVueId = null;   // dernier essai \"en cours\" propos\u00e9 par la ligne de reprise\nlet repriseMasquee = false; // l'utilisateur a ferm\u00e9 la proposition pour cet essai\nlet rechercheListe = [];   // r\u00e9sultats filtr\u00e9s de la palette de recherche (Ctrl+K)\nlet rechercheSel = 0;      // ligne s\u00e9lectionn\u00e9e au clavier dans la palette\nlet tendanceEnPct = false; // v4.15 : vue des tendances en % de tol\u00e9rance consomm\u00e9e\nlet compareCtx = null;     // v4.15 : { a: \"scId|essaiId\", b: \"scId|essaiId\" }\nlet clotureCtx = null;     // v4.25 : { scId, essaiId } \u2014 l'essai \u00e0 cl\u00f4turer/r\u00e9ouvrir\n/* v4.16 \u2014 D\u00c9CLAR\u00c9 ICI et pas dans le bloc cloud : la zone d'ajout de photos lit\n   cloudSession d\u00e8s le premier rendu, qui arrive AVANT le chargement du bloc cloud.\n   loadAll() avalant ses exceptions (pi\u00e8ge historique), une globale lue au rendu et\n   d\u00e9clar\u00e9e trop tard ferait repliquer le chargement sur l'exemple sans un mot. */\nlet cloudSession = null;   // {access_token, refresh_token, expires_at, email}\n// La composition du scenario est depliee par defaut : on memorise donc l'inverse, les\n// scenarios dont l'utilisateur a referme le tableau.\nlet configReplies = new Set();\n/* Fiches outil : repliees par defaut. L'apercu au-dessus donne la vue d'ensemble, la fiche\n   ne s'ouvre que quand on veut modifier \u2014 sinon quatre outils deplies noient l'ecran. */\nlet outilsOuverts = new Set();\n/* v4.28 \u2014 tuiles d'aper\u00e7u dont le d\u00e9tail de calcul du co\u00fbt annuel est d\u00e9pli\u00e9\n   (cl\u00e9 \"scId|logementId\" : survit aux re-rendus comme les fiches outil). */\nlet apDetailsOuverts = new Set();\n/* v4.29 \u2014 d\u00e9tail du co\u00fbt annuel G\u00c9N\u00c9RAL d\u00e9pli\u00e9 (pied du sc\u00e9nario affich\u00e9). */\nlet coutAnnuelDetailOuvert = false;\n/* v4.30 \u2014 contextes d'essai ouverts manuellement (cl\u00e9 \"scId|essaiId\") : le bloc \u00ab Contexte \u00bb\n   (but, observations, r\u00e9daction, programme) est ouvert tant qu'il est vide, repli\u00e9 d\u00e8s qu'il\n   est rempli \u2014 sauf si l'utilisateur l'a ouvert ou repli\u00e9 lui-m\u00eame. */\nlet essaiCtxOuverts = new Set();\n\nfunction normalizeBacklogItem(b){\n  // v4.21 \u2014 le pense-b\u00eate devient un carnet de sujets chauds partag\u00e9 : types \u00ab essai \u00e0\n  // planifier \u00bb et \u00ab sujet technique \u00bb, champ d\u00e9clencheur (\u00e0 saisir si arr\u00eat de ligne\u2026),\n  // et des statuts qui suivent la vie d'une opportunit\u00e9, pas seulement d'un bug.\n  return Object.assign({ id: b.id || (\"b\"+Math.random().toString(36).slice(2)), date:\"\", auteur:\"\", type:\"amelioration\", titre:\"\", description:\"\", statut:\"nouveau\", declencheur:\"\", image:\"\" }, b);\n}\nfunction normalizeOp(o){\n  /* v4.50 \u2014 opCode d\u00e9riv\u00e9 du nom (arbitrage spec crois\u00e9e Hermes/Z Code) : la carte atelier\n     regroupe les OP par code (\u00ab OP10 \u00bb, \u00ab OP 30 Per\u00e7ages \u00bb et \u00ab OP10 Ebauche \u00bb tombent dans\n     OP10). Sans code exploitable (nom \u00ab OP \u00bb seul), opCode vaut \u00ab ? \u00bb : la carte ne dessine\n     pas de tuile fant\u00f4me, l'OP reste atteignable en navigation experte. */\n  const mOpCode = String(o.nom || \"\").toUpperCase().match(/OP\\s?0*(\\d+)/);\n  return Object.assign({ id: o.id || (\"o\"+Math.random().toString(36).slice(2)), nom:\"\", ordre: 10, ficheOutil: null,\n    opCode: mOpCode ? \"OP\" + mOpCode[1] : \"?\" }, o, {\n    config: Object.assign({}, defaultConfig, o.config || {}),\n    scenarios: (o.scenarios || []).map(normalizeScenario)\n  });\n}\nfunction normalizeReference(r){\n  // reprend aussi bien le format actuel (r.ops) que l'ancien format (config/scenarios\n  // directement sur la reference, avant l'introduction du niveau OP) en l'enveloppant\n  // silencieusement dans une seule OP \"OP10\".\n  let ops;\n  if(Array.isArray(r.ops) && r.ops.length){\n    ops = r.ops.map(normalizeOp);\n  } else {\n    ops = [ normalizeOp({ id: \"o\"+Math.random().toString(36).slice(2), nom: \"OP10\", ordre: 10, config: r.config, scenarios: r.scenarios }) ];\n  }\n  ops.sort((a,b) => (a.ordre||0) - (b.ordre||0));\n  return { id: r.id || (\"r\"+Math.random().toString(36).slice(2)), nom: r.nom || \"\",\n           productionAnnuelle: r.productionAnnuelle ?? \"\",\n           cibleCPP: r.cibleCPP ?? \"\", // v4.46.1 \u2014 cible de co\u00fbt pi\u00e8ce du site (excel suivi consommations), lue par le tableau de bord\n           ops };\n}\n/* ============================================================================\n   PROJETS COMME ETIQUETTES, PAS COMME PROPRIETAIRES (v4.1)\n   ============================================================================\n   La v4.0 avait mis le projet AU-DESSUS de la machine : Projet -> Ligne -> Reference ->\n   OP -> Scenario. Deployee, elle a ete retiree en v3.19.2 le temps de trancher une question\n   de fond, posee par Benjamin et confirmee par la revue d'Hermes : une ligne de production\n   est un fait physique unique (une machine, un cout horaire, une reference disque). La\n   forcer a appartenir a UN SEUL projet, c'est confondre \"le projet possede la machine\" avec\n   \"le projet s'interesse a certains essais menes sur la machine\".\n\n   Le bon modele separe les deux :\n     - l'arbre physique (lignes -> references -> OP -> scenarios -> essais) reste RACINE,\n       unique, exactement comme avant la v4.0 -- c'est le \"monde\", il n'existe qu'une fois ;\n     - un PROJET est une liste d'etiquettes posees sur des scenarios existants (une\n       \"playlist\"), plus les quatre informations que la v4.0 avait raison d'inventer :\n       problematique, pilote, statut, echeance.\n\n   Ce que ce choix elimine, entierement :\n     - la gymnastique syncActiveProjet()/reassignation de `lignes` (disparue : `lignes` est\n       de nouveau LA racine, comme en v3) ;\n     - le risque de double comptage entre projets (un scenario \"en serie\" a une seule\n       adresse, pas une copie par projet) ;\n     - la duplication d'une ligne pour la suivre depuis deux projets -- elle est juste\n       etiquetee dans les deux ;\n     - la fusion complexe au niveau ligne/reference/OP pour les projets : fusionner des\n       etiquettes, c'est fusionner des listes d'identifiants, pas des sous-arbres.\n   Ce que ce choix coute, assume :\n     - une etiquette peut pointer vers un scenario supprime entre-temps -> purgerTagsMorts()\n       nettoie a chaque chargement, silencieusement (une etiquette morte n'est pas une\n       perte de donnees, juste une entree de playlist a oublier) ;\n     - la navigation (bandeaux ligne/reference/OP) reste VOLONTAIREMENT non filtree par\n       projet dans cette version : on voit toutes les lignes existantes, quel que soit le\n       projet ouvert. Le cloisonnement porte sur la lecture (tableau de bord, cartes de\n       projet), pas sur la vue d'ensemble de l'atelier -- Matis n'a jamais demande a ne plus\n       voir Step 3 exister, il a demande a ne pas melanger les essais dans SA synthese.\n\n   Format de fichier : 7. Un fichier format 7 a `lignes` a la racine, EXACTEMENT comme le\n   format 5 -- une version anterieure a la v4 (3.19.x et avant) l'ouvre donc correctement et\n   affiche toutes les mesures ; seul le regroupement en projets lui est invisible. C'est la\n   difference majeure avec le format 6 de la v4.0, qui rendait l'arbre illisible aux anciennes\n   versions (incident reproduit et documente en v3.19.2). */\n\nfunction normalizeTag(t){\n  return { ligneId: t.ligneId || \"\", referenceId: t.referenceId || \"\", opId: t.opId || \"\", scenarioId: t.scenarioId || \"\" };\n}\nconst PROJET_STATUTS = { encours:\"En cours\", pause:\"En pause\", termine:\"Termin\u00e9\", abandonne:\"Abandonn\u00e9\" };\nfunction normalizeProjet(p){\n  return Object.assign({\n    id: p.id || (\"pj\"+Math.random().toString(36).slice(2)),\n    // \"problematique\" reste le nom de champ en interne (aucune donnee a migrer) : seule\n    // l'etiquette visible change (\"Description\", v4.2) et la saisie passe en zone de texte.\n    nom: \"\", problematique: \"\", responsable: \"\", responsableId: \"\", statut: \"encours\",\n    dateCible: \"\", creePar: \"\", creeLe: \"\",\n    // ligne sur laquelle le projet a ete cree (v4.3) : sert UNIQUEMENT de repli d'affichage\n    // tant qu'aucune etiquette n'existe encore (voir projetVisibleSurLigne). Des qu'une\n    // etiquette est posee, ce champ n'a plus d'effet -- ce ne sont plus les etiquettes qui\n    // decident, jamais ce champ.\n    ligneCreation: \"\",\n    // identite visuelle du projet (v4.2) : assignee une fois, a la creation, jamais\n    // recalculee au rendu -- sinon les couleurs \"sauteraient\" d'une session a l'autre des\n    // qu'un projet est supprime et decale les index des autres.\n    couleur: \"\"\n  }, p, {\n    tags: (p.tags || []).map(normalizeTag)\n  });\n}\n\n/* Responsables (v4.2) : personne + couleur, geres depuis Options. Independants des projets :\n   supprimer un responsable ne supprime aucun projet, il repasse juste a \"aucun responsable\". */\nfunction normalizeResponsable(r){\n  return Object.assign({ id: r.id || (\"resp\"+Math.random().toString(36).slice(2)), nom:\"\", couleur:\"\" }, r);\n}\n/* Couleur suivante de la palette, jamais deja utilisee par un responsable existant tant\n   qu'il en reste une de libre -- au-dela de 8 responsables, le cycle recommence (une\n   redite est preferable a l'absence de couleur). */\nfunction prochaineCouleurLibre(dejaUtilisees){\n  const libre = OUTIL_COLORS.find(c => !dejaUtilisees.includes(c));\n  return libre || OUTIL_COLORS[dejaUtilisees.length % OUTIL_COLORS.length];\n}\nfunction couleurProjet(pj){\n  return pj.couleur || \"var(--ink-faint)\";\n}\nfunction responsableDe(pj){\n  return responsables.find(r => r.id === pj.responsableId) || null;\n}\n\n/* Resout une etiquette contre l'arbre physique COURANT (`lignes`). Renvoie null si un\n   maillon a disparu (ligne/reference/OP/scenario supprime) : c'est le seul etat d'erreur\n   a prevoir, et il ne doit jamais lever d'exception -- une etiquette morte est un evenement\n   normal (quelqu'un a nettoye un vieux scenario), pas un incident. */\nfunction resoudreTag(tag){\n  const l = lignes.find(x => x.id === tag.ligneId); if(!l) return null;\n  const r = l.references.find(x => x.id === tag.referenceId); if(!r) return null;\n  const op = r.ops.find(x => x.id === tag.opId); if(!op) return null;\n  const sc = (op.scenarios || []).find(x => x.id === tag.scenarioId); if(!sc) return null;\n  return { ligne:l, reference:r, op, scenario:sc };\n}\nfunction scenariosResolusDuProjet(pj){\n  return pj.tags.map(resoudreTag).filter(Boolean);\n}\n/* nettoyage silencieux, appele au chargement : purge les etiquettes qui ne pointent plus\n   vers rien. Ne modifie jamais l'arbre physique, seulement les listes du projet. */\nfunction purgerTagsMorts(pj){\n  const avant = pj.tags.length;\n  pj.tags = pj.tags.filter(t => resoudreTag(t));\n  return avant - pj.tags.length;\n}\nfunction projetContientScenario(pj, ligneId, referenceId, opId, scenarioId){\n  return pj.tags.some(t => t.ligneId===ligneId && t.referenceId===referenceId && t.opId===opId && t.scenarioId===scenarioId);\n}\n/* v4.29 \u2014 les lignes que couvre un projet, d\u00e9doublonn\u00e9es. Un projet EST une playlist qui\n   peut l\u00e9gitimement traverser les lignes (une plaquette test\u00e9e sur deux machines) ; mais\n   un projet \u00ab co\u00fbt EMAG 1 \u00bb qui se retrouve avec un sc\u00e9nario de HESSAPP est presque\n   toujours un \u00e9tiquetage accidentel \u2014 d'o\u00f9 l'avertissement au clic et l'info-bulle. */\n/* v4.55.1 \u2014 la REGLE du rattachement, extraite en fonction pure pour etre testee.\n   Elle ne dit pas \u00ab quel projet a tel nom \u00bb (un nom est du texte libre) mais\n   \u00ab ce projet, dans les faits, accepte-t-il cette ligne ? \u00bb. Trois issues :\n     - \"ok\"        : la ligne fait deja partie du projet, ou le projet contient des\n                     scenarios de plusieurs lignes (donc il est volontairement ouvert) ;\n     - \"premier\"   : le projet est vide -- ce serait son premier scenario ;\n     - \"refuse\"    : le projet est mono-ligne et ce n'est pas la ligne courante. */\nfunction projetAccepteLigne(pj, nomLigneCourante, ligneCourante){\n  const ses = lignesDuProjet(pj);\n  if(!ligneCourante) return \"ok\";\n  if(ses.includes(ligneCourante.nom)) return \"ok\";\n  if(!ses.length) return \"premier\";\n  return \"refuse\";\n}\n\nfunction lignesDuProjet(pj){\n  const noms = new Set();\n  (pj.tags || []).forEach(t => {\n    const r = resoudreTag(t);\n    if(r) noms.add(r.ligne.nom || \"Sans nom\");\n  });\n  return [...noms].sort((a,b) => a.localeCompare(b, \"fr\"));\n}\nfunction toggleTagScenario(pj, ligneId, referenceId, opId, scenarioId){\n  const i = pj.tags.findIndex(t => t.ligneId===ligneId && t.referenceId===referenceId && t.opId===opId && t.scenarioId===scenarioId);\n  if(i === -1) pj.tags.push({ ligneId, referenceId, opId, scenarioId });\n  else pj.tags.splice(i, 1);\n}\n\n/* ---- garde-fous homonymes (v4.5) -----------------------------------------------------\n   Dans le modele v4.4 (projets = etiquettes posees sur des scenarios qui vivent dans les\n   lignes), le piege du double comptage se joue au niveau du SCENARIO EN SERIE : deux projets\n   etiquettent chacun un scenario different qui decrit le MEME changement physique sur la\n   MEME machine (meme nom de scenario, meme ligne), le tableau de bord \"tous projets\"\n   additionne alors deux fois le meme gain annuel. On ne peut pas interdire (deux campagnes\n   homonymes sur deux machines differentes existent), mais on signale la ou la decision se\n   prend : passage en serie, et vue globale du tableau de bord. */\nfunction scenariosSerieHomonymes(){\n  // tous les scenarios \"en serie\", regroupes par (nom nettoye + nom de ligne nettoye) :\n  // meme nom de scenario sur la meme ligne = tres probablement le meme fait physique.\n  // Dedoublonne par scenario.id : le MEME scenario etiquete dans deux projets est un seul\n  // objet (le dashboard le compte via statsProjet de chaque projet, mais c'est le meme\n  // fait physique declare deux fois, pas deux optimisations divergentes a reconcilier) \u2014\n  // l'alerte ne vise que des scenarios DISTINCTS du meme nom, la ou deux descriptions du\n  // meme changement peuvent diverger en silence.\n  const groupes = new Map();\n  projets.forEach(pj => {\n    scenariosResolusDuProjet(pj).forEach(({ ligne, reference, op, scenario: sc }) => {\n      if(sc.statut !== \"serie\") return;\n      if(!(sc.name || \"\").trim()) return;\n      const cle = (sc.name || \"\").trim().toLowerCase() + \"@\" + (ligne.nom || \"\").trim().toLowerCase();\n      if(!groupes.has(cle)) groupes.set(cle, { nom: sc.name, ligne: ligne.nom || \"?\", ids: new Set(), projets: new Set() });\n      const g = groupes.get(cle);\n      g.ids.add(sc.id);\n      g.projets.add(pj.nom || \"Projet\");\n    });\n  });\n  return [...groupes.values()].filter(g => g.ids.size > 1)\n    .map(g => ({ nom: g.nom, ligne: g.ligne, projets: [...g.projets] }));\n}\nfunction avertissementSerieHomonymes(sc){\n  // le scenario sc (sur le point de passer \"en serie\" dans l'OP actif) porte-t-il le meme\n  // nom qu'un scenario deja en serie sur la meme ligne, dans un AUTRE projet ?\n  const ligne = getActiveLigne();\n  const nom = (sc.name || \"\").trim().toLowerCase();\n  if(!nom || !ligne) return [];\n  const res = [];\n  projets.forEach(pj => {\n    scenariosResolusDuProjet(pj).forEach(({ ligne: l2, scenario: s2 }) => {\n      if(s2 === sc || s2.statut !== \"serie\") return;\n      if((s2.name || \"\").trim().toLowerCase() === nom && (l2.nom || \"\").trim().toLowerCase() === (ligne.nom || \"\").trim().toLowerCase()){\n        res.push((pj.nom || \"Projet\") + \" \u203a \" + (l2.nom || \"?\") + \" \u203a \" + (s2.name || \"?\"));\n      }\n    });\n  });\n  return res;\n}\n\n/* Lecture unifiee d'un arbre, quel que soit le format qui l'a produit. Un seul point\n   d'entree utilise partout : chargement, historique, points de reprise, import. */\n/* Etape commune aux formats lus par migrerArbre (v4.2) : assigne une couleur stable a tout\n   projet qui n'en a pas encore (creation ou fichier anterieur a la v4.2), et lie chaque\n   projet a un responsable de la liste geree. Un ancien projet qui n'avait qu'un champ texte\n   libre \"responsable\" (v4.0/4.1) voit ce texte devenir une entree de la liste geree, avec\n   une couleur assignee automatiquement -- aucune saisie n'est perdue ni a ressaisir. */\nfunction finaliserProjetsEtResponsables(projetsBruts, responsablesSource){\n  const responsablesRes = Array.isArray(responsablesSource) && responsablesSource.length\n    ? responsablesSource.map(normalizeResponsable) : [];\n  const trouverOuCreerResponsable = (nomLibre) => {\n    const nom = (nomLibre || \"\").trim();\n    if(!nom) return \"\";\n    let r = responsablesRes.find(x => x.nom === nom);\n    if(!r){\n      r = normalizeResponsable({ nom, couleur: prochaineCouleurLibre(responsablesRes.map(x => x.couleur)) });\n      responsablesRes.push(r);\n    }\n    return r.id;\n  };\n  const projetsRes = projetsBruts.map((pj, i) => {\n    if(!pj.couleur) pj.couleur = OUTIL_COLORS[i % OUTIL_COLORS.length];\n    if(!pj.responsableId && pj.responsable) pj.responsableId = trouverOuCreerResponsable(pj.responsable);\n    return pj;\n  });\n  return { projets: projetsRes, responsables: responsablesRes };\n}\n\nfunction migrerArbre(source){\n  if(!source) return null;\n\n  // format 5 (pre-v4, sans projets) OU format 7/8 (v4.1+, lignes racine + projets-etiquettes) :\n  // les deux ont `lignes` a la racine -- c'est precisement ce qui rend ces formats\n  // retro-lisibles par les versions anterieures a la v4.\n  if(Array.isArray(source.lignes) && source.lignes.length){\n    const lignesLues = source.lignes.map(normalizeLigne);\n    let projetsLus = [];\n    if(Array.isArray(source.projets) && source.projets.length && Array.isArray(source.projets[0].tags)){\n      projetsLus = source.projets.map(normalizeProjet);\n    }\n    const fin = finaliserProjetsEtResponsables(projetsLus, source.responsables);\n    return { lignes: lignesLues, projets: fin.projets, responsables: fin.responsables, livraisons: Array.isArray(source.livraisons) ? source.livraisons.map(normalizeLivraison) : [] };\n  }\n\n  // format 6 (v4.0, projets PROPRIETAIRES des lignes -- deployee moins d'une journee) :\n  // on aplatit les lignes dans l'arbre unique ET on reconstruit un projet-etiquettes par\n  // ancien projet, en pointant ses etiquettes sur les scenarios desormais dans l'arbre\n  // commun. Rien n'est perdu : ni les mesures, ni le regroupement, ni la problematique/\n  // le pilote/le statut/l'echeance que l'utilisateur avait deja saisis.\n  if(Array.isArray(source.projets) && source.projets.length && Array.isArray(source.projets[0].lignes)){\n    const lignesPlates = [];\n    const projetsRecrees = source.projets.map(pjBrut => {\n      const tags = [];\n      (pjBrut.lignes || []).forEach(lBrut => {\n        const l = normalizeLigne(lBrut);\n        lignesPlates.push(l);\n        l.references.forEach(r => r.ops.forEach(op => (op.scenarios || []).forEach(sc => {\n          tags.push({ ligneId:l.id, referenceId:r.id, opId:op.id, scenarioId:sc.id });\n        })));\n      });\n      return normalizeProjet({\n        id: pjBrut.id, nom: pjBrut.nom, problematique: pjBrut.problematique,\n        responsable: pjBrut.responsable, statut: pjBrut.statut, dateCible: pjBrut.dateCible,\n        creePar: pjBrut.creePar, creeLe: pjBrut.creeLe, tags\n      });\n    });\n    const fin = finaliserProjetsEtResponsables(projetsRecrees, source.responsables);\n    return { lignes: lignesPlates, projets: fin.projets, responsables: fin.responsables, livraisons: [] };\n  }\n\n  return null;\n}\n\nfunction normalizeLigne(l){\n  return Object.assign({ id: l.id || (\"l\"+Math.random().toString(36).slice(2)), nom:\"\", coutHoraire:\"\", observations:\"\", maintenanceDate:\"\", maintenanceType:\"\" }, l, {\n    references: (l.references || []).map(normalizeReference)\n  });\n}\n/* v4.53 \u2014 une livraison est un INSTANTAN\u00c9 FIG\u00c9 : ses chiffres ne se recalculent jamais.\n   normalizeLivraison ne fait qu'assurer la forme (l'exactitude est fig\u00e9e \u00e0 la cr\u00e9ation). */\nfunction normalizeLivraison(l){\n  return Object.assign({\n    id: l.id || (\"lv\" + Math.random().toString(36).slice(2)),\n    nom: l.nom || \"Livraison\",\n    date: l.date || \"\",\n    creePar: l.creePar || \"\",\n    gainsActes: l.gainsActes ?? null,\n    gainsEnCours: l.gainsEnCours ?? null,\n    plan: Array.isArray(l.plan) ? l.plan : [],\n    cibles: Array.isArray(l.cibles) ? l.cibles : [],\n    essais: Array.isArray(l.essais) ? l.essais : [],\n    protocole: l.protocole || \"Tout essai concluant est r\u00e9p\u00e9t\u00e9 5\u00d7 ; valid\u00e9 5\u00d7 et viable \u00e9conomiquement, il passe en production.\"\n  }, l);\n}\nfunction getActiveLigne(){ return lignes.find(l => l.id === activeLigneId) || lignes[0]; }\nfunction getActiveReference(){\n  const l = getActiveLigne();\n  if(!l) return null;\n  return l.references.find(r => r.id === activeReferenceId) || l.references[0];\n}\nfunction getActiveOp(){\n  const r = getActiveReference();\n  if(!r) return null;\n  return r.ops.find(o => o.id === activeOpId) || r.ops[0];\n}\n/* data/config peuvent avoir ete reassignes en bloc (reset/import/restaurer) : on les\n   recopie alors dans l'OP active pour que l'arbre reste coherent. */\n/* v4.76.0 \u2014 Benjamin, 01/10 : le contexte EMAG 3 affichait un scenario\n   situe sur EMAG 1 (topo Z Code, \u00a71.3). Les chemins d'ecriture de `activeId`\n   sont sains : render() garde-fou, et switchOp()/allerVers() ferment le\n   contexte avant de poser. Le TROU est ailleurs, et il est grave :\n\n   `data` est un tableau SEPARE de l'OP active, et syncActiveOp() y ecrivait\n   `op.scenarios = data` SANS verifier d'ou venait `data`. Or syncActiveOp()\n   est appele par saveData(), backupSnapshot(), exportData() et\n   cloudEcrireEtat() \u2014 c'est-a-dire par TOUS les chemins de persistance.\n\n   Une divergence ne produisait donc pas qu'un mauvais affichage : elle\n   REECRIVAIT les scenarios d'une operation avec ceux d'une autre. Perte de\n   donnee silencieuse, et la sauvegarde l'emportait.\n\n   On ne peut pas interdire : pendant une restauration, ou un test, `data` est\n   legitimement un tampon. On DETECTE donc, et la regle est precise : un\n   scenario de `data` qui se trouve ailleurs dans l'arbre appartient a une\n   AUTRE operation. C'est une fuite, pas un tampon. */\nfunction signalerContextePerime(op){\n  try{\n    const t = (nom, x) => document.querySelector(\"#\" + nom + \" .panel-hint\");\n    const el = t(\"matisPanel\") || t(\"accueilPanel\");\n    if(el) el.insertAdjacentHTML(\"afterbegin\",\n      '<p class=\"panel-hint\">Contexte recale : le scenario affiche ne venait pas de cette '\n      + 'operation. Aucune donnee n\\'a ete ecrasee. Si tu vois ceci, note ce que tu faisais '\n      + ' juste avant et signale-le a Benjamin.</p>');\n  }catch(e){}\n}\nfunction syncActiveOp(){\n  const op = getActiveOp();\n  if(!op) return;\n  if(op.scenarios !== data && Array.isArray(data) && data.length){\n    const etranger = data.some(sc => {\n      if(!sc) return false;\n      for(const lg of (lignes || [])){\n        for(const rf of ((lg && lg.references) || [])){\n          for(const o of ((rf && rf.ops) || [])){\n            if(o === op) continue;                  // l'OP active : ce n'est pas une fuite\n            if((o.scenarios || []).some(x => x && x.id === sc.id)) return true;\n          }\n        }\n      }\n      return false;\n    });\n    if(etranger){\n      /* la hierarchie fait foi : on relit la VRAIE liste de l'OP active, plutot\n         que d'ecrire le tampon par-dessus. Et on le dit \u2014 parce qu'un silence\n         ici a deja coute une scene. */\n      data = op.scenarios || [];\n      signalerContextePerime(op);\n    }\n  }\n  op.scenarios = data;\n  op.config = config;\n}\nfunction switchOp(ligneId, refId, opId){\n  syncActiveOp();\n  // le \"voir tous les projets\" du bandeau est une echappatoire ponctuelle, pas un reglage :\n  // en changeant de ligne on repart filtre, sinon le mode \"tous\" resterait colle indefiniment\n  if(ligneId !== activeLigneId) bandeauProjetsTousAffiches = false;\n  activeLigneId = ligneId;\n  activeReferenceId = refId;\n  activeOpId = opId;\n  const op = getActiveOp();\n  data = op ? op.scenarios : [];\n  config = op ? op.config : Object.assign({}, defaultConfig);\n  activeId = data[0] ? data[0].id : null;\n  saveData();\n  render();\n}\nfunction switchReference(ligneId, refId){\n  const l = lignes.find(x => x.id === ligneId);\n  const r = l ? (l.references.find(x => x.id === refId) || l.references[0]) : null;\n  switchOp(ligneId, r ? r.id : refId, r && r.ops[0] ? r.ops[0].id : null);\n}\n\n/* v4.9 \u2014 specs usine : battement max et variation d'\u00e9paisseur (VE) max mesur\u00e9es Marposs\n   sur les disques FINIS (apr\u00e8s OP40, finition). Valeurs de r\u00e9f\u00e9rence pour TOUTE l'usine,\n   affich\u00e9es dans l'outil et les rapports ; elles ne changent normalement jamais \u2014 leur\n   modification dans Options exige une double validation. La tol\u00e9rance d'un essai en OP10\n   peut \u00eatre bien plus l\u00e2che : ce sont deux choses distinctes. Voyage dans le suivi\n   (synchronis\u00e9 chez Matis via le cloud, repris par export/import).\n   D\u00c9CLAR\u00c9 AVANT loadAll() : loadAll \u00e9crit cette variable et son appel est silencieusement\n   prot\u00e9g\u00e9 par un try/catch \u2014 une d\u00e9claration apr\u00e8s coup (TDZ) ferait repliquer tout le\n   chargement sur les donn\u00e9es d'exemple sans le moindre message. */\nlet specsUsine = { battement: 0.04, ve: 0.01 };\nfunction normaliserSpecsUsine(s){\n  s = s || {};\n  const nb = parseFloat(s.battement), nv = parseFloat(s.ve);\n  return { battement: isNaN(nb) ? 0.04 : nb, ve: isNaN(nv) ? 0.01 : nv };\n}\n/* v4.10 \u2014 note de synchro : le bilan de la derni\u00e8re fusion/d\u00e9p\u00f4t, embarqu\u00e9 dans le suivi.\n   L'autre poste le lit \u00e0 sa prochaine ouverture (\u00ab Matis a fusionn\u00e9 : 3 essais ajout\u00e9s... \u00bb).\n   M\u00eame r\u00e8gle que specsUsine : d\u00e9clar\u00e9 AVANT loadAll(), qui est prot\u00e9g\u00e9 par un try/catch\n   silencieux (voir le commentaire de specsUsine). */\nlet synchroNote = null;\n/* v4.53 \u2014 les LIVRAISONS : l'objet que la hi\u00e9rarchie lit (d\u00e9cision 3 de la constitution).\n   Une livraison = un instantan\u00e9 FIG\u00c9 et DAT\u00c9 des gains du plan (act\u00e9s, en cours, plan\n   poste par poste, cibles). Elle ne bouge plus : les chiffres vivent dans l'objet, pas\n   dans les sc\u00e9narios. D\u00e9clar\u00e9e AVANT loadAll() (rituel anti-TDZ). */\nlet livraisons = [];\nloadAll();\nrecomputeCycles();\n\nfunction normalizeLogement(l){\n  return Object.assign({ id: l.id || (\"g\"+Math.random().toString(36).slice(2)), nom:\"\", ref:\"\", codeArticle:\"\",\n    // v4.72.0 \u2014 le MABEC est la CLE de raccordement avec le classeur de Matis :\n    // \u00ab un MABEC = un article = un logement \u00bb. Le lecteur de classeur le remontait\n    // d\u00e9j\u00e0, mais le mod\u00e8le n'avait nulle part o\u00f9 le poser : l'information \u00e9tait lue puis perdue.\n    // Un MABEC n'est PAS l'identifiant de l'outil \u2014 plusieurs MABEC sur un m\u00eame\n    // porte-outil est NORMAL (un par logement). Il est ici, sur le logement, o\u00f9 il doit \u00eatre.\n    mabec:\"\",\n    prix:\"\", aretes:8, charniere:\"\", vc:\"\", f:\"\", kappaR:\"\", rayonBec:\"\", apPiste:\"\",\n    tempsCoupe:\"\", tempsDeplacement:\"\", // mesures machine (s), module \"detail du cycle par logement\"\n    suiviTolerance:true }, l); // la charniere se suit toujours ; la tolerance est desactivable par logement\n}\n/* retrouve un logement par son id, quel que soit l'outil qui le porte */\nfunction logementParId(sc, logementId){\n  if(!logementId) return null;\n  for(const o of sc.outils){\n    const l = o.logements.find(x => x.id === logementId);\n    if(l) return l;\n  }\n  return null;\n}\n/* ce logement doit-il valider la tolerance (pas seulement la charniere) ? recherche\n   volontairement dans l'etat ACTUEL du scenario (pas fige a l'essai) : c'est un choix de\n   methode de validation, pas une condition de coupe \u2014 il peut se corriger retroactivement. */\nfunction toleranceRequisePour(sc, row){\n  const l = logementParId(sc, row.logementId);\n  return !l || l.suiviTolerance !== false;\n}\n/* piece detachee d'un porte-outil (cale, vis, corps, bride...) : meme logique\n   d'amortissement qu'une plaquette, mais sur sa propre charniere de remplacement */\nfunction normalizePieceDetachee(p){\n  return Object.assign({ id: p.id || (\"pd\"+Math.random().toString(36).slice(2)),\n    nom:\"\", ref:\"\", prix:\"\", charniere:\"\" }, p);\n}\nfunction normalizeOutil(o){\n  // plan : PDF ou image du montage/trajectoire de CET outil (v3.18). Distinct de la fiche\n  // outil de l'OP, qui couvre toute l'operation.\n  return Object.assign({ id: o.id || (\"t\"+Math.random().toString(36).slice(2)), numero:\"\", correcteur:\"\", description:\"\", plan:null }, o, {\n    logements: (o.logements || []).map(normalizeLogement),\n    pieces: (o.pieces || []).map(normalizePieceDetachee)\n  });\n}\n/* instantane des conditions de coupe de tous les logements, au moment de l'essai :\n   un ajustement ulterieur du scenario ne doit pas reecrire l'histoire des essais passes */\nfunction snapshotLogements(sc){\n  return sc.outils.flatMap(o => o.logements.map(l => ({\n    outilId: o.id, logementId: l.id, outilNumero: o.numero, logementNom: l.nom,\n    vc: l.vc, f: l.f, charniere: l.charniere, ref: l.ref, prix: l.prix\n  })));\n}\n/* v4.11 \u2014 logements r\u00e9ellement suivis par un essai : la s\u00e9lection se coche par essai\n   (\u2715 sur la puce / \u00ab + suivre un logement \u00bb). Un logement exclu (suivi:false) garde son\n   instantan\u00e9 en m\u00e9moire mais ne g\u00e9n\u00e8re plus colonne, progression ni rapport. Pas de\n   marque = suivi (compatibilit\u00e9 totale avec les essais d'avant la v4.11). */\nfunction logementsSuivis(es){\n  return ((es.params && es.params.logements) || []).filter(lp => lp.suivi !== false);\n}\n/* v4.22 \u2014 nom d'un logement d'essai : le nom ACTUEL du sc\u00e9nario, pas le nom fig\u00e9.\n   L'instantan\u00e9 d'un essai (params.logements) g\u00e8le les conditions de coupe \u00e0 sa cr\u00e9ation\n   \u2014 c'est son r\u00f4le. Mais il gelait aussi les NOMS : renommer un outil ou un logement\n   ne se voyait nulle part (graphe des pr\u00e9l\u00e8vements, puces d'essai, rapport) tant qu'un\n   nouvel essai n'\u00e9tait pas cr\u00e9\u00e9 \u2014 \u00ab le nom initial reste en m\u00e9moire \u00bb. Les noms, eux,\n   d\u00e9crivent la m\u00eame position physique : on les relit dans le sc\u00e9nario au moment de\n   l'affichage, via logementId. Si le logement a \u00e9t\u00e9 retir\u00e9 entre-temps, on retombe sur\n   le nom fig\u00e9 \u2014 seule trace historique restante. */\nfunction nomLogementActuel(sc, lp){\n  const o = sc.outils.find(x => x.id === lp.outilId);\n  const l = o && o.logements.find(x => x.id === lp.logementId);\n  return {\n    outilNumero: l ? (o.numero || \"\u2014\") : (lp.outilNumero || \"?\"),\n    logementNom: l ? (l.nom || \"\u2014\") : (lp.logementNom || \"?\")\n  };\n}\n/* reference plaquette au moment de l'essai. Les essais crees avant l'ajout de \"ref\" au\n   snapshot n'ont pas cette valeur figee : on retombe alors sur la reference actuelle du\n   scenario pour ce logement (meilleur effort, mais peut differer si elle a change depuis). */\nfunction refLogementEssai(sc, lp){\n  if(lp.ref) return lp.ref;\n  const o = sc.outils.find(x => x.id === lp.outilId);\n  const l = o && o.logements.find(x => x.id === lp.logementId);\n  return l ? l.ref : \"\";\n}\nfunction normalizeScenario(sc){\n  // statut de vie : le scenario de reference est par definition ce qui tourne en serie,\n  // les autres sont en essai tant qu'on n'a pas tranche\n  const merged = Object.assign({ emag1:false, limitOverride:false, limitLabel:\"Battement (mm)\", limitValue:0.12, validationThreshold:5,\n    battActif:true, battCotes:\"\", criteresSup:[], marpossRapport:false, tendanceRapport:false,\n    critere2Actif:false, limitLabel2:\"Ra (\u00b5m)\", limitValue2:0.8, tauxRebutAnnuel:\"\",\n    logementsParalleles:false, // v4.39 (obsol\u00e8te) : conserv\u00e9 pour les donn\u00e9es interm\u00e9diaires\n    outilsParalleles:false, // v4.40 (obsol\u00e8te, remplac\u00e9 par les cases par outil v4.41)\n    statut: sc.baseline ? \"serie\" : \"essai\", statutMotif:\"\", statutDate:\"\", essais:[], scrapLog:[] }, sc);\n  // v4.4 : le scenario en production (\u2605) EST le scenario \"en serie\" -- un seul concept,\n  // pas deux qui pourraient diverger. Corrige silencieusement toute donnee anterieure ou\n  // saisie hors interface (import, edition manuelle du JSON) qui aurait laisse les deux\n  // decorreles ; l'interface, elle, empeche desormais cette divergence a la source\n  // (voir promouvoirEnProduction / appliquerChangementStatut).\n  if(merged.baseline) merged.statut = \"serie\";\n\n  if(Array.isArray(sc.outils)){\n    merged.outils = sc.outils.map(normalizeOutil);\n    /* v4.41 \u2014 migration du mode global 4.39/4.40 : tous les outils sauf le premier\n       deviennent \u00ab simultan\u00e9 avec le pr\u00e9c\u00e9dent \u00bb (un seul groupe = m\u00eame r\u00e9sultat). */\n    if(merged.outilsParalleles) merged.outils.forEach((o,i) => { if(i > 0) o.simultaneAvecPrecedent = true; });\n  } else {\n    // ancien format bol/piste -> migration en outils/logements. Meme N\u00b0 outil des\n    // deux cotes = un seul outil a 2 logements ; sinon, deux outils distincts.\n    const bol = sc.bol || {}, piste = sc.piste || {};\n    const memeOutil = bol.outil && piste.outil && bol.outil === piste.outil;\n    merged.outils = [];\n    if(memeOutil){\n      merged.outils.push(normalizeOutil({ numero: bol.outil, logements: [\n        normalizeLogement(Object.assign({ nom:\"Bol\" }, bol)),\n        normalizeLogement(Object.assign({ nom:\"Piste\" }, piste))\n      ] }));\n    } else {\n      if(bol.outil || bol.ref || bol.prix) merged.outils.push(normalizeOutil({ numero: bol.outil||\"\", logements:[ normalizeLogement(Object.assign({nom:\"Bol\"}, bol)) ] }));\n      if(piste.outil || piste.ref || piste.prix) merged.outils.push(normalizeOutil({ numero: piste.outil||\"\", logements:[ normalizeLogement(Object.assign({nom:\"Piste\"}, piste)) ] }));\n    }\n  }\n  delete merged.bol; delete merged.piste;\n\n  merged.essais = (sc.essais || []).map(e => {\n    let params = e.params || {};\n    if(!Array.isArray(params.logements)){\n      // ancien format essai.params={vc,f,charniere} fige sur \"piste\" -> on retrouve le\n      // logement nomme Piste pour batir un instantane compatible (comportement identique\n      // a avant : seule la charniere piste comptait pour la conformite de l'essai)\n      const tousLogements = merged.outils.flatMap(o => o.logements.map(l => ({o,l})));\n      const pisteLog = tousLogements.find(x => (x.l.nom||\"\").toLowerCase() === \"piste\");\n      params = { logements: pisteLog ? [{\n        outilId: pisteLog.o.id, logementId: pisteLog.l.id, outilNumero: pisteLog.o.numero, logementNom: pisteLog.l.nom,\n        vc: params.vc, f: params.f, charniere: params.charniere\n      }] : [] };\n    }\n    const marposs = Object.assign({ debut:\"\", fin:\"\", releves:[] }, e.marposs || {});\n    // v4.12 \u2014 extractions multiples : un essai men\u00e9 sur plusieurs jours colle une\n    // extraction Marposs par jour, chacune avec ses heures et son graphe. Migration\n    // silencieuse : l'ancien marposs unique devient la premi\u00e8re extraction. Aucun\n    // changement de format \u2014 un ancien fichier relit ce suivi sans rien voir.\n    let marpossListe = Array.isArray(e.marpossListe) && e.marpossListe.length\n      ? e.marpossListe.map(x => Object.assign({ id: x.id || (\"mj\"+Math.random().toString(36).slice(2)), jour:\"\", debut:\"\", fin:\"\", releves:[] }, x))\n      : null;\n    if(!marpossListe && ((marposs.releves || []).length || marposs.debut || marposs.fin)){\n      marpossListe = [{ id:\"mj1\", jour:\"\", debut: marposs.debut || \"\", fin: marposs.fin || \"\", releves: marposs.releves || [] }];\n    }\n    const photos = (e.photos || []).map(p => Object.assign(\n      { id: p.id || (\"ph\"+Math.random().toString(36).slice(2)), filename:\"\", addedAt:\"\", legende:\"\", crop:null, annotations:[] }, p));\n    return Object.assign(\n      { id: e.id || (\"e\"+Math.random().toString(36).slice(2)), titre:\"\", date:\"\", equipe:\"\", operateur:\"\", observations:\"\", maturiteBruts:\"\", prelevements:[],\n        // tracabilite terrain (v3.11) : sans ces defauts, un essai charge depuis un JSON\n        // anterieur a cette version porte des champs undefined plutot que des chaines vides\n        redigePar:\"\", dateFin:\"\", heureDebut:\"\", heureFin:\"\", programme:\"\", programmeGauche:\"\", programmeDroit:\"\",\n        // horodatage de derniere modification (v3.16) : c'est lui qui arbitre la fusion de\n        // deux fichiers. Vide sur un essai issu d'un JSON anterieur \u2014 la fusion traite alors\n        // le cas en conflit plutot que de deviner.\n        modifieLe:\"\" },\n      e,\n      { params, marposs, marpossListe: marpossListe || [{ id:\"mj1\", jour:\"\", debut:\"\", fin:\"\", releves:[] }],\n        marpossRapport: !!(e.marpossRapport || marposs.marpossRapport),\n        photos, prelevements: (e.prelevements || []).map(r => {\n        const row = Object.assign({ id: r.id || (\"p\"+Math.random().toString(36).slice(2)), piece:\"\", batt:\"\", battD:\"\", battG:\"\", logementId:\"\", pointMesure:\"\", usure:\"\", valeur2:\"\" }, r);\n        // anciennes saisies (avant le split Droite/Gauche d'EMAG 1) : la mesure vivait\n        // seule dans \"batt\". Si le scenario est en mode EMAG 1, on la reporte sur les deux\n        // cotes pour ne pas la faire disparaitre silencieusement de l'affichage.\n        if(merged.emag1 && row.batt !== \"\" && row.batt != null && row.battD === \"\" && row.battG === \"\"){\n          row.battD = row.batt; row.battG = row.batt;\n        }\n        // v4.9 : report de l'ancienne valeur du 2e critere (critere2Actif) vers la\n        // structure generique des criteres supplementaires \u2014 elle redevient visible\n        // dans le tableau, l'atelier, le CSV et les rapports sans migration de format.\n        if(row.valeur2 !== \"\" && row.valeur2 != null && row.valeur2 !== undefined){\n          if(!row.valeurs || !row.valeurs[\"cs1\"]) {\n            row.valeurs = row.valeurs || {};\n            row.valeurs[\"cs1\"] = Object.assign({ v: row.valeur2 }, row.valeurs ? row.valeurs[\"cs1\"] : {});\n          }\n        }\n        return row;\n      }) }\n    );\n  });\n  merged.scrapLog = (sc.scrapLog || []).map(r => Object.assign({ id: r.id || (\"r\"+Math.random().toString(36).slice(2)), date:\"\", equipe:\"\", produites:\"\", rebutees:\"\" }, r));\n  // v4.9 \u2014 criteres supplementaires generiques (Ra, VE, critere libre...) : le 2e critere\n  // historique (une seule colonne) migre une fois pour toutes vers la liste. Fait ici\n  // (a chaque chargement/import) pour que TOUTES les donnees anciennes soient couvertes,\n  // sans changement de format : un fichier v4.x plus ancien relit ce suivi sans rien voir.\n  if(!Array.isArray(merged.criteresSup)) merged.criteresSup = [];\n  if(merged.critere2Actif && !merged.criteresSup.some(c => c.id === \"cs1\")){\n    merged.criteresSup.unshift({ id:\"cs1\", label: merged.limitLabel2 || \"2e crit\u00e8re\", maxi: merged.limitValue2, miniActif:false, mini:\"\", axes:[], actif:true });\n    merged.critere2Actif = false;\n  }\n  return merged;\n}\n\n/* La tol\u00e9rance est un crit\u00e8re produit : commune \u00e0 toute la campagne,\n   sauf si un sc\u00e9nario d\u00e9clare explicitement une exception. */\nfunction limiteDe(sc){ return sc.limitOverride ? sc.limitValue : config.limitValue; }\nfunction libelleDe(sc){ return sc.limitOverride ? sc.limitLabel : config.limitLabel; }\n\n/* Reprise des fichiers ant\u00e9rieurs, o\u00f9 la tol\u00e9rance vivait dans chaque sc\u00e9nario */\n/* Migration d'une reference isolee (ancien format) dont la tolerance vivait par scenario */\nfunction migrerTolerancesOp(op){\n  const scs = op.scenarios;\n  if(!scs.length) return;\n  const refKey = String(scs[0].limitValue) + \"|\" + scs[0].limitLabel;\n  const toutesIdentiques = scs.every(s => String(s.limitValue) + \"|\" + s.limitLabel === refKey);\n  if(toutesIdentiques){\n    op.config.limitValue = scs[0].limitValue;\n    op.config.limitLabel = scs[0].limitLabel;\n    scs.forEach(s => s.limitOverride = false);\n  } else {\n    // valeurs divergentes : on garde la plus fr\u00e9quente en global, les autres en exception\n    const freq = {};\n    scs.forEach(s => { const k = String(s.limitValue)+\"|\"+s.limitLabel; freq[k] = (freq[k]||0)+1; });\n    const majoritaire = Object.keys(freq).sort((a,b) => freq[b]-freq[a])[0];\n    const [v, l] = majoritaire.split(\"|\");\n    op.config.limitValue = parseFloat(v);\n    op.config.limitLabel = l;\n    scs.forEach(s => { s.limitOverride = (String(s.limitValue)+\"|\"+s.limitLabel !== majoritaire); });\n  }\n}\n\n/* Un essai porte-t-il encore les r\u00e9glages actuels du sc\u00e9nario ? */\n/* liste precise de ce qui a change entre les conditions figees a la creation de l'essai\n   et les conditions actuelles du scenario \u2014 pour que \"le scenario a change\" dise QUOI,\n   pas seulement QUE. Tableau vide = rien n'a diverg\u00e9. */\nfunction paramsDivergences(sc, essai){\n  const snap = (essai.params && essai.params.logements) || [];\n  const actifs = snap.filter(s => s.suivi !== false); // v4.11 : les logements exclus volontairement ne signalent rien\n  const courant = snapshotLogements(sc);\n  const memeVal = (a,b) => String(a ?? \"\") === String(b ?? \"\");\n  const aff = v => (v === \"\" || v == null) ? \"\u2014\" : v;\n  const diffs = [];\n  actifs.forEach(s => {\n    const cur = courant.find(c => c.logementId === s.logementId);\n    const nom = cur ? (cur.outilNumero||\"?\") + \" \u00b7 \" + (cur.logementNom||\"\u2014\")\n                    : (s.outilNumero||\"?\") + \" \u00b7 \" + (s.logementNom||\"\u2014\");\n    if(!cur){ diffs.push(nom + \" (retir\u00e9 du sc\u00e9nario)\"); return; }\n    const champs = [];\n    if(!memeVal(s.vc, cur.vc)) champs.push(\"Vc \" + aff(s.vc) + \"\u2192\" + aff(cur.vc));\n    if(!memeVal(s.f, cur.f)) champs.push(\"f \" + aff(s.f) + \"\u2192\" + aff(cur.f));\n    if(!memeVal(s.charniere, cur.charniere)) champs.push(\"charni\u00e8re \" + aff(s.charniere) + \"\u2192\" + aff(cur.charniere));\n    if(champs.length) diffs.push(nom + \" \u2014 \" + champs.join(\", \"));\n  });\n  courant.forEach(c => {\n    if(!snap.some(s => s.logementId === c.logementId)) diffs.push((c.outilNumero||\"?\") + \" \u00b7 \" + (c.logementNom||\"\u2014\") + \" (ajout\u00e9 au sc\u00e9nario)\");\n  });\n  return diffs;\n}\n/* compte total de prelevements dans tout l'arbre : sert de garde-fou au chargement\n   (voir plus bas) pour ne jamais afficher silencieusement un fichier vide alors qu'une\n   sauvegarde plus ancienne, elle, contient des mesures reelles */\nfunction comptePrelevements(lignesArr){\n  return (lignesArr||[]).reduce((n,l) => n + (l.references||[]).reduce((n2,r) => n2 + (r.ops||[]).reduce((n3,o) => n3 + (o.scenarios||[]).reduce((n4,s) => n4 + (s.essais||[]).reduce((n5,e) => n5 + (e.prelevements||[]).length, 0), 0), 0), 0), 0);\n}\n/* Charge l'arbre Ligne > Reference ; reprend silencieusement l'ancien format\n   mono-reference (une seule campagne) s'il n'y a encore rien au nouveau format. */\nfunction loadAll(){\n  let raw;\n  try{ raw = localStorage.getItem(STORAGE_KEY); }catch(e){}\n  if(raw){\n    try{\n      const parsed = JSON.parse(raw);\n      const migre = migrerArbre(parsed);\n      if(migre){\n        lignes = migre.lignes;\n        projets = migre.projets;\n        responsables = migre.responsables;\n        activeProjetId = projets.find(x => x.id === parsed.activeProjetId) ? parsed.activeProjetId : null;\n        projets.forEach(purgerTagsMorts);\n        backlog = (parsed.backlog || []).map(normalizeBacklogItem);\n        revision = parsed.revision || 0;\n        specsUsine = normaliserSpecsUsine(parsed.specsUsine);\n        synchroNote = parsed.synchroNote || null;\n        const l = lignes.find(x => x.id === parsed.activeLigneId) || lignes[0];\n        activeLigneId = l.id;\n        const r = l.references.find(x => x.id === parsed.activeReferenceId) || l.references[0];\n        activeReferenceId = r ? r.id : null;\n        const op = r ? (r.ops.find(x => x.id === parsed.activeOpId) || r.ops[0]) : null;\n        activeOpId = op ? op.id : null;\n        data = op ? op.scenarios : [];\n        config = op ? op.config : Object.assign({}, defaultConfig);\n        activeId = (op && data.find(s => s.id === parsed.activeScenarioId)) ? parsed.activeScenarioId : (data[0] ? data[0].id : null);\n        // garde-fou : si ce fichier \"actuel\" ne contient AUCUN prelevement, on verifie\n        // qu'une ancienne sauvegarde (avant le passage au format Ligne/Reference/OP) ne\n        // contiendrait pas, elle, des mesures reelles restees invisibles derriere ce\n        // fichier vide (c'est exactement ce qui est arrive : une migration a produit un\n        // arbre vide qui masquait silencieusement les vraies donnees).\n        if(comptePrelevements(lignes) === 0){\n          let secours = null;\n          try{ secours = JSON.parse(localStorage.getItem(LEGACY_KEY) || \"null\"); }catch(e2){}\n          if(Array.isArray(secours) && secours.length){\n            const totalSecours = secours.reduce((n,s) => n + (s.essais||[]).reduce((n2,e) => n2 + (e.prelevements||[]).length, 0), 0);\n            if(totalSecours > 0){\n              // dialogue in-app (v4.6) : la reponse peut arriver apres le premier rendu de\n              // l'ecran (sur l'arbre vide) \u2014 on re-rend derriere la decision.\n              dialogueConfirmer(\n                \"Le fichier de suivi actuel semble vide (0 pr\u00e9l\u00e8vement), mais une ancienne sauvegarde de cet outil contient \" + totalSecours + \" pr\u00e9l\u00e8vement(s) enregistr\u00e9(s).\\n\\nR\u00e9cup\u00e9rer cette ancienne sauvegarde maintenant ?\\n\\n(Recommand\u00e9 \u2014 sinon ces essais resteront invisibles.)\",\n                { titre: \"R\u00e9cup\u00e9rer une ancienne sauvegarde ?\" }\n              ).then(okSecours => {\n                if(!okSecours) return;\n                let secoursConfig = null;\n                try{ secoursConfig = JSON.parse(localStorage.getItem(LEGACY_KEY + \"_config\") || \"null\"); }catch(e2){}\n                const op2 = { id: uid(\"o\"), nom: \"OP10\", ordre: 10,\n                  config: Object.assign({}, defaultConfig, { forceRatioActif: true }, secoursConfig || {}),\n                  scenarios: secours.map(normalizeScenario) };\n                const ref2 = { id: uid(\"r\"), nom: \"DV 356x26 RPI\", ops: [op2] };\n                lignes = [{ id: uid(\"l\"), nom: \"EMAG 1\", references: [ref2] }];\n                projets = []; activeProjetId = null; responsables = [];\n                backlog = [];\n                activeLigneId = lignes[0].id; activeReferenceId = ref2.id; activeOpId = op2.id;\n                data = op2.scenarios; config = op2.config;\n                activeId = data[0] ? data[0].id : null;\n                saveData();\n                render();\n              });\n            }\n          }\n        }\n        return;\n      }\n    }catch(e){ console.warn(\"loadAll : lecture du suivi impossible \u2014 repli ancien format/exemple\", e); }\n  }\n  // pas de nouveau format : reprendre l'ancien fichier mono-reference s'il existe\n  let legacyData = null, legacyConfig = null;\n  try{ legacyData = JSON.parse(localStorage.getItem(LEGACY_KEY) || \"null\"); }catch(e){}\n  try{ legacyConfig = JSON.parse(localStorage.getItem(LEGACY_KEY + \"_config\") || \"null\"); }catch(e){}\n  if(Array.isArray(legacyData) && legacyData.length){\n    const op = {\n      id: uid(\"o\"), nom: \"OP10\", ordre: 10,\n      config: Object.assign({}, defaultConfig, { forceRatioActif: true }, legacyConfig || {}),\n      scenarios: legacyData.map(normalizeScenario)\n    };\n    const migrationTolerance = !(legacyConfig && legacyConfig.limitValue !== undefined);\n    if(migrationTolerance) migrerTolerancesOp(op);\n    const ref = { id: uid(\"r\"), nom: \"DV 356x26 RPI\", ops: [op] };\n    lignes = [{ id: uid(\"l\"), nom: \"EMAG 1\", references: [ref] }];\n    projets = []; activeProjetId = null; responsables = [];\n    backlog = [];\n    activeLigneId = lignes[0].id;\n    activeReferenceId = ref.id;\n    activeOpId = op.id;\n    data = op.scenarios;\n    config = op.config;\n    activeId = data[0] ? data[0].id : null;\n    saveData(); // persiste la migration tout de suite : sinon elle refait le meme travail\n                // (et regenere de nouveaux id) a chaque ouverture tant qu'aucune saisie\n                // n'a par ailleurs declenche de sauvegarde\n    return;\n  }\n  // premiere utilisation : donnees de depart, aucun projet (les projets sont facultatifs)\n  lignes = defaultLignes();\n  projets = []; activeProjetId = null; responsables = [];\n  backlog = [];\n  activeLigneId = lignes[0].id;\n  activeReferenceId = lignes[0].references[0].id;\n  activeOpId = lignes[0].references[0].ops[0].id;\n  data = lignes[0].references[0].ops[0].scenarios;\n  config = lignes[0].references[0].ops[0].config;\n  activeId = data[0] ? data[0].id : null;\n}\n/* Repose un arbre complet (projets-etiquettes compris) depuis un instantane ou un fichier\n   importe, quel que soit le format qui l'a produit (5, 6 ou 7 -- voir migrerArbre). Utilise\n   par la restauration depuis l'historique et depuis le point de reprise : la logique etait\n   dupliquee entre les deux, avec le meme risque d'oubli a chaque evolution du format. */\nfunction appliquerArbre(source){\n  const migre = migrerArbre(source);\n  lignes = migre ? migre.lignes : [];\n  projets = migre ? migre.projets : [];\n  responsables = migre ? migre.responsables : [];\n  specsUsine = normaliserSpecsUsine(source.specsUsine);\n  synchroNote = source.synchroNote || null;\n  if(!lignes.length) lignes = defaultLignes();\n  projets.forEach(purgerTagsMorts);\n  activeProjetId = projets.find(x => x.id === source.activeProjetId) ? source.activeProjetId : null;\n  activeLigneId = lignes[0].id;\n  const r = lignes[0].references[0];\n  activeReferenceId = r ? r.id : null;\n  const op = r ? r.ops[0] : null;\n  activeOpId = op ? op.id : null;\n  data = op ? op.scenarios : [];\n  config = op ? op.config : Object.assign({}, defaultConfig);\n  if(!data.find(x => x.baseline) && data.length) data[0].baseline = true;\n  activeId = data[0] ? data[0].id : null;\n}\n\n/* ---- persistance 100 % locale : navigateur (auto) + fichier .json (export/import) ---- */\nlet storageOk = true;\nlet lastSavedAt = null;\nlet unexported = false;\n\n/* ---- SAUVEGARDE ET QUOTA (v3.19) ------------------------------------------------------\n   Le scenario dangereux de l'outil n'est pas un mauvais calcul, c'est celui-ci : le quota du\n   navigateur est atteint, saveData() echoue, et le seul signal etait une PASTILLE ROUGE avec\n   une info-bulle. Quelqu'un qui saisit des relev\u00e9s devant la machine ne survole jamais une\n   pastille : il peut travailler une heure sur des donnees qui ne sont ecrites nulle part, et\n   tout perdre en fermant l'onglet.\n   Trois niveaux desormais :\n     1. RECUPERATION AUTOMATIQUE \u2014 l'historique glissant pese jusqu'a 5 fois le suivi lui-meme.\n        En cas d'echec on le purge et on retente : neuf fois sur dix ca suffit, et un point de\n        reprise vaut moins que les mesures en cours.\n     2. ALERTE FRANCHE \u2014 si ca echoue quand meme : une fenetre modale (une seule fois) qui dit\n        quoi faire, plus un bandeau rouge permanent en haut de page tant que dure la panne.\n     3. PREVENTION \u2014 des que le fichier depasse 3,5 Mo, un avertissement unique avec le detail\n        de ce qui pese, avant que le mur soit atteint.                                        */\nconst QUOTA_ALERTE = 3.5 * 1024 * 1024;\nlet quotaAlerteVue = false;\nlet quotaPanneSignalee = false;\n\nfunction payloadSuivi(){\n  // format 8 (v4.2) : `lignes` reste la racine, exactement comme les formats 5 et 7 -- une\n  // version anterieure a la v4 lit ce fichier normalement, seuls `projets` et `responsables`\n  // lui sont invisibles (elle ne les connait pas, elle ne les cherche pas).\n  return JSON.stringify({ format:8, lignes, projets, activeProjetId, responsables, backlog, revision, specsUsine, synchroNote, activeLigneId, activeReferenceId, activeOpId, activeScenarioId: activeId, livraisons });\n}\n\n/* Ce qui pese vraiment, nomme, pour que l'utilisateur puisse agir plutot que subir. */\nfunction inventairePoids(){\n  const items = [];\n  lignes.forEach(l => l.references.forEach(r => r.ops.forEach(op => {\n    if(op.ficheOutil && op.ficheOutil.stockage !== \"dossier\" && op.ficheOutil.dataUrl){\n      items.push({ quoi: \"Fiche outil \u2014 \" + (l.nom || \"?\") + \" \u203a \" + (r.nom || \"?\") + \" \u203a \" + (op.nom || \"?\"),\n                   octets: op.ficheOutil.dataUrl.length });\n    }\n    (op.scenarios || []).forEach(sc => (sc.outils || []).forEach(o => {\n      if(o.plan && o.plan.stockage !== \"dossier\" && o.plan.dataUrl){\n        items.push({ quoi: \"Plan outil \" + (o.numero || \"?\") + \" \u2014 \" + (sc.name || \"?\"), octets: o.plan.dataUrl.length });\n      }\n    }));\n  })));\n  backlog.forEach(b => { if(b.image) items.push({ quoi: \"Image de suggestion \u2014 \" + (b.titre || \"sans titre\"), octets: b.image.length }); });\n  items.sort((a,b) => b.octets - a.octets);\n  return items;\n}\nfunction ko(n){ return Math.round(n/1024) + \" ko\"; }\nfunction mo(n){ return (n/1024/1024).toFixed(2).replace(\".\", \",\") + \" Mo\"; }\n\nfunction detailPoidsTexte(){\n  const items = inventairePoids();\n  if(!items.length) return \"Aucune pi\u00e8ce jointe int\u00e9gr\u00e9e au fichier : le poids vient des mesures elles-m\u00eames.\";\n  const l = [\"Ce qui p\u00e8se le plus :\"];\n  items.slice(0,6).forEach(i => l.push(\"  \u00b7 \" + i.quoi + \" \u2014 \" + ko(i.octets)));\n  if(items.length > 6) l.push(\"  \u00b7 \u2026 et \" + (items.length - 6) + \" autre(s)\");\n  l.push(\"\", \"Une pi\u00e8ce jointe se d\u00e9place vers le dossier local en la retirant puis en la rejoignant, dossier connect\u00e9.\");\n  return l.join(String.fromCharCode(10));\n}\n\nfunction libererEspaceHistorique(){\n  // les points de reprise valent moins que les mesures en cours de saisie\n  let avait = false;\n  try{ avait = !!localStorage.getItem(HISTORY_KEY); localStorage.removeItem(HISTORY_KEY); }catch(e){}\n  try{ localStorage.removeItem(BACKUP_KEY); }catch(e){}\n  return avait;\n}\n\nfunction signalerPanneStockage(){\n  storageOk = false;\n  renderBandeauStockage();\n  if(quotaPanneSignalee) return;\n  quotaPanneSignalee = true;\n  dialogueAlerte(`SAUVEGARDE BLOQU\u00c9E \u2014 vos derni\u00e8res saisies ne sont PAS enregistr\u00e9es.\n\nLa m\u00e9moire que le navigateur accorde \u00e0 cet outil est pleine. Tout ce que vous saisissez maintenant sera perdu \u00e0 la fermeture de l'onglet.\n\n\u00c0 faire tout de suite, dans cet ordre :\n  1. \u00ab Exporter le suivi \u00bb \u2014 vos donn\u00e9es partent dans un fichier .json, \u00e0 l'abri.\n  2. Connectez le dossier local (menu \u2022\u2022\u2022 \u2192 Dossier photos) et retirez puis rejoignez les pi\u00e8ces jointes lourdes : elles seront stock\u00e9es \u00e0 part.\n\n` + detailPoidsTexte(), \"Sauvegarde bloqu\u00e9e\");\n}\n\nfunction verifierPoids(taille){\n  if(quotaAlerteVue || taille < QUOTA_ALERTE) return;\n  quotaAlerteVue = true;\n  dialogueAlerte(`Le fichier de suivi atteint ${mo(taille)}.\n\nLe navigateur accorde environ 5 Mo \u00e0 cet outil, mesures et pi\u00e8ces jointes comprises. Au-del\u00e0, la sauvegarde \u00e9choue et les relev\u00e9s ne s'enregistrent plus. Il reste de la marge, mais il vaut mieux agir maintenant.\n\n` + detailPoidsTexte(), \"Poids du suivi\");\n}\n\n/* ---- pastille permanente du poids (v4.5) ------------------------------------------\n   Le quota ne se voit qu'au moment de l'alerte, souvent trop tard pour agir sereinement.\n   Une pastille en pied de page affiche en continu le poids du suivi et la marge restante ;\n   le clic donne le detail (meme contenu que l'alerte, consultable a tout moment). */\nlet dernierPoids = 0;\nfunction renderPoidsFooter(taille){\n  dernierPoids = taille || dernierPoids || 0;\n  const el = document.getElementById(\"footPoids\");\n  if(!el) return;\n  const sur5 = dernierPoids / (5 * 1024 * 1024);\n  el.classList.remove(\"alerte\", \"critique\");\n  if(sur5 >= 0.85) el.classList.add(\"critique\");\n  else if(sur5 >= 0.6) el.classList.add(\"alerte\");\n  el.textContent = \"suivi \" + mo(dernierPoids) + \" / ~5 Mo\";\n  el.title = \"Fichier de suivi : \" + mo(dernierPoids) + \" sur ~5 Mo que le navigateur accorde \u00e0 cet outil (\"\n    + Math.round(sur5 * 100) + \"% utilis\u00e9).\\nCliquer pour le d\u00e9tail et les conseils pour all\u00e9ger.\";\n}\nfunction installerClickPoids(){\n  const el = document.getElementById(\"footPoids\");\n  if(!el) return;\n  el.addEventListener(\"click\", () => {\n    dialogueAlerte(\"Poids du suivi : \" + mo(dernierPoids) + \" sur ~5 Mo accord\u00e9s par le navigateur (\"\n      + Math.round((dernierPoids / (5 * 1024 * 1024)) * 100) + \"% utilis\u00e9).\\n\\n\" + detailPoidsTexte(), \"Poids du suivi\");\n  });\n}\n\nfunction saveData(){\n  syncActiveOp();\n  const payload = payloadSuivi();\n  const ecrire = () => {\n    localStorage.setItem(STORAGE_KEY, payload);\n    localStorage.setItem(STORAGE_KEY + \"_meta\", JSON.stringify({ savedAt: new Date().toISOString() }));\n  };\n  try{\n    ecrire();\n    storageOk = true;\n    lastSavedAt = new Date();\n    quotaPanneSignalee = false;\n    renderBandeauStockage();\n    verifierPoids(payload.length);\n    renderPoidsFooter(payload.length);\n    pushHistory();\n    writeBackupToFolder();\n  }catch(e){\n    // 1er secours : purger l'historique glissant, qui pese plusieurs fois le suivi\n    if(libererEspaceHistorique()){\n      try{\n        ecrire();\n        storageOk = true;\n        lastSavedAt = new Date();\n        quotaPanneSignalee = false;\n        renderBandeauStockage();\n        verifierPoids(payload.length);\n        renderPoidsFooter(payload.length);\n        unexported = true;\n        updateSaveUI();\n        if(window.cloudApresSauvegarde) cloudApresSauvegarde();\n        return;\n      }catch(e2){ /* le mur est bien la */ }\n    }\n    signalerPanneStockage();\n  }\n  unexported = true;\n  updateSaveUI();\n  if(window.cloudApresSauvegarde) cloudApresSauvegarde();\n}\n\n/* bandeau permanent : une pastille ne se survole pas quand on saisit devant une machine */\nfunction renderBandeauStockage(){\n  const el = document.getElementById(\"bandeauStockage\");\n  if(!el) return;\n  el.hidden = storageOk;\n  if(!storageOk){\n    el.innerHTML = `<b>Sauvegarde bloqu\u00e9e</b>\n      <span>La m\u00e9moire du navigateur est pleine : vos saisies ne sont plus enregistr\u00e9es et seront perdues \u00e0 la fermeture.</span>\n      <button class=\"primary\" id=\"bandeauExport\">Exporter le suivi maintenant</button>`;\n    const b = document.getElementById(\"bandeauExport\");\n    if(b) b.addEventListener(\"click\", () => document.getElementById(\"exportBtn\").click());\n  }\n}\n\n/* ---- filet de securite renforce : historique glissant de sauvegardes automatiques ----\n   en plus de l'export manuel et du cran d'annulation Reinitialiser/Importer, on garde\n   jusqu'a 5 points de reprise repartis dans le temps (au plus 1 toutes les 5 minutes),\n   consultables depuis \"Historique\" \u2014 ca couvre le cas ou une donnee a ete perdue/masquee\n   sans passer par Reinitialiser/Importer (ex. incident du 27/08/2026). */\nconst HISTORY_KEY = STORAGE_KEY + \"_history\";\nlet lastHistoryAt = 0;\nfunction pushHistory(){\n  const now = Date.now();\n  if(now - lastHistoryAt < 5*60*1000) return;\n  lastHistoryAt = now;\n  let hist = [];\n  try{ hist = JSON.parse(localStorage.getItem(HISTORY_KEY) || \"[]\"); }catch(e){}\n  hist.push({ savedAt: new Date().toISOString(), count: comptePrelevements(lignes), lignes, projets, activeProjetId, responsables, backlog, revision });\n  if(hist.length > 5) hist = hist.slice(hist.length - 5);\n  try{ localStorage.setItem(HISTORY_KEY, JSON.stringify(hist)); }catch(e){}\n}\nfunction historyHTML(){\n  let hist = [];\n  try{ hist = JSON.parse(localStorage.getItem(HISTORY_KEY) || \"[]\"); }catch(e){}\n  const rows = hist.slice().reverse().map((h, i) => {\n    const idx = hist.length - 1 - i;\n    return `<tr>\n      <td>${new Date(h.savedAt).toLocaleString(\"fr-FR\")}</td>\n      <td style=\"text-align:right;\">${h.count}</td>\n      <td><button class=\"ghost\" data-history-restore=\"${idx}\">Restaurer celle-ci</button></td>\n    </tr>`;\n  }).join(\"\") || `<tr><td colspan=\"3\" class=\"log-empty\">Pas encore assez de sauvegardes automatiques (une nouvelle est prise au plus toutes les 5 min pendant que vous travaillez)</td></tr>`;\n  return `\n    <h3>Historique local \u2014 points de reprise automatiques</h3>\n    <p class=\"panel-hint\">En plus de l'export manuel, l'outil garde jusqu'\u00e0 5 sauvegardes prises automatiquement au fil du temps dans ce navigateur, sur cette machine. Utile si des donn\u00e9es ont disparu sans passer par \u00ab R\u00e9initialiser \u00bb ou \u00ab Importer \u00bb.</p>\n    <div class=\"tbl-wrap\">\n      <table class=\"backlog\">\n        <thead><tr><th>Enregistr\u00e9 le</th><th>Pr\u00e9l\u00e8vements</th><th></th></tr></thead>\n        <tbody>${rows}</tbody>\n      </table>\n    </div>\n    <div class=\"panel-actions\"><button class=\"primary\" id=\"historyClose\">Fermer</button></div>\n  `;\n}\nfunction renderHistoryPanel(){\n  const wrap = document.getElementById(\"historyPanel\");\n  if(!wrap || wrap.hidden) return;\n  wrap.innerHTML = historyHTML();\n  wrap.querySelectorAll(\"[data-history-restore]\").forEach(btn => {\n    btn.addEventListener(\"click\", () => {\n      let hist = [];\n      try{ hist = JSON.parse(localStorage.getItem(HISTORY_KEY) || \"[]\"); }catch(e){}\n      const h = hist[parseInt(btn.getAttribute(\"data-history-restore\"), 10)];\n      if(!h) return;\n      dialogueConfirmer(\"Restaurer l'\u00e9tat enregistr\u00e9 le \" + new Date(h.savedAt).toLocaleString(\"fr-FR\") + \" (\" + h.count + \" pr\u00e9l\u00e8vement(s)) ?\\n\\nCela remplacera TOUTES les donn\u00e9es actuellement affich\u00e9es (toutes lignes et r\u00e9f\u00e9rences confondues).\\n\\n(Un \u00ab \u21ba Restaurer \u00bb restera disponible pour annuler ce geste.)\", { titre: \"Restaurer cet \u00e9tat ?\" }).then(ok => {\n        if(!ok) return;\n        backupSnapshot(\"Restauration depuis l'historique (\" + new Date(h.savedAt).toLocaleString(\"fr-FR\") + \")\");\n        appliquerArbre(h);\n        backlog = (h.backlog || []).map(normalizeBacklogItem);\n        revision = h.revision || 0;\n        saveData();\n        updateRestoreUI();\n        fermerPanneaux();\n        render();\n      });\n    });\n  });\n  const closeBtn = document.getElementById(\"historyClose\");\n  if(closeBtn) closeBtn.addEventListener(\"click\", fermerPanneaux);\n}\ndocument.getElementById(\"historyBtn\").addEventListener(\"click\", () => {\n  ouvrirPanneau(\"historyPanel\");\n  renderHistoryPanel();\n});\ndocument.getElementById(\"photosDirBtn\").addEventListener(\"click\", connectPhotosDir);\nif(!fsPhotosSupported()){\n  const b = document.getElementById(\"photosDirBtn\");\n  if(b) b.title = \"Fonction disponible sur Edge/Chrome (ordinateur), via l'adresse en ligne de l'outil.\";\n}\ntryReconnectPhotosDir();\n\nfunction updateSaveUI(){\n  const status = document.getElementById(\"saveStatus\");\n  if(!status) return;\n  const setMsg = (msg) => { status.title = msg; status.setAttribute(\"aria-label\", msg); };\n  const heure = lastSavedAt ? lastSavedAt.toLocaleTimeString(\"fr-FR\", {hour:\"2-digit\", minute:\"2-digit\"}) : null;\n  if(!storageOk){\n    setMsg(unexported\n      ? \"\u26a0 Sauvegarde navigateur bloqu\u00e9e \u2014 exportez avant de fermer\"\n      : \"\u26a0 Sauvegarde navigateur bloqu\u00e9e \u2014 export\u00e9 \u00e0 \" + heure + \", r\u00e9exportez avant de fermer\");\n    status.className = \"save-status error\";\n    return;\n  }\n  if(unexported){\n    setMsg((heure ? \"Enregistr\u00e9 dans ce navigateur \u00e0 \" + heure : \"Enregistr\u00e9 dans ce navigateur\") + \" \u00b7 non export\u00e9\");\n    status.className = \"save-status dirty\";\n  } else if(heure){\n    setMsg(\"Export\u00e9 \u00e0 \" + heure);\n    status.className = \"save-status saved\";\n  } else {\n    setMsg(\"Sauvegarde automatique dans ce navigateur\");\n    status.className = \"save-status\";\n  }\n}\n\n/* ---- filet de securite : un cran d'annulation avant Reinitialiser / Importer ---- */\nconst BACKUP_KEY = STORAGE_KEY + \"_backup\";\nfunction backupSnapshot(label){\n  syncActiveOp();\n  try{\n    localStorage.setItem(BACKUP_KEY, JSON.stringify({ savedAt: new Date().toISOString(), label, lignes, projets, activeProjetId, responsables, backlog, revision, specsUsine, synchroNote }));\n  }catch(e){}\n}\nfunction hasBackup(){\n  try{ return !!localStorage.getItem(BACKUP_KEY); }catch(e){ return false; }\n}\nfunction restoreBackup(){\n  let snap = null;\n  try{ snap = JSON.parse(localStorage.getItem(BACKUP_KEY) || \"null\"); }catch(e){}\n  if(!snap){ dialogueAlerte(\"Aucun \u00e9tat pr\u00e9c\u00e9dent \u00e0 restaurer.\", \"Rien \u00e0 restaurer\"); updateRestoreUI(); return; }\n  const quand = new Date(snap.savedAt).toLocaleString(\"fr-FR\");\n  dialogueConfirmer(\"Restaurer l'\u00e9tat d'avant \u00ab \" + (snap.label || \"la derni\u00e8re op\u00e9ration\") + \" \u00bb (\" + quand + \") ?\\n\\nCela remplacera les donn\u00e9es actuellement affich\u00e9es (toutes lignes et r\u00e9f\u00e9rences confondues).\", { titre: \"Restaurer l'\u00e9tat pr\u00e9c\u00e9dent ?\" }).then(ok => {\n    if(!ok) return;\n    appliquerArbre(snap);\n    backlog = (snap.backlog || []).map(normalizeBacklogItem);\n    revision = snap.revision || 0;\n    specsUsine = normaliserSpecsUsine(snap.specsUsine);\n    synchroNote = snap.synchroNote || null;\n    activeId = data[0] ? data[0].id : null;\n    try{ localStorage.removeItem(BACKUP_KEY); }catch(e){}\n    recomputeCycles();\n    saveData();\n    updateRestoreUI();\n    render();\n  });\n}\nfunction updateRestoreUI(){\n  const btn = document.getElementById(\"restoreBtn\");\n  if(!btn) return;\n  const present = hasBackup();\n  btn.hidden = !present;\n  if(present){\n    try{\n      const snap = JSON.parse(localStorage.getItem(BACKUP_KEY));\n      btn.title = \"Restaurer l'\u00e9tat d'avant \u00ab \" + (snap.label || \"\") + \" \u00bb (\" + new Date(snap.savedAt).toLocaleString(\"fr-FR\") + \")\";\n    }catch(e){}\n  }\n}\n\n/* nom de l'exportateur, memorise sur ce poste pour tracer les envois */\nconst AUTEUR_KEY = STORAGE_KEY + \"_auteur\";\nlet auteurNom = \"\";\ntry{ auteurNom = localStorage.getItem(AUTEUR_KEY) || \"\"; }catch(e){}\n\nfunction exportData(){\n  syncActiveOp();\n  revision += 1;\n  const payload = {\n    outil: \"SPK Suivi optimisation\",\n    // format 8 (v4.2) : `lignes` reste la racine, `projets`/`responsables` ne sont que des\n    // listes posees a cote. Une version anterieure a la v4 lit ce fichier sans souci -- elle\n    // ignore juste ce qu'elle ne connait pas -- contrairement au format 6 (v4.0) qui rendait\n    // l'arbre illisible aux anciennes versions.\n    format: 8,\n    toolVersion: TOOL_VERSION,\n    revision: revision,\n    exporteLe: new Date().toISOString(),\n    exportePar: auteurNom,\n    lignes: lignes,\n    projets: projets,\n    activeProjetId: activeProjetId,\n    responsables: responsables,\n    backlog: backlog,\n    // onglet ouvert chez l'exportateur : permet a l'import de retomber directement\n    // dessus (sinon, avec plusieurs lignes/references/OP, la personne qui importe\n    // atterrit sur le premier onglet de chaque niveau et peut croire que des\n    // prelevements ont disparu alors qu'ils sont juste sur un autre onglet)\n    activeLigneId: activeLigneId,\n    activeReferenceId: activeReferenceId,\n    activeOpId: activeOpId,\n    activeScenarioId: activeId\n  };\n  const blob = new Blob([JSON.stringify(payload, null, 2)], {type:\"application/json\"});\n  const url = URL.createObjectURL(blob);\n  const a = document.createElement(\"a\");\n  const d = new Date();\n  const stamp = d.getFullYear() + String(d.getMonth()+1).padStart(2,\"0\") + String(d.getDate()).padStart(2,\"0\")\n              + \"-\" + String(d.getHours()).padStart(2,\"0\") + String(d.getMinutes()).padStart(2,\"0\");\n  a.href = url;\n  a.download = \"SuiviOptimisation_rev\" + revision + \"_\" + stamp + \".json\";\n  document.body.appendChild(a);\n  a.click();\n  document.body.removeChild(a);\n  setTimeout(() => URL.revokeObjectURL(url), 2000);\n  unexported = false;\n  lastSavedAt = new Date();\n  saveData();\n  updateSaveUI();\n  updateRevisionUI();\n}\n\n/* Export CSV \u2014 une ligne par pr\u00e9l\u00e8vement, lisible par Excel FR et le syst\u00e8me qualit\u00e9.\n   Limite au SEUL scenario affiche (avant : tous les scenarios de l'OP melanges, ce qui\n   noyait le vrai essai sous 2-3 essais de demo restes vides, l'ensemble ressemblant a une\n   ligne repetee) ; essaiIds permet de ne garder que les essais coches dans le panneau. */\nfunction exportCSV(essaiIds){\n  const sc = data.find(s => s.id === activeId);\n  if(!sc){ dialogueAlerte(\"Aucun sc\u00e9nario s\u00e9lectionn\u00e9.\", \"Rien \u00e0 g\u00e9n\u00e9rer\"); return; }\n  const sep = \";\";\n  const num = v => (v === \"\" || v === null || v === undefined || isNaN(parseFloat(v)))\n    ? \"\" : String(v).replace(\".\", \",\");            // Excel FR attend la virgule d\u00e9cimale\n  const txt = v => `\"${String(v ?? \"\").replace(/\"/g, '\"\"')}\"`;\n\n  const ligneActive = getActiveLigne();\n  const refActive = getActiveReference();\n  const opActive = getActiveOp();\n  const csvLignes = [[\n    \"Ligne de production\",\"Reference disque\",\"OP\",\"Scenario\",\"Outils (numero/logement:Vc/f/charniere)\",\n    \"Essai\",\"Date\",\"Heure debut\",\"Heure fin\",\"Equipe\",\"Operateur\",\"Maturite bruts (j)\",\"Observations essai\",\"Logement mesure\",\"Point de mesure\",\n    \"N piece\",\"Grandeur\",\"Valeur\",\"Droite\",\"Gauche\",\n    \"Tolerance\",\n    // v4.9 : une colonne par crit\u00e8re suppl\u00e9mentaire actif \u00d7 axe (\u00e0 la place du 2e crit\u00e8re fig\u00e9)\n    ...criteresSupActifs(sc).flatMap(c => axesDe(c).map(ax =>\n      (c.label || \"critere\") + (ax === \"v\" ? \"\" : \" \" + (AXE_LABELS[ax] || ax)) + \" (tol \" + (c.maxi ?? \"?\") + (c.miniActif ? \" min \" + c.mini : \"\") + \")\")),\n    \"Usure plaquette\",\"Conforme\"\n  ].join(sep)];\n\n  (sc.essais||[]).filter(es => !essaiIds || essaiIds.includes(es.id)).forEach(es => {\n    const snap = logementsSuivis(es);\n    const outilsResume = snap.map(lp => { const n = nomLogementActuel(sc, lp);\n      return `${n.outilNumero||\"?\"}/${n.logementNom||\"?\"}:Vc${lp.vc??\"-\"}/f${lp.f??\"-\"}/charn${lp.charniere??\"-\"}`; }).join(\" | \");\n    (es.prelevements||[]).forEach(r => {\n      const conf = checkConform(sc, r);\n      const lp = snap.find(x => x.logementId === r.logementId);\n      const logementMesure = lp ? (() => { const n = nomLogementActuel(sc, lp); return `${n.outilNumero||\"?\"}/${n.logementNom||\"?\"}`; })() : \"\";\n      csvLignes.push([\n        txt(ligneActive ? ligneActive.nom : \"\"), txt(refActive ? refActive.nom : \"\"), txt(opActive ? opActive.nom : \"\"),\n        txt(sc.name), txt(outilsResume),\n        txt(es.titre), txt(es.date), txt(es.heureDebut || \"\"), txt(es.heureFin || \"\"), txt(es.equipe), txt(es.operateur), num(es.maturiteBruts), txt(es.observations),\n        txt(logementMesure), txt(r.pointMesure),\n        num(r.piece), txt(libelleDe(sc)),\n        num(sc.emag1 ? valeurMesuree(sc, r) : r.batt),\n        num(sc.emag1 ? r.battD : \"\"), num(sc.emag1 ? r.battG : \"\"),\n        num(limiteDe(sc)),\n        ...criteresSupActifs(sc).flatMap(c => axesDe(c).map(ax => {\n          const v = ((r.valeurs || {})[c.id] || {})[ax];\n          return num(v === \"\" || v == null ? \"\" : v);\n        })),\n        txt(USURE_LABELS[r.usure] || \"\"),\n        conf === null ? \"\" : (conf ? \"OUI\" : \"NON\")\n      ].join(sep));\n    });\n  });\n\n  if(csvLignes.length === 1){ dialogueAlerte(\"Aucun pr\u00e9l\u00e8vement \u00e0 exporter pour les essais s\u00e9lectionn\u00e9s.\", \"Export CSV vide\"); return; }\n\n  const blob = new Blob([\"\ufeff\" + csvLignes.join(\"\\r\\n\")], {type:\"text/csv;charset=utf-8\"});\n  const url = URL.createObjectURL(blob);\n  const a = document.createElement(\"a\");\n  const d = new Date();\n  const stamp = d.getFullYear() + String(d.getMonth()+1).padStart(2,\"0\") + String(d.getDate()).padStart(2,\"0\")\n              + \"-\" + String(d.getHours()).padStart(2,\"0\") + String(d.getMinutes()).padStart(2,\"0\");\n  const nomFichier = (sc.name || \"releves\").replace(/[^a-zA-Z0-9_-]+/g, \"_\");\n  a.href = url;\n  a.download = nomFichier + \"_\" + stamp + \".csv\";\n  document.body.appendChild(a); a.click(); document.body.removeChild(a);\n  setTimeout(() => URL.revokeObjectURL(url), 2000);\n}\n\n/* ---- rapport de validation : un scenario, une page HTML autonome pretes a envoyer ---- */\nfunction conclusionScenario(sc){\n  const stats = scenarioStats(sc);\n  if(stats.validated) return { label: \"VALID\u00c9\", classe: \"ok\",\n    detail: stats.validCount + \" essai(s) conforme(s), seuil de \" + (sc.validationThreshold || \"\u2014\") + \" atteint.\" };\n  if(stats.badCount > 0) return { label: \"NON VALID\u00c9\", classe: \"bad\",\n    detail: stats.badCount + \" essai(s) non conforme(s) \u2014 au moins un pr\u00e9l\u00e8vement hors tol\u00e9rance.\" };\n  return { label: \"\u00c0 AFFINER\", classe: \"pending\",\n    detail: stats.validCount + \"/\" + (sc.validationThreshold || \"\u2014\") + \" essai(s) conforme(s) \u2014 campagne encore incompl\u00e8te.\" };\n}\n\n/* detail ligne a ligne des prelevements d'un essai, pour le rapport de validation\n   autonome \u2014 le tableau \"Essais\" ne donne qu'un statut agrege, ce qui a deja fait croire\n   a tort que des mesures manquaient alors que seul le detail n'etait pas exporte */\nfunction prelevementsDetailHTML(sc, es){\n  const snap = (es.params && es.params.logements) || [];\n  const labelLogement = (logementId) => {\n    const lp = snap.find(l => l.logementId === logementId);\n    if(!lp) return \"\";\n    const nom = nomLogementActuel(sc, lp); // v4.22 : nom actuel, pas nom fige\n    return (String(nom.outilNumero||\"?\") + \" \" + String(nom.logementNom||\"\")).trim();\n  };\n  const showLogementCol = snap.length > 1;\n  const csupCols = csupColonnes(sc);\n  const cotesR = battCotesDe(sc);\n  const rows = (es.prelevements || []).slice()\n    .sort((a,b) => parseFloat(a.piece) - parseFloat(b.piece))\n    .map(r => {\n      const exempte = !toleranceRequisePour(sc, r);\n      const conform = checkConform(sc, r);\n      const statut = exempte ? \"Charni\u00e8re seule\" : conform === null ? \"\u2014\" : conform ? \"OK\" : (raisonNonConforme(sc, r) || \"Hors tol\u00e9rance\");\n      const valeur = sc.battActif === false ? \"\u2014\"\n        : cotesR === \"mono\" ? fmtBatt(r.batt)\n        : cotesR === \"D\" ? (\"D \" + fmtBatt(r.battD))\n        : cotesR === \"G\" ? (\"G \" + fmtBatt(r.battG))\n        : (\"D \" + fmtBatt(r.battD) + \" / G \" + fmtBatt(r.battG));\n      return `<tr>\n        <td>${escapeAttr(r.piece)}</td>\n        ${showLogementCol ? `<td>${escapeAttr(labelLogement(r.logementId))}</td>` : \"\"}\n        <td>${escapeAttr(r.pointMesure) || \"\u2014\"}</td>\n        <td style=\"text-align:right;\">${valeur}</td>\n        ${csupCols.map(col => {\n          const v = ((r.valeurs || {})[col.c.id] || {})[col.ax];\n          return `<td style=\"text-align:right;\">${v === \"\" || v == null ? \"\u2014\" : v}</td>`;\n        }).join(\"\")}\n        <td>${USURE_LABELS[r.usure] || \"\u2014\"}</td>\n        <td>${statut}</td>\n      </tr>`;\n    }).join(\"\");\n  if(!rows) return \"\";\n  return `\n    <h3 style=\"font-size:12.5px; margin:16px 0 4px; color:#154d8a; text-transform:uppercase; letter-spacing:.03em;\">${escapeAttr(es.titre)}${es.date ? \" \u2014 \" + escapeAttr(es.date) : \"\"}</h3>\n    <table>\n      <tr><th>N\u00b0 pi\u00e8ce</th>${showLogementCol ? \"<th>Logement</th>\" : \"\"}<th>Point de mesure</th><th>Valeur</th>${csupCols.map(col => `<th>${escapeAttr(col.c.label || \"crit\u00e8re\")}${col.ax !== \"v\" ? \" \" + (AXE_LABELS[col.ax] || col.ax) : \"\"}</th>`).join(\"\")}<th>Usure</th><th>Statut</th></tr>\n      ${rows}\n    </table>\n  `;\n}\nfunction rapportValidationHTML(sc){\n  const ligneActive = getActiveLigne(), refActive = getActiveReference(), opActive = getActiveOp();\n  const stats = scenarioStats(sc);\n  const scrap = scrapStats(sc);\n  const concl = conclusionScenario(sc);\n  const cost = scenarioCost(sc);\n  const base = baselineScenario();\n  const baseCost = base ? scenarioCost(base) : null;\n  // le rapport part chez le client : le pourcentage annonce doit porter sur le meme\n  // perimetre que le cout mis en avant, sinon on promet un gain qui n'existe pas\n  const coutsRap = coutsDetail(sc);\n  const coutsRapBase = base ? coutsDetail(base) : null;\n  const refRap = coutsRap.multiPoste ? coutsRap.total : cost;\n  const refRapBase = coutsRap.multiPoste ? (coutsRapBase ? coutsRapBase.total : null) : baseCost;\n  const annuelRap = bilanAnnuel(sc);\n  let deltaTxt = \"r\u00e9f\u00e9rence\";\n  if(!sc.baseline && refRapBase !== null && refRap !== null){\n    const d = ((refRap - refRapBase) / refRapBase) * 100;\n    deltaTxt = (d > 0 ? \"+\" : \"\") + fmt(d,1) + \" % vs \" + escapeAttr(base.name);\n  }\n  const essaisRows = (sc.essais || []).map(es => {\n    const est = essaiStats(sc, es);\n    const statutTxt = est.status === \"ok\" ? \"Conforme\" : est.status === \"bad\" ? \"Non conforme\" : \"En cours\";\n    return `<tr>\n      <td>${escapeAttr(es.titre)}</td><td>${es.date || \"\u2014\"}</td><td>${es.equipe || \"\u2014\"}</td>\n      <td>${escapeAttr(es.operateur) || \"\u2014\"}</td>\n      <td style=\"text-align:right;\">${es.maturiteBruts === \"\" || es.maturiteBruts == null ? \"\u2014\" : es.maturiteBruts}</td>\n      <td style=\"text-align:right;\">${est.lastPiece ?? 0} / ${est.targetCharniere ?? \"\u2014\"}</td>\n      <td style=\"text-align:right;\">${est.tauxHorsTol === null ? \"\u2014\" : fmt(est.tauxHorsTol,0) + \" %\"}</td>\n      <td>${statutTxt}</td>\n    </tr>`;\n  }).join(\"\") || `<tr><td colspan=\"8\" style=\"text-align:center; color:#5a6470;\">Aucun essai enregistr\u00e9</td></tr>`;\n\n  return `<!doctype html>\n<html lang=\"fr\"><head><meta charset=\"utf-8\">\n<title>Rapport de validation \u2014 ${escapeAttr(sc.name)}</title>\n<style>\n  body{font-family:Arial,'IBM Plex Sans',sans-serif; color:#1c211e; max-width:900px; margin:32px auto; padding:0 20px; line-height:1.5;}\n  h1{font-size:26px; border-bottom:3px solid #1B5EA6; padding-bottom:10px; margin-bottom:6px;}\n  h2{font-size:13px; text-transform:uppercase; letter-spacing:.03em; color:#154d8a; margin-top:28px;}\n  table{border-collapse:collapse; width:100%; margin-top:8px;}\n  th,td{border-bottom:1px solid #d8dad3; padding:6px 10px; font-size:13px; text-align:left;}\n  th{background:#eaece7; font-size:10.5px; text-transform:uppercase;}\n  .verdict{display:inline-block; font-weight:700; font-size:20px; padding:8px 18px; border-radius:4px; margin:10px 0;}\n  .verdict.ok{background:#eaf5ee; color:#1a7a3f;}\n  .verdict.bad{background:#fbe9ea; color:#b8001a;}\n  .verdict.pending{background:#fbf1e2; color:#a5620b;}\n  .kpi{display:flex; gap:20px; flex-wrap:wrap; margin-top:10px;}\n  .kpi div{background:#f2f3f0; border-radius:4px; padding:10px 16px;}\n  .kpi .l{font-size:10px; text-transform:uppercase; color:#7c837c;}\n  .kpi .v{font-family:Consolas,monospace; font-size:20px; font-weight:500;}\n  footer{margin-top:36px; padding-top:12px; border-top:1px solid #d8dad3; font-size:11px; color:#7c837c;}\n</style><style>\n  /* v4.30 \u2014 vue de synth\u00e8se comparative : regroupement + meilleure valeur en \u00e9vidence */\n  table.synthese.syn2 { min-width:760px; }\n  table.synthese.syn2 td.val { font-weight:500; }\n  table.synthese.syn2 tr.syn2-grp td {\n    background:var(--gray-50); color:var(--blue-dark); text-align:left; white-space:normal;\n    font-family:var(--font-body); font-size:10.5px; font-weight:700; letter-spacing:.08em;\n    text-transform:uppercase; padding:6px 10px;\n  }\n  table.synthese.syn2 td.syn2-best { background:var(--gray-50); color:var(--green); }\n  table.synthese.syn2 td.syn2-worst { background:var(--gray-50); color:var(--red); }\n  table.synthese.syn2 th .sc-name { display:block; }\n  table.synthese.syn2 th .syn2-wins {\n    display:block; margin-top:3px; font-family:var(--font-body); font-size:9.5px; font-weight:500;\n    letter-spacing:.02em; text-transform:none; color:var(--ink-faint);\n  }\n  table.synthese.syn2 th.is-lead { box-shadow:inset 0 -3px 0 var(--red); }\n  table.synthese.syn2 th.is-lead .syn2-wins { color:var(--blue-dark); }\n  .syn2-legende { display:flex; gap:16px; flex-wrap:wrap; margin-top:10px; font-size:11.5px; color:var(--ink-soft); }\n  .syn2-legende span { display:inline-flex; align-items:center; gap:6px; }\n  .syn2-legende i { width:12px; height:12px; border-radius:3px; display:inline-block; flex:none; }\n  .syn2-legende .sw-best { background:var(--gray-50); border:1px solid rgba(18,101,58,.35); }\n  .syn2-legende .sw-worst { background:var(--gray-50); border:1px solid rgba(197,0,24,.3); }\n  .syn2-legende .sw-grp { background:var(--gray-50); border:1px solid rgba(13,71,161,.35); }\n\n  /* cascade du gain */\n  .syn2-wf-sub { margin:0 0 14px; font-size:12.5px; color:var(--ink-soft); }\n  .syn2-wf { display:flex; align-items:flex-end; gap:8px; min-height:180px; padding:8px 2px 0; border-bottom:2px solid var(--border); }\n  .syn2-wf-col { flex:1; min-width:0; display:flex; flex-direction:column; justify-content:flex-end; height:100%; }\n  .syn2-wf-bar { border-radius:var(--radius-sm) var(--radius-sm) 0 0; display:flex; align-items:flex-start; justify-content:center;\n                 padding-top:5px; font-family:var(--font-mono); font-size:11.5px; font-weight:500; color:var(--on-accent); overflow:hidden; }\n  .syn2-wf-bar.ref { background:var(--ink-soft); }\n  .syn2-wf-bar.save { background:var(--green); }\n  .syn2-wf-bar.up { background:var(--red); }\n  .syn2-wf-bar.tot { background:var(--blue); }\n  .syn2-wf-lab { margin-top:7px; font-size:11px; color:var(--ink-soft); text-align:center; line-height:1.25; }\n  .syn2-wf-foot { display:flex; gap:12px; flex-wrap:wrap; margin-top:14px; }\n  .syn2-wf-card { border:1px solid var(--border); border-left:4px solid var(--green); border-radius:var(--radius);\n                  background:var(--gray-50); padding:11px 14px; min-width:210px; }\n  .syn2-wf-card.piece { border-left-color:var(--blue); background:var(--gray-50); }\n  .syn2-wf-card .b { font-family:var(--font-disp); font-weight:800; font-size:24px; line-height:1.05; color:var(--green); }\n  .syn2-wf-card.piece .b { color:var(--blue-dark); }\n  .syn2-wf-card .l { font-size:11.5px; color:var(--ink-soft); margin-top:3px; }\n  @media print { .syn2-wf { border-bottom-color:#999; } .syn2-wf-card { background:#fff; } }\n</style>\n\n<style>\n/* \u2500\u2500 v4.53 \u2014 livraisons : le dossier hi\u00e9rarchie (bloc carte + impression A4) \u2500\u2500 */\n.lv-bloc{ margin-top:16px; border-top:2px solid var(--border); padding-top:12px; }\n.lv-tete{ display:flex; align-items:center; gap:12px; flex-wrap:wrap; margin-bottom:8px; }\n.lv-tete b{ font-family:var(--font-disp); font-weight:700; font-size:14px; }\n.lv-row{ display:flex; align-items:center; gap:10px; flex-wrap:wrap; padding:6px 2px; border-bottom:1px solid var(--border); font-size:12.5px; }\n.lv-nom{ font-family:var(--font-disp); font-weight:700; color:var(--ink); flex:0 0 auto; }\n.lv-date{ font-family:var(--font-mono); font-size:10.5px; color:var(--ink-faint); }\n.lv-gains{ margin-left:auto; font-family:var(--font-mono); font-size:10.5px; color:var(--green); }\n#livraisonImpression{ display:none; }\nbody.print-livraison > *{ display:none !important; }\nbody.print-livraison > #livraisonImpression{ display:block !important; }\nbody.print-livraison #livraisonImpression .m4{ font-family:'Public Sans',Arial,sans-serif; color:#111; }\nbody.print-livraison #livraisonImpression .m4-entete{ display:flex; justify-content:space-between; border-bottom:3px solid #1B5EA6; padding-bottom:8px; margin-bottom:14px; }\nbody.print-livraison #livraisonImpression .m4-sur{ font-family:'IBM Plex Mono',monospace; font-size:11px; letter-spacing:.08em; text-transform:uppercase; color:#1B5EA6; font-weight:500; }\nbody.print-livraison #livraisonImpression .m4-titre2{ font-size:12px; color:#333; margin-top:4px; }\nbody.print-livraison #livraisonImpression .m4-date2{ font-family:'IBM Plex Mono',monospace; font-size:10px; color:#555; }\nbody.print-livraison #livraisonImpression .m4-blocs{ display:flex; gap:12px; margin:14px 0; }\nbody.print-livraison #livraisonImpression .m4-bloc{ flex:1; border-radius:6px; padding:10px 14px; border:2px solid #1a7a3f; background:#edf7f1; }\nbody.print-livraison #livraisonImpression .m4-bloc.encours{ border-color:#b45309; background:#fdf6ec; }\nbody.print-livraison #livraisonImpression .m4-bloc .n{ font-family:'Manrope','Open Sans',Arial,sans-serif; font-weight:700; font-size:22px; }\nbody.print-livraison #livraisonImpression .m4-bloc .l{ font-size:10.5px; color:#444; text-transform:uppercase; }\nbody.print-livraison #livraisonImpression .m4-h{ font-family:'IBM Plex Mono',monospace; font-size:10px; letter-spacing:.1em; text-transform:uppercase; color:#555; margin:14px 0 6px; }\nbody.print-livraison #livraisonImpression .m4-row{ display:flex; gap:10px; font-size:11.5px; padding:4px 0; border-bottom:1px solid #eee; }\nbody.print-livraison #livraisonImpression .m4-date{ font-family:'IBM Plex Mono',monospace; min-width:80px; color:#555; }\nbody.print-livraison #livraisonImpression .m4-titre{ flex:1; color:#222; }\nbody.print-livraison #livraisonImpression .m4-stat{ font-family:'IBM Plex Mono',monospace; font-size:10px; color:#1a7a3f; }\nbody.print-livraison #livraisonImpression .m4-proto{ font-size:10.5px; color:#555; margin-top:12px; border-top:1px solid #ccc; padding-top:8px; }\n</style>\n</head><body>\n  <p style=\"font-family:Consolas,monospace; font-size:11px; letter-spacing:.1em; text-transform:uppercase; color:#1B5EA6;\">${escapeAttr([ligneActive && ligneActive.nom, refActive && refActive.nom, opActive && opActive.nom].filter(Boolean).join(\" \u2014 \"))} \u2014 Rapport de validation</p>\n  <h1>${escapeAttr(sc.name)}${sc.baseline ? \" \u2014 R\u00e9f\u00e9rence\" : \"\"}</h1>\n  <p style=\"color:#4b524c;\">${new Date().toLocaleDateString(\"fr-FR\")}</p>\n\n  <div class=\"verdict ${concl.classe}\">${concl.label}</div>\n  <p>${concl.detail}</p>\n\n  <h2>Param\u00e8tres de coupe</h2>\n  <table>\n    <tr><th>N\u00b0 outil</th><th>Correcteur</th><th>Type d'outil</th><th>Logement</th><th>R\u00e9f\u00e9rence plaquette</th><th>Vc (m/min)</th><th>f (mm/rev)</th><th>Charni\u00e8re (p/ar\u00eate)</th></tr>\n    ${sc.outils.flatMap(o => o.logements.map(l =>\n      `<tr><td>${escapeAttr(o.numero)}</td><td>${escapeAttr(o.correcteur) || \"\u2014\"}</td><td>${escapeAttr(o.description) || \"\u2014\"}</td><td>${escapeAttr(l.nom)}</td><td>${escapeAttr(l.ref)}</td><td>${l.vc || \"\u2014\"}</td><td>${l.f || \"\u2014\"}</td><td>${l.charniere || \"\u2014\"}</td></tr>`\n    )).join(\"\") || `<tr><td colspan=\"8\" style=\"text-align:center; color:#5a6470;\">Aucun outil configur\u00e9</td></tr>`}\n  </table>\n\n  <h2>Essais</h2>\n  <table>\n    <tr><th>Essai</th><th>Date</th><th>\u00c9quipe</th><th>Op\u00e9rateur</th><th>Maturit\u00e9 bruts (j)</th><th>Pi\u00e8ces / charni\u00e8re</th><th>% hors tol.</th><th>Statut</th></tr>\n    ${essaisRows}\n  </table>\n  <p style=\"font-size:12px; color:#4b524c;\">Crit\u00e8re de passage en s\u00e9rie : <b>${sc.validationThreshold || \"\u2014\"} essais conformes</b>${parseFloat(sc.validationThreshold) === 5 ? \" \u2014 protocole du site (sept. 2026) : un essai concluant est r\u00e9p\u00e9t\u00e9 5\u00d7, et la viabilit\u00e9 \u00e9conomique est v\u00e9rifi\u00e9e avant le passage en production\" : \"\"}. Acquis \u00e0 ce jour : <b>${stats.validCount}</b>.</p>\n\n  <h2>D\u00e9tail des pr\u00e9l\u00e8vements</h2>\n  ${(sc.essais || []).map(es => prelevementsDetailHTML(sc, es)).join(\"\") || `<p style=\"color:#5a6470;\">Aucun pr\u00e9l\u00e8vement enregistr\u00e9</p>`}\n\n  <h2>R\u00e9sum\u00e9 \u00e9conomique</h2>\n  <div class=\"kpi\">\n    <div><div class=\"l\">${coutsRap.multiPoste ? \"Co\u00fbt total / pi\u00e8ce\" : \"Co\u00fbt outil / pi\u00e8ce\"}</div><div class=\"v\">${refRap === null ? \"\u2014\" : fmt(refRap,4) + \" \u20ac\"}</div><div style=\"font-size:11px; color:#7c837c;\">${deltaTxt}</div></div>\n    ${coutsRap.multiPoste ? `<div><div class=\"l\">Dont plaquettes / temps machine</div><div class=\"v\" style=\"font-size:14px;\">${coutsRap.plaquettes === null ? \"\u2014\" : fmt(coutsRap.plaquettes,4)} \u20ac / ${coutsRap.machine === null ? \"\u2014\" : fmt(coutsRap.machine,4)} \u20ac</div></div>` : \"\"}\n    ${annuelRap && annuelRap.gainAnnuel !== undefined ? `<div><div class=\"l\">${annuelRap.gainAnnuel >= 0 ? \"Gain annuel\" : \"Perte annuelle\"}</div><div class=\"v\" style=\"color:${annuelRap.gainAnnuel >= 0 ? \"#1a7a3f\" : \"#b8001a\"};\">${(annuelRap.gainAnnuel>=0?\"+\":\"\u2212\") + fmtEuroCourt(Math.abs(annuelRap.gainAnnuel))}</div><div style=\"font-size:11px; color:#7c837c;\">sur ${fmt(annuelRap.volume,0)} disques/an</div></div>` : \"\"}\n    <div><div class=\"l\">Temps de cycle (indice 100)</div><div class=\"v\">${sc.cycle === \"\" || sc.cycle == null ? \"\u2014\" : fmt(parseFloat(sc.cycle),0)}</div></div>\n    <div><div class=\"l\">Taux de rebut ligne</div><div class=\"v\">${scrap.rate === null ? \"\u2014\" : fmt(scrap.rate,1) + \" %\"}</div></div>\n    <div><div class=\"l\">Essais conformes</div><div class=\"v\">${stats.validCount} / ${sc.validationThreshold || \"\u2014\"}</div></div>\n  </div>\n\n  <footer>\n    Rapport g\u00e9n\u00e9r\u00e9 automatiquement par l'outil de suivi SPK OP10 (bilan_economique.html) \u2014 ${new Date().toLocaleString(\"fr-FR\")}. Document 100% local, aucune donn\u00e9e transmise.<br>\n    Site Stellantis Sept Fons \u2014 Interlocuteurs Stellantis : Matis Hernu, Arthur Alves \u2014 Interlocuteur CeramTec : Benjamin Rouquette<br>\n    <b style=\"color:#b8001a;\">CONFIDENTIEL</b> \u2014 document interne au projet, ne pas diffuser hors de l'\u00e9quipe projet\n  </footer>\n</body></html>`;\n}\n\nfunction telechargerRapport(sc){\n  const html = rapportValidationHTML(sc);\n  const blob = new Blob([html], {type:\"text/html;charset=utf-8\"});\n  const url = URL.createObjectURL(blob);\n  const a = document.createElement(\"a\");\n  const d = new Date();\n  const stamp = d.getFullYear() + String(d.getMonth()+1).padStart(2,\"0\") + String(d.getDate()).padStart(2,\"0\");\n  a.href = url;\n  a.download = \"Rapport_\" + sc.name.replace(/[^a-z0-9]+/gi,\"_\") + \"_\" + stamp + \".html\";\n  document.body.appendChild(a); a.click(); document.body.removeChild(a);\n  setTimeout(() => URL.revokeObjectURL(url), 2000);\n}\n\n/* rapport HTML autonome d'UN essai (pas tout le scenario) : interlocuteurs, but de\n   l'essai, plaquettes utilisees (avec leur reference, figee au moment de l'essai quand\n   disponible), conditions de coupe, prelevements, observations. Mise en page reprend les\n   tokens du design system SPK (Archivo/IBM Plex Mono, bleu/rouge de la charte). */\nfunction essaiRapportHTML(sc, essai, photosRap){\n  const ligneActive = getActiveLigne(), refActive = getActiveReference(), opActive = getActiveOp();\n  const chemin = [ligneActive && ligneActive.nom, refActive && refActive.nom, opActive && opActive.nom].filter(Boolean).join(\" \u2014 \");\n  const est = essaiStats(sc, essai);\n  const badgeClass = est.status === \"ok\" ? \"ok\" : est.status === \"bad\" ? \"bad\" : est.status === \"arrete\" ? \"arrete\" : \"pending\";\n  const badgeLabel = est.status === \"ok\" ? \"Conforme\" : est.status === \"bad\" ? \"Non conforme\" : est.status === \"arrete\" ? est.raison : \"En cours\";\n  const snap = logementsSuivis(essai);\n  const dateAff = essai.date ? new Date(essai.date + \"T00:00\").toLocaleDateString(\"fr-FR\") : \"\u2014\";\n  const logoSrc = (document.querySelector(\".hd-left img\") || {}).getAttribute ? document.querySelector(\".hd-left img\").getAttribute(\"src\") : \"\";\n\n  const plaquettesRows = snap.map(lp => {\n    const nom = nomLogementActuel(sc, lp); // v4.22 : nom actuel du scenario\n    const outilLive = sc.outils.find(o => o.id === lp.outilId);\n    return `\n    <tr>\n      <td>${escapeAttr(nom.outilNumero)}</td>\n      <td>${escapeAttr(outilLive && outilLive.correcteur) || \"\u2014\"}</td>\n      <td>${escapeAttr(outilLive && outilLive.description) || \"\u2014\"}</td>\n      <td>${escapeAttr(nom.logementNom)}</td>\n      <td>${escapeAttr(refLogementEssai(sc, lp)) || \"\u2014\"}</td>\n      <td>${lp.vc === \"\" || lp.vc == null ? \"\u2014\" : lp.vc}</td>\n      <td>${lp.f === \"\" || lp.f == null ? \"\u2014\" : lp.f}</td>\n      <td>${lp.charniere === \"\" || lp.charniere == null ? \"\u2014\" : lp.charniere}</td>\n    </tr>`;\n  }).join(\"\") || `<tr><td colspan=\"8\" style=\"text-align:center; color:#5a6470;\">Aucun outil configur\u00e9</td></tr>`;\n\n  const mesureLabel = escapeAttr(libelleDe(sc));\n  const showLogementCol = snap.length > 1;\n  const csupCols = csupColonnes(sc);\n  const cotesRap = battCotesDe(sc);\n  const prelRows = (essai.prelevements || []).slice()\n    .sort((a,b) => (parseFloat(a.piece)||0) - (parseFloat(b.piece)||0))\n    .map(r => {\n      const exempte = !toleranceRequisePour(sc, r);\n      const conform = checkConform(sc, r);\n      const statut = exempte ? \"Charni\u00e8re seule\" : conform === null ? \"\u2014\" : conform ? \"OK\" : (raisonNonConforme(sc, r) || \"Hors tol\u00e9rance\");\n      const lp = snap.find(l => l.logementId === r.logementId);\n      const logementTxt = lp ? (() => { const n = nomLogementActuel(sc, lp); return (String(n.outilNumero||\"?\") + \" \u00b7 \" + String(n.logementNom||\"\")).trim(); })() : \"\u2014\";\n      const valeur = sc.battActif === false ? \"\u2014\"\n        : cotesRap === \"mono\" ? fmtBatt(r.batt)\n        : cotesRap === \"D\" ? (\"Droite \" + fmtBatt(r.battD))\n        : cotesRap === \"G\" ? (\"Gauche \" + fmtBatt(r.battG))\n        : (\"Droite \" + fmtBatt(r.battD) + \" / Gauche \" + fmtBatt(r.battG));\n      return `<tr>\n        <td>${escapeAttr(r.piece)}</td>\n        ${showLogementCol ? `<td>${escapeAttr(logementTxt)}</td>` : \"\"}\n        <td>${escapeAttr(r.pointMesure) || \"\u2014\"}</td>\n        <td>${valeur}</td>\n        ${csupCols.map(col => {\n          const v = ((r.valeurs || {})[col.c.id] || {})[col.ax];\n          return `<td>${v === \"\" || v == null ? \"\u2014\" : v}</td>`;\n        }).join(\"\")}\n        <td>${USURE_LABELS[r.usure] || \"\u2014\"}</td>\n        <td>${statut}</td>\n      </tr>`;\n    }).join(\"\");\n  const csupHeadsRap = csupCols.map(col => `<th>${escapeAttr(col.c.label || \"crit\u00e8re\")}${col.ax !== \"v\" ? \" \" + (AXE_LABELS[col.ax] || col.ax) : \"\"}</th>`).join(\"\");\n\n  /* v4.12 \u2014 section Marposs du rapport : UNE sous-section par extraction (par journ\u00e9e)\n     si l'essai a coch\u00e9 l'option. Palette en dur : le rapport est un fichier autonome\n     sans les variables CSS de l'outil. */\n  const mRaps = (essai.marpossListe || []).filter(ex => (ex.releves||[]).length);\n  const marpossRapportBloc = (essai.marpossRapport && mRaps.length) ? `\n    <h2>Suivi Marposs ${mRaps.length > 1 ? \"\u2014 \" + mRaps.length + \" journ\u00e9es\" : \"\u2014 production du jour\"}</h2>\n    ${mRaps.map((ex, i) => {\n      const st = marpossStats(ex);\n      return `\n      ${mRaps.length > 1 ? `<h3 style=\"font-size:12.5px; margin:14px 0 6px; color:#154d8a; text-transform:uppercase; letter-spacing:.03em;\">Extraction ${i+1}${ex.jour ? \" \u2014 \" + escapeAttr(ex.jour) : \"\"}</h3>` : \"\"}\n      <div class=\"grid\">\n        <div><div class=\"l\">D\u00e9but de l'essai</div><div class=\"v\">${escapeAttr(ex.debut) || \"\u2014\"}</div></div>\n        <div><div class=\"l\">Fin de l'essai</div><div class=\"v\">${escapeAttr(ex.fin) || \"\u2014\"}</div></div>\n        <div><div class=\"l\">Relev\u00e9s du jour</div><div class=\"v\">${ex.releves.length}</div></div>\n        <div><div class=\"l\">Moyenne pendant l'essai</div><div class=\"v\">${st.moyenneEssai === null ? \"\u2014\" : fmt(st.moyenneEssai,3)} <span style=\"color:var(--ink-faint);\">(${st.nbEssai} pi\u00e8ce(s))</span></div></div>\n        <div><div class=\"l\">Moyenne journ\u00e9e</div><div class=\"v\">${st.moyenneJour === null ? \"\u2014\" : fmt(st.moyenneJour,3)}</div></div>\n      </div>\n      ${marpossChartSVG(sc, ex, { blue:\"#1B5EA6\", red:\"#E2001A\", teal:\"#0b6e63\", faint:\"#5a6470\" })}`;\n    }).join(\"\")}\n    <p style=\"font-size:10.5px; color:var(--ink-faint); margin-top:2px;\">Chaque point : un disque contr\u00f4l\u00e9 par la Marposs au fil de la journ\u00e9e. Bande bleue : plage de l'essai. Ligne rouge : tol\u00e9rance d'essai.</p>\n  ` : \"\";\n\n  return `<!doctype html>\n<html lang=\"fr\"><head><meta charset=\"utf-8\">\n<title>Rapport d'essai \u2014 ${escapeAttr(essai.titre)} \u2014 ${escapeAttr(sc.name)}</title>\n<!-- Aucune ressource externe : ce rapport part chez le client et son pied de page affirme\n     \"Document 100% local, aucune donnee transmise\". Il ne peut donc pas appeler Google Fonts\n     en s'ouvrant. Les piles de polices retombent sur Arial / Consolas, presentes partout. -->\n<style>\n  :root{\n    --blue:#1B5EA6; --blue-dark:#154d8a; --blue-bg:#e8f0fb;\n    --green:#1a7a3f; --green-bg:#edf7f1;\n    --amber:#b45309; --amber-bg:#fff8ed;\n    --red:#E2001A; --red-bg:#fce8ea;\n    --ink:#1a1a1a; --ink-soft:#4a5560; --ink-faint:#5a6470;\n    --border:#e5e5e5; --surface-alt:#f4f4f4;\n  }\n  *{box-sizing:border-box;}\n  body{font-family:'Open Sans',Arial,sans-serif; color:var(--ink); max-width:860px; margin:36px auto; padding:0 24px 60px; line-height:1.5; font-size:14px;}\n  .hd{display:flex; align-items:center; gap:18px; border-bottom:4px solid var(--blue); padding-bottom:16px; margin-bottom:20px;}\n  .hd img{height:44px; width:auto; flex-shrink:0;}\n  .hd-eyebrow{font-family:'IBM Plex Mono',Consolas,monospace; font-size:10.5px; letter-spacing:.14em; text-transform:uppercase; color:var(--blue); font-weight:500; margin:0 0 5px; display:flex; align-items:center; gap:9px;}\n  .hd-eyebrow::before{content:\"\"; width:20px; height:3px; border-radius:2px; background:var(--red); flex-shrink:0;}\n  h1{font-family:'Archivo',Arial,sans-serif; font-weight:800; font-size:26px; margin:0; letter-spacing:-.02em; line-height:1.1;}\n  .hd-meta{font-family:'IBM Plex Mono',Consolas,monospace; font-size:11px; color:var(--ink-soft); margin-left:auto; text-align:right; line-height:1.8; white-space:nowrap;}\n  .verdict{display:inline-flex; align-items:center; gap:8px; font-family:'IBM Plex Mono',Consolas,monospace; font-weight:500; font-size:11.5px; letter-spacing:.05em; text-transform:uppercase; padding:7px 16px; border-radius:999px; margin-bottom:22px;}\n  .verdict.ok{background:var(--gray-50); color:var(--green);}\n  .verdict.bad{background:var(--gray-50); color:var(--red);}\n  .verdict.pending{background:var(--gray-50); color:var(--amber);}\n  .verdict.arrete{background:#e4e7eb; color:var(--ink-soft);}\n  h2{font-family:'IBM Plex Mono',Consolas,monospace; font-size:11px; text-transform:uppercase; letter-spacing:.1em; color:var(--ink-faint); margin:26px 0 10px; padding-bottom:6px; border-bottom:1px solid var(--border);}\n  .grid{display:grid; grid-template-columns:repeat(auto-fit,minmax(190px,1fr)); gap:16px 24px;}\n  .grid .l{font-family:'IBM Plex Mono',Consolas,monospace; font-size:9.5px; letter-spacing:.08em; text-transform:uppercase; color:var(--ink-faint); margin-bottom:3px;}\n  .grid .v{font-size:14px; color:var(--ink); font-weight:500;}\n  .but-box{background:var(--gray-50); border-left:4px solid var(--blue); border-radius:0 8px 8px 0; padding:14px 18px; font-size:14px; color:var(--ink);}\n  .obs-box{background:var(--gray-50); border-left:4px solid var(--amber); border-radius:0 8px 8px 0; padding:14px 18px; font-size:13.5px; color:var(--ink); font-style:italic;}\n  table{border-collapse:collapse; width:100%; margin-top:6px;}\n  th,td{border-bottom:1px solid var(--border); padding:7px 10px; font-size:12.5px; text-align:left;}\n  td{font-family:'IBM Plex Mono',Consolas,monospace;}\n  th{font-family:'IBM Plex Mono',Consolas,monospace; font-size:10px; letter-spacing:.07em; text-transform:uppercase; color:var(--ink-faint); background:var(--surface-alt); font-weight:500;}\n  .chart-block{margin:18px 0;}\n  .chart-svg{width:100%; height:auto;}\n  .chart-legend{display:flex; gap:14px; flex-wrap:wrap; font-size:11px; color:var(--ink-soft); margin-top:8px; align-items:center;}\n  .chart-legend .tol{display:inline-block; width:20px; border-top:2px dashed var(--red); vertical-align:middle;}\n  .photos-rap{display:grid; grid-template-columns:repeat(auto-fit,minmax(250px,1fr)); gap:16px; margin-top:8px;}\n  .photos-rap .ph{margin:0; break-inside:avoid;}\n  .photos-rap .ph img{width:100%; height:auto; border:1px solid var(--border); border-radius:8px; display:block; background:#fff;}\n  .photos-rap figcaption{font-family:'IBM Plex Mono',Consolas,monospace; font-size:10.5px; color:var(--ink-soft); margin-top:5px; line-height:1.5;}\n  .photos-rap .ph-absente{border:1px dashed var(--border); border-radius:8px; padding:26px 14px; text-align:center; font-family:'IBM Plex Mono',Consolas,monospace; font-size:10.5px; color:var(--ink-faint);}\n  footer{margin-top:40px; padding-top:14px; border-top:1px solid var(--border); font-family:'IBM Plex Mono',Consolas,monospace; font-size:10.5px; color:var(--ink-faint); line-height:1.8;}\n  footer b{color:var(--red);}\n</style></head><body>\n\n  <div class=\"hd\">\n    ${logoSrc ? `<img src=\"${logoSrc}\" alt=\"SPK by CeramTec\">` : \"\"}\n    <div>\n      <p class=\"hd-eyebrow\">${escapeAttr(chemin)} \u2014 Rapport d'essai</p>\n      <h1>${escapeAttr(essai.titre || \"Essai\")}</h1>\n    </div>\n    <div class=\"hd-meta\">${escapeAttr(sc.name)}<br>${dateAff}</div>\n  </div>\n\n  <span class=\"verdict ${badgeClass}\">${badgeLabel}${est.raison && est.status !== \"arrete\" ? \" \u2014 \" + escapeAttr(est.raison) : \"\"}</span>\n\n  <h2>Interlocuteurs</h2>\n  <div class=\"grid\">\n    <div><div class=\"l\">Site</div><div class=\"v\">Stellantis Sept Fons</div></div>\n    <div><div class=\"l\">Interlocuteurs Stellantis</div><div class=\"v\">Matis Hernu \u00b7 Arthur Alves</div></div>\n    <div><div class=\"l\">Interlocuteur CeramTec</div><div class=\"v\">Benjamin Rouquette</div></div>\n  </div>\n\n  ${essai.but ? `<h2>But de l'essai</h2><div class=\"but-box\">${escapeAttr(essai.but)}</div>` : \"\"}\n\n  <h2>Informations essai</h2>\n  <div class=\"grid\">\n    <div><div class=\"l\">Date</div><div class=\"v\">${dateAff}${(essai.heureDebut || essai.heureFin) ? \" \u00b7 \" + (essai.heureDebut || \"\u2014\") + \" \u2192 \" + (essai.heureFin || \"\u2014\") : \"\"}${essai.dateFin ? \" \u2192 \" + new Date(essai.dateFin + \"T00:00\").toLocaleDateString(\"fr-FR\") + (essai.heureFin ? \" \u00e0 \" + essai.heureFin : \"\") : \"\"}</div></div>\n    <div><div class=\"l\">\u00c9quipe</div><div class=\"v\">${escapeAttr(essai.equipe) || \"\u2014\"}</div></div>\n    <div><div class=\"l\">Op\u00e9rateur</div><div class=\"v\">${escapeAttr(essai.operateur) || \"\u2014\"}</div></div>\n    <div><div class=\"l\">R\u00e9dig\u00e9 par</div><div class=\"v\">${escapeAttr(essai.redigePar) || \"\u2014\"}</div></div>\n    <div><div class=\"l\">Maturit\u00e9 des bruts</div><div class=\"v\">${essai.maturiteBruts === \"\" || essai.maturiteBruts == null ? \"\u2014\" : essai.maturiteBruts + \" jour(s)\"}</div></div>\n    ${sc.emag1\n      ? `<div><div class=\"l\">Programme</div><div class=\"v\">Gauche : ${escapeAttr(essai.programmeGauche) || \"\u2014\"} \u00b7 Droit : ${escapeAttr(essai.programmeDroit) || \"\u2014\"}</div></div>`\n      : (essai.programme ? `<div><div class=\"l\">Programme</div><div class=\"v\">${escapeAttr(essai.programme)}</div></div>` : \"\")}\n  </div>\n\n  <h2>Plaquettes utilis\u00e9es</h2>\n  <table>\n    <tr><th>N\u00b0 outil</th><th>Correcteur</th><th>Type d'outil</th><th>Logement</th><th>R\u00e9f\u00e9rence plaquette</th><th>Vc (m/min)</th><th>f (mm/rev)</th><th>Charni\u00e8re (p/ar\u00eate)</th></tr>\n    ${plaquettesRows}\n  </table>\n\n  <h2>Pr\u00e9l\u00e8vements \u2014 ${mesureLabel}${sc.battActif === false ? \" (battement non jug\u00e9)\" : \"\"}</h2>\n  <table>\n    <tr><th>N\u00b0 pi\u00e8ce</th>${showLogementCol ? \"<th>Logement</th>\" : \"\"}<th>Point de mesure</th><th>Valeur</th>${csupHeadsRap}<th>Usure</th><th>Statut</th></tr>\n    ${prelRows || `<tr><td colspan=\"${5 + (showLogementCol?1:0) + csupCols.length}\" style=\"text-align:center; color:#5a6470;\">Aucun pr\u00e9l\u00e8vement enregistr\u00e9</td></tr>`}\n  </table>\n  <p style=\"font-family:'IBM Plex Mono',Consolas,monospace; font-size:10.5px; color:var(--ink-faint); margin-top:4px;\">Tol\u00e9rance d'essai : ${escapeAttr(mesureLabel)} \u2264 ${fmt(parseFloat(limiteDe(sc)),3)} \u00b7 Spec usine (OP40, disque fini) : Battement \u2264 ${fmt(specsUsine.battement,3)} \u00b7 VE \u2264 ${fmt(specsUsine.ve,3)}</p>\n\n  ${essai.observations ? `<h2>Observations</h2><div class=\"obs-box\">${escapeAttr(essai.observations)}</div>` : \"\"}\n\n  ${photosRapportHTML(photosRap)}\n\n  ${marpossRapportBloc}\n\n  ${sc.tendanceRapport ? `<h2>Tendance \u2014 \u00e9volution des crit\u00e8res</h2>\n  ${groupesTendance(sc).filter(g => g.series.length).map(g => tendanceChartHTML(sc, g, {\n    border:\"#e5e5e5\", faint:\"#5a6470\", red:\"#E2001A\", blue:\"#1B5EA6\", surface:\"#ffffff\", soft:\"#4a5560\",\n    mono:\"'IBM Plex Mono',Consolas,monospace\"\n  })).join(\"\")}\n  <p style=\"font-size:10.5px; color:var(--ink-faint); margin-top:2px;\">Chaque point : un pr\u00e9l\u00e8vement mesur\u00e9 au fil des pi\u00e8ces. Ligne rouge : tol\u00e9rance du crit\u00e8re. Une couleur par axe mesur\u00e9 (Inter/Exter...) et par essai.</p>` : \"\"}\n\n  <footer>\n    Rapport d'essai g\u00e9n\u00e9r\u00e9 automatiquement par l'outil de suivi SPK OP10 (bilan_economique.html) \u2014 ${new Date().toLocaleString(\"fr-FR\")}. Document 100% local, aucune donn\u00e9e transmise.<br>\n    <b>CONFIDENTIEL</b> \u2014 document interne au projet, ne pas diffuser hors de l'\u00e9quipe projet\n  </footer>\n</body></html>`;\n}\n\nasync function telechargerRapportEssai(sc, essai){\n  try{\n    // v4.24 : les photos (aplaties + l\u00e9gend\u00e9es) partent avec le rapport \u2014 voir photosPourRapport\n    const photosRap = await photosPourRapport(essai);\n    const html = essaiRapportHTML(sc, essai, photosRap);\n    const blob = new Blob([html], {type:\"text/html;charset=utf-8\"});\n    const url = URL.createObjectURL(blob);\n    const a = document.createElement(\"a\");\n    const d = new Date();\n    const stamp = d.getFullYear() + String(d.getMonth()+1).padStart(2,\"0\") + String(d.getDate()).padStart(2,\"0\");\n    a.href = url;\n    a.download = \"Rapport_essai_\" + (sc.name + \"_\" + essai.titre).replace(/[^a-z0-9]+/gi,\"_\") + \"_\" + stamp + \".html\";\n    document.body.appendChild(a); a.click(); document.body.removeChild(a);\n    setTimeout(() => URL.revokeObjectURL(url), 2000);\n  }catch(e){\n    dialogueAlerte(\"La g\u00e9n\u00e9ration du rapport a \u00e9chou\u00e9 : \" + ((e && e.message) || e) + \"\\n\\nLe rapport sans photos reste disponible \u2014 r\u00e9essayez, ou v\u00e9rifiez la connexion au dossier/cloud photos.\", \"G\u00e9n\u00e9ration impossible\");\n  }\n}\n\n/* ============================================================================\n   FUSION DE DEUX FICHIERS (v3.16)\n   Jusqu'ici, importer remplacait tout l'arbre. A trois sur le meme suivi, ca impose de\n   travailler en serie : si deux personnes saisissent en parallele sur deux OP differents,\n   le fichier importe en dernier ecrase le travail de l'autre. Le compteur de revision\n   prevenait, il n'empechait rien.\n\n   Regle de fusion, volontairement simple et annoncee a l'utilisateur avant de valider :\n   - STRUCTURE (lignes, references, OP, scenarios, outils, logements, conditions de coupe,\n     options) : ce qui existe ici est conserve tel quel, ce qui n'existe que dans le fichier\n     recu est ajoute. Une fusion n'ecrase jamais un reglage local.\n   - ESSAIS : c'est le niveau ou le travail se repartit, donc le niveau ou on arbitre. Un\n     essai present des deux cotes est remplace en bloc par la version la plus recemment\n     modifiee (champ modifieLe). Jamais champ par champ : deux moities d'essais recollees\n     donneraient une mesure qui n'a jamais existe.\n   - CONFLIT : memes dates, ou date absente d'un cote (fichier anterieur a la v3.16). On\n     garde alors la version locale et on la signale nommement \u2014 a l'utilisateur de trancher\n     en regardant les deux fichiers.\n   ============================================================================ */\nfunction fusionnerLignes(locales, entrantes){\n  const bilan = { lignes:0, references:0, ops:0, scenarios:0,\n                  essaisAjoutes:0, essaisMaj:0, essaisConserves:0, conflits:[] };\n  /* v4.49.1 \u2014 comparaison CANONIQUE : l'ordre des cl\u00e9es ne doit pas compter.\n     Un aller-retour JSON (import/export) r\u00e9ordonne les cl\u00e9s sans toucher aux\n     valeurs : l'ancienne comparaison JSON.stringify brut d\u00e9clarait alors des\n     \u00ab conflits \u00bb sur des essais strictement identiques (5 faux positifs\n     constat\u00e9s le 28/09). */\n  const canon = (o) => {\n    if(Array.isArray(o)) return o.map(canon);\n    if(o && typeof o === \"object\"){\n      const triees = {}; Object.keys(o).sort().forEach(k => triees[k] = canon(o[k]));\n      return triees;\n    }\n    return o;\n  };\n  const memeContenu = (a,b) => { try{ return JSON.stringify(canon(a)) === JSON.stringify(canon(b)); }catch(e){ return false; } };\n\n  const fusionnerEssais = (scLocal, scEntrant, chemin) => {\n    scLocal.essais = scLocal.essais || [];\n    (scEntrant.essais || []).forEach(esE => {\n      const i = scLocal.essais.findIndex(x => x.id === esE.id);\n      if(i === -1){ scLocal.essais.push(esE); bilan.essaisAjoutes++; return; }\n      const esL = scLocal.essais[i];\n      if(memeContenu(esL, esE)) return;             // identiques : rien a faire\n      const dL = esL.modifieLe || \"\", dE = esE.modifieLe || \"\";\n      if(dL && dE && dE > dL){ scLocal.essais[i] = esE; bilan.essaisMaj++; }\n      else if(dL && dE && dL > dE){ bilan.essaisConserves++; }\n      else {\n        bilan.essaisConserves++;\n        bilan.conflits.push({ chemin, essai: (esL.titre || esL.id) + (esE.titre && esE.titre !== esL.titre ? \" (re\u00e7u sous le nom \u00ab \" + esE.titre + \" \u00bb)\" : \"\"),\n          raison: (!dL || !dE) ? \"date de modification absente d'un c\u00f4t\u00e9 (fichier ant\u00e9rieur \u00e0 la v3.16)\" : \"modifi\u00e9s \u00e0 la m\u00eame seconde\" });\n      }\n    });\n  };\n\n  (entrantes || []).forEach(ligneE => {\n    let ligneL = locales.find(l => l.id === ligneE.id);\n    if(!ligneL){ locales.push(ligneE); bilan.lignes++; return; }\n    (ligneE.references || []).forEach(refE => {\n      let refL = (ligneL.references = ligneL.references || []).find(r => r.id === refE.id);\n      if(!refL){ ligneL.references.push(refE); bilan.references++; return; }\n      (refE.ops || []).forEach(opE => {\n        let opL = (refL.ops = refL.ops || []).find(o => o.id === opE.id);\n        if(!opL){ refL.ops.push(opE); bilan.ops++; return; }\n        (opE.scenarios || []).forEach(scE => {\n          let scL = (opL.scenarios = opL.scenarios || []).find(x => x.id === scE.id);\n          if(!scL){ opL.scenarios.push(scE); bilan.scenarios++; return; }\n          fusionnerEssais(scL, scE, [ligneL.nom, refL.nom, opL.nom, scL.name].filter(Boolean).join(\" \u203a \"));\n        });\n      });\n    });\n  });\n  return bilan;\n}\n\n/* fusion du backlog : meme logique, un item est ajoute s'il est inconnu, sinon la version\n   locale est conservee (les statuts \u00ab Trait\u00e9 \u00bb se posent ici, on ne les ecrase pas) */\nfunction fusionnerBacklog(local, entrant){\n  let ajoutes = 0;\n  (entrant || []).forEach(itE => {\n    if(!local.find(x => x.id === itE.id)){ local.push(itE); ajoutes++; }\n  });\n  return ajoutes;\n}\n\n/* Fusion des projets-etiquettes (v4.1). Beaucoup plus simple que la fusion de la v4.0 :\n   un projet n'est qu'une liste d'identifiants, fusionner deux listes ne demande aucun\n   arbitrage essai-par-essai. Un projet inconnu arrive entier ; un projet connu recoit les\n   etiquettes qui lui manquent, sans jamais toucher a son nom, son pilote, son statut ou\n   son echeance -- exactement la meme regle que pour les outils et conditions de coupe. */\nfunction fusionnerProjetsTags(locaux, entrants){\n  let projetsAjoutes = 0, tagsAjoutes = 0;\n  (entrants || []).forEach(pjE => {\n    const pjL = locaux.find(x => x.id === pjE.id);\n    if(!pjL){ locaux.push(pjE); projetsAjoutes++; return; }\n    (pjE.tags || []).forEach(t => {\n      if(!pjL.tags.some(x => x.ligneId===t.ligneId && x.referenceId===t.referenceId && x.opId===t.opId && x.scenarioId===t.scenarioId)){\n        pjL.tags.push(t); tagsAjoutes++;\n      }\n    });\n  });\n  return { projetsAjoutes, tagsAjoutes };\n}\n\n/* Fusion des responsables (v4.2) : correspondance par id (meme personne exportee puis\n   reimportee) ou par nom (creee independamment sur deux postes) -- sinon deux \"Julien\" avec\n   des ids differents et des couleurs differentes coexisteraient sans raison. */\nfunction fusionnerResponsables(locaux, entrants){\n  let ajoutes = 0;\n  (entrants || []).forEach(rE => {\n    if(!locaux.some(x => x.id === rE.id || x.nom === rE.nom)){ locaux.push(rE); ajoutes++; }\n  });\n  return ajoutes;\n}\n\nfunction bilanFusionHTML(b){\n  const struct = [\n    b.lignes && b.lignes + \" ligne\" + (b.lignes>1?\"s\":\"\"),\n    b.references && b.references + \" r\u00e9f\u00e9rence\" + (b.references>1?\"s\":\"\"),\n    b.ops && b.ops + \" OP\",\n    b.scenarios && b.scenarios + \" sc\u00e9nario\" + (b.scenarios>1?\"s\":\"\")\n  ].filter(Boolean).join(\", \");\n  const lignes = [\n    `<li><b>${b.essaisAjoutes}</b> essai${b.essaisAjoutes>1?\"s\":\"\"} ajout\u00e9${b.essaisAjoutes>1?\"s\":\"\"}</li>`,\n    `<li><b>${b.essaisMaj}</b> essai${b.essaisMaj>1?\"s\":\"\"} mis \u00e0 jour <span class=\"fusion-note\">(la version re\u00e7ue \u00e9tait la plus r\u00e9cente)</span></li>`,\n    `<li><b>${b.essaisConserves}</b> essai${b.essaisConserves>1?\"s\":\"\"} conserv\u00e9${b.essaisConserves>1?\"s\":\"\"} <span class=\"fusion-note\">(votre version \u00e9tait la plus r\u00e9cente, ou conflit ci-dessous)</span></li>`,\n    struct ? `<li>Structure ajout\u00e9e : ${struct}</li>` : \"\",\n    b.projetsAjoutes ? `<li><b>${b.projetsAjoutes}</b> projet${b.projetsAjoutes>1?\"s\":\"\"} ajout\u00e9${b.projetsAjoutes>1?\"s\":\"\"}</li>` : \"\",\n    b.tagsAjoutes ? `<li><b>${b.tagsAjoutes}</b> sc\u00e9nario${b.tagsAjoutes>1?\"s\":\"\"} rattach\u00e9${b.tagsAjoutes>1?\"s\":\"\"} \u00e0 un projet existant</li>` : \"\",\n    b.responsablesAjoutes ? `<li><b>${b.responsablesAjoutes}</b> responsable${b.responsablesAjoutes>1?\"s\":\"\"} ajout\u00e9${b.responsablesAjoutes>1?\"s\":\"\"}</li>` : \"\"\n  ].filter(Boolean).join(\"\");\n  const conflits = b.conflits.length ? `\n    <p class=\"fusion-conflit-titre\">${b.conflits.length} conflit${b.conflits.length>1?\"s\":\"\"} \u2014 votre version a \u00e9t\u00e9 conserv\u00e9e, \u00e0 v\u00e9rifier :</p>\n    <ul class=\"fusion-conflits\">${b.conflits.map(c =>\n      `<li><b>${escapeAttr(c.essai)}</b> <span class=\"fusion-note\">${escapeAttr(c.chemin)}</span><br><span class=\"fusion-note\">${escapeAttr(c.raison)}</span></li>`).join(\"\")}</ul>` : \"\";\n  return `<ul class=\"fusion-bilan\">${lignes}</ul>${conflits}`;\n}\n\n/* Reconna\u00eet un export de l'outil (format 8 et tous les formats ant\u00e9rieurs) et renvoie\n   l'arbre pr\u00eat \u00e0 \u00eatre appliqu\u00e9 \u2014 ou null (message d\u00e9j\u00e0 affich\u00e9). Utilis\u00e9 par l'import\n   fichier ET par la synchro cloud : m\u00eame donn\u00e9e, m\u00eame porte d'entr\u00e9e, m\u00eames migrations. */\nfunction preparerImportDepuis(parsed){\n  let nouvellesLignes, nouveauxProjets, nouveauxResponsables, nouveauBacklog, revisionEntrante;\n  const migreImport = migrerArbre(parsed);\n  if(migreImport){\n    nouvellesLignes = migreImport.lignes;\n    nouveauxProjets = migreImport.projets;\n    nouveauxResponsables = migreImport.responsables;\n    nouveauBacklog = (parsed.backlog || []).map(normalizeBacklogItem);\n    revisionEntrante = parsed.revision || 0;\n  } else {\n    const scenarios = Array.isArray(parsed) ? parsed : parsed.scenarios;\n    if(!Array.isArray(scenarios) || !scenarios.length){\n      dialogueAlerte(\"Aucune donn\u00e9e reconnue dans ce contenu.\", \"Import impossible\");\n      return null;\n    }\n    const op = { id: uid(\"o\"), nom: \"OP10\", ordre: 10,\n      config: Object.assign({}, defaultConfig, parsed.config || {}),\n      scenarios: scenarios.map(normalizeScenario) };\n    const ref = { id: uid(\"r\"), nom: \"DV 356x26 RPI\", ops: [op] };\n    nouvellesLignes = [{ id: uid(\"l\"), nom: \"EMAG 1\", references: [ref] }];\n    nouveauxProjets = [];\n    nouveauxResponsables = [];\n    nouveauBacklog = [];\n    revisionEntrante = 0;\n  }\n  /* v4.81.1 \u2014 cette ligne lisait `source`, le param\u00e8tre de migrerArbre : ReferenceError\n     lev\u00e9e en silence dans le onload du FileReader \u2014 aucun panneau, aucun message,\n     aucun import, depuis la 4.53.0. Les livraisons normalis\u00e9es existent d\u00e9j\u00e0 dans\n     migreImport ; le repli (anciens formats) n'en porte pas. */\n  return { nouvellesLignes, nouveauxProjets, nouveauxResponsables, nouveauBacklog, revisionEntrante,\n           livraisons: migreImport ? (migreImport.livraisons || []) : [] };\n}\n\nfunction importData(file){\n  const reader = new FileReader();\n  reader.onload = () => {\n    let parsed;\n    try{\n      parsed = JSON.parse(reader.result);\n    }catch(e){\n      dialogueAlerte(\"Fichier illisible : ce n'est pas un export valide de cet outil.\", \"Import impossible\");\n      return;\n    }\n\n    const prep = preparerImportDepuis(parsed);\n    if(!prep) return;\n\n    // Le choix fusionner/remplacer se fait dans un panneau : c'est une decision a\n    // consequences, elle merite mieux qu'un confirm() ou \"OK\" voudrait dire \"ecrase tout\".\n    importEnAttente = Object.assign({ parsed }, prep);\n    ouvrirChoixImport();\n  };\n  reader.readAsText(file);\n}\n\nlet importEnAttente = null;\n\n/* Cle du \"ne plus afficher\" de l'explication de fusion : locale au poste, comme celle des\n   nouveautes. On ne masque que l'explication, jamais le choix lui-meme. */\nconst CLE_FUSION_EXPL_OFF = \"spk_fusion_explication_masquee\";\n\n/* L'explication est longue a dessein. Aujourd'hui une seule personne saisit : remplacer est\n   le geste normal et reste le bouton par defaut. La fusion est la pour le jour ou ils seront\n   plusieurs \u2014 encore faut-il qu'a ce moment-la on comprenne ce qu'on choisit sans avoir a\n   demander. D'ou l'explication au premier import, et la coche pour ne plus la revoir. */\nfunction explicationFusionHTML(){\n  return `\n    <div class=\"import-expl\" id=\"importExpl\">\n      <p><b>Deux fa\u00e7ons d'int\u00e9grer un fichier re\u00e7u.</b></p>\n      <p><b>Remplacer tout</b> \u2014 le fonctionnement habituel. Tout ce qui est affich\u00e9 ici est\n      remplac\u00e9 par le contenu du fichier. C'est le bon choix quand une seule personne tient le\n      suivi et que le fichier re\u00e7u est la derni\u00e8re version en date : c'est simple et sans\n      surprise. <b>\u00ab \u21ba Restaurer \u00bb permet toujours de revenir en arri\u00e8re.</b></p>\n      <p><b>Fusionner</b> \u2014 utile le jour o\u00f9 vous serez plusieurs \u00e0 saisir en parall\u00e8le. Les\n      essais que vous n'avez pas sont ajout\u00e9s ; ceux que vous avez d\u00e9j\u00e0 ne sont remplac\u00e9s que si\n      la version re\u00e7ue a \u00e9t\u00e9 modifi\u00e9e plus r\u00e9cemment que la v\u00f4tre. Vos r\u00e9glages, vos outils et\n      vos conditions de coupe ne sont jamais \u00e9cras\u00e9s. Quand l'outil ne peut pas trancher (m\u00eame\n      date des deux c\u00f4t\u00e9s, ou fichier cr\u00e9\u00e9 avant la version 3.16 qui n'a pas d'horodatage), il\n      garde <b>votre</b> version et vous la signale \u2014 \u00e0 vous d'aller voir.</p>\n      <p class=\"import-expl-note\">En r\u00e9sum\u00e9 : <b>remplacer</b> quand le fichier re\u00e7u fait\n      autorit\u00e9, <b>fusionner</b> quand chacun a saisi de son c\u00f4t\u00e9. Dans le doute, exportez\n      d'abord votre version pour en garder une copie.</p>\n      <label class=\"opt-row\" style=\"border-top:none; padding-bottom:0;\">\n        <input type=\"checkbox\" id=\"fusionExplMasquer\">\n        <span><b>Ne plus afficher cette explication</b>\n        <em>Elle restera accessible par le lien \u00ab Comment choisir ? \u00bb en haut de cette fen\u00eatre.</em></span>\n      </label>\n    </div>`;\n}\n\nfunction ouvrirChoixImport(){\n  const { parsed, revisionEntrante } = importEnAttente;\n  const quand = parsed.exporteLe ? new Date(parsed.exporteLe).toLocaleString(\"fr-FR\") : \"date inconnue\";\n  const par = parsed.exportePar ? \" par \" + escapeAttr(parsed.exportePar) : \"\";\n  const plusAncien = revisionEntrante && revisionEntrante <= revision;\n  const explMasquee = (() => { try{ return localStorage.getItem(CLE_FUSION_EXPL_OFF) === \"1\"; }catch(e){ return false; } })();\n\n  document.getElementById(\"importPanelBody\").innerHTML = `\n    <p class=\"panel-hint\">Fichier re\u00e7u : r\u00e9vision <b>${revisionEntrante || \"\u2014\"}</b>, export\u00e9 le ${escapeAttr(quand)}${par}. Vos donn\u00e9es actuelles sont en r\u00e9vision <b>${revision || \"\u2014\"}</b>.</p>\n    ${explMasquee ? `<p class=\"import-expl-lien\"><button class=\"ghost small\" id=\"importExplRouvrir\">Comment choisir ?</button></p>` : explicationFusionHTML()}\n    ${plusAncien ? `<div class=\"note\" style=\"margin:0 0 16px;\"><b>Ce fichier est plus ancien ou identique \u00e0 vos donn\u00e9es.</b> Le remplacer \u00e9craserait des saisies plus r\u00e9centes que les siennes. V\u00e9rifiez que c'est bien le fichier voulu \u2014 ou fusionnez, ce qui ne peut rien perdre.</div>` : \"\"}\n    <div class=\"import-choix\">\n      <button class=\"primary\" id=\"importRemplace\">Remplacer tout</button>\n      <p>Fonctionnement habituel, et choix par d\u00e9faut : le contenu du fichier remplace ce qui est affich\u00e9 ici. \u00ab \u21ba Restaurer \u00bb reste disponible pour annuler.</p>\n    </div>\n    <div class=\"import-choix\">\n      <button class=\"ghost\" id=\"importFusion\">Fusionner</button>\n      <p>\u00c0 utiliser quand plusieurs personnes ont saisi chacune de leur c\u00f4t\u00e9 : les essais manquants sont ajout\u00e9s, les v\u00f4tres ne sont remplac\u00e9s que par une version plus r\u00e9cente. Un rapport d\u00e9taille ce qui a chang\u00e9.</p>\n    </div>`;\n\n  ouvrirPanneau(\"importPanel\");\n  document.getElementById(\"importRemplace\").addEventListener(\"click\", () => appliquerImport(\"remplace\"));\n  document.getElementById(\"importFusion\").addEventListener(\"click\", () => appliquerImport(\"fusion\"));\n\n  const coche = document.getElementById(\"fusionExplMasquer\");\n  if(coche) coche.addEventListener(\"change\", () => {\n    try{ localStorage.setItem(CLE_FUSION_EXPL_OFF, coche.checked ? \"1\" : \"0\"); }catch(e){}\n  });\n  const rouvrir = document.getElementById(\"importExplRouvrir\");\n  if(rouvrir) rouvrir.addEventListener(\"click\", () => {\n    try{ localStorage.setItem(CLE_FUSION_EXPL_OFF, \"0\"); }catch(e){}\n    ouvrirChoixImport(); // re-rendu avec l'explication depliee\n  });\n}\n\nfunction appliquerImport(mode){\n  const { parsed, nouvellesLignes, nouveauxProjets, nouveauxResponsables, nouveauBacklog, revisionEntrante } = importEnAttente;\n  backupSnapshot((mode === \"fusion\" ? \"Fusionner\" : \"Importer\") + \" (r\u00e9vision \" + (revisionEntrante || \"\u2014\") + \")\");\n\n  let bilan = null;\n  if(mode === \"fusion\"){\n    bilan = fusionnerLignes(lignes, nouvellesLignes);\n    const bp = fusionnerProjetsTags(projets, nouveauxProjets);\n    bilan.projetsAjoutes = bp.projetsAjoutes; bilan.tagsAjoutes = bp.tagsAjoutes;\n    bilan.responsablesAjoutes = fusionnerResponsables(responsables, nouveauxResponsables || []);\n    bilan.backlog = fusionnerBacklog(backlog, nouveauBacklog);\n    const nouvellesLivraisons = (importEnAttente && importEnAttente.livraisons) || [];\n    livraisons = (livraisons || []).concat(nouvellesLivraisons.filter(nl => !(livraisons || []).some(x => x.id === nl.id)));\n    // la fusion produit un etat qui n'existe dans aucun des deux fichiers : elle merite sa\n    // propre revision, sinon deux postes croiraient detenir la meme\n    revision = Math.max(revision, revisionEntrante || 0) + 1;\n  } else {\n    lignes = nouvellesLignes;\n    projets = nouveauxProjets;\n    responsables = nouveauxResponsables || [];\n    livraisons = (importEnAttente.livraisons || []).map(normalizeLivraison);\n    activeProjetId = projets.find(x => x.id === parsed.activeProjetId) ? parsed.activeProjetId : null;\n    backlog = nouveauBacklog;\n    revision = Math.max(revision, revisionEntrante || 0);\n    // le fichier re\u00e7u fait autorit\u00e9 : ses specs usine et sa note de synchro remplacent les locales\n    specsUsine = normaliserSpecsUsine(parsed.specsUsine);\n    synchroNote = parsed.synchroNote || null;\n  }\n  projets.forEach(purgerTagsMorts);\n\n  // on retombe sur l'onglet qu'avait l'exportateur (ligne > reference > OP > scenario),\n  // s'il est bien present dans le fichier re\u00e7u ; sinon repli sur le tout premier de chaque niveau\n  const ligne = lignes.find(l => l.id === parsed.activeLigneId) || lignes[0];\n  activeLigneId = ligne.id;\n  const r = ligne.references.find(x => x.id === parsed.activeReferenceId) || ligne.references[0];\n  activeReferenceId = r ? r.id : null;\n  const op = r ? (r.ops.find(x => x.id === parsed.activeOpId) || r.ops[0]) : null;\n  activeOpId = op ? op.id : null;\n  data = op ? op.scenarios : [];\n  config = op ? op.config : Object.assign({}, defaultConfig);\n  if(!data.find(s => s.baseline) && data.length) data[0].baseline = true;\n  activeId = (data.find(s => s.id === parsed.activeScenarioId) ? parsed.activeScenarioId : (data[0] ? data[0].id : null));\n  recomputeCycles();\n  saveData();\n  updateRestoreUI();\n  updateRevisionUI();\n  // le resultat d'une fusion n'existe encore sur aucun autre poste : il reste a re-exporter\n  unexported = (mode === \"fusion\");\n  render();\n  importEnAttente = null;\n\n  if(bilan){\n    document.getElementById(\"importPanelBody\").innerHTML =\n      `<p class=\"panel-hint\">Fusion termin\u00e9e \u2014 vos donn\u00e9es passent en r\u00e9vision <b>${revision}</b>. Pensez \u00e0 r\u00e9-exporter : ce r\u00e9sultat fusionn\u00e9 n'existe encore sur aucun autre poste.</p>`\n      + bilanFusionHTML(bilan)\n      + (bilan.backlog ? `<p class=\"fusion-note\">${bilan.backlog} suggestion(s) ajout\u00e9e(s) au backlog.</p>` : \"\");\n  } else {\n    fermerPanneaux();\n  }\n  return bilan || null;\n}\n\nfunction fmt(n, dec){\n  if(n === null || n === undefined || isNaN(n)) return \"\u2014\";\n  // Le francais separe les milliers par U+202F (espace fine insecable), absente de certaines\n  // polices embarquees (\"200 000\" s'affichait quasi colle, l'espace tombant a 1,6 px au lieu\n  // de 9,6. On ramene donc les espaces fines a l'espace insecable ordinaire U+00A0, presente\n  // dans toutes les polices \u2014 meme largeur visible, et les nombres ne se coupent toujours pas.\n  return n.toLocaleString(\"fr-FR\", {minimumFractionDigits:dec, maximumFractionDigits:dec})\n          .replace(/[\\u202f\\u2009\\u2007\\u2008]/g, \"\\u00a0\");\n}\n/* montants annuels : on parle en k\u20ac des qu'on depasse le millier, personne ne lit\n   \"127 340,88 \u20ac\" dans une carte */\nfunction fmtEuroCourt(n){\n  if(n === null || n === undefined || isNaN(n)) return \"\u2014\";\n  const abs = Math.abs(n);\n  if(abs >= 1000000) return fmt(n/1000000, 2) + \" M\u20ac\";\n  if(abs >= 1000) return fmt(n/1000, abs >= 100000 ? 0 : 1) + \" k\u20ac\";\n  return fmt(n, 0) + \" \u20ac\";\n}\nfunction fmtBatt(v){\n  const n = parseFloat(v);\n  return (v === \"\" || v === null || v === undefined || isNaN(n)) ? \"\u2014\" : fmt(n,3);\n}\n\nfunction posCost(pos){\n  const p = parseFloat(pos.prix), a = parseFloat(pos.aretes), c = parseFloat(pos.charniere);\n  if(!p || !a || !c) return null;\n  return p / (a * c);\n}\nfunction posCostPerEdge(pos){\n  const p = parseFloat(pos.prix), a = parseFloat(pos.aretes);\n  if(!p || !a) return null;\n  return p / a;\n}\nfunction scenarioCost(sc){\n  const costs = sc.outils.flatMap(o => o.logements.map(l => posCost(l))).filter(v => v !== null);\n  if(!costs.length) return null;\n  return costs.reduce((a,b) => a+b, 0);\n}\nfunction scenarioCostPerEdge(sc){\n  return sc.outils.flatMap(o => o.logements).reduce((s,l) => s + (posCostPerEdge(l)||0), 0);\n}\nfunction baselineScenario(){\n  return data.find(s => s.baseline) || data[0];\n}\n\n/* ---- v4.19 \u2014 co\u00fbt annuel par logement : o\u00f9 part l'argent de l'outillage ----\n   La vue d'ensemble donnait le co\u00fbt PI\u00c8CE de chaque logement, mais pas ce qu'il pesait\n   sur l'ann\u00e9e : \u00e0 0,0020 \u20ac/pi\u00e8ce sur 150 000 disques, un logement \u00ab pas cher \u00bb peut\n   co\u00fbter plus que son voisin \u00ab cher \u00bb. La couleur cible les postes \u00e0 travailler : la\n   part annuelle du logement est compar\u00e9e \u00e0 sa part th\u00e9orique (1/nb logements) \u2014\n   vert = mineur, ambre = notable, rouge = majeur. */\nfunction libelleAnnuel(v){\n  return v >= 10000 ? fmt(v / 1000, 1) + \" k\u20ac/an\" : fmt(v, 0) + \" \u20ac/an\";\n}\nfunction couleurPartCout(ratio){\n  // ratio = part r\u00e9elle / part th\u00e9orique. 0,33 -> vert (145\u00b0), 2 -> rouge (0\u00b0),\n  // interpolation lin\u00e9aire entre les deux, born\u00e9e des deux c\u00f4t\u00e9s.\n  const r = Math.max(0.33, Math.min(2, ratio));\n  const teinte = Math.round(145 * (2 - r) / (2 - 0.33));\n  return \"hsl(\" + teinte + \", 62%, 34%)\";\n}\n\n/* ============================================================================\n   SCENARIO EN PRODUCTION (v4.4)\n   ============================================================================\n   \"\u2605 Scenario ref.\" = le scenario reellement en production sur cet OP. Un seul concept,\n   pas deux : avant la v4.4, `baseline` (l'ancre de comparaison) et `statut === \"serie\"`\n   pouvaient diverger librement, sans qu'aucune interface ne les remette en phase. Desormais\n   ils ne font plus qu'un, dans les deux sens :\n     - un scenario baseline ne peut pas avoir un autre statut que \"serie\" (verrouille dans\n       statutSelectHTML et appliquerChangementStatut) ;\n     - promouvoir un scenario \"en serie\" (par la pastille \u2605 OU par le menu Statut) passe\n       TOUJOURS par cette fonction, qui retrograde l'ancien titulaire au lieu de laisser\n       deux scenarios \"en serie\" coexister sur le meme OP.\n   L'ancien titulaire retombe a \"Valide\" (pas \"Abandonne\" : il n'a pas echoue, il a ete\n   remplace ; pas \"Essai\" : il a bien tourne en production). Confirme avant d'agir des\n   qu'un autre scenario est reellement impacte, pour que l'effet de bord soit vu avant,\n   pas decouvert apres. */\n/* Questions posees avant une promotion, separees de l'effet (v4.6) : les tests internes\n   verifient le contenu des questions et la machine a etats sans attendre un clic.\n   - garde-fou double comptage (v4.5) : un scenario du meme nom deja en serie sur la meme\n     ligne dans un autre projet = le tableau de bord comptera le gain annuel deux fois pour\n     un seul changement physique. On ne bloque pas (le nom peut mentir), mais on ne laisse\n     pas passer en silence -- c'est le chiffre qui part en reunion.\n   - annonce du remplacement : l'ancien titulaire retombe a \"Valide\", il faut le dire. */\nfunction questionsPromotion(sc){\n  const qs = [];\n  if((projets || []).length > 1){\n    const homonymes = avertissementSerieHomonymes(sc);\n    if(homonymes.length){\n      qs.push({ titre: \"Double comptage possible\", texte:\n        `\u00ab ${sc.name} \u00bb passe en s\u00e9rie ici, mais un sc\u00e9nario du m\u00eame nom est d\u00e9j\u00e0 en s\u00e9rie sur la m\u00eame ligne dans :\\n\\n` +\n        homonymes.join(\"\\n\") +\n        `\\n\\nSi c'est le m\u00eame changement physique suivi deux fois, le gain annuel sera compt\u00e9 DEUX FOIS dans le tableau de bord (une fois par projet).\\n\\nGardez \u00ab en s\u00e9rie \u00bb dans un seul projet si c'est le m\u00eame optimisation.` });\n    }\n  }\n  const ancien = data.find(s => s.baseline && s.id !== sc.id);\n  if(ancien){\n    qs.push({ titre: \"Changer le sc\u00e9nario en production ?\", texte:\n      `Faire de \u00ab ${sc.name} \u00bb le sc\u00e9nario en production ?\\n\\nIl remplace \u00ab ${ancien.name} \u00bb comme sc\u00e9nario de r\u00e9f\u00e9rence (\u2605) \u2014 son statut passera \u00e0 \u00ab Valid\u00e9 \u00bb.` });\n  }\n  return qs;\n}\n/* l'effet lui-meme, sans aucune question : l'ancien titulaire retombe a \"Valide\" (pas\n   \"Abandonne\" : il n'a pas echoue, il a ete remplace ; pas \"Essai\" : il a bien tourne en\n   production). */\nfunction appliquerPromotion(sc){\n  const ancien = data.find(s => s.baseline && s.id !== sc.id);\n  if(ancien){\n    ancien.baseline = false;\n    ancien.statut = \"valide\";\n    if(!ancien.statutDate) ancien.statutDate = new Date().toISOString().slice(0,10);\n  }\n  data.forEach(s => { if(s.id !== sc.id) s.baseline = false; });\n  sc.baseline = true;\n  sc.statut = \"serie\";\n  if(!sc.statutDate) sc.statutDate = new Date().toISOString().slice(0,10);\n  return true;\n}\n/* chemin interactif : pose les questions (dialogues in-app, v4.6) puis applique.\n   Renvoie une promesse de booleen -- meme semantique que l'ancien retour synchrone :\n   false = annule, aucune mutation n'a eu lieu. Le parametre `demander` (tests internes)\n   permet d'injecter une reponse synchrone : la promesse degene alors en booleen. */\nfunction promouvoirEnProduction(sc, demander){\n  if(sc.baseline && sc.statut === \"serie\") return Promise.resolve(true); // deja en place\n  const qs = questionsPromotion(sc);\n  if(!qs.length) return Promise.resolve(appliquerPromotion(sc));\n  const ask = demander || dialogueConfirmer;\n  const suite = i => {\n    if(i >= qs.length) return appliquerPromotion(sc);\n    const rep = ask(qs[i].texte, { titre: qs[i].titre, okLabel: qs[i].titre === \"Double comptage possible\" ? \"Passer en s\u00e9rie quand m\u00eame\" : \"Confirmer\" });\n    if(rep && typeof rep.then === \"function\") return rep.then(ok2 => ok2 === false ? false : suite(i + 1));\n    return rep === false ? false : suite(i + 1);\n  };\n  return suite(0);\n}\n\n/* Point d'entree unique du menu \"Statut\" d'un scenario : verrouille le statut du scenario\n   en production (il faut redefinir la reference pour en sortir), et route toute promotion\n   \"En serie\" par promouvoirEnProduction ci-dessus. Renvoie false si le changement est\n   refuse ou annule -- l'appelant se contente alors de re-rendre pour que le menu deroulant\n   reaffiche la vraie valeur (aucune mutation n'a eu lieu, rien a annuler). */\nfunction appliquerChangementStatut(el){\n  const sc = data.find(s => s.id === el.getAttribute(\"data-id\"));\n  if(!sc) return false;\n  const nouveau = el.value;\n  if((sc.statut || \"essai\") === nouveau) return true;\n  if(sc.baseline && nouveau !== \"serie\"){\n    dialogueAlerte(`\u00ab ${sc.name} \u00bb est le sc\u00e9nario en production (\u2605). Pour lui donner un autre statut, d\u00e9finissez d'abord un autre sc\u00e9nario comme r\u00e9f\u00e9rence.`, \"Statut verrouill\u00e9\");\n    return false;\n  }\n  if(nouveau === \"serie\") return promouvoirEnProduction(sc);\n  sc.statut = nouveau;\n  if((sc.statut === \"serie\" || sc.statut === \"abandonne\") && !sc.statutDate) sc.statutDate = new Date().toISOString().slice(0,10);\n  return true;\n}\n/* le logement \"de reference\" pour le temps de cycle : celui nomme Piste (retro-compat)\n   si migre depuis l'ancien format, sinon le premier logement disponible */\nfunction logementCycle(sc){\n  /* v4.39 \u2014 plus d'heuristique par nom : \u00ab Piste \u00bb venait de la toute premi\u00e8re saisie et\n     n'avait pas \u00e0 gouverner le calcul pour toujours. Le logement d'ancrage de l'indice de\n     cycle est le PREMIER logement du sc\u00e9nario \u2014 l'ordre des fiches fait foi. */\n  const tous = sc.outils.flatMap(o => o.logements);\n  return tous[0] || null;\n}\n\n/* ---- indice thermique K et ratio d'effort radial/axial, temps reel a la saisie ---- */\nconst K_REF = [174, 448];    // points deja valides en production (Vc500/f0,35 et Vc900/f0,50, sin(85\u00b0))\n// Fr/Fa ~ cot(kappa_r) : modele simplifie (decomposition classique tournage), ignore\n// coefficients Kienzle, rayon de bec, usure \u2014 sert a COMPARER des geometries entre\n// elles, pas a predire un effort en Newtons.\nconst FRFA_REF = [1 / Math.tan(85 * Math.PI / 180), 1 / Math.tan(75 * Math.PI / 180)]; // ~0,09 (85\u00b0, valide) a ~0,27 (75\u00b0, habituel)\nfunction kvfDe(logement){\n  const vc = parseFloat(logement.vc), f = parseFloat(logement.f), kr = parseFloat(logement.kappaR);\n  if(isNaN(vc) || isNaN(f)) return { k: null };\n  const vf = vc * f;\n  const k = isNaN(kr) ? null : vf * Math.sin(kr * Math.PI / 180);\n  return { k };\n}\n/* Angle effectif corrige par le rayon de bec : quand la profondeur de passe ap\n   n'atteint pas le rayon de bec re, la coupe se fait uniquement sur la partie\n   arrondie du bec, dont l'angle local varie de 0\u00b0 (tangent a la surface generee)\n   jusqu'a kappa_r nominal (au point de raccord avec l'arete droite). La profondeur\n   d'un point de l'arc a l'angle phi vaut re x (1-cos phi) \u2014 d'ou l'inversion ci-dessous.\n   Au-dela de cette transition, l'arete droite domine et l'angle reste kappa_r nominal. */\nfunction kappaEffectif(logement){\n  const kr = parseFloat(logement.kappaR);\n  if(isNaN(kr)) return null;\n  const re = parseFloat(logement.rayonBec), ap = parseFloat(logement.apPiste);\n  if(isNaN(re) || re <= 0 || isNaN(ap) || ap < 0) return kr; // pas assez de donnees pour affiner\n  const krRad = kr * Math.PI / 180;\n  const apTransition = re * (1 - Math.cos(krRad));\n  if(ap >= apTransition) return kr; // coupe au-dela du bec, l'arete droite domine\n  const ratio = Math.max(0, Math.min(1, ap / re));\n  return Math.acos(1 - ratio) * 180 / Math.PI; // coupe uniquement sur le bec arrondi\n}\nfunction forceRatioDe(logement){\n  const kr = kappaEffectif(logement);\n  if(kr === null || kr <= 0 || kr > 90) return null;\n  return 1 / Math.tan(kr * Math.PI / 180);\n}\nfunction dansEncadrement(v, ref){\n  // les bornes de reference sont elles-memes des valeurs arrondies (ex. 448\n  // pour 900x0,50xsin(85\u00b0)=448,29) : on compare donc arrondi a arrondi\n  if(v === null) return false;\n  const vr = Math.round(v);\n  return vr >= Math.min(...ref) && vr <= Math.max(...ref);\n}\nfunction dansEncadrementPrecis(v, ref, eps){\n  if(v === null) return false;\n  eps = eps || 1e-9;\n  return v >= Math.min(...ref) - eps && v <= Math.max(...ref) + eps;\n}\n/* K s'affiche partout ou kappa_r est renseigne (indice thermique, toujours utile) ;\n   Fr/Fa reste optionnel (config.forceRatioActif, par OP) \u2014 specifique a certaines\n   references/plaquettes, pas systematique. */\n/* v4.42 \u2014 botte secrete : le coefficient K ne s'affiche que pour l'auteur du projet\n   (auteurNom contient \u00ab Rouquette \u00bb, ou drapeau local spk_k_secrete=1) et JAMAIS dans\n   les chemins d'impression. Le calcul (kvfDe) reste inchang\u00e9 : seule la sortie visible\n   est conditionn\u00e9e. */\nfunction kAutorise(){\n  try{ if(localStorage.getItem(\"spk_k_secrete\") === \"1\") return true; }catch(e){}\n  return /rouquette/i.test(auteurNom || \"\");\n}\nfunction kvfWidgetHTML(sc, autoriseK){\n  const items = [];\n  sc.outils.forEach((o, oi) => {\n    o.logements.forEach(l => {\n      if(l.kappaR === \"\" || l.kappaR == null || isNaN(parseFloat(l.kappaR))) return;\n      const couleur = OUTIL_COLORS[oi % OUTIL_COLORS.length];\n      const label = escapeAttr(o.numero || \"\u2014\") + \" \u00b7 \" + escapeAttr(l.nom || \"\u2014\");\n      if(autoriseK){\n        const { k } = kvfDe(l);\n        const kOk = k === null ? null : dansEncadrement(k, K_REF);\n        items.push(`\n        <div class=\"kvf-item\" style=\"border-left:3px solid ${couleur}; padding-left:8px;\">\n          <span class=\"l\">${label} \u2014 K</span>\n          <span class=\"v ${k === null ? \"\" : (kOk ? \"in\" : \"out\")}\">${k === null ? \"\u2014\" : fmt(k,0)}</span>\n          <span class=\"ref\">r\u00e9f. encadrement ${K_REF[0]}\u2013${K_REF[1]}</span>\n        </div>\n      `);\n      }\n      if(config.forceRatioActif){\n        const krNominal = parseFloat(l.kappaR);\n        const krEff = kappaEffectif(l);\n        const frfa = forceRatioDe(l);\n        const frfaOk = frfa === null ? null : dansEncadrementPrecis(frfa, FRFA_REF);\n        const affine = krEff !== null && Math.abs(krEff - krNominal) > 0.05;\n        items.push(`\n          <div class=\"kvf-item\" style=\"border-left:3px solid ${couleur}; padding-left:8px;\">\n            <span class=\"l\">${label} \u2014 Fr/Fa</span>\n            <span class=\"v ${frfa === null ? \"\" : (frfaOk ? \"in\" : \"out\")}\">${frfa === null ? \"\u2014\" : fmt(frfa,2)}</span>\n            <span class=\"ref\">r\u00e9f. \u03bar 85\u00b0\u219275\u00b0 : ${fmt(Math.min(...FRFA_REF),2)}\u2013${fmt(Math.max(...FRFA_REF),2)}${affine ? \" \u00b7 \u03bar effectif \" + fmt(krEff,1) + \"\u00b0\" : \"\"}</span>\n          </div>\n        `);\n      }\n    });\n  });\n  if(!items.length) return \"\";\n  return `<div class=\"kvf-widget\">${items.join(\"\")}</div>`;\n}\n\nfunction recomputeCycles(){\n  const base = baselineScenario();\n  if(!base) return;\n  const baseLog = logementCycle(base);\n  const vcRef = baseLog ? parseFloat(baseLog.vc) : NaN, fRef = baseLog ? parseFloat(baseLog.f) : NaN;\n  const vfRef = (!isNaN(vcRef) && !isNaN(fRef) && vcRef*fRef > 0) ? vcRef*fRef : null;\n  data.forEach(sc => {\n    if(sc.id === base.id){ sc.cycle = 100; return; }\n    if(vfRef === null) return;\n    const log = logementCycle(sc);\n    if(!log) return;\n    const vc = parseFloat(log.vc), f = parseFloat(log.f);\n    if(isNaN(vc) || isNaN(f) || vc*f === 0) return;\n    sc.cycle = Math.round((100 * vfRef / (vc*f)) * 10) / 10;\n  });\n}\n\nfunction checkConformPrincipal(sc, row){\n  // v4.9 : le battement se d\u00e9coche (un essai peut ne porter que sur le Ra, par exemple) \u2014\n  // un crit\u00e8re volontairement d\u00e9sactiv\u00e9 ne peut ni faire \u00e9chouer, ni exempter.\n  if(sc.battActif === false) return true;\n  if(!toleranceRequisePour(sc, row)) return null; // ce logement ne suit que la charniere, pas la tolerance\n  const limit = parseFloat(limiteDe(sc));\n  if(isNaN(limit)) return null;\n  if(sc.emag1){\n    // v4.9 : c\u00f4t\u00e9s s\u00e9lectionnables par sc\u00e9nario \u2014 un essai peut ne porter qu'un seul c\u00f4t\u00e9\n    const cotes = battCotesDe(sc);\n    const vals = [];\n    if(cotes !== \"G\"){ const d = parseFloat(row.battD); if(!isNaN(d)) vals.push(d); }\n    if(cotes !== \"D\"){ const g = parseFloat(row.battG); if(!isNaN(g)) vals.push(g); }\n    if(!vals.length) return null;\n    return Math.max(...vals) <= limit;\n  }\n  const b = parseFloat(row.batt);\n  if(isNaN(b)) return null;\n  return b <= limit;\n}\n/* c\u00f4t\u00e9s mesur\u00e9s pour le battement : \"DG\" (d\u00e9faut), \"D\" ou \"G\" (essai \u00e0 un seul c\u00f4t\u00e9) ;\n   \"mono\" quand la mesure droite/gauche n'est pas activ\u00e9e du tout */\nfunction battCotesDe(sc){\n  if(!sc.emag1) return \"mono\";\n  return (sc.battCotes === \"D\" || sc.battCotes === \"G\") ? sc.battCotes : \"DG\";\n}\n/* v4.9 \u2014 crit\u00e8res suppl\u00e9mentaires g\u00e9n\u00e9riques : Ra, VE, ou tout crit\u00e8re libre de\n   l'op\u00e9rateur. Chacun porte ses bornes (maxi, mini optionnelle) et ses axes de mesure\n   (Droite/Gauche pour les broches, Inter/Exter pour les pistes \u2014 une valeur unique si\n   aucun axe). Les valeurs vivent dans prelevement.valeurs[critere.id][axe]. */\nfunction criteresSupActifs(sc){\n  return (sc.criteresSup || []).filter(c => c.actif !== false);\n}\nfunction axesDe(c){ return (c.axes && c.axes.length) ? c.axes : [\"v\"]; }\nconst AXE_LABELS = { D:\"Droite\", G:\"Gauche\", I:\"Inter\", E:\"Exter\", v:\"\" };\n/* les colonnes affich\u00e9es pour les crit\u00e8res suppl\u00e9mentaires : une par crit\u00e8re actif \u00d7 axe */\nfunction csupColonnes(sc){\n  const cols = [];\n  criteresSupActifs(sc).forEach(c => { axesDe(c).forEach(ax => cols.push({ c, ax })); });\n  return cols;\n}\n/* une case vide ne fait jamais \u00e9chouer un pr\u00e9l\u00e8vement par ailleurs conforme ; s'il n'y\n   a AUCUNE valeur saisie pour les crit\u00e8res actifs, le verdict est null (non \u00e9valu\u00e9) */\nfunction evaluerCriteresSup(sc, row){\n  const actifs = criteresSupActifs(sc);\n  if(!actifs.length) return null;\n  let evalue = false, ok = true;\n  for(const c of actifs){\n    const vals = (row.valeurs || {})[c.id] || {};\n    for(const ax of axesDe(c)){\n      const v = parseFloat(vals[ax]);\n      if(isNaN(v)) continue;\n      evalue = true;\n      const maxi = parseFloat(c.maxi);\n      if(!isNaN(maxi) && v > maxi) ok = false;\n      if(c.miniActif){ const mini = parseFloat(c.mini); if(!isNaN(mini) && v < mini) ok = false; }\n    }\n  }\n  return evalue ? ok : null;\n}\n/* premi\u00e8re valeur hors bornes, pour nommer pr\u00e9cis\u00e9ment la raison (crit\u00e8re + axe) */\nfunction premiereHorsBornesSup(sc, row){\n  for(const c of criteresSupActifs(sc)){\n    const vals = (row.valeurs || {})[c.id] || {};\n    for(const ax of axesDe(c)){\n      const v = parseFloat(vals[ax]);\n      if(isNaN(v)) continue;\n      const maxi = parseFloat(c.maxi);\n      if(!isNaN(maxi) && v > maxi) return { label: c.label, axe: ax, v, borne: maxi, sens: \"maxi\" };\n      if(c.miniActif){ const mini = parseFloat(c.mini); if(!isNaN(mini) && v < mini) return { label: c.label, axe: ax, v, borne: mini, sens: \"mini\" }; }\n    }\n  }\n  return null;\n}\n/* usure visuelle : \"a changer\" fait toujours echouer le prelevement, quelle que soit la\n   mesure \u2014 un outil visiblement use n'est pas rattrape par une cote encore dans la tol. */\nfunction checkUsure(row){\n  return row.usure === \"changer\" ? false : true;\n}\nconst USURE_LABELS = { ok: \"OK\", limite: \"Usure limite\", changer: \"\u00c0 changer\" };\nfunction usureBadgeHTML(usure){\n  if(usure === \"changer\") return `<span class=\"badge risk\">\u00c0 changer</span>`;\n  if(usure === \"limite\") return `<span class=\"badge warn\">Usure limite</span>`;\n  if(usure === \"ok\") return `<span class=\"badge ok\">OK</span>`;\n  return `<span class=\"badge muted\">\u2014</span>`;\n}\nfunction usureSelectHTML(row, attrs){\n  return `<select class=\"cell usure-select small\" ${attrs} data-field=\"usure\">\n    <option value=\"\" ${!row.usure ? \"selected\" : \"\"}>\u2014</option>\n    <option value=\"ok\" ${row.usure===\"ok\"?\"selected\":\"\"}>OK</option>\n    <option value=\"limite\" ${row.usure===\"limite\"?\"selected\":\"\"}>Usure limite</option>\n    <option value=\"changer\" ${row.usure===\"changer\"?\"selected\":\"\"}>\u00c0 changer</option>\n  </select>`;\n}\n/* explique pourquoi un prelevement est hors tolerance, pour les raisons affichees au\n   niveau de l'essai (sinon tout est etiquete \"hors tolerance\" meme quand c'est l'usure\n   visuelle ou l'etat de surface qui a fait basculer le verdict) */\nfunction raisonNonConforme(sc, row){\n  if(checkConformPrincipal(sc, row) === false) return \"hors tol\u00e9rance\";\n  const hb = premiereHorsBornesSup(sc, row);\n  if(hb){\n    const axe = hb.axe !== \"v\" ? \" \" + (AXE_LABELS[hb.axe] || hb.axe) : \"\";\n    return (hb.label || \"crit\u00e8re\") + axe + (hb.sens === \"maxi\" ? \" : \" + fmtBatt(hb.v) + \" > \" + fmtBatt(hb.borne) : \" : \" + fmtBatt(hb.v) + \" < \" + fmtBatt(hb.borne));\n  }\n  if(checkUsure(row) === false) return \"plaquette \u00e0 changer (usure)\";\n  return \"\";\n}\n/* verdict combine d'un prelevement : conforme seulement si toutes les gardes passent. Le\n   battement reste seul maitre du null (pas de tolerance requise / valeur absente) ; les\n   criteres supplementaires et l'usure ne peuvent que faire basculer un prelevement DEJA\n   evalue de conforme a non conforme, jamais l'inverse et jamais depuis le null. */\nfunction checkConform(sc, row){\n  const principal = checkConformPrincipal(sc, row);\n  if(principal !== true) return principal; // null (exempte/pas de valeur) ou false : inchange\n  if(evaluerCriteresSup(sc, row) === false) return false;\n  if(checkUsure(row) === false) return false;\n  return true;\n}\n/* le dernier n\u00b0 de piece atteint POUR UN LOGEMENT DONNE : si au moins un prelevement de\n   l'essai porte un logementId, on ne compte que ceux de ce logement (mesures menees en\n   parallele sur plusieurs logements) ; sinon (anciens essais, un seul flux de mesures\n   partage), on retombe sur tous les prelevements \u2014 comportement identique a avant. */\nfunction lastPieceLogement(essai, logementId){\n  const prels = essai.prelevements || [];\n  const utiliseLogements = prels.some(r => r.logementId);\n  const rows = utiliseLogements ? prels.filter(r => r.logementId === logementId) : prels;\n  const vals = rows.map(r => parseFloat(r.piece)).filter(v => !isNaN(v));\n  return vals.length ? Math.max(...vals) : null;\n}\n/* ---- valeur mesuree principale d'un prelevement, independamment du mode EMAG ----\n   (sur ligne EMAG 1 on suit deux cotes par piece : c'est la plus defavorable qui compte) */\nfunction mesurePrincipale(sc, row){\n  if(sc.emag1){\n    const vals = [parseFloat(row.battD), parseFloat(row.battG)].filter(v => !isNaN(v));\n    return vals.length ? Math.max(...vals) : null;\n  }\n  const b = parseFloat(row.batt);\n  return isNaN(b) ? null : b;\n}\n\n/* ---- prevision de sortie de tolerance ----------------------------------------------\n   L'outil constatait l'usure, il ne la projetait pas : on lisait \"212 / 400 p\" sans savoir\n   si la cote tiendrait jusqu'a 400. Regression lineaire sur les prelevements deja saisis\n   (n\u00b0 de piece -> cote mesuree), extrapolee jusqu'a la tolerance. Ca ne remplace pas l'essai,\n   ca dit s'il vaut la peine d'etre poursuivi.\n\n   Garde-fous volontaires \u2014 mieux vaut ne rien afficher qu'un chiffre non defendable :\n   - au moins 4 points de mesure, et au moins 3 n\u00b0 de piece distincts (sinon on \"predit\"\n     a partir d'une seule position d'usure) ;\n   - pente positive : une cote stable ou qui s'ameliore n'a pas de date de sortie ;\n   - R\u00b2 >= 0,35, sinon la dispersion domine la tendance et l'extrapolation ne veut rien dire ;\n   - incertitude affichee (\u00b1 2 erreurs-types ramenees en n\u00b0 de piece), jamais un chiffre sec.  */\nfunction previsionUsure(sc, essai, logementId){\n  const limit = parseFloat(limiteDe(sc));\n  if(isNaN(limit)) return null;\n  const prels = (essai.prelevements || []).filter(r => toleranceRequisePour(sc, r));\n  const utiliseLogements = prels.some(r => r.logementId);\n  const rows = (utiliseLogements && logementId) ? prels.filter(r => r.logementId === logementId) : prels;\n  const pts = rows.map(r => ({ x: parseFloat(r.piece), y: mesurePrincipale(sc, r) }))\n                  .filter(pt => !isNaN(pt.x) && pt.y !== null);\n  if(pts.length < 4) return null;\n  if(new Set(pts.map(pt => pt.x)).size < 3) return null;\n\n  const n = pts.length;\n  const mx = pts.reduce((a,pt) => a+pt.x, 0)/n;\n  const my = pts.reduce((a,pt) => a+pt.y, 0)/n;\n  const sxx = pts.reduce((a,pt) => a + (pt.x-mx)*(pt.x-mx), 0);\n  if(sxx === 0) return null;\n  const sxy = pts.reduce((a,pt) => a + (pt.x-mx)*(pt.y-my), 0);\n  const pente = sxy / sxx;\n  const ord = my - pente*mx;\n  const syy = pts.reduce((a,pt) => a + (pt.y-my)*(pt.y-my), 0);\n  const sse = pts.reduce((a,pt) => { const e = pt.y - (pente*pt.x + ord); return a + e*e; }, 0);\n  const r2 = syy > 0 ? Math.max(0, 1 - sse/syy) : 0;\n\n  const derniere = Math.max(...pts.map(pt => pt.x));\n  const dejaSortie = pts.some(pt => pt.y > limit);\n  if(pente <= 0) return { etat: \"stable\", r2, derniere, dejaSortie };\n  if(r2 < 0.35) return { etat: \"disperse\", r2, derniere, dejaSortie };\n\n  const piece = (limit - ord) / pente;\n  if(!isFinite(piece)) return null;\n  // \u00b1 2 erreurs-types de la cote, converties en n\u00b0 de piece par la pente\n  const se = n > 2 ? Math.sqrt(sse/(n-2)) : 0;\n  const marge = pente > 0 ? (2*se)/pente : 0;\n  return { etat: \"prevu\", piece, marge, pente, r2, derniere, dejaSortie };\n}\n\n/* pastille de tendance affichee a cote de la progression d'un logement. Le libelle est\n   volontairement explicite (\"tendance\", \"vers la piece X\") : c'est une extrapolation, pas\n   une mesure, et personne ne doit la lire comme une garantie de duree de vie. */\nfunction previsionChipHTML(sc, essai, lp){\n  const pr = previsionUsure(sc, essai, lp.logementId);\n  if(!pr) return \"\";\n  const lab = escapeAttr(libelleDe(sc));\n  if(pr.dejaSortie) return `<span class=\"prev-chip bad\" title=\"Au moins un pr\u00e9l\u00e8vement de ce logement d\u00e9passe d\u00e9j\u00e0 la tol\u00e9rance ${lab}.\">d\u00e9j\u00e0 hors tol.</span>`;\n  if(pr.etat === \"stable\") return `<span class=\"prev-chip ok\" title=\"Sur les pr\u00e9l\u00e8vements saisis, la cote ${lab} ne d\u00e9rive pas (pente nulle ou n\u00e9gative) : pas de sortie de tol\u00e9rance pr\u00e9visible \u00e0 ce stade.\">tendance stable</span>`;\n  if(pr.etat === \"disperse\") return `<span class=\"prev-chip muted\" title=\"Dispersion trop forte pour extrapoler (R\u00b2 = ${fmt(pr.r2,2)}). Ajouter des pr\u00e9l\u00e8vements ou v\u00e9rifier la r\u00e9p\u00e9tabilit\u00e9 de la mesure.\">tendance non lisible</span>`;\n  const piece = Math.round(pr.piece), marge = Math.round(pr.marge);\n  const avantCible = lp.target !== null && piece < lp.target;\n  const cls = avantCible ? \"bad\" : (lp.target !== null && piece < lp.target * 1.15 ? \"warn\" : \"ok\");\n  const tip = `Extrapolation lin\u00e9aire des mesures relev\u00e9es jusqu'\u00e0 la pi\u00e8ce ${escapeAttr(String(pr.derniere))} (R\u00b2 = ${fmt(pr.r2,2)}) : `\n    + `la cote ${lab} atteindrait la tol\u00e9rance vers la pi\u00e8ce ${piece} (\u00b1 ${marge}). `\n    + (avantCible ? `C'est AVANT la charni\u00e8re vis\u00e9e de ${lp.target} \u2014 l'essai ne tiendra pas la cible au rythme d'usure actuel.` : `Tendance, pas une garantie : \u00e0 confirmer par les pr\u00e9l\u00e8vements suivants.`);\n  return `<span class=\"prev-chip ${cls}\" title=\"${tip}\">tendance : tol. vers ${piece} p \u00b1 ${marge}</span>`;\n}\n\nfunction essaiStats(sc, essai){\n  const prels = essai.prelevements || [];\n  // seules les lignes dont le logement suit la tolerance comptent pour la conformite /\n  // les mesures manquantes ; un logement \"charniere seule\" ne bloque jamais l'essai sur\n  // ses mesures, meme si sa colonne de valeur reste vide\n  const prelsTolerance = prels.filter(r => toleranceRequisePour(sc, r));\n  const evaluated = prelsTolerance.filter(r => checkConform(sc,r) !== null);\n  const badCount = evaluated.filter(r => checkConform(sc,r) === false).length;\n  const anyBad = badCount > 0;\n  const tauxHorsTol = evaluated.length ? (badCount / evaluated.length) * 100 : null;\n  const manquantes = prelsTolerance.length - evaluated.length;\n  const pieceVals = prels.map(r => parseFloat(r.piece)).filter(v => !isNaN(v));\n  const lastPiece = pieceVals.length ? Math.max(...pieceVals) : null;\n\n  // chaque logement a sa propre charniere visee ET son propre flux de mesures (mene en\n  // parallele) \u2014 independance totale : un outil peut atteindre sa cible pendant qu'un\n  // autre continue, chacun compte ses propres pieces\n  const snap = logementsSuivis(essai);\n  const logementProgress = snap.map(lp => {\n    const target = parseFloat(lp.charniere);\n    const hasTarget = !isNaN(target);\n    const lastPieceLog = lastPieceLogement(essai, lp.logementId);\n    const complete = hasTarget && lastPieceLog !== null && lastPieceLog >= target;\n    const nom = nomLogementActuel(sc, lp); // v4.22 : nom actuel (reprise, statut)\n    return { outilNumero: nom.outilNumero, logementNom: nom.logementNom, logementId: lp.logementId, target: hasTarget ? target : null, lastPiece: lastPieceLog, complete };\n  });\n  const targetsValides = logementProgress.filter(lp => lp.target !== null);\n  const tousComplets = targetsValides.length > 0 && targetsValides.every(lp => lp.complete);\n\n  let status = \"pending\", raison = \"\";\n  if(essai.cloture && essai.cloture.motif){\n    /* v4.25 \u2014 cl\u00f4ture (arr\u00eat anticip\u00e9) : la d\u00e9cision de record passe AVANT tout. Un essai\n       arr\u00eat\u00e9 pour casse avant la charni\u00e8re n'est ni \"en cours\" (il n'attend plus rien),\n       ni \"non conforme\" (la casse n'est pas une sortie de tol\u00e9rance mesur\u00e9e) : il est\n       \"arr\u00eat\u00e9\", avec son motif. Ses pr\u00e9l\u00e8vements restent intacts pour les courbes. */\n    status = \"arrete\";\n    raison = \"Arr\u00eat\u00e9 \u2014 \" + libelleMotifArret(essai.cloture.motif) +\n      (essai.cloture.date ? \" le \" + essai.cloture.date.split(\"-\").reverse().join(\"/\") : \"\") +\n      (essai.cloture.detail ? \" \u00b7 \" + essai.cloture.detail : \"\");\n  } else if(anyBad){\n    status = \"bad\";\n    const premierBad = evaluated.find(r => checkConform(sc,r) === false);\n    raison = premierBad ? raisonNonConforme(sc, premierBad) : \"hors tol\u00e9rance\";\n  } else if(!prels.length){\n    raison = \"aucun pr\u00e9l\u00e8vement\";\n  } else if(manquantes > 0){\n    raison = manquantes + \" mesure\" + (manquantes>1?\"s\":\"\") + \" \u00e0 saisir\";\n  } else if(!targetsValides.length){\n    raison = \"charni\u00e8re non renseign\u00e9e\";\n  } else if(!tousComplets){\n    raison = targetsValides.filter(lp => !lp.complete)\n      .map(lp => (lp.outilNumero||\"?\") + \" \" + (lp.logementNom||\"\") + \" \" + (lp.lastPiece ?? 0) + \"/\" + lp.target)\n      .join(\", \") + \" p\";\n  } else {\n    status = \"ok\";\n  }\n  return { count: prels.length, evaluatedCount: evaluated.length, badCount, tauxHorsTol, manquantes,\n           lastPiece, logementProgress, complete: tousComplets, anyBad, status, raison };\n}\n\n/* v4.25 \u2014 motifs d'arr\u00eat anticip\u00e9 d'un essai cl\u00f4tur\u00e9 avant sa charni\u00e8re */\nconst MOTIFS_ARRET = [\n  [\"casse\", \"Casse / \u00e9clat d'ar\u00eate\"],\n  [\"horsTolerance\", \"Hors tol\u00e9rance\"],\n  [\"brut\", \"Probl\u00e8me de brut (\u00e9clat, maturit\u00e9\u2026)\"],\n  [\"machine\", \"Incident machine\"],\n  [\"autre\", \"Autre\"]\n];\nfunction libelleMotifArret(m){\n  const t = MOTIFS_ARRET.find(x => x[0] === m);\n  return t ? t[1] : (m || \"motif inconnu\");\n}\n\nfunction scenarioStats(sc){\n  const essais = sc.essais || [];\n  const list = essais.map(e => essaiStats(sc, e));\n  const validCount = list.filter(s => s.status === \"ok\").length;\n  const badCount = list.filter(s => s.status === \"bad\").length;\n  const arreteCount = list.filter(s => s.status === \"arrete\").length;\n  const threshold = parseFloat(sc.validationThreshold);\n  const validated = !isNaN(threshold) && threshold > 0 && validCount >= threshold;\n  const allEvaluated = essais.flatMap(e => (e.prelevements||[]).filter(r => checkConform(sc,r) !== null));\n  const allBad = allEvaluated.filter(r => checkConform(sc,r) === false).length;\n  const rate = allEvaluated.length ? (allBad/allEvaluated.length)*100 : null;\n  return { essaisCount: essais.length, validCount, badCount, arreteCount, rate, validated };\n}\n\n/* ---- bandeau verdict : la reponse a la question que l'outil sert a trancher ----\n   \"est-ce que ce scenario est meilleur que ce qui tourne aujourd'hui, et de combien ?\"\n   Avant, il fallait lire trois cartes et faire le calcul de tete. */\n/* v4.30 \u2014 dur\u00e9e de vie du sc\u00e9nario = charni\u00e8re du logement de r\u00e9f\u00e9rence (pi\u00e8ces par ar\u00eate).\n   Sert \u00e0 la fois au verdict (le ratio \u00ab \u00d7 la dur\u00e9e de vie \u00bb) et \u00e0 sa cellule du tableau\n   de bord (la valeur absolue, qui quittait les chips du verdict). */\nfunction dureeVieScenario(sc){\n  const l = logementCycle(sc);\n  const v = parseFloat(l && l.charniere);\n  return isNaN(v) ? null : v;\n}\n\nfunction verdictHTML(sc){\n  const base = baselineScenario();\n  const stats = scenarioStats(sc);\n  const cost = scenarioCost(sc), baseCost = base ? scenarioCost(base) : null;\n\n  // duree de vie = charniere du logement de reference (pieces par arete)\n  const vieSc = dureeVieScenario(sc), vieBase = base ? dureeVieScenario(base) : null;\n\n  // des que plusieurs postes de cout sont actifs, c'est le cout complet qui fait foi :\n  // annoncer -93 % sur les seules plaquettes quand le temps machine double serait faux\n  const couts = coutsDetail(sc);\n  const coutsBase = base ? coutsDetail(base) : null;\n  const complet = couts.multiPoste;\n  /* v4.45 \u2014 le % de co\u00fbt se calcule sur le p\u00e9rim\u00e8tre commun sc\u00e9nario/r\u00e9f\u00e9rence */\n  const periVerdict = base ? perimetreCompare(couts, coutsBase) : null;\n  const refCout = (periVerdict && periVerdict.communs.length) ? periVerdict.sc : (complet ? couts.total : cost);\n  const refBase = (periVerdict && periVerdict.communs.length) ? periVerdict.base : (complet ? (coutsBase ? coutsBase.total : null) : baseCost);\n  const horsMachine = !!(periVerdict && periVerdict.exclus.includes(\"temps machine\"));\n  const annuel = bilanAnnuel(sc);\n\n  let titre, sousTitre, classe, eyebrow;\n\n  if(sc.baseline){\n    classe = \"ref\";\n    eyebrow = \"R\u00e9f\u00e9rence de production\";\n    titre = \"Base 100 \u2014 tous les autres sc\u00e9narios se comparent \u00e0 celui-ci.\";\n    sousTitre = \"\";\n  } else {\n    const dCost = (refCout !== null && refBase) ? ((refCout - refBase) / refBase) * 100 : null;\n    const rVie  = (vieSc !== null && vieBase) ? vieSc / vieBase : null;\n    const gain = dCost !== null && dCost < 0;\n\n    classe = stats.validated ? \"ok\" : (stats.badCount > 0 ? \"bad\" : \"pending\");\n    eyebrow = stats.validated ? \"Bilan valid\u00e9\" : \"Verdict d'essai\";\n    if(dCost === null){\n      titre = \"Renseignez prix, ar\u00eates et charni\u00e8re\";\n      sousTitre = \"Le gain se calcule d\u00e8s que les plaquettes sont d\u00e9crites.\";\n    } else {\n      titre = (gain ? \"\u2212\" : \"+\") + fmt(Math.abs(dCost),1) + \" % de co\u00fbt par pi\u00e8ce\" + (horsMachine ? \" (hors temps machine)\" : complet ? \" (tout compris)\" : \" outil\");\n      const bouts = [];\n      if(annuel && annuel.gainAnnuel !== undefined){\n        bouts.push((annuel.gainAnnuel >= 0 ? \"\" : \"perte de \") + fmtEuroCourt(Math.abs(annuel.gainAnnuel)) + \"/an\");\n      }\n      if(rVie !== null && rVie !== 1) bouts.push(fmt(rVie,1).replace(\",0\",\"\") + \"\u00d7 la dur\u00e9e de vie d'ar\u00eate\");\n      bouts.push(stats.validated\n        ? \"valid\u00e9 sur \" + stats.validCount + \" essai\" + (stats.validCount>1?\"s\":\"\")\n        : stats.badCount > 0\n          ? stats.badCount + \" essai\" + (stats.badCount>1?\"s\":\"\") + \" non conforme\" + (stats.badCount>1?\"s\":\"\")\n          : \"validation en cours (\" + stats.validCount + \"/\" + (sc.validationThreshold||\"\u2014\") + \")\");\n      if(horsMachine) bouts.push(\"comparaison hors temps machine \u2014 la r\u00e9f\u00e9rence n'a pas de cycle chiffrable\");\n      sousTitre = bouts.join(\" \u00b7 \") + \" \u2014 vs \" + escapeAttr(base.name);\n    }\n  }\n\n  /* v4.30 \u2014 plus de chips : chaque chiffre qu'elles r\u00e9p\u00e9taient a sa cellule dans la bande\n     (co\u00fbt/pi\u00e8ce, dont temps machine dans la d\u00e9composition, dur\u00e9e de vie, gain annuel,\n     hors tol\u00e9rance dans la cellule validation). Ici : l'\u00e9tat, la r\u00e9ponse, la raison. */\n  return `<div class=\"foot-verdict ${classe}\">\n    <p class=\"fv-eyebrow\">${eyebrow}</p>\n    <div class=\"fv-titre\">${titre}</div>\n    ${sousTitre ? `<div class=\"fv-sous\">${sousTitre}</div>` : \"\"}\n  </div>`;\n}\n\n/* ---- MODE ATELIER : saisie plein ecran, pensee pour etre utilisee debout devant la\n   machine, avec des gants. Une mesure a la fois, gros champs, gros boutons, le contexte\n   toujours visible (quel essai, quel logement, quelle piece). Ecrit dans les memes donnees\n   que la saisie tableau \u2014 ce n'est qu'une autre porte d'entree, pas un stockage separe. ---- */\nlet atelierCtx = null; // { scId, essaiId, logementId, pointMesure }\n\nfunction atelierProchainePiece(essai, logementId){\n  const last = lastPieceLogement(essai, logementId);\n  const pas = (function(){\n    // devine le pas de prelevement a partir des deux dernieres pieces du meme logement\n    const rows = (essai.prelevements||[]).filter(r => !logementId || r.logementId === logementId);\n    const vals = [...new Set(rows.map(r => parseFloat(r.piece)).filter(v => !isNaN(v)))].sort((a,b)=>a-b);\n    if(vals.length >= 2) return vals[vals.length-1] - vals[vals.length-2];\n    return 10; // defaut : Matis mesure toutes les 10 pieces\n  })();\n  return last === null ? 1 : last + (pas > 0 ? pas : 10);\n}\nfunction atelierHTML(){\n  if(!atelierCtx) return \"\";\n  const sc = data.find(s => s.id === atelierCtx.scId);\n  const essai = sc && (sc.essais||[]).find(e => e.id === atelierCtx.essaiId);\n  if(!sc || !essai) return \"\";\n  const snap = logementsSuivis(essai);\n  if(!atelierCtx.logementId && snap.length) atelierCtx.logementId = snap[0].logementId;\n  const lp = snap.find(x => x.logementId === atelierCtx.logementId);\n  const piece = atelierProchainePiece(essai, atelierCtx.logementId);\n  const st = essaiStats(sc, essai);\n  const prog = st.logementProgress.find(p => p.logementId === atelierCtx.logementId);\n  const pct = prog && prog.target ? Math.min(100, ((prog.lastPiece||0)/prog.target)*100) : 0;\n  // v4.14 : le signal au bon moment. La barre de progression montrait la distance parcourue,\n  // rien ne disait QUAND d\u00e9cider : \u00e0 la charni\u00e8re vis\u00e9e, on resserre le pas de mesure ou on\n  // tranche (prolonger / arr\u00eater) ; au-del\u00e0, la dur\u00e9e de vie d\u00e9passe l'objectif, c'est une\n  // bonne nouvelle \u00e0 exploiter tant que la cote tient.\n  const viseeAtteinte = !!(prog && prog.target !== null && piece >= prog.target);\n\n  // points de mesure deja utilises dans cet essai : proposes en raccourci\n  const points = [...new Set((essai.prelevements||[]).map(r => (r.pointMesure||\"\").trim()).filter(Boolean))];\n  const pmActif = atelierCtx.pointMesure || \"\";\n\n  const dernieres = (essai.prelevements||[])\n    .filter(r => !atelierCtx.logementId || r.logementId === atelierCtx.logementId)\n    .slice(-4).reverse().map(r => {\n      const c = checkConform(sc, r);\n      const val = sc.emag1 ? (fmtBatt(r.battD) + \" / \" + fmtBatt(r.battG)) : fmtBatt(r.batt);\n      return `<div class=\"at-recent-row\"><span class=\"p\">n\u00b0${escapeAttr(r.piece)}</span>\n        <span class=\"pm\">${escapeAttr(r.pointMesure)||\"\"}</span>\n        <span class=\"v\">${val}</span>\n        <span class=\"${c===false?\"bad\":c===true?\"ok\":\"na\"}\">${c===false?\"HORS TOL.\":c===true?\"OK\":\"\u2014\"}</span></div>`;\n    }).join(\"\") || `<div class=\"at-recent-vide\">Aucune mesure pour l'instant</div>`;\n\n  // v4.9 : champs de saisie construits depuis les crit\u00e8res actifs du sc\u00e9nario \u2014\n  // battement (respecte les c\u00f4t\u00e9s choisis, peut \u00eatre d\u00e9sactiv\u00e9) puis crit\u00e8res\n  // suppl\u00e9mentaires (Ra, VE, libres) avec une case par axe.\n  const cotesAt = battCotesDe(sc);\n  const champs = [];\n  if(sc.battActif !== false){\n    if(cotesAt === \"mono\") champs.push(`<div class=\"at-champ\"><label>${escapeAttr(libelleDe(sc))}</label><input type=\"number\" step=\"0.001\" inputmode=\"decimal\" id=\"atV\" placeholder=\"0,000\"></div>`);\n    else {\n      if(cotesAt !== \"G\") champs.push(`<div class=\"at-champ\"><label>Droite</label><input type=\"number\" step=\"0.001\" inputmode=\"decimal\" id=\"atD\" placeholder=\"0,000\"></div>`);\n      if(cotesAt !== \"D\") champs.push(`<div class=\"at-champ\"><label>Gauche</label><input type=\"number\" step=\"0.001\" inputmode=\"decimal\" id=\"atG\" placeholder=\"0,000\"></div>`);\n    }\n  }\n  criteresSupActifs(sc).forEach(c => {\n    axesDe(c).forEach(ax => {\n      const suf = ax === \"v\" ? \"\" : \" \" + (AXE_LABELS[ax] || ax);\n      champs.push(`<div class=\"at-champ\"><label>${escapeAttr(c.label || \"crit\u00e8re\")}${suf}</label><input type=\"number\" step=\"0.001\" inputmode=\"decimal\" id=\"atCs_${c.id}_${ax}\" placeholder=\"0,000\"></div>`);\n    });\n  });\n  const champUsure = `<div class=\"at-champ\"><label>Usure plaquette</label>\n    <select id=\"atUsure\"><option value=\"\">\u2014</option><option value=\"ok\">OK</option><option value=\"limite\">Usure limite</option><option value=\"changer\">\u00c0 changer</option></select>\n  </div>`;\n\n  return `\n    <div class=\"at-head\">\n      <div>\n        <div class=\"at-titre\">${escapeAttr(essai.titre)}</div>\n        <div class=\"at-sous\">${escapeAttr(sc.name)} \u2014 tol\u00e9rance ${fmt(parseFloat(limiteDe(sc)),3)}</div>\n      </div>\n      <button class=\"ghost at-close\" id=\"atelierClose\">Fermer</button>\n    </div>\n\n    ${snap.length > 1 ? `<div class=\"at-logements\">${snap.map(l => {\n      const nom = nomLogementActuel(sc, l); // v4.22 : nom actuel du scenario\n      return `<button class=\"at-log ${l.logementId===atelierCtx.logementId?\"actif\":\"\"}\" data-at-log=\"${l.logementId}\">\n        ${escapeAttr(nom.outilNumero||\"?\")}<span>${escapeAttr(nom.logementNom||\"\u2014\")}</span>\n      </button>`; }).join(\"\")}</div>` : \"\"}\n\n    <div class=\"at-piece\">\n      <label>N\u00b0 pi\u00e8ce</label>\n      <div class=\"at-piece-row\">\n        <button class=\"at-step\" data-at-piece=\"-\">\u2212</button>\n        <input type=\"number\" inputmode=\"numeric\" id=\"atPiece\" value=\"${piece}\">\n        <button class=\"at-step\" data-at-piece=\"+\">+</button>\n      </div>\n      ${prog && prog.target ? `<div class=\"at-prog\"><div class=\"at-prog-bar\"><i style=\"width:${pct}%\"></i></div>\n        <span>${prog.lastPiece ?? 0} / ${prog.target} p \u2014 ${escapeAttr(prog.logementNom||\"\")}</span></div>` : \"\"}\n      ${viseeAtteinte ? `<div class=\"at-charniere${piece > prog.target ? \" depassee\" : \"\"}\">${piece > prog.target\n        ? `\u25ce Au-del\u00e0 de la charni\u00e8re vis\u00e9e (${prog.target} p) \u2014 la dur\u00e9e de vie d\u00e9passe l'objectif : prolongez tant que la cote tient, ou cl\u00f4turez l'essai.`\n        : `\u25ce Cette pi\u00e8ce atteint la charni\u00e8re vis\u00e9e (${prog.target} p) \u2014 resserrez le pas de mesure vers la fin, ou d\u00e9cidez : prolonger / arr\u00eater.`}</div>` : \"\"}\n    </div>\n\n    ${points.length ? `<div class=\"at-points\">\n      <label>Point de mesure</label>\n      <div class=\"at-points-row\">\n        ${points.map(p => `<button class=\"at-pm ${p===pmActif?\"actif\":\"\"}\" data-at-pm=\"${escapeAttr(p)}\">${escapeAttr(p)}</button>`).join(\"\")}\n        <button class=\"at-pm ${pmActif===\"\"?\"actif\":\"\"}\" data-at-pm=\"\">\u2014</button>\n      </div>\n    </div>` : \"\"}\n\n    <div class=\"at-champs\">${champs.join(\"\")}${champUsure}</div>\n\n    <button class=\"primary at-valider\" id=\"atelierValider\">Enregistrer et pi\u00e8ce suivante</button>\n\n    <div class=\"at-recent\">\n      <div class=\"at-recent-t\">Derni\u00e8res mesures</div>\n      ${dernieres}\n    </div>\n  `;\n}\nfunction renderAtelier(){\n  const el = document.getElementById(\"atelierPanel\");\n  if(!el || el.hidden) return;\n  el.innerHTML = atelierHTML();\n\n  const fermer = () => { el.hidden = true; atelierCtx = null; document.body.classList.remove(\"atelier-on\"); render(); };\n  const cb = document.getElementById(\"atelierClose\");\n  if(cb) cb.addEventListener(\"click\", fermer);\n\n  el.querySelectorAll(\"[data-at-log]\").forEach(b => b.addEventListener(\"click\", () => {\n    atelierCtx.logementId = b.getAttribute(\"data-at-log\"); renderAtelier();\n  }));\n  el.querySelectorAll(\"[data-at-pm]\").forEach(b => b.addEventListener(\"click\", () => {\n    atelierCtx.pointMesure = b.getAttribute(\"data-at-pm\"); renderAtelier();\n  }));\n  el.querySelectorAll(\"[data-at-piece]\").forEach(b => b.addEventListener(\"click\", () => {\n    const inp = document.getElementById(\"atPiece\");\n    const v = parseFloat(inp.value); if(isNaN(v)) return;\n    inp.value = Math.max(1, v + (b.getAttribute(\"data-at-piece\")===\"+\" ? 1 : -1));\n  }));\n\n  const valider = () => {\n    const sc = data.find(s => s.id === atelierCtx.scId);\n    const essai = sc && (sc.essais||[]).find(e => e.id === atelierCtx.essaiId);\n    if(!sc || !essai) return;\n    const piece = document.getElementById(\"atPiece\").value;\n    const row = { id:\"p\"+Math.random().toString(36).slice(2), piece, batt:\"\", battD:\"\", battG:\"\", usure:\"\",\n                  logementId: atelierCtx.logementId || \"\", pointMesure: atelierCtx.pointMesure || \"\" };\n    // v4.9 : battement selon les c\u00f4t\u00e9s actifs, puis crit\u00e8res suppl\u00e9mentaires (une case par axe)\n    const cotesAt = battCotesDe(sc);\n    if(sc.battActif !== false){\n      if(cotesAt === \"mono\") row.batt = document.getElementById(\"atV\") ? document.getElementById(\"atV\").value : \"\";\n      else {\n        if(cotesAt !== \"G\") row.battD = document.getElementById(\"atD\") ? document.getElementById(\"atD\").value : \"\";\n        if(cotesAt !== \"D\") row.battG = document.getElementById(\"atG\") ? document.getElementById(\"atG\").value : \"\";\n      }\n    }\n    let nbValeurs = [row.batt, row.battD, row.battG].filter(v => v !== \"\" && v != null).length;\n    criteresSupActifs(sc).forEach(c => {\n      axesDe(c).forEach(ax => {\n        const inp = document.getElementById(\"atCs_\" + c.id + \"_\" + ax);\n        if(!inp || inp.value === \"\") return;\n        row.valeurs = row.valeurs || {};\n        row.valeurs[c.id] = row.valeurs[c.id] || {};\n        row.valeurs[c.id][ax] = inp.value;\n        nbValeurs++;\n      });\n    });\n    if(nbValeurs === 0){ dialogueAlerte(\"Saisissez au moins une valeur mesur\u00e9e.\", \"Mesure incompl\u00e8te\"); return; }\n    const usureSel = document.getElementById(\"atUsure\");\n    if(usureSel) row.usure = usureSel.value;\n    essai.prelevements.push(row);\n    toucherEssai(essai);\n    essai.prelevements.sort((a,b)=>{\n      const va=parseFloat(a.piece), vb=parseFloat(b.piece);\n      if(isNaN(va)&&isNaN(vb)) return 0; if(isNaN(va)) return 1; if(isNaN(vb)) return -1; return va-vb;\n    });\n    saveData();\n    // retour visuel immediat : conforme ou non\n    const c = checkConform(sc, row);\n    renderAtelier();\n    const flash = document.createElement(\"div\");\n    flash.className = \"at-flash \" + (c===false?\"bad\":c===true?\"ok\":\"na\");\n    flash.textContent = c===false ? \"\u26a0 Hors tol\u00e9rance \u2014 pi\u00e8ce \" + piece : c===true ? \"\u2713 Conforme \u2014 pi\u00e8ce \" + piece : \"Enregistr\u00e9 \u2014 pi\u00e8ce \" + piece;\n    document.getElementById(\"atelierPanel\").appendChild(flash);\n    setTimeout(()=>flash.remove(), 1800);\n  };\n  const vb = document.getElementById(\"atelierValider\");\n  if(vb) vb.addEventListener(\"click\", valider);\n  // Entree depuis n'importe quel champ = enregistrer (pas besoin de viser le bouton)\n  el.querySelectorAll('input[type=\"number\"]').forEach(i => i.addEventListener(\"keydown\", e => {\n    if(e.key === \"Enter\"){ e.preventDefault(); valider(); }\n  }));\n  const premier = document.getElementById(\"atD\") || document.getElementById(\"atV\");\n  if(premier) premier.focus();\n}\nfunction ouvrirAtelier(scId, essaiId){\n  atelierCtx = { scId, essaiId, logementId:\"\", pointMesure:\"\" };\n  const el = document.getElementById(\"atelierPanel\");\n  el.hidden = false;\n  document.body.classList.add(\"atelier-on\");\n  renderAtelier();\n}\n\nfunction scrapStats(sc){\n  const rows = sc.scrapLog || [];\n  let totalProd = 0, totalRebut = 0;\n  rows.forEach(r => {\n    const p = parseFloat(r.produites), rb = parseFloat(r.rebutees);\n    if(!isNaN(p)) totalProd += p;\n    if(!isNaN(rb)) totalRebut += rb;\n  });\n  const rate = totalProd > 0 ? (totalRebut/totalProd)*100 : null;\n  return { count: rows.length, totalProd, totalRebut, rate };\n}\n\n/* v4.20 \u2014 d'o\u00f9 vient le taux de rebut d'un sc\u00e9nario. Deux canaux : la saisie annuelle\n   (tauxRebutAnnuel, le chiffre Stellantis sur l'ann\u00e9e, rentr\u00e9 par Matis sur le sc\u00e9nario\n   de r\u00e9f\u00e9rence puis affin\u00e9 par essai) et le journal d'\u00e9quipe (scrapLog, calcul\u00e9). LA\n   SAISIE FAIT FOI quand elle est remplie \u2014 le journal continue de tracer le d\u00e9tail par\n   \u00e9quipe, mais ce n'est plus lui qui p\u00e8se dans le bilan. Un seul point de v\u00e9rit\u00e9 quel\n   que soit le canal, pour le co\u00fbt pi\u00e8ce comme pour le gain annuel. */\nfunction tauxRebutDe(sc){\n  const manuel = parseFloat(sc.tauxRebutAnnuel);\n  if(!isNaN(manuel) && manuel >= 0) return { taux: manuel, source: \"saisi\" };\n  const r = scrapStats(sc).rate;\n  return r === null ? null : { taux: r, source: \"journal\" };\n}\n\n/* ---- modules optionnels ---- */\nfunction coutRebutPiece(sc, cfg){\n  cfg = cfg || config;\n  if(!cfg.coutRebutActif) return null;\n  const cd = parseFloat(cfg.coutDisque);\n  const tr = tauxRebutDe(sc);\n  if(isNaN(cd) || tr === null) return null;\n  return (tr.taux/100) * cd;\n}\n\n/* ---- pieces detachees : amorties comme une plaquette, mais sur leur propre charniere\n   de remplacement, et rattachees au porte-outil (un scenario = un montage) ---- */\nfunction pieceCost(p){\n  const prix = parseFloat(p.prix), ch = parseFloat(p.charniere);\n  if(!prix || !ch) return null;\n  return prix / ch;\n}\nfunction coutPiecesDetachees(sc, cfg){\n  cfg = cfg || config;\n  if(!cfg.piecesActif) return null;\n  const costs = (sc.outils||[]).flatMap(o => (o.pieces||[]).map(pieceCost)).filter(v => v !== null);\n  if(!costs.length) return null;\n  return costs.reduce((a,b) => a+b, 0);\n}\n\n/* ---- temps de cycle reel ----\n   L'indice vaut 100 x (Vc.f reference)/(Vc.f) : c'est un indice de TEMPS COUPANT, pas de\n   cycle complet. L'appliquer au cycle entier surestime la penalite, puisque chargement,\n   approche et retrait ne bougent pas avec Vc/f. On ne fait donc varier que la part\n   coupante declaree. */\n/* ---- detail du cycle par logement : temps coupe + deplacement mesures machine ----\n   L'indice base 100 ci-dessus applique un seul ratio a tout le cycle coupant du scenario.\n   Ca tient quand tous les logements changent ensemble (process CBN -> ceramique integrale),\n   mais ne represente plus rien des qu'un scenario est mixte (un seul cote change, ex.\n   \"bol CBN + piste ceramique\") : le ratio global melange alors deux realites differentes.\n   Ce module remplace l'indice par une mesure reelle, par logement, releve sur machine \u2014\n   uniquement si TOUS les logements du scenario sont renseignes (coupe ET deplacement) ;\n   sinon on retombe silencieusement sur l'indice base 100 pour ne jamais afficher un total\n   partiel qui aurait l'air complet. */\nfunction cycleDetailStatus(sc, cfg){\n  cfg = cfg || config;\n  /* v4.41 \u2014 la physique d'une OP, par groupes d'outils : DANS un outil, les logements\n     encha\u00eenent toujours \u00e0 la suite (somme) ; un outil coch\u00e9s \u00ab simultan\u00e9 avec le\n     pr\u00e9c\u00e9dent \u00bb rejoint le groupe de son voisin \u2014 le groupe vaut le temps de son outil\n     le plus long, et le cycle est la somme des groupes. Aucune case coch\u00e9e = outils en\n     s\u00e9rie (somme de tout). Le temps de d\u00e9placement reste hors calcul (invariant). */\n  const outils = sc.outils || [];\n  let filled = 0, total = 0;\n  const groupes = [];\n  outils.forEach((o, idx) => {\n    let s = 0;\n    (o.logements||[]).forEach(l => {\n      total++;\n      const c = parseFloat(l.tempsCoupe);\n      if(!isNaN(c)){ filled++; s += c; }\n    });\n    if(idx > 0 && o.simultaneAvecPrecedent && groupes.length) groupes[groupes.length-1].push(s);\n    else groupes.push([s]);\n  });\n  const complete = total > 0 && filled === total;\n  const denom = groupes.reduce((acc,g) => acc + Math.max(...g), 0);\n  const secs = complete ? denom : null;\n  return { actif: !!(cfg && cfg.cycleDetailActif), complete, filled, total, secs,\n           nbGroupes: groupes.length, nbOutils: outils.length };\n}\n/* statut affich\u00e9 sous la composition du scenario : dit clairement quel calcul est\n   REELLEMENT utilise pour ce scenario, puisque le detail par logement retombe\n   silencieusement sur l'indice base 100 des qu'un seul logement manque */\nfunction cycleDetailStatusHTML(sc){\n  const st = cycleDetailStatus(sc, config);\n  // v4.39 \u2014 la ligne n'appara\u00eet que si les mesures sont commenc\u00e9es ou si le module est\n  // affich\u00e9 : pas d'avertissement permanent sur un sc\u00e9nario qui n'a jamais saisi de temps.\n  if(!st.total || (!st.filled && !st.actif)) return \"\";\n  const mode = st.nbGroupes < st.nbOutils\n    ? st.nbGroupes + \" groupe\" + (st.nbGroupes>1?\"s\":\"\") + \" d'outils simultan\u00e9s \u2014 cycle = somme des groupes, chaque groupe valant son outil le plus long\"\n    : \"outils en s\u00e9rie \u2014 cycle = somme des temps\";\n  return st.complete\n    ? `<p class=\"panel-hint cycle-detail-ok\">\u2713 ${st.filled}/${st.total} logements renseign\u00e9s \u2014 temps de cycle calcul\u00e9 sur mesures machine (${fmt(st.secs,1)} s \u00b7 ${mode}).</p>`\n    : `<p class=\"panel-hint cycle-detail-ko\">\u26a0 ${st.filled}/${st.total} logements renseign\u00e9s (temps de coupe) \u2014 incomplet, ce sc\u00e9nario retombe sur l'indice base 100 tant que tous les logements ne sont pas renseign\u00e9s.</p>`;\n}\nfunction cycleSecondes(sc, cfg){\n  cfg = cfg || config;\n  /* v4.39 \u2014 les mesures machine comptent d\u00e8s qu'elles sont compl\u00e8tes, sans interrupteur :\n     la r\u00e8gle \u00ab tous les logements ou rien \u00bb est le garde-fou, pas une option. L'option\n     \u00ab d\u00e9tail du cycle \u00bb ne d\u00e9cide plus que de l'affichage de la colonne \u00e0 l'impression. */\n  const det = cycleDetailStatus(sc, cfg);\n  if(det.complete) return det.secs;\n  const ref = parseFloat(cfg.cycleRefSec);\n  const idx = parseFloat(sc.cycle);\n  if(isNaN(ref) || isNaN(idx)) return null;\n  let part = parseFloat(cfg.partCoupante);\n  if(isNaN(part)) part = 100;\n  part = Math.min(100, Math.max(0, part)) / 100;\n  return (ref * part) * (idx/100) + ref * (1 - part);\n}\nfunction cadenceHeure(sc, cfg){\n  const s = cycleSecondes(sc, cfg);\n  return (s && s > 0) ? 3600/s : null;\n}\n/* le temps machine devient un cout : c'est ce qui rend comparables un scenario moins cher\n   en plaquettes mais plus lent, et un scenario rapide mais gourmand en outil */\nfunction coutMachinePiece(sc, cfg, ligne){\n  cfg = cfg || config;\n  if(!cfg.coutMachineActif) return null;\n  const l = ligne || getActiveLigne();\n  const taux = l ? parseFloat(l.coutHoraire) : NaN;\n  const s = cycleSecondes(sc, cfg);\n  if(isNaN(taux) || s === null) return null;\n  return (taux/3600) * s;\n}\n\n/* ---- cout complet, composante par composante ----\n   Un seul point de verite : tout l'affichage economique passe par ici. */\nfunction coutsDetail(sc, cfg, ligne){\n  cfg = cfg || config;\n  const plaquettes = scenarioCost(sc);\n  const pieces = coutPiecesDetachees(sc, cfg);\n  const machine = coutMachinePiece(sc, cfg, ligne);\n  const rebut = coutRebutPiece(sc, cfg);\n  const parts = [plaquettes, pieces, machine, rebut];\n  const total = parts.some(v => v !== null) ? parts.reduce((a,b) => a + (b||0), 0) : null;\n  return { plaquettes, pieces, machine, rebut, total,\n           multiPoste: parts.filter(v => v !== null).length > 1 };\n}\nfunction coutTotalPiece(sc, cfg, ligne){\n  return coutsDetail(sc, cfg, ligne).total;\n}\n/* v4.45 \u2014 p\u00e9rim\u00e8tre de comparaison synchronis\u00e9 : un poste n'entre dans un delta que\n   s'il est chiffrable DES DEUX c\u00f4t\u00e9s (sc\u00e9nario ET r\u00e9f\u00e9rence). Comparer un total avec\n   machine \u00e0 un total sans (cas typique : l'essai a des mesures de cycle compl\u00e8tes,\n   la r\u00e9f\u00e9rence non) faisait para\u00eetre le sc\u00e9nario plus cher qu'il n'\u00e9tait.\n   Retourne les postes communs, les postes exclus (avec leur libell\u00e9) et les deux\n   totaux sur le p\u00e9rim\u00e8tre commun. */\nfunction perimetreCompare(couts, coutsBase){\n  const postes = [\n    [\"plaquettes\", \"plaquettes\"],\n    [\"machine\", \"temps machine\"],\n    [\"rebut\", \"co\u00fbt du rebut\"],\n    [\"pieces\", \"pi\u00e8ces d\u00e9tach\u00e9es\"]\n  ];\n  const communs = [], exclus = [];\n  postes.forEach(([cle, lib]) => {\n    const a = couts[cle], b = coutsBase ? coutsBase[cle] : null;\n    if(a !== null && b !== null) communs.push([cle, lib]);\n    else if(a !== null || b !== null) exclus.push(lib);\n  });\n  const somme = cs => communs.reduce((acc,[cle]) => acc + (cs[cle] || 0), 0);\n  return { communs, exclus, sc: somme(couts), base: coutsBase ? somme(coutsBase) : null };\n}\n\n/* ---- charniere reellement atteinte ----\n   On ne peut affirmer qu'une duree de vie a ete tenue que jusqu'au dernier prelevement\n   conforme precedant une sortie de tolerance. Si aucun essai n'est sorti de tolerance,\n   la valeur est une BORNE INFERIEURE : l'essai s'arrete a la charniere visee, on ne sait\n   rien de ce qui se serait passe au-dela. */\nfunction charniereReelle(sc, logementId){\n  const atteintes = [];\n  let borneInf = true;\n  (sc.essais || []).forEach(es => {\n    const prels = (es.prelevements || [])\n      .filter(r => !logementId || !r.logementId || r.logementId === logementId)\n      .slice()\n      .sort((a,b) => (parseFloat(a.piece)||0) - (parseFloat(b.piece)||0));\n    if(!prels.length) return;\n    let derniereConforme = null, echec = false;\n    for(const r of prels){\n      if(checkConform(sc, r) === false){ echec = true; break; }\n      const p = parseFloat(r.piece);\n      if(!isNaN(p)) derniereConforme = p;\n    }\n    // sortie de tolerance des le premier prelevement : la duree de vie observee est nulle,\n    // il faut le voir plutot que d'ignorer l'essai en silence\n    if(derniereConforme !== null || echec){\n      atteintes.push(derniereConforme ?? 0);\n      if(echec) borneInf = false;\n    }\n  });\n  if(!atteintes.length) return null;\n  return { moyenne: atteintes.reduce((a,b)=>a+b,0) / atteintes.length,\n           essais: atteintes.length, borneInf, min: Math.min(...atteintes) };\n}\n/* logements dont la duree de vie observee est retombee sous la charniere visee :\n   c'est la que le business case se fissure, il faut le voir tout de suite */\nfunction ecartsCharniere(sc, cfg){\n  cfg = cfg || config;\n  const marge = parseFloat(cfg.ecartCharniereTolerance);\n  const out = [];\n  (sc.outils||[]).forEach(o => o.logements.forEach(l => {\n    const cible = parseFloat(l.charniere);\n    const reel = charniereReelle(sc, l.id);\n    if(isNaN(cible) || !reel || reel.borneInf) return;\n    if(reel.moyenne < cible - (isNaN(marge) ? 0.5 : marge)){\n      const prix = parseFloat(l.prix), aretes = parseFloat(l.aretes);\n      out.push({ outilNumero: o.numero, logementNom: l.nom, cible, reel: reel.moyenne, essais: reel.essais,\n        coutReel: (prix && aretes && reel.moyenne) ? prix/(aretes*reel.moyenne) : null,\n        coutCible: (prix && aretes && cible) ? prix/(aretes*cible) : null });\n    }\n  }));\n  return out;\n}\n\n/* ---- volume annuel : convertit chaque ecart en euros et en heures machine ---- */\nfunction volumeAnnuel(ref, cfg){\n  cfg = cfg || config;\n  if(!cfg.volumeActif) return null;\n  const r = ref || getActiveReference();\n  const v = r ? parseFloat(r.productionAnnuelle) : NaN;\n  return (isNaN(v) || v <= 0) ? null : v;\n}\n/* v4.23 \u2014 l'\u00e9criture du volume annuel est trac\u00e9e SUR la r\u00e9f\u00e9rence : chaque changement\n   enregistre valeur, auteur et date (10 derni\u00e8res). R\u00f4le double : documenter les mont\u00e9es\n   en cadence, et pouvoir dire QUI a \u00e9crit QUOI QUAND si deux r\u00e9f\u00e9rences se retrouvent\n   avec la valeur de l'autre \u2014 le champ Options porte d\u00e9sormais sa cible en toutes\n   lettres, et la tuile de la composition emm\u00e8ne directement au bon champ. */\nfunction enregistrerVolumeAnnuel(ref, nv){\n  if(!ref) return;\n  if(String(ref.productionAnnuelle ?? \"\") !== String(nv)){\n    ref.volumeHistorique = ref.volumeHistorique || [];\n    ref.volumeHistorique.unshift({ valeur: nv, par: auteurNom || \"?\", date: new Date().toISOString() });\n    if(ref.volumeHistorique.length > 10) ref.volumeHistorique.length = 10;\n  }\n  ref.productionAnnuelle = nv;\n}\n/* consommation annuelle de plaquettes d'un logement : le carnet de commandes, en clair */\nfunction plaquettesParAn(l, volume){\n  const a = parseFloat(l.aretes), c = parseFloat(l.charniere);\n  if(!volume || !a || !c) return null;\n  return volume / (a * c);\n}\nfunction bilanAnnuel(sc, cfg, ligne, ref, baseCmp){\n  cfg = cfg || config;\n  const volume = volumeAnnuel(ref, cfg);\n  if(!volume) return null;\n  const base = baseCmp || baselineScenario();\n  const cSc = coutsDetail(sc, cfg, ligne);\n  const out = { volume, coutAnnuel: cSc.total === null ? null : cSc.total * volume };\n  if(base && base.id !== sc.id){\n    const cBase = coutsDetail(base, cfg, ligne);\n    /* v4.45 \u2014 le gain annuel ne m\u00e9lange plus les p\u00e9rim\u00e8tres : poste commun seulement,\n       et drapeau perimetrePartiel quand un poste n'est chiffrable que d'un c\u00f4t\u00e9. */\n    const peri = perimetreCompare(cSc, cBase);\n    if(peri.communs.length && peri.base > 0) out.gainAnnuel = (peri.base - peri.sc) * volume;\n    if(peri.exclus.length) out.perimetrePartiel = peri.exclus;\n    const sBase = cycleSecondes(base, cfg), sSc = cycleSecondes(sc, cfg);\n    if(sBase !== null && sSc !== null) out.heuresAnnuelles = ((sSc - sBase) * volume) / 3600;\n  }\n  out.plaquettes = (sc.outils||[]).flatMap(o => o.logements.map(l => ({\n    outilNumero: o.numero, logementNom: l.nom, ref: l.ref, nb: plaquettesParAn(l, volume)\n  }))).filter(p => p.nb !== null);\n  return out;\n}\n\n/* v4.29 \u2014 d\u00e9tail d\u00e9pliable de la tuile \u00ab Co\u00fbt annuel / Gain annuel \u00bb du pied de\n   sc\u00e9nario : chaque composante du co\u00fbt complet, multipli\u00e9e par la production, et le\n   d\u00e9tail logement par logement pour l'outillage. M\u00eame point de v\u00e9rit\u00e9 que le chiffre\n   de t\u00eate (coutsDetail sans ligne explicite = ligne active en repli), pour que le\n   d\u00e9tail tombe toujours juste sous le total affich\u00e9. Renvoie \"\" si rien \u00e0 d\u00e9tailler. */\nfunction coutAnnuelDetailHTML(sc, annuel){\n  if(!annuel) return \"\";\n  const cfg = config, vol = annuel.volume;\n  const ligne = (l, v) => `<div class=\"foot-detail-l\"><span>${l}</span><b>${v}</b></div>`;\n  const euros = v => fmtEuroCourt(v) + \"/an\";\n  let corps = \"\";\n  const base = baselineScenario();\n  if(!sc.baseline && base && annuel.gainAnnuel !== undefined){\n    const cB = coutsDetail(base, cfg), cS = coutsDetail(sc, cfg);\n    if(cB.total !== null) corps += ligne(\"R\u00e9f\u00e9rence \u00ab \" + (base.name || \"\u2014\") + \" \u00bb : co\u00fbt complet pi\u00e8ce \u00d7 production\",\n      fmt(cB.total,4) + \" \u20ac \u00d7 \" + fmt(vol,0) + \" = \" + euros(cB.total * vol));\n    if(cS.total !== null) corps += ligne(\"Ce sc\u00e9nario : co\u00fbt complet pi\u00e8ce \u00d7 production\",\n      fmt(cS.total,4) + \" \u20ac \u00d7 \" + fmt(vol,0) + \" = \" + euros(cS.total * vol));\n    corps += ligne(\"Gain annuel = r\u00e9f\u00e9rence \u2212 sc\u00e9nario\",\n      (annuel.gainAnnuel >= 0 ? \"+\" : \"\u2212\") + fmtEuroCourt(Math.abs(annuel.gainAnnuel)) + \"/an\" +\n      (annuel.heuresAnnuelles !== undefined ? \" \u00b7 \" + (annuel.heuresAnnuelles >= 0 ? \"+\" : \"\u2212\") + fmt(Math.abs(annuel.heuresAnnuelles),0) + \" h machine/an\" : \"\"));\n    if(annuel.perimetrePartiel && annuel.perimetrePartiel.length)\n      corps += ligne(\"Comparaison hors : \" + annuel.perimetrePartiel.join(\", \"),\n        \"non chiffrable sur la r\u00e9f\u00e9rence\");\n  } else {\n    const cd = coutsDetail(sc, cfg);\n    if(cd.plaquettes !== null){\n      corps += ligne(\"Outillage : co\u00fbt plaquette pi\u00e8ce \u00d7 production\",\n        fmt(cd.plaquettes,4) + \" \u20ac \u00d7 \" + fmt(vol,0) + \" = \" + euros(cd.plaquettes * vol));\n      corps += (sc.outils||[]).flatMap(o => o.logements.map(l => {\n        const pc = posCost(l);\n        if(pc === null) return null;\n        return ligne((o.numero || \"\u2014\") + \" \u00b7 \" + (l.nom || \"\u2014\") + \" (\" + fmt(parseFloat(l.prix),2) + \" \u20ac \u00f7 \" + l.aretes + \" \u00d7 \" + l.charniere + \")\", euros(pc * vol));\n      })).filter(Boolean).join(\"\");\n    }\n    if(cd.pieces !== null) corps += ligne(\"Pi\u00e8ces d\u00e9tach\u00e9es pi\u00e8ce \u00d7 production\", fmt(cd.pieces,4) + \" \u20ac \u00d7 \" + fmt(vol,0) + \" = \" + euros(cd.pieces * vol));\n    if(cd.machine !== null) corps += ligne(\"Temps machine pi\u00e8ce \u00d7 production\", fmt(cd.machine,4) + \" \u20ac \u00d7 \" + fmt(vol,0) + \" = \" + euros(cd.machine * vol));\n    if(cd.rebut !== null) corps += ligne(\"Rebut pi\u00e8ce \u00d7 production\", fmt(cd.rebut,4) + \" \u20ac \u00d7 \" + fmt(vol,0) + \" = \" + euros(cd.rebut * vol));\n    if(cd.total !== null) corps += ligne(\"Total = co\u00fbt complet pi\u00e8ce \u00d7 production\", fmt(cd.total,4) + \" \u20ac \u00d7 \" + fmt(vol,0) + \" = \" + euros(cd.total * vol));\n  }\n  return corps ? `<div class=\"foot-detail-inner\">${corps}</div>` : \"\";\n}\n\n/* ---- seuil de bascule : le point ou le scenario cesse d'etre gagnant ----\n   C'est la question que pose toujours l'atelier : \"jusqu'ou je peux ralentir avant que\n   ca ne vaille plus le coup ?\" */\nfunction seuilBascule(sc, cfg, ligne){\n  cfg = cfg || config;\n  const base = baselineScenario();\n  if(!base || base.id === sc.id) return null;\n  const cBase = coutsDetail(base, cfg, ligne), cSc = coutsDetail(sc, cfg, ligne);\n  if(cBase.total === null || cSc.total === null) return null;\n  const res = { gain: cBase.total - cSc.total };\n  const l = ligne || getActiveLigne();\n  const taux = l ? parseFloat(l.coutHoraire) : NaN;\n  if(cfg.coutMachineActif && !isNaN(taux) && taux > 0){\n    const autres = (cSc.plaquettes||0) + (cSc.pieces||0) + (cSc.rebut||0);\n    const marge = cBase.total - autres;\n    res.cycleMaxSec = marge > 0 ? (marge * 3600 / taux) : 0;\n    res.cycleActuelSec = cycleSecondes(sc, cfg);\n  }\n  const reste = (cSc.pieces||0) + (cSc.machine||0) + (cSc.rebut||0);\n  const marge2 = cBase.total - reste, outil = cSc.plaquettes || 0;\n  // facteur a appliquer aux charnieres pour revenir a l'equilibre (n'a de sens que si on perd)\n  res.facteurCharniere = (res.gain < 0 && marge2 > 0 && outil > 0) ? (outil / marge2) : null;\n  // cas frequent et decisif : hors plaquettes, le scenario coute deja plus cher que la\n  // reference entiere \u2014 aucune duree de vie d'arete ne peut rattraper ca\n  res.charniereImpossible = res.gain < 0 && marge2 <= 0;\n  return res;\n}\n\n/* ---- rendu des blocs economiques ---- */\nconst COUT_POSTES = [\n  { key:\"plaquettes\", label:\"Plaquettes\",       cls:\"cb-plaq\" },\n  { key:\"pieces\",     label:\"Pi\u00e8ces d\u00e9tach\u00e9es\", cls:\"cb-pieces\" },\n  { key:\"machine\",    label:\"Temps machine\",    cls:\"cb-machine\" },\n  { key:\"rebut\",      label:\"Rebut\",            cls:\"cb-rebut\" }\n];\n/* un chiffre agrege seul n'est pas defendable : on montre ou part l'argent */\nfunction coutBreakdownHTML(couts){\n  if(!couts.multiPoste || !couts.total) return \"\";\n  const postes = COUT_POSTES.filter(p => couts[p.key] !== null && couts[p.key] > 0);\n  if(postes.length < 2) return \"\";\n  const segs = postes.map(p =>\n    `<span class=\"cb-seg ${p.cls}\" style=\"width:${(couts[p.key]/couts.total*100).toFixed(2)}%;\" title=\"${p.label} : ${fmt(couts[p.key],4)} \u20ac/pi\u00e8ce\"></span>`).join(\"\");\n  const legende = postes.map(p =>\n    `<span class=\"cb-item\"><i class=\"cb-dot ${p.cls}\"></i>${p.label} <b>${fmt(couts[p.key],4)}</b></span>`).join(\"\");\n  return `<div class=\"cout-breakdown\"><div class=\"cb-bar\">${segs}</div><div class=\"cb-legend\">${legende}</div></div>`;\n}\n/* \"jusqu'ou je peux ralentir avant que ca ne vaille plus le coup ?\" */\nfunction seuilBasculeHTML(sc){\n  const s = seuilBascule(sc);\n  if(!s) return \"\";\n  const bits = [];\n  if(s.cycleMaxSec !== undefined && s.cycleActuelSec !== null && s.cycleActuelSec !== undefined){\n    const ok = s.cycleActuelSec <= s.cycleMaxSec;\n    bits.push(`<span class=\"seuil-item ${ok ? \"ok\" : \"bad\"}\">\n      <b>${fmt(s.cycleMaxSec,1)} s</b> de cycle maximum pour rester gagnant\n      <em>actuellement ${fmt(s.cycleActuelSec,1)} s \u2014 ${ok ? \"marge de \" + fmt(s.cycleMaxSec - s.cycleActuelSec,1) + \" s\" : \"d\u00e9pass\u00e9 de \" + fmt(s.cycleActuelSec - s.cycleMaxSec,1) + \" s\"}</em>\n    </span>`);\n  }\n  if(s.facteurCharniere){\n    bits.push(`<span class=\"seuil-item bad\">Multiplier vos charni\u00e8res par <b>\u00d7${fmt(s.facteurCharniere,2)}</b> pour revenir \u00e0 l'\u00e9quilibre<em>\u00e0 conditions de coupe inchang\u00e9es</em></span>`);\n  } else if(s.charniereImpossible){\n    bits.push(`<span class=\"seuil-item bad\"><b>Aucune dur\u00e9e de vie ne compense</b><em>hors plaquettes, ce sc\u00e9nario d\u00e9passe d\u00e9j\u00e0 la r\u00e9f\u00e9rence : le levier n'est pas l'outil</em></span>`);\n  }\n  if(!bits.length) return \"\";\n  return `<div class=\"seuil-strip\"><span class=\"seuil-lab\">Seuil de bascule</span><div class=\"seuil-items\">${bits.join(\"\")}</div></div>`;\n}\n/* la ou le business case se fissure : la duree de vie promise n'a pas tenu */\nfunction ecartsCharniereHTML(sc){\n  const ecarts = ecartsCharniere(sc);\n  if(!ecarts.length) return \"\";\n  const items = ecarts.map(e => `<li><b>${escapeAttr(e.outilNumero||\"\u2014\")} \u00b7 ${escapeAttr(e.logementNom||\"\u2014\")}</b> \u2014 vis\u00e9e ${fmt(e.cible,0)} p/ar\u00eate, observ\u00e9e <b>${fmt(e.reel,0)}</b> sur ${e.essais} essai${e.essais>1?\"s\":\"\"}${\n    e.coutReel !== null ? ` \u2192 co\u00fbt r\u00e9el <b>${fmt(e.coutReel,4)} \u20ac</b> au lieu de ${fmt(e.coutCible,4)} \u20ac` : \"\"}</li>`).join(\"\");\n  return `<div class=\"note reality-note\">\n    <b>Dur\u00e9e de vie observ\u00e9e sous la cible</b> \u2014 un ou plusieurs logements sont sortis de tol\u00e9rance avant la charni\u00e8re vis\u00e9e. Le co\u00fbt affich\u00e9 plus haut reste calcul\u00e9 sur la charni\u00e8re vis\u00e9e : c'est l'objectif, pas encore le constat.\n    <ul>${items}</ul>\n  </div>`;\n}\n\nfunction escapeAttr(s){\n  return String(s ?? \"\").replace(/&/g,\"&amp;\").replace(/\"/g,\"&quot;\").replace(/</g,\"&lt;\");\n}\n\n/* ---- graphique de tendance ---- */\nconst CHART_COLORS = [\"#3b82f6\",\"#14b8a6\",\"#a78bfa\",\"#f59e0b\",\"#22c55e\",\"#94a3b8\",\"#ec4899\",\"#0ea5e9\"];\n\n/* v4.15 \u2014 mesure exprim\u00e9e en % de la tol\u00e9rance consomm\u00e9e : 100 % = la borne maxi, 0 % =\n   la borne mini si elle existe (plage min\u2013max), sinon z\u00e9ro. Permet de superposer sur une\n   m\u00eame lecture des grandeurs physiquement diff\u00e9rentes (battement, Ra, VE) \u2014 en option\n   d'affichage seulement : un pourcentage reste une normalisation, pas une mesure. */\nfunction pourcentageTolerance(y, limite, mini){\n  const L = parseFloat(limite), M = parseFloat(mini);\n  if(!isNaN(M) && !isNaN(L) && L > M) return (y - M) / (L - M) * 100;\n  if(!isNaN(L) && L !== 0) return y / L * 100;\n  return null;\n}\n/* palette dediee aux points partageant le meme n\u00b0 de piece (ex. mesures Inter/Exter\n   d'une meme piece) : volontairement distincte de CHART_COLORS (couleur de courbe) et\n   du rouge (reserve au hors-tolerance), pour ne pas creer de confusion visuelle */\nconst POINT_COLORS = [\"#d946ef\",\"#f97316\",\"#0891b2\",\"#65a30d\",\"#7c3aed\",\"#0d9488\",\"#ca8a04\",\"#2563eb\"];\n/* couleur deterministe par texte de point de mesure (Inter/Exter/Droite/Gauche...) : basee\n   sur un hash du texte, pas sur l'ordre d'apparition, pour que \"Inter\" soit TOUJOURS la\n   meme couleur partout, quel que soit l'essai ou l'ordre de saisie */\nfunction couleurPointMesure(txt){\n  const cle = String(txt||\"\").trim().toLowerCase();\n  if(!cle) return null;\n  let h = 0;\n  for(let i=0;i<cle.length;i++) h = (h*31 + cle.charCodeAt(i)) >>> 0;\n  return POINT_COLORS[h % POINT_COLORS.length];\n}\n/* motifs de trait, pour rester lisible en impression noir et blanc (pas seulement par la couleur) */\nconst STROKE_DASH = [\"none\",\"7 4\",\"2 3\",\"10 3 2 3\",\"1 4\",\"5 2 1 2\",\"9 2\",\"3 2 1 2 1 2\"];\nfunction dashAttr(d){ return (!d || d === \"none\") ? \"\" : ` stroke-dasharray=\"${d}\"`; }\nfunction dashSwatch(couleur, dash){\n  return `<svg width=\"22\" height=\"10\" viewBox=\"0 0 22 10\" style=\"vertical-align:middle; overflow:visible;\"><line x1=\"1\" y1=\"5\" x2=\"21\" y2=\"5\" stroke=\"${couleur}\" stroke-width=\"2.4\"${dashAttr(dash)}/></svg>`;\n}\n\nfunction valeurMesuree(sc, row){\n  if(sc.emag1){\n    const vals = [parseFloat(row.battD), parseFloat(row.battG)].filter(v => !isNaN(v));\n    return vals.length ? Math.max(...vals) : null;\n  }\n  const b = parseFloat(row.batt);\n  return isNaN(b) ? null : b;\n}\n\n/* construit les s\u00e9ries d'un crit\u00e8re : un essai men\u00e9 en parall\u00e8le sur plusieurs logements\n   est scind\u00e9 en une courbe par logement ; un essai classique garde une courbe unique */\nfunction seriesTendance(sc, valeurFn){\n  const series = [];\n  (sc.essais||[]).forEach(es => {\n    const prels = es.prelevements || [];\n    const utiliseLogements = prels.some(r => r.logementId);\n    const pousse = (titre, rows) => {\n      const pts = rows.map(r => ({ x: parseFloat(r.piece), y: valeurFn(r), pointMesure: r.pointMesure || \"\" }))\n        .filter(p => !isNaN(p.x) && p.y !== null)\n        .sort((a,b) => a.x - b.x);\n      if(pts.length) series.push({ titre, pts });\n    };\n    if(utiliseLogements){\n      logementsSuivis(es).forEach(lp => {\n        const nom = nomLogementActuel(sc, lp);\n        pousse(`${es.titre} (${nom.outilNumero}\u00b7${nom.logementNom})`, prels.filter(r => r.logementId === lp.logementId));\n      });\n    } else {\n      pousse(es.titre, prels);\n    }\n  });\n  return series;\n}\n\nfunction groupesTendance(sc){\n  /* v4.11 \u2014 la Tendance trace QUELQUE SOIT le crit\u00e8re \u00e9valu\u00e9 : le battement (s'il est\n     actif), puis chaque crit\u00e8re suppl\u00e9mentaire (Ra, VE, crit\u00e8re libre). Un graphe par\n     crit\u00e8re \u2014 les \u00e9chelles ne se m\u00e9langent pas \u2014 et \u00e0 l'int\u00e9rieur une courbe (une\n     couleur) par axe : les \u00e9volutions Inter et Exter se lisent s\u00e9par\u00e9ment d'un coup\n     d'\u0153il, avec leur ligne de tol\u00e9rance propre. */\n  const groupes = [];\n  if(sc.battActif !== false){\n    groupes.push({\n      label: libelleDe(sc),\n      tolerance: parseFloat(limiteDe(sc)),\n      toleranceMini: NaN,\n      note: sc.emag1 ? \"valeur trac\u00e9e : max(Droite, Gauche)\" : \"\",\n      series: seriesTendance(sc, r => valeurMesuree(sc, r))\n    });\n  }\n  criteresSupActifs(sc).forEach(c => {\n    const series = [];\n    axesDe(c).forEach(ax => {\n      seriesTendance(sc, r => {\n        const v = ((r.valeurs || {})[c.id] || {})[ax];\n        const n = parseFloat(v);\n        return isNaN(n) ? null : n;\n      }).forEach(s => series.push({\n        titre: s.titre + (ax !== \"v\" ? \" \u2014 \" + (AXE_LABELS[ax] || ax) : \"\"),\n        pts: s.pts\n      }));\n    });\n    groupes.push({\n      label: c.label || \"crit\u00e8re\",\n      tolerance: parseFloat(c.maxi),\n      toleranceMini: c.miniActif ? parseFloat(c.mini) : NaN,\n      note: \"\",\n      series\n    });\n  });\n  return groupes;\n}\n\nfunction chartHTML(sc){\n  const sections = groupesTendance(sc).filter(g => g.series.length).map(g => tendanceChartHTML(sc, g));\n  if(!sections.length){\n    return `<div class=\"chart-block\">\n      <h3>Tendance</h3>\n      <p class=\"chart-empty\">Le graphique appara\u00eetra d\u00e8s qu'un pr\u00e9l\u00e8vement sera mesur\u00e9 (n\u00b0 de pi\u00e8ce + valeur).</p>\n    </div>`;\n  }\n  return sections.join(\"\");\n}\n\nfunction tendanceChartHTML(sc, g, pal){\n  // palette param\u00e9trable : variables CSS dans l'outil, couleurs en dur dans le rapport\n  // autonome (qui n'a pas les variables de l'outil)\n  pal = Object.assign({\n    border:\"var(--border)\", faint:\"var(--ink-faint)\", red:\"var(--red)\",\n    blue:\"var(--blue)\", surface:\"var(--surface)\", soft:\"var(--ink-soft)\",\n    mono:\"var(--font-mono)\"\n  }, pal || {});\n  const series = g.series;\n  series.forEach((s, i) => Object.assign(s, { couleur: CHART_COLORS[i % CHART_COLORS.length], dash: STROKE_DASH[i % STROKE_DASH.length] }));\n  // une meme piece peut porter plusieurs points de mesure (ex. Inter/Exter, Droite/Gauche\n  // hors EMAG1) : chaque point de mesure recoit une couleur fixe et coherente sur tout le\n  // graphique (pas seulement au sein d'une piece), pour les identifier au premier coup\n  // d'oeil ET comparer leur tendance respective d'une piece a l'autre. Le rouge reste\n  // reserve au hors-tolerance (deja utilise partout ailleurs dans l'outil).\n  const couleurParPointMesure = new Map();\n  series.forEach(s => s.pts.forEach(p => {\n    const cle = (p.pointMesure || \"\").trim().toLowerCase();\n    if(cle && !couleurParPointMesure.has(cle)){\n      couleurParPointMesure.set(cle, couleurPointMesure(cle));\n    }\n  }));\n\n  const limite = g.tolerance, mini = g.toleranceMini;\n  /* v4.49.2 \u2014 l'\u00e9chelle X suit la charni\u00e8re des logements SUIVIS par les essais trac\u00e9s,\n     pas celle de tout l'outillage du sc\u00e9nario. Depuis \u00ab Compl\u00e9ter depuis la prod \u00bb, un\n     sc\u00e9nario d'essai porte aussi des outils \u00e0 charni\u00e8re tr\u00e8s longue (300, 600, 4000\n     pi\u00e8ces de l'excel) qui ne sont pas suivis par l'essai : leur max \u00e9crasait les\n     pr\u00e9l\u00e8vements r\u00e9els sur une fine bande du graphe (retour Benjamin : \u00ab visibilit\u00e9\n     impact\u00e9e fortement \u00bb). Les logements repr\u00e9sent\u00e9s dans les s\u00e9ries font foi. */\n  const idsSuivis = new Set();\n  (sc.essais||[]).forEach(es => (logementsSuivis(es)||[]).forEach(lp => idsSuivis.add(lp.logementId)));\n  const logementsRepresentes = (sc.outils||[]).flatMap(o => o.logements||[])\n    .filter(l => !idsSuivis.size || idsSuivis.has(l.id));\n  const charnieresSc = logementsRepresentes.map(l => parseFloat(l.charniere)).filter(v => !isNaN(v));\n  const charniere = charnieresSc.length ? Math.max(...charnieresSc) : NaN;\n  // v4.15 \u2014 vue en % de tol\u00e9rance consomm\u00e9e (option d'affichage, jamais par d\u00e9faut) :\n  // 100 % = la limite, 0 % = la borne mini si plage min\u2013max, sinon z\u00e9ro. Normalise la\n  // lecture d'un crit\u00e8re dont on ne conna\u00eet pas les valeurs \u00ab raisonnables \u00bb par coeur.\n  const plageMiniValide = !isNaN(mini) && !isNaN(limite) && limite > mini;\n  const pctUtilisable = !!tendanceEnPct && !isNaN(limite) && limite > 0;\n  const yDe = p => pctUtilisable ? pourcentageTolerance(p.y, limite, plageMiniValide ? mini : NaN) : p.y;\n  const allX = series.flatMap(s => s.pts.map(p => p.x));\n  const allY = series.flatMap(s => s.pts.map(yDe)).filter(v => !isNaN(v));\n  // +8 % a droite (v4.6) : le dernier point (souvent le plus haut n\u00b0 de piece, ou la\n  // charniere elle-meme) tombait exactement sur le bord \u2014 colle au cadre, moitie coupe.\n  let xMax = Math.max(...allX, isNaN(charniere) ? 0 : charniere) * 1.08 || 1;\n  // en %, l'axe est cal\u00e9 sur un multiple de 20 : les graduations tombent rondes\n  // (0 / 30 / 60 / 90 / 120) au lieu de couper un pourcentage \u00e0 vif\n  let yMax = pctUtilisable\n    ? Math.max(Math.ceil(Math.max(...allY, 100) / 20) * 20, 120)\n    : Math.max(...allY, ...[limite, mini].filter(v => !isNaN(v))) * 1.18 || 1;\n\n  const W = 720, H = 250, ml = 58, mr = 14, mt = 12, mb = 38;\n  const iw = W - ml - mr, ih = H - mt - mb;\n  const X = v => ml + (v / xMax) * iw;\n  const Y = v => mt + ih - (v / yMax) * ih;\n  const dec = pctUtilisable ? 0 : yMax < 1 ? 3 : yMax < 10 ? 2 : 0;\n  const unite = pctUtilisable ? \" %\" : \"\";\n\n  let grid = \"\", ticksY = \"\";\n  for(let i = 0; i <= 4; i++){\n    const v = (yMax / 4) * i, yy = Y(v);\n    grid += `<line x1=\"${ml}\" y1=\"${yy.toFixed(1)}\" x2=\"${W-mr}\" y2=\"${yy.toFixed(1)}\" stroke=\"${pal.border}\" stroke-width=\"1\"/>`;\n    ticksY += `<text x=\"${ml-8}\" y=\"${(yy+4).toFixed(1)}\" text-anchor=\"end\" font-size=\"11\" fill=\"${pal.faint}\" font-family=\"${pal.mono}\">${fmt(v, dec)}${unite}</text>`;\n  }\n  let ticksX = \"\";\n  for(let i = 0; i <= 4; i++){\n    const v = (xMax / 4) * i, xx = X(v);\n    ticksX += `<text x=\"${xx.toFixed(1)}\" y=\"${H-mb+18}\" text-anchor=\"middle\" font-size=\"11\" fill=\"${pal.faint}\" font-family=\"${pal.mono}\">${Math.round(v)}</text>`;\n  }\n\n  // lignes de bornes : en vue % elles sont fixes (100 % = limite, 0 % = mini si plage)\n  const lignesBornesData = pctUtilisable\n    ? [{ v:100, lbl:\"tol\u00e9rance (100 %)\" }, ...(plageMiniValide ? [{ v:0, lbl:\"min (0 %)\", min:true }] : [])]\n    : [{ v:limite, lbl:isNaN(limite) ? \"\" : `tol\u00e9rance ${fmt(limite, dec)}` },\n       ...(isNaN(mini) ? [] : [{ v:mini, lbl:`min ${fmt(mini, dec)}`, min:true }])];\n  const lignesBornes = lignesBornesData.map(b => {\n    if(isNaN(b.v) || b.v > yMax || b.v < 0) return \"\";\n    const yl = Y(b.v);\n    const couleur = b.min ? pal.blue : pal.red;\n    return `<line x1=\"${ml}\" y1=\"${yl.toFixed(1)}\" x2=\"${W-mr}\" y2=\"${yl.toFixed(1)}\" stroke=\"${couleur}\" stroke-width=\"2\" stroke-dasharray=\"7 5\"/>\n      <text x=\"${W-mr}\" y=\"${(yl-7).toFixed(1)}\" text-anchor=\"end\" font-size=\"11\" font-weight=\"600\" fill=\"${couleur}\" font-family=\"var(--font-mono)\">${escapeAttr(b.lbl)}</text>`;\n  }).join(\"\");\n\n  const paths = series.map(s => {\n    const d = s.pts.map(p => `${X(p.x).toFixed(1)},${Y(yDe(p)).toFixed(1)}`).join(\" \");\n    const line = s.pts.length > 1\n      ? `<polyline points=\"${d}\" fill=\"none\" stroke=\"${s.couleur}\" stroke-width=\"2.2\" stroke-linejoin=\"round\" stroke-linecap=\"round\"${dashAttr(s.dash)}/>` : \"\";\n    const dots = s.pts.map(p => {\n      const yp = yDe(p);\n      const hors = !isNaN(limite) && p.y > limite;\n      const cle = (p.pointMesure || \"\").trim().toLowerCase();\n      const couleurPoint = cle ? couleurParPointMesure.get(cle) : null;\n      const fill = hors ? pal.red : (couleurPoint || s.couleur);\n      const titre = `Pi\u00e8ce ${p.x}${p.pointMesure ? \" \u2014 \" + escapeAttr(p.pointMesure) : \"\"} : ${fmt(p.y, dec)}${pctUtilisable && yp !== null ? ` (${fmt(yp,0)} %)` : \"\"}`;\n      return `<circle cx=\"${X(p.x).toFixed(1)}\" cy=\"${Y(yp).toFixed(1)}\" r=\"${hors ? 5 : 3.8}\" fill=\"${fill}\" stroke=\"var(--surface)\" stroke-width=\"1.5\"><title>${titre}</title></circle>`;\n    }).join(\"\");\n    return line + dots;\n  }).join(\"\");\n\n  const legendPointsMesure = [...couleurParPointMesure.entries()].map(([cle, couleur]) => {\n    const premier = series.flatMap(s => s.pts).find(p => (p.pointMesure||\"\").trim().toLowerCase() === cle);\n    return `<span><i style=\"background:${couleur}; width:9px; height:9px; border-radius:50%; display:inline-block;\"></i>${escapeAttr(premier ? premier.pointMesure : cle)}</span>`;\n  }).join(\"\");\n  const legend = series.map(s =>\n    `<span>${dashSwatch(s.couleur, s.dash)}${escapeAttr(s.titre)}</span>`\n  ).join(\"\")\n    + (isNaN(limite) ? \"\" : `<span><i class=\"tol\"></i>Limite ${escapeAttr(g.label)}${pctUtilisable ? \" (100 %)\" : \"\"}</span>`)\n    + (isNaN(mini) ? \"\" : `<span>${dashSwatch(pal.blue, \"7 5\")}Min${pctUtilisable && plageMiniValide ? \" (0 %)\" : \"\"}</span>`)\n    + (g.note ? `<span style=\"color:var(--ink-faint);\">${escapeAttr(g.note)}</span>` : \"\")\n    + legendPointsMesure;\n\n  // v4.15 : la bascule \u00ab % de tol\u00e9rance \u00bb n'existe que si le crit\u00e8re a une limite exploitable ;\n  // l'\u00e9tat est partag\u00e9 par toutes les tendances de l'\u00e9cran (tendanceEnPct), le libell\u00e9 suit.\n  const peutPct = !isNaN(limite) && limite > 0;\n\n  return `\n    <div class=\"chart-block\">\n      <h3><span>Tendance \u2014 ${escapeAttr(g.label)} en fonction du n\u00b0 de pi\u00e8ce</span>\n        ${peutPct ? `<button class=\"ghost small pct-toggle\" title=\"${pctUtilisable ? \"Revenir aux valeurs mesur\u00e9es\" : \"Exprimer la mesure en % de la tol\u00e9rance consomm\u00e9e (100 % = limite)\"}\">${pctUtilisable ? \"Voir les valeurs\" : \"Voir en % de tol.\"}</button>` : \"\"}</h3>\n      <svg class=\"chart-svg\" viewBox=\"0 0 ${W} ${H}\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"\n           aria-label=\"\u00c9volution de ${escapeAttr(g.label)} au fil des pi\u00e8ces produites, par essai\">\n        ${grid}\n        <line x1=\"${ml}\" y1=\"${mt}\" x2=\"${ml}\" y2=\"${mt+ih}\" stroke=\"${pal.faint}\" stroke-width=\"1\"/>\n        <line x1=\"${ml}\" y1=\"${mt+ih}\" x2=\"${W-mr}\" y2=\"${mt+ih}\" stroke=\"${pal.faint}\" stroke-width=\"1\"/>\n        ${ticksY}${ticksX}${lignesBornes}${paths}\n        <text x=\"${ml+iw/2}\" y=\"${H-4}\" text-anchor=\"middle\" font-size=\"11.5\" fill=\"${pal.soft}\">N\u00b0 de pi\u00e8ce</text>\n        <text x=\"14\" y=\"${mt+ih/2}\" text-anchor=\"middle\" font-size=\"11.5\" fill=\"${pal.soft}\"\n              transform=\"rotate(-90 14 ${mt+ih/2})\">${escapeAttr(pctUtilisable ? \"% de la tol\u00e9rance consomm\u00e9e\" : g.label)}</text>\n      </svg>\n      <div class=\"chart-legend\">${legend}</div>\n    </div>\n  `;\n}\n\n/* ---- comparaison multi-scenarios : lequel derive le plus vite ? ---- */\nfunction representativeEssai(sc){\n  const list = (sc.essais||[]).map(es => {\n    const pts = (es.prelevements||[])\n      .map(r => ({ x: parseFloat(r.piece), y: valeurMesuree(sc, r) }))\n      .filter(p => !isNaN(p.x) && p.y !== null)\n      .sort((a,b) => a.x - b.x);\n    return { es, pts };\n  }).filter(o => o.pts.length);\n  if(!list.length) return null;\n  // l'essai le plus representatif : celui qui a le plus de mesures, puis celui qui va le plus loin\n  list.sort((a,b) => b.pts.length - a.pts.length || (b.pts[b.pts.length-1].x - a.pts[a.pts.length-1].x));\n  return list[0];\n}\n\nfunction multiChartHTML(){\n  const series = data.map((sc, i) => {\n    const rep = representativeEssai(sc);\n    if(!rep) return null;\n    return { nom: sc.name, essaiTitre: rep.es.titre, couleur: CHART_COLORS[i % CHART_COLORS.length],\n             dash: STROKE_DASH[i % STROKE_DASH.length], pts: rep.pts, limite: parseFloat(limiteDe(sc)) };\n  }).filter(Boolean);\n\n  if(series.length < 2){\n    return `<div class=\"chart-block\">\n      <h3>Comparaison multi-sc\u00e9narios \u2014 ${escapeAttr(config.limitLabel)}</h3>\n      <p class=\"chart-empty\">Appara\u00eet d\u00e8s que deux sc\u00e9narios au moins ont un essai mesur\u00e9. Chaque courbe trace l'essai le plus complet de son sc\u00e9nario \u2014 pour r\u00e9pondre \u00e0 \u00ab lequel d\u00e9rive le plus vite ? \u00bb.</p>\n    </div>`;\n  }\n\n  const limites = series.map(s => s.limite).filter(v => !isNaN(v));\n  const limiteCommune = (limites.length === series.length && limites.every(v => v === limites[0])) ? limites[0] : null;\n\n  const allX = series.flatMap(s => s.pts.map(p => p.x));\n  const allY = series.flatMap(s => s.pts.map(p => p.y));\n  // meme marge a droite que chartHTML (v4.6) : le point le plus avance ne colle plus au bord\n  const xMax = Math.max(...allX, 1) * 1.08;\n  const yMax = Math.max(...allY, ...limites, 0.001) * 1.18;\n\n  const W = 720, H = 260, ml = 58, mr = 14, mt = 12, mb = 38;\n  const iw = W - ml - mr, ih = H - mt - mb;\n  const X = v => ml + (v / xMax) * iw;\n  const Y = v => mt + ih - (v / yMax) * ih;\n  const dec = yMax < 1 ? 3 : yMax < 10 ? 2 : 0;\n\n  let grid = \"\", ticksY = \"\";\n  for(let i = 0; i <= 4; i++){\n    const v = (yMax / 4) * i, yy = Y(v);\n    grid += `<line x1=\"${ml}\" y1=\"${yy.toFixed(1)}\" x2=\"${W-mr}\" y2=\"${yy.toFixed(1)}\" stroke=\"var(--border)\" stroke-width=\"1\"/>`;\n    ticksY += `<text x=\"${ml-8}\" y=\"${(yy+4).toFixed(1)}\" text-anchor=\"end\" font-size=\"11\" fill=\"var(--ink-faint)\" font-family=\"var(--font-mono)\">${fmt(v, dec)}</text>`;\n  }\n  let ticksX = \"\";\n  for(let i = 0; i <= 4; i++){\n    const v = (xMax / 4) * i, xx = X(v);\n    ticksX += `<text x=\"${xx.toFixed(1)}\" y=\"${H-mb+18}\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--ink-faint)\" font-family=\"var(--font-mono)\">${Math.round(v)}</text>`;\n  }\n\n  let tolLine = \"\";\n  if(limiteCommune !== null && limiteCommune <= yMax){\n    const yl = Y(limiteCommune);\n    tolLine = `<line x1=\"${ml}\" y1=\"${yl.toFixed(1)}\" x2=\"${W-mr}\" y2=\"${yl.toFixed(1)}\" stroke=\"var(--red)\" stroke-width=\"2\" stroke-dasharray=\"7 5\"/>\n      <text x=\"${W-mr}\" y=\"${(yl-7).toFixed(1)}\" text-anchor=\"end\" font-size=\"11\" font-weight=\"600\" fill=\"var(--red)\" font-family=\"var(--font-mono)\">tol\u00e9rance ${fmt(limiteCommune, dec)}</text>`;\n  }\n\n  const paths = series.map(s => {\n    const d = s.pts.map(p => `${X(p.x).toFixed(1)},${Y(p.y).toFixed(1)}`).join(\" \");\n    const line = s.pts.length > 1\n      ? `<polyline points=\"${d}\" fill=\"none\" stroke=\"${s.couleur}\" stroke-width=\"2.4\" stroke-linejoin=\"round\" stroke-linecap=\"round\"${dashAttr(s.dash)}/>` : \"\";\n    const dots = s.pts.map(p => {\n      const hors = !isNaN(s.limite) && p.y > s.limite;\n      return `<circle cx=\"${X(p.x).toFixed(1)}\" cy=\"${Y(p.y).toFixed(1)}\" r=\"${hors ? 5 : 3.6}\" fill=\"${hors ? \"var(--red)\" : s.couleur}\" stroke=\"var(--surface)\" stroke-width=\"1.5\"/>`;\n    }).join(\"\");\n    return line + dots;\n  }).join(\"\");\n\n  const legend = series.map(s =>\n    `<span>${dashSwatch(s.couleur, s.dash)}${escapeAttr(s.nom)} <span style=\"color:var(--ink-faint);\">(${escapeAttr(s.essaiTitre)})</span></span>`\n  ).join(\"\") + (limiteCommune === null\n      ? `<span style=\"color:var(--ink-faint);\">tol\u00e9rances diff\u00e9rentes selon sc\u00e9nario \u2014 non trac\u00e9es</span>`\n      : `<span><i class=\"tol\"></i>Limite ${escapeAttr(config.limitLabel)}</span>`);\n\n  return `\n    <div class=\"chart-block\">\n      <h3>Comparaison multi-sc\u00e9narios \u2014 ${escapeAttr(config.limitLabel)} (essai le plus complet de chaque sc\u00e9nario)</h3>\n      <svg class=\"chart-svg\" viewBox=\"0 0 ${W} ${H}\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"\n           aria-label=\"Comparaison de la d\u00e9rive entre sc\u00e9narios\">\n        ${grid}\n        <line x1=\"${ml}\" y1=\"${mt}\" x2=\"${ml}\" y2=\"${mt+ih}\" stroke=\"var(--ink-faint)\" stroke-width=\"1\"/>\n        <line x1=\"${ml}\" y1=\"${mt+ih}\" x2=\"${W-mr}\" y2=\"${mt+ih}\" stroke=\"var(--ink-faint)\" stroke-width=\"1\"/>\n        ${ticksY}${ticksX}${tolLine}${paths}\n        <text x=\"${ml+iw/2}\" y=\"${H-4}\" text-anchor=\"middle\" font-size=\"11.5\" fill=\"var(--ink-soft)\">N\u00b0 de pi\u00e8ce</text>\n        <text x=\"14\" y=\"${mt+ih/2}\" text-anchor=\"middle\" font-size=\"11.5\" fill=\"var(--ink-soft)\"\n              transform=\"rotate(-90 14 ${mt+ih/2})\">${escapeAttr(config.limitLabel)}</text>\n      </svg>\n      <div class=\"chart-legend\">${legend}</div>\n    </div>\n  `;\n}\n\n/* ---- comparaison de deux essais (v4.15) ------------------------------------------------\n   Deux usages, un seul \u00e9cran : deux essais du M\u00caME sc\u00e9nario (la superposition montre la\n   r\u00e9p\u00e9tabilit\u00e9 \u2014 le fond du protocole 5\u00d7), ou deux essais de sc\u00e9narios DIFF\u00c9RENTS (quelle\n   d\u00e9rive tient le mieux ?). Les courbes reprennent exactement les s\u00e9ries de la Tendance\n   (m\u00eame lecture Droite/Gauche, points de mesure, crit\u00e8res), restreintes \u00e0 chaque essai. */\nfunction grandeurCleDeLabel(label){\n  return \"csup:\" + normaliserRecherche(label || \"\");\n}\nfunction groupeTendanceUnEssai(sc, es, cle){\n  // les m\u00eames s\u00e9ries que groupesTendance, pour UN essai et UNE grandeur\n  const scSolo = Object.assign({}, sc, { essais: [es] });\n  if(cle === \"batt\"){\n    if(sc.battActif === false) return null;\n    return { label: libelleDe(sc), tolerance: parseFloat(limiteDe(sc)), toleranceMini: NaN,\n      series: seriesTendance(scSolo, r => valeurMesuree(sc, r)) };\n  }\n  const cleLabel = cle.slice(5);\n  const c = criteresSupActifs(sc).find(x => normaliserRecherche(x.label || \"\") === cleLabel);\n  if(!c) return null;\n  const series = [];\n  axesDe(c).forEach(ax => {\n    seriesTendance(scSolo, r => {\n      const v = ((r.valeurs || {})[c.id] || {})[ax];\n      const n = parseFloat(v);\n      return isNaN(n) ? null : n;\n    }).forEach(s => series.push({\n      titre: s.titre + (ax !== \"v\" ? \" \u2014 \" + (AXE_LABELS[ax] || ax) : \"\"), pts: s.pts\n    }));\n  });\n  return { label: c.label || \"crit\u00e8re\", tolerance: parseFloat(c.maxi),\n    toleranceMini: c.miniActif ? parseFloat(c.mini) : NaN, series };\n}\nfunction grandeursComparees(scA, scB){\n  const cles = [];\n  if(scA.battActif !== false || scB.battActif !== false) cles.push(\"batt\");\n  const labels = new Set([\n    ...criteresSupActifs(scA).map(c => normaliserRecherche(c.label || \"\")),\n    ...criteresSupActifs(scB).map(c => normaliserRecherche(c.label || \"\"))\n  ].filter(Boolean));\n  labels.forEach(l => cles.push(\"csup:\" + l));\n  return cles;\n}\nfunction essaiComparaison(cle){\n  const [scId, essaiId] = cle.split(\"|\");\n  const sc = data.find(s => s.id === scId);\n  const es = sc && (sc.essais || []).find(e => e.id === essaiId);\n  return sc && es ? { sc, es } : null;\n}\nfunction optionsComparaisonPour(cleSelectionnee){\n  return data.map(sc => {\n    const inner = (sc.essais || []).map(es => {\n      const cle = sc.id + \"|\" + es.id;\n      const lbl = (es.titre || \"(sans titre)\") + (es.date ? \" \u2014 \" + es.date : \"\") + (es.prelevements && es.prelevements.length ? \"\" : \" (aucune mesure)\");\n      return `<option value=\"${cle}\" ${cle === cleSelectionnee ? \"selected\" : \"\"}>${escapeAttr(lbl)}</option>`;\n    }).join(\"\");\n    return inner ? `<optgroup label=\"${escapeAttr(sc.name)}\">${inner}</optgroup>` : \"\";\n  }).join(\"\");\n}\nfunction ouvrirComparaison(scId, essaiId){\n  compareCtx = { a: scId + \"|\" + essaiId, b: null };\n  ouvrirPanneau(\"comparePanel\");\n  remplirComparaison();\n}\nfunction trouverPaireComparaison(aCle){\n  // B par d\u00e9faut : le premier AUTRE essai mesur\u00e9, de pr\u00e9f\u00e9rence dans le m\u00eame sc\u00e9nario\n  const [scAid, esAid] = aCle.split(\"|\");\n  const scA = data.find(s => s.id === scAid);\n  const autres = ((scA && scA.essais) || []).filter(e => e.id !== esAid && (e.prelevements || []).length);\n  if(autres.length) return scAid + \"|\" + autres[0].id;\n  for(const sc of data){\n    for(const e of (sc.essais || [])){\n      const cle = sc.id + \"|\" + e.id;\n      if(cle !== aCle && (e.prelevements || []).length) return cle;\n    }\n  }\n  return null;\n}\nfunction remplirComparaison(){\n  const selA = document.getElementById(\"cmpA\"), selB = document.getElementById(\"cmpB\");\n  if(!compareCtx.b) compareCtx.b = trouverPaireComparaison(compareCtx.a) || compareCtx.a;\n  selA.innerHTML = optionsComparaisonPour(compareCtx.a);\n  selB.innerHTML = optionsComparaisonPour(compareCtx.b);\n  rendreComparaison();\n}\nfunction comparerConditionsLigne(label, va, vb){\n  return `<tr><td>${label}</td><td>${va}</td><td>${vb}</td></tr>`;\n}\nfunction rendreComparaison(){\n  const body = document.getElementById(\"compareBody\");\n  const sous = document.getElementById(\"compareSous\");\n  const A = essaiComparaison(compareCtx.a), B = essaiComparaison(compareCtx.b);\n  if(!A || !B){\n    body.innerHTML = `<p class=\"log-empty\">Choisissez deux essais \u00e0 comparer (il en faut deux, dans les sc\u00e9narios de cet OP).</p>`;\n    sous.textContent = \"\";\n    return;\n  }\n  const memeScenario = A.sc.id === B.sc.id;\n  sous.innerHTML = memeScenario\n    ? `Deux essais du <b>m\u00eame sc\u00e9nario</b> \u2014 la superposition montre la <b>r\u00e9p\u00e9tabilit\u00e9</b> : c'est exactement ce que demande le protocole (un essai concluant r\u00e9p\u00e9t\u00e9 5\u00d7).`\n    : `Deux <b>sc\u00e9narios diff\u00e9rents</b> \u2014 comparez la d\u00e9rive et le niveau des courbes, chacun avec sa propre tol\u00e9rance.`;\n\n  const stA = essaiStats(A.sc, A.es), stB = essaiStats(B.sc, B.es);\n  const statutTxt = st => st.status === \"ok\" ? \"\u2713 Conforme\" : st.status === \"bad\" ? \"\u2717 Non conforme\" : st.status === \"arrete\" ? \"\u23f9 \" + st.raison : \"En cours \u2014 \" + st.raison;\n  // v4.28 : noms actuels des logements, pas les noms fig\u00e9s \u00e0 l'essai\n  const plaquettesDe = (sc, es) => logementsSuivis(es).map(lp => {\n    const n = nomLogementActuel(sc, lp);\n    return `${escapeAttr(n.outilNumero || \"?\")}\u00b7${escapeAttr(n.logementNom || \"\u2014\")} ${escapeAttr(refLogementEssai(sc, lp) || \"\u2014\")}`;\n  }).join(\"<br>\") || \"\u2014\";\n  const coupeDe = (sc, es) => logementsSuivis(es).map(lp => {\n    const n = nomLogementActuel(sc, lp);\n    return `${escapeAttr(n.outilNumero || \"?\")}\u00b7${escapeAttr(n.logementNom || \"\u2014\")} Vc ${lp.vc ?? \"\u2014\"} / f ${lp.f ?? \"\u2014\"} / ch. ${lp.charniere ?? \"\u2014\"}`;\n  }).join(\"<br>\") || \"\u2014\";\n\n  const tableau = `\n    <table class=\"cmp-table\">\n      <tr><th></th><th>${escapeAttr(A.es.titre || \"Essai A\")}</th><th>${escapeAttr(B.es.titre || \"Essai B\")}</th></tr>\n      ${comparerConditionsLigne(\"Sc\u00e9nario\", escapeAttr(A.sc.name) + (A.sc.baseline ? \" \u2605\" : \"\"), escapeAttr(B.sc.name) + (B.sc.baseline ? \" \u2605\" : \"\"))}\n      ${comparerConditionsLigne(\"Date / \u00e9quipe\", `${A.es.date || \"\u2014\"} \u00b7 ${escapeAttr(A.es.equipe) || \"\u2014\"}`, `${B.es.date || \"\u2014\"} \u00b7 ${escapeAttr(B.es.equipe) || \"\u2014\"}`)}\n      ${comparerConditionsLigne(\"Op\u00e9rateur\", escapeAttr(A.es.operateur) || \"\u2014\", escapeAttr(B.es.operateur) || \"\u2014\")}\n      ${comparerConditionsLigne(\"Bruts (jours)\", A.es.maturiteBruts === \"\" || A.es.maturiteBruts == null ? \"\u2014\" : A.es.maturiteBruts, B.es.maturiteBruts === \"\" || B.es.maturiteBruts == null ? \"\u2014\" : B.es.maturiteBruts)}\n      ${comparerConditionsLigne(\"Plaquettes (fig\u00e9es \u00e0 l'essai)\", plaquettesDe(A.sc, A.es), plaquettesDe(B.sc, B.es))}\n      ${comparerConditionsLigne(\"Conditions de coupe\", coupeDe(A.sc, A.es), coupeDe(B.sc, B.es))}\n      ${comparerConditionsLigne(\"Pr\u00e9l\u00e8vements\", `${stA.count} (dernier n\u00b0 ${stA.lastPiece ?? \"\u2014\"})`, `${stB.count} (dernier n\u00b0 ${stB.lastPiece ?? \"\u2014\"})`)}\n      ${comparerConditionsLigne(\"Hors tol\u00e9rance\", stA.tauxHorsTol === null ? \"\u2014\" : fmt(stA.tauxHorsTol, 0) + \" %\", stB.tauxHorsTol === null ? \"\u2014\" : fmt(stB.tauxHorsTol, 0) + \" %\")}\n      ${comparerConditionsLigne(\"Statut\", statutTxt(stA), statutTxt(stB))}\n    </table>`;\n\n  // une courbe superpos\u00e9e par grandeur commune (battement, puis crit\u00e8res par libell\u00e9)\n  const sections = grandeursComparees(A.sc, B.sc).map(cle => {\n    const gA = groupeTendanceUnEssai(A.sc, A.es, cle);\n    const gB = groupeTendanceUnEssai(B.sc, B.es, cle);\n    const series = [\n      ...(gA ? gA.series.map(s => ({ titre: \"A \u00b7 \" + s.titre, pts: s.pts, couleur: \"#3b82f6\", dash: \"none\" })) : []),\n      ...(gB ? gB.series.map(s => ({ titre: \"B \u00b7 \" + s.titre, pts: s.pts, couleur: \"#f59e0b\", dash: \"7 5\" })) : [])\n    ].filter(s => s.pts.length);\n    if(!series.length) return \"\";\n    const label = (gA || gB).label;\n    return comparaisonChartHTML(label, series, gA, gB);\n  }).join(\"\");\n\n  body.innerHTML = tableau + (sections || `<p class=\"chart-empty\">Aucune mesure mesur\u00e9e \u00e0 superposer : le graphique appara\u00eetra d\u00e8s que les deux essais portent des pr\u00e9l\u00e8vements.</p>`);\n}\nfunction comparaisonChartHTML(label, series, gA, gB){\n  const allX = series.flatMap(s => s.pts.map(p => p.x));\n  const allY = series.flatMap(s => s.pts.map(p => p.y));\n  const xMax = Math.max(...allX, 1) * 1.08;\n  const yMax = Math.max(...allY, ...[gA, gB].map(g => g ? g.tolerance : NaN).filter(v => !isNaN(v)), 0.001) * 1.18;\n\n  const W = 720, H = 260, ml = 58, mr = 14, mt = 12, mb = 38;\n  const iw = W - ml - mr, ih = H - mt - mb;\n  const X = v => ml + (v / xMax) * iw;\n  const Y = v => mt + ih - (v / yMax) * ih;\n  const dec = yMax < 1 ? 3 : yMax < 10 ? 2 : 0;\n\n  let grid = \"\", ticksY = \"\";\n  for(let i = 0; i <= 4; i++){\n    const v = (yMax / 4) * i, yy = Y(v);\n    grid += `<line x1=\"${ml}\" y1=\"${yy.toFixed(1)}\" x2=\"${W-mr}\" y2=\"${yy.toFixed(1)}\" stroke=\"var(--border)\" stroke-width=\"1\"/>`;\n    ticksY += `<text x=\"${ml-8}\" y=\"${(yy+4).toFixed(1)}\" text-anchor=\"end\" font-size=\"11\" fill=\"var(--ink-faint)\" font-family=\"var(--font-mono)\">${fmt(v, dec)}</text>`;\n  }\n  let ticksX = \"\";\n  for(let i = 0; i <= 4; i++){\n    const v = (xMax / 4) * i, xx = X(v);\n    ticksX += `<text x=\"${xx.toFixed(1)}\" y=\"${H-mb+18}\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--ink-faint)\" font-family=\"var(--font-mono)\">${Math.round(v)}</text>`;\n  }\n  // tol\u00e9rances : une ligne par essai, fusionn\u00e9es si elles sont identiques\n  const tols = [];\n  if(gA && !isNaN(gA.tolerance)) tols.push({ v: gA.tolerance, lbl: \"tol. A \" + fmt(gA.tolerance, dec) });\n  if(gB && !isNaN(gB.tolerance) && !(gA && !isNaN(gA.tolerance) && gA.tolerance === gB.tolerance))\n    tols.push({ v: gB.tolerance, lbl: \"tol. B \" + fmt(gB.tolerance, dec) });\n  const lignesTol = tols.map(t => {\n    if(t.v > yMax) return \"\";\n    const yl = Y(t.v);\n    return `<line x1=\"${ml}\" y1=\"${yl.toFixed(1)}\" x2=\"${W-mr}\" y2=\"${yl.toFixed(1)}\" stroke=\"var(--red)\" stroke-width=\"2\" stroke-dasharray=\"7 5\"/>\n      <text x=\"${W-mr}\" y=\"${(yl-7).toFixed(1)}\" text-anchor=\"end\" font-size=\"11\" font-weight=\"600\" fill=\"var(--red)\" font-family=\"var(--font-mono)\">${escapeAttr(t.lbl)}</text>`;\n  }).join(\"\");\n\n  const paths = series.map(s => {\n    const d = s.pts.map(p => `${X(p.x).toFixed(1)},${Y(p.y).toFixed(1)}`).join(\" \");\n    const line = s.pts.length > 1\n      ? `<polyline points=\"${d}\" fill=\"none\" stroke=\"${s.couleur}\" stroke-width=\"2.4\" stroke-linejoin=\"round\" stroke-linecap=\"round\"${dashAttr(s.dash)}/>` : \"\";\n    const dots = s.pts.map(p =>\n      `<circle cx=\"${X(p.x).toFixed(1)}\" cy=\"${Y(p.y).toFixed(1)}\" r=\"3.6\" fill=\"${s.couleur}\" stroke=\"var(--surface)\" stroke-width=\"1.5\"><title>Pi\u00e8ce ${p.x} : ${fmt(p.y, dec)}</title></circle>`).join(\"\");\n    return line + dots;\n  }).join(\"\");\n\n  const legend = series.map(s =>\n    `<span>${dashSwatch(s.couleur, s.dash)}${escapeAttr(s.titre)}</span>`).join(\"\");\n\n  return `\n    <div class=\"chart-block\">\n      <h3><span>${escapeAttr(label)} \u2014 essais superpos\u00e9s</span></h3>\n      <svg class=\"chart-svg\" viewBox=\"0 0 ${W} ${H}\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"\n           aria-label=\"Comparaison de deux essais sur ${escapeAttr(label)}\">\n        ${grid}\n        <line x1=\"${ml}\" y1=\"${mt}\" x2=\"${ml}\" y2=\"${mt+ih}\" stroke=\"var(--ink-faint)\" stroke-width=\"1\"/>\n        <line x1=\"${ml}\" y1=\"${mt+ih}\" x2=\"${W-mr}\" y2=\"${mt+ih}\" stroke=\"var(--ink-faint)\" stroke-width=\"1\"/>\n        ${ticksY}${ticksX}${lignesTol}${paths}\n        <text x=\"${ml+iw/2}\" y=\"${H-4}\" text-anchor=\"middle\" font-size=\"11.5\" fill=\"var(--ink-soft)\">N\u00b0 de pi\u00e8ce</text>\n        <text x=\"14\" y=\"${mt+ih/2}\" text-anchor=\"middle\" font-size=\"11.5\" fill=\"var(--ink-soft)\"\n              transform=\"rotate(-90 14 ${mt+ih/2})\">${escapeAttr(label)}</text>\n      </svg>\n      <div class=\"chart-legend\">${legend}</div>\n    </div>\n  `;\n}\n\n/* ---- vue de synthese comparative : tous scenarios en colonnes, criteres en lignes ---- */\n/* ---- v4.32 \u2014 base de comparaison explicite -------------------------------------------\n   Auparavant le scenario de production (\u2605) faisait office de base pour tous les ecarts :\n   mettre le scenario le plus cher en production faisait apparaitre tous les autres comme\n   des economies, sans que rien ne le dise. On separe desormais les deux notions :\n   - le statut \u2605 (\u00ab scenario en production \u00bb) reste ce qui tourne en atelier ;\n   - la BASE DE COMPARAISON est un choix explicite, par OP, memorise localement.\n   Par defaut la base est le scenario en production (le choix de l'atelier). */\nconst BASE_KEY = \"spk_base_compare_v1\";\nfunction cleOpBase(){ return [activeLigneId, activeReferenceId, activeOpId].join(\"|\"); }\nfunction baseComparaison(){\n  try {\n    const m = JSON.parse(localStorage.getItem(BASE_KEY) || \"{}\");\n    const id = m[cleOpBase()];\n    const sc = id ? data.find(s => s.id === id) : null;\n    if(sc) return sc;\n  } catch(e) {}\n  return baselineScenario();\n}\nfunction setBaseComparaison(id){\n  try {\n    const m = JSON.parse(localStorage.getItem(BASE_KEY) || \"{}\");\n    if(id) m[cleOpBase()] = id; else delete m[cleOpBase()];\n    localStorage.setItem(BASE_KEY, JSON.stringify(m));\n  } catch(e) {}\n}\nfunction meilleurCoutScenario(){\n  let best = null, bestC = null;\n  data.forEach(sc => {\n    const c = coutsDetail(sc).total;\n    if(c === null) return;\n    if(bestC === null || c < bestC){ bestC = c; best = sc; }\n  });\n  return { sc: best, cout: bestC };\n}\n/* bandeau de tete : dit NOIR SUR BLANC contre quoi on compare, et quel est le meilleur */\nfunction baseBannerHTML(){\n  if(data.length < 2) return \"\";\n  const base = baseComparaison();\n  if(!base) return \"\";\n  const bc = coutsDetail(base).total;\n  const best = meilleurCoutScenario();\n  const bprod = baselineScenario();\n  const estProd = !!(bprod && bprod.id === base.id);\n  const ecart = (best.sc && best.sc.id !== base.id && bc !== null && bc > 0 && best.cout !== null)\n      ? ((best.cout - bc) / bc) * 100 : null;\n  const baseChere = ecart !== null && ecart < -0.05;\n  const opts = data.map(sc => '<option value=\"' + sc.id + '\"' + (sc.id === base.id ? \" selected\" : \"\") + \">\" + escapeAttr(sc.name) + \"</option>\").join(\"\");\n  const reco = (ecart !== null)\n    ? 'Meilleur co\u00fbt : <b>' + escapeAttr(best.sc.name) + \"</b> \u2014 \" + fmt(best.cout, 4) + \" \u20ac/pi\u00e8ce (\" + (ecart > 0 ? \"+\" : \"\u2212\") + fmt(Math.abs(ecart), 1) + \" % vs base)\"\n    : \"Aucun autre sc\u00e9nario n'est moins cher que la base.\";\n  return '<div class=\"base-banner\">'\n    + '<div class=\"bb-left\"><span class=\"bb-l\">Base de comparaison</span>'\n    + '<select id=\"baseSel\" class=\"bb-sel\" aria-label=\"Choisir la base de comparaison\">' + opts + \"</select>\"\n    + (estProd ? '<span class=\"bb-tag\">en production \u2605</span>' : '<span class=\"bb-tag alt\">base choisie</span>')\n    + \"</div>\"\n    + '<div class=\"bb-right\"><span class=\"bb-reco\">' + reco + \"</span>\"\n    + (baseChere ? '<span class=\"bb-alert\">La base est l\\'option la plus ch\u00e8re \u2014 les autres sc\u00e9narios \u00e9conomisent.</span>' : \"\")\n    + \"</div></div>\";\n}\n\nfunction syntheseTableHTML(){\n  if(data.length < 2){\n    return `<div class=\"synthese-block\"><h3>Vue de synth\u00e8se comparative</h3><p class=\"chart-empty\">Ajoutez un second sc\u00e9nario pour activer la comparaison.</p></div>`;\n  }\n  const base = baseComparaison();\n  const baseCost = base ? scenarioCost(base) : null;\n  const baseCycle = base ? parseFloat(base.cycle) : null;\n\n  const cols = data.map(sc => {\n    const stats = scenarioStats(sc);\n    const scrap = scrapStats(sc);\n    const cost = scenarioCost(sc);\n    const cd = coutsDetail(sc);\n    const an = bilanAnnuel(sc, null, null, null, base);\n    const cbase = base ? coutsDetail(base) : null;\n    let deltaCost = \"r\u00e9f.\";\n    if(base && sc.id !== base.id && baseCost !== null && cost !== null){\n      const d = ((cost - baseCost) / baseCost) * 100;\n      deltaCost = (d > 0 ? \"+\" : \"\") + fmt(d,1) + \" %\";\n    }\n    let deltaTotal = \"r\u00e9f.\";\n    if(base && sc.id !== base.id && cbase && cbase.total && cd.total !== null){\n      const p = ((cd.total - cbase.total) / cbase.total) * 100;\n      deltaTotal = (p > 0 ? \"+\" : \"\") + fmt(p,1) + \" %\";\n    }\n    const cyc = parseFloat(sc.cycle);\n    let deltaCycle = \"r\u00e9f.\";\n    if(base && sc.id !== base.id && baseCycle && !isNaN(cyc)){\n      const d = ((cyc - baseCycle) / baseCycle) * 100;\n      deltaCycle = (d > 0 ? \"+\" : \"\") + fmt(d,1) + \" %\";\n    }\n    const secs = cycleSecondes(sc), cadence = cadenceHeure(sc);\n    const logCycle = logementCycle(sc);\n    const frfa = logCycle ? forceRatioDe(logCycle) : null;\n    const nbOutils = sc.outils.length, nbLogements = sc.outils.reduce((n,o)=>n+o.logements.length,0);\n    return {\n      sc, stats, scrap,\n      isBase: !!(base && base.id === sc.id),\n      nCoutTotal: cd.multiPoste ? cd.total : null,\n      nCoutOutil: cost,\n      nGain: (an && an.gainAnnuel !== undefined) ? an.gainAnnuel : null,\n      nArete: scenarioCostPerEdge(sc),\n      nCycle: isNaN(cyc) ? null : cyc,\n      nHorsTol: stats.rate,\n      nBad: stats.badCount,\n      nRebut: scrap.rate,\n      tCoutTotal: cd.multiPoste ? (cd.total === null ? \"\u2014\" : fmt(cd.total,4) + \" \u20ac (\" + deltaTotal + \")\") : null,\n      tCoutOutil: cost === null ? \"\u2014\" : fmt(cost,4) + \" \u20ac (\" + deltaCost + \")\",\n      tGain: (an && an.gainAnnuel !== undefined)\n              ? ((an.gainAnnuel>=0?\"+\":\"\u2212\") + fmtEuroCourt(Math.abs(an.gainAnnuel)) + \" / an\")\n              : (an && an.coutAnnuel !== null ? fmtEuroCourt(an.coutAnnuel) + \" / an\" : null),\n      tArete: fmt(scenarioCostPerEdge(sc), 3) + \" \u20ac\",\n      tOutils: nbOutils ? (nbOutils + \" / \" + nbLogements) : \"\u2014\",\n      tVcf: logCycle && (logCycle.vc || logCycle.f) ? ((logCycle.vc || \"\u2014\") + \" / \" + (logCycle.f || \"\u2014\")) : \"\u2014\",\n      tFrfa: frfa === null ? \"\u2014\" : fmt(frfa,2),\n      tCycle: (sc.cycle === \"\" || sc.cycle == null) ? \"\u2014\" :\n        fmt(parseFloat(sc.cycle),0) + \" (\" + deltaCycle + \")\" +\n        (secs !== null ? \" \u00b7 \" + fmt(secs,1) + \" s\" + (cadence ? \" \u00b7 \" + fmt(cadence,0) + \" p/h\" : \"\") : \"\"),\n      tHorsTol: stats.rate === null ? \"\u2014\" : fmt(stats.rate,0) + \" %\",\n      tBad: stats.badCount,\n      tRebut: scrap.rate === null ? \"\u2014\" : fmt(scrap.rate,1) + \" %\",\n      tStatut: `<span class=\"statut-pill ${sc.statut||\"essai\"}\">${statutLabel(sc.statut)}</span>`,\n      tVal: stats.validated ? \"\u2713 Valid\u00e9\" : (stats.validCount + \"/\" + (sc.validationThreshold || \"\u2014\") + \" essais\")\n    };\n  });\n\n  const groups = [\n    { titre:\"\u00c9conomique \u2014 \u00e9cart vs base\", rows:[\n      { label:\"Co\u00fbt total / pi\u00e8ce (tous postes)\", key:\"tCoutTotal\", num:\"nCoutTotal\", better:\"min\", skip:() => cols.every(x => x.tCoutTotal === null) },\n      { label:\"dont co\u00fbt outil / pi\u00e8ce\", key:\"tCoutOutil\", num:\"nCoutOutil\", better:\"min\" },\n      { label:\"Gain annuel vs base\", key:\"tGain\", num:\"nGain\", better:\"max\", skip:() => cols.every(x => x.tGain === null) },\n      { label:\"\u20ac / ar\u00eate (tous logements)\", key:\"tArete\", num:\"nArete\", better:\"min\" }\n    ]},\n    { titre:\"Process\", rows:[\n      { label:\"Outils / logements\", key:\"tOutils\", num:null, better:null },\n      { label:\"Vc / f (logement de r\u00e9f\u00e9rence cycle)\", key:\"tVcf\", num:null, better:null },\n      ...(config.forceRatioActif ? [{ label:\"Fr/Fa \u2248 cot(\u03bar) (logement de r\u00e9f\u00e9rence cycle)\", key:\"tFrfa\", num:null, better:null }] : []),\n      { label:\"Temps de cycle (indice r\u00e9f. 100)\", key:\"tCycle\", num:\"nCycle\", better:\"min\" }\n    ]},\n    { titre:\"Qualit\u00e9 & essais\", rows:[\n      { label:\"Statut de validation\", key:\"tVal\", num:null, better:null },\n      { label:\"Statut du sc\u00e9nario\", key:\"tStatut\", num:null, better:null },\n      { label:\"Taux hors tol\u00e9rance (battement, tous essais)\", key:\"tHorsTol\", num:\"nHorsTol\", better:\"min\" },\n      { label:\"Essais non conformes\", key:\"tBad\", num:\"nBad\", better:\"min\" },\n      { label:\"Taux de rebut ligne (\u00e9quipe)\", key:\"tRebut\", num:\"nRebut\", better:\"min\" }\n    ]}\n  ];\n\n  const wins = cols.map(() => 0);\n  groups.forEach(g => g.rows.forEach(r => {\n    if(!r.num || !r.better) return;\n    const nums = cols.map(c => c[r.num]).filter(v => v !== null && v !== undefined && !isNaN(v));\n    if(nums.length < 2) return;\n    const best = r.better === \"min\" ? Math.min.apply(null, nums) : Math.max.apply(null, nums);\n    cols.forEach((c, i) => { if(c[r.num] === best) wins[i]++; });\n  }));\n  const lead = Math.max.apply(null, wins);\n\n  const head = `<tr><th class=\"crit\" scope=\"col\">Crit\u00e8re</th>` + cols.map((c, i) =>\n    `<th class=\"sc-col${c.isBase ? \" colbase\" : \"\"}${(lead > 0 && wins[i] === lead) ? \" is-lead\" : \"\"}\" scope=\"col\">`\n    + `<span class=\"sc-name\">${escapeAttr(c.sc.name)}${c.sc.baseline ? \" \u2605\" : \"\"}</span>`\n    + (c.isBase ? `<span class=\"syn2-wins\">base de comparaison</span>` : (lead > 0 ? `<span class=\"syn2-wins\">${wins[i]} meilleur${wins[i] > 1 ? \"s\" : \"\"} crit\u00e8re${wins[i] > 1 ? \"s\" : \"\"}</span>` : \"\"))\n    + `</th>`).join(\"\") + `</tr>`;\n\n  const rowHtml = (r) => {\n    const nums = r.num ? cols.map(c => c[r.num]).filter(v => v !== null && v !== undefined && !isNaN(v)) : [];\n    let best = null, worst = null;\n    if(r.num && r.better && nums.length >= 2){\n      best = r.better === \"min\" ? Math.min.apply(null, nums) : Math.max.apply(null, nums);\n      worst = r.better === \"min\" ? Math.max.apply(null, nums) : Math.min.apply(null, nums);\n    }\n    return `<tr><td class=\"crit\">${r.label}</td>` + cols.map(c => {\n      const isBest = best !== null && c[r.num] === best;\n      const isWorst = worst !== null && worst !== best && c[r.num] === worst;\n      return `<td class=\"val${isBest ? \" syn2-best\" : \"\"}${isWorst ? \" syn2-worst\" : \"\"}\">${c[r.key] == null ? \"\u2014\" : c[r.key]}</td>`;\n    }).join(\"\") + `</tr>`;\n  };\n\n  const body = groups.map(g => {\n    const rows = g.rows.filter(r => !(r.skip && r.skip()));\n    if(!rows.length) return \"\";\n    return `<tr class=\"syn2-grp\"><td colspan=\"${cols.length + 1}\">${g.titre}</td></tr>` + rows.map(rowHtml).join(\"\");\n  }).join(\"\");\n\n  return `\n    <div class=\"synthese-block\">\n      <h3>Vue de synth\u00e8se comparative \u2014 tous sc\u00e9narios</h3>\n      ${baseBannerHTML()}\n      <div class=\"tbl-wrap\">\n        <table class=\"synthese syn2\">\n          <thead>${head}</thead>\n          <tbody>${body}</tbody>\n        </table>\n      </div>\n      <div class=\"syn2-legende\">\n        <span><i class=\"sw-best\"></i>Meilleure valeur du crit\u00e8re</span>\n        <span><i class=\"sw-worst\"></i>Valeur la plus d\u00e9favorable</span>\n        <span><i class=\"sw-base\"></i>Colonne de base \u2014 les \u00e9carts se lisent contre elle</span>\n      </div>\n    </div>\n  `;\n}\n\n/* ---- v4.32 cascade du gain : d'ou vient chaque euro economise (vs base) --------------- */\nfunction cascadeGainHTML(){\n  const base = baseComparaison();\n  if(!base) return \"\";\n  const actif = data.find(sc => sc.id === activeId);\n  /* v4.48 \u2014 la cascade ne dispara\u00eet plus silencieusement : quand le sc\u00e9nario ouvert EST\n     la base ou qu'aucun poste n'est chiffrable, le bloc reste visible et dit pourquoi \u2014\n     une barre absente se lit comme un bug, pas comme une absence d'\u00e9carts. */\n  if(!actif || actif.id === base.id){\n    return `<div class=\"synthese-block\"><h3>Cascade du gain \u2014 d'o\u00f9 vient l'\u00e9conomie</h3>\n      <p class=\"chart-empty\">Le sc\u00e9nario ouvert est la base de comparaison \u2014 ouvrez un sc\u00e9nario d'essai pour voir d'o\u00f9 vient chaque euro \u00e9conomis\u00e9, poste par poste.</p></div>`;\n  }\n  const cb = coutsDetail(base), ca = coutsDetail(actif);\n  if(cb.total === null || ca.total === null) return \"\";\n  const postes = COUT_POSTES\n    .map(p => ({ label:p.label, delta:(cb[p.key]||0) - (ca[p.key]||0), a: cb[p.key], b: ca[p.key] }))\n    .filter(p => Math.abs(p.delta) > 0.0005);\n  if(!postes.length){\n    return `<div class=\"synthese-block\"><h3>Cascade du gain \u2014 d'o\u00f9 vient l'\u00e9conomie</h3>\n      <p class=\"chart-empty\">${escapeAttr(actif.name)} et la base ont des co\u00fbts identiques poste par poste \u2014 aucun \u00e9cart \u00e0 d\u00e9tailler.</p></div>`;\n  }\n  const gainPiece = cb.total - ca.total;\n  const an = bilanAnnuel(actif, null, null, null, base);\n  const maxV = Math.max(cb.total, ca.total, ...postes.map(p => Math.abs(p.delta)), 0.0001);\n  const h = v => Math.max(6, Math.round((v / maxV) * 150)) + \"px\";\n  const col = (label, value, cls, sub, titre) =>\n    `<div class=\"syn2-wf-col\" title=\"${titre || \"\"}\">` +\n      `<div class=\"syn2-wf-bar ${cls}\" style=\"height:${h(value)}\">${sub}</div>` +\n      `<div class=\"syn2-wf-lab\">${label}</div></div>`;\n  const colsHtml = [\n    col(\"Base<br>\" + escapeAttr(base.name), cb.total, \"ref\", fmt(cb.total,2) + \" \u20ac\", \"Co\u00fbt total / pi\u00e8ce de la base\"),\n    ...postes.map(p => col(escapeAttr(p.label), Math.abs(p.delta), p.delta >= 0 ? \"save\" : \"up\",\n        (p.delta >= 0 ? \"\u2212\" : \"+\") + fmt(Math.abs(p.delta),2) + \" \u20ac\",\n        p.label + \" : \" + fmt(p.a,2) + \" \u20ac \u2192 \" + fmt(p.b,2) + \" \u20ac\")),\n    col(\"Sc\u00e9nario<br>\" + escapeAttr(actif.name), ca.total, \"tot\", fmt(ca.total,2) + \" \u20ac\", \"Co\u00fbt total / pi\u00e8ce du sc\u00e9nario ouvert\")\n  ].join(\"\");\n  const gainHtml = (an && an.gainAnnuel !== undefined)\n    ? `<div class=\"syn2-wf-card save\"><div class=\"b\">${(an.gainAnnuel>=0?\"+\":\"\u2212\")}${fmtEuroCourt(Math.abs(an.gainAnnuel))}</div><div class=\"l\">Gain annuel projet\u00e9 \u2014 ${escapeAttr(actif.name)} vs base</div></div>`\n    : \"\";\n  return `\n    <div class=\"synthese-block\">\n      <h3>Cascade du gain \u2014 d'o\u00f9 vient l'\u00e9conomie</h3>\n      <p class=\"syn2-wf-sub\">\u00c9cart de co\u00fbt / pi\u00e8ce entre <b>${escapeAttr(base.name)}</b> (base de comparaison) et <b>${escapeAttr(actif.name)}</b>, poste par poste. Barre verte = le sc\u00e9nario d\u00e9pense moins sur ce poste.</p>\n      <div class=\"syn2-wf\">${colsHtml}</div>\n      <div class=\"syn2-wf-foot\">\n        ${gainHtml}\n        <div class=\"syn2-wf-card piece\"><div class=\"b\">${(gainPiece>=0?\"\u2212\":\"+\")}${fmt(Math.abs(gainPiece),2)} \u20ac</div><div class=\"l\">\u00c9cart par pi\u00e8ce (${fmt(cb.total,2)} \u20ac \u2192 ${fmt(ca.total,2)} \u20ac)</div></div>\n      </div>\n    </div>\n  `;\n}\n\n/* ---- dispersion par equipe -----------------------------------------------------------\n   Les champs \"equipe\" et \"redige par\" ne servaient qu'a tracer. Croises avec la conformite\n   des prelevements, ils repondent a la question que l'atelier pose des qu'un essai derape :\n   est-ce l'outil, ou la conduite ? Si les trois postes sont a 2 % et un a 18 %, ce n'est pas\n   la plaquette. Le tableau ne s'affiche que s'il y a de quoi comparer (>= 2 equipes\n   renseignees) \u2014 sinon il induirait une conclusion a partir d'une seule.               */\nfunction dispersionEquipeHTML(){\n  const equipes = [];\n  data.forEach(sc => (sc.essais||[]).forEach(es => {\n    const eq = (es.equipe || \"\").trim();\n    if(eq && !equipes.includes(eq)) equipes.push(eq);\n  }));\n  if(equipes.length < 2) return \"\";\n\n  // une cellule = un couple (equipe, scenario) : nb d'essais, prelevements evalues, taux hors tol.\n  const cellule = (eq, sc) => {\n    const essais = (sc.essais||[]).filter(es => (es.equipe||\"\").trim() === eq);\n    const prels = essais.flatMap(es => (es.prelevements||[]).filter(r => toleranceRequisePour(sc, r)));\n    const evalues = prels.filter(r => checkConform(sc, r) !== null);\n    const bad = evalues.filter(r => checkConform(sc, r) === false).length;\n    return { essais: essais.length, evalues: evalues.length, bad,\n             taux: evalues.length ? (bad/evalues.length)*100 : null };\n  };\n  const grille = equipes.map(eq => ({ eq, cols: data.map(sc => cellule(eq, sc)) }));\n\n  // seuil d'alerte : une equipe qui depasse de plus de 5 points la moyenne des autres sur\n  // le meme scenario, avec au moins 10 prelevements evalues (sinon c'est du bruit)\n  const alerte = (ligne, j) => {\n    const c = ligne.cols[j];\n    if(c.taux === null || c.evalues < 10) return false;\n    const autres = grille.filter(l => l !== ligne).map(l => l.cols[j]).filter(x => x.taux !== null && x.evalues >= 10);\n    if(!autres.length) return false;\n    const moy = autres.reduce((a,x) => a+x.taux, 0)/autres.length;\n    return c.taux > moy + 5;\n  };\n\n  const head = `<tr><th class=\"crit\">\u00c9quipe</th>${data.map(sc =>\n    `<th class=\"sc-col${sc.baseline ? \" is-baseline\" : \"\"}\">${escapeAttr(sc.name)}${sc.baseline ? \" \u2605\" : \"\"}</th>`).join(\"\")}</tr>`;\n  const body = grille.map(ligne => `<tr><td class=\"crit\">${escapeAttr(ligne.eq)}</td>${\n    ligne.cols.map((c,j) => {\n      if(!c.evalues) return `<td>\u2014</td>`;\n      const tip = `${c.essais} essai${c.essais>1?\"s\":\"\"} \u00b7 ${c.bad} pr\u00e9l\u00e8vement${c.bad>1?\"s\":\"\"} hors tol\u00e9rance sur ${c.evalues} \u00e9valu\u00e9${c.evalues>1?\"s\":\"\"}`;\n      const flag = alerte(ligne, j) ? ` <span class=\"badge risk\" title=\"Plus de 5 points au-dessus de la moyenne des autres \u00e9quipes sur ce sc\u00e9nario, sur au moins 10 pr\u00e9l\u00e8vements. \u00c0 regarder du c\u00f4t\u00e9 de la conduite (r\u00e9glage, changement d'outil, mode op\u00e9ratoire) avant d'incriminer la plaquette.\">\u00e9cart</span>` : \"\";\n      const petit = c.evalues < 10 ? ` <span class=\"dispersion-faible\" title=\"Moins de 10 pr\u00e9l\u00e8vements \u00e9valu\u00e9s : indicatif seulement.\">(n=${c.evalues})</span>` : \"\";\n      return `<td title=\"${escapeAttr(tip)}\">${fmt(c.taux,0)} %${petit}${flag}</td>`;\n    }).join(\"\")}</tr>`).join(\"\");\n\n  return `\n    <div class=\"synthese-block\">\n      <h3>Dispersion par \u00e9quipe \u2014 taux hors tol\u00e9rance</h3>\n      <p class=\"hint-bloc\">M\u00eame sc\u00e9nario, m\u00eame outil : un \u00e9cart marqu\u00e9 d'un poste \u00e0 l'autre pointe la conduite (r\u00e9glage, moment du changement d'outil, mode op\u00e9ratoire) plut\u00f4t que la plaquette. Les essais sans \u00e9quipe renseign\u00e9e ne sont pas compt\u00e9s.</p>\n      <div class=\"tbl-wrap\">\n        <table class=\"synthese\">\n          <thead>${head}</thead>\n          <tbody>${body}</tbody>\n        </table>\n      </div>\n    </div>\n  `;\n}\n\nfunction syntheseHTML(){\n  return feuilleRouteHTML() + syntheseTableHTML() + cascadeGainHTML() + dispersionEquipeHTML() + multiChartHTML();\n}\nfunction renderSynthese(){\n  const wrap = document.getElementById(\"syntheseWrap\");\n  if(!wrap || wrap.hidden) return; // masque -> pas de calcul, evite de ralentir la saisie\n  wrap.innerHTML = syntheseHTML();\n}\n\n/* ---- tabs / comparative strip ---- */\nfunction renderTabs(){\n  const el = document.getElementById(\"tabsStrip\");\n  const base = baseComparaison();\n  const baseCost = base ? scenarioCost(base) : null;\n  // v4.3 : la liste affichee respecte le filtre de projet actif (voir scenariosVisibles).\n  // Le numero de chaque tuile reste son rang dans `data` (la liste COMPLETE de l'OP), pas\n  // dans la liste filtree -- sinon \"le scenario 3\" changerait de sens selon le projet\n  // ouvert, ce qui casserait exactement la reperabilite que ce numero est cense donner.\n  const visibles = scenariosVisibles();\n  if(!visibles.length && data.length){\n    const pjActif = projets.find(p => p.id === activeProjetId);\n    el.innerHTML = `<p class=\"log-empty\" style=\"padding:16px 4px;\">Aucun sc\u00e9nario de \u00ab ${escapeAttr(pjActif ? pjActif.nom : \"\")} \u00bb sur cet OP.\n      <button class=\"ghost small\" id=\"voirTousScenariosBtn\" style=\"margin-left:8px;\">Voir tous les sc\u00e9narios de cet OP</button></p>`;\n    const btn = document.getElementById(\"voirTousScenariosBtn\");\n    if(btn) btn.addEventListener(\"click\", () => { activeProjetId = null; saveData(); render(); });\n    return;\n  }\n  // Le scenario ouvert passe en tete et s'affiche en grand : on lit d'abord ce qu'on\n  // regarde. Le numero, lui, reste celui de la creation \u2014 il ne bouge pas quand l'ordre\n  // d'affichage change, sinon on ne peut plus se dire \"regarde le 3\".\n  const numeroDe = new Map(data.map((sc, i) => [sc.id, i + 1]));\n  const ordre = visibles.map(sc => ({ sc, numero: numeroDe.get(sc.id) }));\n  ordre.sort((a, b) => (b.sc.id === activeId) - (a.sc.id === activeId));\n  const carte = ({ sc, numero }) => {\n    const cost = scenarioCost(sc);\n    const stats = scenarioStats(sc);\n    const scrap = scrapStats(sc);\n    // la liste des scenarios doit annoncer le meme chiffre que la fiche : sinon le rail\n    // dit -46 % pendant que le scenario ouvert affiche +33 %\n    const couts = coutsDetail(sc);\n    const coutsBase = base ? coutsDetail(base) : null;\n    const cRef = couts.multiPoste ? couts.total : cost;\n    const cRefBase = couts.multiPoste ? (coutsBase ? coutsBase.total : null) : baseCost;\n    let deltaHtml = `<span class=\"tc-delta zero\">r\u00e9f.</span>`;\n    if(sc.id !== (base ? base.id : null) && cRefBase !== null && cRefBase && cRef !== null){\n      const d = ((cRef - cRefBase) / cRefBase) * 100;\n      const cls = d > 0.05 ? \"pos\" : d < -0.05 ? \"neg\" : \"zero\";\n      deltaHtml = `<span class=\"tc-delta ${cls}\">${d>0?\"+\":\"\"}${fmt(d,1)} %</span>`;\n    }\n    const an = bilanAnnuel(sc, null, null, null, base);\n    return `\n      <button class=\"tab-card st-${sc.statut || \"essai\"} ${sc.id === activeId ? \"active\" : \"\"} ${sc.baseline ? \"is-baseline\" : \"\"}\" data-tab=\"${sc.id}\">\n        <span class=\"tc-head\">\n          <span class=\"tc-num\">${numero}</span>\n          <span class=\"tc-name\">${escapeAttr(sc.name)}${sc.baseline ? \" \u2605\" : \"\"}</span>\n        </span>\n        <span class=\"tc-badges\">\n          <span class=\"statut-pill ${sc.statut || \"essai\"}\">${statutLabel(sc.statut)}</span>\n          <span class=\"status-badge ${stats.validated ? \"ok\" : \"pending\"}\"${!stats.validated && parseFloat(sc.validationThreshold) === 5 ? ' title=\"Protocole site : un essai concluant est r\u00e9p\u00e9t\u00e9 5\u00d7 avant passage en s\u00e9rie\"' : \"\"}>${stats.validated ? \"\u2713 Valid\u00e9\" : `${stats.validCount}/${sc.validationThreshold || \"\u2014\"} essais conformes`}</span>\n        </span>\n        ${projets.length ? `<span class=\"tc-tags\">${projets.map(pj => {\n          const dedans = projetContientScenario(pj, activeLigneId, activeReferenceId, activeOpId, sc.id);\n          // couleur propre au projet (v4.2) plutot qu'un bleu uniforme : avec plusieurs\n          // etiquettes actives sur un meme scenario, chacune reste identifiable sans lire\n          // le texte -- la meme couleur que le petit point sur sa carte de projet.\n          const style = dedans ? ` style=\"background:${couleurProjet(pj)}; border-color:${couleurProjet(pj)};\"` : \"\";\n          // v4.29 : l'info-bulle dit quelles lignes le projet couvre d\u00e9j\u00e0 \u2014 le pi\u00e8ge\n          // \u00ab rattacher un sc\u00e9nario de HESSAPP au projet co\u00fbt EMAG 1 \u00bb se voit AVANT le clic\n          const ses = lignesDuProjet(pj);\n          const ctx = ses.length ? ` \u2014 contient : ${escapeAttr(ses.join(\", \"))}` : \"\";\n          return `<span class=\"tag-pill ${dedans ? \"on\" : \"\"}\"${style} data-projet=\"${pj.id}\" title=\"${dedans ? \"Retirer de\" : \"Ajouter \u00e0\"} \u00ab ${escapeAttr(pj.nom)} \u00bb${ctx}\">${dedans ? \"\u2713 \" : \"+ \"}${escapeAttr(pj.nom)}</span>`;\n        }).join(\"\")}</span>` : \"\"}\n        <span class=\"tc-row\"><span class=\"tc-label\">${couts.multiPoste ? \"\u20ac/pi\u00e8ce total\" : \"\u20ac/pi\u00e8ce\"}</span><span class=\"tc-val\">${cRef === null ? \"\u2014\" : fmt(cRef,4)}</span>${deltaHtml}</span>\n        ${an && an.gainAnnuel !== undefined ? `<span class=\"tc-row\"><span class=\"tc-label\">${an.gainAnnuel>=0?\"Gain/an\":\"Perte/an\"}</span><span class=\"tc-val ${an.gainAnnuel>=0?\"tc-gain\":\"tc-perte\"}\">${(an.gainAnnuel>=0?\"+\":\"\u2212\")+fmtEuroCourt(Math.abs(an.gainAnnuel))}</span></span>` : \"\"}\n        ${sc.id !== activeId ? \"\" : `\n        ${couts.multiPoste ? `<span class=\"tc-row\"><span class=\"tc-label\">dont plaquettes</span><span class=\"tc-val\">${couts.plaquettes === null ? \"\u2014\" : fmt(couts.plaquettes,4)}</span></span>` : \"\"}\n        <span class=\"tc-row\"><span class=\"tc-label\">Temps cycle</span><span class=\"tc-val\">${sc.cycle === \"\" || sc.cycle == null ? \"\u2014\" : fmt(parseFloat(sc.cycle),0)}${cycleSecondes(sc) !== null ? \" \u00b7 \" + fmt(cycleSecondes(sc),1) + \" s\" : \"\"}</span></span>\n        <span class=\"tc-row\"><span class=\"tc-label\">Essais</span><span class=\"tc-val\">${stats.essaisCount}${stats.badCount ? ` \u2014 ${stats.badCount} non conforme${stats.badCount>1?\"s\":\"\"}` : \"\"}</span></span>\n        <span class=\"tc-row\"><span class=\"tc-label\">Rebut ligne (\u00e9quipe)</span><span class=\"tc-val\">${scrap.rate === null ? \"\u2014\" : fmt(scrap.rate,1)+\" %\"}</span></span>`}\n      </button>\n    `;\n  };\n  // La tuile ouverte est sortie de la grille : si elle la traversait, la grille creerait\n  // autant de colonnes qu'elle peut en tenir et ecraserait les autres tuiles a 200 px.\n  const ouverte = ordre.filter(o => o.sc.id === activeId);\n  const autres  = ordre.filter(o => o.sc.id !== activeId);\n  el.innerHTML = '<div class=\"zone-band\"><b>1 &middot; Reponse</b><span>\u00e0 quoi on compare, et quel sc\u00e9nario gagne</span></div>' + baseBannerHTML() + pieceCPPBannerHTML() + '<div class=\"zone-band\"><b>2 &middot; Sc\u00e9narios</b><span>le sc\u00e9nario ouvert d abord, les autres ensuite</span></div>' + ouverte.map(carte).join(\"\") +\n    (autres.length ? `<div class=\"tabs-rest\">${autres.map(carte).join(\"\")}</div>` : \"\");\n  const selBase = document.getElementById(\"baseSel\");\n  if(selBase) selBase.addEventListener(\"change\", () => { setBaseComparaison(selBase.value); render(); });\n  el.querySelectorAll(\".tab-card\").forEach(b => {\n    b.addEventListener(\"click\", (e) => {\n      const pill = e.target.closest(\".tag-pill\");\n      if(pill){\n        const pj = projets.find(x => x.id === pill.getAttribute(\"data-projet\"));\n        const scId = b.getAttribute(\"data-tab\");\n        if(!pj) return;\n        /* v4.55.1 \u2014 rattacher un sc\u00e9nario d'une AUTRE LIGNE \u00e0 un projet est d\u00e9sormais\n           BLOQU\u00c9 (d\u00e9cision Benjamin, 29/09 : \u00ab Co\u00fbt et qualit\u00e9 EMAG 1 \u00bb est un projet\n           EMAG 1, rien d'autre).\n\n           Le trou corrig\u00e9 : avant, la r\u00e8gle n'avertissait que si le projet contenait\n           D\u00c9J\u00c0 des sc\u00e9narios d'une autre ligne. Un projet VIDE passait donc en silence,\n           et son nom (\u00ab \u2026 EMAG 1 \u00bb) annon\u00e7ait une restriction que rien n'appliquait \u2014\n           exactement le cas rencontr\u00e9.\n\n           On ne se fie pas au NOM du projet (c'est du texte libre) mais au FAIT mesur\u00e9 :\n           si le projet porte d\u00e9j\u00e0 des sc\u00e9narios, ils doivent tous \u00eatre de la ligne\n           courante. Pour ouvrir volontairement un projet \u00e0 une deuxi\u00e8me ligne, la\n           marche \u00e0 suivre est de rattacher d'abord un sc\u00e9nario de CETTE ligne ; le\n           projet devient alors multi-ligne et accueille l'autre sans question. */\n        const rattler = () => { toggleTagScenario(pj, activeLigneId, activeReferenceId, activeOpId, scId); saveData(); render(); };\n        if(!projetContientScenario(pj, activeLigneId, activeReferenceId, activeOpId, scId)){\n          const ses = lignesDuProjet(pj);\n          const ligneCourante = getActiveLigne();\n          const decision = projetAccepteLigne(pj, null, ligneCourante);\n          if(decision !== \"ok\"){\n            /* projet vide : on ne sait pas s'il est mono-ligne. On ne bloque pas \u2014 il\n               peut l\u00e9gitimement d\u00e9marrer sur une campagne commune \u2014 mais on le dit. */\n            if(decision === \"premier\"){\n              dialogueConfirmer(\n                \"\u00ab \" + pj.nom + \" \u00bb ne contient encore aucun sc\u00e9nario.\\n\\n\" +\n                \"Vous \u00eates sur \" + (ligneCourante.nom || \"une autre ligne\") + \" \u2014 ce sc\u00e9nario sera le premier du projet. Rattacher ?\",\n                { titre: \"Premier sc\u00e9nario du projet\", okLabel: \"Rattacher\" }).then(ok => { if(ok) rattler(); });\n              return;\n            }\n            /* projet d\u00e9j\u00e0 rattach\u00e9 \u00e0 une autre ligne : on refuse, et on dit comment\n               faire si l'intention est d'ouvrir le projet \u00e0 cette ligne. */\n            dialogueAlerte(\n              \"\u00ab \" + pj.nom + \" \u00bb ne contient que des sc\u00e9narios de : \" + ses.join(\", \") + \".\\n\\n\" +\n              \"Vous \u00eates sur \" + (ligneCourante.nom || \"une autre ligne\") + \" : ce sc\u00e9nario ne peut pas y \u00eatre rattach\u00e9.\\n\\n\" +\n              \"Si vous voulez vraiment ouvrir ce projet \u00e0 cette ligne, rattachez d'abord un sc\u00e9nario de \" +\n              (ligneCourante.nom || \"cette ligne\") + \" \u2014 le projet deviendra alors multi-ligne.\",\n              \"Projet d'une seule ligne\");\n            return;\n          }\n        }\n        rattler();\n        return;\n      }\n      activeId = b.getAttribute(\"data-tab\"); render();\n    });\n  });\n}\n\n/* ---- statut de vie d'un scenario ----\n   \"valide\" = techniquement conforme, \"serie\" = reellement passe en production. Les deux\n   ne se confondent pas, et un scenario abandonne garde son motif : c'est ce qui evite de\n   refaire deux ans plus tard une impasse deja explor\u00e9e. */\nconst STATUTS = [\n  { v:\"etude\",     label:\"\u00c0 l'\u00e9tude\" },\n  { v:\"essai\",     label:\"En essai\" },\n  { v:\"valide\",    label:\"Valid\u00e9\" },\n  { v:\"serie\",     label:\"En s\u00e9rie\" },\n  { v:\"abandonne\", label:\"Abandonn\u00e9\" }\n];\nfunction statutLabel(v){\n  const s = STATUTS.find(x => x.v === (v || \"essai\"));\n  return s ? s.label : \"En essai\";\n}\nfunction statutSelectHTML(sc){\n  const cur = sc.statut || \"essai\";\n  const opts = STATUTS.map(s => `<option value=\"${s.v}\" ${cur === s.v ? \"selected\" : \"\"}>${s.label}</option>`).join(\"\");\n  // v4.4 : le scenario en production (\u2605) a son statut verrouille sur \"En serie\" -- en\n  // sortir passe par la redefinition de la reference (pastille \u2605 sur un autre scenario),\n  // jamais par ce menu directement. Le menu reste techniquement modifiable (necessaire\n  // pour que le \"change\" se declenche et route vers appliquerChangementStatut, qui refuse\n  // et reaffiche la vraie valeur) mais visuellement attenue, avec l'explication en info-bulle.\n  const verrouille = !!sc.baseline;\n  return `<span class=\"statut-wrap\">\n    <select class=\"statut-select ${cur} ${verrouille ? \"verrouille\" : \"\"}\" data-id=\"${sc.id}\" data-field=\"statut\"\n            ${verrouille ? `title=\"Sc\u00e9nario en production (\u2605) \u2014 red\u00e9finissez la r\u00e9f\u00e9rence pour lui donner un autre statut.\"` : \"\"}>${opts}</select>\n    ${verrouille ? `<span class=\"statut-lock\" title=\"Verrouill\u00e9 : sc\u00e9nario en production\">\ud83d\udd12</span>` : \"\"}\n    ${cur === \"abandonne\" ? `<input class=\"statut-motif\" data-id=\"${sc.id}\" data-field=\"statutMotif\" value=\"${escapeAttr(sc.statutMotif)}\" placeholder=\"Motif de l'abandon (usure, battement, cadence\u2026)\">` : \"\"}\n  </span>`;\n}\n\n/* ---- shared markup for one scenario (interactive on screen, static for print) ---- */\nfunction scenarioBlockHTML(sc, interactive){\n  const stats = scenarioStats(sc);\n\n  const head = interactive ? `\n      <input class=\"sc-name\" data-id=\"${sc.id}\" data-field=\"name\" value=\"${escapeAttr(sc.name)}\">\n      <span class=\"baseline-pill ${sc.baseline ? \"active\" : \"\"}\" data-id=\"${sc.id}\" data-action=\"baseline\" title=\"${sc.baseline\n        ? \"Sc\u00e9nario en production : celui qui tourne r\u00e9ellement en s\u00e9rie, toujours visible m\u00eame filtr\u00e9 par un projet. Cliquer sur \u2605 un autre sc\u00e9nario le remplace ici.\"\n        : \"\u00ab R\u00e9f\u00e9rence \u00bb ici d\u00e9signe le sc\u00e9nario de comparaison (\u2605), pas la r\u00e9f\u00e9rence disque ni la r\u00e9f\u00e9rence plaquette. Le d\u00e9signer en fait le sc\u00e9nario en production : son statut passera \u00e0 \u00ab En s\u00e9rie \u00bb et il restera toujours visible, m\u00eame filtr\u00e9 par un projet.\"}\">${sc.baseline ? \"\u2605 Sc\u00e9nario r\u00e9f.\" : \"D\u00e9finir sc\u00e9nario r\u00e9f.\"}</span>\n      ${statutSelectHTML(sc)}\n      <div class=\"sc-actions\">\n        <button data-id=\"${sc.id}\" data-action=\"duplicate\">Dupliquer</button>\n        <button data-id=\"${sc.id}\" data-action=\"delete\" ${data.length <= 1 ? \"disabled\" : \"\"}>Supprimer</button>\n      </div>\n  ` : `<span class=\"sc-name-print\">${escapeAttr(sc.name)}${sc.baseline ? \" \u2014 R\u00e9f\u00e9rence\" : \"\"}</span><span class=\"statut-pill ${sc.statut||\"essai\"}\">${statutLabel(sc.statut)}</span>`;\n\n  // rayon de bec / ap ne servent qu'a l'affinage Fr\u00b7Fa (module optionnel, rarement actif \u2014 voir\n  // Options) : les masquer par defaut allege le tableau de 2 colonnes sur 14. \u03bar, lui, reste\n  // toujours visible car il alimente aussi le widget K (suivi thermique), utile meme sans Fr\u00b7Fa.\n  const showFrFa = !!config.forceRatioActif;\n  const showCycleDetail = !!config.cycleDetailActif;\n  const posColspan = (interactive ? 15 : 14) - (showFrFa ? 0 : 2) + (showCycleDetail ? 1 : 0);\n  // largeurs explicites : sans elles le navigateur repartit les colonnes a peu pres egalement,\n  // ce qui coupe \"Reference plaquette\" (texte le plus long) et laisse des colonnes numeriques\n  // courtes (Aretes, ap...) bien trop larges\n  const posCols = `\n    <colgroup>\n      <col style=\"width:6%\">\n      <col style=\"width:7%\">\n      <col style=\"width:${showFrFa ? 20 : 30}%\">\n      <col style=\"width:5%\">\n      <col style=\"width:4%\">\n      <col style=\"width:6%\">\n      <col style=\"width:${showFrFa ? 9 : 10}%\">\n      <col style=\"width:${showFrFa ? 5 : 6}%\">\n      <col style=\"width:${showFrFa ? 5 : 6}%\">\n      <col style=\"width:5%\">\n      ${showFrFa ? '<col style=\"width:7%\"><col style=\"width:4%\">' : \"\"}\n      ${showCycleDetail ? '<col style=\"width:6%\">' : \"\"}\n      <col style=\"width:6%\">\n      <col style=\"width:6%\">\n      ${interactive ? '<col style=\"width:2%\">' : \"\"}\n    </colgroup>\n  `;\n  const posTableau = `\n    <div class=\"tbl-wrap\">\n      <table class=\"postable\">\n        ${posCols}\n        <thead>\n          <tr>\n            <th>N\u00b0 Outil</th>\n            <th>Logement</th>\n            <th>R\u00e9f\u00e9rence plaquette</th>\n            <th class=\"num\">Prix (\u20ac)</th>\n            <th class=\"num\">Ar\u00eates</th>\n            <th class=\"num\">Charni\u00e8re (p/ar\u00eate)</th>\n            <th>Crit\u00e8re valid\u00e9</th>\n            <th class=\"num\">Vc (m/min)</th>\n            <th class=\"num\">f (mm/rev)</th>\n            <th class=\"num\">\u03bar (\u00b0)</th>\n            ${showFrFa ? '<th class=\"num\">Rayon de bec r\u03b5 (mm)</th><th class=\"num\">ap (mm)</th>' : \"\"}\n            ${showCycleDetail ? '<th class=\"num\">Temps coupe (s)</th>' : \"\"}\n            <th class=\"num\">\u20ac / ar\u00eate</th>\n            <th class=\"num\">\u20ac / pi\u00e8ce</th>\n          </tr>\n        </thead>\n        <tbody>\n          ${sc.outils.map((o, oi) => outilRowsHTML(sc, o, oi, showFrFa, showCycleDetail)).join(\"\") || `<tr><td colspan=\"${posColspan}\" class=\"log-empty\">Aucun outil configur\u00e9</td></tr>`}\n        </tbody>\n      </table>\n    </div>`;\n\n  // A l'ecran on saisit : fiches, un champ = un libelle + une largeur adaptee.\n  // A l'impression on lit : le tableau compact garde tout son sens, rien n'y est saisissable.\n  const posFiches = `\n    <div class=\"outils-liste\">\n      ${sc.outils.map((o, oi) => outilCarteHTML(sc, o, oi, showFrFa, showCycleDetail)).join(\"\")\n        || `<p class=\"log-empty\" style=\"padding:14px 2px;\">Aucun outil configur\u00e9</p>`}\n    </div>`;\n\n  const posTable = `\n    ${interactive ? posFiches : posTableau}\n    ${interactive ? `<button class=\"ghost outil-add\" data-id=\"${sc.id}\" style=\"margin-top:10px;\">+ Ajouter un outil</button>` : \"\"}\n    ${interactive && copieDepuisPossible(sc) ? `<button class=\"ghost outils-copier\" data-id=\"${sc.id}\" style=\"margin-top:10px;\">\u29c9 Copier les outils de \u00ab ${escapeAttr(baselineScenario().name)} \u00bb</button>` : \"\"}\n    ${interactive && outilsManquants(sc).length ? `<button class=\"ghost outils-completer\" data-id=\"${sc.id}\" style=\"margin-top:10px;\" title=\"Ajouter \u00e0 ce sc\u00e9nario les outils qui tournent en prod mais manquent ici (base excel) \u2014 les outils d'essai et les essais enregistr\u00e9s ne sont pas touch\u00e9s. Comparer un sc\u00e9nario incomplet \u00e0 une prod compl\u00e8te fausse le co\u00fbt pi\u00e8ce.\">\u229e Compl\u00e9ter depuis la prod (${outilsManquants(sc).length} outil${outilsManquants(sc).length>1?\"s\":\"\"} manquant${outilsManquants(sc).length>1?\"s\":\"\"})</button>` : \"\"}}\n    ${interactive && !showFrFa ? `<p class=\"panel-hint\" style=\"margin:8px 2px 0;\">Rayon de bec et ap (affinage Fr\u00b7Fa) sont masqu\u00e9s \u2014 activez le module Fr\u00b7Fa dans <b>Options</b> si votre r\u00e9f\u00e9rence en a besoin.</p>` : \"\"}\n    ${interactive ? `<details class=\"zone-det\"><summary>D\u00e9tail du calcul, consommation annuelle &amp; pi\u00e8ces d\u00e9tach\u00e9es</summary>` : \"\"}\n    ${cycleDetailStatusHTML(sc)}\n    ${consommationAnnuelleHTML(sc)}\n    ${piecesDetacheesHTML(sc, interactive)}\n    ${interactive ? `</details>` : \"\"}\n  `;\n\n  const cost = scenarioCost(sc);\n  const base = baselineScenario();\n  const baseCost = base ? scenarioCost(base) : null;\n  const baseCycle = base ? parseFloat(base.cycle) : null;\n  let deltaHtml = `<span class=\"delta zero\">r\u00e9f.</span>`;\n  if(!sc.baseline && baseCost !== null && cost !== null){\n    const d = ((cost - baseCost) / baseCost) * 100;\n    const cls = d > 0.05 ? \"pos\" : d < -0.05 ? \"neg\" : \"zero\";\n    deltaHtml = `<span class=\"delta ${cls}\">${d>0?\"+\":\"\"}${fmt(d,1)} %</span>`;\n  }\n  let cycleDeltaHtml = `<span class=\"delta zero\">r\u00e9f.</span>`;\n  const cyc = parseFloat(sc.cycle);\n  if(!sc.baseline && baseCycle && !isNaN(cyc)){\n    const d = ((cyc - baseCycle) / baseCycle) * 100;\n    const cls = d > 0.5 ? \"pos\" : d < -0.5 ? \"neg\" : \"zero\";\n    cycleDeltaHtml = `<span class=\"delta ${cls}\">${d>0?\"+\":\"\"}${fmt(d,1)} %</span>`;\n  }\n  // le scenario de reference vaut toujours 100 par definition (recomputeCycles le reimpose\n  // a chaque chargement) : le rendre editable laissait croire qu'une autre valeur tenait,\n  // alors qu'elle etait ecrasee silencieusement au rechargement suivant\n  const cycleCell = !interactive\n    ? `<div class=\"v\">${sc.cycle === \"\" || sc.cycle === undefined ? \"\u2014\" : fmt(parseFloat(sc.cycle),0)}</div>`\n    : sc.baseline\n      ? `<div class=\"v\" title=\"Le sc\u00e9nario de r\u00e9f\u00e9rence vaut toujours 100, par d\u00e9finition.\">100</div>`\n      : `<input class=\"cell-cycle\" data-id=\"${sc.id}\" data-field=\"cycle\" type=\"number\" step=\"1\" value=\"${sc.cycle ?? \"\"}\">`;\n\n  const secs = cycleSecondes(sc);\n  const cadence = cadenceHeure(sc);\n  /* v4.39 \u2014 la cellule cycle raconte tout : valeur, cadence, d'o\u00f9 elle vient (mesures\n     machine compl\u00e8tes ou indice), comment les logements composent le cycle (s\u00e9rie ou\n     simultan\u00e9), et ce qu'il co\u00fbte en machine \u2014 AFFICH\u00c9 d\u00e8s que le taux horaire existe,\n     la pond\u00e9ration dans le co\u00fbt pi\u00e8ce restant de son c\u00f4t\u00e9 d\u00e9cid\u00e9e par l'option. */\n  const stCycle = cycleDetailStatus(sc, config);\n  const cycleSecLine = `<div class=\"foot-sub\">${secs === null ? \"\u2014\" : fmt(secs,1)+\" s\"}${cadence ? \" \u00b7 \" + fmt(cadence,0) + \" p/h\" : \"\"}${stCycle.complete ? ` \u00b7 mesures machine (${stCycle.filled}/${stCycle.total} logements)` : \"\"}</div>`;\n  const cycleModeLine = stCycle.total > 1 && stCycle.nbOutils > 1\n    ? `<div class=\"foot-sub\">${stCycle.nbGroupes < stCycle.nbOutils\n        ? stCycle.nbGroupes + \" groupe\" + (stCycle.nbGroupes>1?\"s\":\"\") + \" d'outils simultan\u00e9s \u2014 chaque groupe vaut son outil le plus long\"\n        : \"outils en s\u00e9rie \u2014 les temps s'additionnent\"}</div>`\n    : \"\";\n  const tauxLigne = (() => { const lg = getActiveLigne(); const t = lg ? parseFloat(lg.coutHoraire) : NaN; return isNaN(t) ? null : t; })();\n  const coutMachPiece = (tauxLigne !== null && secs !== null) ? (tauxLigne/3600)*secs : null;\n  const cycleMachineLine = coutMachPiece !== null\n    ? `<div class=\"foot-sub\">${fmt(coutMachPiece,4)} \u20ac machine/pi\u00e8ce${config.coutMachineActif ? \"\" : \" \u00b7 affich\u00e9, non pond\u00e9r\u00e9 (option inactive)\"}</div>`\n    : (config.coutMachineActif ? `<div class=\"foot-sub\" style=\"color:var(--on-fill-warn);\">taux horaire de la ligne non renseign\u00e9 \u2014 le temps machine ne peut pas \u00eatre chiffr\u00e9</div>` : \"\");\n  // recomputeCycles() ne peut rien recalculer sans Vc/f exploitables sur la reference : le\n  // dire, plutot que laisser un indice fige sans explication (cas silencieux avant ce fix)\n  const baseLogCycle = sc.baseline ? null : (base ? logementCycle(base) : null);\n  const baseVfManquant = !sc.baseline && base && (!baseLogCycle\n    || isNaN(parseFloat(baseLogCycle.vc)) || isNaN(parseFloat(baseLogCycle.f))\n    || parseFloat(baseLogCycle.vc) * parseFloat(baseLogCycle.f) === 0);\n  const cycleVfWarnLine = baseVfManquant\n    ? `<div class=\"foot-sub\" style=\"color:var(--on-fill-warn);\">\u26a0 Vc/f de la r\u00e9f\u00e9rence manquants \u2014 l'indice n'est plus recalcul\u00e9 automatiquement</div>` : \"\";\n\n  // ---- economie : un seul chiffre de tete, decompose poste par poste ----\n  const couts = coutsDetail(sc);\n  const coutsBase = base ? coutsDetail(base) : null;\n  // le delta se calcule sur le meme perimetre que le chiffre affiche : des que plusieurs\n  // postes entrent en jeu, comparer les seules plaquettes n'a plus de sens\n  let deltaTotalHtml = `<span class=\"delta zero\">r\u00e9f.</span>`;\n  const periFoot = (!sc.baseline && coutsBase) ? perimetreCompare(couts, coutsBase) : null;\n  if(periFoot && periFoot.communs.length && periFoot.base > 0){\n    const d = ((periFoot.sc - periFoot.base) / periFoot.base) * 100;\n    const cls = d > 0.05 ? \"pos\" : d < -0.05 ? \"neg\" : \"zero\";\n    const titre = periFoot.exclus.length\n      ? \"Comparaison sur le p\u00e9rim\u00e8tre commun (\" + periFoot.communs.map(c => c[1]).join(\" + \") + \") \u2014 hors : \" + periFoot.exclus.join(\", \")\n      : \"Comparaison \u00e0 p\u00e9rim\u00e8tre identique (tous les postes chiffrables)\";\n    deltaTotalHtml = `<span class=\"delta ${cls}\" title=\"${titre}\">${d>0?\"+\":\"\"}${fmt(d,1)} %</span>`;\n  }\n  const refActive = getActiveReference();\n  const cibleCPP = refActive && refActive.cibleCPP !== \"\" && refActive.cibleCPP != null && !isNaN(parseFloat(refActive.cibleCPP)) ? parseFloat(refActive.cibleCPP) : null;\n  const cibleLine = (cibleCPP !== null && !sc.baseline) ? \"\" : (cibleCPP !== null ? `<div class=\"foot-sub\">cible site : ${fmt(cibleCPP,3)} \u20ac/pi\u00e8ce (excel consommations)</div>` : \"\");\n  const coutCell = couts.multiPoste ? `\n      <div class=\"foot-cell foot-cell-wide\">\n        <div class=\"l\">Co\u00fbt total / pi\u00e8ce</div>\n        <div class=\"v\">${couts.total === null ? \"\u2014\" : fmt(couts.total,4)}<small>\u20ac</small></div>\n        ${couts.multiPoste ? deltaTotalHtml : deltaHtml}\n        ${coutBreakdownHTML(couts)}\n        ${cibleLine}\n        ${periFoot && periFoot.exclus.includes(\"temps machine\") ? `<div class=\"foot-sub\" style=\"color:var(--on-fill-warn);\" title=\"Le co\u00fbt affich\u00e9 int\u00e8gre le temps machine de CE sc\u00e9nario, mais la r\u00e9f\u00e9rence n'a pas de cycle chiffrable (ni mesures compl\u00e8tes, ni cycle de r\u00e9f\u00e9rence en secondes). Le % compare donc les p\u00e9rim\u00e8tres communs.\">Comparaison hors temps machine \u2014 la r\u00e9f\u00e9rence n'a pas de cycle chiffrable \u00b7 renseigne le cycle de r\u00e9f\u00e9rence en secondes pour un \u00ab tout compris \u00bb</div>` : \"\"}\n      </div>` : `\n      <div class=\"foot-cell\">\n        <div class=\"l\">Co\u00fbt outil / pi\u00e8ce</div>\n        <div class=\"v\">${cost === null ? \"\u2014\" : fmt(cost,4)}<small>\u20ac</small></div>\n        ${deltaHtml}\n        ${cibleLine}\n      </div>`;\n\n  const annuel = bilanAnnuel(sc, config, null, null);\n  const annuelCell = annuel ? `\n      <div class=\"foot-cell foot-cell-annuel${coutAnnuelDetailOuvert ? \" ouvert\" : \"\"}\" title=\"Cliquer pour d\u00e9plier le d\u00e9tail du calcul${sc.baseline ? \"\" : \" du gain\"}\">\n        <div class=\"l\">${sc.baseline ? \"Co\u00fbt annuel\" : \"Gain annuel\"}</div>\n        ${sc.baseline || annuel.gainAnnuel === undefined\n          ? `<div class=\"v mid\">${annuel.coutAnnuel === null ? \"\u2014\" : fmtEuroCourt(annuel.coutAnnuel)}</div>\n             <div class=\"foot-sub\">${fmt(annuel.volume,0)} disques/an</div>`\n          : `<div class=\"v mid\" style=\"color:${annuel.gainAnnuel >= 0 ? \"var(--on-fill-good)\" : \"var(--on-fill-bad)\"};\">${(annuel.gainAnnuel>=0?\"+\":\"\u2212\") + fmtEuroCourt(Math.abs(annuel.gainAnnuel))}</div>\n             <div class=\"foot-sub\">sur ${fmt(annuel.volume,0)} disques/an${annuel.heuresAnnuelles !== undefined ? ` \u00b7 ${annuel.heuresAnnuelles>=0?\"+\":\"\u2212\"}${fmt(Math.abs(annuel.heuresAnnuelles),0)} h machine` : \"\"}</div>`}\n        ${(!sc.baseline && !config.coutMachineActif && baseCycle && !isNaN(cyc) && Math.abs(cyc - baseCycle) > 0.5)\n          ? `<div class=\"foot-sub\" style=\"color:var(--on-fill-warn);\">\u26a0 \u00e9cart de cycle non chiffr\u00e9 ici \u2014 activez \u00ab Int\u00e9grer le temps machine au co\u00fbt pi\u00e8ce \u00bb dans Options</div>` : \"\"}\n        ${(!sc.baseline && annuel && annuel.perimetrePartiel && annuel.perimetrePartiel.includes(\"temps machine\"))\n          ? `<div class=\"foot-sub\" style=\"color:var(--on-fill-warn);\">Gain annuel hors temps machine \u2014 la r\u00e9f\u00e9rence n'a pas de cycle chiffrable \u00b7 renseigne le cycle de r\u00e9f\u00e9rence en secondes pour une comparaison tout compris</div>` : \"\"}\n      </div>` : \"\";\n\n  /* v4.30 \u2014 un seul tableau de bord : le verdict ouvre la bande, les chiffres suivent.\n     La dur\u00e9e de vie a sa cellule (elle quittait les chips du verdict) ; le % hors tol\u00e9rance\n     rejoint la cellule validation. Le d\u00e9tail du co\u00fbt annuel (v4.29) se d\u00e9plie en bas de\n     bande, sur toute la largeur, au lieu de couper la rang\u00e9e de cellules en deux. */\n  const vieScCell = dureeVieScenario(sc), vieBaseCell = base ? dureeVieScenario(base) : null;\n  const foot = `\n    <div class=\"scenario-foot\">\n      ${verdictHTML(sc)}\n      ${coutCell}\n      ${annuelCell}\n      <div class=\"foot-cell\">\n        <div class=\"l\">Dur\u00e9e de vie vis\u00e9e</div>\n        <div class=\"v mid\">${vieScCell === null ? \"\u2014\" : fmt(vieScCell,0)}<small>p/ar\u00eate</small></div>\n        ${!sc.baseline && vieBaseCell !== null\n          ? `<div class=\"foot-sub\">r\u00e9f. ${fmt(vieBaseCell,0)} p/ar\u00eate</div>`\n          : `<div class=\"foot-sub\">charni\u00e8re du logement de r\u00e9f\u00e9rence</div>`}\n      </div>\n      <div class=\"foot-cell\">\n        <div class=\"l\">\u20ac / ar\u00eate (tous logements)</div>\n        <div class=\"v\">${fmt(scenarioCostPerEdge(sc), 3)}<small>\u20ac</small></div>\n      </div>\n      <div class=\"foot-cell\">\n        <div class=\"l\">Temps de cycle \u2014 indice base 100 (\u00e9ditable)</div>\n        ${cycleCell}\n        ${cycleDeltaHtml}\n        ${cycleModeLine}\n        ${cycleSecLine}\n        ${cycleMachineLine}\n        ${cycleVfWarnLine}\n      </div>\n      <div class=\"foot-cell\">\n        <div class=\"l\">Validation sc\u00e9nario</div>\n        <div class=\"v small\">${stats.validCount}<small>/ ${sc.validationThreshold || \"\u2014\"} essais conformes</small></div>\n        <div class=\"progress-track\"><div class=\"progress-fill\" style=\"width:${(sc.validationThreshold ? Math.min(100, stats.validCount/parseFloat(sc.validationThreshold)*100) : 0)}%;\"></div></div>\n        ${stats.rate !== null ? `<div class=\"foot-sub\">${fmt(stats.rate,0)} % de pr\u00e9l\u00e8vements hors tol\u00e9rance</div>` : \"\"}\n        ${parseFloat(sc.validationThreshold) === 5\n          ? `<div class=\"foot-sub\" title=\"Protocole du site (sept. 2026) : un essai concluant est r\u00e9p\u00e9t\u00e9 5\u00d7 ; valid\u00e9 5\u00d7 et viable \u00e9conomiquement, il passe en production.\">Protocole site : essai concluant r\u00e9p\u00e9t\u00e9 5\u00d7 + viabilit\u00e9 \u00e9co</div>`\n          : `<div class=\"foot-sub\">Seuil de validation propre \u00e0 ce sc\u00e9nario : ${sc.validationThreshold || \"\u2014\"} essais conformes</div>`}\n      </div>\n      ${annuel ? `<div class=\"foot-detail\"${coutAnnuelDetailOuvert ? \"\" : \" hidden\"}>${coutAnnuelDetailHTML(sc, annuel)}</div>` : \"\"}\n    </div>\n    ${seuilBasculeHTML(sc)}\n    ${ecartsCharniereHTML(sc)}\n  `;\n\n  const emagRow = interactive ? `\n    <label class=\"emag-toggle\">\n      <input type=\"checkbox\" data-id=\"${sc.id}\" data-field=\"emag1\" ${sc.emag1 ? \"checked\" : \"\"}>\n      Mesure Droite / Gauche (ligne EMAG 1)\n    </label>\n  ` : `<div class=\"emag-toggle-print\">${sc.emag1 ? \"Mesure Droite / Gauche (EMAG 1)\" : \"Mesure simple (EMAG 2)\"}</div>`;\n\n  /* v4.9 \u2014 le bloc de crit\u00e8res, refondu : le battement se d\u00e9coche, sa tol\u00e9rance s'\u00e9dite\n     ici m\u00eame (l'\u00e9diter la rend sp\u00e9cifique au sc\u00e9nario \u2014 plus de case \u00e0 cocher au pr\u00e9alable),\n     ses c\u00f4t\u00e9s se s\u00e9lectionnent (un essai peut ne porter qu'un seul c\u00f4t\u00e9), et les crit\u00e8res\n     suppl\u00e9mentaires (Ra, VE, crit\u00e8re libre) se g\u00e8rent en liste avec bornes et axes. */\n  const limitRow = interactive ? `\n    <div class=\"limit-row\">\n      <label class=\"emag-toggle\" title=\"D\u00e9cocher si l'essai ne doit pas \u00eatre jug\u00e9 sur le battement (ex. essai uniquement sur l'\u00e9tat de surface)\">\n        <input type=\"checkbox\" data-id=\"${sc.id}\" data-field=\"battActif\" ${sc.battActif !== false ? \"checked\" : \"\"}>\n        Battement\n      </label>\n      <input class=\"limit-label\" data-id=\"${sc.id}\" data-field=\"limitLabel\" value=\"${escapeAttr(libelleDe(sc))}\" ${sc.battActif === false ? \"disabled\" : \"\"}>\n      <span>\u2264</span>\n      <input class=\"limit-value\" data-id=\"${sc.id}\" data-field=\"limitValue\" type=\"number\" step=\"0.001\" value=\"${limiteDe(sc) ?? \"\"}\" ${sc.battActif === false ? \"disabled\" : \"\"}>\n      ${battCotesDe(sc) !== \"mono\" ? `\n        <select class=\"cell small\" data-id=\"${sc.id}\" data-field=\"battCotes\" title=\"C\u00f4t\u00e9s mesur\u00e9s \u2014 un essai peut ne porter qu'un seul c\u00f4t\u00e9\">\n          <option value=\"DG\" ${(sc.battCotes || \"DG\")===\"DG\"?\"selected\":\"\"}>Droite + Gauche</option>\n          <option value=\"D\" ${sc.battCotes===\"D\"?\"selected\":\"\"}>Droite seul</option>\n          <option value=\"G\" ${sc.battCotes===\"G\"?\"selected\":\"\"}>Gauche seul</option>\n        </select>` : \"\"}\n      <span class=\"limit-op-note\" title=\"${sc.limitOverride ? \"Tol\u00e9rance sp\u00e9cifique \u00e0 ce sc\u00e9nario (la valeur OP a \u00e9t\u00e9 \u00e9dit\u00e9e).\" : \"Valeur OP \u2014 l'\u00e9diter la rend sp\u00e9cifique \u00e0 ce sc\u00e9nario.\"}\">${sc.limitOverride ? \"tol\u00e9rance sp\u00e9cifique\" : \"valeur OP\"}</span>\n    </div>\n  ` : `<div class=\"limit-row-print\">${sc.battActif === false ? \"Battement non jug\u00e9 \u2014 \" : \"\"}${escapeAttr(libelleDe(sc))} \u2264 ${fmt(parseFloat(limiteDe(sc)),3)}${sc.limitOverride ? \" (tol\u00e9rance sp\u00e9cifique)\" : \"\"}</div>`;\n\n  const AXES_DEFS = [[\"D\",\"Droite\"],[\"G\",\"Gauche\"],[\"I\",\"Inter\"],[\"E\",\"Exter\"]];\n  const csupRows = interactive ? (sc.criteresSup||[]).map(c => `\n    <div class=\"limit-row csup-row\">\n      <label class=\"emag-toggle\" title=\"D\u00e9cocher sans supprimer (garde la saisie existante)\"><input type=\"checkbox\" data-id=\"${sc.id}\" data-csup=\"${c.id}\" data-csfield=\"actif\" ${c.actif !== false ? \"checked\" : \"\"}></label>\n      <input class=\"limit-label\" data-id=\"${sc.id}\" data-csup=\"${c.id}\" data-csfield=\"label\" value=\"${escapeAttr(c.label || \"\")}\" placeholder=\"ex. Ra (\u00b5m)\">\n      <span>\u2264</span>\n      <input class=\"limit-value\" data-id=\"${sc.id}\" data-csup=\"${c.id}\" data-csfield=\"maxi\" type=\"number\" step=\"0.001\" value=\"${c.maxi ?? \"\"}\">\n      <label class=\"emag-toggle\" title=\"Activer une borne minimale (plage min\u2013max)\"><input type=\"checkbox\" data-id=\"${sc.id}\" data-csup=\"${c.id}\" data-csfield=\"miniActif\" ${c.miniActif ? \"checked\" : \"\"}>min</label>\n      <input class=\"limit-value\" data-id=\"${sc.id}\" data-csup=\"${c.id}\" data-csfield=\"mini\" type=\"number\" step=\"0.001\" value=\"${c.mini ?? \"\"}\" ${c.miniActif ? \"\" : \"disabled\"} placeholder=\"min\">\n      ${AXES_DEFS.map(([ax, nom]) => `\n        <label class=\"emag-toggle\" title=\"Mesure ${nom}\"><input type=\"checkbox\" data-id=\"${sc.id}\" data-csup=\"${c.id}\" data-csfield=\"axe\" data-axe=\"${ax}\" ${((c.axes||[]).indexOf(ax)!==-1)?\"checked\":\"\"}>${nom}</label>`).join(\"\")}\n      <button class=\"log-del csup-del\" data-id=\"${sc.id}\" data-csup=\"${c.id}\" title=\"Supprimer ce crit\u00e8re\">\u2715</button>\n    </div>`).join(\"\") : (sc.criteresSup||[]).filter(c => c.actif !== false).map(c => {\n      const axesTxt = (c.axes && c.axes.length) ? \" \u2014 \" + c.axes.map(a => ({D:\"Droite\",G:\"Gauche\",I:\"Inter\",E:\"Exter\"})[a] || a).join(\" / \") : \"\";\n      return `<div class=\"limit-row-print\">${escapeAttr(c.label || \"crit\u00e8re\")} \u2264 ${fmt(parseFloat(c.maxi),3)}${c.miniActif ? \" (min \" + fmt(parseFloat(c.mini),3) + \")\" : \"\"}${axesTxt}</div>`;\n    }).join(\"\");\n  const csupAddRow = interactive ? `\n    <div class=\"limit-row\">\n      <button class=\"ghost small csup-add\" data-id=\"${sc.id}\" data-cstype=\"ra\" title=\"\u00c9tat de surface Ra (\u00b5m) \u2014 borne maxi, mini optionnelle, c\u00f4t\u00e9s Droite/Gauche ou Inter/Exter\">+ Ra</button>\n      <button class=\"ghost small csup-add\" data-id=\"${sc.id}\" data-cstype=\"ve\" title=\"Variation d'\u00e9paisseur VE (mm) \u2014 borne maxi, mini optionnelle, c\u00f4t\u00e9s Droite/Gauche ou Inter/Exter\">+ VE</button>\n      <button class=\"ghost small csup-add\" data-id=\"${sc.id}\" data-cstype=\"libre\" title=\"Tout crit\u00e8re libre \u2014 libell\u00e9, borne maxi (mini optionnelle), c\u00f4t\u00e9s Droite/Gauche ou Inter/Exter\">+ Autre crit\u00e8re\u2026</button>\n    </div>` : \"\";\n\n  const thresholdRow = interactive ? `\n    <div class=\"limit-row\">\n      <span>Seuil de validation \u2014</span>\n      <input class=\"limit-value\" data-id=\"${sc.id}\" data-field=\"validationThreshold\" type=\"number\" step=\"1\" min=\"1\" value=\"${sc.validationThreshold ?? \"\"}\">\n      <span>relev\u00e9s conformes</span>\n      <label class=\"emag-toggle\" title=\"Coche cette case pour que le rapport de chaque essai embarque le(s) graphique(s) de Tendance (battement, Ra, VE... selon les crit\u00e8res suivis)\">\n        <input type=\"checkbox\" data-id=\"${sc.id}\" data-field=\"tendanceRapport\" ${sc.tendanceRapport ? \"checked\" : \"\"}>\n        Inclure le graphe de Tendance dans les rapports d'essai\n      </label>\n    </div>\n  ` : `<div class=\"limit-row-print\">Seuil de validation : ${sc.validationThreshold ?? \"\u2014\"} relev\u00e9s conformes</div>`;\n\n  const essaisHtml = (sc.essais||[]).map(es => essaiCardHTML(sc, es, interactive)).join(\"\");\n  const addEssaiBtn = interactive ? `<button class=\"primary essai-add\" data-id=\"${sc.id}\">+ Ajouter un essai</button>` : \"\";\n\n  const logSection = `\n    <div class=\"log-section\">\n      <h3>Essais \u2014 relev\u00e9s de contr\u00f4le (un essai = plusieurs pr\u00e9l\u00e8vements sur la charni\u00e8re vis\u00e9e)</h3>\n      <div class=\"log-meta\">${emagRow}${limitRow}${csupRows}${csupAddRow}${thresholdRow}<div class=\"limit-row-print spec-usine\">Spec usine (OP40, disque fini) : Battement \u2264 ${fmt(specsUsine.battement,3)} \u00b7 VE \u2264 ${fmt(specsUsine.ve,3)}</div></div>\n      <div class=\"essais-list\">\n        ${essaisHtml || `<div class=\"log-empty\" style=\"padding:16px;\">Aucun essai enregistr\u00e9</div>`}\n      </div>\n      ${addEssaiBtn}\n      <div class=\"log-summary\">\n        <span class=\"status-badge ${stats.validated ? \"ok\" : \"pending\"}\">${stats.validated ? \"\u2713 Sc\u00e9nario valid\u00e9\" : `En cours de validation \u2014 ${stats.validCount}/${sc.validationThreshold || \"\u2014\"} essais conformes`}</span>\n        <span><b>${stats.essaisCount}</b> essai${stats.essaisCount>1?\"s\":\"\"} enregistr\u00e9${stats.essaisCount>1?\"s\":\"\"}</span>\n        <span><b>${stats.badCount}</b> non conforme${stats.badCount>1?\"s\":\"\"}</span>\n        ${stats.arreteCount ? `<span><b>${stats.arreteCount}</b> arr\u00eat\u00e9${stats.arreteCount>1?\"s\":\"\"} avant charni\u00e8re</span>` : \"\"}\n        <span><b>${stats.rate === null ? \"\u2014\" : fmt(stats.rate,0)+\" %\"}</b> de pr\u00e9l\u00e8vements hors tol\u00e9rance (tous essais)</span>\n      </div>\n    </div>\n  `;\n\n  const scrap = scrapStats(sc);\n  const scrapRows = (sc.scrapLog||[]).map(row => scrapRowHTML(sc, row, interactive)).join(\"\");\n  const scrapAddBtn = interactive ? `<button class=\"ghost scrap-add\" data-id=\"${sc.id}\">+ Ajouter un suivi \u00e9quipe</button>` : \"\";\n  const scrapEmptyColspan = interactive ? 6 : 5;\n\n  /* v4.20 \u2014 taux de rebut annuel : le chiffre de l'ann\u00e9e, saisi en t\u00eate du suivi rebut.\n     Il fait foi sur le taux calcul\u00e9 du journal (voir tauxRebutDe) et p\u00e8se dans le gain\n     annuel d\u00e8s que le module Co\u00fbt de rebut est actif avec un prix de disque. */\n  const trAnnuel = tauxRebutDe(sc);\n  const moduleRebutOK = config.coutRebutActif && !isNaN(parseFloat(config.coutDisque));\n  const rebutAnnuelNote = !interactive ? \"\" : `<span class=\"rebut-source ${trAnnuel && trAnnuel.source === \"saisi\" ? \"ok\" : \"\"}\">${\n    trAnnuel && trAnnuel.source === \"saisi\"\n      ? \"fait foi \u2014 retenu pour le bilan\" +\n        (moduleRebutOK ? \"\" : \" \u00b7 pour qu'il p\u00e8se : activer \u00ab Co\u00fbt de rebut \u00bb et le prix du disque dans Options\")\n      : trAnnuel\n        ? \"non saisi \u2014 le taux calcul\u00e9 du journal (\" + fmt(trAnnuel.taux,1) + \" %) est retenu\"\n        : \"non saisi \u2014 le taux du journal s'appliquera d\u00e8s qu'une ligne existe\"\n  }</span>`;\n\n  const scrapSection = `\n    <div class=\"log-section\">\n      <h3>Suivi rebut \u2014 production \u00e9quipe (taux de rebut battement, toutes pi\u00e8ces)</h3>\n      ${interactive ? `<div class=\"rebut-annuel-row\">\n        <label>Taux de rebut annuel (%)\n          <input class=\"cell\" data-id=\"${sc.id}\" data-field=\"tauxRebutAnnuel\" value=\"${escapeAttr(sc.tauxRebutAnnuel ?? \"\")}\" placeholder=\"ex. 2,5\" style=\"max-width:90px;\" title=\"Le chiffre annuel (Stellantis) pour ce sc\u00e9nario. Rempli, il fait foi sur le taux calcul\u00e9 du journal et p\u00e8se dans le gain annuel via le module Co\u00fbt de rebut.\">\n        </label>\n        ${rebutAnnuelNote}\n      </div>` : \"\"}\n      <div class=\"tbl-wrap\">\n        <table>\n          <thead>\n            <tr>\n              <th>Date</th><th>\u00c9quipe</th><th class=\"num\">Pi\u00e8ces produites</th><th class=\"num\">Pi\u00e8ces rebut\u00e9es (battement)</th><th class=\"num\">% rebut</th>${interactive?\"<th></th>\":\"\"}\n            </tr>\n          </thead>\n          <tbody>${scrapRows || `<tr><td colspan=\"${scrapEmptyColspan}\" class=\"log-empty\">Aucun suivi enregistr\u00e9</td></tr>`}</tbody>\n        </table>\n      </div>\n      ${scrapAddBtn}\n      <div class=\"log-summary\">\n        <span><b>${scrap.totalProd}</b> pi\u00e8ces produites (cumul)</span>\n        <span><b>${scrap.totalRebut}</b> rebut\u00e9es</span>\n        <span>Taux de rebut ligne : <b>${scrap.rate === null ? \"\u2014\" : fmt(scrap.rate,1)+\" %\"}</b></span>\n      </div>\n    </div>\n  `;\n\n  // Ordre de lecture : le verdict (la reponse), les chiffres cles, puis la composition du\n  // scenario \u2014 outils, logements, plaquettes, pieces detachees, conditions de coupe \u2014 avant\n  // la preuve (graphique) et le travail quotidien (essais). Le tableau est deplie par\n  // defaut : c'est la fiche d'identite du scenario. Il reste repliable une fois la campagne\n  // lancee et la configuration figee, et ce choix survit aux re-rendus (voir configReplies).\n  const replie = configReplies.has(sc.id);\n  const nbOutilsSc = sc.outils.length;\n  const configSection = interactive ? `\n    ${compositionApercuHTML(sc)}\n    <details class=\"config-block\"${replie ? \"\" : \" open\"} data-config-id=\"${sc.id}\">\n      <summary>Modifier la composition<span class=\"config-resume\">outils, plaquettes, conditions de coupe${nbOutilsSc ? \" \u2014 \" + nbOutilsSc + \" fiche\" + (nbOutilsSc>1?\"s\":\"\") : \"\"}</span></summary>\n      <div class=\"config-body\">${volumeAnnuelHTML()}${kvfWidgetHTML(sc, kAutorise())}${posTable}</div>\n    </details>\n  ` : `${compositionApercuHTML(sc)}${volumeAnnuelHTML()}${kvfWidgetHTML(sc, false)}${posTable}`;\n\n  return `\n    <div class=\"scenario ${sc.baseline ? \"baseline\" : \"\"}\">\n      <div class=\"scenario-head\">${head}<span class=\"status-badge ${stats.validated ? \"ok\" : \"pending\"}\">${stats.validated ? \"\u2713 Valid\u00e9\" : \"En cours\"}</span></div>\n      ${foot}\n      <div class=\"sec-plaquettes\">${configSection}</div>\n      <div class=\"sec-graph\">${interactive ? `<details class=\"zone-det\"><summary>Tendance \u2014 \u00e9volution au fil des pi\u00e8ces</summary>` : \"\"}${chartHTML(sc)}${interactive ? `</details>` : \"\"}</div>\n      <div class=\"sec-essais\">${logSection}</div>\n      <div class=\"sec-rebut\">${scrapSection}</div>\n    </div>\n  `;\n}\n\nfunction scrapRowHTML(sc, row, interactive){\n  const p = parseFloat(row.produites), rb = parseFloat(row.rebutees);\n  const rate = (!isNaN(p) && p > 0 && !isNaN(rb)) ? (rb/p)*100 : null;\n  const rateHtml = rate === null ? \"\u2014\" : fmt(rate,2)+\" %\";\n  if(interactive){\n    const equipeOpts = [\"\", \"Matin\", \"Apr\u00e8s-midi\", \"Nuit\"].map(o =>\n      `<option value=\"${o}\" ${row.equipe === o ? \"selected\" : \"\"}>${o || \"\u2014\"}</option>`).join(\"\");\n    return `\n      <tr>\n        <td><input class=\"cell\" data-id=\"${sc.id}\" data-scrap=\"${row.id}\" data-field=\"date\" type=\"date\" value=\"${row.date ?? \"\"}\"></td>\n        <td><select class=\"cell log-equipe\" data-id=\"${sc.id}\" data-scrap=\"${row.id}\" data-field=\"equipe\">${equipeOpts}</select></td>\n        <td class=\"num\"><input class=\"cell\" data-id=\"${sc.id}\" data-scrap=\"${row.id}\" data-field=\"produites\" type=\"number\" step=\"1\" value=\"${row.produites ?? \"\"}\"></td>\n        <td class=\"num\"><input class=\"cell\" data-id=\"${sc.id}\" data-scrap=\"${row.id}\" data-field=\"rebutees\" type=\"number\" step=\"1\" value=\"${row.rebutees ?? \"\"}\"></td>\n        <td class=\"num computed\">${rateHtml}</td>\n        <td><button class=\"log-del scrap-del\" data-id=\"${sc.id}\" data-scrap=\"${row.id}\">\u2715</button></td>\n      </tr>\n    `;\n  }\n  return `\n    <tr>\n      <td>${row.date || \"\u2014\"}</td>\n      <td>${row.equipe || \"\u2014\"}</td>\n      <td class=\"num\">${row.produites === \"\" || row.produites == null ? \"\u2014\" : row.produites}</td>\n      <td class=\"num\">${row.rebutees === \"\" || row.rebutees == null ? \"\u2014\" : row.rebutees}</td>\n      <td class=\"num computed\">${rateHtml}</td>\n    </tr>\n  `;\n}\n\n/* ---- suivi Marposs : replacer un essai dans le contexte de la production du jour ---- */\nfunction heureToMinutes(h){\n  const m = String(h||\"\").match(/(\\d{1,2}):(\\d{2})/);\n  if(!m) return null;\n  return parseInt(m[1],10)*60 + parseInt(m[2],10);\n}\n/* colle Excel (2 colonnes : date/heure, valeur) -> tabulation en priorite, sinon plusieurs\n   espaces ; on ne garde que l'heure (HH:MM) de la 1re colonne et un nombre valide en 2e */\nfunction parseMarpossPaste(text){\n  const lignes = String(text||\"\").split(/\\r?\\n/).map(l => l.trim()).filter(Boolean);\n  const rows = [];\n  let ignorees = 0;\n  lignes.forEach(l => {\n    const cols = l.includes(\"\\t\") ? l.split(\"\\t\") : l.split(/\\s{2,}|;/);\n    if(cols.length < 2){ ignorees++; return; }\n    const heureRaw = cols[0].trim();\n    const valeurRaw = cols[cols.length-1].trim().replace(\",\", \".\");\n    const valeur = parseFloat(valeurRaw);\n    if(isNaN(valeur)){ ignorees++; return; }\n    const hm = heureRaw.match(/(\\d{1,2}):(\\d{2})(:\\d{2})?/);\n    rows.push({ heure: hm ? hm[0] : heureRaw, valeur: String(valeur) });\n  });\n  return { rows, ignorees };\n}\n/* v4.12 \u2014 les stats portent sur UNE extraction (une journ\u00e9e) : {debut, fin, releves} */\nfunction marpossStats(ex){\n  ex = ex || {};\n  const releves = ex.releves || [];\n  const debutMin = heureToMinutes(ex.debut), finMin = heureToMinutes(ex.fin);\n  const dansEssai = (debutMin === null || finMin === null) ? [] : releves.filter(r => {\n    const hm = heureToMinutes(r.heure);\n    return hm !== null && hm >= debutMin && hm <= finMin;\n  });\n  const moyenne = arr => arr.length ? arr.reduce((s,r) => s + (parseFloat(r.valeur)||0), 0) / arr.length : null;\n  return { total: releves.length, moyenneJour: moyenne(releves), moyenneEssai: moyenne(dansEssai), nbEssai: dansEssai.length, debutMin, finMin };\n}\nfunction marpossChartSVG(sc, ex, pal){\n  // palette param\u00e9trable : variables CSS dans l'outil, couleurs en dur dans le rapport\n  // autonome (qui n'a pas les variables de l'outil)\n  pal = Object.assign({ blue:\"var(--blue)\", red:\"var(--red)\", teal:\"var(--teal-strong)\", faint:\"var(--ink-faint)\" }, pal || {});\n  const m = ex || { debut:\"\", fin:\"\", releves:[] };\n  const releves = (m.releves||[]).map(r => ({ x: heureToMinutes(r.heure), y: parseFloat(r.valeur) }))\n    .filter(p => p.x !== null && !isNaN(p.y));\n  if(!releves.length) return \"\";\n  const limite = parseFloat(limiteDe(sc));\n  const stats = marpossStats(ex);\n  const allX = releves.map(p=>p.x), allY = releves.map(p=>p.y);\n  let xMin = Math.min(...allX), xMax = Math.max(...allX);\n  if(xMax === xMin) xMax = xMin + 1;\n  const yMax = Math.max(...allY, isNaN(limite)?0:limite) * 1.15 || 1;\n\n  const W = 720, H = 200, ml = 50, mr = 14, mt = 10, mb = 26;\n  const iw = W - ml - mr, ih = H - mt - mb;\n  const X = v => ml + ((v - xMin) / (xMax - xMin)) * iw;\n  const Y = v => mt + ih - (v / yMax) * ih;\n  const dec = yMax < 1 ? 3 : yMax < 10 ? 2 : 0;\n\n  let zone = \"\";\n  if(stats.debutMin !== null && stats.finMin !== null){\n    const x1 = X(Math.max(xMin, Math.min(stats.debutMin, stats.finMin)));\n    const x2 = X(Math.min(xMax, Math.max(stats.debutMin, stats.finMin)));\n    if(x2 > x1) zone = `<rect x=\"${x1.toFixed(1)}\" y=\"${mt}\" width=\"${(x2-x1).toFixed(1)}\" height=\"${ih}\" fill=\"${pal.blue}\" opacity=\"0.12\"/>`;\n  }\n  let tolLine = \"\";\n  if(!isNaN(limite) && limite <= yMax){\n    const yl = Y(limite);\n    tolLine = `<line x1=\"${ml}\" y1=\"${yl.toFixed(1)}\" x2=\"${W-mr}\" y2=\"${yl.toFixed(1)}\" stroke=\"${pal.red}\" stroke-width=\"1.5\" stroke-dasharray=\"6 4\"/>`;\n  }\n  let ticksX = \"\";\n  for(let i=0;i<=4;i++){\n    const v = xMin + ((xMax-xMin)/4)*i;\n    const hh = Math.floor(v/60), mm = Math.round(v%60);\n    ticksX += `<text x=\"${X(v).toFixed(1)}\" y=\"${H-mb+16}\" text-anchor=\"middle\" font-size=\"10\" fill=\"${pal.faint}\" font-family=\"Consolas,monospace\">${String(hh).padStart(2,\"0\")}:${String(mm).padStart(2,\"0\")}</text>`;\n  }\n  const dots = releves.map(p => {\n    const hors = !isNaN(limite) && p.y > limite;\n    return `<circle cx=\"${X(p.x).toFixed(1)}\" cy=\"${Y(p.y).toFixed(1)}\" r=\"2.2\" fill=\"${hors ? pal.red : pal.teal}\" opacity=\"0.75\"/>`;\n  }).join(\"\");\n\n  return `\n    <svg class=\"chart-svg\" viewBox=\"0 0 ${W} ${H}\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\" aria-label=\"Battement mesur\u00e9 par la Marposs au fil de la journ\u00e9e\">\n      <line x1=\"${ml}\" y1=\"${mt}\" x2=\"${ml}\" y2=\"${mt+ih}\" stroke=\"${pal.faint}\" stroke-width=\"1\"/>\n      <line x1=\"${ml}\" y1=\"${mt+ih}\" x2=\"${W-mr}\" y2=\"${mt+ih}\" stroke=\"${pal.faint}\" stroke-width=\"1\"/>\n      ${zone}${tolLine}${dots}${ticksX}\n    </svg>\n  `;\n}\nfunction marpossBlocExHTML(sc, essai, ex, i){\n  const stats = marpossStats(ex);\n  const chart = marpossChartSVG(sc, ex);\n  const titre = \"Extraction \" + (i+1) + (ex.jour ? \" \u2014 \" + escapeAttr(ex.jour) : \"\");\n  const rows = (ex.releves||[]).slice(0, 1000).map((r, k) => {\n    const conf = isNaN(parseFloat(limiteDe(sc))) ? null : parseFloat(r.valeur) <= parseFloat(limiteDe(sc));\n    return `<tr><td>${escapeAttr(r.heure)}</td><td class=\"num\">${k+1}</td><td class=\"num\">${fmtBatt(r.valeur)}</td>\n      <td>${conf === null ? \"\u2014\" : conf ? '<span class=\"badge ok\">OUI</span>' : '<span class=\"badge risk\">NON</span>'}</td></tr>`;\n  }).join(\"\");\n  const tropLong = (ex.releves||[]).length > 1000 ? `<p class=\"panel-hint\">Affichage limit\u00e9 aux 1000 premi\u00e8res lignes (${ex.releves.length} au total) \u2014 les statistiques et le graphique portent bien sur l'ensemble.</p>` : \"\";\n  return `\n    <div class=\"marposs-ex\" style=\"border-top:2px solid var(--border); margin-top:14px; padding-top:10px;\">\n      <div class=\"marposs-window\">\n        <b style=\"color:var(--teal);\">${titre}</b>\n        <label>Jour <input type=\"date\" class=\"cell\" data-marposs-ex=\"${ex.id}\" data-marposs-field=\"jour\" value=\"${escapeAttr(ex.jour || \"\")}\" title=\"Jour de cette extraction (un essai peut s'\u00e9tendre sur plusieurs jours)\"></label>\n        <label>D\u00e9but <input type=\"time\" class=\"cell\" data-marposs-ex=\"${ex.id}\" data-marposs-field=\"debut\" value=\"${escapeAttr(ex.debut)}\"></label>\n        <label>Fin <input type=\"time\" class=\"cell\" data-marposs-ex=\"${ex.id}\" data-marposs-field=\"fin\" value=\"${escapeAttr(ex.fin)}\"></label>\n        ${(i > 0 || essai.marpossListe.length > 1) ? `<button class=\"ghost danger marposs-ex-del\" data-essai=\"${essai.id}\" data-marposs-ex=\"${ex.id}\" title=\"Supprimer cette extraction\">\u2715</button>` : \"\"}\n      </div>\n      <div class=\"marposs-paste-row\">\n        <textarea class=\"marposs-paste\" data-marposs-ex=\"${ex.id}\" rows=\"3\" placeholder=\"Collez ici les 2 colonnes copi\u00e9es depuis l'extraction Marposs de ce jour : heure, puis valeur (une pi\u00e8ce par ligne).\"></textarea>\n        <div class=\"marposs-paste-actions\">\n          <button class=\"save marposs-import\" data-marposs-ex=\"${ex.id}\">Importer le collage</button>\n          ${ex.releves.length ? `<button class=\"ghost danger marposs-clear\" data-marposs-ex=\"${ex.id}\">Vider (${ex.releves.length})</button>` : \"\"}\n        </div>\n      </div>\n      ${ex.releves.length ? `\n        <div class=\"marposs-kpis\">\n          <div><span class=\"l\">Moyenne journ\u00e9e</span><span class=\"v\">${stats.moyenneJour===null?\"\u2014\":fmt(stats.moyenneJour,3)}</span></div>\n          <div><span class=\"l\">Moyenne essai</span><span class=\"v\">${stats.moyenneEssai===null?\"\u2014\":fmt(stats.moyenneEssai,3)}</span><span class=\"foot-sub\" style=\"display:block;\">${stats.nbEssai} pi\u00e8ce(s) entre d\u00e9but et fin</span></div>\n          <div><span class=\"l\">Total journ\u00e9e</span><span class=\"v\">${stats.total}</span></div>\n        </div>\n        <div class=\"chart-block\" style=\"padding:10px 0;border-top:none;\">${chart}</div>\n        <div class=\"tbl-wrap\" style=\"max-height:320px; overflow-y:auto;\">\n          <table><thead><tr><th>Heure</th><th class=\"num\">N\u00b0 disque</th><th class=\"num\">Battement</th><th>Conf.</th></tr></thead>\n          <tbody>${rows}</tbody></table>\n        </div>\n        ${tropLong}\n      ` : `<p class=\"panel-hint\">Collez l'extraction de ce jour pour voir appara\u00eetre le tableau, les moyennes et le graphique.</p>`}\n    </div>`;\n}\nfunction marpossHTML(sc, essai){\n  if(!Array.isArray(essai.marpossListe) || !essai.marpossListe.length){\n    essai.marpossListe = [{ id:\"mj1\", jour:\"\", debut:\"\", fin:\"\", releves:[] }];\n  }\n  const nbReleves = essai.marpossListe.reduce((n, ex) => n + (ex.releves||[]).length, 0);\n  const plusieursJours = essai.marpossListe.length > 1;\n  const blocs = essai.marpossListe.map((ex, i) => marpossBlocExHTML(sc, essai, ex, i)).join(\"\");\n  return `\n    <details class=\"marposs-block\" ${nbReleves ? \"open\" : \"\"}>\n      <summary><svg class=\"icon\" viewBox=\"0 0 18 18\"><path d=\"M2.5 13.5 7 8l3 3 5.5-7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>Suivi Marposs ${plusieursJours ? `\u2014 ${essai.marpossListe.length} journ\u00e9es` : \"\"} ${nbReleves ? `<span class=\"badge muted\">${nbReleves} relev\u00e9(s)</span>` : \"\"}</summary>\n      <div class=\"marposs-body\">\n        <div style=\"margin-bottom:10px;\">\n          <label><input type=\"checkbox\" data-marposs-rapport=\"${essai.id}\" ${essai.marpossRapport ? \"checked\" : \"\"}> Inclure les graphes Marposs dans le rapport de l'essai</label>\n          <span class=\"panel-hint\" style=\"margin:0;\">Un essai sur plusieurs jours = une extraction par jour : \u00ab + Ajouter une extraction \u00bb cr\u00e9e la journ\u00e9e suivante, avec ses heures et son propre graphe.</span>\n        </div>\n        ${blocs}\n        <button class=\"ghost marposs-add-ex\" data-essai=\"${essai.id}\" style=\"margin-top:10px;\">+ Ajouter une extraction (autre journ\u00e9e\u2026)</button>\n      </div>\n    </details>\n  `;\n}\n\n/* ---- photos par essai : fichiers reels dans le dossier local connecte, jamais dans le\n   JSON echange (seule une reference legere y voyage) ---- */\n/* ---- v4.24 \u2014 les photos de l'essai voyagent dans le rapport ---------------------------\n   Le rapport d'essai est un fichier autonome envoy\u00e9 \u00e0 des gens qui n'ont NI l'outil NI le\n   dossier photos : sans elles, un constat photographi\u00e9 perdait sa preuve. Chaque photo est\n   APLATIE (rognage et annotations appliqu\u00e9s, exactement comme \u00e0 l'\u00e9cran) en JPEG embarqu\u00e9\n   en data URL \u2014 le rapport reste un seul fichier, lisible partout, sans appel r\u00e9seau. Une\n   photo indisponible au moment de la g\u00e9n\u00e9ration (dossier d\u00e9connect\u00e9, cloud hors ligne) ne\n   casse rien : une case nomm\u00e9e avec la raison la remplace dans le rapport. */\nconst RAPPORT_PHOTO_MAXW = 1200;\nfunction dimensionsAplaties(largSrc, hautSrc, crop, maxW){\n  const c = (crop && (crop.w < 0.999 || crop.h < 0.999)) ? crop : null;\n  const sw = c ? Math.max(1, Math.round(largSrc * c.w)) : largSrc;\n  const sh = c ? Math.max(1, Math.round(hautSrc * c.h)) : hautSrc;\n  const scale = Math.min(maxW / sw, 1);\n  return { w: Math.max(1, Math.round(sw * scale)), h: Math.max(1, Math.round(sh * scale)), crop: c };\n}\nfunction aplatirPhoto(img, p){\n  const { w: W, h: H, crop } = dimensionsAplaties(img.naturalWidth, img.naturalHeight, p.crop, RAPPORT_PHOTO_MAXW);\n  const canvas = document.createElement(\"canvas\");\n  canvas.width = W; canvas.height = H;\n  const ctx = canvas.getContext(\"2d\");\n  ctx.fillStyle = \"#ffffff\"; ctx.fillRect(0, 0, W, H);\n  if(crop){\n    ctx.drawImage(img, crop.x * img.naturalWidth, crop.y * img.naturalHeight,\n      crop.w * img.naturalWidth, crop.h * img.naturalHeight, 0, 0, W, H);\n  } else {\n    ctx.drawImage(img, 0, 0, W, H);\n  }\n  if(p.annotations && p.annotations.length){\n    drawAnnotShapes(ctx, p.annotations, W, H, -1, crop || defaultCrop());\n  }\n  return canvas.toDataURL(\"image/jpeg\", 0.85);\n}\nfunction blobEnDataUrl(blob){\n  return new Promise((resolve, reject) => {\n    const r = new FileReader();\n    r.onload = () => resolve(r.result);\n    r.onerror = () => reject(new Error(\"lecture impossible\"));\n    r.readAsDataURL(blob);\n  });\n}\nfunction chargerImageDepuisUrl(url){\n  return new Promise((resolve, reject) => {\n    const img = new Image();\n    img.onload = () => resolve(img);\n    img.onerror = () => reject(new Error(\"d\u00e9codage impossible\"));\n    img.src = url;\n  });\n}\n/* Pr\u00e9paration de TOUTES les photos d'un essai pour le rapport. photoObjectURL g\u00e8re les\n   deux stockages (dossier local, cloud + cache IndexedDB) ; un \u00e9chec nominatif ne bloque\n   pas les autres photos. Renvoie [{legende, dataUrl}] ou [{legende, erreur}]. */\nasync function photosPourRapport(essai){\n  const photos = (essai && essai.photos) || [];\n  const sorties = [];\n  for(const p of photos){\n    try{\n      const url = await photoObjectURL(p);\n      if(!url) throw new Error(p.stockage === \"cloud\" ? \"photo cloud indisponible (hors ligne ?)\" : \"dossier photos local non connect\u00e9\");\n      const blob = await (await fetch(url)).blob();\n      const dataUrl = await blobEnDataUrl(blob);\n      const img = await chargerImageDepuisUrl(dataUrl);\n      sorties.push({ legende: p.legende || \"\", dataUrl: aplatirPhoto(img, p) });\n      if(url.startsWith(\"blob:\")) URL.revokeObjectURL(url);\n    }catch(e){\n      sorties.push({ legende: p.legende || \"\", erreur: (e && e.message) || \"indisponible\" });\n    }\n  }\n  return sorties;\n}\nfunction photosRapportHTML(photos){\n  if(!photos || !photos.length) return \"\";\n  const items = photos.map(ph => ph.dataUrl\n    ? `<figure class=\"ph\"><img src=\"${ph.dataUrl}\" alt=\"${escapeAttr(ph.legende || \"Photo de l'essai\")}\">${ph.legende ? `<figcaption>${escapeAttr(ph.legende)}</figcaption>` : \"\"}</figure>`\n    : `<figure class=\"ph\"><div class=\"ph-absente\">Photo non incorpor\u00e9e \u2014 ${escapeAttr(ph.erreur)}</div>${ph.legende ? `<figcaption>${escapeAttr(ph.legende)}</figcaption>` : \"\"}</figure>`\n  ).join(\"\");\n  const toutesAbsentes = photos.every(ph => !ph.dataUrl);\n  return `<h2>Photos \u2014 constats, m\u00e9trologie, usures</h2>\n  <div class=\"photos-rap\">${items}</div>\n  <p style=\"font-family:'IBM Plex Mono',Consolas,monospace; font-size:10.5px; color:var(--ink-faint); margin-top:6px;\">${\n    toutesAbsentes\n      ? \"Aucune photo n'a pu \u00eatre incorpor\u00e9e \u00e0 la g\u00e9n\u00e9ration du rapport \u2014 rouvrez l'outil avec le dossier photos connect\u00e9 (ou en ligne pour le cloud) et reg\u00e9n\u00e9rez.\"\n      : \"Photos de l'onglet Photos de l'essai, telles qu'annot\u00e9es dans l'outil (rognage et rep\u00e8res appliqu\u00e9s).\"\n  }</p>`;\n}\n\nfunction photosHTML(sc, essai){\n  if(!essai.photos) essai.photos = [];\n  const photos = essai.photos;\n  const thumbs = photos.map(p => {\n    const hasAnnot = (p.annotations && p.annotations.length) || (p.crop && (p.crop.w < 0.999 || p.crop.h < 0.999));\n    const enCloud = p.stockage === \"cloud\";\n    return `\n    <div class=\"photo-thumb-wrap\">\n      <div class=\"photo-thumb\">\n        <img data-photo-filename=\"${escapeAttr(p.filename)}\" data-photo-stockage=\"${enCloud ? \"cloud\" : \"dossier\"}\"\n             alt=\"${escapeAttr(p.filename)}\"${enCloud ? ' title=\"Photo cloud \u2014 partag\u00e9e avec l\u2019autre poste\"' : \"\"}>\n        ${hasAnnot ? `<span class=\"photo-annot-badge\" title=\"Photo annot\u00e9e\">\u270e</span>` : \"\"}\n        <button class=\"photo-annot\" data-essai=\"${essai.id}\" data-photo=\"${p.id}\" title=\"Annoter (rogner, fl\u00e8ches, texte...)\">\u270e</button>\n        <button class=\"photo-del\" data-essai=\"${essai.id}\" data-photo=\"${p.id}\" title=\"Supprimer\">\u2715</button>\n      </div>\n      <input class=\"photo-legende\" data-essai=\"${essai.id}\" data-photo=\"${p.id}\" value=\"${escapeAttr(p.legende || \"\")}\" placeholder=\"L\u00e9gende (ex. usure de l'ar\u00eate apr\u00e8s 4212 pi\u00e8ces)\">\n    </div>\n  `;\n  }).join(\"\");\n  // v4.16 : trois fa\u00e7ons d'ajouter une photo, par priorit\u00e9 \u2014 dossier local (z\u00e9ro r\u00e9seau),\n  // cloud priv\u00e9 (partag\u00e9 avec l'autre poste), sinon l'invitation \u00e0 se brancher.\n  const attributEssai = `data-essai=\"${essai.id}\"`;\n  const uploadZone = photosDirHandle\n    ? `<label class=\"backlog-image-add\">\uff0b Ajouter des photos<input type=\"file\" accept=\"image/*\" multiple class=\"photo-input\" ${attributEssai} hidden></label>`\n    : cloudSession\n      ? `<label class=\"backlog-image-add\" title=\"Sans dossier local connect\u00e9, les photos partent dans le cloud priv\u00e9 (comptes de l'\u00e9quipe) et se partagent automatiquement avec l'autre poste.\">\uff0b Ajouter des photos (cloud)<input type=\"file\" accept=\"image/*\" multiple class=\"photo-input\" ${attributEssai} hidden></label>`\n      : (fsPhotosSupported()\n        ? `<button class=\"ghost photos-connect-btn\">\ud83d\udcc1 Connecter le dossier photos</button>\n           <p class=\"panel-hint\">Ou connectez-vous au cloud (Options \u2192 Cloud) : les photos y seront partag\u00e9es avec l'autre poste.</p>`\n        : `<p class=\"panel-hint\">Fonction disponible sur Edge/Chrome (ordinateur), via l'adresse en ligne de l'outil.</p>`);\n  return `\n    <details class=\"photos-block\" ${photos.length ? \"open\" : \"\"}>\n      <summary><svg class=\"icon\" viewBox=\"0 0 18 18\"><path d=\"M3 6.5a1 1 0 0 1 1-1h1.3l.8-1.3h3.8l.8 1.3H14a1 1 0 0 1 1 1V13a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V6.5Z\" stroke-linejoin=\"round\"/><circle cx=\"9\" cy=\"9.5\" r=\"2.3\"/></svg>Photos ${photos.length ? `<span class=\"badge muted\">${photos.length}</span>` : \"\"}</summary>\n      <div class=\"photos-body\">\n        ${uploadZone}\n        ${thumbs ? `<div class=\"photos-grid\">${thumbs}</div>` : \"\"}\n      </div>\n    </details>\n  `;\n}\nasync function loadPhotoThumbnails(){\n  // v4.16 : deux modes coexistent photo par photo \u2014 dossier local (readPhotoURL) et\n  // cloud (t\u00e9l\u00e9chargement \u00e0 la demande + cache IndexedDB). Une photo cloud sans\n  // connexion ne casse rien : elle s'affiche estomp\u00e9e, avec la raison en info-bulle.\n  const imgs = [...document.querySelectorAll(\"img[data-photo-filename]\")]\n    .filter(img => !img.src); // ne recharger que les vignettes pas encore r\u00e9solues\n  for(const img of imgs){\n    const filename = img.getAttribute(\"data-photo-filename\");\n    if(!filename) continue;\n    const url = await photoObjectURL({ filename, stockage: img.getAttribute(\"data-photo-stockage\") });\n    if(url){\n      // revoque des que l'image est decodee : le bitmap decode reste affichable, seul\n      // l'objet Blob sous-jacent est libere (sinon fuite memoire a l'usage prolonge)\n      img.addEventListener(\"load\", () => URL.revokeObjectURL(url), { once:true });\n      img.src = url;\n    } else {\n      img.classList.add(\"photo-missing\");\n      if(img.getAttribute(\"data-photo-stockage\") === \"cloud\")\n        img.title = \"Photo cloud indisponible \u2014 \" + cloudPhotoErreurDerniere;\n    }\n  }\n}\n\n/* ---- annotation de photo : rognage + fleches/formes/texte, non destructif --------------\n   Rien n'est jamais ecrit dans le fichier image d'origine (coherent avec \"jamais dans le\n   JSON... sauf reference legere\" plus haut) : le rognage et les formes sont de simples\n   nombres (fractions 0-1 de l'image ORIGINALE) stockes sur l'objet photo, et recomposes a\n   la volee sur un <canvas> a l'affichage (miniature laissee brute, lightbox et rapport\n   recoivent le rendu compose). Ca reste editable indefiniment, sans jamais degrader l'image\n   source ni gonfler le JSON de pixels. */\nconst ANNOT_COLORS = [\"#e2001a\",\"#f59e0b\",\"#facc15\",\"#22c55e\",\"#1b5ea6\",\"#ffffff\",\"#111111\"];\nconst ANNOT_MAXW = 780, ANNOT_MAXH = 480;\nlet annot = null; // etat de l'editeur ouvert, ou null si ferme\n\nfunction defaultCrop(){ return { x:0, y:0, w:1, h:1 }; }\nfunction annotCanvasSize(w, h){\n  const scale = Math.min(ANNOT_MAXW / w, ANNOT_MAXH / h, 1);\n  return { w: Math.max(1, Math.round(w*scale)), h: Math.max(1, Math.round(h*scale)) };\n}\nfunction photoOfAnnot(){\n  if(!annot) return null;\n  const es = annot.sc.essais.find(e => e.id === annot.essaiId);\n  return es && (es.photos||[]).find(x => x.id === annot.photoId);\n}\nasync function openPhotoAnnotator(essaiId, photoId){\n  const sc = data.find(s => s.essais && s.essais.some(e => e.id === essaiId));\n  const es = sc && sc.essais.find(e => e.id === essaiId);\n  const p = es && (es.photos||[]).find(x => x.id === photoId);\n  if(!p) return;\n  // v4.16 : dossier local OU cloud \u2014 photoObjectURL g\u00e8re les deux modes\n  const url = await photoObjectURL(p);\n  if(!url){\n    dialogueAlerte(p.stockage === \"cloud\"\n      ? \"Photo cloud indisponible \u2014 \" + (cloudPhotoErreurDerniere || \"v\u00e9rifiez la connexion.\")\n      : \"Connectez d'abord le dossier photos (bouton dans le bloc Photos).\", \"Photo indisponible\");\n    return;\n  }\n  const img = new Image();\n  img.onload = () => {\n    URL.revokeObjectURL(url); // l'image est decodee, le Blob source n'est plus necessaire\n    annot = {\n      sc, essaiId, photoId, img,\n      crop: p.crop ? Object.assign({}, p.crop) : defaultCrop(),\n      shapes: (p.annotations || []).map(s => Object.assign({}, s)),\n      tool: \"move\", color: ANNOT_COLORS[0], selected: -1, draft: null, cropDraft: null,\n      legendeDraft: p.legende || \"\"\n    };\n    // empreinte de l'etat charge : sert a savoir, a la fermeture, s'il y a vraiment\n    // quelque chose de non enregistre a perdre (ouvrir une photo deja annotee ne doit\n    // pas a lui seul declencher une confirmation)\n    annot.snapshot = JSON.stringify({ crop: annot.crop, shapes: annot.shapes, legende: annot.legendeDraft });\n    renderAnnotEditor();\n    ouvrirPanneau(\"photoAnnotWrap\");\n  };\n  img.onerror = () => { URL.revokeObjectURL(url); dialogueAlerte(\"Impossible de charger l'image.\", \"Photo illisible\"); };\n  img.src = url;\n}\nfunction annotToolButtons(){\n  const tools = [\n    [\"move\",\"\u2725\",\"S\u00e9lection / d\u00e9placer\"], [\"crop\",\"\u26f6\",\"Rogner\"],\n    [\"arrow\",\"\u2197\",\"Fl\u00e8che droite\"], [\"curve\",\"\u3030\",\"Fl\u00e8che courbe\"],\n    [\"rect\",\"\u25ad\",\"Rectangle\"], [\"ellipse\",\"\u25ef\",\"Ellipse\"], [\"text\",\"T\",\"Texte\"]\n  ];\n  return tools.map(([id,icon,label]) => `<button type=\"button\" class=\"annot-tool${annot.tool===id?\" active\":\"\"}\" data-tool=\"${id}\" title=\"${label}\">${icon}</button>`).join(\"\");\n}\nfunction annotColorButtons(){\n  return ANNOT_COLORS.map(c => `<button type=\"button\" class=\"annot-swatch${c===annot.color?\" active\":\"\"}\" data-color=\"${c}\" style=\"background:${c};\" title=\"${c}\"></button>`).join(\"\")\n    + `<input type=\"color\" class=\"annot-color-custom\" id=\"annotColorCustom\" value=\"${/^#[0-9a-f]{6}$/i.test(annot.color)?annot.color:\"#000000\"}\" title=\"Couleur personnalis\u00e9e\">`;\n}\nconst ANNOT_HINTS = {\n  crop: \"Faites glisser pour d\u00e9finir la zone \u00e0 conserver, puis validez.\",\n  move: \"Cliquez une forme pour la s\u00e9lectionner (\ud83d\uddd1 ou Suppr pour l'effacer), glissez pour la d\u00e9placer. Une fl\u00e8che courbe s\u00e9lectionn\u00e9e affiche une poign\u00e9e bleue \u00e0 glisser.\",\n  arrow: \"Cliquez-glissez pour tracer une fl\u00e8che droite.\",\n  curve: \"Cliquez-glissez pour tracer une fl\u00e8che courbe (ajustable ensuite avec la poign\u00e9e).\",\n  rect: \"Cliquez-glissez pour dessiner un rectangle de s\u00e9lection.\",\n  ellipse: \"Cliquez-glissez pour dessiner un cercle/ovale de s\u00e9lection.\",\n  text: \"Cliquez sur l'image pour placer du texte.\"\n};\nfunction renderAnnotEditor(){\n  const wrap = document.getElementById(\"photoAnnotWrap\");\n  if(!wrap || !annot) return;\n  wrap.innerHTML = `\n    <h3>Annoter la photo</h3>\n    <p class=\"panel-hint\" style=\"margin:0 0 12px;\">Rognage et dessins ne modifient jamais le fichier d'origine \u2014 ils sont recompos\u00e9s \u00e0 l'affichage.</p>\n    <div class=\"annot-toolbar\">\n      ${annotToolButtons()}\n      <span class=\"annot-sep\"></span>\n      ${annotColorButtons()}\n      <span class=\"annot-sep\"></span>\n      <button type=\"button\" class=\"annot-tool\" id=\"annotUndo\" title=\"Annuler la derni\u00e8re forme\">\u21ba</button>\n      <button type=\"button\" class=\"annot-tool\" id=\"annotDelSel\" title=\"Supprimer la forme s\u00e9lectionn\u00e9e\">\ud83d\uddd1</button>\n      ${annot.tool === \"crop\" ? (() => {\n        const hasDraft = annot.cropDraft && annot.cropDraft.w > 4 && annot.cropDraft.h > 4;\n        return `<span class=\"annot-sep\"></span><button type=\"button\" class=\"annot-tool active\" id=\"annotCropApply\" ${hasDraft ? \"\" : \"disabled\"} title=\"${hasDraft ? \"\" : \"Dessinez d'abord la zone \u00e0 conserver\"}\">\u2713 Valider le rognage</button><button type=\"button\" class=\"annot-tool\" id=\"annotCropReset\">\u21ba R\u00e9initialiser</button>`;\n      })() : \"\"}\n    </div>\n    <div class=\"annot-canvas-wrap\"><canvas id=\"annotCanvas\"></canvas></div>\n    <p class=\"annot-hint\">${ANNOT_HINTS[annot.tool] || \"\"}</p>\n    <input type=\"text\" class=\"annot-legende\" id=\"annotLegende\" value=\"${escapeAttr(annot.legendeDraft)}\" placeholder=\"L\u00e9gende de la photo (ex. usure de l'ar\u00eate apr\u00e8s 4212 pi\u00e8ces)\">\n    <div class=\"panel-actions\">\n      <button class=\"ghost\" id=\"annotCancel\">Annuler</button>\n      <button class=\"primary\" id=\"annotSave\">Enregistrer</button>\n    </div>\n  `;\n  wireAnnotToolbar();\n  setupAnnotCanvas();\n}\nfunction wireAnnotToolbar(){\n  const wrap = document.getElementById(\"photoAnnotWrap\");\n  wrap.querySelectorAll(\".annot-tool[data-tool]\").forEach(btn => {\n    btn.addEventListener(\"click\", () => {\n      annot.tool = btn.getAttribute(\"data-tool\");\n      annot.selected = -1; annot.draft = null; annot.cropDraft = null;\n      renderAnnotEditor();\n    });\n  });\n  wrap.querySelectorAll(\".annot-swatch\").forEach(btn => {\n    btn.addEventListener(\"click\", () => {\n      annot.color = btn.getAttribute(\"data-color\");\n      if(annot.selected >= 0 && annot.shapes[annot.selected]) annot.shapes[annot.selected].color = annot.color;\n      renderAnnotEditor();\n    });\n  });\n  const customColor = document.getElementById(\"annotColorCustom\");\n  if(customColor) customColor.addEventListener(\"input\", () => {\n    annot.color = customColor.value;\n    if(annot.selected >= 0 && annot.shapes[annot.selected]) annot.shapes[annot.selected].color = annot.color;\n    redrawAnnotCanvas();\n  });\n  const undoBtn = document.getElementById(\"annotUndo\");\n  if(undoBtn) undoBtn.addEventListener(\"click\", () => { annot.shapes.pop(); annot.selected = -1; redrawAnnotCanvas(); });\n  const delBtn = document.getElementById(\"annotDelSel\");\n  if(delBtn) delBtn.addEventListener(\"click\", () => {\n    if(annot.selected >= 0){ annot.shapes.splice(annot.selected, 1); annot.selected = -1; redrawAnnotCanvas(); }\n  });\n  const cropApply = document.getElementById(\"annotCropApply\");\n  if(cropApply) cropApply.addEventListener(\"click\", () => {\n    const canvas = document.getElementById(\"annotCanvas\");\n    if(annot.cropDraft && annot.cropDraft.w > 4 && annot.cropDraft.h > 4){\n      annot.crop = { x: annot.cropDraft.x/canvas.width, y: annot.cropDraft.y/canvas.height,\n                      w: annot.cropDraft.w/canvas.width, h: annot.cropDraft.h/canvas.height };\n    }\n    annot.cropDraft = null; annot.tool = \"move\";\n    renderAnnotEditor();\n  });\n  const cropReset = document.getElementById(\"annotCropReset\");\n  if(cropReset) cropReset.addEventListener(\"click\", () => { annot.crop = defaultCrop(); annot.cropDraft = null; redrawAnnotCanvas(); });\n  const legendeInp = document.getElementById(\"annotLegende\");\n  if(legendeInp) legendeInp.addEventListener(\"input\", () => { annot.legendeDraft = legendeInp.value; });\n  document.getElementById(\"annotCancel\").addEventListener(\"click\", () => { annot = null; fermerPanneaux(); });\n  document.getElementById(\"annotSave\").addEventListener(\"click\", saveAnnotEditor);\n}\nfunction annotBaseDims(){\n  if(annot.tool === \"crop\") return { w: annot.img.naturalWidth, h: annot.img.naturalHeight };\n  const c = annot.crop;\n  return { w: Math.max(1, c.w*annot.img.naturalWidth), h: Math.max(1, c.h*annot.img.naturalHeight) };\n}\nfunction setupAnnotCanvas(){\n  const canvas = document.getElementById(\"annotCanvas\");\n  const base = annotBaseDims();\n  const size = annotCanvasSize(base.w, base.h);\n  canvas.width = size.w; canvas.height = size.h;\n  canvas.className = annot.tool === \"move\" ? \"move\" : \"\";\n  canvas.tabIndex = 0; // pour recevoir les evenements clavier (Suppr)\n  redrawAnnotCanvas();\n  bindAnnotPointerEvents(canvas);\n}\nfunction fracToCanvas(fx, fy, W, H, crop){\n  const c = crop || annot.crop; // crop explicite : composition hors editeur (rapport, v4.24)\n  return [ (fx - c.x)/c.w * W, (fy - c.y)/c.h * H ];\n}\nfunction canvasToFrac(px, py, W, H){\n  const c = annot.crop;\n  return [ c.x + (px/W)*c.w, c.y + (py/H)*c.h ];\n}\nfunction drawAnnotArrowhead(ctx, fromX, fromY, toX, toY, size){\n  const angle = Math.atan2(toY-fromY, toX-fromX);\n  ctx.beginPath();\n  ctx.moveTo(toX, toY);\n  ctx.lineTo(toX - size*Math.cos(angle-Math.PI/7), toY - size*Math.sin(angle-Math.PI/7));\n  ctx.lineTo(toX - size*Math.cos(angle+Math.PI/7), toY - size*Math.sin(angle+Math.PI/7));\n  ctx.closePath();\n  ctx.fill();\n}\nfunction annotShapeBBox(s, W, H){\n  if(s.type === \"arrow\" || s.type === \"curve\"){\n    const [x1,y1] = fracToCanvas(s.x1,s.y1,W,H), [x2,y2] = fracToCanvas(s.x2,s.y2,W,H);\n    const xs=[x1,x2], ys=[y1,y2];\n    if(s.type === \"curve\"){ const [cx,cy]=fracToCanvas(s.cx,s.cy,W,H); xs.push(cx); ys.push(cy); }\n    return { x:Math.min(...xs), y:Math.min(...ys), w:Math.max(...xs)-Math.min(...xs), h:Math.max(...ys)-Math.min(...ys) };\n  }\n  if(s.type === \"rect\" || s.type === \"ellipse\"){\n    const [x,y] = fracToCanvas(s.x,s.y,W,H), [x2,y2] = fracToCanvas(s.x+s.w,s.y+s.h,W,H);\n    return { x:Math.min(x,x2), y:Math.min(y,y2), w:Math.abs(x2-x), h:Math.abs(y2-y) };\n  }\n  if(s.type === \"text\"){\n    const [x,y] = fracToCanvas(s.x,s.y,W,H);\n    const fontSize = Math.max(14, Math.min(W,H)*0.045);\n    return { x, y, w:(s.text||\"\").length*fontSize*0.55, h:fontSize+4 };\n  }\n  return { x:0,y:0,w:0,h:0 };\n}\nfunction drawAnnotShapes(ctx, shapes, W, H, selectedIdx, crop){\n  // crop explicite : composition hors editeur (aplatissage rapport, v4.24) \u2014 sinon\n  // c'est le crop de l'editeur ouvert (annot.crop) qui sert, comme avant.\n  const lw = Math.max(2, Math.min(W,H)*0.006);\n  shapes.forEach((s, i) => {\n    ctx.strokeStyle = s.color; ctx.fillStyle = s.color; ctx.lineWidth = lw;\n    if(s.type === \"arrow\" || s.type === \"curve\"){\n      const [x1,y1] = fracToCanvas(s.x1,s.y1,W,H,crop), [x2,y2] = fracToCanvas(s.x2,s.y2,W,H,crop);\n      ctx.beginPath(); ctx.moveTo(x1,y1);\n      if(s.type === \"curve\"){\n        const [cx,cy] = fracToCanvas(s.cx,s.cy,W,H,crop);\n        ctx.quadraticCurveTo(cx,cy,x2,y2); ctx.stroke();\n        drawAnnotArrowhead(ctx, cx, cy, x2, y2, lw*4);\n      } else {\n        ctx.lineTo(x2,y2); ctx.stroke();\n        drawAnnotArrowhead(ctx, x1, y1, x2, y2, lw*4);\n      }\n    } else if(s.type === \"rect\"){\n      const [x,y] = fracToCanvas(s.x,s.y,W,H,crop), [x2,y2] = fracToCanvas(s.x+s.w,s.y+s.h,W,H,crop);\n      ctx.strokeRect(x, y, x2-x, y2-y);\n    } else if(s.type === \"ellipse\"){\n      const [x,y] = fracToCanvas(s.x,s.y,W,H,crop), [x2,y2] = fracToCanvas(s.x+s.w,s.y+s.h,W,H,crop);\n      ctx.beginPath();\n      ctx.ellipse((x+x2)/2, (y+y2)/2, Math.abs(x2-x)/2, Math.abs(y2-y)/2, 0, 0, Math.PI*2);\n      ctx.stroke();\n    } else if(s.type === \"text\"){\n      const [x,y] = fracToCanvas(s.x,s.y,W,H,crop);\n      const fontSize = Math.max(14, Math.min(W,H)*0.045);\n      ctx.font = `700 ${fontSize}px 'Archivo','Open Sans',Arial,sans-serif`;\n      ctx.textBaseline = \"top\";\n      const w = ctx.measureText(s.text).width;\n      ctx.fillStyle = \"rgba(255,255,255,.75)\"; ctx.fillRect(x-3, y-2, w+6, fontSize+6);\n      ctx.fillStyle = s.color; ctx.fillText(s.text, x, y);\n    }\n    if(i === selectedIdx){\n      ctx.save();\n      ctx.strokeStyle = \"#1B5EA6\"; ctx.lineWidth = 1.5; ctx.setLineDash([4,3]);\n      const bb = annotShapeBBox(s, W, H);\n      ctx.strokeRect(bb.x-4, bb.y-4, bb.w+8, bb.h+8);\n      ctx.setLineDash([]);\n      if(s.type === \"curve\"){\n        const [cx,cy] = fracToCanvas(s.cx, s.cy, W, H, crop);\n        ctx.fillStyle = \"#1B5EA6\"; ctx.beginPath(); ctx.arc(cx,cy,6,0,Math.PI*2); ctx.fill();\n      }\n      ctx.restore();\n    }\n  });\n}\nfunction distToSegment(px,py,x1,y1,x2,y2){\n  const dx=x2-x1, dy=y2-y1, len2=dx*dx+dy*dy;\n  let t = len2 ? ((px-x1)*dx+(py-y1)*dy)/len2 : 0;\n  t = Math.max(0, Math.min(1, t));\n  return Math.hypot(px-(x1+t*dx), py-(y1+t*dy));\n}\nfunction annotHitTest(px, py, W, H){\n  for(let i=annot.shapes.length-1; i>=0; i--){\n    const s = annot.shapes[i];\n    if(s.type === \"arrow\" || s.type === \"curve\"){\n      const [x1,y1] = fracToCanvas(s.x1,s.y1,W,H), [x2,y2] = fracToCanvas(s.x2,s.y2,W,H);\n      if(s.type === \"curve\"){\n        const [cx,cy] = fracToCanvas(s.cx,s.cy,W,H);\n        let hit = false;\n        for(let t=0;t<=1;t+=0.05){\n          const bx=(1-t)*(1-t)*x1+2*(1-t)*t*cx+t*t*x2, by=(1-t)*(1-t)*y1+2*(1-t)*t*cy+t*t*y2;\n          if(Math.hypot(px-bx,py-by) < 10){ hit = true; break; }\n        }\n        if(hit) return i;\n      } else if(distToSegment(px,py,x1,y1,x2,y2) < 10) return i;\n    } else {\n      const bb = annotShapeBBox(s, W, H);\n      if(px >= bb.x-4 && px <= bb.x+bb.w+4 && py >= bb.y-4 && py <= bb.y+bb.h+4) return i;\n    }\n  }\n  return -1;\n}\nfunction fractionCropToCanvasRect(crop, W, H){ return { x:crop.x*W, y:crop.y*H, w:crop.w*W, h:crop.h*H }; }\nfunction redrawAnnotCanvas(){\n  const canvas = document.getElementById(\"annotCanvas\");\n  if(!canvas || !annot) return;\n  const ctx = canvas.getContext(\"2d\");\n  ctx.clearRect(0,0,canvas.width,canvas.height);\n  if(annot.tool === \"crop\"){\n    ctx.drawImage(annot.img, 0, 0, canvas.width, canvas.height);\n    const rect = annot.cropDraft || fractionCropToCanvasRect(annot.crop, canvas.width, canvas.height);\n    ctx.save();\n    ctx.fillStyle = \"rgba(0,0,0,.45)\";\n    ctx.fillRect(0, 0, canvas.width, rect.y);\n    ctx.fillRect(0, rect.y+rect.h, canvas.width, canvas.height-(rect.y+rect.h));\n    ctx.fillRect(0, rect.y, rect.x, rect.h);\n    ctx.fillRect(rect.x+rect.w, rect.y, canvas.width-(rect.x+rect.w), rect.h);\n    ctx.restore();\n    ctx.strokeStyle = \"#fff\"; ctx.lineWidth = 2; ctx.setLineDash([6,4]);\n    ctx.strokeRect(rect.x, rect.y, rect.w, rect.h);\n    ctx.setLineDash([]);\n    return;\n  }\n  const scale = canvas.width / (annot.crop.w * annot.img.naturalWidth);\n  ctx.drawImage(annot.img, -annot.crop.x*annot.img.naturalWidth*scale, -annot.crop.y*annot.img.naturalHeight*scale,\n    annot.img.naturalWidth*scale, annot.img.naturalHeight*scale);\n  drawAnnotShapes(ctx, annot.shapes, canvas.width, canvas.height, annot.selected);\n  if(annot.draft) drawAnnotShapes(ctx, [annot.draft], canvas.width, canvas.height, -1);\n}\nfunction commitDraft(){\n  if(!annot.draft) return;\n  const d = annot.draft;\n  const degenerate = (d.type === \"arrow\" || d.type === \"curve\")\n    ? Math.hypot(d.x2-d.x1, d.y2-d.y1) < 0.006\n    : (d.w < 0.006 || d.h < 0.006);\n  if(!degenerate){\n    annot.shapes.push(d);\n    annot.selected = annot.shapes.length-1;\n    if(d.type === \"curve\"){ annot.draft = null; annot.tool = \"move\"; renderAnnotEditor(); return; }\n  }\n  annot.draft = null;\n  redrawAnnotCanvas();\n}\nfunction bindAnnotPointerEvents(canvas){\n  let dragging = null;\n  const getPos = (e) => {\n    const r = canvas.getBoundingClientRect();\n    const cx = e.clientX - r.left, cy = e.clientY - r.top;\n    return [ cx * canvas.width/r.width, cy * canvas.height/r.height ];\n  };\n  // Suppr/Retour arriere efface la forme selectionnee \u2014 promis par le hint du mode\n  // \"Selection / deplacer\" (ANNOT_HINTS.move), il fallait le cabler\n  canvas.addEventListener(\"keydown\", (e) => {\n    if((e.key === \"Delete\" || e.key === \"Backspace\") && annot.selected >= 0){\n      e.preventDefault();\n      annot.shapes.splice(annot.selected, 1);\n      annot.selected = -1;\n      redrawAnnotCanvas();\n    }\n  });\n  canvas.addEventListener(\"pointerdown\", (e) => {\n    canvas.setPointerCapture(e.pointerId);\n    canvas.focus();\n    const [px,py] = getPos(e);\n    const W = canvas.width, H = canvas.height;\n    if(annot.tool === \"crop\"){\n      dragging = { kind:\"crop\", x0:px, y0:py };\n      annot.cropDraft = { x:px, y:py, w:0, h:0 };\n      return;\n    }\n    if(annot.tool === \"move\"){\n      if(annot.selected >= 0 && annot.shapes[annot.selected] && annot.shapes[annot.selected].type === \"curve\"){\n        const s = annot.shapes[annot.selected];\n        const [hx,hy] = fracToCanvas(s.cx, s.cy, W, H);\n        if(Math.hypot(px-hx, py-hy) < 14){ dragging = { kind:\"curveHandle\", idx: annot.selected }; return; }\n      }\n      const hit = annotHitTest(px, py, W, H);\n      annot.selected = hit;\n      if(hit >= 0) dragging = { kind:\"moveShape\", idx:hit, startPx:px, startPy:py, snapshot: JSON.parse(JSON.stringify(annot.shapes[hit])) };\n      redrawAnnotCanvas();\n      return;\n    }\n    if(annot.tool === \"text\"){\n      dialogueDemander(\"Texte \u00e0 afficher sur la photo :\", \"\", { titre: \"Texte sur la photo\" }).then(txt => {\n        if(txt){\n          const [fx,fy] = canvasToFrac(px, py, W, H);\n          annot.shapes.push({ type:\"text\", x:fx, y:fy, text:txt, color: annot.color });\n          annot.selected = annot.shapes.length-1;\n        }\n        redrawAnnotCanvas();\n      });\n      return;\n    }\n    const [fx,fy] = canvasToFrac(px, py, W, H);\n    dragging = { kind:\"draw\", startFx:fx, startFy:fy };\n    if(annot.tool === \"arrow\") annot.draft = { type:\"arrow\", x1:fx, y1:fy, x2:fx, y2:fy, color: annot.color };\n    else if(annot.tool === \"curve\") annot.draft = { type:\"curve\", x1:fx, y1:fy, cx:fx, cy:fy, x2:fx, y2:fy, color: annot.color };\n    else if(annot.tool === \"rect\") annot.draft = { type:\"rect\", x:fx, y:fy, w:0, h:0, color: annot.color };\n    else if(annot.tool === \"ellipse\") annot.draft = { type:\"ellipse\", x:fx, y:fy, w:0, h:0, color: annot.color };\n  });\n  canvas.addEventListener(\"pointermove\", (e) => {\n    if(!dragging) return;\n    const [px,py] = getPos(e);\n    const W = canvas.width, H = canvas.height;\n    if(dragging.kind === \"crop\"){\n      annot.cropDraft = { x:Math.min(dragging.x0,px), y:Math.min(dragging.y0,py), w:Math.abs(px-dragging.x0), h:Math.abs(py-dragging.y0) };\n      redrawAnnotCanvas(); return;\n    }\n    if(dragging.kind === \"curveHandle\"){\n      const [fx,fy] = canvasToFrac(px, py, W, H);\n      annot.shapes[dragging.idx].cx = fx; annot.shapes[dragging.idx].cy = fy;\n      redrawAnnotCanvas(); return;\n    }\n    if(dragging.kind === \"moveShape\"){\n      const [fx0,fy0] = canvasToFrac(dragging.startPx, dragging.startPy, W, H);\n      const [fx1,fy1] = canvasToFrac(px, py, W, H);\n      const dx = fx1-fx0, dy = fy1-fy0, snap = dragging.snapshot, s = annot.shapes[dragging.idx];\n      if(s.type === \"arrow\" || s.type === \"curve\"){\n        s.x1 = snap.x1+dx; s.y1 = snap.y1+dy; s.x2 = snap.x2+dx; s.y2 = snap.y2+dy;\n        if(s.type === \"curve\"){ s.cx = snap.cx+dx; s.cy = snap.cy+dy; }\n      } else { s.x = snap.x+dx; s.y = snap.y+dy; }\n      redrawAnnotCanvas(); return;\n    }\n    if(dragging.kind === \"draw\"){\n      const [fx,fy] = canvasToFrac(px, py, W, H);\n      if(annot.tool === \"arrow\"){ annot.draft.x2 = fx; annot.draft.y2 = fy; }\n      else if(annot.tool === \"curve\"){ annot.draft.x2 = fx; annot.draft.y2 = fy; annot.draft.cx = (annot.draft.x1+fx)/2; annot.draft.cy = (annot.draft.y1+fy)/2; }\n      else if(annot.tool === \"rect\" || annot.tool === \"ellipse\"){\n        annot.draft.x = Math.min(dragging.startFx, fx); annot.draft.y = Math.min(dragging.startFy, fy);\n        annot.draft.w = Math.abs(fx-dragging.startFx); annot.draft.h = Math.abs(fy-dragging.startFy);\n      }\n      redrawAnnotCanvas();\n    }\n  });\n  const finish = () => {\n    if(dragging && dragging.kind === \"draw\") commitDraft();\n    if(dragging && dragging.kind === \"crop\"){\n      // met a jour l'etat du bouton \"Valider\" sans reconstruire toute la barre d'outils\n      const btn = document.getElementById(\"annotCropApply\");\n      const hasDraft = annot.cropDraft && annot.cropDraft.w > 4 && annot.cropDraft.h > 4;\n      if(btn){ btn.disabled = !hasDraft; btn.title = hasDraft ? \"\" : \"Dessinez d'abord la zone \u00e0 conserver\"; }\n    }\n    dragging = null;\n  };\n  canvas.addEventListener(\"pointerup\", finish);\n  canvas.addEventListener(\"pointercancel\", finish);\n}\nfunction saveAnnotEditor(){\n  const p = photoOfAnnot();\n  if(p){\n    const c = annot.crop;\n    p.crop = (c.x===0 && c.y===0 && c.w>=0.999 && c.h>=0.999) ? null : c;\n    p.annotations = annot.shapes;\n    p.legende = annot.legendeDraft;\n  }\n  annot = null;\n  saveData();\n  // saveData() avale ses erreurs (localStorage plein, etc.) et se contente de basculer\n  // storageOk a false : sans ce controle, l'annotation reste correcte en memoire pour la\n  // session en cours mais l'utilisateur ferme le panneau en croyant qu'elle est sauvegardee,\n  // alors qu'un rechargement la perdrait\n  if(!storageOk){\n    dialogueAlerte(\"La photo annot\u00e9e reste affich\u00e9e pour cette session, mais la sauvegarde automatique est actuellement bloqu\u00e9e (stockage plein ou indisponible) \u2014 elle sera perdue \u00e0 la fermeture. Exportez le suivi (.json) d\u00e8s maintenant pour ne rien perdre.\", \"Sauvegarde bloqu\u00e9e\");\n  }\n  fermerPanneaux();\n  render();\n}\n/* recompose rognage + formes sur un canvas offscreen, pour la lightbox (jamais de fichier\n   modifie) : reutilise le moteur de dessin de l'editeur via un `annot` temporaire minimal */\nasync function openAnnotatedLightbox(essaiId, photoId){\n  const sc = data.find(s => s.essais && s.essais.some(e => e.id === essaiId));\n  const es = sc && sc.essais.find(e => e.id === essaiId);\n  const p = es && (es.photos||[]).find(x => x.id === photoId);\n  if(!p) return;\n  const url = await photoObjectURL(p); // v4.16 : dossier local ou cloud\n  if(!url) return;\n  const hasCrop = p.crop && (p.crop.w < 0.999 || p.crop.h < 0.999 || p.crop.x > 0 || p.crop.y > 0);\n  if(!hasCrop && !(p.annotations && p.annotations.length)){\n    document.getElementById(\"imgLightboxImg\").addEventListener(\"load\", () => URL.revokeObjectURL(url), { once:true });\n    ouvrirLightbox(url);\n    return;\n  }\n  const img = new Image();\n  img.onload = () => {\n    const crop = p.crop || defaultCrop();\n    const nw = img.naturalWidth, nh = img.naturalHeight;\n    const cw = crop.w*nw, ch = crop.h*nh;\n    const scale = Math.min(1, 1600/Math.max(cw,ch));\n    const canvas = document.createElement(\"canvas\");\n    canvas.width = Math.max(1, Math.round(cw*scale));\n    canvas.height = Math.max(1, Math.round(ch*scale));\n    const ctx = canvas.getContext(\"2d\");\n    const drawScale = canvas.width/cw;\n    ctx.drawImage(img, -crop.x*nw*drawScale, -crop.y*nh*drawScale, nw*drawScale, nh*drawScale);\n    URL.revokeObjectURL(url); // dessine sur le canvas, le Blob source n'est plus necessaire\n    const saved = annot;\n    annot = { crop };\n    drawAnnotShapes(ctx, p.annotations || [], canvas.width, canvas.height, -1);\n    annot = saved;\n    ouvrirLightbox(canvas.toDataURL(\"image/jpeg\", 0.9));\n  };\n  img.src = url;\n}\n\nfunction equipeOptions(selected){\n  return [\"\", \"Matin\", \"Apr\u00e8s-midi\", \"Nuit\"].map(o =>\n    `<option value=\"${o}\" ${selected === o ? \"selected\" : \"\"}>${o || \"\u2014\"}</option>`).join(\"\");\n}\n\nfunction essaiCardHTML(sc, essai, interactive){\n  const es = essaiStats(sc, essai);\n  const badgeClass = es.status === \"ok\" ? \"ok\" : es.status === \"bad\" ? \"risk\" : es.status === \"arrete\" ? \"arrete\" : \"pending\";\n  const badgeText = es.status === \"ok\" ? \"\u2713 Conforme\"\n    : es.status === \"bad\" ? \"\u2717 Non conforme \u2014 \" + es.raison\n    : es.status === \"arrete\" ? \"\u23f9 \" + es.raison\n    : \"En cours \u2014 \" + es.raison;\n\n  const head = interactive ? `\n    <input class=\"cell ref essai-titre\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-field=\"titre\" value=\"${escapeAttr(essai.titre)}\">\n    <input class=\"cell\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-field=\"date\" type=\"date\" value=\"${essai.date ?? \"\"}\">\n    <select class=\"cell log-equipe\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-field=\"equipe\">${equipeOptions(essai.equipe)}</select>\n    <input class=\"cell ref\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-field=\"operateur\" value=\"${escapeAttr(essai.operateur)}\" placeholder=\"Op\u00e9rateur\">\n    <span class=\"status-badge ${badgeClass}\">${badgeText}</span>\n    <button class=\"ghost small essai-cloture\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" title=\"${essai.cloture ? \"Modifier le motif ou r\u00e9ouvrir cet essai arr\u00eat\u00e9\" : \"Cl\u00f4turer cet essai \u2014 arr\u00eat anticip\u00e9 avant la charni\u00e8re (casse, brut, incident...)\"}\">${essai.cloture ? \"\u23f9 Arr\u00eat\u00e9\" : \"\u23f9 Cl\u00f4turer\"}</button>\n    <button class=\"log-del essai-del\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\">\u2715 Essai</button>\n  ` : `\n    <span class=\"sc-name-print\" style=\"font-size:14px;\">${escapeAttr(essai.titre)}</span>\n    <span class=\"essai-meta-print\">${essai.date || \"\u2014\"} \u00b7 ${essai.equipe || \"\u2014\"} \u00b7 ${escapeAttr(essai.operateur) || \"\u2014\"}</span>\n    <span class=\"status-badge ${badgeClass}\">${badgeText}</span>\n  `;\n\n  const butRow = interactive\n    ? `<div class=\"essai-but-wrap\"><span class=\"essai-but-icon\">\u25ce</span><input class=\"essai-but\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-field=\"but\"\n         value=\"${escapeAttr(essai.but)}\" placeholder=\"But de l'essai : ce qu'on cherche \u00e0 valider...\"></div>`\n    : (essai.but ? `<div class=\"essai-but-print\">But : ${escapeAttr(essai.but)}</div>` : \"\");\n\n  const obsRow = interactive\n    ? `<div class=\"essai-obs-wrap\"><span class=\"essai-obs-icon\">\u270e</span><input class=\"essai-obs\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-field=\"observations\"\n         value=\"${escapeAttr(essai.observations)}\" placeholder=\"Observations : mode d'usure, entaille, incident, lot de fonte\u2026\"></div>`\n    : (essai.observations ? `<div class=\"essai-obs-print\">Observations : ${escapeAttr(essai.observations)}</div>` : \"\");\n\n  // tracabilite terrain : qui a redige, quand l'essai s'est termine (pas seulement commence),\n  // et quel programme CNC tournait \u2014 trois infos que le rapport papier de Matis note toujours\n  // et qu'aucun champ ne capturait avant la v3.11\n  const finEssaiRow = interactive\n    ? `<div class=\"essai-params\" style=\"flex-wrap:wrap;\">\n         <span title=\"Qui a r\u00e9dig\u00e9 ce rapport d'essai \u2014 peut diff\u00e9rer de l'op\u00e9rateur machine, renseign\u00e9 plus haut.\">R\u00e9dig\u00e9 par \u2014</span>\n         <input class=\"cell ref\" style=\"width:160px; min-width:120px;\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-field=\"redigePar\" value=\"${escapeAttr(essai.redigePar)}\" placeholder=\"${escapeAttr(auteurNom) || \"Nom du r\u00e9dacteur\"}\" title=\"Nom du r\u00e9dacteur du rapport \u2014 l'op\u00e9rateur machine (champ ci-dessus) peut \u00eatre une personne diff\u00e9rente.\">\n         <span style=\"margin-left:10px;\">D\u00e9but essai \u2014</span>\n         <input class=\"cell\" style=\"width:95px; min-width:80px;\" type=\"time\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-field=\"heureDebut\" value=\"${essai.heureDebut ?? \"\"}\" title=\"Pr\u00e9-remplit la fen\u00eatre horaire du suivi Marposs (si elle est encore vide)\">\n         <span style=\"margin-left:10px;\">Fin d'essai \u2014</span>\n         <input class=\"cell\" style=\"width:135px; min-width:120px;\" type=\"date\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-field=\"dateFin\" value=\"${essai.dateFin ?? \"\"}\">\n         <input class=\"cell\" style=\"width:95px; min-width:80px;\" type=\"time\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-field=\"heureFin\" value=\"${essai.heureFin ?? \"\"}\" title=\"Pr\u00e9-remplit la fen\u00eatre horaire du suivi Marposs (si elle est encore vide)\">\n       </div>`\n    : ((essai.redigePar || essai.dateFin || essai.heureDebut) ? `<div class=\"essai-obs-print\">${essai.redigePar ? \"R\u00e9dig\u00e9 par : \" + escapeAttr(essai.redigePar) : \"\"}${essai.dateFin ? (essai.redigePar ? \" \u00b7 \" : \"\") + \"Fin d'essai : \" + essai.dateFin + (essai.heureFin ? \" \u00e0 \" + essai.heureFin : \"\") : \"\"}${essai.heureDebut ? (essai.dateFin || essai.redigePar ? \" \u00b7 \" : \"\") + \"D\u00e9but : \" + essai.heureDebut : \"\"}</div>` : \"\");\n\n  const programmeRow = sc.emag1\n    ? (interactive\n        ? `<div class=\"essai-params\" style=\"flex-wrap:wrap;\">\n             <span>Programme \u2014</span>\n             <input class=\"cell ref\" style=\"width:150px; min-width:110px;\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-field=\"programmeGauche\" value=\"${escapeAttr(essai.programmeGauche)}\" placeholder=\"Gauche\">\n             <input class=\"cell ref\" style=\"width:150px; min-width:110px;\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-field=\"programmeDroit\" value=\"${escapeAttr(essai.programmeDroit)}\" placeholder=\"Droit\">\n           </div>`\n        : ((essai.programmeGauche || essai.programmeDroit) ? `<div class=\"essai-obs-print\">Programme \u2014 Gauche : ${escapeAttr(essai.programmeGauche) || \"\u2014\"} \u00b7 Droit : ${escapeAttr(essai.programmeDroit) || \"\u2014\"}</div>` : \"\"))\n    : (interactive\n        ? `<div class=\"essai-params\" style=\"flex-wrap:wrap;\">\n             <span>Programme \u2014</span>\n             <input class=\"cell ref\" style=\"width:220px; min-width:150px;\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-field=\"programme\" value=\"${escapeAttr(essai.programme)}\" placeholder=\"Nom du programme CNC\">\n           </div>`\n        : (essai.programme ? `<div class=\"essai-obs-print\">Programme : ${escapeAttr(essai.programme)}</div>` : \"\"));\n\n  // conditions de coupe de chaque logement, telles qu'elles etaient au moment de l'essai.\n  // v4.11 : la s\u00e9lection est cochable \u2014 \u2715 sur une puce = ne plus suivre ce logement dans\n  // CET essai (il reste dans le sc\u00e9nario et re-suivable \u00e0 tout moment).\n  const snap = logementsSuivis(essai);\n  const tousSnap = (essai.params && essai.params.logements) || [];\n  const diverge = paramsDivergences(sc, essai);\n  const chips = snap.map(lp => {\n    const oi = sc.outils.findIndex(o => o.id === lp.outilId);\n    const couleur = oi >= 0 ? OUTIL_COLORS[oi % OUTIL_COLORS.length] : \"var(--ink-faint)\";\n    const nom = nomLogementActuel(sc, lp); // v4.22 : renommer se voit tout de suite\n    const croix = interactive ? `<button class=\"essai-lp-del\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-lp=\"${lp.logementId}\" title=\"Ne plus suivre ce logement dans cet essai (le logement reste dans le sc\u00e9nario, re-suivable \u00e0 tout moment)\">\u2715</button>` : \"\";\n    return `<b style=\"border-left:3px solid ${couleur}; padding-left:6px;\">${escapeAttr(nom.outilNumero||\"\u2014\")} \u00b7 ${escapeAttr(nom.logementNom||\"\u2014\")} \u2014 Vc ${lp.vc === \"\" || lp.vc == null ? \"\u2014\" : lp.vc} f ${lp.f === \"\" || lp.f == null ? \"\u2014\" : lp.f} charni\u00e8re ${lp.charniere === \"\" || lp.charniere == null ? \"\u2014\" : lp.charniere} p${croix}</b>`;\n  }).join(\"\");\n  const ajoutables = interactive\n    ? snapshotLogements(sc).filter(c => !snap.some(s => s.logementId === c.logementId))\n    : [];\n  const lpAdd = interactive ? `\n    <select class=\"cell essai-lp-add\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" style=\"max-width:250px; min-width:160px;\" title=\"Ajouter un logement du sc\u00e9nario au suivi de cet essai\">\n      <option value=\"\">+ suivre un logement\u2026</option>\n      ${ajoutables.map(c => `<option value=\"${c.logementId}\">${escapeAttr((c.outilNumero||\"?\") + \" \u00b7 \" + (c.logementNom||\"\u2014\"))}</option>`).join(\"\")}\n    </select>` : \"\";\n  const paramsRow = `\n    <div class=\"essai-params${diverge.length ? \" diverge\" : \"\"}\" style=\"flex-wrap:wrap;\">\n      <span>Conditions de l'essai \u2014</span>\n      ${chips}${lpAdd}\n      ${(!chips && !interactive) ? `<span style=\"color:var(--ink-faint);\">aucun logement suivi</span>` : \"\"}\n      ${diverge.length ? `<span class=\"essai-diverge\">\u26a0 modifi\u00e9 depuis : ${escapeAttr(diverge.join(\" \u00b7 \"))}${interactive ? ` <button class=\"params-sync\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\">Aligner sur le sc\u00e9nario</button>` : \"\"}</span>` : \"\"}\n    </div>\n    <div class=\"essai-params\">\n      <span>Maturit\u00e9 des bruts \u2014</span>\n      ${interactive\n        ? `<input class=\"cell\" style=\"width:60px; min-width:60px;\" type=\"number\" step=\"1\" min=\"0\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-field=\"maturiteBruts\" value=\"${essai.maturiteBruts ?? \"\"}\">`\n        : `<b>${essai.maturiteBruts === \"\" || essai.maturiteBruts == null ? \"\u2014\" : essai.maturiteBruts}</b>`}\n      <span>jour${parseFloat(essai.maturiteBruts) > 1 ? \"s\" : \"\"}</span>\n      <span style=\"margin-left:auto; color:var(--ink-faint);\">Taux hors tol\u00e9rance de l'essai : <b style=\"color:var(--ink-soft);\">${es.tauxHorsTol === null ? \"\u2014\" : fmt(es.tauxHorsTol,0) + \" %\"}</b></span>\n    </div>`;\n\n  const mesureLabel = escapeAttr(libelleDe(sc));\n  const snapLogements = logementsSuivis(essai);\n  const showLogementCol = snapLogements.length > 1;\n  const logementHead = showLogementCol ? `<th>Logement</th>` : \"\";\n  // v4.9 : colonnes battement selon les c\u00f4t\u00e9s choisis ; crit\u00e8res suppl\u00e9mentaires : une\n  // colonne par crit\u00e8re actif \u00d7 axe (ou une seule si le crit\u00e8re n'a pas d'axe)\n  const cotes = battCotesDe(sc);\n  const battHeads = cotes === \"mono\" ? `<th class=\"num\">${mesureLabel}</th>`\n    : cotes === \"D\" ? `<th class=\"num\">${mesureLabel} D</th>`\n    : cotes === \"G\" ? `<th class=\"num\">${mesureLabel} G</th>`\n    : `<th class=\"num\">Droite</th><th class=\"num\">Gauche</th>`;\n  const csupCols = csupColonnes(sc);\n  const csupHeads = csupCols.map(col => `<th class=\"num\">${escapeAttr(col.c.label || \"crit\u00e8re\")}${col.ax !== \"v\" ? \" \" + (AXE_LABELS[col.ax] || col.ax) : \"\"}</th>`).join(\"\");\n  const prelHead = `${logementHead}<th class=\"num\">N\u00b0 pi\u00e8ce</th><th>Point de mesure</th>${sc.battActif !== false ? battHeads : \"\"}${csupHeads}<th>Usure</th><th>Conf.</th>`;\n  const prelListe = interactive\n    ? (essai.prelevements||[])\n    : (essai.prelevements||[]).slice().sort((a,b) => (parseFloat(a.piece)||0) - (parseFloat(b.piece)||0));\n  const prelRows = prelListe.map(p => prelevementRowHTML(sc, essai, p, interactive, snapLogements, showLogementCol)).join(\"\");\n  const addPrelBtn = interactive ? `<button class=\"ghost prel-add\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\">+ Ajouter un pr\u00e9l\u00e8vement</button>\n    <button class=\"primary atelier-open\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" title=\"Saisie plein \u00e9cran, gros champs \u2014 pour mesurer devant la machine\"><svg class=\"icon\" viewBox=\"0 0 18 18\"><path d=\"M3.5 3.5h11v11h-11z\" stroke-linejoin=\"round\"/><path d=\"M6.5 9h5M9 6.5v5\" stroke-linecap=\"round\"/></svg>Mode atelier</button>\n    <button class=\"ghost essai-comparer\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" title=\"Superposer cet essai \u00e0 un autre : conditions c\u00f4te \u00e0 c\u00f4te, courbes, r\u00e9p\u00e9tabilit\u00e9\"><svg class=\"icon\" viewBox=\"0 0 18 18\"><path d=\"M3 15V6M9 15V3M15 15v-7\" stroke-linecap=\"round\"/></svg>Comparer\u2026</button>\n    <button class=\"ghost essai-rapport\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" title=\"G\u00e9n\u00e8re un rapport HTML autonome de cet essai \u2014 interlocuteurs, but, plaquettes, mesures\"><svg class=\"icon\" viewBox=\"0 0 18 18\"><path d=\"M5 2.5h5l3 3V15a.8.8 0 0 1-.8.8H5.8a.8.8 0 0 1-.8-.8V2.5Z\" stroke-linejoin=\"round\"/><path d=\"M6.5 9h5M6.5 11.5h5M6.5 6.5h2\"/></svg>Rapport de l'essai</button>` : \"\";\n  const emptyColspan = (showLogementCol?1:0) + 2 + (sc.battActif !== false ? (cotes === \"DG\" ? 2 : 1) : 0) + csupCols.length + 1 + (interactive?1:0);\n\n  // une progression independante par logement : un outil peut atteindre sa charniere\n  // pendant qu'un autre continue, chacun avec sa propre cible\n  const progressRows = es.logementProgress.map(lp => {\n    const pct = lp.target ? Math.min(100, ((lp.lastPiece||0)/lp.target)*100) : 0;\n    return `\n      <div class=\"logement-progress\">\n        <span class=\"lp-label\">${escapeAttr(lp.outilNumero||\"\u2014\")} \u00b7 ${escapeAttr(lp.logementNom||\"\u2014\")}</span>\n        <div class=\"progress-track small\"><div class=\"progress-fill ${lp.complete?\"ok\":\"\"}\" style=\"width:${pct}%;\"></div></div>\n        <span class=\"lp-val\">${lp.lastPiece ?? 0} / ${lp.target ?? \"\u2014\"} p</span>\n        ${previsionChipHTML(sc, essai, lp)}\n      </div>`;\n  }).join(\"\");\n\n  // v4.30 \u2014 contexte repliable : le quotidien d'un essai, ce sont les conditions, les\n  // pr\u00e9l\u00e8vements et la progression. Le but, les observations, la r\u00e9daction et le programme\n  // sont du contexte de cr\u00e9ation : regroup\u00e9s, ouverts tant que tout est vide, repli\u00e9s d\u00e8s\n  // qu'un champ est rempli (un r\u00e9sum\u00e9 du but reste lisible dans le bandeau repli\u00e9).\n  const ctxKey = sc.id + \"|\" + essai.id;\n  const ctxVide = !(essai.but || essai.observations || essai.redigePar || essai.dateFin || essai.heureDebut || essai.heureFin || essai.programme || essai.programmeGauche || essai.programmeDroit);\n  const butTxt = String(essai.but || \"\");\n  const ctxResume = butTxt ? escapeAttr(butTxt.length > 90 ? butTxt.slice(0, 90) + \"\u2026\" : butTxt) : \"\";\n  const ctxBloc = interactive\n    ? `<details class=\"essai-ctx\"${(ctxVide || essaiCtxOuverts.has(ctxKey)) ? \" open\" : \"\"} data-essai-id=\"${essai.id}\">\n        <summary>Contexte \u2014 but, observations, r\u00e9daction, programme${ctxResume ? `<span class=\"essai-ctx-resume\">\u25ce ${ctxResume}</span>` : \"\"}</summary>\n        <div class=\"essai-ctx-body\">${butRow}${obsRow}${finEssaiRow}${programmeRow}</div>\n      </details>`\n    : `${butRow}${obsRow}${finEssaiRow}${programmeRow}`;\n\n  const body = `\n      <div class=\"essai-head\">${head}</div>\n      ${paramsRow}\n      ${ctxBloc}\n      <div class=\"tbl-wrap\">\n        <table>\n          <thead><tr>${prelHead}${interactive?\"<th></th>\":\"\"}</tr></thead>\n          <tbody>${prelRows || `<tr><td colspan=\"${emptyColspan}\" class=\"log-empty\">Aucun pr\u00e9l\u00e8vement</td></tr>`}</tbody>\n        </table>\n      </div>\n      ${addPrelBtn}\n      <div class=\"essai-progress-multi\">${progressRows || \"\"}</div>\n      ${interactive ? photosHTML(sc, essai) : \"\"}\n      ${interactive ? marpossHTML(sc, essai) : \"\"}\n  `;\n\n  if(!interactive){\n    return `<div class=\"essai-card ${badgeClass}\">${body}</div>`;\n  }\n\n  // replie en tuile par defaut : le detail (parametres, tableau, photos, marposs) ne\n  // s'affiche qu'a la demande, pour ne pas ouvrir l'ecran sur tous les essais a la fois.\n  // Cle composee scenario+essai : certains jeux de donnees reutilisent le meme id d'essai\n  // (ex. \"e1\") d'un scenario a l'autre.\n  const tileKey = sc.id + \"|\" + essai.id;\n  const tileMeta = [essai.date, essai.equipe].filter(Boolean).join(\" \u00b7 \");\n  return `\n    <details class=\"essai-card ${badgeClass}\" data-essai-id=\"${essai.id}\"${essaisOuverts.has(tileKey) ? \" open\" : \"\"}>\n      <summary>\n        <span class=\"essai-tile-title\">${escapeAttr(essai.titre || \"Essai\")}</span>\n        ${tileMeta ? `<span class=\"essai-tile-meta\">${escapeAttr(tileMeta)}</span>` : \"\"}\n        <span class=\"status-badge ${badgeClass}\">${badgeText}</span>\n      </summary>\n      <div class=\"essai-body\">${body}</div>\n    </details>\n  `;\n}\n\nfunction prelevementRowHTML(sc, essai, row, interactive, snapLogements, showLogementCol){\n  snapLogements = snapLogements || logementsSuivis(essai);\n  showLogementCol = showLogementCol !== undefined ? showLogementCol : snapLogements.length > 1;\n  /* v4.47.1 \u2014 calcul\u00e9 ICI : ce nom ne vivait que dans la port\u00e9e de essaiCardHTML, la\n     branche \u00ab mono \u00bb (sc\u00e9nario sans emag1) levait une ReferenceError qui figeait l'\u00e9cran\n     sur la s\u00e9lection pr\u00e9c\u00e9dente au lieu de rendre le sc\u00e9nario cliqu\u00e9 */\n  const mesureLabel = escapeAttr(libelleDe(sc));\n  const conform = checkConform(sc, row);\n  const exempte = !toleranceRequisePour(sc, row);\n  const badge = exempte ? `<span class=\"badge muted\" title=\"Ce logement ne suit que la charni\u00e8re, pas la tol\u00e9rance dimensionnelle.\">\ud83d\udd13 Charni\u00e8re</span>`\n    : conform === null ? `<span class=\"badge muted\">\u2014</span>` : conform ? `<span class=\"badge ok\">OK</span>` : `<span class=\"badge risk\">Hors tol.</span>`;\n  const rowClass = conform === false ? \"row-bad\" : conform === true ? \"row-ok\" : \"\";\n  if(interactive){\n    const logementCell = showLogementCol ? `\n      <td><select class=\"cell log-equipe small\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-prel=\"${row.id}\" data-field=\"logementId\">\n        <option value=\"\">\u2014</option>\n        ${snapLogements.map(lp => { const n = nomLogementActuel(sc, lp);\n          return `<option value=\"${lp.logementId}\" ${row.logementId===lp.logementId?\"selected\":\"\"}>${escapeAttr(n.outilNumero||\"\u2014\")} \u00b7 ${escapeAttr(n.logementNom||\"\u2014\")}</option>`; }).join(\"\")}\n      </select></td>` : \"\";\n    // v4.9 : colonnes battement selon les c\u00f4t\u00e9s choisis (un essai peut n'en porter qu'un)\n    const cotes = battCotesDe(sc);\n    const battCell = (field, lbl) => `<td class=\"num\"><input class=\"cell measure\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-prel=\"${row.id}\" data-field=\"${field}\" type=\"number\" step=\"0.001\" inputmode=\"decimal\" value=\"${row[field] ?? \"\"}\" aria-label=\"${lbl}\"></td>`;\n    const measureCells = sc.battActif === false ? \"\"\n      : cotes === \"mono\" ? battCell(\"batt\", mesureLabel)\n      : cotes === \"D\" ? battCell(\"battD\", \"Droite\")\n      : cotes === \"G\" ? battCell(\"battG\", \"Gauche\")\n      : battCell(\"battD\", \"Droite\") + battCell(\"battG\", \"Gauche\");\n    const csupCells = csupColonnes(sc).map(col => {\n      const v = ((row.valeurs||{})[col.c.id]||{})[col.ax];\n      return `<td class=\"num\"><input class=\"cell measure\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-prel=\"${row.id}\" data-csup=\"${col.c.id}\" data-csax=\"${col.ax}\" type=\"number\" step=\"0.001\" inputmode=\"decimal\" value=\"${v ?? \"\"}\"></td>`;\n    }).join(\"\");\n    const usureCell = `<td>${usureSelectHTML(row, `data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-prel=\"${row.id}\"`)}</td>`;\n    return `\n      <tr class=\"${rowClass}\">\n        ${logementCell}\n        <td class=\"num\"><input class=\"cell\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-prel=\"${row.id}\" data-field=\"piece\" type=\"number\" step=\"1\" inputmode=\"numeric\" value=\"${row.piece ?? \"\"}\"></td>\n        <td><input class=\"cell ref small\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-prel=\"${row.id}\" data-field=\"pointMesure\" value=\"${escapeAttr(row.pointMesure)}\" placeholder=\"Inter, Exter...\"></td>\n        ${measureCells}\n        ${csupCells}\n        ${usureCell}\n        <td>${badge}</td>\n        <td><button class=\"log-del prel-del\" data-id=\"${sc.id}\" data-essai=\"${essai.id}\" data-prel=\"${row.id}\">\u2715</button></td>\n      </tr>\n    `;\n  }\n  const logementLabel = snapLogements.find(lp => lp.logementId === row.logementId);\n  const nomLabel = logementLabel ? nomLogementActuel(sc, logementLabel) : null; // v4.28 : nom actuel\n  const logementCellPrint = showLogementCol ? `<td>${nomLabel ? escapeAttr(nomLabel.outilNumero||\"\u2014\") + \" \u00b7 \" + escapeAttr(nomLabel.logementNom||\"\u2014\") : \"\u2014\"}</td>` : \"\";\n  const cotesP = battCotesDe(sc);\n  const measureCells = sc.battActif === false ? \"\"\n    : cotesP === \"mono\" ? `<td class=\"num\">${fmtBatt(row.batt)}</td>`\n    : cotesP === \"D\" ? `<td class=\"num\">${fmtBatt(row.battD)}</td>`\n    : cotesP === \"G\" ? `<td class=\"num\">${fmtBatt(row.battG)}</td>`\n    : `<td class=\"num\">${fmtBatt(row.battD)}</td><td class=\"num\">${fmtBatt(row.battG)}</td>`;\n  const csupCellsPrint = csupColonnes(sc).map(col => {\n    const v = ((row.valeurs||{})[col.c.id]||{})[col.ax];\n    return `<td class=\"num\">${v === \"\" || v == null ? \"\u2014\" : v}</td>`;\n  }).join(\"\");\n  const usureCellPrint = `<td>${USURE_LABELS[row.usure] || \"\u2014\"}</td>`;\n  return `\n    <tr class=\"${rowClass}\">\n      ${logementCellPrint}\n      <td class=\"num\">${row.piece === \"\" || row.piece === undefined || row.piece === null ? \"\u2014\" : row.piece}</td>\n      <td>${row.pointMesure ? escapeAttr(row.pointMesure) : \"\u2014\"}</td>\n      ${measureCells}\n      ${csupCellsPrint}\n      ${usureCellPrint}\n      <td>${badge}</td>\n    </tr>\n  `;\n}\n\n/* un outil peut avoir plusieurs logements (positions plaquette) ; chaque logement est\n   independant (sa propre charniere, geometrie...). Couleur par outil pour identifier\n   d'un coup d'oeil quelles lignes appartiennent au meme outil physique. */\n/* Production annuelle de la reference, posee en haut a droite de la composition du\n   scenario : c'est le multiplicateur de tout le reste, il doit se lire sans le chercher.\n   N'apparait que si le module Volume annuel est actif et la valeur renseignee. */\n/* Volume annuel invalide : jusqu'ici, une valeur negative ou nulle faisait simplement\n   disparaitre le bandeau et tous les gains annuels, sans un mot. Pour qui s'est trompe de\n   signe ou a saisi 0, \"le gain a disparu\" est incomprehensible \u2014 et la valeur peut arriver\n   par un import, ou le min=\"0\" du champ ne protege rien. On le dit maintenant, avec le\n   chemin exact pour corriger. */\nfunction volumeInvalideHTML(){\n  if(!config.volumeActif) return \"\";\n  const r = getActiveReference();\n  const brut = r ? r.productionAnnuelle : \"\";\n  if(brut === \"\" || brut === null || brut === undefined) return \"\"; // simplement pas encore renseigne\n  const v = parseFloat(brut);\n  if(!isNaN(v) && v > 0) return \"\";\n  const cause = isNaN(v) ? \"n'est pas un nombre\" : (v === 0 ? \"vaut 0\" : \"est n\u00e9gative\");\n  return `<div class=\"note volume-invalide\">\n    <b>Volume annuel invalide</b> \u2014 la production annuelle de la r\u00e9f\u00e9rence\n    ${r && r.nom ? \"\u00ab \" + escapeAttr(r.nom) + \" \u00bb \" : \"\"}${cause} (${escapeAttr(String(brut))}).\n    Les gains en \u20ac/an, les heures machine et la consommation annuelle de plaquettes sont\n    d\u00e9sactiv\u00e9s tant qu'elle n'est pas corrig\u00e9e \u2014 ils ne valent pas z\u00e9ro, ils ne sont pas calcul\u00e9s.\n    \u00c0 corriger dans <b>Options</b> \u203a <b>Volume annuel de production</b>.\n  </div>`;\n}\n\nfunction volumeAnnuelHTML(){\n  const v = volumeAnnuel();\n  if(!v) return volumeInvalideHTML();\n  const ref = getActiveReference();\n  return `<div class=\"volume-bandeau clickable\" title=\"Cliquer pour modifier le volume annuel de cette r\u00e9f\u00e9rence (Options, champ pr\u00e9-rempli pour LA r\u00e9f\u00e9rence affich\u00e9e)\">\n    <span class=\"vb-l\">Production annuelle${ref && ref.nom ? \" \u2014 \" + escapeAttr(ref.nom) : \"\"}</span>\n    <span class=\"vb-v\">${fmt(v,0)}<small>disques / an</small></span>\n    <span class=\"vb-edit\">\u270e modifier</span>\n  </div>`;\n}\n\n/* consommation annuelle de plaquettes : la meme donnee lue depuis l'approvisionnement.\n   Visible des que le volume annuel de la reference est renseigne. */\nfunction consommationAnnuelleHTML(sc){\n  const an = bilanAnnuel(sc);\n  if(!an || !an.plaquettes || !an.plaquettes.length) return \"\";\n  const items = an.plaquettes.map(p =>\n    `<span class=\"conso-item\"><b>${fmt(p.nb,0)}</b> plaquettes/an<em>${escapeAttr(p.outilNumero||\"\u2014\")} \u00b7 ${escapeAttr(p.logementNom||\"\u2014\")}${p.ref ? \" \u2014 \" + escapeAttr(p.ref) : \"\"}</em></span>`).join(\"\");\n  return `<div class=\"conso-strip\">\n    <span class=\"conso-lab\">Consommation annuelle</span>\n    <div class=\"conso-items\">${items}</div>\n    <span class=\"conso-vol\">sur ${fmt(an.volume,0)} disques/an</span>\n  </div>`;\n}\n\n/* pieces detachees : un bloc par porte-outil, visible seulement si le module est actif.\n   Meme amortissement que les plaquettes, sur la charniere de remplacement de chaque piece. */\nfunction piecesDetacheesHTML(sc, interactive){\n  if(!config.piecesActif || !(sc.outils||[]).length) return \"\";\n  const blocs = sc.outils.map((o, oi) => {\n    const couleur = OUTIL_COLORS[oi % OUTIL_COLORS.length];\n    const pieces = o.pieces || [];\n    const rows = pieces.map(p => {\n      const c = pieceCost(p);\n      if(!interactive){\n        return `<tr>\n          <td>${escapeAttr(p.nom)}</td><td>${escapeAttr(p.ref)}</td>\n          <td class=\"num\">${p.prix === \"\" || p.prix == null ? \"\u2014\" : fmt(parseFloat(p.prix),2)}</td>\n          <td class=\"num\">${p.charniere === \"\" || p.charniere == null ? \"\u2014\" : fmt(parseFloat(p.charniere),0)}</td>\n          <td class=\"computed\">${c === null ? \"\u2014\" : fmt(c,5)}</td>\n        </tr>`;\n      }\n      const attrs = `data-id=\"${sc.id}\" data-outil=\"${o.id}\" data-piece=\"${p.id}\"`;\n      return `<tr>\n        <td><input class=\"cell ref\" ${attrs} data-field=\"nom\" value=\"${escapeAttr(p.nom)}\" placeholder=\"Cale, vis, corps d'outil\u2026\"></td>\n        <td><input class=\"cell ref\" ${attrs} data-field=\"ref\" value=\"${escapeAttr(p.ref)}\" placeholder=\"R\u00e9f\u00e9rence\"></td>\n        <td class=\"num\"><input class=\"cell\" ${attrs} data-field=\"prix\" type=\"number\" step=\"1\" min=\"0\" value=\"${p.prix ?? \"\"}\"></td>\n        <td class=\"num\"><input class=\"cell\" ${attrs} data-field=\"charniere\" type=\"number\" step=\"500\" min=\"0\" value=\"${p.charniere ?? \"\"}\"></td>\n        <td class=\"computed\">${c === null ? \"\u2014\" : fmt(c,5)}</td>\n        <td><button class=\"log-del piece-del\" data-id=\"${sc.id}\" data-outil=\"${o.id}\" data-piece=\"${p.id}\" title=\"Supprimer\">\u2715</button></td>\n      </tr>`;\n    }).join(\"\");\n    const total = (pieces.map(pieceCost).filter(v => v !== null).reduce((a,b)=>a+b,0)) || 0;\n    return `\n      <div class=\"pieces-outil\" style=\"border-left:4px solid ${couleur};\">\n        <div class=\"pieces-head\">\n          <span class=\"pieces-outil-nom\">${escapeAttr(o.numero || \"Outil sans n\u00b0\")}</span>\n          ${pieces.length ? `<span class=\"pieces-total\">${fmt(total,5)} \u20ac/pi\u00e8ce</span>` : `<span class=\"pieces-vide\">aucune pi\u00e8ce d\u00e9tach\u00e9e d\u00e9clar\u00e9e</span>`}\n        </div>\n        ${pieces.length ? `\n        <div class=\"tbl-wrap\">\n          <table class=\"pieces-table\">\n            <thead><tr><th>D\u00e9signation</th><th>R\u00e9f\u00e9rence</th><th class=\"num\">Prix (\u20ac)</th><th class=\"num\">Charni\u00e8re (pi\u00e8ces)</th><th class=\"num\">\u20ac / pi\u00e8ce</th>${interactive?\"<th></th>\":\"\"}</tr></thead>\n            <tbody>${rows}</tbody>\n          </table>\n        </div>` : \"\"}\n        ${interactive ? `<button class=\"ghost small piece-add\" data-id=\"${sc.id}\" data-outil=\"${o.id}\">+ Pi\u00e8ce d\u00e9tach\u00e9e pour ${escapeAttr(o.numero || \"cet outil\")}</button>` : \"\"}\n      </div>`;\n  }).join(\"\");\n  const totalSc = coutPiecesDetachees(sc);\n  return `\n    <div class=\"pieces-block\">\n      <h4 class=\"pieces-titre\">Pi\u00e8ces d\u00e9tach\u00e9es par porte-outil${totalSc !== null ? ` <span class=\"pieces-cumul\">${fmt(totalSc,5)} \u20ac/pi\u00e8ce au total</span>` : \"\"}</h4>\n      <p class=\"panel-hint\" style=\"margin:2px 2px 10px;\">Amorties sur leur charni\u00e8re de remplacement, comme les plaquettes. Comptez la pi\u00e8ce autant de fois qu'elle est mont\u00e9e sur l'outil.</p>\n      ${blocs}\n    </div>`;\n}\n\nfunction outilRowsHTML(sc, o, oi, showFrFa, showCycleDetail){\n  const couleur = OUTIL_COLORS[oi % OUTIL_COLORS.length];\n  return o.logements.map(l => logementRowHTML(sc, o, l, couleur, showFrFa, showCycleDetail)).join(\"\");\n}\n/* duree de vie observee, affichee sous la charniere visee : \"\u2265 150\" tant qu'aucun essai\n   n'est sorti de tolerance (on ne pousse jamais au-dela de la cible, donc on ne sait pas),\n   une valeur ferme des qu'un essai a lache avant. */\nfunction charniereSubHTML(sc, l){\n  const info = charniereReelle(sc, l.id);\n  if(!info) return \"\";\n  const cible = parseFloat(l.charniere);\n  const sous = !isNaN(cible) && !info.borneInf && info.moyenne < cible - 0.5;\n  const titre = info.borneInf\n    ? \"Aucun essai n'est sorti de tol\u00e9rance : la dur\u00e9e de vie tenue est au moins celle-ci. Les essais s'arr\u00eatent \u00e0 la charni\u00e8re vis\u00e9e, on ne sait pas ce qu'il y a au-del\u00e0.\"\n    : \"Moyenne du dernier pr\u00e9l\u00e8vement conforme avant sortie de tol\u00e9rance.\";\n  return `<div class=\"charniere-reel ${sous ? \"bad\" : \"ok\"}\" title=\"${titre}\">${info.borneInf ? \"\u2265 \" : \"\"}${fmt(info.moyenne,0)} r\u00e9el <span>(${info.essais})</span></div>`;\n}\n\n/* ============================================================================\n   COMPOSITION DU SCENARIO \u2014 vue de saisie (v3.17)\n   Ce bloc etait un tableau de 15 colonnes rendu en 11 px, avec table-layout:fixed et des\n   largeurs en pourcentage : la colonne \"N\u00b0 outil\" recevait 6 % de 920 px, soit ~55 px, pour\n   y empiler TROIS champs (numero, correcteur, \"Foret carbure monobloc a goujure droite\").\n   Resultat : tout etait tronque, et personne ne pouvait relire ce qu'il avait saisi.\n   Le fond du probleme n'est pas la largeur, c'est la nature de l'objet : 15 colonnes pour\n   2 a 4 lignes, ce n'est pas un tableau, c'est un formulaire deguise. On le rend donc comme\n   un formulaire \u2014 une fiche par outil, un bloc par logement, chaque champ avec son libelle\n   au-dessus et une largeur adaptee a ce qu'il recoit. Le tableau, lui, reste tel quel pour\n   l'impression et le rapport client, ou la compacite a un sens et ou rien n'est saisissable.\n   ============================================================================ */\nfunction champHTML(label, inputHTML, cls, aide){\n  return `<div class=\"oc-champ ${cls||\"\"}\">\n    <label${aide ? ` title=\"${escapeAttr(aide)}\"` : \"\"}>${label}</label>\n    ${inputHTML}\n  </div>`;\n}\n\nfunction logementBlocHTML(sc, o, l, showFrFa, showCycleDetail){\n  const perEdge = posCostPerEdge(l), perPiece = posCost(l);\n  const base = (field, extra) => `data-id=\"${sc.id}\" data-outil=\"${o.id}\" data-logement=\"${l.id}\" data-field=\"${field}\" ${extra||\"\"}`;\n  const num = (field, label, step, attrs, aide) => champHTML(label,\n    `<input class=\"cell\" ${base(field)} type=\"number\" step=\"${step}\" ${attrs||\"\"} value=\"${l[field] ?? \"\"}\">`, \"oc-num\", aide);\n\n  const coupe = [\n    num(\"vc\", \"Vc <span>m/min</span>\", \"10\"),\n    num(\"f\", \"f <span>mm/tr</span>\", \"0.01\"),\n    num(\"kappaR\", \"\u03bar <span>\u00b0</span>\", \"1\", 'min=\"0\" max=\"90\"', \"Angle de direction d'ar\u00eate : alimente le rapport Fr/Fa et le suivi thermique.\"),\n    showFrFa ? num(\"rayonBec\", \"r\u03b5 <span>mm</span>\", \"0.1\", 'min=\"0\"', \"Rayon de bec \u2014 affine le \u03bar effectif quand la coupe se fait sur le bec.\") : \"\",\n    showFrFa ? num(\"apPiste\", \"ap <span>mm</span>\", \"0.1\", 'min=\"0\"', \"Profondeur de passe \u2014 affine le \u03bar effectif.\") : \"\",\n    num(\"tempsCoupe\", \"Temps de coupe <span>s</span>\", \"0.1\", 'min=\"0\"')\n  ].filter(Boolean).join(\"\");\n\n  return `\n    <div class=\"logement-bloc\">\n      <div class=\"lb-tete\">\n        ${champHTML(\"Logement\", `<input class=\"cell ref\" ${base(\"nom\")} value=\"${escapeAttr(l.nom)}\" placeholder=\"D1, D2, Bol, Piste\u2026\" title=\"La position de la plaquette sur le porte-outil : D1, D2\u2026 (le vocabulaire du classeur de Matis), ou un nom fonctionnel (Bol, Piste).\">`, \"oc-moyen\")}\n        ${champHTML(\"R\u00e9f\u00e9rence plaquette\", `<input class=\"cell ref\" ${base(\"ref\")} value=\"${escapeAttr(l.ref)}\" placeholder=\"CNGX 120716 T02020 LKT640\">`, \"oc-large\")}\n        ${champHTML(\"MABEC <span>code article</span>\", `<input class=\"cell ref\" ${base(\"codeArticle\")} value=\"${escapeAttr(l.codeArticle)}\" placeholder=\"ex. IM02 209 560\" title=\"Le num\u00e9ro d'article du classeur de Matis (colonne MABEC). C'est lui qui relie le suivi au classeur : saisis-le tel quel.\">`, \"oc-moyen\")}\n        <label class=\"lb-tol\" title=\"D\u00e9coch\u00e9, ce logement ne suit que la charni\u00e8re : ses mesures ne font jamais \u00e9chouer un essai sur la tol\u00e9rance.\">\n          <input type=\"checkbox\" data-outil=\"${o.id}\" data-logement=\"${l.id}\" data-field=\"suiviTolerance\" ${l.suiviTolerance !== false ? \"checked\" : \"\"}>\n          <span>Suivi en tol\u00e9rance</span>\n        </label>\n        <button class=\"log-del logement-del\" data-id=\"${sc.id}\" data-outil=\"${o.id}\" data-logement=\"${l.id}\" title=\"Supprimer ce logement\">\u2715</button>\n      </div>\n      <div class=\"lb-groupes\">\n        <div class=\"lb-groupe\">\n          <div class=\"lb-legende\">Plaquette</div>\n          <div class=\"lb-champs\">\n            ${num(\"prix\", \"Prix <span>\u20ac</span>\", \"0.5\")}\n            ${num(\"aretes\", \"Ar\u00eates\", \"1\")}\n            ${champHTML(\"Charni\u00e8re <span>p/ar\u00eate</span>\",\n              `<input class=\"cell\" ${base(\"charniere\")} type=\"number\" step=\"1\" value=\"${l.charniere ?? \"\"}\">${charniereSubHTML(sc, l)}`, \"oc-num\")}\n          </div>\n        </div>\n        <div class=\"lb-groupe\">\n          <div class=\"lb-legende\">Conditions de coupe</div>\n          <div class=\"lb-champs\">${coupe}</div>\n        </div>\n        <div class=\"lb-groupe lb-resultats\">\n          <div class=\"lb-legende\">Co\u00fbt</div>\n          <div class=\"lb-champs\">\n            <div class=\"oc-champ oc-num\"><label>\u20ac / ar\u00eate</label><div class=\"oc-calc\">${perEdge === null ? \"\u2014\" : fmt(perEdge,3)}</div></div>\n            <div class=\"oc-champ oc-num\"><label>\u20ac / pi\u00e8ce</label><div class=\"oc-calc\">${perPiece === null ? \"\u2014\" : fmt(perPiece,4)}</div></div>\n          </div>\n        </div>\n      </div>\n    </div>`;\n}\n\n/* ---- APERCU DE LA COMPOSITION (v3.18) -------------------------------------------------\n   Le \"premier coup d'oeil\" tenait dans une ligne de resume en 11 px mono, gris clair, qui\n   concatenait toutes les plaquettes bout a bout. Cette ligne essayait d'etre deux choses a\n   la fois : l'etiquette d'un volet repliable ET la vue d'ensemble du scenario. Elle etait\n   dimensionnee comme une note de bas de page et lue comme un tableau de bord.\n   L'apercu prend donc son propre bloc, toujours visible (volet ouvert ou ferme) : une tuile\n   par logement, avec ce qu'on va vraiment chercher du regard \u2014 quelle plaquette, quelle\n   duree de vie, a quelles conditions, pour combien. Ce qui manque est signale ici plutot\n   que decouvert plus tard dans un calcul qui ne tombe pas. */\nfunction apercuLogementHTML(sc, o, l, couleur, oi, volume, totalAnnuel, partRef){\n  const pc = posCost(l);\n  // Deux causes distinctes a un cout qui ne tombe pas, et il faut les nommer separement :\n  // une case vide (on n'a pas encore saisi) et une valeur saisie mais inexploitable (0 arete,\n  // charniere a 0). Le second cas est le plus traitre : la tuile affichait \"Co\u00fbt \u2014\" alors que\n  // la cause etait juste a cote, lisible, sans que rien ne fasse le lien.\n  const manque = [];\n  if(!l.ref) manque.push(\"r\u00e9f\u00e9rence\");\n  if(l.prix === \"\" || l.prix == null) manque.push(\"prix\");\n  if(l.aretes === \"\" || l.aretes == null) manque.push(\"ar\u00eates\");\n  if(l.charniere === \"\" || l.charniere == null) manque.push(\"charni\u00e8re\");\n  const bloquant = [];\n  const nb = v => { const x = parseFloat(v); return isNaN(x) ? null : x; };\n  if(nb(l.aretes) !== null && nb(l.aretes) <= 0) bloquant.push(\"nombre d'ar\u00eates \u00e0 \" + l.aretes);\n  if(nb(l.charniere) !== null && nb(l.charniere) <= 0) bloquant.push(\"charni\u00e8re \u00e0 \" + l.charniere);\n  if(nb(l.prix) !== null && nb(l.prix) < 0) bloquant.push(\"prix n\u00e9gatif\");\n  const cond = [\n    l.vc !== \"\" && l.vc != null ? \"Vc \" + l.vc : null,\n    l.f !== \"\" && l.f != null ? \"f \" + fmt(parseFloat(l.f),2) : null,\n    l.kappaR !== \"\" && l.kappaR != null ? \"\u03bar \" + l.kappaR + \"\u00b0\" : null\n  ].filter(Boolean).join(\" \u00b7 \");\n  const reel = charniereReelle(sc, l.id);\n  // co\u00fbt annuel du logement (v4.19) : seulement si co\u00fbt pi\u00e8ce ET production annuelle connus\n  const annuel = (pc !== null && volume > 0) ? pc * volume : null;\n  const part = (annuel !== null && totalAnnuel > 0) ? annuel / totalAnnuel : null;\n  const ratio = (part !== null && partRef > 0) ? part / partRef : null;\n  const couleurAnnuelle = ratio === null ? null : couleurPartCout(ratio);\n  const pctPart = part === null ? null : Math.round(part * 100);\n  /* v4.28 \u2014 le d\u00e9tail du calcul, d\u00e9pliable au clic sur la tuile (choix : d\u00e9ploiement\n     plut\u00f4t qu'infobulle, lisible au doigt et copiable). Chaque ligne reprend une\n     op\u00e9ration avec SES chiffres : prix, dur\u00e9e de vie, co\u00fbt pi\u00e8ce, production, plaquettes\n     par an, co\u00fbt annuel. L'\u00e9tat ouvert survit aux re-rendus (Set, comme les fiches). */\n  const cleDetail = sc.id + \"|\" + l.id;\n  const detailOuvert = apDetailsOuverts.has(cleDetail);\n  const detailCalc = annuel !== null ? (() => {\n    const prix = parseFloat(l.prix), aretes = parseFloat(l.aretes), charn = parseFloat(l.charniere);\n    return `\n      <div class=\"ap-detail-l\"><span>Prix plaquette</span><b>${fmt(prix,2)} \u20ac</b></div>\n      <div class=\"ap-detail-l\"><span>Dur\u00e9e de vie vis\u00e9e</span><b>${aretes} ar\u00eates \u00d7 ${fmt(charn,0)} p/ar\u00eate</b></div>\n      <div class=\"ap-detail-l\"><span>Co\u00fbt pi\u00e8ce = prix \u00f7 (ar\u00eates \u00d7 charni\u00e8re)</span><b>${fmt(prix,2)} \u00f7 (${aretes} \u00d7 ${fmt(charn,0)}) = ${fmt(pc,4)} \u20ac</b></div>\n      <div class=\"ap-detail-l\"><span>Production annuelle</span><b>${fmt(volume,0)} disques</b></div>\n      <div class=\"ap-detail-l\"><span>Plaquettes consomm\u00e9es / an</span><b>\u2248 ${fmt(volume / (aretes * charn),0)}</b></div>\n      <div class=\"ap-detail-l ap-detail-total\"><span>Co\u00fbt annuel = co\u00fbt pi\u00e8ce \u00d7 production</span><b>${fmt(pc,4)} \u00d7 ${fmt(volume,0)} = ${escapeAttr(libelleAnnuel(annuel))}</b></div>`;\n  })() : `\n      <div class=\"ap-detail-l\"><span>Co\u00fbt annuel non calculable</span><b>${\n        volume > 0 ? \"co\u00fbt pi\u00e8ce indisponible (case manquante ou \u00e0 z\u00e9ro)\" : \"production annuelle non renseign\u00e9e (Options \u203a Volume annuel)\"\n      }</b></div>`;\n  /* v4.39 \u2014 section cycle du d\u00e9pliant : le temps mesur\u00e9 du logement, sa part du cycle\n     (somme ou plus-long selon le mode du sc\u00e9nario) et l'indice conditions vs base (Vc\u00b7f \u2014\n     une estimation, distincte de la mesure). Rappelle aussi pourquoi le sc\u00e9nario ignore\n     \u00e9ventuellement les mesures : elles ne comptent que compl\u00e8tes, jamais un m\u00e9lange. */\n  const coupe = parseFloat(l.tempsCoupe);\n  const stC = cycleDetailStatus(sc, config);\n  const cycPart = (!isNaN(coupe) && stC.complete && stC.secs > 0) ? coupe / stC.secs : null;\n  let indiceCond = null;\n  if(!sc.baseline){\n    const flatsSc = sc.outils.flatMap(o => o.logements||[]);\n    const baseB = baselineScenario();\n    const lb = baseB ? (baseB.outils.flatMap(o => o.logements||[]))[flatsSc.indexOf(l)] : null;\n    if(lb){\n      const vSc = parseFloat(l.vc) * parseFloat(l.f), vB = parseFloat(lb.vc) * parseFloat(lb.f);\n      if(vSc > 0 && vB > 0) indiceCond = vB / vSc * 100;\n    }\n  }\n  const detailCycle = `\n      <div class=\"ap-detail-sep\">Cycle</div>\n      <div class=\"ap-detail-l\"><span>Temps de coupe (mesure machine)</span><b>${isNaN(coupe) ? \"\u2014\" : fmt(coupe,1)+\" s\"}</b></div>\n      ${cycPart !== null ? `<div class=\"ap-detail-l\"><span>Part du cycle \u2014 ${stC.nbGroupes < stC.nbOutils ? stC.nbGroupes + \" groupe\" + (stC.nbGroupes>1?\"s\":\"\") + \" d'outils simultan\u00e9s\" : \"outils en s\u00e9rie\"}</span><b>${fmt(cycPart*100,0)} %</b></div>` : \"\"}\n      ${indiceCond !== null ? `<div class=\"ap-detail-l\"><span>Indice conditions vs base (Vc\u00b7f, 100 = base)</span><b>${fmt(indiceCond,0)}</b></div>` : \"\"}\n      ${!stC.complete ? `<div class=\"ap-detail-l\"><span>Pris en compte dans le cycle</span><b>non \u2014 ${stC.filled}/${stC.total} logements renseign\u00e9s, l'indice global s'applique</b></div>` : \"\"}`;\n  return `\n    <div class=\"ap-tuile${detailOuvert ? \" ouvert\" : \"\"}\" data-cle-detail=\"${escapeAttr(cleDetail)}\" title=\"Cliquer pour d\u00e9plier le d\u00e9tail du calcul${annuel !== null ? \" du co\u00fbt annuel\" : \"\"}\" style=\"--outil-couleur:${couleur};\">\n      <div class=\"ap-tete\">\n        <span class=\"ap-pastille\">${oi + 1}</span>\n        <span class=\"ap-outil\">${escapeAttr(o.numero || \"outil sans n\u00b0\")}</span>\n        <span class=\"ap-sep\">\u00b7</span>\n        <span class=\"ap-logement\">${escapeAttr(l.nom || \"logement sans nom\")}</span>\n        ${l.suiviTolerance === false ? `<span class=\"ap-flag\" title=\"Ce logement ne suit que la charni\u00e8re : ses mesures ne font pas \u00e9chouer un essai sur la tol\u00e9rance.\">charni\u00e8re seule</span>` : \"\"}\n      </div>\n      <div class=\"ap-ref\">${l.ref ? escapeAttr(l.ref) : `<em>r\u00e9f\u00e9rence plaquette non renseign\u00e9e</em>`}</div>\n      <div class=\"ap-chiffres\">\n        <div class=\"ap-c\"><span class=\"ap-l\">Charni\u00e8re</span><span class=\"ap-v\">${l.charniere === \"\" || l.charniere == null ? \"\u2014\" : fmt(parseFloat(l.charniere),0)}<small>p/ar\u00eate</small></span>\n          ${reel ? `<span class=\"ap-reel ${!reel.borneInf && !isNaN(parseFloat(l.charniere)) && reel.moyenne < parseFloat(l.charniere) - 0.5 ? \"bad\" : \"\"}\">${reel.borneInf ? \"\u2265 \" : \"\"}${fmt(reel.moyenne,0)} r\u00e9el</span>` : \"\"}</div>\n        <div class=\"ap-c\"><span class=\"ap-l\">Plaquette</span><span class=\"ap-v\">${l.prix === \"\" || l.prix == null ? \"\u2014\" : fmt(parseFloat(l.prix),2)}<small>\u20ac</small></span>\n          <span class=\"ap-reel\">${l.aretes === \"\" || l.aretes == null ? \"\u2014 ar\u00eate\" : l.aretes + \" ar\u00eates\"}</span></div>\n        <div class=\"ap-c ap-cout\"><span class=\"ap-l\">Co\u00fbt</span><span class=\"ap-v\">${pc === null ? \"\u2014\" : fmt(pc,4)}<small>\u20ac/pi\u00e8ce</small></span>\n          ${annuel !== null ? `<span class=\"ap-annuel\" style=\"color:${couleurAnnuelle};\" title=\"\u2248 ${escapeAttr(libelleAnnuel(annuel))} sur l'ann\u00e9e (${pctPart} % du co\u00fbt outillage) \u2014 la couleur compare la part de ce logement aux autres : vert = mineur, rouge = majeur, \u00e0 cibler en priorit\u00e9.\">${escapeAttr(libelleAnnuel(annuel))}</span>` : \"\"}</div>\n      </div>\n      <div class=\"ap-detail\"${detailOuvert ? \"\" : \" hidden\"}>${detailCalc}${detailCycle}</div>\n      ${cond ? `<div class=\"ap-cond\">${escapeAttr(cond)}</div>` : \"\"}\n      ${manque.length ? `<div class=\"ap-manque\">Manque : ${escapeAttr(manque.join(\", \"))}</div>` : \"\"}\n      ${bloquant.length ? `<div class=\"ap-manque ap-bloquant\" title=\"Le co\u00fbt pi\u00e8ce ne peut pas \u00eatre calcul\u00e9 tant que cette valeur reste telle quelle.\">Co\u00fbt non calculable : ${escapeAttr(bloquant.join(\", \"))}</div>` : \"\"}\n    </div>`;\n}\n\nfunction compositionApercuHTML(sc){\n  // v4.19 \u2014 co\u00fbt annuel par logement : production annuelle de la r\u00e9f\u00e9rence courante.\n  // Le total annuel sert de d\u00e9nominateur aux parts ; la part th\u00e9orique (1/n) \u00e9talonne\n  // la couleur d'un logement face aux autres.\n  const refSc = getActiveReference();\n  const volume = refSc ? parseFloat(refSc.productionAnnuelle) : NaN;\n  const nbLogements = sc.outils.reduce((n, o) => n + o.logements.length, 0);\n  const total = scenarioCost(sc);\n  const totalAnnuelSc = (total !== null && volume > 0) ? total * volume : 0;\n  const partRefSc = nbLogements > 0 ? 1 / nbLogements : 0;\n  /* v4.47 \u2014 les outils d'un m\u00eame groupe simultan\u00e9 sont ENFERM\u00c9S dans un bloc ambre :\n     la disposition dit la physique (ces outils tournent ensemble, seul le plus long\n     compte dans le cycle) au lieu d'un badge discret qu'on ne voit pas. */\n  const groupes = [];\n  let courant = null;\n  sc.outils.forEach((o, oi) => {\n    if(o.simultaneAvecPrecedent && courant) courant.push(oi);\n    else { courant = [oi]; groupes.push(courant); }\n  });\n  const tuileOutil = (o, oi) =>\n    o.logements.map(l => apercuLogementHTML(sc, o, l, OUTIL_COLORS[oi % OUTIL_COLORS.length], oi, volume, totalAnnuelSc, partRefSc));\n  const tuiles = groupes.map(g => {\n    const tuilesG = g.map(oi => tuileOutil(sc.outils[oi], oi));\n    if(g.length === 1) return tuilesG.join(\"\");\n    return `<div class=\"ap-groupe-sim\"><div class=\"ap-gs-tete\">\u21c9 Travail simultan\u00e9 \u2014 ${g.length} outils usinent ensemble, seul le plus long compte dans le cycle</div><div class=\"ap-gs-tuiles\">${tuilesG.join(\"\")}</div></div>`;\n  }).join(\"\");\n  const nbOutils = sc.outils.length;\n  if(!tuiles) return `<div class=\"compo-apercu vide\">Aucun outil configur\u00e9 \u2014 ouvrez \u00ab Modifier la composition \u00bb pour en ajouter un.</div>`;\n  return `\n    <div class=\"compo-apercu\">\n      <div class=\"ap-entete\">\n        <h4>Composition</h4>\n        <span class=\"ap-compte\">${nbOutils} outil${nbOutils>1?\"s\":\"\"} \u00b7 ${nbLogements} logement${nbLogements>1?\"s\":\"\"}</span>\n        <span class=\"ap-total\">${total === null ? \"\u2014\" : fmt(total,4)} <small>\u20ac / pi\u00e8ce, outillage</small></span>\n        ${totalAnnuelSc > 0 ? `<span class=\"ap-total-annuel\">\u2248 ${escapeAttr(libelleAnnuel(totalAnnuelSc))}</span>` : \"\"}\n      </div>\n      <div class=\"ap-grille\">${tuiles}</div>\n    </div>`;\n}\n\n/* ---- PIECES JOINTES : une seule regle, appliquee partout (v3.19) ---------------------\n   Un PDF de plan ou de fiche outil pese couramment 1 a 2 Mo. localStorage plafonne autour de\n   5 Mo pour L'INTEGRALITE du suivi (mesures comprises) : deux pieces jointes integrees au\n   fichier suffisent a le saturer, et une sauvegarde qui echoue bloque l'enregistrement des\n   MESURES \u2014 on perdrait des relev\u00e9s a cause d'un plan. D'ou la regle unique :\n     1. dossier local connecte  -> le fichier y est ecrit, seul son nom voyage dans le JSON ;\n     2. sinon, sous 500 ko      -> integre au fichier de suivi (base64), ca reste raisonnable ;\n     3. sinon                   -> refus explique, avec le chemin pour connecter le dossier.\n   Renvoie le descriptif a stocker, ou null si l'utilisateur doit d'abord agir. */\nconst PJ_MAX_SANS_DOSSIER = 500 * 1024;\n\nasync function attacherPieceJointe(file, prefixe){\n  const ext = (file.name.match(/\\.[a-z0-9]+$/i) || [\"\"])[0].toLowerCase();\n  const mime = file.type || (ext === \".pdf\" ? \"application/pdf\" : \"application/octet-stream\");\n  if(photosDirHandle){\n    try{\n      const nom = prefixe + \"_\" + Date.now() + ext;\n      await writePhotoBlob(nom, file);\n      return { filename: nom, nomOrigine: file.name, mime, addedAt: new Date().toISOString(), stockage: \"dossier\" };\n    }catch(err){\n      dialogueAlerte(\"\u00c9chec de l'enregistrement dans le dossier local : \" + err.message, \"\u00c9chec d'enregistrement\");\n      return null;\n    }\n  }\n  if(file.size > PJ_MAX_SANS_DOSSIER){\n    dialogueAlerte(`Ce fichier p\u00e8se ${Math.round(file.size/1024)} ko.\n\nSans dossier local connect\u00e9, il devrait \u00eatre int\u00e9gr\u00e9 au fichier de suivi, dont la capacit\u00e9 totale est d'environ 5 Mo pour TOUT le suivi, mesures comprises. Deux pi\u00e8ces jointes de cette taille suffiraient \u00e0 le saturer \u2014 et une sauvegarde qui \u00e9choue bloque l'enregistrement de vos relev\u00e9s. On ne perd pas des mesures \u00e0 cause d'un plan.\n\nConnectez le dossier local (menu \u2022\u2022\u2022 \u2192 Dossier photos) : le fichier y sera enregistr\u00e9 \u00e0 part, sans limite g\u00eanante. Ou joignez une version all\u00e9g\u00e9e (moins de 500 ko).`);\n    return null;\n  }\n  return await new Promise(resolve => {\n    const reader = new FileReader();\n    reader.onload = () => resolve({ filename: file.name, mime, addedAt: new Date().toISOString(), stockage: \"fichier\", dataUrl: reader.result });\n    reader.onerror = () => { dialogueAlerte(\"Lecture du fichier impossible.\", \"Lecture impossible\"); resolve(null); };\n    reader.readAsDataURL(file);\n  });\n}\n\n/* ouvre une piece jointe quel que soit son mode de stockage.\n   Pi\u00e8ge historique : window.open(\"data:...\") est bloqu\u00e9 par Chrome/Edge (navigation\n   top-level vers une data: URL) \u2014 un PDF int\u00e9gr\u00e9 ne s'ouvrait donc jamais. Les images\n   passent par la lightbox ; les documents sont convertis en Blob/ObjectURL (autoris\u00e9),\n   r\u00e9voqu\u00e9 une minute plus tard, le temps que le lecteur du navigateur l'ait charg\u00e9. */\nasync function ouvrirPieceJointe(pj){\n  if(!pj) return;\n  if(pj.stockage === \"dossier\"){\n    if(!photosDirHandle){ dialogueAlerte(\"Le dossier local n'est pas connect\u00e9 sur ce poste \u2014 reconnectez-le (menu \u2022\u2022\u2022 \u2192 Dossier photos) pour ouvrir ce fichier.\", \"Dossier non connect\u00e9\"); return; }\n    const url = await readPhotoURL(pj.filename);\n    if(!url){ dialogueAlerte(\"Fichier introuvable dans le dossier local : \" + pj.filename, \"Fichier introuvable\"); return; }\n    window.open(url, \"_blank\");\n  } else if((pj.dataUrl || \"\").startsWith(\"data:image/\")){\n    ouvrirLightbox(pj.dataUrl);\n  } else if(pj.dataUrl){\n    try{\n      const blob = await (await fetch(pj.dataUrl)).blob();\n      const url = URL.createObjectURL(blob);\n      const w = window.open(url, \"_blank\");\n      if(!w) dialogueAlerte(\"Le navigateur a bloqu\u00e9 l'ouverture dans un nouvel onglet. Autorisez les pop-ups pour ce site, ou connectez le dossier local (menu \u2022\u2022\u2022 \u2192 Dossier photos).\", \"Ouverture bloqu\u00e9e\");\n      setTimeout(() => URL.revokeObjectURL(url), 60000);\n    }catch(e){\n      dialogueAlerte(\"Ouverture impossible : \" + e.message, \"Ouverture impossible\");\n    }\n  }\n}\n\n/* plan de l'outil : PDF ou image du montage / de la trajectoire, propre a CET outil.\n   Stockage : dans le dossier local s'il est connecte (un plan pese vite 1 a 2 Mo, et\n   localStorage plafonne autour de 5 Mo pour TOUT le suivi) ; a defaut en base64 dans le\n   fichier, mais seulement en dessous de 500 ko, pour ne pas faire sauter le quota. */\nfunction planOutilHTML(sc, o){\n  const p = o.plan;\n  if(p){\n    const ou = p.stockage === \"dossier\" ? \"dossier local\" : \"int\u00e9gr\u00e9 au fichier de suivi\";\n    return `<div class=\"plan-outil\">\n      <span class=\"plan-icone\">${(p.mime||\"\").startsWith(\"image/\") ? \"\ud83d\uddbc\" : \"\ud83d\udcc4\"}</span>\n      <span class=\"plan-nom\" title=\"${escapeAttr(p.filename)} \u2014 ${ou}\">${escapeAttr(p.filename)}</span>\n      <span class=\"plan-ou\">${ou}</span>\n      <button class=\"ghost small plan-open\" data-id=\"${sc.id}\" data-outil=\"${o.id}\">Ouvrir</button>\n      <button class=\"ghost small plan-del\" data-id=\"${sc.id}\" data-outil=\"${o.id}\">Retirer</button>\n    </div>`;\n  }\n  return `<label class=\"plan-ajout\">\ud83d\udcce Joindre le plan de l'outil <span>(PDF ou image)</span>\n    <input type=\"file\" accept=\".pdf,image/*\" class=\"plan-input\" data-id=\"${sc.id}\" data-outil=\"${o.id}\" hidden>\n  </label>`;\n}\n\n/* ---- v4.19 \u2014 r\u00e9ordonner les outils par glissement de tuile ----\n   L'ordre des fiches \u00e9tait fig\u00e9 \u00e0 l'ordre de cr\u00e9ation. Le glisser-d\u00e9poser r\u00e9ordonne\n   directement le tableau sc.outils : c'est LUI qui fixe l'ordre partout (fiches,\n   tuiles d'aper\u00e7u, pastilles num\u00e9rot\u00e9es), donc un seul geste met tout d'accord.\n   Fonction pure pour \u00eatre test\u00e9e sans DOM. */\nfunction deplacerOutil(sc, srcId, cibleId){\n  const ids = (sc.outils || []).map(o => o.id);\n  const from = ids.indexOf(srcId), to = ids.indexOf(cibleId);\n  if(from < 0 || to < 0 || from === to) return false;\n  sc.outils.splice(to, 0, sc.outils.splice(from, 1)[0]);\n  return true;\n}\n\n/* ---- v4.22 \u2014 copier les outils du sc\u00e9nario de production ----\n   Un nouveau sc\u00e9nario repartait d'un outil vide : tester une variante sur la m\u00eame base\n   obligeait \u00e0 retaper toutes les plaquettes. La copie par s\u00e9lection reprend les outils\n   choisis du sc\u00e9nario de production \u2014 n\u00b0, correcteur, type, logements avec TOUTES leurs\n   donn\u00e9es (r\u00e9f, prix, ar\u00eates, charni\u00e8re, Vc/f, \u03bar, rayon de bec, temps machine), pi\u00e8ces\n   d\u00e9tach\u00e9es \u2014 avec de NOUVEAUX identifiants, donc aucune collision avec les instantan\u00e9s\n   d'essai de la production. Les NOMS restent ceux de la production : m\u00eames positions\n   physiques ; chaque courbe de tendance reste titr\u00e9e par son essai, comparer deux essais\n   reste lisible (d\u00e9cision act\u00e9e avec Benjamin). Les plans joints ne sont pas copi\u00e9s \u2014\n   ce sont des fichiers du sc\u00e9nario d'origine ; se les r\u00e9associer si besoin. */\nfunction copieDepuisPossible(sc){\n  const base = baselineScenario();\n  return !!(base && base.id !== sc.id && (base.outils || []).length);\n}\n/* v4.48 \u2014 le sc\u00e9nario \u00ab Prod actuelle (base excel) \u00bb du m\u00eame OP : la base \u00e9conomique\n   fig\u00e9e, source du compl\u00e9ment d'outils pour les sc\u00e9narios d'essai incomplets. */\nfunction scenarioBaseExcel(sc){\n  return (data || []).find(x => x.id !== sc.id && /base excel/i.test(x.name || \"\")) || null;\n}\n/* v4.48 \u2014 outils de la base excel absents du sc\u00e9nario. Rapprochement par pr\u00e9fixe de\n   num\u00e9ro (T548 \u2194 T548 D1 = le m\u00eame outil : la convention de nommage diff\u00e8re entre les\n   sc\u00e9narios de Matis et l'excel). Un outil d\u00e9j\u00e0 pr\u00e9sent \u00e0 l'essai n'est JAMAIS remplac\u00e9 :\n   ses conditions d'essai font foi ; seuls les manquants seront ajout\u00e9s. */\nfunction outilsManquants(sc){\n  const base = scenarioBaseExcel(sc);\n  if(!base || sc.baseline) return [];\n  const prefixe = n => String(n || \"\").trim().toLowerCase().split(/\\s+/)[0] || \"?\";\n  const dispo = {};\n  (sc.outils || []).forEach(t => { const p = prefixe(t.numero); dispo[p] = (dispo[p] || 0) + 1; });\n  const manquants = [];\n  const restants = Object.assign({}, dispo);\n  (base.outils || []).forEach(t => {\n    const p = prefixe(t.numero);\n    if((restants[p] || 0) > 0){ restants[p]--; return; }\n    manquants.push(t);\n  });\n  return manquants;\n}\n\n/* ---- v4.49 \u2014 le co\u00fbt pi\u00e8ce COMPLET : la pi\u00e8ce n'est pas une OP ------------------------\n   L'outil pense par OP ; l'atelier pense par pi\u00e8ce. Cette agr\u00e9gation somme, pour la\n   r\u00e9f\u00e9rence affich\u00e9e, le CPP de prod (sc\u00e9nario \u00ab base excel \u00bb) de chaque OP, le meilleur\n   sc\u00e9nario d'essai disponible par OP, et le confronte \u00e0 la cible du site (cibleCPP).\n   % de chemin = ce que le meilleur en cours a d\u00e9j\u00e0 parcouru de prod vers la cible. */\n/* v4.51.2 (contrat, d\u00e9cision (a) de Benjamin) \u2014 LE CO\u00dbT MACHINE EXIGE LA LIGNE DU POSTE.\n   coutsDetail(prodSc) sans troisi\u00e8me argument retombe sur getActiveLigne() : ce n\u2019est correct\n   QUE parce que ce module ne s\u2019appelle que sur la r\u00e9f\u00e9rence active. Sur une ligne \u00e0 taux\n   horaire, l\u2019\u00e9cart entre les deux appels mesur\u00e9 vaut x19 (0,7042 \u20ac/pi\u00e8ce contre 0,0375).\n   Donc : pieceCPPComplet() ne s\u2019appelle qu\u2019en contexte r\u00e9f\u00e9rence ouverte ; la carte et\n   l\u2019A4 Mission consomment gainPoste(), qui passe la ligne explicitement. */\nfunction pieceCPPComplet(ref, ligne){\n  /* v4.59 (Q7) \u2014 la r\u00e9f\u00e9rence ET la ligne deviennent des param\u00e8tres explicites,\n     optionnels : sans argument, comportement strictement inchang\u00e9 (r\u00e9f\u00e9rence ouverte,\n     ligne active). C'est la fin de la d\u00e9pendance \u00e0 l'\u00e9tat global pour les appelants\n     qui savent ce qu'ils lisent \u2014 la le\u00e7on de l'\u00e9cart \u00d719 (4.51.1) : un co\u00fbt lu dans\n     le mauvais contexte ne doit plus \u00eatre possible. La ligne est pass\u00e9e \u00e0\n     coutsDetail partout : le co\u00fbt machine est celui du poste, jamais un repli\n     silencieux sur la ligne active. */\n  ref = ref || getActiveReference();\n  if(!ref) return null;\n  const ops = [];\n  ref.ops.forEach(op => {\n    ops.push(dansContexteOp(op, () => {\n      /* v4.49.4 \u2014 le co\u00fbt de prod d'une OP, c'est D'ABORD la prod r\u00e9elle (\u2605), l'excel en\n         repli : apr\u00e8s le merge OP40 (DWG \u2605 qui remplace l'excel), le bandean ne comptait\n         plus l'OP40. Et une OP sans sc\u00e9nario chiffrable (OP20 de Matis, valeurs vides)\n         reste list\u00e9e comme \u00ab non chiffr\u00e9e \u00bb au lieu de dispara\u00eetre \u2014 l'\u00e9cart doit se voir. */\n      const excel = (op.scenarios||[]).find(x => /base excel/i.test(x.name||\"\"));\n      const star = (op.scenarios||[]).find(x => x.baseline);\n      const prodSc = star || excel || null;\n      const tBase = prodSc ? coutsDetail(prodSc, undefined, ligne).total : null;\n      let meilleur = null;\n      (op.scenarios||[]).forEach(sc => {\n        if(prodSc && sc.id === prodSc.id) return;\n        const t = coutsDetail(sc, undefined, ligne).total;\n        if(t === null) return;\n        if(!meilleur || t < meilleur.cout) meilleur = { sc, cout: t };\n      });\n      return { op, prodSc, tBase, meilleur };\n    }));\n  });\n  const connues = ops.filter(o => o.tBase !== null && o.tBase !== undefined);\n  if(!connues.length) return null;\n  const prod = connues.reduce((a,o) => a + o.tBase, 0);\n  const enCours = connues.reduce((a,o) => a + (o.meilleur && o.meilleur.cout < o.tBase ? o.meilleur.cout : o.tBase), 0);\n  const cible = (ref.cibleCPP !== \"\" && ref.cibleCPP != null && !isNaN(parseFloat(ref.cibleCPP))) ? parseFloat(ref.cibleCPP) : null;\n  let chemin = null;\n  if(cible !== null && prod > cible && prod > 0) chemin = Math.max(0, Math.min(100, ((prod - enCours) / (prod - cible)) * 100));\n  return { ref, ops: connues, nonChiffrees: ops.filter(o => o.tBase === null || o.tBase === undefined), prod, enCours, cible, chemin };\n}\n/* statut de progression d'une OP : ce que l'atelier demande \u2014 r\u00e9alis\u00e9 / en cours / rien */\nfunction statutOP(o){\n  const scs = (o.op.scenarios||[]).filter(sc => !/base excel/i.test(sc.name||\"\"));\n  if(scs.some(sc => sc.statut === \"serie\")) return { cls:\"ok\", txt:\"pass\u00e9 en s\u00e9rie\" };\n  if(scs.some(sc => sc.statut === \"valide\")) return { cls:\"ok\", txt:\"valid\u00e9 5\u00d7 \u2014 \u00e0 passer en s\u00e9rie\" };\n  if(scs.some(sc => (sc.essais||[]).length)) return { cls:\"pending\", txt:\"essai en cours\" };\n  return { cls:\"arrete\", txt:\"prod seule\" };\n}\n/* la barre prod \u2192 cible, partag\u00e9e par le bandeau pi\u00e8ce (Zone 1) et la feuille de route */\nfunction barreRouteHTML(p){\n  if(!p) return \"\";\n  const pct = p.chemin === null ? 0 : Math.round(p.chemin);\n  const cibleTxt = p.cible === null ? \"cible non renseign\u00e9e\" : \"cible site : \" + fmt(p.cible,3) + \" \u20ac\";\n  return `<div class=\"route-wrap\">\n    <div class=\"route-track\"><div class=\"route-fill\" style=\"width:${pct}%;\"></div>\n      <span class=\"route-mono\">${fmt(p.prod,3)} \u20ac prod</span>\n      ${p.chemin !== null ? `<span class=\"route-pct\">${pct} % du chemin</span>` : \"\"}\n      <span class=\"route-cible\">${cibleTxt}</span>\n    </div>\n  </div>`;\n}\n/* bandeau Zone 1 : la pi\u00e8ce compl\u00e8te d'un coup d'\u0153il */\nfunction pieceCPPBannerHTML(){\n  const p = pieceCPPComplet();\n  if(!p) return \"\";\n  const chips = p.ops.map(o => {\n    const st = statutOP(o);\n    const delta = o.meilleur && o.meilleur.cout < o.tBase ? ` <em>\u00b7 ${escapeAttr(String(o.meilleur.sc.name).slice(0,26))} \u2212${fmt(o.tBase - o.meilleur.cout,3)} \u20ac</em>` : \"\";\n    return `<span class=\"pcb-op\">${escapeAttr(String(o.op.nom||\"OP\").trim())} <b>${fmt(o.tBase,3)} \u20ac</b>${delta} <i class=\"pcb-st ${st.cls}\">${st.txt}</i></span>`;\n  }).join(\"\");\n  const chipsVides = (p.nonChiffrees || []).map(o =>\n    `<span class=\"pcb-op\" title=\"Aucun sc\u00e9nario de prod chiffrable sur cette OP (outils sans prix ou charni\u00e8re) \u2014 compl\u00e9tez la prod pour qu'elle entre dans le co\u00fbt pi\u00e8ce.\">${escapeAttr(String(o.op.nom||\"OP\").trim())} <b>non chiffr\u00e9e</b> <i class=\"pcb-st pending\">\u00e0 compl\u00e9ter</i></span>`).join(\"\");\n  return `<div class=\"pcb-banner\">\n    <span class=\"pcb-l\">Co\u00fbt pi\u00e8ce complet \u2014 ${escapeAttr(p.ref.nom || \"\")}</span>\n    <div class=\"pcb-ops\">${chips}${chipsVides}</div>\n    <span class=\"pcb-total\">${fmt(p.prod,3)} \u20ac<small>/pi\u00e8ce toutes OP</small></span>\n    ${p.enCours < p.prod ? `<span class=\"pcb-encours\">meilleur en cours : ${fmt(p.enCours,3)} \u20ac (\u2212${fmt(p.prod - p.enCours,3)} \u20ac)</span>` : \"\"}\n    ${barreRouteHTML(p)}\n  </div>`;\n}\n/* feuille de route dans la vue de synth\u00e8se : global, par OP, statuts */\nfunction feuilleRouteHTML(){\n  const p = pieceCPPComplet();\n  if(!p) return `<div class=\"synthese-block\"><h3>Feuille de route \u2014 co\u00fbt pi\u00e8ce complet</h3><p class=\"chart-empty\">Aucune OP de cette r\u00e9f\u00e9rence n'a de sc\u00e9nario \u00ab base excel \u00bb chiffrable.</p></div>`;\n  const vol = parseFloat(p.ref.productionAnnuelle);\n  const rows = p.ops.map(o => {\n    const st = statutOP(o);\n    const essaiTxt = o.meilleur\n      ? `${escapeAttr(o.meilleur.sc.name)} \u2014 <b>${fmt(o.meilleur.cout,3)} \u20ac</b> (\u2212${fmt(o.tBase - o.meilleur.cout,3)} \u20ac/pi\u00e8ce${!isNaN(vol) && vol > 0 ? \" \u00b7 \" + escapeAttr(libelleAnnuel((o.tBase - o.meilleur.cout) * vol)) + \"/an\" : \"\"})`\n      : \"aucun essai \u2014 prod seule\";\n    return `<div class=\"fr-row\">\n      <span class=\"fr-op\">${escapeAttr(String(o.op.nom||\"OP\").trim())}</span>\n      <span class=\"fr-prod\">prod ${fmt(o.tBase,3)} \u20ac</span>\n      <span class=\"fr-essai\">${essaiTxt}</span>\n      <span class=\"pcb-st ${st.cls}\">${st.txt}</span>\n    </div>`;\n  }).join(\"\") + (p.nonChiffrees || []).map(o =>\n    `<div class=\"fr-row\">\n      <span class=\"fr-op\">${escapeAttr(String(o.op.nom||\"OP\").trim())}</span>\n      <span class=\"fr-prod\">prod \u2014 \u20ac</span>\n      <span class=\"fr-essai\">non chiffr\u00e9e : aucun sc\u00e9nario de prod chiffrable (outils sans prix ou charni\u00e8re) \u2014 compl\u00e9tez la prod</span>\n      <span class=\"pcb-st pending\">\u00e0 compl\u00e9ter</span>\n    </div>`).join(\"\");\n  return `<div class=\"synthese-block\">\n    <h3>Feuille de route \u2014 co\u00fbt pi\u00e8ce complet vs cible</h3>\n    <div class=\"fr-global\">\n      <div class=\"fr-chiffres\">\n        <span><b>${fmt(p.prod,3)} \u20ac</b> prod (somme des OP)</span>\n        ${p.enCours < p.prod ? `<span><b>${fmt(p.enCours,3)} \u20ac</b> meilleur en cours</span>` : \"\"}\n        ${p.cible !== null ? `<span><b>${fmt(p.cible,3)} \u20ac</b> cible site</span>` : `<span>cible non renseign\u00e9e</span>`}\n        ${p.chemin !== null && !isNaN(vol) && vol > 0 ? `<span class=\"fr-gain\">gain disponible aujourd'hui : ${escapeAttr(libelleAnnuel((p.prod - p.enCours) * vol))}/an</span>` : \"\"}\n      </div>\n      ${barreRouteHTML(p)}\n    </div>\n    <div class=\"fr-rows\">${rows}</div>\n  </div>`;\n}\nfunction copierOutilsDeProduction(sc, ids){\n  const base = baselineScenario();\n  if(!base) return 0;\n  let n = 0;\n  ids.forEach(idO => {\n    const src = base.outils.find(o => o.id === idO);\n    if(!src) return;\n    const copie = JSON.parse(JSON.stringify(src));\n    copie.id = \"t\"+Math.random().toString(36).slice(2);\n    copie.plan = null;\n    copie.logements = (copie.logements || []).map(l => Object.assign(l, { id: \"g\"+Math.random().toString(36).slice(2) }));\n    copie.pieces = (copie.pieces || []).map(p => Object.assign(p, { id: \"pc\"+Math.random().toString(36).slice(2) }));\n    sc.outils.push(copie);\n    n++;\n  });\n  return n;\n}\n\nfunction outilCarteHTML(sc, o, oi, showFrFa, showCycleDetail){\n  const couleur = OUTIL_COLORS[oi % OUTIL_COLORS.length];\n  const base = (field) => `data-id=\"${sc.id}\" data-outil=\"${o.id}\" data-field=\"${field}\"`;\n  const cle = sc.id + \"|\" + o.id;\n  const coutOutil = o.logements.reduce((a, l) => { const c = posCost(l); return c === null ? a : a + c; }, 0);\n  const aDesCouts = o.logements.some(l => posCost(l) !== null);\n  return `\n    <details class=\"outil-carte\"${outilsOuverts.has(cle) ? \" open\" : \"\"} data-outil-id=\"${o.id}\" style=\"--outil-couleur:${couleur};\">\n      <summary class=\"outil-sommaire\">\n        <span class=\"os-grip\" title=\"Glisser pour d\u00e9placer cet outil dans l'ordre\">\u283f</span>\n        <span class=\"outil-pastille\">${oi + 1}</span>\n        <span class=\"os-numero\">${escapeAttr(o.numero || \"Outil sans n\u00b0\")}</span>\n        ${o.correcteur ? `<span class=\"os-corr\" title=\"Correcteur\">${escapeAttr(o.correcteur)}</span>` : \"\"}\n        <span class=\"os-desc\">${escapeAttr(o.description || \"\")}</span>\n        <span class=\"os-logements\">${o.logements.map(l => escapeAttr(l.nom || \"\u2014\")).join(\" + \") || \"aucun logement\"}</span>\n        ${oi > 0 && o.simultaneAvecPrecedent ? `<span class=\"os-sim\" title=\"Cet outil usine en m\u00eame temps que le pr\u00e9c\u00e9dent \u2014 leurs temps ne s'additionnent pas, le groupe vaut le plus long.\">\u21c9 simultan\u00e9</span>` : \"\"}\n        ${o.plan ? `<span class=\"os-plan\" title=\"Un plan est joint \u00e0 cet outil\">${(o.plan.mime||\"\").startsWith(\"image/\") ? \"\ud83d\uddbc\" : \"\ud83d\udcc4\"} plan</span>` : \"\"}\n        ${aDesCouts ? `<span class=\"os-cout\">${fmt(coutOutil,4)} <small>\u20ac/pi\u00e8ce</small></span>` : \"\"}\n      </summary>\n      <div class=\"outil-corps\">\n        ${oi > 0 ? `<label class=\"oc-simultane\" title=\"Coche cette case si cet outil usine en m\u00eame temps que \u00ab ${escapeAttr((sc.outils[oi-1]||{}).numero || \"l'outil pr\u00e9c\u00e9dent\")} \u00bb (\u00e9bauche et finition piste sur deux stations, par exemple) : leurs temps ne s'additionnent pas, le groupe d'outils simultan\u00e9s vaut le temps du plus long. D\u00e9coch\u00e9e, l'outil encha\u00eene apr\u00e8s les autres.\">\n          <input type=\"checkbox\" data-id=\"${sc.id}\" data-outil=\"${o.id}\" data-ofield=\"simultaneAvecPrecedent\" ${o.simultaneAvecPrecedent ? \"checked\" : \"\"}>\n          \u21c9 Tourne en simultan\u00e9 avec l'outil pr\u00e9c\u00e9dent (${escapeAttr((sc.outils[oi-1]||{}).numero || \"sans n\u00b0\")})\n        </label>` : \"\"}\n        <div class=\"outil-tete\">\n          ${champHTML(\"N\u00b0 outil\", `<input class=\"cell ref\" ${base(\"numero\")} value=\"${escapeAttr(o.numero)}\" placeholder=\"T517\" title=\"Le num\u00e9ro du PORTE-OUTIL (T517), pas d'une position : les positions D1/D2 se saisissent comme logements dessous.\">`, \"oc-moyen\")}\n          ${champHTML(\"Correcteur\", `<input class=\"cell ref\" ${base(\"correcteur\")} value=\"${escapeAttr(o.correcteur)}\" placeholder=\"\u2014\" title=\"Correcteur de CET outil quand il n'en a qu'un (foret, mono-position). Pour un porte-outil \u00e0 plusieurs positions (T517 D1/D2), saisis plut\u00f4t un logement par position : D1, D2\u2026\">`, \"oc-court\")}\n          ${champHTML(\"Type d'outil\", `<input class=\"cell ref\" ${base(\"description\")} value=\"${escapeAttr(o.description)}\" placeholder=\"ex. foret carbure monobloc \u00e0 goujure droite\">`, \"oc-large\")}\n        </div>\n        ${planOutilHTML(sc, o)}\n        ${o.logements.map(l => logementBlocHTML(sc, o, l, showFrFa, showCycleDetail)).join(\"\")}\n        <button class=\"ghost small logement-add\" data-id=\"${sc.id}\" data-outil=\"${o.id}\">+ Logement pour ${escapeAttr(o.numero || \"cet outil\")}</button>\n      </div>\n    </details>`;\n}\n\n/* Rendu tableau : desormais reserve a l'impression et au rapport client. La saisie a l'ecran\n   passe par outilCarteHTML/logementBlocHTML (fiches) \u2014 la branche interactive de cette\n   fonction a ete supprimee avec elle plutot que laissee en double entretien. */\nfunction logementRowHTML(sc, o, l, couleur, showFrFa, showCycleDetail){\n  const perEdge = posCostPerEdge(l);\n  const perPiece = posCost(l);\n  return `\n    <tr class=\"pos-row\" style=\"border-left:4px solid ${couleur};\">\n      <td>${escapeAttr(o.numero)}${o.correcteur ? `<br><span class=\"ref-sub-print\">Correcteur : ${escapeAttr(o.correcteur)}</span>` : \"\"}${o.description ? `<br><span class=\"ref-sub-print\">${escapeAttr(o.description)}</span>` : \"\"}</td>\n      <td>${escapeAttr(l.nom)}</td>\n      <td>${escapeAttr(l.ref)}${l.codeArticle ? `<br><span class=\"ref-sub-print\">MABEC : ${escapeAttr(l.codeArticle)}</span>` : \"\"}</td>\n      <td class=\"num\">${l.prix === \"\" ? \"\u2014\" : l.prix ?? \"\u2014\"}</td>\n      <td class=\"num\">${l.aretes === \"\" ? \"\u2014\" : l.aretes ?? \"\u2014\"}</td>\n      <td class=\"num\">${l.charniere === \"\" ? \"\u2014\" : l.charniere ?? \"\u2014\"}${charniereSubHTML(sc, l)}</td>\n      <td style=\"font-size:11px;\">${l.suiviTolerance !== false ? \"Charni\u00e8re + tol\u00e9rance\" : \"Charni\u00e8re seule\"}</td>\n      <td class=\"num\">${l.vc === \"\" ? \"\u2014\" : l.vc ?? \"\u2014\"}</td>\n      <td class=\"num\">${l.f === \"\" ? \"\u2014\" : l.f ?? \"\u2014\"}</td>\n      <td class=\"num\">${l.kappaR === \"\" || l.kappaR == null ? \"\u2014\" : l.kappaR}</td>\n      ${showFrFa ? `\n      <td class=\"num\">${l.rayonBec === \"\" || l.rayonBec == null ? \"\u2014\" : l.rayonBec}</td>\n      <td class=\"num\">${l.apPiste === \"\" || l.apPiste == null ? \"\u2014\" : l.apPiste}</td>` : \"\"}\n      ${showCycleDetail ? `\n      <td class=\"num\">${l.tempsCoupe === \"\" || l.tempsCoupe == null ? \"\u2014\" : l.tempsCoupe}</td>` : \"\"}\n      <td class=\"computed\">${perEdge === null ? \"\u2014\" : fmt(perEdge,3)}</td>\n      <td class=\"computed\">${perPiece === null ? \"\u2014\" : fmt(perPiece,4)}</td>\n    </tr>\n  `;\n}\n\nfunction renderDetail(){\n  const sc = data.find(s => s.id === activeId) || data[0];\n  const wrap = document.getElementById(\"scenarioDetail\");\n  if(!sc){ wrap.innerHTML = \"\"; return; }\n  wrap.innerHTML = `<div class=\"zone-band\"><b>3 &middot; Tra\u00e7abilit\u00e9 du sc\u00e9nario ouvert</b><span>outils, cycle, essais, rebut</span><button class=\"ghost small\" id=\"livraisonsBtn\" title=\"Le dossier hi\u00e9rarchie : figer les gains du jour dans un document dat\u00e9 (dans la carte atelier)\">\ud83d\udce6 Livraisons</button><button class=\"ghost small\" id=\"retourCarteBtn\" title=\"Revenir \u00e0 la carte atelier\" style=\"margin-left:auto;\">\u21e0 Carte atelier</button></div>` + scenarioBlockHTML(sc, true);\n  attachDetailHandlers(sc);\n  loadPhotoThumbnails();\n}\nfunction renderAll(){\n  const soloActif = document.getElementById(\"prtActifSeul\") && document.getElementById(\"prtActifSeul\").checked;\n  const liste = soloActif ? data.filter(s => s.id === activeId) : data;\n  const synthesePrint = (!soloActif && document.getElementById(\"prtSynthese\") && document.getElementById(\"prtSynthese\").checked)\n    ? syntheseHTML() : \"\";\n  document.getElementById(\"scenarioAll\").innerHTML = synthesePrint + liste.map(sc => scenarioBlockHTML(sc, false)).join(\"\");\n}\n\n/* ============================================================================\n   SELECTEUR DE PROJET (v4.1) -- des cartes, pas une quatrieme barre grise. Le projet est\n   un changement de focus (quels essais je regarde), pas un niveau de navigation physique\n   supplementaire : la ligne/reference/OP restent visibles et navigables normalement, quel\n   que soit le projet ouvert (voir la note en tete de fichier sur les etiquettes).\n   ============================================================================ */\nfunction statsProjet(pj){\n  const rs = scenariosResolusDuProjet(pj);\n  const lignesTouchees = new Set(rs.map(x => x.ligne.id));\n  const opsTouches = new Set(rs.map(x => x.op.id));\n  let essais = 0, valides = 0, enSerie = 0, gain = 0, gainConnu = false;\n  rs.forEach(({ ligne, reference, op, scenario: sc }) => {\n    essais += (sc.essais || []).length;\n    if(sc.statut === \"valide\") valides++;\n    if(sc.statut === \"serie\") enSerie++;\n    if(sc.statut === \"serie\"){\n      dansContexteOp(op, () => {\n        try{\n          const an = bilanAnnuel(sc, op.config, ligne, reference);\n          if(an && an.gainAnnuel !== undefined){ gain += an.gainAnnuel; gainConnu = true; }\n        }catch(e){}\n      });\n    }\n  });\n  return { scenarios: rs.length, lignes: lignesTouchees.size, ops: opsTouches.size,\n           essais, valides, enSerie, gain, gainConnu };\n}\n\nfunction projetCarteHTML(pj){\n  const st = statsProjet(pj);\n  const actif = pj.id === activeProjetId;\n  const statut = PROJET_STATUTS[pj.statut] || PROJET_STATUTS.encours;\n  const resp = responsableDe(pj);\n  // Deux axes couleur distincts, jamais fusionnes (v4.2) : la bordure gauche porte la\n  // couleur du RESPONSABLE (qui pilote -- une personne, une couleur stable dans le temps) ;\n  // le statut reste lisible via son badge texte, inchange. Le petit point avant le nom porte\n  // la couleur du PROJET lui-meme (assignee a la creation), la meme que sur ses etiquettes\n  // de scenario (voir tag-pill) -- pour apprendre au premier coup d'oeil quelle couleur\n  // designe quel projet, avant meme de croiser cette couleur ailleurs dans l'ecran.\n  const couleurBordure = resp ? resp.couleur : \"var(--ink-faint)\";\n  // l'echeance se lit, elle ne sanctionne pas : dans un atelier, un essai glisse pour des\n  // raisons subies (dispo machine, dispo bruts, priorite client) -- pas de badge \"en retard\".\n  let echeance = \"\";\n  if(pj.dateCible){\n    const j = Math.round((new Date(pj.dateCible) - new Date()) / 86400000);\n    echeance = isNaN(j) ? \"\" : `<span class=\"pj-echeance\" title=\"\u00c9ch\u00e9ance vis\u00e9e : ${escapeAttr(pj.dateCible)}\">${\n      j >= 0 ? \"J\u2212\" + j : \"\u00e9ch\u00e9ance d\u00e9pass\u00e9e de \" + Math.abs(j) + \" j\"}</span>`;\n  }\n  return `\n    <div class=\"pj-carte ${actif ? \"active\" : \"\"} pj-${escapeAttr(pj.statut || \"encours\")}\" style=\"border-left-color:${couleurBordure};\">\n      <button class=\"pj-corps\" data-projet=\"${pj.id}\"\n              title=\"${actif ? \"Retirer le filtre (voir tous les projets)\" : \"Filtrer sur ce projet\"}\">\n        <span class=\"pj-haut\">\n          <span class=\"pj-puce\" style=\"background:${couleurProjet(pj)};\" title=\"Couleur de ce projet, reprise sur ses \u00e9tiquettes de sc\u00e9nario\"></span>\n          <span class=\"pj-nom\">${escapeAttr(pj.nom || \"Projet sans nom\")}</span>\n          <span class=\"pj-statut\">${statut}</span>\n          ${echeance}\n        </span>\n        ${pj.problematique ? `<span class=\"pj-pb\">${escapeAttr(pj.problematique)}</span>` : \"\"}\n        <span class=\"pj-chiffres\">\n          <span><b>${st.scenarios}</b> sc\u00e9nario${st.scenarios>1?\"s\":\"\"}</span>\n          <span><b>${st.lignes}</b> ligne${st.lignes>1?\"s\":\"\"}</span>\n          <span><b>${st.essais}</b> essai${st.essais>1?\"s\":\"\"}</span>\n          ${st.enSerie ? `<span class=\"pj-serie\"><b>${st.enSerie}</b> en s\u00e9rie</span>` : \"\"}\n        </span>\n        ${st.gainConnu ? `<span class=\"pj-gain ${st.gain>=0?\"pos\":\"neg\"}\">${st.gain>=0?\"+\":\"\u2212\"}${fmtEuroCourt(Math.abs(st.gain))} / an acquis</span>` : \"\"}\n        ${resp ? `<span class=\"pj-resp\"><span class=\"pj-resp-puce\" style=\"background:${resp.couleur};\"></span>Pilote : ${escapeAttr(resp.nom)}</span>` : \"\"}\n      </button>\n      <button class=\"pj-modifier\" data-cfg-projet=\"${pj.id}\">Modifier</button>\n    </div>`;\n}\n\n/* Un projet est visible sur une ligne si : c'est le projet actif (on doit toujours pouvoir\n   voir/desactiver ce qu'on a choisi, meme en regardant une autre ligne -- un projet peut\n   volontairement couvrir plusieurs lignes) ; ou il a deja au moins un scenario tague sur\n   cette ligne.\n   Correctif v4.3 : un projet SANS AUCUNE etiquette n'est plus visible \"partout\" -- ce\n   comportement etait le bug remonte en usage reel (\"je clique sur une ligne, \u00e7a m'affiche\n   des projets qui n'ont rien \u00e0 voir\"). Il est desormais visible UNIQUEMENT sur la ligne ou\n   il a ete cree (`ligneCreation`, pose par creerProjet() qui tague aussi d'office tous les\n   scenarios de l'OP courant -- un projet neuf n'est donc presque jamais reellement vide).\n   Le seul cas ou l'ancien comportement (\"partout\") est conserve : un projet cree par une\n   version anterieure a la v4.3, qui n'a pas ce champ -- pour ne pas le faire disparaitre\n   d'un coup sans explication a la mise a jour. */\nfunction projetVisibleSurLigne(pj, ligneId){\n  if(pj.id === activeProjetId) return true;\n  if(pj.tags.length) return pj.tags.some(t => t.ligneId === ligneId);\n  return pj.ligneCreation ? pj.ligneCreation === ligneId : true;\n}\n\n/* ============================================================================\n   FILTRE REEL DU TRAVAIL PAR PROJET (v4.3)\n   ============================================================================\n   Jusqu'ici, \"activer\" un projet ne faisait que du cosmetique : bandeau de cartes,\n   auto-etiquetage a la creation, filtre du tableau de bord. La liste des scenarios sur\n   laquelle on travaille au quotidien (le bandeau de tuiles, `data`) restait, elle,\n   totalement insensible au projet actif -- on pouvait cliquer \"Co\u00fbt EMAG 1\" et continuer a\n   voir cote a cote des scenarios d'un autre projet sur le meme OP. Ce n'etait pas juste\n   incomplet, c'etait incoherent : deux mecanismes de filtrage qui ne se parlaient pas.\n\n   Regle desormais (logique atelier) :\n     - si AUCUN scenario de l'OP courant n'est etiquete dans un quelconque projet, l'OP\n       n'a pas ete organise par projets : rien n'est filtre, comportement identique a avant\n       l'existence des projets. Personne ne doit sentir la fonctionnalite s'il ne l'utilise\n       pas ;\n     - des qu'au moins un scenario de cet OP appartient a un projet, ET qu'un projet precis\n       est le filtre actif, la liste se scope reellement : seuls les scenarios de CE projet\n       s'affichent. On ne regarde plus \"tout\", on travaille \"dans\" le projet choisi.\n   `render()` s'appuie dessus pour ne jamais laisser `activeId` pointer vers un scenario\n   masque ; `renderTabs()` s'en sert pour la liste affichee et son etat vide dedie. */\nfunction opOrganiseParProjets(){\n  return data.some(sc => projets.some(pj => projetContientScenario(pj, activeLigneId, activeReferenceId, activeOpId, sc.id)));\n}\nfunction scenariosVisibles(){\n  if(!activeProjetId) return data;\n  if(!opOrganiseParProjets()) return data;\n  const pjActif = projets.find(p => p.id === activeProjetId);\n  if(!pjActif) return data;\n  // v4.4 : le scenario en production reste toujours visible, meme filtre projet actif et\n  // meme s'il n'est etiquete dans aucun projet -- c'est la reference de l'OP, elle ne doit\n  // jamais disparaitre du bandeau. Exemption d'AFFICHAGE uniquement : statsProjet() et\n  // projetContientScenario() ne changent pas, un baseline non etiquete ne compte donc pas\n  // dans les stats du projet actif malgre sa presence a l'ecran.\n  return data.filter(sc => sc.baseline || projetContientScenario(pjActif, activeLigneId, activeReferenceId, activeOpId, sc.id));\n}\n\n/* Vue \"tous les projets\" du bandeau : etat d'affichage volatil, comme le filtre du tableau\n   de bord -- ne se sauvegarde pas, on repart filtre par ligne a chaque rechargement. */\nlet bandeauProjetsTousAffiches = false;\n\nfunction renderProjets(){\n  const el = document.getElementById(\"projetsBandeau\");\n  if(!el) return;\n  if(!projets.length){\n    // aucun projet cree : pas la peine d'occuper l'ecran avec un bandeau vide, un simple\n    // lien suffit -- les projets sont facultatifs, l'outil marche identiquement sans eux\n    el.innerHTML = `<button class=\"primary\" id=\"addProjetBtn\">+ Cr\u00e9er un projet</button>\n      <span class=\"pj-aide\">Un projet regroupe les sc\u00e9narios qui r\u00e9pondent \u00e0 une m\u00eame probl\u00e9matique, sans changer o\u00f9 ils vivent physiquement.</span>`;\n    document.getElementById(\"addProjetBtn\").addEventListener(\"click\", creerProjet);\n    return;\n  }\n\n  const ligneNom = (getActiveLigne() || {}).nom || \"cette ligne\";\n  const visibles = bandeauProjetsTousAffiches ? projets : projets.filter(pj => projetVisibleSurLigne(pj, activeLigneId));\n\n  if(!visibles.length){\n    // des projets existent, mais aucun ne concerne la ligne ouverte -- on le dit plutot\n    // que d'afficher un bandeau vide qui laisserait croire qu'aucun projet n'existe\n    el.innerHTML = `\n      <div class=\"pj-entete\">\n        <h4>Projets</h4>\n        <span class=\"pj-compte\">Aucun sur \u00ab ${escapeAttr(ligneNom)} \u00bb</span>\n        <button class=\"ghost small\" id=\"toggleVueProjetsBtn\">Voir tous les projets (${projets.length})</button>\n        <button class=\"primary\" id=\"addProjetBtn\">+ Nouveau projet</button>\n      </div>`;\n    document.getElementById(\"toggleVueProjetsBtn\").addEventListener(\"click\", () => { bandeauProjetsTousAffiches = true; render(); });\n    document.getElementById(\"addProjetBtn\").addEventListener(\"click\", creerProjet);\n    return;\n  }\n\n  el.innerHTML = `\n    <div class=\"pj-entete\">\n      <h4>Projets</h4>\n      <span class=\"pj-compte\">${bandeauProjetsTousAffiches\n        ? `${projets.length} projet${projets.length>1?\"s\":\"\"}`\n        : `${visibles.length} sur \u00ab ${escapeAttr(ligneNom)} \u00bb`}${activeProjetId ? \" \u2014 filtr\u00e9\" : \"\"}</span>\n      <button class=\"ghost small\" id=\"toggleVueProjetsBtn\">${bandeauProjetsTousAffiches ? \"Filtrer sur cette ligne\" : \"Voir tous les projets\"}</button>\n      ${activeProjetId ? `<button class=\"ghost small\" id=\"clearProjetBtn\">Retirer le filtre projet</button>` : \"\"}\n      <button class=\"primary\" id=\"addProjetBtn\">+ Nouveau projet</button>\n    </div>\n    <div class=\"pj-grille\">${visibles.map(projetCarteHTML).join(\"\")}</div>`;\n\n  el.querySelectorAll(\"[data-projet]\").forEach(b => b.addEventListener(\"click\", () => {\n    const id = b.getAttribute(\"data-projet\");\n    activeProjetId = (activeProjetId === id) ? null : id;\n    saveData(); render();\n  }));\n  el.querySelectorAll(\"[data-cfg-projet]\").forEach(b => b.addEventListener(\"click\", () => ouvrirProjetInfo(b.getAttribute(\"data-cfg-projet\"))));\n  document.getElementById(\"addProjetBtn\").addEventListener(\"click\", creerProjet);\n  document.getElementById(\"toggleVueProjetsBtn\").addEventListener(\"click\", () => { bandeauProjetsTousAffiches = !bandeauProjetsTousAffiches; render(); });\n  const clr = document.getElementById(\"clearProjetBtn\");\n  if(clr) clr.addEventListener(\"click\", () => { activeProjetId = null; saveData(); render(); });\n}\n\nfunction creerProjet(){\n  // v4.5 : panneau dedie plutot que prompt() natif \u2014 meme famille visuelle que le panneau\n  // projet, et le champ Description y trouve sa place des la creation.\n  const champ = document.getElementById(\"projetCreateNom\");\n  const auto = document.getElementById(\"projetCreateAutoTag\");\n  if(!champ) return;\n  champ.value = \"\";\n  const nb = (data || []).length;\n  const l = getActiveLigne();\n  if(auto){\n    auto.textContent = nb\n      ? \"Seront rattach\u00e9s automatiquement : les \" + nb + \" sc\u00e9nario(s) de l'OP ouvert (\" + ((l && l.nom) || \"cette ligne\") + \" \u203a \" + ((getActiveOp() || {}).nom || \"OP\") + \"). Retirez ensuite les \u00e9tiquettes qui n'ont rien \u00e0 voir, ou gardez-les toutes.\"\n      : \"Aucun sc\u00e9nario dans l'OP ouvert : le projet d\u00e9marrera vide \u2014 vous \u00e9tiquetterez ses sc\u00e9narios au fur et \u00e0 mesure.\";\n  }\n  ouvrirPanneau(\"projetCreatePanel\");\n  champ.focus();\n}\nfunction validerCreationProjet(){\n  const champ = document.getElementById(\"projetCreateNom\");\n  const nom = (champ ? champ.value : \"\") || \"\";\n  const pj = normalizeProjet({\n    nom: nom.trim() || \"Nouveau projet\",\n    creePar: auteurNom || \"\",\n    creeLe: new Date().toISOString().slice(0,10),\n    // couleur d'identite assignee une fois pour toutes, ici, a la creation -- jamais\n    // recalculee au rendu (voir normalizeProjet)\n    couleur: OUTIL_COLORS[projets.length % OUTIL_COLORS.length],\n    // repli d'affichage tant qu'aucune etiquette n'existe (voir projetVisibleSurLigne)\n    ligneCreation: activeLigneId || \"\"\n  });\n  // v4.3 : \"creer un projet ici\" tague TOUS les scenarios de l'OP courant, pas seulement\n  // celui qui etait ouvert par hasard -- \"ici\" doit se comprendre comme \"cette ligne, cet\n  // OP, maintenant\", pas comme une loterie sur le scenario affiche. On affine ensuite au\n  // cas par cas avec les etiquettes des cartes de scenario.\n  (data || []).forEach(sc => pj.tags.push({ ligneId: activeLigneId, referenceId: activeReferenceId, opId: activeOpId, scenarioId: sc.id }));\n  projets.push(pj);\n  activeProjetId = pj.id;\n  saveData();\n  fermerPanneaux();\n  ouvrirProjetInfo(pj.id);\n  render();\n}\n\nlet projetInfoTargetId = null;\n/* Remplit le menu deroulant \"Pilote du projet\" a partir de la liste geree, plus une option\n   de creation rapide -- inutile d'aller dans Options pour la toute premiere personne. */\nfunction remplirSelectResponsables(selectionneId){\n  const sel = document.getElementById(\"projetResponsable\");\n  sel.innerHTML = `<option value=\"\">\u2014 Aucun \u2014</option>`\n    + responsables.map(r => `<option value=\"${r.id}\">${escapeAttr(r.nom)}</option>`).join(\"\")\n    + `<option value=\"__nouveau__\">+ Nouveau responsable\u2026</option>`;\n  sel.value = selectionneId || \"\";\n}\n\nfunction ouvrirProjetInfo(id){\n  const pj = projets.find(x => x.id === id);\n  if(!pj) return;\n  projetInfoTargetId = pj.id;\n  document.getElementById(\"projetNom\").value = pj.nom || \"\";\n  document.getElementById(\"projetProblematique\").value = pj.problematique || \"\";\n  remplirSelectResponsables(pj.responsableId || \"\");\n  document.getElementById(\"projetStatut\").value = pj.statut || \"encours\";\n  document.getElementById(\"projetDateCible\").value = pj.dateCible || \"\";\n  const st = statsProjet(pj);\n  document.getElementById(\"projetMeta\").textContent =\n    (pj.creeLe ? \"Cr\u00e9\u00e9 le \" + pj.creeLe + (pj.creePar ? \" par \" + pj.creePar : \"\") + \" \u00b7 \" : \"\")\n    + st.scenarios + \" sc\u00e9nario(s) \u00e9tiquet\u00e9(s) sur \" + st.lignes + \" ligne(s), \" + st.essais + \" essai(s).\"\n    // v4.5 : un projet fraichement cree a rattache d'office les scenarios de l'OP ouvert \u2014\n    // il faut le DIRE, sinon l'utilisateur ne sait pas que son projet \"contient\" deja quelque chose\n    + (pj.creeLe === new Date().toISOString().slice(0,10) && st.scenarios\n        ? \" \" + st.scenarios + \" sc\u00e9nario(s) rattach\u00e9(s) automatiquement \u00e0 la cr\u00e9ation \u2014 ajustez les \u00e9tiquettes si certains n'ont rien \u00e0 voir.\"\n        : \"\");\n  ouvrirPanneau(\"projetInfoPanel\");\n}\n\n/* Selection \"+ Nouveau responsable\u2026\" dans le menu deroulant : cree la personne a la volee\n   (couleur assignee automatiquement, modifiable ensuite dans Options) sans faire quitter\n   le panneau du projet. */\nfunction ajouterResponsableDepuisSelect(){\n  const pj = projets.find(x => x.id === projetInfoTargetId);\n  dialogueDemander(\"Nom du nouveau responsable :\", \"\", { titre: \"Nouveau responsable\" }).then(nom => {\n    if(nom === null || !nom.trim()){ remplirSelectResponsables(pj ? pj.responsableId : \"\"); return; }\n    const r = normalizeResponsable({ nom: nom.trim(), couleur: prochaineCouleurLibre(responsables.map(x => x.couleur)) });\n    responsables.push(r);\n    remplirSelectResponsables(r.id);\n    enregistrerProjetInfo();\n  });\n}\n\nfunction enregistrerProjetInfo(){\n  const pj = projets.find(x => x.id === projetInfoTargetId);\n  if(!pj) return;\n  pj.nom = document.getElementById(\"projetNom\").value.trim() || \"Projet sans nom\";\n  pj.problematique = document.getElementById(\"projetProblematique\").value.trim();\n  pj.responsableId = document.getElementById(\"projetResponsable\").value;\n  pj.responsable = \"\"; // le champ texte libre (v4.0/4.1) n'est plus utilise en saisie\n  pj.statut = document.getElementById(\"projetStatut\").value;\n  pj.dateCible = document.getElementById(\"projetDateCible\").value;\n  saveData(); render();\n}\nfunction supprimerProjetActif(){\n  const pj = projets.find(x => x.id === projetInfoTargetId);\n  if(!pj) return;\n  // supprimer un projet ne touche a AUCUNE donnee physique : ce n'est qu'une liste\n  // d'etiquettes qui disparait. Les scenarios, essais et mesures restent intacts.\n  dialogueConfirmer(`Supprimer le projet \u00ab ${pj.nom} \u00bb ?\\n\\nSes ${pj.tags.length} \u00e9tiquette(s) de sc\u00e9nario disparaissent. Les lignes, sc\u00e9narios et essais eux-m\u00eames ne sont PAS supprim\u00e9s \u2014 ils restent dans l'outil, seulement plus rattach\u00e9s \u00e0 ce projet.`, { titre: \"Supprimer le projet ?\", danger: true, okLabel: \"Supprimer\" }).then(ok => {\n    if(!ok) return;\n    projets = projets.filter(x => x.id !== pj.id);\n    if(activeProjetId === pj.id) activeProjetId = null;\n    fermerPanneaux();\n    saveData(); render();\n  });\n}\n\n/* ---- navigation : fil d'Ariane (v4.13, CDC UX \u00a73.1) --------------------------------\n   Les trois rang\u00e9es de pastilles (ligne / r\u00e9f\u00e9rence / OP), toutes identiques, se lisaient\n   comme trois fois la m\u00eame chose. Un seul fil maintenant : \u00ab EMAG 1 \u203a R\u00e9f\u00e9rence \u203a OP10 \u00bb.\n   Chaque maillon est cliquable et ouvre son propre s\u00e9lecteur \u2014 cr\u00e9ations, renommages et\n   suppressions vivent DEDANS, la rang\u00e9e reste propre. Le \u2699 (infos ligne) reste visible\n   \u00e0 c\u00f4t\u00e9 du premier maillon : une action invisible n'est pas une action (le\u00e7on v4.2). */\n/* v4.64 (C6\u2032-a) \u2014 le cadenas de la barre de contexte : l'ic\u00f4ne ET le mot */\nfunction filLockHTML(locked){\n  return locked ? `<span class=\"fil-lock\" title=\"Consultation : la saisie est verrouill\u00e9e. Ouvrir le cadenas de la barre d'outils pour modifier.\">\ud83d\udd12 verrouill\u00e9</span>` : \"\";\n}\n\nfunction renderFilAriane(){  const el = document.getElementById(\"filAriane\");\n  if(!el) return;\n  const l = getActiveLigne(), r = getActiveReference(), op = getActiveOp();\n  /* v4.64 (C6\u2032-a) \u2014 la barre de contexte en 4 \u00c9TAPES, la r\u00e9ponse au reproche de\n     septembre (\u00ab quand tu veux une information, tu dois r\u00e9fl\u00e9chir \u00bb) : avant de\n     saisir, on sait o\u00f9 l'on est. Chaque segment porte son num\u00e9ro, son libell\u00e9 en\n     petites capitales, sa valeur \u2014 et \u25be pour dire qu'on peut choisir. Des liens,\n     jamais du texte : le clic ouvre la liste des valeurs r\u00e9elles de ce niveau. */\n  const sc = (op && (op.scenarios || []).find(x => x.id === activeId))\n           || ((r && r.ops || []).flatMap(o => o.scenarios || []).find(x => x.id === activeId))\n           || null;\n  const seg = (num, cle, libelle, val, opts) => {\n    opts = opts || {};\n    return `<button class=\"fil-seg${opts.bleu ? \" fil-seg-bleu\" : \"\"}\" data-fil=\"${cle}\" title=\"${escapeAttr(libelle)} \u2014 cliquer pour choisir\">\n      <span class=\"fil-meta\"><span class=\"fil-num\">${num}</span><span class=\"fil-lib\">${escapeAttr(libelle)}</span></span>\n      <span class=\"fil-val\">${escapeAttr(val)}</span><span class=\"fil-mod\" aria-hidden=\"true\">\u25be</span>\n    </button>`;\n  };\n  /* le cadenas porte l'ic\u00f4ne ET le mot (\u00a75.2) : le verrou de consultation est\n     l'\u00e9tat r\u00e9el de l'outil (body.locked) \u2014 on ne l'invente pas par sc\u00e9nario.\n     Fonction pure : testable au harnais, o\u00f9 body.classList est un stub muet. */\n  const lock = filLockHTML(document.body.classList.contains(\"locked\"));\n  el.innerHTML = `\n    ${seg(\"01\", \"ligne\", \"Ligne machine\", l ? l.nom : \"aucune ligne\")}\n    ${l ? `<button class=\"fil-ico\" data-cfg-ligne=\"${l.id}\" title=\"Co\u00fbt horaire, observations, maintenance\">\u2699</button>` : \"\"}\n    <span class=\"fil-sep\">\u203a</span>\n    ${seg(\"02\", \"ref\", \"R\u00e9f\u00e9rence pi\u00e8ce\", r ? r.nom : \"aucune r\u00e9f\u00e9rence\")}\n    <span class=\"fil-sep\">\u203a</span>\n    ${seg(\"03\", \"op\", \"Op\u00e9ration\", op ? op.nom : \"aucune OP\")}\n    <span class=\"fil-sep\">\u203a</span>\n    ${seg(\"04\", \"sc\", \"Sc\u00e9nario\", sc ? sc.name : \"aucun sc\u00e9nario\", { bleu: !!sc })}\n    ${lock}\n    <span class=\"fil-menu\" id=\"filMenu\" hidden></span>`;\n}\n\nfunction filItem(action, id, label, opts){\n  opts = opts || {};\n  return `<button class=\"fil-item ${opts.cls || \"\"}\" data-fil-item=\"${action}\" data-fil-id=\"${escapeAttr(id || \"\")}\"${opts.cur ? ' data-fil-cur=\"1\"' : \"\"}>${opts.cur ? \"\u25cf&nbsp; \" : \"\"}${escapeAttr(label)}</button>`;\n}\n\nfunction ouvrirFilMenu(cle, ancre, menu){\n  const l = getActiveLigne(), r = getActiveReference(), op = getActiveOp();\n  const lecture = lectureSeule; // en consultation : naviguer oui, cr\u00e9er/renommer/supprimer non\n  let items = \"\";\n  if(cle === \"ligne\"){\n    items = lignes.map(x => filItem(\"go-ligne\", x.id, x.nom || \"Sans nom\", { cur: l && x.id === l.id })).join(\"\")\n      + `<div class=\"toolbar-more-sep\"></div>`\n      + (lecture ? \"\" : filItem(\"add-ligne\", \"\", \"+ Nouvelle ligne\u2026\")\n        + (l ? filItem(\"ren-ligne\", l.id, \"Renommer la ligne\u2026\") : \"\")\n        + (l && lignes.length > 1 ? filItem(\"del-ligne\", l.id, \"Supprimer la ligne\u2026\", { cls: \"danger\" }) : \"\"));\n  } else if(cle === \"ref\"){\n    if(!l) return;\n    items = l.references.map(x => filItem(\"go-ref\", x.id, x.nom || \"Sans nom\", { cur: r && x.id === r.id })).join(\"\")\n      + `<div class=\"toolbar-more-sep\"></div>`\n      + (lecture ? \"\" : filItem(\"add-ref\", \"\", \"+ Nouvelle r\u00e9f\u00e9rence disque\u2026\")\n        + (r ? filItem(\"ren-ref\", r.id, \"Renommer la r\u00e9f\u00e9rence\u2026\") : \"\")\n        + (r && l.references.length > 1 ? filItem(\"del-ref\", r.id, \"Supprimer la r\u00e9f\u00e9rence\u2026\", { cls: \"danger\" }) : \"\"));\n  } else if(cle === \"op\"){\n    if(!r) return;\n    items = r.ops.map(x => filItem(\"go-op\", x.id, x.nom || \"Sans nom\", { cur: op && x.id === op.id })).join(\"\")\n      + `<div class=\"toolbar-more-sep\"></div>`\n      + (lecture ? \"\" : filItem(\"add-op\", \"\", \"+ Nouvelle OP\u2026\")\n        + (op ? filItem(\"ren-op\", op.id, \"Renommer l'OP\u2026\") : \"\")\n        + (r.ops.length > 1 && op ? filItem(\"del-op\", op.id, \"Supprimer l'OP\u2026\", { cls: \"danger\" }) : \"\"));\n  } else if(cle === \"sc\"){\n    /* v4.64 (C6\u2032-a) \u2014 le 4\u1d49 niveau : les sc\u00e9narios de l'OP ouverte, avec le\n       marque r\u00e9el de chaque statut (\u2605 prod, \u25cf s\u00e9rie) \u2014 jamais une liste libre.\n       La cr\u00e9ation passe par le \u00ab + Ajouter \u00bb existant : le menu navigue, il ne\n       saisit pas (le fil est un rep\u00e8re, pas un formulaire). */\n    if(!op || !(op.scenarios || []).length){\n      items = `<div class=\"fil-vide-note\">Aucun sc\u00e9nario sur cette OP \u2014 \u00ab + Ajouter \u00bb dans la barre d'outils en cr\u00e9e un.</div>`;\n    } else {\n      items = op.scenarios.map(x => filItem(\"go-sc\", x.id,\n        (x.baseline ? \"\u2605 \" : \"\") + (x.name || \"Sans nom\") + (x.statut === \"serie\" ? \" \u00b7 s\u00e9rie\" : \"\"),\n        { cur: x.id === activeId })).join(\"\");\n    }\n  } else return;\n  menu.innerHTML = items;\n  menu.style.left = Math.max(0, ancre.offsetLeft) + \"px\";\n  menu.dataset.cle = cle;\n  menu.hidden = false;\n}\n\nfunction traiterFilItem(item, menu){\n  const action = item.getAttribute(\"data-fil-item\");\n  const id = item.getAttribute(\"data-fil-id\");\n  menu.hidden = true;\n  const l = getActiveLigne(), r = getActiveReference(), op = getActiveOp();\n  if(action === \"go-ligne\"){\n    const cible = lignes.find(x => x.id === id);\n    if(cible) switchReference(cible.id, cible.references[0] ? cible.references[0].id : null);\n  } else if(action === \"go-ref\"){\n    switchReference(activeLigneId, id);\n  } else if(action === \"go-op\"){\n    switchOp(activeLigneId, activeReferenceId, id);\n  } else if(action === \"go-sc\"){\n    /* v4.64 (C6\u2032-a) \u2014 naviguer vers le sc\u00e9nario choisi depuis la barre de contexte */\n    const cible = (r && r.ops || []).flatMap(o => o.scenarios || []).find(x => x.id === id);\n    if(cible){ activeId = cible.id; saveData(); render(); }\n  } else if(action === \"add-ligne\"){\n    dialogueDemander(\"Nom de la nouvelle ligne de production (ex. EMAG 1, EMAG 2, WEISSER 1, WEISSER 2, HESSAP...) :\", \"\", { titre: \"Nouvelle ligne de production\" }).then(nom => {\n      if(!nom || !nom.trim()) return;\n      const nOp = { id: uid(\"o\"), nom: \"OP10\", ordre: 10, config: Object.assign({}, defaultConfig), scenarios: [] };\n      const nRef = { id: uid(\"r\"), nom: \"Nouvelle r\u00e9f\u00e9rence\", ops: [nOp] };\n      const nL = { id: uid(\"l\"), nom: nom.trim(), references: [nRef] };\n      lignes.push(nL);\n      switchReference(nL.id, nRef.id);\n    });\n  } else if(action === \"ren-ligne\"){\n    if(!l) return;\n    dialogueDemander(\"Renommer la ligne de production :\", l.nom, { titre: \"Renommer la ligne\" }).then(nom => {\n      if(nom === null || !nom.trim()) return;\n      l.nom = nom.trim();\n      saveData(); render();\n    });\n  } else if(action === \"del-ligne\"){\n    if(!l || lignes.length <= 1) return;\n    const nbRef = l.references.length;\n    dialogueConfirmer(\"Supprimer la ligne \u00ab \" + l.nom + \" \u00bb ?\" + (nbRef ? \"\\n\\nElle contient \" + nbRef + \" r\u00e9f\u00e9rence(s) disque qui seront perdues.\" : \"\"), { titre: \"Supprimer la ligne ?\", danger: true, okLabel: \"Supprimer\" }).then(ok => {\n      if(!ok) return;\n      lignes = lignes.filter(x => x.id !== l.id);\n      switchReference(lignes[0].id, lignes[0].references[0] ? lignes[0].references[0].id : null);\n    });\n  } else if(action === \"add-ref\"){\n    if(!l) return;\n    dialogueDemander(\"Nom de la nouvelle r\u00e9f\u00e9rence disque :\", \"\", { titre: \"Nouvelle r\u00e9f\u00e9rence disque\" }).then(nom => {\n      if(!nom || !nom.trim()) return;\n      const nOp = { id: uid(\"o\"), nom: \"OP10\", ordre: 10, config: Object.assign({}, defaultConfig), scenarios: [] };\n      const nRef = { id: uid(\"r\"), nom: nom.trim(), ops: [nOp] };\n      l.references.push(nRef);\n      switchReference(l.id, nRef.id);\n    });\n  } else if(action === \"ren-ref\"){\n    if(!r) return;\n    dialogueDemander(\"Renommer la r\u00e9f\u00e9rence disque :\", r.nom, { titre: \"Renommer la r\u00e9f\u00e9rence\" }).then(nom => {\n      if(nom === null || !nom.trim()) return;\n      r.nom = nom.trim();\n      saveData(); render();\n    });\n  } else if(action === \"del-ref\"){\n    if(!l || !r || l.references.length <= 1) return;\n    const nbSc = r.ops.reduce((n, o) => n + o.scenarios.length, 0);\n    dialogueConfirmer(\"Supprimer la r\u00e9f\u00e9rence \u00ab \" + r.nom + \" \u00bb ?\" + (nbSc ? \"\\n\\nElle contient \" + nbSc + \" sc\u00e9nario(s) (toutes OP confondues) qui seront perdus.\" : \"\"), { titre: \"Supprimer la r\u00e9f\u00e9rence ?\", danger: true, okLabel: \"Supprimer\" }).then(ok => {\n      if(!ok) return;\n      l.references = l.references.filter(x => x.id !== r.id);\n      switchReference(l.id, l.references[0].id);\n    });\n  } else if(action === \"add-op\"){\n    if(!r) return;\n    dialogueDemander(\"Nom de la nouvelle OP (ex. OP10, OP20, Per\u00e7age...) :\", \"\", { titre: \"Nouvelle OP\" }).then(nom => {\n      if(!nom || !nom.trim()) return;\n      const ordreMax = r.ops.reduce((m, o) => Math.max(m, o.ordre || 0), 0);\n      const nOp = { id: uid(\"o\"), nom: nom.trim(), ordre: ordreMax + 10, config: Object.assign({}, defaultConfig), scenarios: [] };\n      r.ops.push(nOp);\n      switchOp(activeLigneId, activeReferenceId, nOp.id);\n    });\n  } else if(action === \"ren-op\"){\n    if(!op) return;\n    dialogueDemander(\"Renommer l'OP :\", op.nom, { titre: \"Renommer l'OP\" }).then(nom => {\n      if(nom === null || !nom.trim()) return;\n      op.nom = nom.trim();\n      saveData(); render();\n    });\n  } else if(action === \"del-op\"){\n    if(!r || !op || r.ops.length <= 1) return;\n    const nbSc = op.scenarios.length;\n    dialogueConfirmer(\"Supprimer l'OP \u00ab \" + op.nom + \" \u00bb ?\" + (nbSc ? \"\\n\\nElle contient \" + nbSc + \" sc\u00e9nario(s) qui seront perdus.\" : \"\"), { titre: \"Supprimer l'OP ?\", danger: true, okLabel: \"Supprimer\" }).then(ok => {\n      if(!ok) return;\n      r.ops = r.ops.filter(x => x.id !== op.id);\n      switchOp(activeLigneId, activeReferenceId, r.ops[0].id);\n    });\n  }\n}\n\n/* un seul \u00e9couteur d\u00e9l\u00e9gu\u00e9, pos\u00e9 une fois pour toutes : le fil et son menu sont\n   reconstruits \u00e0 chaque rendu, la d\u00e9l\u00e9gation leur survit. Clic hors du fil = menu ferm\u00e9. */\ndocument.addEventListener(\"click\", (e) => {\n  const ariane = document.getElementById(\"filAriane\");\n  if(!ariane) return;\n  const menu = document.getElementById(\"filMenu\");\n  const seg = e.target.closest(\".fil-seg\");\n  if(seg && ariane.contains(seg)){\n    const cle = seg.getAttribute(\"data-fil\");\n    if(menu && !menu.hidden && menu.dataset.cle === cle){ menu.hidden = true; return; }\n    if(menu) ouvrirFilMenu(cle, seg, menu);\n    return;\n  }\n  const cfg = e.target.closest(\".fil-ico[data-cfg-ligne]\");\n  if(cfg && ariane.contains(cfg)){ ouvrirLigneInfo(cfg.getAttribute(\"data-cfg-ligne\")); return; }\n  const item = e.target.closest(\".fil-item\");\n  if(item && menu && menu.contains(item)){ traiterFilItem(item, menu); return; }\n  if(menu && !menu.hidden) menu.hidden = true;\n});\ndocument.addEventListener(\"keydown\", (e) => {\n  if(e.key !== \"Escape\") return;\n  const menu = document.getElementById(\"filMenu\");\n  if(menu && !menu.hidden) menu.hidden = true;\n});\n\n/* ---- ligne de reprise (v4.14) ---------------------------------------------------------\n   Le geste n\u00b01 de la journ\u00e9e, c'est de continuer l'essai commenc\u00e9 avant : ouvrir le bon\n   sc\u00e9nario, d\u00e9plier le bon essai, entrer en mode atelier \u2014 trois ou quatre gestes avant de\n   pouvoir taper une mesure, debout devant la machine. Le bandeau propose directement le\n   dernier essai EN COURS touch\u00e9 (modifieLe le plus r\u00e9cent) : un essai d\u00e9j\u00e0 conforme ou non\n   conforme est une campagne close, on ne le repropose pas. Le \u2715 masque la proposition pour\n   CET essai ; un essai diff\u00e9rent touch\u00e9 plus tard repasse devant naturellement. */\nfunction dernierEssaiEnCours(){\n  /* v4.25 \u2014 le bandeau propose d'abord les essais en cours du sc\u00e9nario AFFICH\u00c9 : l\u00e0 o\u00f9\n     l'on travaille. Avant, le plus r\u00e9cent toutes lignes/sc\u00e9narios confondues gagnait \u2014\n     un vieil essai d'un autre sc\u00e9nario (et ses noms de logements d'\u00e9poque) s'affichait\n     donc en t\u00eate des nouvelles cr\u00e9ations. \u00c0 d\u00e9faut d'essai en cours ici, on retombe\n     sur le plus r\u00e9cent de l'outil, comme avant. */\n  const candidats = [];\n  lignes.forEach(l => (l.references || []).forEach(r => (r.ops || []).forEach(o => (o.scenarios || []).forEach(sc => {\n    (sc.essais || []).forEach(es => {\n      const st = essaiStats(sc, es);\n      if(st.status !== \"pending\") return;\n      const t = es.modifieLe || (es.date ? es.date + \"T00:00:00\" : \"\");\n      if(!t) return;\n      candidats.push({ t, actif: sc.id === activeId, ligneId:l.id, refId:r.id, opId:o.id,\n        scId:sc.id, essaiId:es.id, scName:sc.name, essaiTitre:es.titre, date:es.date, st });\n    });\n  }))));\n  if(!candidats.length) return null;\n  const actifs = candidats.filter(c => c.actif);\n  const pool = actifs.length ? actifs : candidats;\n  pool.sort((a, b) => (a.t < b.t ? 1 : a.t > b.t ? -1 : 0));\n  return pool[0];\n}\nfunction renderReprise(){\n  const el = document.getElementById(\"repriseBandeau\");\n  if(!el) return;\n  const rep = dernierEssaiEnCours();\n  if(!rep){\n    el.hidden = true; el.innerHTML = \"\"; return;\n  }\n  if(rep.essaiId !== repriseVueId){ repriseVueId = rep.essaiId; repriseMasquee = false; }\n  const dejaOuvert = rep.scId === activeId && essaisOuverts.has(rep.scId + \"|\" + rep.essaiId);\n  if(repriseMasquee || dejaOuvert){ el.hidden = true; el.innerHTML = \"\"; return; }\n  const derniere = rep.st.lastPiece !== null ? \"dernier pr\u00e9l\u00e8vement n\u00b0\" + rep.st.lastPiece : \"aucun pr\u00e9l\u00e8vement\";\n  el.innerHTML = `\n    <span class=\"rep-ico\">\u21bb</span>\n    <span class=\"rep-txt\"><b>Reprendre</b> \u2014 ${escapeAttr(rep.essaiTitre || \"Essai\")}${rep.date ? \" (\" + escapeAttr(rep.date) + \")\" : \"\"} \u00b7 ${escapeAttr(rep.scName)} \u00b7 ${derniere}${rep.st.raison ? \" \u00b7 \" + escapeAttr(rep.st.raison) : \"\"}</span>\n    <button class=\"primary\" id=\"repAtelier\">Mode atelier</button>\n    <button class=\"ghost\" id=\"repOuvrir\">Ouvrir</button>\n    <button class=\"ghost rep-fermer\" id=\"repFermer\" title=\"Masquer pour cet essai (il reviendra s'il redevient le plus r\u00e9cent)\">\u2715</button>`;\n  el.hidden = false;\n  document.getElementById(\"repAtelier\").addEventListener(\"click\", () => {\n    allerVers(rep.ligneId, rep.refId, rep.opId, rep.scId, rep.essaiId);\n    ouvrirAtelier(rep.scId, rep.essaiId);\n  });\n  document.getElementById(\"repOuvrir\").addEventListener(\"click\", () => {\n    allerVers(rep.ligneId, rep.refId, rep.opId, rep.scId, rep.essaiId, true);\n  });\n  document.getElementById(\"repFermer\").addEventListener(\"click\", () => {\n    repriseMasquee = true; renderReprise();\n  });\n}\n/* navigation programmatique vers un essai pr\u00e9cis, quel que soit l'endroit d'o\u00f9 l'on part :\n   l'arbre est repositionn\u00e9 (ligne/r\u00e9f\u00e9rence/OP), le filtre de projet saut\u00e9 s'il cachait le\n   sc\u00e9nario vis\u00e9, la tuile de l'essai d\u00e9pli\u00e9e, et l'\u00e9cran d\u00e9file jusqu'\u00e0 elle si demand\u00e9. */\nfunction allerVers(ligneId, refId, opId, scId, essaiId, defiler){\n  if(activeProjetId){\n    const pj = projets.find(p => p.id === activeProjetId);\n    const visible = pj && projetContientScenario(pj, ligneId, refId, opId, scId);\n    if(!visible) activeProjetId = null; // jamais un sc\u00e9nario vis\u00e9 rest\u00e9 cach\u00e9 par le filtre\n  }\n  if(ligneId !== activeLigneId || refId !== activeReferenceId || opId !== activeOpId){\n    switchOp(ligneId, refId, opId); // fait d\u00e9j\u00e0 saveData + render\n  }\n  activeId = scId;\n  if(essaiId) essaisOuverts.add(scId + \"|\" + essaiId);\n  render();\n  if(essaiId && defiler){\n    const carte = document.querySelector('details.essai-card[data-essai-id=\"' + essaiId + '\"]');\n    if(carte) carte.scrollIntoView({ block: \"start\" });\n  }\n}\n\n/* ---- palette de recherche (v4.14, Ctrl+K) --------------------------------------------\n   L'arbre grandit : deux lignes, plusieurs r\u00e9f\u00e9rences et OP, des dizaines d'essais, des\n   projets. Taper \u00ab T513 \u00bb doit suffire pour atterrir sur l'essai. L'index est reconstruit\n   \u00e0 chaque ouverture (quelques centaines d'entr\u00e9es au plus, n\u00e9gligeable) ; le filtre ignore\n   la casse et les accents. \u2191\u2193 naviguent, Entr\u00e9e ouvre, un clic aussi. */\nfunction normaliserRecherche(s){\n  return (s || \"\").toString().toLowerCase().normalize(\"NFD\").replace(/[\\u0300-\\u036f]/g, \"\");\n}\nfunction construireIndexRecherche(){\n  const items = [];\n  lignes.forEach(l => {\n    items.push({ type:\"Ligne\", label:l.nom || \"Sans nom\", sous:(l.references||[]).length + \" r\u00e9f\u00e9rence(s)\",\n      go:() => switchReference(l.id, l.references[0] ? l.references[0].id : null) });\n    (l.references || []).forEach(r => {\n      items.push({ type:\"R\u00e9f\u00e9rence\", label:r.nom || \"Sans nom\", sous:l.nom || \"\",\n        go:() => switchReference(l.id, r.id) });\n      (r.ops || []).forEach(o => {\n        items.push({ type:\"OP\", label:o.nom || \"Sans nom\", sous:(l.nom||\"\") + \" \u203a \" + (r.nom||\"\"),\n          go:() => switchOp(l.id, r.id, o.id) });\n        (o.scenarios || []).forEach(sc => {\n          items.push({ type:\"Sc\u00e9nario\", label:sc.name, sous:(l.nom||\"\") + \" \u203a \" + (r.nom||\"\") + \" \u203a \" + (o.nom||\"\") + (sc.baseline ? \" \u00b7 \u2605 en production\" : \"\"),\n            go:() => { switchOp(l.id, r.id, o.id); activeId = sc.id; render(); } });\n          (sc.essais || []).forEach(es => {\n            items.push({ type:\"Essai\", label:es.titre || \"(sans titre)\", sous:(sc.name||\"\") + (es.date ? \" \u00b7 \" + es.date : \"\"),\n              go:() => allerVers(l.id, r.id, o.id, sc.id, es.id, true) });\n          });\n        });\n      });\n    });\n  });\n  (projets || []).forEach(pj => items.push({ type:\"Projet\", label:pj.nom || \"Sans nom\", sous:\"filtre de lecture\",\n    go:() => { activeProjetId = pj.id; render(); } }));\n  return items;\n}\nfunction ouvrirRecherche(){\n  rechercheListe = [];\n  rechercheSel = 0;\n  ouvrirPanneau(\"searchPanel\");\n  const inp = document.getElementById(\"searchInput\");\n  inp.value = \"\";\n  rendreRecherche(\"\");\n}\nfunction rendreRecherche(q){\n  const nq = normaliserRecherche(q.trim());\n  const tous = construireIndexRecherche();\n  rechercheListe = (!nq ? tous.slice(0, 12) : tous\n      .map(it => ({ it, i: normaliserRecherche(it.type + \" \" + it.label + \" \" + (it.sous||\"\")).indexOf(nq) }))\n      .filter(x => x.i >= 0)\n      .sort((a,b) => a.i - b.i)\n      .slice(0, 20)\n      .map(x => x.it));\n  rechercheSel = 0;\n  const box = document.getElementById(\"searchResults\");\n  box.innerHTML = rechercheListe.length ? rechercheListe.map((it, k) => `\n    <button class=\"search-item ${k === rechercheSel ? \"sel\" : \"\"}\" data-idx=\"${k}\">\n      <span class=\"search-type\">${it.type}</span>\n      <span class=\"search-label\">${escapeAttr(it.label)}</span>\n      <span class=\"search-sous\">${escapeAttr(it.sous || \"\")}</span>\n    </button>`).join(\"\")\n    : `<p class=\"log-empty\" style=\"padding:12px 4px;\">Aucun r\u00e9sultat \u2014 essayez un nom de sc\u00e9nario, d'essai, d'OP ou de projet.</p>`;\n  box.querySelectorAll(\".search-item\").forEach(b => b.addEventListener(\"click\", () => {\n    allerRecherche(parseInt(b.getAttribute(\"data-idx\"), 10));\n  }));\n}\nfunction allerRecherche(k){\n  const it = rechercheListe[k];\n  if(!it) return;\n  fermerPanneaux();\n  it.go();\n}\nfunction majSelRecherche(){\n  document.querySelectorAll(\"#searchResults .search-item\").forEach((b, k) => b.classList.toggle(\"sel\", k === rechercheSel));\n  const sel = document.querySelector(\"#searchResults .search-item.sel\");\n  if(sel) sel.scrollIntoView({ block: \"nearest\" });\n}\n\n/* (v4.13) renderReferences et renderOps supprim\u00e9s avec les rang\u00e9es de pastilles :\n   leurs s\u00e9lecteurs vivent d\u00e9sormais dans le menu du fil d'Ariane (ouvrirFilMenu). */\n\n/* ---- backlog : remontees de bugs/ameliorations par Matis/Arthur, voyage avec le fichier ---- */\nfunction backlogHTML(){\n  // carte pleine largeur par suggestion (plutot qu'une ligne de tableau) : la description\n  // etait coupee dans une cellule etroite, illisible pendant la saisie ; ici le texte a\n  // toute la largeur du panneau et grandit avec le contenu.\n  const cards = backlog.map(b => `\n    <div class=\"backlog-card\">\n      <div class=\"backlog-card-head\">\n        <input class=\"cell\" data-backlog=\"${b.id}\" data-field=\"date\" type=\"date\" value=\"${b.date ?? \"\"}\">\n        <input class=\"cell ref\" data-backlog=\"${b.id}\" data-field=\"auteur\" value=\"${escapeAttr(b.auteur)}\" placeholder=\"Nom\" style=\"max-width:120px;\">\n        <select class=\"backlog-type\" data-backlog=\"${b.id}\" data-field=\"type\">\n          <option value=\"bug\" ${b.type===\"bug\"?\"selected\":\"\"}>Bug</option>\n          <option value=\"amelioration\" ${b.type===\"amelioration\"?\"selected\":\"\"}>Am\u00e9lioration</option>\n          <option value=\"essai\" ${b.type===\"essai\"?\"selected\":\"\"}>Essai \u00e0 planifier</option>\n          <option value=\"technique\" ${b.type===\"technique\"?\"selected\":\"\"}>Sujet technique</option>\n        </select>\n        <select class=\"backlog-statut\" data-backlog=\"${b.id}\" data-field=\"statut\">\n          <option value=\"nouveau\" ${b.statut===\"nouveau\"?\"selected\":\"\"}>Nouveau</option>\n          <option value=\"encours\" ${b.statut===\"encours\"?\"selected\":\"\"}>En cours</option>\n          <option value=\"pret\" ${b.statut===\"pret\"?\"selected\":\"\"}>Pr\u00eat \u00e0 lancer</option>\n          <option value=\"lance\" ${b.statut===\"lance\"?\"selected\":\"\"}>Lanc\u00e9</option>\n          <option value=\"traite\" ${b.statut===\"traite\"?\"selected\":\"\"}>Clos</option>\n        </select>\n        <button class=\"log-del\" data-backlog-del=\"${b.id}\" style=\"margin-left:auto;\">\u2715</button>\n      </div>\n      <input class=\"cell ref backlog-titre\" data-backlog=\"${b.id}\" data-field=\"titre\" value=\"${escapeAttr(b.titre)}\" placeholder=\"Titre court\">\n      <input class=\"cell ref backlog-declencheur\" data-backlog=\"${b.id}\" data-field=\"declencheur\" value=\"${escapeAttr(b.declencheur || \"\")}\" placeholder=\"\u26a1 D\u00e9clencheur \u2014 ex. \u00ab \u00e0 lancer d\u00e8s un arr\u00eat de ligne EMAG 1 \u00bb\">\n      <textarea class=\"backlog-desc\" data-backlog=\"${b.id}\" data-field=\"description\" placeholder=\"Description, contexte, \u00e9tapes pour reproduire...\">${escapeAttr(b.description)}</textarea>\n      <div class=\"backlog-image-row\">\n        ${b.image\n          ? `<div class=\"backlog-image-preview\"><img src=\"${b.image}\" alt=\"\"><button class=\"ghost backlog-image-del\" data-backlog=\"${b.id}\">Retirer l'image</button></div>`\n          : `<label class=\"backlog-image-add\">\ud83d\udcf7 Joindre une image (capture d'\u00e9cran...)<input type=\"file\" accept=\"image/*\" class=\"backlog-image-input\" data-backlog=\"${b.id}\" hidden></label>`}\n      </div>\n    </div>\n  `).join(\"\") || `<p class=\"log-empty\">Aucune remont\u00e9e pour l'instant</p>`;\n\n  return `\n    <div class=\"backlog-block\">\n      <h3>Suggestions \u2014 vos id\u00e9es et remarques sur l'outil</h3>\n      <p class=\"hint\">Le pense-b\u00eate partag\u00e9 de l'\u00e9quipe : bugs et am\u00e9liorations de l'outil, <b>essais \u00e0 planifier</b> et <b>sujets techniques</b> abord\u00e9s ensemble \u2014 avec leur <b>d\u00e9clencheur</b> (\u00ab \u00e0 lancer d\u00e8s un arr\u00eat de ligne\u2026 \u00bb) pour anticiper au lieu de subir. Tout voyage avec le fichier synchronis\u00e9 : ce que l'un note, l'autre le voit \u00e0 l'ouverture.</p>\n      <div class=\"backlog-cards\">${cards}</div>\n      <button class=\"ghost\" id=\"backlogAddBtn\" style=\"margin-top:10px;\">+ Ajouter une suggestion</button>\n      <div class=\"panel-actions\"><button class=\"primary\" id=\"backlogClose\">Fermer</button></div>\n    </div>\n  `;\n}\nfunction renderBacklog(){\n  const wrap = document.getElementById(\"backlogWrap\");\n  if(!wrap || wrap.hidden) return;\n  wrap.innerHTML = backlogHTML();\n  wrap.querySelectorAll(\"input[data-backlog], select[data-backlog], textarea[data-backlog]\").forEach(inp => {\n    const evt = (inp.tagName === \"SELECT\") ? \"change\" : \"input\";\n    inp.addEventListener(evt, () => {\n      const b = backlog.find(x => x.id === inp.getAttribute(\"data-backlog\"));\n      if(!b) return;\n      b[inp.getAttribute(\"data-field\")] = inp.value;\n      saveData();\n    });\n    if(inp.tagName !== \"SELECT\"){\n      inp.addEventListener(\"blur\", () => renderBacklog());\n    }\n  });\n  // la description grandit avec le texte tape (jusqu'a une hauteur raisonnable), pour\n  // qu'on voie tout ce qu'on ecrit sans avoir a scroller dans un champ minuscule\n  wrap.querySelectorAll(\"textarea.backlog-desc\").forEach(ta => {\n    const grow = () => { ta.style.height = \"auto\"; ta.style.height = Math.min(ta.scrollHeight, 400) + \"px\"; };\n    ta.addEventListener(\"input\", grow);\n    grow();\n  });\n  wrap.querySelectorAll(\"[data-backlog-del]\").forEach(btn => {\n    btn.addEventListener(\"click\", () => {\n      backlog = backlog.filter(x => x.id !== btn.getAttribute(\"data-backlog-del\"));\n      saveData(); renderBacklog();\n    });\n  });\n  wrap.querySelectorAll(\".backlog-image-preview img\").forEach(img => {\n    img.addEventListener(\"click\", () => ouvrirLightbox(img.src));\n  });\n  wrap.querySelectorAll(\".backlog-image-input\").forEach(inp => {\n    inp.addEventListener(\"change\", () => {\n      const file = inp.files && inp.files[0];\n      if(!file) return;\n      const b = backlog.find(x => x.id === inp.getAttribute(\"data-backlog\"));\n      if(!b) return;\n      const img = new Image();\n      const reader = new FileReader();\n      reader.onload = () => {\n        img.onload = () => {\n          // redimensionne cote client avant stockage : une capture d'ecran brute peut peser\n          // plusieurs Mo, ce qui gonflerait vite le localStorage a plusieurs suggestions\n          const maxW = 1000;\n          const scale = Math.min(1, maxW / img.width);\n          const canvas = document.createElement(\"canvas\");\n          canvas.width = img.width * scale; canvas.height = img.height * scale;\n          canvas.getContext(\"2d\").drawImage(img, 0, 0, canvas.width, canvas.height);\n          b.image = canvas.toDataURL(\"image/jpeg\", 0.82);\n          saveData(); renderBacklog();\n        };\n        img.src = reader.result;\n      };\n      reader.readAsDataURL(file);\n    });\n  });\n  wrap.querySelectorAll(\".backlog-image-del\").forEach(btn => {\n    btn.addEventListener(\"click\", () => {\n      const b = backlog.find(x => x.id === btn.getAttribute(\"data-backlog\"));\n      if(!b) return;\n      b.image = \"\";\n      saveData(); renderBacklog();\n    });\n  });\n  const addBtn = document.getElementById(\"backlogAddBtn\");\n  if(addBtn) addBtn.addEventListener(\"click\", () => {\n    backlog.push({ id: \"b\"+Math.random().toString(36).slice(2), date: new Date().toISOString().slice(0,10),\n      auteur: auteurNom, type: \"amelioration\", titre: \"\", description: \"\", statut: \"nouveau\", image: \"\" });\n    saveData(); renderBacklog();\n  });\n  const closeBtn = document.getElementById(\"backlogClose\");\n  if(closeBtn) closeBtn.addEventListener(\"click\", fermerPanneaux);\n}\n\nfunction updateRevisionUI(){\n  const el = document.getElementById(\"revisionStatus\");\n  if(!el) return;\n  el.textContent = \"R\u00e9vision \" + revision;\n}\n\n/* le titre affiche (ecran + impression) suit la ligne/reference/OP reellement active :\n   l'outil gere desormais plusieurs lignes/references/OP en parallele, un intitule fige\n   (ex. \"OP10 \u2014 EMAG 1 \u2014 DV 356x26 RPI\") deviendrait vite incoherent avec ce qui est ouvert */\nfunction updateHeader(){\n  const l = getActiveLigne(), r = getActiveReference(), op = getActiveOp();\n  const pjFiltre = activeProjetId && projets.find(x => x.id === activeProjetId);\n  const eyebrow = [pjFiltre && pjFiltre.nom, l && l.nom, op && op.nom].filter(Boolean).join(\" \u2014 \")\n    || \"Suivi_optimisation_SPK \u2014 Am\u00e9lioration Process\";\n  const titre = (r && r.nom) || \"\";\n  const hdE = document.getElementById(\"hdEyebrow\"), hdT = document.getElementById(\"hdTitle\");\n  if(hdE) hdE.textContent = eyebrow;\n  if(hdT) hdT.textContent = titre || \"\u00a0\";\n  // v4.13 (CDC UX \u00a73.6) : le titre \u00e9cran tronque maintenant proprement (ellipse en CSS) ;\n  // l'info-bulle native porte le texte complet, un nom long ne d\u00e9bordait plus du cadre noir.\n  if(hdT) hdT.title = titre || \"\";\n  const prE = document.getElementById(\"printEyebrow\"), prT = document.getElementById(\"printTitle\");\n  if(prE) prE.textContent = eyebrow;\n  if(prT) prT.textContent = titre || \"\u00a0\";\n}\n/* ---- mode consultation : etat local au poste, jamais exporte ---------------------- */\nconst LOCK_KEY = \"spk_lecture_seule\";\nlet lectureSeule = (() => { try{ return localStorage.getItem(LOCK_KEY) === \"1\"; }catch(e){ return false; } })();\n\nfunction applyLockState(){\n  document.body.classList.toggle(\"locked\", lectureSeule);\n  const lbl = document.getElementById(\"lockLabel\");\n  if(lbl) lbl.textContent = lectureSeule ? \"D\u00e9verrouiller\" : \"Verrouiller\";\n  const btn = document.getElementById(\"lockBtn\");\n  if(btn) btn.title = lectureSeule\n    ? \"Saisie verrouill\u00e9e sur ce poste \u2014 cliquez pour pouvoir modifier\"\n    : \"Passe l'outil en lecture seule \u2014 pour l'\u00e9cran partag\u00e9 d'atelier\";\n  // le mode atelier garde sa saisie : on y entre volontairement, en plein ecran\n  document.querySelectorAll(\"input, textarea, select\").forEach(el => {\n    if(el.type === \"file\" || el.id === \"nvMasquer\" || el.closest(\".atelier\")) return;\n    if(el.tagName === \"SELECT\" || el.type === \"checkbox\" || el.type === \"radio\" || el.type === \"color\"){\n      el.disabled = lectureSeule;\n    } else {\n      el.readOnly = lectureSeule;\n    }\n  });\n}\nfunction toggleLock(){\n  lectureSeule = !lectureSeule;\n  try{ localStorage.setItem(LOCK_KEY, lectureSeule ? \"1\" : \"0\"); }catch(e){}\n  applyLockState();\n}\n\nfunction render(){\n  if(!data.find(s => s.id === activeId)) activeId = data[0] ? data[0].id : null;\n  // le filtre de projet (v4.3) peut masquer le scenario actuellement ouvert : on retombe\n  // sur le premier scenario encore visible, comme s'il avait ete supprime -- jamais un\n  // panneau de detail affichant un scenario que la liste dit ne pas montrer.\n  const visibles = scenariosVisibles();\n  if(visibles.length && !visibles.find(s => s.id === activeId)) activeId = visibles[0].id;\n  updateHeader();\n  updatePhotosDirUI();\n  renderProjets();\n  renderParcours();\n  renderFilAriane();\n  renderReprise();\n  renderTabs();\n  renderDetail();\n  // #scenarioAll (impression), #syntheseWrap et #backlogWrap ne sont pas visibles en usage\n  // normal : on ne les recalcule pas a chaque frappe, seulement quand ils sont reellement\n  // affiches (ouverture de la vue de synthese/backlog, panneau d'impression) - sinon la\n  // saisie devient lente.\n  renderSynthese();\n  renderBacklog();\n  applyLockState(); // le rendu recree les champs : l'etat de verrouillage doit etre re-applique\n  renderBandeauStockage();\n  if(typeof renduMigrBandeau === \"function\") renduMigrBandeau(); // v4.74 : le bandeau de migration suit l'etat des donnees\n  appliquerFondLigne(); // v4.27 : teinte + filigrane de la ligne affich\u00e9e\n}\n\nfunction attachDetailHandlers(sc){\n  const root = document.getElementById(\"scenarioDetail\");\n  /* v4.52 \u2014 retour carte atelier depuis la tra\u00e7abilit\u00e9 (A1 : jamais de cul-de-sac) */\n  const retourCarte = root.querySelector(\"#retourCarteBtn\");\n  if(retourCarte) retourCarte.addEventListener(\"click\", () => { renderCarte(); ouvrirPanneau(\"cartePanel\"); });\n  /* v4.74.3 \u2014 le dossier hi\u00e9rarchie depuis l'\u00e9cran de travail : Benjamin le\n     cherchait ici, il y vit d\u00e9sormais (la carte s'ouvre rendue, on y saute). */\n  const livrBtn = root.querySelector(\"#livraisonsBtn\");\n  if(livrBtn) livrBtn.addEventListener(\"click\", () => {\n    renderCarte(); ouvrirPanneau(\"cartePanel\");\n    const bloc = document.querySelector(\"#cartePanel .lv-bloc\");\n    if(bloc) bloc.scrollIntoView({ behavior: \"smooth\", block: \"start\" });\n  });\n  root.querySelectorAll(\"details.config-block[data-config-id]\").forEach(det => {\n    det.addEventListener(\"toggle\", () => {\n      const id = det.getAttribute(\"data-config-id\");\n      if(det.open) configReplies.delete(id); else configReplies.add(id);\n    });\n  });\n  root.querySelectorAll(\"details.outil-carte[data-outil-id]\").forEach(det => {\n    det.addEventListener(\"toggle\", () => {\n      const cle = sc.id + \"|\" + det.getAttribute(\"data-outil-id\");\n      if(det.open) outilsOuverts.add(cle); else outilsOuverts.delete(cle);\n    });\n    /* v4.19 \u2014 glisser-d\u00e9poser : la poign\u00e9e est le bandeau de la fiche (repli\u00e9e ou non).\n       Un simple clic ouvre toujours la fiche : le drag ne d\u00e9clenche pas de click. */\n    const som = det.querySelector(\".outil-sommaire\");\n    if(som){\n      som.setAttribute(\"draggable\", \"true\");\n      som.addEventListener(\"dragstart\", (e) => {\n        e.dataTransfer.setData(\"text/plain\", det.getAttribute(\"data-outil-id\"));\n        e.dataTransfer.effectAllowed = \"move\";\n        det.classList.add(\"drag-en-cours\");\n      });\n      som.addEventListener(\"dragend\", () => det.classList.remove(\"drag-en-cours\"));\n    }\n    det.addEventListener(\"dragover\", (e) => {\n      if(det.classList.contains(\"drag-en-cours\")) return;\n      e.preventDefault();\n      e.dataTransfer.dropEffect = \"move\";\n      det.classList.add(\"drag-cible\");\n    });\n    det.addEventListener(\"dragleave\", () => det.classList.remove(\"drag-cible\"));\n    det.addEventListener(\"drop\", (e) => {\n      e.preventDefault();\n      det.classList.remove(\"drag-cible\");\n      const srcId = e.dataTransfer.getData(\"text/plain\");\n      if(!srcId) return;\n      if(deplacerOutil(sc, srcId, det.getAttribute(\"data-outil-id\"))){ saveData(); render(); }\n    });\n  });\n  root.querySelectorAll(\"details.essai-card[data-essai-id]\").forEach(det => {\n    det.addEventListener(\"toggle\", () => {\n      const key = sc.id + \"|\" + det.getAttribute(\"data-essai-id\");\n      if(det.open) essaisOuverts.add(key);\n      else essaisOuverts.delete(key);\n    });\n  });\n  /* v4.30 \u2014 contexte d'essai : l'\u00e9tat ouvert/repli\u00e9 pos\u00e9 par l'utilisateur survit aux re-rendus */\n  root.querySelectorAll(\"details.essai-ctx[data-essai-id]\").forEach(det => {\n    det.addEventListener(\"toggle\", () => {\n      const cle = sc.id + \"|\" + det.getAttribute(\"data-essai-id\");\n      if(det.open) essaiCtxOuverts.add(cle); else essaiCtxOuverts.delete(cle);\n    });\n  });\n  root.querySelectorAll(\"input.cell, input.sc-name, input.cell-cycle, input.limit-label, input.limit-value, input.essai-obs, input.essai-but, select.log-equipe, select.statut-select, input.statut-motif, select.usure-select\").forEach(inp => {\n    inp.addEventListener(\"change\", onInputChange);\n    // a chaque caractere : on ecrit juste la valeur (pas de reconstruction de l'ecran).\n    // Reconstruire tout l'affichage a chaque frappe (badges, couts, graphique...) rendait\n    // la saisie au clavier physique instable : le focus se perdait en cours de frappe et\n    // un simple clic finissait par n'incrementer que les flechettes du champ nombre.\n    inp.addEventListener(\"input\", (e) => { if(e.target.type === \"number\") writeFieldValue(e.target); });\n  });\n  // remet les pr\u00e9l\u00e8vements dans l'ordre des n\u00b0 de pi\u00e8ce une fois la saisie termin\u00e9e\n  root.querySelectorAll('input[data-prel][data-field=\"piece\"]').forEach(inp => {\n    inp.addEventListener(\"blur\", () => {\n      const essaiId = inp.getAttribute(\"data-essai\");\n      const es = sc.essais.find(e => e.id === essaiId);\n      if(!es) return;\n      const avant = es.prelevements.map(r => r.id).join(\",\");\n      es.prelevements.sort((a,b) => {\n        const va = parseFloat(a.piece), vb = parseFloat(b.piece);\n        if(isNaN(va) && isNaN(vb)) return 0;\n        if(isNaN(va)) return 1;\n        if(isNaN(vb)) return -1;\n        return va - vb;\n      });\n      if(es.prelevements.map(r => r.id).join(\",\") !== avant){ saveData(); renderApresClic(); }\n    });\n  });\n  // v4.12 \u2014 champs d'une extraction Marposs (jour/d\u00e9but/fin) : cibl\u00e9s par extraction\n  const trouverExtraction = (es, exId) => (es.marpossListe || []).find(x => x.id === exId);\n  root.querySelectorAll('input[data-marposs-ex][data-marposs-field]').forEach(inp => {\n    inp.addEventListener(\"change\", () => {\n      const es = sc.essais.find(e => e.id === inp.getAttribute(\"data-essai\"));\n      const ex = es && trouverExtraction(es, inp.getAttribute(\"data-marposs-ex\"));\n      if(!ex) return;\n      ex[inp.getAttribute(\"data-marposs-field\")] = inp.value;\n      toucherEssai(es);\n      saveData(); render();\n    });\n  });\n  // case \u00ab inclure les graphes Marposs au rapport \u00bb : un seul drapeau pour tout l'essai\n  root.querySelectorAll('input[data-marposs-rapport]').forEach(inp => {\n    inp.addEventListener(\"change\", () => {\n      const es = sc.essais.find(e => e.id === inp.getAttribute(\"data-marposs-rapport\"));\n      if(!es) return;\n      es.marpossRapport = inp.checked;\n      toucherEssai(es);\n      saveData();\n    });\n  });\n  // + Ajouter une extraction (autre journ\u00e9e du m\u00eame essai)\n  root.querySelectorAll(\".marposs-add-ex\").forEach(btn => {\n    btn.addEventListener(\"click\", () => {\n      const es = sc.essais.find(e => e.id === btn.getAttribute(\"data-essai\"));\n      if(!es) return;\n      es.marpossListe = es.marpossListe || [];\n      es.marpossListe.push({ id: uid(\"mj\"), jour: es.dateFin || \"\", debut:\"\", fin:\"\", releves:[] });\n      toucherEssai(es);\n      saveData(); render();\n    });\n  });\n  // supprimer une extraction (les autres restent)\n  root.querySelectorAll(\".marposs-ex-del\").forEach(btn => {\n    btn.addEventListener(\"click\", () => {\n      const es = sc.essais.find(e => e.id === btn.getAttribute(\"data-essai\"));\n      const ex = es && trouverExtraction(es, btn.getAttribute(\"data-marposs-ex\"));\n      if(!ex) return;\n      const nom = (ex.jour ? \"du \" + ex.jour + \" \" : \"\") + \"(\" + (ex.releves||[]).length + \" relev\u00e9(s))\";\n      dialogueConfirmer(\"Supprimer cette extraction \" + nom + \" ?\\n\\nLes autres journ\u00e9es de l'essai ne sont pas touch\u00e9es.\", { titre: \"Supprimer l'extraction ?\", danger: (ex.releves||[]).length > 0, okLabel: \"Supprimer\" }).then(ok => {\n        if(!ok) return;\n        es.marpossListe = es.marpossListe.filter(x => x.id !== ex.id);\n        toucherEssai(es);\n        saveData(); render();\n      });\n    });\n  });\n  // v4.11 \u2014 s\u00e9lection des logements suivis par essai : \u2715 = ne plus suivre (le logement\n  // reste dans le sc\u00e9nario, ses pr\u00e9l\u00e8vements restent dans le tableau), et le s\u00e9lecteur\n  // \u00ab + suivre un logement \u00bb ram\u00e8ne un logement exclu ou ajoute un nouveau venu.\n  root.querySelectorAll(\".essai-lp-del\").forEach(btn => {\n    btn.addEventListener(\"click\", () => {\n      const es = sc.essais.find(e => e.id === btn.getAttribute(\"data-essai\"));\n      if(!es || !es.params) return;\n      const lp = (es.params.logements||[]).find(x => x.logementId === btn.getAttribute(\"data-lp\"));\n      if(!lp) return;\n      const nom = (lp.outilNumero||\"?\") + \" \u00b7 \" + (lp.logementNom||\"\u2014\");\n      const nbPrels = (es.prelevements||[]).filter(r => r.logementId === lp.logementId).length;\n      dialogueConfirmer(\"Ne plus suivre \u00ab \" + nom + \" \u00bb dans cet essai ?\" +\n        (nbPrels ? \"\\n\\n\" + nbPrels + \" pr\u00e9l\u00e8vement(s) lui sont attribu\u00e9(s) : ils restent dans le tableau mais ne compteront plus dans la progression de ce logement.\" : \"\") +\n        \"\\n\\nLe logement reste dans le sc\u00e9nario \u2014 re-suivable \u00e0 tout moment via \u00ab + suivre un logement \u00bb.\",\n        { titre: \"Ne plus suivre ce logement ?\", danger: nbPrels > 0, okLabel: \"Ne plus suivre\" }).then(ok => {\n        if(!ok) return;\n        lp.suivi = false; // l'instantan\u00e9 reste : re-cocher restitue les conditions d'origine\n        toucherEssai(es);\n        saveData(); render();\n      });\n    });\n  });\n  root.querySelectorAll(\"select.essai-lp-add\").forEach(sel => {\n    sel.addEventListener(\"change\", () => {\n      const lid = sel.value;\n      if(!lid) return;\n      const es = sc.essais.find(e => e.id === sel.getAttribute(\"data-essai\"));\n      if(!es || !es.params) return;\n      es.params.logements = es.params.logements || [];\n      const deja = es.params.logements.find(x => x.logementId === lid);\n      if(deja){\n        deja.suivi = true; // re-coche avec son instantan\u00e9 d'origine\n      } else {\n        const courant = snapshotLogements(sc).find(c => c.logementId === lid);\n        if(courant) es.params.logements.push(Object.assign({ suivi: true }, courant));\n      }\n      toucherEssai(es);\n      saveData(); render();\n    });\n  });\n  // v4.9.1 : l'heure de d\u00e9but/fin de l'essai pr\u00e9-remplit la fen\u00eatre de la PREMI\u00c8RE\n  // extraction Marposs si elle est encore vide (une seule saisie en pratique ; la fen\u00eatre\n  // reste modifiable s\u00e9par\u00e9ment \u2014 la machine, elle, contr\u00f4le toute la journ\u00e9e)\n  root.querySelectorAll('input[data-field=\"heureDebut\"], input[data-field=\"heureFin\"]').forEach(inp => {\n    inp.addEventListener(\"change\", () => {\n      const es = sc.essais.find(e => e.id === inp.getAttribute(\"data-essai\"));\n      if(!es) return;\n      if(!Array.isArray(es.marpossListe) || !es.marpossListe.length) es.marpossListe = [{ id:\"mj1\", jour:\"\", debut:\"\", fin:\"\", releves:[] }];\n      const ex1 = es.marpossListe[0];\n      // lire l'INPUT et pas le mod\u00e8le : ce listener peut partir avant le c\u00e2blage g\u00e9n\u00e9rique\n      const v = (inp.value || \"\").trim();\n      let rempli = false;\n      if(v && inp.getAttribute(\"data-field\") === \"heureDebut\" && !ex1.debut){ ex1.debut = v; rempli = true; }\n      if(v && inp.getAttribute(\"data-field\") === \"heureFin\" && !ex1.fin){ ex1.fin = v; rempli = true; }\n      if(rempli){ saveData(); render(); }\n    });\n  });\n  root.querySelectorAll(\".marposs-import\").forEach(btn => {\n    btn.addEventListener(\"click\", () => {\n      const exId = btn.getAttribute(\"data-marposs-ex\");\n      const es = sc.essais.find(e => (e.marpossListe||[]).some(x => x.id === exId));\n      const ta = root.querySelector(`.marposs-paste[data-marposs-ex=\"${exId}\"]`);\n      if(!es || !ta) return;\n      const { rows, ignorees } = parseMarpossPaste(ta.value);\n      if(!rows.length){ dialogueAlerte(\"Aucune ligne valide reconnue dans le collage (attendu : heure puis valeur, s\u00e9par\u00e9es par une tabulation).\", \"Collage non reconnu\"); return; }\n      const ex = trouverExtraction(es, exId);\n      ex.releves = rows;\n      toucherEssai(es);\n      saveData(); render();\n      dialogueAlerte(rows.length + \" relev\u00e9(s) import\u00e9(s)\" + (ignorees ? \", \" + ignorees + \" ligne(s) ignor\u00e9e(s) (non reconnue(s)).\" : \".\"), \"Relev\u00e9s Marposs import\u00e9s\");\n    });\n  });\n  root.querySelectorAll(\".marposs-clear\").forEach(btn => {\n    btn.addEventListener(\"click\", () => {\n      const exId = btn.getAttribute(\"data-marposs-ex\");\n      const es = sc.essais.find(e => (e.marpossListe||[]).some(x => x.id === exId));\n      const ex = es && (es.marpossListe||[]).find(x => x.id === exId);\n      if(!ex) return;\n      dialogueConfirmer(\"Vider les \" + (ex.releves||[]).length + \" relev\u00e9(s) de cette extraction ?\", { titre: \"Vider les relev\u00e9s ?\", danger: true, okLabel: \"Vider\" }).then(ok => {\n        if(!ok) return;\n        ex.releves = [];\n        toucherEssai(es);\n        saveData(); render();\n      });\n    });\n  });\n  root.querySelectorAll(\".photos-connect-btn\").forEach(btn => btn.addEventListener(\"click\", connectPhotosDir));\n  root.querySelectorAll(\".photo-input\").forEach(inp => {\n    inp.addEventListener(\"change\", async () => {\n      const essaiId = inp.getAttribute(\"data-essai\");\n      const es = sc.essais.find(e => e.id === essaiId);\n      // v4.16 : dossier local prioritaire ; sans dossier, les photos partent dans le\n      // cloud priv\u00e9 (bucket `photos`, comptes de l'\u00e9quipe) et voyagent avec le suivi.\n      const versCloud = !photosDirHandle && !!cloudSession;\n      if(!es || (!photosDirHandle && !versCloud)) return;\n      if(!es.photos) es.photos = [];\n      const files = [...inp.files];\n      for(const file of files){\n        try{\n          const blob = await compressImageFile(file, 1600, 0.82);\n          const stamp = Date.now() + \"-\" + Math.random().toString(36).slice(2,6);\n          let filename, photo;\n          if(photosDirHandle){\n            filename = slugify(sc.name) + \"_\" + slugify(es.titre) + \"_\" + stamp + \".jpg\";\n            await writePhotoBlob(filename, blob);\n            photo = { id: \"ph\"+Math.random().toString(36).slice(2), filename, addedAt: new Date().toISOString(), legende:\"\", crop:null, annotations:[], stockage:\"dossier\" };\n          } else {\n            filename = essaiId + \"/\" + stamp + \".jpg\";\n            await cloudPhotoEnvoyer(filename, blob);\n            photo = { id: \"ph\"+Math.random().toString(36).slice(2), filename, addedAt: new Date().toISOString(), legende:\"\", crop:null, annotations:[], stockage:\"cloud\" };\n          }\n          es.photos.push(photo);\n        }catch(err){ dialogueAlerte(\"\u00c9chec de l'enregistrement d'une photo : \" + err.message, \"\u00c9chec d'enregistrement\"); }\n      }\n      saveData(); render();\n    });\n  });\n  root.querySelectorAll(\".photo-del\").forEach(btn => {\n    btn.addEventListener(\"click\", async () => {\n      const essaiId = btn.getAttribute(\"data-essai\"), photoId = btn.getAttribute(\"data-photo\");\n      const es = sc.essais.find(e => e.id === essaiId);\n      if(!es) return;\n      const p = (es.photos||[]).find(x => x.id === photoId);\n      if(!p) return;\n      dialogueConfirmer(\"Supprimer cette photo ?\", { titre: \"Supprimer la photo ?\", danger: true, okLabel: \"Supprimer\" }).then(async ok => {\n        if(!ok) return;\n        if(p.stockage === \"cloud\"){\n          await cloudPhotoSupprimer(p.filename); // retire le fichier du bucket + le cache\n        } else if(photosDirHandle){\n          await deletePhotoFile(p.filename);\n        }\n        es.photos = es.photos.filter(x => x.id !== photoId);\n        saveData(); render();\n      });\n    });\n  });\n  root.querySelectorAll(\".photo-legende\").forEach(inp => {\n    inp.addEventListener(\"blur\", () => {\n      const essaiId = inp.getAttribute(\"data-essai\"), photoId = inp.getAttribute(\"data-photo\");\n      const es = sc.essais.find(e => e.id === essaiId);\n      const p = es && (es.photos||[]).find(x => x.id === photoId);\n      if(p){ p.legende = inp.value; saveData(); }\n    });\n  });\n  root.querySelectorAll(\".photo-annot\").forEach(btn => {\n    btn.addEventListener(\"click\", () => openPhotoAnnotator(btn.getAttribute(\"data-essai\"), btn.getAttribute(\"data-photo\")));\n  });\n  root.querySelectorAll(\"img[data-photo-filename]\").forEach(img => {\n    img.addEventListener(\"click\", () => {\n      const wrap = img.closest(\".photo-thumb\");\n      const annotBtn = wrap && wrap.querySelector(\".photo-annot\");\n      if(annotBtn) openAnnotatedLightbox(annotBtn.getAttribute(\"data-essai\"), annotBtn.getAttribute(\"data-photo\"));\n    });\n  });\n  root.querySelectorAll('input[data-field=\"emag1\"]').forEach(inp => {\n    inp.addEventListener(\"change\", () => { sc.emag1 = inp.checked; saveData(); render(); });\n  });\n  root.querySelectorAll('input[data-field=\"limitOverride\"]').forEach(inp => {\n    inp.addEventListener(\"change\", () => {\n      sc.limitOverride = inp.checked;\n      if(inp.checked){ sc.limitLabel = config.limitLabel; sc.limitValue = config.limitValue; }\n      saveData(); render();\n    });\n  });\n  root.querySelectorAll('input[data-field=\"critere2Actif\"]').forEach(inp => {\n    inp.addEventListener(\"change\", () => {\n      sc.critere2Actif = inp.checked;\n      saveData(); render();\n    });\n  });\n  // v4.9 \u2014 crit\u00e8res du bloc Essais : battement on/off, c\u00f4t\u00e9s, tol\u00e9rance \u00e9dit\u00e9e sur place\n  // (l'\u00e9dition pose la sp\u00e9cificit\u00e9 au sc\u00e9nario, plus besoin de cocher au pr\u00e9alable),\n  // crit\u00e8res suppl\u00e9mentaires (label, bornes, axes, ajout, suppression).\n  root.querySelectorAll('input[data-field=\"battActif\"]').forEach(inp => {\n    inp.addEventListener(\"change\", () => { sc.battActif = inp.checked; saveData(); render(); });\n  });\n  root.querySelectorAll('input[data-field=\"tendanceRapport\"]').forEach(inp => {\n    inp.addEventListener(\"change\", () => { sc.tendanceRapport = inp.checked; saveData(); });\n  });\n  root.querySelectorAll('select[data-field=\"battCotes\"]').forEach(sel => {\n    sel.addEventListener(\"change\", () => { sc.battCotes = sel.value; saveData(); render(); });\n  });\n  /* v4.41 \u2014 case \u00ab tourne en simultan\u00e9 avec l'outil pr\u00e9c\u00e9dent \u00bb : regroupe les outils,\n     le cycle vaut la somme des groupes (chaque groupe = son outil le plus long) */\n  root.querySelectorAll('input[data-ofield=\"simultaneAvecPrecedent\"]').forEach(inp => {\n    inp.addEventListener(\"change\", () => {\n      const o = (sc.outils||[]).find(x => x.id === inp.getAttribute(\"data-outil\"));\n      if(!o) return;\n      o.simultaneAvecPrecedent = inp.checked;\n      saveData(); render();\n    });\n  });\n  root.querySelectorAll('input[data-field=\"limitLabel\"], input[data-field=\"limitValue\"]').forEach(inp => {\n    inp.addEventListener(\"change\", () => {\n      if(!sc.limitOverride) sc.limitOverride = true;\n      const lab = root.querySelector('input[data-field=\"limitLabel\"]');\n      const val = root.querySelector('input[data-field=\"limitValue\"]');\n      if(lab) sc.limitLabel = lab.value;\n      if(val) sc.limitValue = val.value === \"\" ? \"\" : parseFloat(val.value);\n      saveData(); render();\n    });\n  });\n  root.querySelectorAll('[data-csup][data-csfield]').forEach(inp => {\n    const apply = () => {\n      const c = (sc.criteresSup || []).find(x => x.id === inp.getAttribute(\"data-csup\"));\n      if(!c) return;\n      const f = inp.getAttribute(\"data-csfield\");\n      if(f === \"actif\" || f === \"miniActif\") c[f] = inp.checked;\n      else if(f === \"axe\"){\n        const ax = inp.getAttribute(\"data-axe\");\n        c.axes = c.axes || [];\n        const i = c.axes.indexOf(ax);\n        if(inp.checked && i === -1) c.axes.push(ax);\n        if(!inp.checked && i !== -1) c.axes.splice(i, 1);\n      }\n      else if(f === \"maxi\" || f === \"mini\") c[f] = inp.value === \"\" ? \"\" : parseFloat(inp.value);\n      else c[f] = inp.value;\n      saveData();\n      // les axes changent les colonnes du tableau : reconstruction, mais pas \u00e0 chaque frappe\n      if(f === \"axe\" || f === \"actif\" || f === \"miniActif\") render();\n    };\n    inp.addEventListener(\"change\", apply);\n    if(inp.getAttribute(\"data-csfield\") === \"label\") inp.addEventListener(\"input\", apply);\n  });\n  root.querySelectorAll(\".csup-del\").forEach(btn => {\n    btn.addEventListener(\"click\", () => {\n      const cid = btn.getAttribute(\"data-csup\");\n      const c = (sc.criteresSup || []).find(x => x.id === cid);\n      dialogueConfirmer(\"Supprimer le crit\u00e8re \u00ab \" + ((c && c.label) || \"?\") + \" \u00bb ?\\n\\nLes valeurs d\u00e9j\u00e0 saisies pour ce crit\u00e8re restent dans les donn\u00e9es mais ne sont plus affich\u00e9es ni \u00e9valu\u00e9es.\", { titre: \"Supprimer le crit\u00e8re ?\", danger: true, okLabel: \"Supprimer\" }).then(ok => {\n        if(!ok) return;\n        sc.criteresSup = (sc.criteresSup || []).filter(x => x.id !== cid);\n        saveData(); render();\n      });\n    });\n  });\n  root.querySelectorAll(\".csup-add\").forEach(btn => {\n    btn.addEventListener(\"click\", () => {\n      const type = btn.getAttribute(\"data-cstype\");\n      sc.criteresSup = sc.criteresSup || [];\n      if(type === \"libre\"){\n        dialogueDemander(\"Nom du crit\u00e8re (ex. \u00ab Concentricit\u00e9 (mm) \u00bb) :\", \"\", { titre: \"Nouveau crit\u00e8re\", okLabel: \"Cr\u00e9er\" }).then(nom => {\n          if(nom === null || !nom.trim()) return;\n          sc.criteresSup.push({ id: uid(\"cs\"), label: nom.trim(), maxi: \"\", miniActif:false, mini:\"\", axes:[], actif:true });\n          saveData(); render();\n        });\n        return;\n      }\n      const def = type === \"ra\"\n        ? { label: \"Ra (\u00b5m)\", maxi: \"\", axes: [\"I\",\"E\"] }\n        : { label: \"VE (mm)\", maxi: \"\", axes: [\"D\",\"G\"] };\n      sc.criteresSup.push(Object.assign({ id: uid(\"cs\"), miniActif:false, mini:\"\", actif:true }, def));\n      saveData(); render();\n    });\n  });\n  root.querySelectorAll('input[data-field=\"suiviTolerance\"]').forEach(inp => {\n    inp.addEventListener(\"change\", () => {\n      const outilId = inp.getAttribute(\"data-outil\"), logementId = inp.getAttribute(\"data-logement\");\n      const o = sc.outils.find(x => x.id === outilId);\n      const l = o && o.logements.find(x => x.id === logementId);\n      if(l){ l.suiviTolerance = inp.checked; saveData(); render(); }\n    });\n  });\n  root.querySelectorAll(\".params-sync\").forEach(el => {\n    el.addEventListener(\"click\", () => {\n      const es = sc.essais.find(e => e.id === el.getAttribute(\"data-essai\"));\n      if(!es) return;\n      dialogueConfirmer(\"Aligner \u00ab \" + es.titre + \" \u00bb sur les conditions actuelles du sc\u00e9nario ?\\n\\n\u00c0 ne faire que si cet essai a r\u00e9ellement \u00e9t\u00e9 men\u00e9 avec ces param\u00e8tres.\", { titre: \"Aligner sur le sc\u00e9nario ?\", okLabel: \"Aligner\" }).then(ok => {\n        if(!ok) return;\n        es.params = { logements: snapshotLogements(sc) };\n        saveData(); render();\n      });\n    });\n  });\n  root.querySelectorAll('[data-action=\"baseline\"]').forEach(el => {\n    el.addEventListener(\"click\", () => {\n      promouvoirEnProduction(sc).then(ok => {\n        if(!ok) return; // annule : rien n'a bouge\n        recomputeCycles(); saveData(); render();\n      });\n    });\n  });\n  root.querySelectorAll('[data-action=\"duplicate\"]').forEach(el => {\n    el.addEventListener(\"click\", () => {\n      const copy = JSON.parse(JSON.stringify(sc));\n      copy.id = uid(\"s\");\n      copy.name = sc.name + \" (copie)\";\n      copy.baseline = false;\n      // nouveaux ids pour les outils/logements de la copie, et on reporte la correspondance\n      // ancien->nouveau id dans les instantanes d'essai geles (params.logements)\n      const idMap = {};\n      copy.outils = (copy.outils||[]).map(o => {\n        const newOutilId = \"t\"+Math.random().toString(36).slice(2);\n        idMap[o.id] = newOutilId;\n        return Object.assign({}, o, { id: newOutilId, logements: (o.logements||[]).map(l => {\n          const newLogementId = \"g\"+Math.random().toString(36).slice(2);\n          idMap[l.id] = newLogementId;\n          return Object.assign({}, l, { id: newLogementId });\n        }) });\n      });\n      copy.essais = (copy.essais||[]).map(es => Object.assign({}, es, {\n        id: \"e\"+Math.random().toString(36).slice(2),\n        params: { logements: ((es.params && es.params.logements) || []).map(lp => Object.assign({}, lp, {\n          outilId: idMap[lp.outilId] || lp.outilId, logementId: idMap[lp.logementId] || lp.logementId\n        })) },\n        prelevements: (es.prelevements||[]).map(r => Object.assign({}, r, { id: \"p\"+Math.random().toString(36).slice(2) }))\n      }));\n      const idx = data.findIndex(s => s.id === sc.id);\n      data.splice(idx + 1, 0, copy);\n      activeId = copy.id;\n      // la copie herite des projets de l'original : dupliquer un scenario pour tester une\n      // variante ne doit pas le faire sortir silencieusement de sa campagne\n      projets.forEach(pj => {\n        if(projetContientScenario(pj, activeLigneId, activeReferenceId, activeOpId, sc.id)){\n          toggleTagScenario(pj, activeLigneId, activeReferenceId, activeOpId, copy.id);\n        }\n      });\n      saveData(); render();\n    });\n  });\n  root.querySelectorAll('[data-action=\"delete\"]').forEach(el => {\n    el.addEventListener(\"click\", () => {\n      if(data.length <= 1) return;\n      const n = (sc.essais||[]).length;\n      dialogueConfirmer(\"Supprimer le sc\u00e9nario \u00ab \" + sc.name + \" \u00bb ?\" + (n ? \"\\n\\nIl contient \" + n + \" essai(s) qui seront perdus.\" : \"\"), { titre: \"Supprimer le sc\u00e9nario ?\", danger: true, okLabel: \"Supprimer\" }).then(ok => {\n        if(!ok) return;\n        const wasBaseline = sc.baseline;\n        data = data.filter(s => s.id !== sc.id);\n        if(wasBaseline && data.length) data[0].baseline = true;\n        activeId = data[0] ? data[0].id : null;\n        saveData(); render();\n      });\n    });\n  });\n  root.querySelectorAll(\".essai-add\").forEach(el => {\n    el.addEventListener(\"click\", () => {\n      const today = new Date().toISOString().slice(0,10);\n      sc.essais = sc.essais || [];\n      const nouvelId = \"e\"+Math.random().toString(36).slice(2);\n      sc.essais.push({ id: nouvelId, titre: \"Essai \" + (sc.essais.length+1),\n        date: today, equipe: \"\", operateur: \"\", but: \"\", observations: \"\", maturiteBruts: \"\",\n        params: { logements: snapshotLogements(sc) },\n        marposs: { debut:\"\", fin:\"\", releves:[] },\n        photos: [],\n        prelevements: [],\n        modifieLe: new Date().toISOString() });\n      // le nouvel essai s'ouvre deplie (saisie immediate) ; les autres restent en tuile\n      essaisOuverts.add(sc.id + \"|\" + nouvelId);\n      saveData(); render();\n      const det = document.querySelector(`details.essai-card[data-essai-id=\"${nouvelId}\"]`);\n      if(det) det.scrollIntoView({block:\"center\", behavior:\"smooth\"});\n    });\n  });\n  root.querySelectorAll(\".essai-del\").forEach(el => {\n    el.addEventListener(\"click\", () => {\n      const essaiId = el.getAttribute(\"data-essai\");\n      const es = sc.essais.find(e => e.id === essaiId);\n      const n = es ? (es.prelevements||[]).length : 0;\n      dialogueConfirmer(\"Supprimer l'essai \u00ab \" + (es ? es.titre : \"\") + \" \u00bb ?\" + (n ? \"\\n\\nSes \" + n + \" pr\u00e9l\u00e8vement(s) seront perdus.\" : \"\"), { titre: \"Supprimer l'essai ?\", danger: true, okLabel: \"Supprimer\" }).then(ok => {\n        if(!ok) return;\n        sc.essais = sc.essais.filter(e => e.id !== essaiId);\n        essaisOuverts.delete(sc.id + \"|\" + essaiId);\n        saveData(); render();\n      });\n    });\n  });\n  root.querySelectorAll(\".atelier-open\").forEach(el => {\n    el.addEventListener(\"click\", () => ouvrirAtelier(el.getAttribute(\"data-id\"), el.getAttribute(\"data-essai\")));\n  });\n  root.querySelectorAll(\".essai-rapport\").forEach(el => {\n    el.addEventListener(\"click\", () => {\n      const es = sc.essais.find(e => e.id === el.getAttribute(\"data-essai\"));\n      if(es) telechargerRapportEssai(sc, es);\n    });\n  });\n  // v4.15 \u2014 comparaison de deux essais + bascule des tendances en % de tol\u00e9rance\n  root.querySelectorAll(\".essai-comparer\").forEach(el => {\n    el.addEventListener(\"click\", () => ouvrirComparaison(el.getAttribute(\"data-id\"), el.getAttribute(\"data-essai\")));\n  });\n  root.querySelectorAll(\".pct-toggle\").forEach(el => {\n    el.addEventListener(\"click\", () => { tendanceEnPct = !tendanceEnPct; renderDetail(); });\n  });\n  root.querySelectorAll(\".prel-add\").forEach(el => {\n    el.addEventListener(\"click\", () => {\n      const essaiId = el.getAttribute(\"data-essai\");\n      const es = sc.essais.find(e => e.id === essaiId);\n      if(es){\n        es.prelevements.push({ id: \"p\"+Math.random().toString(36).slice(2), piece: \"\", batt: \"\", battD: \"\", battG: \"\", logementId: \"\", pointMesure: \"\" });\n        toucherEssai(es);\n        saveData(); render();\n      }\n    });\n  });\n  root.querySelectorAll(\".prel-del\").forEach(el => {\n    el.addEventListener(\"click\", () => {\n      const essaiId = el.getAttribute(\"data-essai\");\n      const prelId = el.getAttribute(\"data-prel\");\n      const es = sc.essais.find(e => e.id === essaiId);\n      if(es){\n        es.prelevements = es.prelevements.filter(r => r.id !== prelId);\n        toucherEssai(es);\n        saveData(); render();\n      }\n    });\n  });\n  /* Plan d'outil. Le dossier local est prefere des qu'il est connecte : un plan de montage\n     pese couramment 1 a 2 Mo, et localStorage plafonne autour de 5 Mo pour TOUT le suivi \u2014\n     deux plans integres au fichier suffiraient a le saturer. Sans dossier, on accepte quand\n     meme les petits fichiers (< 500 ko) pour que la fonction reste utilisable, et on explique\n     pourquoi on refuse les autres. */\n  root.querySelectorAll(\".plan-input\").forEach(el => {\n    el.addEventListener(\"change\", async (e) => {\n      const file = e.target.files && e.target.files[0];\n      if(!file) return;\n      const o = sc.outils.find(x => x.id === el.getAttribute(\"data-outil\"));\n      if(!o) return;\n      const pj = await attacherPieceJointe(file, \"plan_\" + slugify(sc.name) + \"_\" + slugify(o.numero || \"outil\"));\n      el.value = \"\";\n      if(!pj) return;\n      o.plan = pj;\n      saveData(); render();\n    });\n  });\n  root.querySelectorAll(\".plan-open\").forEach(el => {\n    el.addEventListener(\"click\", () => {\n      const o = sc.outils.find(x => x.id === el.getAttribute(\"data-outil\"));\n      if(o) ouvrirPieceJointe(o.plan);\n    });\n  });\n  root.querySelectorAll(\".plan-del\").forEach(el => {\n    el.addEventListener(\"click\", () => {\n      const o = sc.outils.find(x => x.id === el.getAttribute(\"data-outil\"));\n      if(!o || !o.plan) return;\n      dialogueConfirmer(\"Retirer le plan de cet outil ?\" + (o.plan.stockage === \"dossier\" ? `\n\nLe fichier reste dans le dossier local, seul le lien est supprim\u00e9.` : \"\"), { titre: \"Retirer le plan ?\", danger: true, okLabel: \"Retirer\" }).then(ok => {\n        if(!ok) return;\n        o.plan = null; saveData(); render();\n      });\n    });\n  });\n  root.querySelectorAll(\".outil-add\").forEach(el => {\n    el.addEventListener(\"click\", () => {\n      sc.outils.push({ id: \"t\"+Math.random().toString(36).slice(2), numero: \"\", logements: [ normalizeLogement({ nom: \"Logement 1\" }) ] });\n      saveData(); render();\n    });\n  });\n  /* v4.22 \u2014 copie des outils du scenario de production, par selection */\n  root.querySelectorAll(\".outils-copier\").forEach(el => {\n    el.addEventListener(\"click\", () => { ouvrirPanneau(\"copieOutilsPanel\"); renderCopieOutilsPanel(); });\n  });\n  /* v4.48 \u2014 compl\u00e9ter depuis la prod (base excel) : ajout SEUL, jamais de remplacement */\n  root.querySelectorAll(\".outils-completer\").forEach(el => {\n    el.addEventListener(\"click\", () => {\n      const manquants = outilsManquants(sc);\n      if(!manquants.length) return;\n      const liste = manquants.map(t => \"\\u00b7 \" + (t.numero || \"outil sans n\\u00b0\") + ((t.logements||[]).length > 1 ? \" (\" + t.logements.length + \" logements)\" : \"\")).join(\"\\n\");\n      dialogueConfirmer(\"Compl\\u00e9ter ce sc\\u00e9nario avec \" + manquants.length + \" outil(s) de la prod (base excel) ?\\n\\n\" + liste + \"\\n\\nVos outils d'essai gardent leurs conditions \u2014 seuls les outils manquants sont ajout\u00e9s, tels qu'ils tournent en prod. Les essais, pr\u00e9l\u00e8vements et photos enregistr\u00e9s ne sont pas touch\u00e9s.\",\n        { titre: \"Compl\u00e9ter depuis la prod ?\", okLabel: \"Compl\u00e9ter\" }).then(ok => {\n        if(!ok) return;\n        manquants.forEach(src => {\n          const copie = JSON.parse(JSON.stringify(src));\n          copie.id = \"t\" + Math.random().toString(36).slice(2);\n          copie.plan = null;\n          copie.logements = (copie.logements || []).map(l => Object.assign(l, { id: \"g\" + Math.random().toString(36).slice(2) }));\n          copie.pieces = (copie.pieces || []).map(pc => Object.assign(pc, { id: \"pc\" + Math.random().toString(36).slice(2) }));\n          sc.outils.push(copie);\n        });\n        saveData(); render();\n      });\n    });\n  });\n\n  /* v4.25 \u2014 cl\u00f4ture d'essai (arr\u00eat anticip\u00e9) */\n  root.querySelectorAll(\".essai-cloture\").forEach(el => {\n    el.addEventListener(\"click\", () => {\n      clotureCtx = { scId: el.getAttribute(\"data-id\"), essaiId: el.getAttribute(\"data-essai\") };\n      ouvrirPanneau(\"cloturePanel\"); renderCloturePanel();\n    });\n  });\n  /* v4.28 \u2014 d\u00e9tail du calcul du co\u00fbt annuel, d\u00e9pliable au clic sur la tuile */\n  root.querySelectorAll(\".ap-tuile[data-cle-detail]\").forEach(tuile => {\n    tuile.addEventListener(\"click\", () => {\n      const cle = tuile.getAttribute(\"data-cle-detail\");\n      const det = tuile.querySelector(\".ap-detail\");\n      if(!det) return;\n      if(det.hidden){ det.hidden = false; apDetailsOuverts.add(cle); }\n      else { det.hidden = true; apDetailsOuverts.delete(cle); }\n    });\n  });\n  /* v4.29 \u2014 d\u00e9tail du co\u00fbt annuel G\u00c9N\u00c9RAL (pied de sc\u00e9nario) */\n  root.querySelectorAll(\".foot-cell-annuel\").forEach(cell => {\n    cell.addEventListener(\"click\", () => {\n      coutAnnuelDetailOuvert = !coutAnnuelDetailOuvert;\n      const det = root.querySelector(\".foot-detail\");\n      if(det) det.hidden = !coutAnnuelDetailOuvert;\n      cell.classList.toggle(\"ouvert\", coutAnnuelDetailOuvert);\n    });\n  });\n  /* v4.23 \u2014 la tuile du volume annuel emm\u00e8ne au bon champ : Options, pr\u00e9-rempli pour LA\n     r\u00e9f\u00e9rence affich\u00e9e. Un seul geste, aucune ambigu\u00eft\u00e9 sur la cible. */\n  root.querySelectorAll(\".volume-bandeau.clickable\").forEach(el => {\n    el.addEventListener(\"click\", () => {\n      ouvrirPanneau(\"optionsPanel\"); syncOptionsUI();\n      const f = document.getElementById(\"optProductionAnnuelle\");\n      if(f) f.focus();\n    });\n  });\n  root.querySelectorAll(\".logement-add\").forEach(el => {\n    el.addEventListener(\"click\", () => {\n      const o = sc.outils.find(x => x.id === el.getAttribute(\"data-outil\"));\n      if(!o) return;\n      o.logements.push(normalizeLogement({ nom: \"Logement \" + (o.logements.length+1) }));\n      saveData(); render();\n    });\n  });\n  root.querySelectorAll(\".piece-add\").forEach(el => {\n    el.addEventListener(\"click\", () => {\n      const o = sc.outils.find(x => x.id === el.getAttribute(\"data-outil\"));\n      if(!o) return;\n      o.pieces = o.pieces || [];\n      o.pieces.push(normalizePieceDetachee({}));\n      saveData(); render();\n    });\n  });\n  root.querySelectorAll(\".piece-del\").forEach(el => {\n    el.addEventListener(\"click\", () => {\n      const o = sc.outils.find(x => x.id === el.getAttribute(\"data-outil\"));\n      if(!o) return;\n      o.pieces = (o.pieces||[]).filter(x => x.id !== el.getAttribute(\"data-piece\"));\n      saveData(); render();\n    });\n  });\n  root.querySelectorAll(\".logement-del\").forEach(el => {\n    el.addEventListener(\"click\", () => {\n      const outilId = el.getAttribute(\"data-outil\"), logementId = el.getAttribute(\"data-logement\");\n      const o = sc.outils.find(x => x.id === outilId);\n      if(!o) return;\n      dialogueConfirmer(\"Supprimer ce logement ?\", { titre: \"Supprimer le logement ?\", danger: true, okLabel: \"Supprimer\" }).then(ok => {\n        if(!ok) return;\n        o.logements = o.logements.filter(x => x.id !== logementId);\n        if(!o.logements.length) sc.outils = sc.outils.filter(x => x.id !== outilId);\n        saveData(); render();\n      });\n    });\n  });\n  // saisie rapide : Entree dans la derniere ligne d'un essai cree une nouvelle ligne et y place le focus\n  root.querySelectorAll('input[data-prel]').forEach(inp => {\n    inp.addEventListener(\"keydown\", (e) => {\n      if(e.key !== \"Enter\") return;\n      const essaiId = inp.getAttribute(\"data-essai\");\n      const prelId = inp.getAttribute(\"data-prel\");\n      const es = sc.essais.find(x => x.id === essaiId);\n      if(!es || !es.prelevements.length) return;\n      const isLast = es.prelevements[es.prelevements.length - 1].id === prelId;\n      if(!isLast) return;\n      e.preventDefault();\n      writeFieldValue(inp); // capture la valeur en cours de frappe avant de reconstruire l'ecran\n      es.prelevements.push({ id: \"p\"+Math.random().toString(36).slice(2), piece:\"\", batt:\"\", battD:\"\", battG:\"\", logementId:\"\", pointMesure:\"\", usure:\"\", valeur2:\"\" });\n      toucherEssai(es);\n      saveData();\n      render();\n      const list = document.querySelectorAll(`#scenarioDetail input[data-essai=\"${essaiId}\"][data-field=\"piece\"]`);\n      const again = list[list.length - 1];\n      if(again) again.focus();\n    });\n  });\n  root.querySelectorAll(\".scrap-add\").forEach(el => {\n    el.addEventListener(\"click\", () => {\n      const today = new Date().toISOString().slice(0,10);\n      sc.scrapLog = sc.scrapLog || [];\n      sc.scrapLog.push({ id: \"r\"+Math.random().toString(36).slice(2), date: today, equipe: \"\", produites: \"\", rebutees: \"\" });\n      saveData(); render();\n    });\n  });\n  root.querySelectorAll(\".scrap-del\").forEach(el => {\n    el.addEventListener(\"click\", () => {\n      const scrapId = el.getAttribute(\"data-scrap\");\n      sc.scrapLog = (sc.scrapLog||[]).filter(r => r.id !== scrapId);\n      saveData(); render();\n    });\n  });\n}\n\n/* ecrit la valeur du champ dans le modele de donnees, SANS reconstruire l'affichage \u2014\n   utilise a chaque frappe (fluide, pas de perte de focus) et repris tel quel au blur. */\n/* Date de derniere modification d'un essai : c'est la seule information qui permet, a la\n   fusion de deux fichiers, de savoir quelle version d'un meme essai garder. Posee a chaque\n   ecriture (champ d'essai ou de prelevement), a la creation, et a l'ajout/suppression de\n   prelevements, photos ou releves Marposs. */\nfunction toucherEssai(es){\n  if(es){\n    es.modifieLe = new Date().toISOString();\n    // v4.10 : qui a touch\u00e9 \u2014 pour le journal de synchro et l'arbitrage lisible des fusions\n    es.modifiePar = auteurNom || ((typeof cloudSession !== \"undefined\" && cloudSession) ? cloudSession.email : \"\") || \"\";\n  }\n}\n\n/* v4.9 \u2014 champs des crit\u00e8res suppl\u00e9mentaires (config du bloc Essais ET cellules des\n   pr\u00e9l\u00e8vements) : \u00e9criture pure, sans sauvegarde ni rendu \u2014 le change event d\u00e9clenche\n   la sauvegarde par le c\u00e2blage g\u00e9n\u00e9rique, exactement comme les autres champs. */\nfunction ecrireCsup(el){\n  const sc = data.find(s => s.id === el.getAttribute(\"data-id\"));\n  if(!sc) return null;\n  const cid = el.getAttribute(\"data-csup\");\n  const prelId = el.getAttribute(\"data-prel\");\n  const val = el.type === \"number\" ? (el.value === \"\" ? \"\" : parseFloat(el.value)) : el.value;\n  if(prelId){\n    const es = sc.essais.find(e => e.id === el.getAttribute(\"data-essai\"));\n    const row = es && es.prelevements.find(r => r.id === prelId);\n    if(!row) return null;\n    const ax = el.getAttribute(\"data-csax\") || \"v\";\n    row.valeurs = row.valeurs || {};\n    row.valeurs[cid] = row.valeurs[cid] || {};\n    row.valeurs[cid][ax] = val;\n    toucherEssai(es);\n  } else {\n    const c = (sc.criteresSup || []).find(x => x.id === cid);\n    if(!c) return null;\n    const field = el.getAttribute(\"data-csfield\");\n    if(field === \"maxi\" || field === \"mini\") c[field] = val;\n    else if(field === \"label\") c.label = el.value;\n  }\n  return null;\n}\n\nfunction writeFieldValue(el){\n  const id = el.getAttribute(\"data-id\");\n  if(el.getAttribute(\"data-csup\")) return ecrireCsup(el);\n  const field = el.getAttribute(\"data-field\");\n  const outilId = el.getAttribute(\"data-outil\");\n  const logementId = el.getAttribute(\"data-logement\");\n  const essaiId = el.getAttribute(\"data-essai\");\n  const prelId = el.getAttribute(\"data-prel\");\n  const scrapId = el.getAttribute(\"data-scrap\");\n  const pieceId = el.getAttribute(\"data-piece\");\n  const sc = data.find(s => s.id === id);\n  if(!sc) return null;\n  const val = el.type === \"number\" ? (el.value === \"\" ? \"\" : parseFloat(el.value)) : el.value;\n  if(pieceId){\n    const o = sc.outils.find(x => x.id === outilId);\n    const p = o && (o.pieces||[]).find(x => x.id === pieceId);\n    if(p) p[field] = val;\n  } else if(scrapId){\n    const row = (sc.scrapLog||[]).find(r => r.id === scrapId);\n    if(row) row[field] = val;\n  } else if(prelId){\n    const es = sc.essais.find(e => e.id === essaiId);\n    const row = es && es.prelevements.find(r => r.id === prelId);\n    if(row){ row[field] = val; toucherEssai(es); }\n  } else if(essaiId){\n    const es = sc.essais.find(e => e.id === essaiId);\n    if(es){ es[field] = val; toucherEssai(es); }\n  } else if(outilId && logementId){\n    const o = sc.outils.find(x => x.id === outilId);\n    const l = o && o.logements.find(x => x.id === logementId);\n    if(l) l[field] = val;\n  } else if(outilId){\n    const o = sc.outils.find(x => x.id === outilId);\n    if(o) o[field] = val;\n  } else {\n    sc[field] = val;\n  }\n  /* v4.66.0 \u2014 le garde-fou porte-outil/logement, AU MOMENT O\u00d9 ON \u00c9CRIT.\n     On n'emp\u00eache rien : la valeur est \u00e9crite telle quelle (l'utilisateur a\n     toujours le droit de garder deux outils distincts). On propose ensuite,\n     en une phrase, ce que son vocabulaire sugg\u00e8re. */\n  let fusion = null;\n  if(outilId && !logementId && field === \"numero\"){\n    fusion = proposerFusionLogement(val, sc.outils, outilId);\n  }\n  return { sc, outilId, logementId, field, fusion };\n}\n\n/* au blur (ou Entree/Tab qui en decoule) : on ecrit la valeur finale, on recalcule ce qui\n   en depend, on sauvegarde et on reconstruit l'affichage complet (badges, couts, graphique). */\n\n/* ---- v4.17 \u2014 ne jamais reconstruire l'ecran AU MILIEU d'un clic ----\n   Le blur qui declenche `change` se produit pendant le MOUSEDOWN du clic suivant (l'action\n   par defaut du mousedown est de deplacer le focus). Un render() immediat remplace alors le\n   noeud sous le pointeur entre mousedown et mouseup : le click final part sur l'ancetre\n   commun au lieu du bouton, et le clic est avele. Symptome exact du \u00ab Joindre le plan de\n   l'outil \u00bb qui n'ouvrait le s\u00e9lecteur de fichier qu'au DEUXIEME clic des que l'on venait\n   de saisir un champ. On retarde donc le render a la fin du clic en cours \u2014 sans le\n   retarder du tout quand le change arrive hors clic (Tab, Entree), ou le comportement\n   reste immediat comme avant. */\nlet clicSourisEnCours = false;\nlet renderEnAttenteClic = false;\ndocument.addEventListener(\"mousedown\", () => { clicSourisEnCours = true; }, true);\ndocument.addEventListener(\"mouseup\", () => {\n  clicSourisEnCours = false;\n  if(renderEnAttenteClic){\n    renderEnAttenteClic = false;\n    setTimeout(render, 0); // apres le click (dispatche synchrone des mouseup), jamais avant\n  }\n}, true);\nfunction renderApresClic(){\n  if(!clicSourisEnCours){ render(); return; }\n  if(renderEnAttenteClic) return;\n  renderEnAttenteClic = true;\n  // filet de securite : mouseup perdu (bouton relache hors de la fenetre) -> on rend quand meme\n  setTimeout(() => { if(renderEnAttenteClic){ renderEnAttenteClic = false; render(); } }, 400);\n}\n\nfunction onInputChange(e){\n  const el = e.target;\n  // le statut d'un scenario passe par sa propre logique (verrouillage du scenario en\n  // production, promotion coordonnee) plutot que par l'ecriture generique de champ --\n  // voir appliquerChangementStatut. Le resultat (accepte ou refuse) est ignore ici : dans\n  // les deux cas, saveData()+render() suivent -- accepte, ils persistent le nouvel etat ;\n  // refuse, aucune mutation n'a eu lieu et render() reaffiche simplement la vraie valeur.\n  // Depuis les dialogues in-app (v4.6), la promotion \"En serie\" passe par une promesse :\n  // on attend sa resolution avant de sauvegarder, sinon l'etat mute apres la sauvegarde.\n  if(el.classList.contains(\"statut-select\")){\n    Promise.resolve(appliquerChangementStatut(el)).then(() => {\n      saveData();\n      render();\n    });\n    return;\n  }\n  const ctx = writeFieldValue(el);\n  if(!ctx) return;\n  if(ctx.outilId && ctx.logementId && (ctx.field === \"vc\" || ctx.field === \"f\")) recomputeCycles();\n  /* v4.66.0 \u2014 on vient peut-\u00eatre de saisir \u00ab T517 D2 \u00bb sur un outil qui\n     s'appelle d\u00e9j\u00e0 \u00ab T517 D1 \u00bb. On ne bloque RIEN : la valeur est \u00e9crite. On\n     demande, en une phrase, si les deux sont le m\u00eame porte-outil \u2014 et c'est\n     un CLIC EXPLICITE qui r\u00e9unit. */\n  if(ctx.fusion){\n    const p = ctx.fusion;\n    const phrase = p.mode === \"complet\"\n      ? `\u00ab ${el.value} \u00bb et \u00ab ${p.cible.numero} \u00bb sont le m\u00eame porte-outil ${p.porte},`\n      : `L'outil ${p.porte} existe d\u00e9j\u00e0,`;\n    Promise.resolve(dialogueConfirmer(\n        `${phrase} mais deux outils distincts. Les r\u00e9unir en un seul outil ${p.porte}, avec un logement ${p.position} ?`,\n        { titre: \"M\u00eame porte-outil ?\", okLabel: \"R\u00e9unir en un outil\", danger:false }))\n      .then(ok => {\n        if(!ok) return;\n        ctx.sc.outils = fusionnerOutils(ctx.sc.outils, ctx.outilId, p);\n        saveData(); render();\n      });\n  }\n  // passage en abandon : on date la decision, c'est elle qui fait l'historique (le cas\n  // \"serie\" est desormais entierement gere par appliquerChangementStatut ci-dessus)\n  if(ctx.field === \"statut\" && ctx.sc.statut === \"abandonne\" && !ctx.sc.statutDate){\n    ctx.sc.statutDate = new Date().toISOString().slice(0,10);\n  }\n  saveData();\n  renderApresClic();\n}\n\ndocument.getElementById(\"importAnnuler\").addEventListener(\"click\", fermerPanneaux);\ndocument.getElementById(\"lockBtn\").addEventListener(\"click\", toggleLock);\ndocument.getElementById(\"addBtn\").addEventListener(\"click\", () => {\n  const l = getActiveLigne();\n  const emag1Auto = !!(l && l.nom && l.nom.trim().toLowerCase() === \"emag 1\");\n  const blank = {\n    id: uid(\"s\"), name: \"Nouveau sc\u00e9nario\", baseline: false, cycle: \"\",\n    emag1: emag1Auto, limitOverride: false, limitLabel: \"Battement (mm)\", limitValue: 0.12, validationThreshold: 5,\n    critere2Actif: false, limitLabel2: \"Ra (\u00b5m)\", limitValue2: 0.8,\n    // v4.10.1 \u2014 plus de logements pr\u00e9-cr\u00e9\u00e9s : le sc\u00e9nario arrive avec un outil vide, et\n    // l'op\u00e9rateur nomme ses logements lui-m\u00eame (les \u00ab Bol \u00bb/\u00ab Piste \u00bb automatiques mentaient\n    // sur les montages qui n'en ont pas \u2014 un logement ne porte un nom que s'il a \u00e9t\u00e9 saisi)\n    outils: [{ id: \"t\"+Math.random().toString(36).slice(2), numero: \"\", logements: [] }],\n    essais: [], scrapLog: []\n  };\n  data.push(blank);\n  activeId = blank.id;\n  // \"renseigner les donnees dans le projet qu'on a selectionne\" (Matis) : un nouveau\n  // scenario cree pendant qu'un projet precis est ouvert y est etiquete d'office.\n  const pjActif = activeProjetId && projets.find(x => x.id === activeProjetId);\n  if(pjActif) toggleTagScenario(pjActif, activeLigneId, activeReferenceId, activeOpId, blank.id);\n  saveData(); render();\n});\n\ndocument.getElementById(\"resetBtn\").addEventListener(\"click\", () => {\n  const nbEssais = lignes.reduce((n, l) => n + l.references.reduce((n2, r) => n2 + r.ops.reduce((n3, o) => n3 + o.scenarios.reduce((n4, s) => n4 + (s.essais||[]).length, 0), 0), 0), 0);\n  const nbRef = lignes.reduce((n, l) => n + l.references.length, 0);\n  const nbOp = lignes.reduce((n, l) => n + l.references.reduce((n2, r) => n2 + r.ops.length, 0), 0);\n  // un simple clic sur \"OK\" se fait sans y penser (surtout avec ce bouton juste a cote des\n  // autres actions courantes) : on exige de taper un mot exact, comme un vrai \"sont-vous sur\"\n  // qui force une action deliberee plutot qu'un reflexe de souris.\n  // dialogue in-app (v4.6) : la validation reste un mot exact a taper \u2014 le geste est\n  // deliber\u00e9, pas un reflexe de souris \u2014 mais dans la famille visuelle de l'outil.\n  dialogueDemander(\n    \"R\u00e9initialiser l'outil ?\\n\\nTOUTES les lignes de production, TOUTES les r\u00e9f\u00e9rences disque (\" + nbRef + \"), TOUTES les OP (\" + nbOp + \"), tous les sc\u00e9narios et les \" + nbEssais + \" essai(s) saisis seront effac\u00e9s et remplac\u00e9s par les valeurs de d\u00e9part.\\n\\nExportez d'abord le suivi si vous voulez le conserver.\\n\\nPour confirmer, tapez exactement : REINITIALISER\",\n    \"\", { titre: \"R\u00e9initialiser l'outil ?\", okLabel: \"R\u00e9initialiser\", danger: true }\n  ).then(saisie => {\n    if(saisie !== \"REINITIALISER\"){ if(saisie !== null) dialogueAlerte(\"R\u00e9initialisation annul\u00e9e \u2014 le texte tap\u00e9 ne correspond pas.\", \"Annul\u00e9e\"); return; }\n    backupSnapshot(\"R\u00e9initialiser\");\n    lignes = defaultLignes();\n    projets = []; activeProjetId = null; responsables = [];\n    backlog = [];\n    activeLigneId = lignes[0].id;\n    activeReferenceId = lignes[0].references[0].id;\n    activeOpId = lignes[0].references[0].ops[0].id;\n    data = lignes[0].references[0].ops[0].scenarios;\n    config = lignes[0].references[0].ops[0].config;\n    activeId = data[0].id;\n    recomputeCycles();\n    saveData();\n    updateRestoreUI();\n    render();\n  });\n});\n\ndocument.getElementById(\"restoreBtn\").addEventListener(\"click\", restoreBackup);\ndocument.getElementById(\"syntheseBtn\").addEventListener(\"click\", () => {\n  const wrap = document.getElementById(\"syntheseWrap\");\n  wrap.hidden = !wrap.hidden;\n  if(!wrap.hidden) renderSynthese();\n});\ndocument.getElementById(\"backlogBtn\").addEventListener(\"click\", () => {\n  ouvrirPanneau(\"backlogWrap\");\n  renderBacklog();\n});\nconst auteurInput = document.getElementById(\"auteurInput\");\nauteurInput.value = auteurNom;\nauteurInput.addEventListener(\"change\", () => {\n  auteurNom = auteurInput.value;\n  try{ localStorage.setItem(AUTEUR_KEY, auteurNom); }catch(e){}\n});\n\n/* ---- panneaux modaux ---- */\nfunction ouvrirPanneau(id){\n  const pan = document.getElementById(id);\n  if(panneauPile.indexOf(id) === -1){\n    if(!panneauPile.length && !focusAvantPanneau) focusAvantPanneau = document.activeElement;\n    panneauPile.push(id);\n  }\n  pan.hidden = false;\n  // role dialogue pose dynamiquement (v4.6) : chaque panneau se comporte comme une fenetre\n  // modale pour les lecteurs d'ecran, et le piege de Tab ci-dessus s'appuie sur la pile.\n  pan.setAttribute(\"role\", \"dialog\");\n  pan.setAttribute(\"aria-modal\", \"true\");\n  if(!pan.hasAttribute(\"aria-label\")){\n    const t = pan.querySelector(\"h3\");\n    if(t) pan.setAttribute(\"aria-label\", t.textContent.trim());\n  }\n  document.getElementById(\"panelBackdrop\").hidden = false;\n  // le focus entre dans le panneau ouvert : premier champ, sinon le panneau lui-meme \u2014\n  // sinon il reste derriere le voile et Tab ressort de la fenetre invisible.\n  const cible = pan.querySelector(SELECTEUR_FOCUSABLE);\n  if(cible && cible.getClientRects().length) cible.focus();\n  else { pan.tabIndex = -1; pan.focus({ preventScroll:true }); }\n}\nfunction fermerPanneaux(){\n  fermerDialogue();\n  document.getElementById(\"panelBackdrop\").hidden = true;\n  // tous les panneaux, sans liste en dur : projetCreatePanel oublie ici restait ouvert\n  // apres la creation d'un projet, empile sous le panneau d'info (et un 2e clic sur\n  // \"Creer le projet\" creait un doublon). Un futur panneau sera couvert d'office.\n  document.querySelectorAll(\".panel\").forEach(p => { p.hidden = true; });\n  annot = null;\n  importEnAttente = null;\n  document.getElementById(\"toolbarMore\").hidden = true;\n  panneauPile = [];\n  restaurerFocusPanneau();\n}\ndocument.getElementById(\"dashboardBtn\").addEventListener(\"click\", () => {\n  renderDashboard();\n  ouvrirPanneau(\"dashboardPanel\");\n});\n/* v4.51.2 \u2014 la carte atelier s\u2019ouvre sur le projet actif (H1-b) ; son filtre lui est propre. */\ndocument.getElementById(\"carteBtn\").addEventListener(\"click\", ouvrirCarte);\ndocument.getElementById(\"accueilBtn\").addEventListener(\"click\", ouvrirAccueil);\n/* v4.55.0 \u2014 lecture du classeur Matis : constat, jamais un import (option C). */\ndocument.getElementById(\"matisBtn\").addEventListener(\"click\", ouvrirMatis);\n/* v4.14 \u2014 palette de recherche : bouton du menu, frappe directe au clavier (Ctrl+K),\n   navigation fl\u00e8ches + Entr\u00e9e dans la liste de r\u00e9sultats. */\ndocument.getElementById(\"searchBtn\").addEventListener(\"click\", ouvrirRecherche);\ndocument.getElementById(\"searchInput\").addEventListener(\"input\", (e) => rendreRecherche(e.target.value));\ndocument.getElementById(\"searchInput\").addEventListener(\"keydown\", (e) => {\n  const max = rechercheListe.length;\n  if(e.key === \"ArrowDown\" && max){ e.preventDefault(); rechercheSel = (rechercheSel + 1) % max; majSelRecherche(); }\n  else if(e.key === \"ArrowUp\" && max){ e.preventDefault(); rechercheSel = (rechercheSel - 1 + max) % max; majSelRecherche(); }\n  else if(e.key === \"Enter\"){ e.preventDefault(); allerRecherche(rechercheSel); }\n});\ndocument.addEventListener(\"keydown\", (e) => {\n  if((e.ctrlKey || e.metaKey) && !e.altKey && !e.shiftKey && (e.key === \"k\" || e.key === \"K\")){\n    e.preventDefault();\n    ouvrirRecherche();\n  }\n});\n/* v4.15 \u2014 comparaison d'essais : les menus A/B re-remplissent le panneau au changement. */\ndocument.getElementById(\"cmpA\").addEventListener(\"change\", (e) => {\n  compareCtx = { a: e.target.value, b: compareCtx ? compareCtx.b : null };\n  remplirComparaison();\n});\ndocument.getElementById(\"cmpB\").addEventListener(\"change\", (e) => {\n  compareCtx = { a: compareCtx ? compareCtx.a : null, b: e.target.value };\n  remplirComparaison();\n});\ndocument.getElementById(\"compareClose\").addEventListener(\"click\", fermerPanneaux);\ndocument.getElementById(\"parcoursBtn\").addEventListener(\"click\", ouvrirParcours);\ndocument.getElementById(\"nouveautesBtn\").addEventListener(\"click\", ouvrirNouveautes);\n// des formes/rognage/legende non enregistres dans l'editeur d'annotation se perdaient\n// silencieusement sur Echap ou un clic hors panneau \u2014 confirmation ajoutee, uniquement\n// s'il y a vraiment quelque chose de different de l'etat charge (annotDirty)\nfunction annotDirty(){\n  if(!annot) return false;\n  return JSON.stringify({ crop: annot.crop, shapes: annot.shapes, legende: annot.legendeDraft }) !== annot.snapshot;\n}\nfunction fermerPanneauxConfirme(){\n  const annotWrap = document.getElementById(\"photoAnnotWrap\");\n  if(annotWrap && !annotWrap.hidden && annotDirty()){\n    // dialogue in-app (v4.6) : le refus laisse le panneau ouvert, comme avant avec confirm().\n    dialogueConfirmer(\"Fermer sans enregistrer ? Le rognage, les formes et la l\u00e9gende ajout\u00e9s \u00e0 cette photo seront perdus.\", { titre: \"Fermer sans enregistrer ?\", danger: true, okLabel: \"Fermer sans enregistrer\" }).then(ok => {\n      if(!ok) return;\n      annot = null;\n      fermerPanneaux();\n    });\n    return;\n  }\n  annot = null;\n  fermerPanneaux();\n}\ndocument.getElementById(\"panelBackdrop\").addEventListener(\"click\", fermerPanneauxConfirme);\ndocument.addEventListener(\"keydown\", (e) => {\n  if(e.key === \"Escape\"){\n    fermerPanneauxConfirme();\n    fermerLightbox();\n    document.getElementById(\"toolbarMore\").hidden = true; // menu \u2022\u2022\u2022 : Echap le fermait pas\n  }\n});\n\n/* ---- agrandissement plein ecran d'une image (ex. capture jointe a une suggestion) ---- */\nfunction ouvrirLightbox(src){\n  document.getElementById(\"imgLightboxImg\").src = src;\n  document.getElementById(\"imgLightbox\").hidden = false;\n  // relance l'animation de fondu du rappel \"Cliquer ou Echap pour fermer\" (sinon elle ne\n  // joue qu'une fois, au premier chargement de page)\n  const hint = document.getElementById(\"imgLightboxHint\");\n  hint.style.animation = \"none\";\n  void hint.offsetWidth;\n  hint.style.animation = \"\";\n}\nfunction fermerLightbox(){\n  document.getElementById(\"imgLightbox\").hidden = true;\n  document.getElementById(\"imgLightboxImg\").src = \"\";\n}\ndocument.getElementById(\"imgLightbox\").addEventListener(\"click\", fermerLightbox);\n/* menu \"\u2022\u2022\u2022\" : toggle au clic sur le bouton, fermeture au clic ailleurs ou sur une action\n   du menu (chaque bouton a l'interieur ouvre de toute facon son propre panneau ensuite) */\ndocument.getElementById(\"moreBtn\").addEventListener(\"click\", (e) => {\n  e.stopPropagation();\n  document.getElementById(\"toolbarMore\").hidden = !document.getElementById(\"toolbarMore\").hidden;\n});\ndocument.getElementById(\"toolbarMore\").addEventListener(\"click\", (e) => {\n  if(e.target.closest(\"button\")) document.getElementById(\"toolbarMore\").hidden = true;\n});\ndocument.addEventListener(\"click\", (e) => {\n  const more = document.getElementById(\"toolbarMore\");\n  if(!more.hidden && !e.target.closest(\".toolbar-more-wrap\")) more.hidden = true;\n});\n\n/* Options \u2014 modules de calcul */\nconst optCoutRebut = document.getElementById(\"optCoutRebut\");\nconst optCoutDisque = document.getElementById(\"optCoutDisque\");\nconst optCycleSec = document.getElementById(\"optCycleSec\");\nconst optCycleRefSec = document.getElementById(\"optCycleRefSec\");\nconst optLimitLabel = document.getElementById(\"optLimitLabel\");\nconst optLimitValue = document.getElementById(\"optLimitValue\");\nconst optForceRatio = document.getElementById(\"optForceRatio\");\nconst optEcartCharniere = document.getElementById(\"optEcartCharniere\");\nconst optCoutMachine = document.getElementById(\"optCoutMachine\");\nconst optPartCoupante = document.getElementById(\"optPartCoupante\");\nconst optCoutHoraire = document.getElementById(\"optCoutHoraire\");\nconst optCycleDetail = document.getElementById(\"optCycleDetail\");\nconst optPieces = document.getElementById(\"optPieces\");\nconst optVolume = document.getElementById(\"optVolume\");\nconst optProductionAnnuelle = document.getElementById(\"optProductionAnnuelle\");\n\n/* etat du cout machine (v4.7) : l'ancienne note statique des \"quatre choses a faire\"\n   disait trop \u2014 le calcul reel (coutMachinePiece/cycleSecondes) n'exige que le module\n   actif, le cycle de reference et le cout horaire ; l'affichage en secondes est une\n   commodite, pas une condition. L'outil le dit maintenant depuis le code, pas depuis\n   un texte qui pouvait deriver de lui. */\nfunction etatCoutMachine(cfg, ligne){\n  cfg = cfg || config;\n  const l = ligne || getActiveLigne();\n  const taux = l ? parseFloat(l.coutHoraire) : NaN;\n  const manquants = [];\n  if(cfg.cycleRefSec === \"\" || isNaN(parseFloat(cfg.cycleRefSec))) manquants.push(\"le temps de cycle du sc\u00e9nario de r\u00e9f\u00e9rence (s)\");\n  if(isNaN(taux) || taux <= 0) manquants.push(\"le co\u00fbt horaire de la ligne (\u20ac/h)\");\n  return { actif: !!cfg.coutMachineActif && !manquants.length, taux, manquants };\n}\nfunction majStatutCoutMachine(){\n  const el = document.getElementById(\"optCoutMachineStatut\");\n  if(!el) return;\n  if(!config.coutMachineActif){ el.hidden = true; return; }\n  const et = etatCoutMachine();\n  el.hidden = false;\n  if(et.manquants.length){\n    el.className = \"opt-statut ko\";\n    el.innerHTML = `Co\u00fbt machine incomplet \u2014 il manque encore ${et.manquants.join(\" et \")}. Tant qu'il manque, le co\u00fbt pi\u00e8ce ignore le temps machine : aucun \u00e9cart de cycle ne p\u00e8se dans le gain annuel.`;\n  } else {\n    el.className = \"opt-statut ok\";\n    el.innerHTML = `Co\u00fbt machine actif \u2014 ${fmt(et.taux,2)} \u20ac/h \u00d7 temps de cycle. Les \u00e9carts de cycle p\u00e8sent maintenant dans le co\u00fbt pi\u00e8ce et le gain annuel.`;\n  }\n}\nfunction majChampsOptions(){\n  document.getElementById(\"optCoutRebutField\").classList.toggle(\"on\", optCoutRebut.checked);\n  document.getElementById(\"optCycleRefField\").classList.toggle(\"on\", optCycleSec.checked || optCoutMachine.checked);\n  document.getElementById(\"optCoutMachineField\").classList.toggle(\"on\", optCoutMachine.checked);\n  document.getElementById(\"optVolumeField\").classList.toggle(\"on\", optVolume.checked);\n  majStatutCoutMachine();\n}\nfunction syncOptionsUI(){\n  optLimitLabel.value = config.limitLabel ?? \"\";\n  optLimitValue.value = config.limitValue ?? \"\";\n  optCoutRebut.checked = !!config.coutRebutActif;\n  optCoutDisque.value = config.coutDisque ?? \"\";\n  optCycleSec.checked = !!config.cycleSecActif;\n  optCycleRefSec.value = config.cycleRefSec ?? \"\";\n  optCoutMachine.checked = !!config.coutMachineActif;\n  optPartCoupante.value = config.partCoupante ?? \"\";\n  optCycleDetail.checked = !!config.cycleDetailActif;\n  optPieces.checked = !!config.piecesActif;\n  optVolume.checked = !!config.volumeActif;\n  const ref = getActiveReference();\n  optProductionAnnuelle.value = ref ? (ref.productionAnnuelle ?? \"\") : \"\";\n  optForceRatio.checked = !!config.forceRatioActif;\n  optEcartCharniere.value = config.ecartCharniereTolerance ?? 0.5;\n  // contexte (v4.7) : les reglages d'Options ne portent pas tous la meme portee \u2014 on dit\n  // laquelle, d'un coup, en tete de panneau, plutot que de la deviner champ par champ.\n  const lg = getActiveLigne(), op = getActiveOp();\n  document.getElementById(\"optionsContexte\").innerHTML =\n    `${escapeAttr(op ? op.nom : \"\u2014\")} \u00b7 ${escapeAttr(ref ? ref.nom : \"\u2014\")} \u00b7 ${escapeAttr(lg ? lg.nom : \"\u2014\")}` +\n    ` \u2014 chaque r\u00e9glage porte son badge de port\u00e9e : <i class=\"opt-scope\">OP</i>, <i class=\"opt-scope\">R\u00e9f\u00e9rence</i>, <i class=\"opt-scope\">Ligne</i> ou <i class=\"opt-scope\">Tous</i>.`;\n  // v4.23 \u2014 le champ volume porte sa cible en toutes lettres : ligne \u203a r\u00e9f\u00e9rence, plus\n  // la trace de la derni\u00e8re modification. Fini le doute \u00ab ce chiffre s'applique \u00e0 qui ? \u00bb\n  const optVolumeTarget = document.getElementById(\"optVolumeTarget\");\n  if(optVolumeTarget){\n    const dernierVol = ref && ref.volumeHistorique && ref.volumeHistorique[0];\n    const volDate = dernierVol ? new Date(dernierVol.date).toLocaleDateString(\"fr-FR\") : \"\";\n    optVolumeTarget.innerHTML = ref && lg\n      ? `<b>S'applique \u00e0 : ${escapeAttr(lg.nom)} \u203a ${escapeAttr(ref.nom)}</b>` +\n        (dernierVol ? ` \u2014 derni\u00e8re modification : ${escapeAttr(dernierVol.valeur === \"\" ? \"champ vid\u00e9\" : fmt(parseFloat(dernierVol.valeur),0) + \" disques/an\")} par ${escapeAttr(dernierVol.par || \"?\")}${volDate ? \" le \" + volDate : \"\"}` : \"\")\n      : \"\";\n  }\n  // le cout horaire vit sur la ligne : champ en place (v4.7), meme donnee que l'icone \u2699\n  optCoutHoraire.value = lg ? (lg.coutHoraire ?? \"\") : \"\";\n  // v4.9 : specs usine affich\u00e9es, toujours reverrouill\u00e9es \u00e0 l'ouverture du panneau\n  usineUnlockOk = false;\n  optUsineBatt.value = specsUsine.battement;\n  optUsineVE.value = specsUsine.ve;\n  optUsineBatt.disabled = true;\n  optUsineVE.disabled = true;\n  optUsineUnlock.textContent = \"Modifier\";\n  majChampsOptions();\n  renderFicheOutil();\n  renderResponsablesOptions();\n}\n\n/* Gestion des responsables (v4.2), dans Options : liste geree independamment des projets --\n   supprimer un responsable ne supprime jamais un projet, il repasse a \"aucun responsable\"\n   (voir supprimerResponsable). */\nfunction renderResponsablesOptions(){\n  const el = document.getElementById(\"responsablesListe\");\n  if(!el) return;\n  el.innerHTML = responsables.length\n    ? responsables.map(r => `\n        <div class=\"responsable-ligne\" data-responsable=\"${r.id}\">\n          <input type=\"color\" class=\"responsable-couleur\" value=\"${r.couleur || \"#94a3b8\"}\" title=\"Couleur de ${escapeAttr(r.nom)}\">\n          <span class=\"responsable-nom\">${escapeAttr(r.nom)}</span>\n          <button class=\"log-del\" data-suppr-responsable=\"${r.id}\" title=\"Supprimer\">\u2715</button>\n        </div>`).join(\"\")\n    : `<p class=\"opt-note\">Aucun responsable pour l'instant \u2014 ajoutez-en un ci-dessous, ou directement depuis le panneau d'un projet.</p>`;\n  el.querySelectorAll(\".responsable-couleur\").forEach(inp => {\n    inp.addEventListener(\"change\", () => {\n      const r = responsables.find(x => x.id === inp.closest(\"[data-responsable]\").getAttribute(\"data-responsable\"));\n      if(r){ r.couleur = inp.value; saveData(); render(); }\n    });\n  });\n  el.querySelectorAll(\"[data-suppr-responsable]\").forEach(btn => {\n    btn.addEventListener(\"click\", () => {\n      const id = btn.getAttribute(\"data-suppr-responsable\");\n      const r = responsables.find(x => x.id === id);\n      if(!r) return;\n      const nbProjets = projets.filter(p => p.responsableId === id).length;\n      dialogueConfirmer(`Supprimer \u00ab ${r.nom} \u00bb de la liste des responsables ?` + (nbProjets ? `\\n\\n${nbProjets} projet(s) actuellement pilot\u00e9(s) par cette personne repasseront \u00e0 \u00ab Aucun \u00bb \u2014 ils ne sont pas supprim\u00e9s.` : \"\"), { titre: \"Supprimer le responsable ?\", danger: true, okLabel: \"Supprimer\" }).then(ok => {\n        if(!ok) return;\n        responsables = responsables.filter(x => x.id !== id);\n        projets.forEach(p => { if(p.responsableId === id) p.responsableId = \"\"; });\n        saveData(); render(); renderResponsablesOptions();\n      });\n    });\n  });\n}\ndocument.getElementById(\"responsableAjouter\").addEventListener(\"click\", () => {\n  const nomEl = document.getElementById(\"responsableNouveauNom\");\n  const couleurEl = document.getElementById(\"responsableNouvelleCouleur\");\n  const nom = nomEl.value.trim();\n  if(!nom){ dialogueAlerte(\"Indiquez un nom.\", \"Nom manquant\"); return; }\n  responsables.push(normalizeResponsable({ nom, couleur: couleurEl.value }));\n  nomEl.value = \"\";\n  couleurEl.value = prochaineCouleurLibre(responsables.map(x => x.couleur));\n  saveData(); render(); renderResponsablesOptions();\n});\n\nfunction appliquerOptions(){\n  config.limitLabel = optLimitLabel.value;\n  config.limitValue = optLimitValue.value === \"\" ? \"\" : parseFloat(optLimitValue.value);\n  config.coutRebutActif = optCoutRebut.checked;\n  config.coutDisque = optCoutDisque.value === \"\" ? \"\" : parseFloat(optCoutDisque.value);\n  config.cycleSecActif = optCycleSec.checked;\n  config.cycleRefSec = optCycleRefSec.value === \"\" ? \"\" : parseFloat(optCycleRefSec.value);\n  config.coutMachineActif = optCoutMachine.checked;\n  config.partCoupante = optPartCoupante.value === \"\" ? 100 : parseFloat(optPartCoupante.value);\n  config.cycleDetailActif = optCycleDetail.checked;\n  config.piecesActif = optPieces.checked;\n  config.volumeActif = optVolume.checked;\n  const ref = getActiveReference();\n  if(ref) enregistrerVolumeAnnuel(ref, optProductionAnnuelle.value === \"\" ? \"\" : parseFloat(optProductionAnnuelle.value));\n  // cout horaire saisi en place (v4.7) : il ecrit dans la ligne active, comme le ferait\n  // l'icone \u2699 de son onglet \u2014 meme champ, deux portes d'entree, zero changement de format\n  const lgOpt = getActiveLigne();\n  if(lgOpt) lgOpt.coutHoraire = optCoutHoraire.value;\n  config.forceRatioActif = optForceRatio.checked;\n  config.ecartCharniereTolerance = optEcartCharniere.value === \"\" ? 0.5 : parseFloat(optEcartCharniere.value);\n  majChampsOptions();\n  saveData();\n  render();\n}\n// chaque frappe dans un champ number d'Options declenchait un saveData()+render() complet\n// (perceptible sur un gros arbre) : debounce leger sur \"input\", \"change\" (blur/Entree)\n// reste instantane\nlet optionsInputDebounce = null;\n[optCoutRebut, optCoutDisque, optCycleSec, optCycleRefSec, optCoutMachine, optPartCoupante, optCycleDetail,\n optPieces, optVolume, optProductionAnnuelle, optLimitLabel, optLimitValue, optForceRatio, optEcartCharniere, optCoutHoraire].forEach(el => {\n  el.addEventListener(\"change\", () => { clearTimeout(optionsInputDebounce); appliquerOptions(); });\n  el.addEventListener(\"input\", () => {\n    if(el.type !== \"number\") return;\n    clearTimeout(optionsInputDebounce);\n    optionsInputDebounce = setTimeout(appliquerOptions, 150);\n  });\n});\ndocument.getElementById(\"optionsBtn\").addEventListener(\"click\", () => { syncOptionsUI(); ouvrirPanneau(\"optionsPanel\"); });\n\n/* v4.9 \u2014 modification des specs usine : double validation. Le bouton d\u00e9verrouille les\n   champs apr\u00e8s confirmation explicite ; les valeurs ne sont \u00e9crites qu'au\n   reverrouillage (\u00ab Verrouiller et enregistrer \u00bb), et le panneau reverrouille tout seul\n   \u00e0 sa prochaine ouverture. */\nlet usineUnlockOk = false;\ndocument.getElementById(\"optUsineUnlock\").addEventListener(\"click\", () => {\n  const b = document.getElementById(\"optUsineUnlock\");\n  const batt = document.getElementById(\"optUsineBatt\");\n  const ve = document.getElementById(\"optUsineVE\");\n  if(usineUnlockOk){\n    if(batt.value !== \"\" && !isNaN(parseFloat(batt.value))) specsUsine.battement = parseFloat(batt.value);\n    if(ve.value !== \"\" && !isNaN(parseFloat(ve.value))) specsUsine.ve = parseFloat(ve.value);\n    usineUnlockOk = false;\n    batt.disabled = ve.disabled = true;\n    b.textContent = \"Modifier\";\n    saveData();\n    dialogueAlerte(\"Specs usine enregistr\u00e9es : Battement \u2264 \" + fmt(specsUsine.battement,3) + \" \u00b7 VE \u2264 \" + fmt(specsUsine.ve,3) + \".\", \"Specs usine\");\n    return;\n  }\n  dialogueConfirmer(\"Modifier les sp\u00e9cifications usine ?\\n\\nCes valeurs (battement max et variation d'\u00e9paisseur max mesur\u00e9es Marposs sur disque fini, apr\u00e8s OP40) servent de r\u00e9f\u00e9rence pour TOUS les disques de l'usine et ne changent normalement jamais.\\n\\nNe continuer que si la sp\u00e9cification a r\u00e9ellement \u00e9t\u00e9 revue officiellement.\", { titre: \"Modifier les specs usine ?\", danger: true, okLabel: \"D\u00e9verrouiller\" }).then(ok => {\n    if(!ok) return;\n    usineUnlockOk = true;\n    batt.disabled = ve.disabled = false;\n    batt.focus();\n    b.textContent = \"Verrouiller et enregistrer\";\n  });\n});\n[\"projetNom\",\"projetProblematique\",\"projetStatut\",\"projetDateCible\"].forEach(id => {\n  const el = document.getElementById(id);\n  if(el) el.addEventListener(\"change\", enregistrerProjetInfo);\n});\ndocument.getElementById(\"projetResponsable\").addEventListener(\"change\", (e) => {\n  if(e.target.value === \"__nouveau__\") ajouterResponsableDepuisSelect();\n  else enregistrerProjetInfo();\n});\ndocument.getElementById(\"projetInfoClose\").addEventListener(\"click\", () => { enregistrerProjetInfo(); fermerPanneaux(); });\ndocument.getElementById(\"projetSupprimer\").addEventListener(\"click\", supprimerProjetActif);\n/* creation projet (v4.5) : panneau dedie, Enter valide, echap/annuler ferme */\ndocument.getElementById(\"projetCreateGo\").addEventListener(\"click\", validerCreationProjet);\ndocument.getElementById(\"projetCreateAnnuler\").addEventListener(\"click\", fermerPanneaux);\ndocument.getElementById(\"projetCreateNom\").addEventListener(\"keydown\", (e) => { if(e.key === \"Enter\") validerCreationProjet(); });\ndocument.getElementById(\"optionsClose\").addEventListener(\"click\", fermerPanneaux);\n\n/* fiche outil (PDF ou image) : n\u00b0 d'outils et trajectoires par logement, par OP.\n   Stockee en base64 directement dans l'OP \u2014 voyage avec l'export/import JSON, sans\n   dossier a part (contrairement aux photos d'essai, sur fichiers reels locaux). */\nfunction renderFicheOutil(){\n  const wrap = document.getElementById(\"ficheOutilWrap\");\n  if(!wrap) return;\n  const op = getActiveOp();\n  const f = op && op.ficheOutil;\n  // les fiches jointes avant la v3.19 n'ont pas de champ \"stockage\" : elles sont en base64\n  const enDossier = f && f.stockage === \"dossier\";\n  wrap.innerHTML = f\n    ? `<div class=\"plan-outil\">\n         <span class=\"plan-icone\">${(f.mime||\"\").startsWith(\"image/\") ? \"\ud83d\uddbc\" : \"\ud83d\udcc4\"}</span>\n         <span class=\"plan-nom\">${escapeAttr(f.nomOrigine || f.filename)}</span>\n         <span class=\"plan-ou\">${enDossier ? \"dossier local\" : \"int\u00e9gr\u00e9e au fichier de suivi\"}</span>\n         <button class=\"ghost small\" id=\"ficheOutilOpen\" type=\"button\">Ouvrir</button>\n         <button class=\"ghost small\" id=\"ficheOutilDel\" type=\"button\">Retirer</button>\n       </div>`\n    : `<label class=\"plan-ajout\">\ud83d\udcce Joindre la fiche outil de l'OP <span>(PDF ou image)</span>\n         <input type=\"file\" accept=\".pdf,image/*\" id=\"ficheOutilInput\" hidden>\n       </label>`;\n  if(f){\n    document.getElementById(\"ficheOutilOpen\").addEventListener(\"click\", () => ouvrirPieceJointe(f));\n    document.getElementById(\"ficheOutilDel\").addEventListener(\"click\", () => {\n      dialogueConfirmer(\"Retirer la fiche outil de cette OP ?\" + (enDossier ? `\n\nLe fichier reste dans le dossier local, seul le lien est supprim\u00e9.` : \"\"), { titre: \"Retirer la fiche outil ?\", danger: true, okLabel: \"Retirer\" }).then(ok => {\n        if(!ok) return;\n        const op2 = getActiveOp();\n        if(op2) op2.ficheOutil = null;\n        saveData(); renderFicheOutil();\n      });\n    });\n  } else {\n    document.getElementById(\"ficheOutilInput\").addEventListener(\"change\", async (e) => {\n      const file = e.target.files && e.target.files[0];\n      if(!file) return;\n      const op2 = getActiveOp();\n      if(!op2) return;\n      const pj = await attacherPieceJointe(file, \"ficheoutil_\" + slugify(op2.nom || \"op\"));\n      e.target.value = \"\";\n      if(!pj) return;\n      op2.ficheOutil = pj;\n      saveData(); renderFicheOutil();\n    });\n  }\n}\n\n/* ---- nouveautes de version ----\n   Evite d'envoyer un e-mail a chaque mise a jour : l'outil annonce lui-meme ce qui a\n   change, une seule fois par version. Fermer la fenetre vaut \"lu\" \u2014 inutile de cocher\n   quoi que ce soit. La case \"ne plus afficher\" est un secours, pas le fonctionnement\n   normal : la cocher revient a ne plus etre prevenu des evolutions suivantes.\n   A CHAQUE VERSION : ajouter une entree en tete, 3 a 5 points lisibles par quelqu'un qui\n   n'a pas suivi le developpement. Le CHANGELOG est trop technique pour cet usage. */\nconst NOUVEAUTES = [\n  { version:\"4.81.1\", date:\"12/10/2026\", points:[\n    \"<b>Le bouton \u00ab \ud83d\udcc2 Importer \u00bb fonctionne de nouveau.</b> Depuis le 29 septembre, choisir un fichier ne faisait <b>rien du tout</b> : aucune fen\u00eatre, aucun message \u2014 la panne mourait en silence. Si vous avez essay\u00e9 d'importer un fichier re\u00e7u et que \u00ab rien ne se passait \u00bb, c'\u00e9tait \u00e7a : rechargez cette version et recommencez, le fichier sera propos\u00e9 \u00e0 l'import comme avant. Aucune donn\u00e9e n'a pu \u00eatre perdue par cette panne (rien n'\u00e9tait \u00e9crit) \u2014 le seul dommage \u00e9tait l'impossibilit\u00e9 d'en charger une.\"\n  ]},\n  { version:\"4.81.0\", date:\"12/10/2026\", points:[\n    \"<b>La synchro cloud ne t\u00e9l\u00e9charge plus l'\u00e9tat complet \u00e0 chaque cycle.</b> L'\u00e9tat partag\u00e9 p\u00e8se 3 \u00e0 4 Mo ; toutes les 90 secondes, chaque onglet ouvert le re-t\u00e9l\u00e9chargeait en entier pour comparer une date \u2014 quelques jours d'onglet ouvert suffisaient \u00e0 \u00e9puiser le quota de bande du plan gratuit, et Supabase a restreint le projet (vous avez peut-\u00eatre vu \u00ab cloud injoignable \u00bb). D\u00e9sormais la synchro de routine lit <b>le tampon horaire seul</b> (~100 octets) et ne t\u00e9l\u00e9charge le contenu complet que lorsqu'une d\u00e9cision le demande : premi\u00e8re connexion, mise \u00e0 jour \u00e0 prendre, fusion. <b>M\u00eames d\u00e9cisions, m\u00eame ordre, aucune saisie touch\u00e9e</b> \u2014 seul le poids du regard change. Rien \u00e0 faire de votre c\u00f4t\u00e9 : au prochain chargement, l'outil consomme ~1 000 fois moins. Le cloud redeviendra actif d\u00e8s la r\u00e9initialisation du quota par Supabase.\"\n  ]},\n  { version:\"4.80.0\", date:\"02/10/2026\", points:[\n    \"<b>L'\u00e9cran a de nouveau des couleurs, du relief, et des polices qui se distinguent.</b> Le fond redevient gris et les cartes blanches \u2014 c'est ce retrait qui les fait ressortir. Le bleu #1B5EA6, le rouge #E2001A, les angles \u00e0 3 et 4 px : l'identit\u00e9 d'avant le Design System B, rendue \u00e0 nouveau. Surtout, <b>les titres ont leur propre police</b> (Manrope) et redeviennent distincts du texte (Roboto) et des chiffres (IBM Plex Mono) : depuis la 4.63, c'\u00e9tait la m\u00eame pour tous, et l'\u00e9cran paraissait sans hi\u00e9rarchie. Rien n'est perdu en lisibilit\u00e9 : quatre des six contrastes de l'outil s'y trouvent <b>meilleurs</b> (le gris des intitul\u00e9s passe de 5,07:1 \u00e0 6,01:1), et les deux autres restent au-dessus du seuil. <b>Aucun chiffre, aucun calcul, aucune saisie n'est touch\u00e9.</b>\"\n  ]},\n  { version:\"4.79.0\", date:\"01/10/2026\", points:[\n    \"<b>Le bouton \u00ab \ud83d\udda8 A4 Mission \u00bb imprime enfin sa page.</b> Il \u00e9tait l\u00e0 depuis la 4.52 \u2014 la fonction derri\u00e8re n'existait pas (clic mort). L'A4 Mission raconte la d\u00e9marche en un feuillet : gains ACT\u00c9S et EN COURS en deux blocs distincts, timeline des essais r\u00e9cents avec leur statut (conforme / non conforme / arr\u00eat\u00e9 / en cours), plan poste par poste et prochaines \u00e9tapes. Elle se <b>recalcule \u00e0 chaque \u00e9dition</b> \u2014 c'est sa diff\u00e9rence avec la livraison, qui fige. Au passage : l'impression A4 des <b>livraisons</b> \u00e9tait cass\u00e9e depuis sa naissance (le CSS d'impression vivait dans le rapport autonome, pas dans l'outil) \u2014 les deux A4 s'impriment d\u00e9sormais seuls, sur la m\u00eame mise en page. Et l'interface s'est donn\u00e9 des <b>promesses v\u00e9rifi\u00e9es</b> : chaque bouton n'appelle que des fonctions qui existent \u2014 un clic mort est d\u00e9sormais vu par les tests.\"\n  ]},\n  { version:\"4.78.0\", date:\"01/10/2026\", points:[\n    \"<b>La vue CPP : l'\u00e9pine dorsale de l'outil.</b> Depuis l'accueil, bouton \u00ab \ud83d\udd0d Vue CPP \u00bb : chaque pi\u00e8ce avec son CPP outillage (la m\u00eame mesure que le classeur de Matis) <b>en face de la r\u00e9f\u00e9rence Matis</b>, l'\u00e9cart en toutes lettres \u2014 puis d\u00e9pliez : op\u00e9ration par op\u00e9ration avec sa part dans la pi\u00e8ce, outil par outil, logement par logement avec MABEC et co\u00fbt. Le temps machine s'affiche \u00e0 part et dit qu'il n'est pas comparable au classeur (constitution 2 quater). Lecture seule : rien n'est \u00e9crit.\"\n  ]},\n  { version:\"4.75.0\", date:\"01/10/2026\", points:[\n    \"<b>Depuis l\u2019accueil, la carte s\u2019ouvre SUR la ligne cliqu\u00e9e.</b> Tu cliques EMAG 3 dans le tableau de bord : la carte d\u00e9file jusqu\u2019\u00e0 la section EMAG 3, surlign\u00e9e deux secondes \u2014 plus jamais une autre ligne devant les yeux. Et la correction des correcteurs manquants (outils regroup\u00e9s avant la 4.74.2) est propos\u00e9e dans le bandeau.\"\n  ]},\n  { version:\"4.76.0\", date:\"01/10/2026\", points:[\n    \"<b>Un scenario affiche au mauvais endroit ne peut plus rien ecraser.</b> On a trouve un trou ou le scenario ouvert etait reecrit par-dessus ceux d une autre operation \u2014 sur tous les chemins de sauvegarde, export et partage. La hierarchie fait desormais foi, et l ecran te previent. Rien n est efface : la scene reste la ou elle est.\"\n  ]},\n  { version:\"4.74.2\", date:\"01/10/2026\", points:[\n    \"<b>La r\u00e9f\u00e9rence plaquette et le correcteur remplis depuis le classeur.</b> La colonne \u00ab ISO \u00bb du fichier de Matis remplit d\u00e9sormais la r\u00e9f\u00e9rence plaquette de chaque logement (elle \u00e9tait lue puis jet\u00e9e) \u2014 et le correcteur (le D1/D2 apr\u00e8s le num\u00e9ro d\u2019outil) remplit le champ Correcteur de l\u2019outil. La correction \u00e0 la demande compl\u00e8te aussi les r\u00e9f\u00e9rences vid\u00e9es hier : l\u2019ISO de ton T543 (TNGN160412\u2026 pour D1, SNGN090416\u2026 pour D2) est repris depuis les sc\u00e9narios \u00ab base excel \u00bb quand il y est connu.\"\n  ]},\n  { version:\"4.74.1\", date:\"01/10/2026\", points:[\n    \"<b>Le MABEC remis \u00e0 sa place.</b> Six logements portaient un code MABEC (\u00ab Z000 455 182 \u00bb) dans le champ \u00ab R\u00e9f\u00e9rence plaquette \u00bb \u2014 une inversion avec le fichier de Matis, o\u00f9 l\u2019ISO et le MABEC sont deux colonnes distinctes. La correction \u00e0 la demande remet le MABEC dans son champ ; l\u2019ISO n\u2019\u00e9tant pas dans les donn\u00e9es, la r\u00e9f\u00e9rence restera \u00e0 saisir. Le bandeau de d\u00e9marrage le propose avec le reste.\"\n  ]},\n  { version:\"4.74.0\", date:\"01/10/2026\", points:[\n    \"<b>La correction des outils D1/D2 arrive dans vos donn\u00e9es.</b> Les outils saisis AVANT la r\u00e8gle (\u00ab T543 D1 \u00bb + \u00ab T543 D2 \u00bb en deux outils) sont d\u00e9tect\u00e9s au d\u00e9marrage : un bandeau vous propose de les regrouper \u2014 un porte-outil = un outil \u00e0 logements. La correction est \u00c0 LA DEMANDE, avec le rapport de ce qui a boug\u00e9, et ne touche jamais un outil nu sans position.\"\n  ]},\n  { version:\"4.73.0\", date:\"01/10/2026\", points:[\n    \"<b>Le lecteur du classeur conna\u00eet la r\u00e8gle porte-outil.</b> Une ligne Excel = un logement : \u00ab T513 D1 \u00bb et \u00ab T513 D2 \u00bb se lisent d\u00e9sormais <b>T513 \u2014 2 logements</b>, chaque logement gardant le MABEC, le prix et les ar\u00eates de sa ligne \u2014 rien n'est fabriqu\u00e9. L'\u00e9cran dit ce qu'il regroupe (\u00ab 2 porte-outils regroup\u00e9s \u00e0 la lecture\u2026 \u00bb) au lieu de le faire en silence, et le nombre de logements se lit sur la ligne du d\u00e9tail.\"\n  ]},\n  { version:\"4.65.2\", date:\"30/09/2026\", points:[\n    \"<b>La table que la hi\u00e9rarchie lit.</b> Sous les tuiles, toutes les op\u00e9rations de toutes les lignes vivantes : ligne, op\u00e9ration, r\u00e9f\u00e9rence, gain unitaire, gain annuel (act\u00e9 et projet\u00e9 jamais m\u00e9lang\u00e9s), statut en toutes lettres \u2014 et un poste non impact\u00e9 reste affich\u00e9 \u00e0 \u00b10,000 \u20ac, il ne dispara\u00eet pas. Chaque ligne porte sa porte \u00ab Ouvrir \u2192 \u00bb. En pied : l'\u00e9quipe du suivi et les trois actions existantes (bilan atelier, exporter, historique).\"\n  ]},\n  { version:\"4.72.0\", date:\"30/09/2026\", points:[\n    \"<b>Les donnees du classeur de Matis, importables en un geste.</b> Les 129 outils et 192 logements du classeur, avec le bon nombre de logements par porte-outil : T543 avec D1 et D2, ce sont DEUX logements, pas deux outils. Le MABEC a enfin sa place dans l outil \u2014 c est lui qui relie chaque logement a son article. Et une ligne jamais travaillee affiche \u00ab jamais travaillee \u00bb, pas un zero invente.\"\n  ]},\n  { version:\"4.71.0\", date:\"30/09/2026\", points:[\n    \"<b>Un outil, deux correcteurs, deux logements.</b> C etait faux : l outil T543 avec D1 et D2 donnait TROIS logements, dont un provisoire jamais repris.corrige, et mesur\u00e9 sur ton cas avant. Ajoute : \u00ab T 543 D1 \u00bb et \u00ab T543 D1 \u00bb sont desormais le meme porte-outil, et une reparation peut reunir ce qui est deja saisi en double \u2014 sans jamais perdre un MABEC, un prix ou une mesure, et en te disant d abord ce qu elle va faire.\"\n  ]},\n  { version:\"4.70.2\", date:\"30/09/2026\", points:[\n    \"<b>Les champs ne sont plus des boites.</b> Un filet sobre sous la saisie, qui devient rouge qu on est dedans \u2014 la forme exacte de la charte. Les cases a cocher, les fichiers et les couleurs gardent leur cadre : un filet sous une case ne veut rien dire. Les tableaux, eux, sont rayes de filets gris et leurs en-tetes sont en capitales. Tout cela est de la CSS : aucune ligne de saisie n a bouge.\"\n  ]},\n  { version:\"4.70.1\", date:\"30/09/2026\", points:[\n    \"<b>Les boutons ne sont plus des paves.</b> Un bouton, c est desormais un disque de 34 px avec un chevron, puis le libelle \u2014 la forme exacte de la charte CeramTec. La barre porte son filet bicolore de 2 px et l onglet actif est souligne en rouge. Et le titre de l accueil passe de 21 px en mono a 36 px, avec le filet bleu et le mot-cle en rouge. La densite, elle, n a pas bouge : un regleur voit toujours tout sans defiler.\"\n  ]},\n  { version:\"4.69.0\", date:\"30/09/2026\", points:[\n    \"<b>L ecran est enfin noir et blanc.</b> Il portait 122 aplats de couleur \u2014 bleus, verts, ambres, rouges. La charte CeramTec est noire, blanche et grise : les couleurs d accent ne sont jamais des aplats, elles sont des signaux. Les 69 fonds tentes et les 13 pastilles pleines sont passes en blanc. Ce qui reste en couleur, ce sont les points, les barres et le texte des etats \u2014 la ou la couleur a un sens. Aucun mot d etat n a disparu.\"\n  ]},\n  { version:\"4.67.0\", date:\"30/09/2026\", points:[\n    \"<b>La page est blanche, comme la charte CeramTec.</b> Le fond etait gris clair : toute l ecran etait teinte. Il est blanc, et les cartes se detachent par leur contour \u2014 la charte dit que la couleur d accent ne doit jamais etre un aplat. Et le poids 600, absent de la charte, a disparu : 145 occurrences sont passees en 500.\"\n  ]},\n  { version:\"4.66.0\", date:\"30/09/2026\", points:[\n    \"<b>Les outils ne se creusent plus en double.</b> Si vous tapez T517 D2 a cote d un outil T517 D1, l outil vous le dit et vous pouvez les reunir en un seul outil a deux logements. Rien n est bloque tout seul, et vos prix, aretes et charnieres suivent le logement.\"\n  ]},\n  { version:\"4.65.0\", date:\"30/09/2026\", points:[\n    \"<b>L'accueil ouvre sur le tableau de bord.</b> L'en-t\u00eate porte le titre, le p\u00e9rim\u00e8tre r\u00e9el des lignes vivantes et l'index de l'\u00e9cran \u2014 et le bandeau des quatre chiffres arrive : \u00e9conomie valid\u00e9e (avec son p\u00e9rim\u00e8tre \u00e9crit), ralliement \u00e0 la cible CPP (le reste \u00e0 capter, calcul\u00e9), cadence (<b>\u2014 non mesur\u00e9e</b>, jamais estim\u00e9e) et lignes en engagement (un compte, avec les noms). Chaque chiffre remonte \u00e0 sa source ; chaque absence dit ce qui manque.\"\n  ]},\n  { version:\"4.64.0\", date:\"30/09/2026\", points:[\n    \"<b>On sait o\u00f9 l'on est, avant de saisir.</b> La barre de contexte affiche les 4 \u00e9tapes num\u00e9rot\u00e9es \u2014 ligne machine, r\u00e9f\u00e9rence pi\u00e8ce, op\u00e9ration, sc\u00e9nario \u2014 chacune cliquable (elle ouvre la liste r\u00e9elle de son niveau, jamais une saisie libre). Le sc\u00e9nario ouvert porte le bleu ; sans sc\u00e9nario, la barre le dit. Et quand l'outil est verrouill\u00e9 en consultation, le cadenas s'affiche <b>avec le mot</b> \u00ab verrouill\u00e9 \u00bb.\"\n  ]},\n  { version:\"4.63.0\", date:\"30/09/2026\", points:[\n    \"<b>Le Design System B entre dans l'outil.</b> Une seule palette de valeurs (encre noire, bleu #006AB3, rouge CeramTec #E30045, gris de la gamme industrielle), une seule famille de formes quasi-plate (2 px), une seule police sans-serif syst\u00e8me plus le mono pour tous les chiffres. Cinq polices embarqu\u00e9es partent (112 Ko de moins), l'impression d\u00e9rive des m\u00eames accents, le mode nuit et les rapports clients restent eux-m\u00eames.\"\n  ]},\n  { version:\"4.63.3\", date:\"30/09/2026\", points:[\n    \"<b>Les libelles sont enfin lisibles.</b> Le gris des intitules etait a 2,81:1 sur une carte blanche, sous le seuil, et sur du texte de 10 px on ne voit pas la difference : l ecran semblait inchange. Il est desormais a 5,07:1. Et la police : un nom qui n existe pas etait en tete de pile, donc l ecran avait une tete differente selon le poste. Les deux sont corriges.\"\n  ]},\n  { version:\"4.62.0\", date:\"30/09/2026\", points:[\n    \"<b>L\u2019outil s\u2019ouvre sur l\u2019overview.</b> Au lancement, c\u2019est l\u2019\u00e9cran d\u2019accueil qui appara\u00eet \u2014 l\u2019usine par lignes, la vue d\u2019ensemble avant le d\u00e9tail. La fen\u00eatre des nouveaut\u00e9s passe devant au premier lancement ; fermez-la, l\u2019usine est l\u00e0. Le d\u00e9tail du sc\u00e9nario reste accessible en un clic, comme toujours.\"\n  ]},\n  { version:\"4.61.0\", date:\"30/09/2026\", points:[\n    \"<b>Les lignes hors p\u00e9rim\u00e8tre ne se comptent plus une par une.</b> Weisser et PCI \u2014 d\u00e9clar\u00e9es, jamais travaill\u00e9es, rien \u00e0 piloter \u2014 vivent d\u00e9sormais ensemble dans <b>une seule tuile grise</b> : \u00ab 6 lignes hors p\u00e9rim\u00e8tre : WEISSER 1\u20134 \u00b7 PCI 4\u20135 \u00bb. Un clic ouvre la liste des noms et le choix explicite : d\u00e9clarer leurs machines quand elles entrent dans le suivi, ou les retirer. La grille ne dit plus \u00ab six choses \u00e0 faire \u00bb \u2014 il n\u2019y en a pas.\",\n    \"La recette de l\u2019\u00e9cran compte d\u00e9sormais le p\u00e9rim\u00e8tre : \u00ab 4 lignes actionnables sur 4 dans le p\u00e9rim\u00e8tre \u00b7 6 lignes hors p\u00e9rim\u00e8tre \u00bb.\"\n  ]},\n  { version:\"4.60.1\", date:\"30/09/2026\", points:[\n    \"<b>Deux corrections apr\u00e8s relecture de l\u2019\u00e9cran d\u2019accueil avec vos donn\u00e9es r\u00e9elles.</b> Un co\u00fbt qui ne couvre pas toutes les op\u00e9rations le dit d\u00e9sormais : \u00ab hors 1 op\u00e9ration non chiffr\u00e9e \u00bb \u2014 il ne passe plus pour complet. Et une ligne sans r\u00e9f\u00e9rences n\u2019affiche plus \u00ab volume annuel \u00e0 saisir \u00bb : sa pastille dit d\u00e9j\u00e0 \u00ab machines \u00e0 d\u00e9clarer \u00bb, une seule invitation \u00e0 la fois.\"\n  ]},\n  { version:\"4.60.0\", date:\"30/09/2026\", points:[\n    \"<b>Le premier \u00e9cran est l\u00e0 : \u00ab Accueil \u00bb, l\u2019usine par lignes.</b> Un bouton \u00ab Accueil \u00bb ouvre la grille : une tuile = une ligne enti\u00e8re (EMAG 1 avec ses r\u00e9f\u00e9rences et ses postes), avec le gain d\u00e9j\u00e0 act\u00e9 et celui en cours dans deux blocs s\u00e9par\u00e9s, le co\u00fbt pi\u00e8ce <b>\u00e9tiquet\u00e9 par la r\u00e9f\u00e9rence dominante</b> (\u00ab 356x26 : 0,038 \u20ac/pce \u00b7 +1 r\u00e9f. \u00bb), le chemin vers la cible, et <b>le \u00e0-faire en toutes lettres</b> (\u00ab OP20 \u2014 Cible du site pos\u00e9e, aucune mesure \u00bb).\",\n    \"<b>La pastille dit l\u2019action la plus urgente.</b> Un poste \u00e0 chiffrer passe avant tout ; sinon les essais en cours ; sinon la production gagn\u00e9e ; sinon l\u2019attente. Toujours le mot avec la couleur.\",\n    \"<b>Sans volume annuel, la tuile le dit</b> : \u00ab \u2014 volume annuel \u00e0 saisir \u00bb, jamais un co\u00fbt choisi en silence. Et une ligne jamais travaill\u00e9e ne montre aucun chiffre \u2014 son invitation seulement.\",\n    \"\u00ab Voir l\u2019atelier \u2192 \u00bb descend vers la carte des machines : ligne \u2192 machines \u2192 fiche \u2192 poste, sans cul-de-sac. L\u2019\u00e9cran affiche sa propre recette (lignes actionnables / total) et se d\u00e9clare creux sous un tiers \u2014 il dit s\u2019il sert.\"\n  ]},\n  { version:\"4.59.0\", date:\"30/09/2026\", points:[\n    \"<b>Les fondations de l\u2019\u00e9cran d\u2019accueil sont pos\u00e9es.</b> Une nouvelle fonction <b>gainLigne</b> r\u00e9sume une ligne enti\u00e8re \u2014 EMAG 1 avec ses quatre postes \u2014 en un seul objet : gains act\u00e9 et en cours, \u00e9tats compt\u00e9s, co\u00fbt pi\u00e8ce <b>\u00e9tiquet\u00e9 par la r\u00e9f\u00e9rence dominante</b>, et la prochaine \u00e9tape de chaque poste. Aucun \u00e9cran nouveau pour l\u2019instant : c\u2019est le calcul, test\u00e9, qui alimentera les tuiles.\"\n  ]},\n  { version:\"4.58.1\", date:\"30/09/2026\", points:[\n    \"<b>Une couleur qui ne crie plus.</b> Dans le d\u00e9tail du classeur, \u00ab pas encore saisi \u00bb s\u2019affiche d\u00e9sormais en gris discret, et l\u2019en-t\u00eate du panneau r\u00e9sume le rapprochement : \u00ab 14 suivies \u00b7 6 \u00e0 saisir \u00bb. L\u2019ambre reste r\u00e9serv\u00e9 aux vraies divergences \u2014 \u00e9cart classeur/suivi, production divergente \u2014 pour qu\u2019il garde son poids le jour o\u00f9 il parlera.\"\n  ]},\n  { version:\"4.58.0\", date:\"30/09/2026\", points:[\n    \"<b>Le MABEC trouve sa place dans la fiche outil.</b> Le champ \u00ab code article \u00bb du logement devient explicitement <b>MABEC (code article)</b> \u2014 saisissez le num\u00e9ro d\u2019article du classeur tel quel (ex. IM02 209 560) : c\u2019est lui qui relie le suivi au classeur de consommations.\",\n    \"<b>Et la convention d\u2019outillage est \u00e9crite noir sur blanc.</b> N\u00b0 outil = le porte-outil (T517) ; les positions D1, D2 = un logement chacune ; le correcteur d\u2019outil reste pour les mono-positions. Chaque champ le rappelle au survol.\",\n    \"<b>Le classeur se rapproche plaquette par plaquette.</b> Dans \u00ab Classeur Matis \u2192 D\u00e9tail par outil \u00bb, la colonne \u00ab Dans le suivi \u00bb dit o\u00f9 vit chaque plaquette : \u00ab suivi : T517 \u00b7 D1 (OP10) \u00bb, \u00ab suivi ailleurs \u00bb (m\u00eame plaquette sur un autre porte-outil \u2014 c\u2019est normal), ou \u00ab pas encore saisi \u00bb en ambre : l\u2019invitation \u00e0 compl\u00e9ter la fiche.\"\n  ]},\n  { version:\"4.57.0\", date:\"30/09/2026\", points:[\n    \"<b>Les \u00e9crans sont \u00e0 leur place.</b> Carte atelier, Tableau de bord, Vue de synth\u00e8se et Classeur Matis \u00e9taient planqu\u00e9s derri\u00e8re le bouton \u00ab \u2022\u2022\u2022 \u00bb : il fallait d\u00e9plier un menu pour les trouver. Ils sont d\u00e9sormais visibles dans la barre, \u00e0 c\u00f4t\u00e9 de l\u2019\u00e9cran de travail. Le menu ne garde plus que le rare : recherche, export CSV, rapports, options, historique.\"\n  ]},\n  { version:\"4.56.0\", date:\"30/09/2026\", points:[\n    \"<b>Le classeur et le suivi se r\u00e9pondent.</b> Chaque couple machine \u00d7 r\u00e9f\u00e9rence lu dans le classeur vous dit maintenant s\u2019il existe aussi dans le suivi, en toutes lettres : \u00ab dans le suivi : EMAG 1 \u00b7 356x26 RPI \u2014 production conforme (6 781/an) \u00bb. Ce qui n\u2019existe pas d\u2019un c\u00f4t\u00e9 se voit aussi : ligne non d\u00e9clar\u00e9e, r\u00e9f\u00e9rence absente, production non relev\u00e9e.\",\n    \"<b>Les divergences de production sautent aux yeux.</b> Quand le classeur et l\u2019outil ne racontent pas la m\u00eame production, la phrase passe en ambre et cite les deux chiffres : \u00ab le classeur dit 50/an, l\u2019outil d\u00e9clare 6 781/an \u00bb. Un \u00e9cart pareil ne doit plus se d\u00e9couvrir des mois plus tard.\",\n    \"Toujours un constat : cette lecture n\u2019\u00e9crit rien dans le suivi.\"\n  ]},\n  { version:\"4.55.1\", date:\"29/09/2026\", points:[\n    \"<b>Correction : un projet n\u2019accueille plus par erreur un sc\u00e9nario d\u2019une autre ligne.</b> Si le projet \u00ab Co\u00fbt et qualit\u00e9 EMAG 1 \u00bb ne contient que des sc\u00e9narios d\u2019EMAG 1, un sc\u00e9nario HESSAPP ne peut plus y \u00eatre rattach\u00e9 : l\u2019outil vous le dit et explique comment proc\u00e9der.\",\n    \"Avant, ce rattachement passait en silence d\u00e8s que le projet \u00e9tait vide \u2014 son nom annon\u00e7ait une r\u00e8gle que rien n\u2019appliquait. D\u00e9sormais un projet d\u00e9j\u00e0 ouvert \u00e0 plusieurs lignes continue d\u2019accueillir les deux sans question.\"\n  ]},\n  { version:\"4.55.0\", date:\"29/09/2026\", points:[\n    \"<b>Le classeur de Matis se lit directement dans l\u2019outil.</b> Un bouton \u00ab Classeur Matis \u00bb ouvre le suivi des consommations r\u00e9elles : production r\u00e9elle par machine et par r\u00e9f\u00e9rence, co\u00fbt r\u00e9ellement consomm\u00e9, et \u2014 le plus important \u2014 l\u2019\u00e9cart entre ce que l\u2019outil budg\u00e8te et ce que l\u2019atelier consomme. Vous choisissez votre fichier : il est lu sur ce poste, rien n\u2019est envoy\u00e9.\",\n    \"<b>Un chiffre \u00e0 surveiller.</b> Sur la p\u00e9riode 14-21/09, le budget-outillage annon\u00e7ait 5 218 \u20ac/an pour l\u2019ensemble des couples produits, la consommation r\u00e9elle est de 8 179 \u20ac : <b>2 961 \u20ac d\u2019\u00e9cart, soit +57 %</b>. Ce n\u2019est pas une erreur de saisie, c\u2019est l\u2019\u00e9cart entre un mod\u00e8le et le terrain \u2014 et c\u2019est exactement ce qu\u2019on ne voyait pas avant.\",\n    \"<b>Le d\u00e9tail par outil.</b> Num\u00e9ros d\u2019outil, articles, codes MABEC, CPP th\u00e9orique et r\u00e9el : le vocabulaire que Matis utilise tous les jours, mis en regard de l\u2019outillage saisi.\",\n    \"Cette lecture est un <b>constat</b>, pas un import : elle n\u2019\u00e9crit rien dans le suivi. La d\u00e9cision sur la production r\u00e9elle comme entit\u00e9 \u00e0 part enti\u00e8re reste \u00e0 prendre, et elle s\u2019appuiera sur ces mesures.\"\n  ]},\n  { version:\"4.54.0\", date:\"29/09/2026\", points:[\n    \"<b>La fiche de la machine.</b> Survolez (ou touchez) une tuile de la carte : l\u2019outil vous dit ce qui se passe sur ce poste \u2014 la r\u00e9f\u00e9rence qui y travaille, ce qui est d\u00e9j\u00e0 en production, ce qui reste \u00e0 faire. Puis un bouton emm\u00e8ne dans le d\u00e9tail.\",\n    \"<b>La prochaine \u00e9tape, \u00e9crite en toutes lettres.</b> \u00ab Terminer le protocole 5\u00d7 \u2014 2/5 essais relev\u00e9s \u00bb, \u00ab Cible du site pos\u00e9e, aucune mesure \u00bb, \u00ab Jamais travaill\u00e9 \u00bb. En atelier, on n\u2019a pas le temps d\u2019interpr\u00e9ter un tableau : l\u2019outil dit quoi faire maintenant.\",\n    \"<b>Un poste en production ne ment pas sur son avance.</b> Aucun \u00ab 0/5 essais \u00bb sur une machine d\u00e9j\u00e0 en s\u00e9rie \u2014 le protocole ne concerne que les essais en cours.\",\n    \"La couche 1 ne change ni vos donn\u00e9es ni vos calculs : elle se contente de dire ce que la carte et le d\u00e9tail s\u00e9parent d\u00e9j\u00e0.\"\n  ]},\n  { version:\"4.52.0\", date:\"29/09/2026\", points:[\n    \"<b>L'A4 Mission \u2014 le livrable hi\u00e9rarchie.</b> Un imprimable qui raconte la d\u00e9marche : les gains ACT\u00c9S en production, les gains EN COURS (valid\u00e9s ou en essai), la timeline des essais r\u00e9cents avec leur statut, et le plan poste par poste. Bouton \u00ab \ud83d\udda8 A4 Mission \u00bb dans la carte atelier \u2014 m\u00eame source de v\u00e9rit\u00e9 que la carte (jamais de chiffre divergent).\"\n  ]},\n  { version:\"4.51.2\", date:\"29/09/2026\", points:[\n    \"<b>La carte de l\u2019atelier.</b> Un nouveau bouton \u00ab Carte atelier \u00bb ouvre l\u2019usine en un coup d\u2019\u0153il : une tuile par machine, avec ce que l\u2019\u00e9quipe a d\u00e9j\u00e0 gagn\u00e9, ce qui est en cours, et ce qui reste \u00e0 faire. Survol ou premier toucher : la fiche du poste. Puis \u00ab Ouvrir le poste \u00bb pour entrer dans le d\u00e9tail.\",\n    \"<b>Quatre \u00e9tats, jamais un z\u00e9ro deguise\u00e9.</b> <b>Gagn\u00e9</b> (vert) : l\u2019outillage est pass\u00e9 en s\u00e9rie, le gain est act\u00e9. <b>En cours</b> (bleu) : un essai est relev\u00e9. <b>\u00c0 chiffrer</b> (ambre) : le site a pos\u00e9 une cible, la mesure manque \u2014 c\u2019est une invitation \u00e0 venir le mesurer, pas un poste rat\u00e9. <b>Opportunit\u00e9</b> (gris) : la machine est d\u00e9clar\u00e9e, jamais travaill\u00e9e.\",\n    \"<b>Les chiffres ne sont jamais l\u00e9gers.</b> Chaque montant vient du m\u00eame calcul que le bandeau d\u2019un sc\u00e9nario, sur le m\u00eame p\u00e9rim\u00e8tre. Une op\u00e9ration non chiffrable est annonc\u00e9e comme telle au lieu de laisser croire \u00e0 un gain de 0 \u20ac. Et la barre vers la cible du site tient compte des gains d\u00e9j\u00e0 r\u00e9alis\u00e9s.\",\n    \"<b>Un filtre qui montre le travail.</b> La carte s\u2019ouvre sur le projet actif ; \u00ab Toute l\u2019usine \u00bb d\u2019un clic. Elle affiche m\u00eame son taux de tuiles actionnables \u2014 si la carte devenait d\u00e9corative, elle vous le dirait.\"\n  ]},\n  { version:\"4.51.1\", date:\"29/09/2026\", points:[\n    \"<b>Correction backstage, visible dans la prochaine \u00e9tape.</b> Le chemin vers la cible tient compte des gains d\u00e9j\u00e0 r\u00e9alis\u00e9s : un poste o\u00f9 le nouveau outillage est pass\u00e9 en s\u00e9rie fait avancer la barre, au lieu de rester fig\u00e9. Aucun changement \u00e0 l'\u00e9cran pour l'instant.\"\n  ]},\n  { version:\"4.51.0\", date:\"29/09/2026\", points:[\n    \"<b>Le calcul des gains par poste est pr\u00eat pour la carte de l'atelier.</b> L'outil sait d\u00e9sormais r\u00e9pondre, machine par machine : quel gain est d\u00e9j\u00e0 act\u00e9 en s\u00e9rie, quel gain est encore projet\u00e9, et o\u00f9 en est le poste par rapport \u00e0 la cible du site.\",\n    \"<b>Un gain n'appara\u00eet que s'il est v\u00e9rifiable.</b> Chaque chiffre est compar\u00e9 sur le m\u00eame p\u00e9rim\u00e8tre que le bandeau d'un sc\u00e9nario \u2014 jamais un total compar\u00e9 \u00e0 un autre total. Un poste dont la production n'est pas chiffrable reste affich\u00e9 comme tel au lieu de laisser croire \u00e0 un gain de z\u00e9ro.\",\n    \"<b>Quatre \u00e9tats de poste, une seule r\u00e8gle.</b> Vert : le gain est act\u00e9 en s\u00e9rie. Bleu : un essai est en cours. Ambre : une cible est pos\u00e9e, le poste reste \u00e0 chiffrer. Gris : le poste est d\u00e9clar\u00e9 mais pas encore travaill\u00e9 \u2014 une opportunit\u00e9, pas un \u00e9chec.\",\n    \"Aucun changement visible \u00e0 l'\u00e9cran pour l'instant : c'est le socle de calcul de la prochaine \u00e9tape, la vue en tuiles de l'atelier.\"\n  ]},\n  { version:\"4.50.0\", date:\"29/09/2026\", points:[\n    \"<b>Pr\u00e9paration de la carte atelier.</b> Chaque OP porte d\u00e9sormais un code (OP10, OP30\u2026) d\u00e9riv\u00e9 de son nom, et la topologie machines de l'atelier est d\u00e9clar\u00e9e par ligne \u2014 le socle technique de la future vue en tuiles machines (travail engag\u00e9 avec l'\u00e9quipe). Aucun changement visible \u00e0 l'\u00e9cran.\"\n  ]},\n  { version:\"4.49.4\", date:\"29/09/2026\", points:[\n    \"<b>Corrig\u00e9 : le co\u00fbt pi\u00e8ce complet compte maintenant toutes les OPs qui ont une prod.</b> Le co\u00fbt de prod d'une OP, c'est d'abord la prod r\u00e9elle (\u2605), l'excel en repli \u2014 apr\u00e8s le merge OP40 (DWG \u2605 rempla\u00e7ant l'excel), l'OP40 avait disparu du d\u00e9compte. Et une OP sans sc\u00e9nario chiffrable s'affiche d\u00e9sormais \u00ab non chiffr\u00e9e \u2014 \u00e0 compl\u00e9ter \u00bb au lieu de dispara\u00eetre silencieusement (l'OP20 de la 356x26 attend ses valeurs).\"\n  ]},\n  { version:\"4.49.3\", date:\"29/09/2026\", points:[\n    \"<b>Message de bienvenue \u00e0 la premi\u00e8re ouverture.</b> Un \u00e9cran d'accueil pr\u00e9sente la base 2026/2027 et le geste de mise \u00e0 jour de l'application (une version ancienne efface les cibles de co\u00fbt au partage). Affich\u00e9 une fois par poste.\"\n  ]},\n  { version:\"4.49.2\", date:\"28/09/2026\", points:[\n    \"<b>Corrig\u00e9 : le graphe de tendance redevient lisible apr\u00e8s compl\u00e9tion.</b> Son \u00e9chelle horizontale \u00e9tait cal\u00e9e sur la plus grande charni\u00e8re de TOUT l'outillage du sc\u00e9nario \u2014 depuis \u00ab Compl\u00e9ter depuis la prod \u00bb, les outils longs de l'excel (300 \u00e0 4000 pi\u00e8ces) \u00e9crasaient les pr\u00e9l\u00e8vements r\u00e9els sur une fine bande. L'\u00e9chelle suit d\u00e9sormais les charni\u00e8res des logements r\u00e9ellement suivis par les essais trac\u00e9s.\"\n  ]},\n  { version:\"4.49.1\", date:\"28/09/2026\", points:[\n    \"<b>Corrig\u00e9 : la fusion ne crie plus au conflit pour rien.</b> La comparaison d'essais \u00e0 l'import/synchro \u00e9tait sensible \u00e0 l'ordre des cl\u00e9s du fichier JSON \u2014 un aller-retour export/import suffisait \u00e0 d\u00e9clarer des \u00ab conflits \u00e0 v\u00e9rifier \u00bb sur des essais strictement identiques (5 faux positifs constat\u00e9s). La comparaison est d\u00e9sormais canonique : seul le contenu compte.\"\n  ]},\n  { version:\"4.49.0\", date:\"28/09/2026\", points:[\n    \"<b>La feuille de route arrive.</b> Un bandeau \u00ab Co\u00fbt pi\u00e8ce complet \u00bb en t\u00eate d'\u00e9cran somme le CPP de prod de toutes les OPs de la r\u00e9f\u00e9rence, le confronte \u00e0 la cible du site et montre le meilleur essai en cours par OP. La vue de synth\u00e8se ouvre sur la feuille de route : barre prod \u2192 cible avec le % de chemin parcouru, statut par OP (pass\u00e9 en s\u00e9rie / valid\u00e9 5\u00d7 / essai en cours / prod seule), gain disponible annualis\u00e9. Et la cascade du gain ne dispara\u00eet plus silencieusement : elle explique pourquoi elle est vide quand c'est le cas.\"\n  ]},\n  { version:\"4.48.0\", date:\"28/09/2026\", points:[\n    \"<b>\u00ab \u229e Compl\u00e9ter depuis la prod \u00bb.</b> Sur un sc\u00e9nario d'essai incomplet, un bouton ajoute les outils qui tournent en prod (base excel) mais manquent ici \u2014 avec aper\u00e7u et confirmation. Les outils d'essai gardent leurs conditions, les essais/pr\u00e9l\u00e8vements/photos ne sont pas touch\u00e9s : un ajout pur, indispensable pour comparer un sc\u00e9nario d'essai \u00e0 une prod compl\u00e8te sans fausser le co\u00fbt pi\u00e8ce.\"\n  ]},\n  { version:\"4.47.1\", date:\"28/09/2026\", points:[\n    \"<b>Corrig\u00e9 : un sc\u00e9nario d'essai ne s'affichait pas au clic.</b> Sur les sc\u00e9narios sans mesure Droite/Gauche (les sc\u00e9narios OP40 notamment), le rendu plantait silencieusement et l'\u00e9cran restait fig\u00e9 sur le sc\u00e9nario pr\u00e9c\u00e9dent. La cause \u00e9tait un bug latent pr\u00e9sent depuis toujours, r\u00e9v\u00e9l\u00e9 par les nouveaux sc\u00e9narios de la base 2026/2027.\"\n  ]},\n  { version:\"4.47.0\", date:\"28/09/2026\", points:[\n    \"<b>Le travail simultan\u00e9 se voit maintenant d'un coup d'\u0153il.</b> Les outils qui usinent ensemble sont enferm\u00e9s dans un bloc ambre avec l'en-t\u00eate \u00ab \u21c9 Travail simultan\u00e9 \u2014 seul le plus long compte dans le cycle \u00bb, dans la vue d'ensemble de la composition. Le badge de la fiche repli\u00e9e passe \u00e0 la m\u00eame couleur ambre : un seul code visuel pour le concept.\"\n  ]},\n  { version:\"4.46.1\", date:\"28/09/2026\", points:[\n    \"<b>Cible de co\u00fbt pi\u00e8ce par r\u00e9f\u00e9rence.</b> Le co\u00fbt cible du site (onglets \u00ab Evolution co\u00fbt pi\u00e8ce \u00bb de l'excel consommations \u2014 0,212 \u20ac sur la 304x28, 0,129 \u20ac sur la 302x26 HESSAPP\u2026) est d\u00e9sormais une donn\u00e9e de la r\u00e9f\u00e9rence : import\u00e9e, persist\u00e9e, et affich\u00e9e dans la cellule co\u00fbt du sc\u00e9nario de r\u00e9f\u00e9rence pour comparer d'un coup d'\u0153il le r\u00e9alis\u00e9 \u00e0 l'objectif.\"\n  ]},\n  { version:\"4.46.0\", date:\"28/09/2026\", points:[\n    \"<b>Retour au design system d'origine.</b> Manrope et Public Sans reprennent les titres, les gros chiffres et le texte (l'identit\u00e9 pos\u00e9e \u00e0 la v4.29), IBM Plex Mono garde les chiffres \u2014 l'identit\u00e9 couleur SPK by CeramTec et toutes les \u00e9volutions d'\u00e9cran restent inchang\u00e9es.\"\n  ]},\n  { version:\"4.45.0\", date:\"28/09/2026\", points:[\n    \"<b>Retour du terrain : les comparaisons ne m\u00e9langent plus les p\u00e9rim\u00e8tres.</b> Quand un sc\u00e9nario a des mesures de cycle compl\u00e8tes (donc un co\u00fbt avec temps machine) et que sa r\u00e9f\u00e9rence n'a pas de cycle chiffrable, le % de gain se calculait sur un total avec machine contre un total sans \u2014 le sc\u00e9nario paraissait plus cher qu'il n'\u00e9tait. D\u00e9sormais le % se calcule sur le p\u00e9rim\u00e8tre commun des deux c\u00f4t\u00e9s, hors machine si besoin, avec un avertissement explicite et l'invitation \u00e0 renseigner le cycle de r\u00e9f\u00e9rence en secondes pour un \u00ab tout compris \u00bb. Le gain annuel suit la m\u00eame r\u00e8gle.\"\n  ]},\n  { version:\"4.44.0\", date:\"25/09/2026\", points:[\n    \"<b>Retour d'audit : la feuille de style remise d'aplomb.</b> Les patchs dat\u00e9s des versions 4.32 \u00e0 4.41 sont consolid\u00e9s en un seul bloc document\u00e9 (fini la pile \u00ab dernier gagne \u00bb qui avait caus\u00e9 le bug d'affichage 4.40), les classes CSS mortes des refontes sont purg\u00e9es, et les derni\u00e8res couleurs en dur rejoignent les tokens.\"\n  ]},\n  { version:\"4.43.0\", date:\"25/09/2026\", points:[\n    \"<b>Retour d'audit : le syst\u00e8me de polices repasse au propre.</b> Les chiffres de saisie et de mesure retrouvent une vraie police \u00e0 chasse fixe (IBM Plex Mono, d\u00e9j\u00e0 embarqu\u00e9e pour les rapports), les deux polices orphelines depuis le changement d'identit\u00e9 sont retir\u00e9es (\u221267 Ko sur le fichier), et le faux gras dispara\u00eet des titres et des gros chiffres \u2014 la hi\u00e9rarchie vient d\u00e9sormais de la taille et de l'encre.\"\n  ]},\n  { version:\"4.42.0\", date:\"25/09/2026\", points:[\n    \"<b>Retour d'audit : resserrement de la confidentialit\u00e9.</b> L'indice thermique du widget Fr\u00b7Fa ne s'affiche plus que pour l'auteur du projet et ne part jamais dans les pages imprim\u00e9es \u2014 le reste de l'outil (saisie, calculs, Fr/Fa) est inchang\u00e9.\"\n  ]},\n  { version:\"4.41.1\", date:\"25/09/2026\", points:[\n    \"<b>Petites r\u00e9parations d'affichage rep\u00e9r\u00e9es par l'audit.</b> Textes corrompus r\u00e9par\u00e9s (r\u00e9sum\u00e9 de la Tendance, annonces 4.38), libell\u00e9 de la cellule Validation \u00e9clairci pour retrouver le contraste r\u00e9glementaire, secondes de cycle d\u00e9sormais affich\u00e9es aussi dans les tuiles de sc\u00e9narios (comme dans le tableau de bord), et textes d'Options remis en phase avec le fonctionnement r\u00e9el du module cycle.\"\n  ]},\n  { version:\"4.41.0\", date:\"25/09/2026\", points:[\n    \"<b>Le simultan\u00e9 se coche outil par outil.</b> Chaque fiche outil (sauf la premi\u00e8re) gagne une case \u00ab \u21c9 Tourne en simultan\u00e9 avec l'outil pr\u00e9c\u00e9dent \u00bb : coch\u00e9e, l'outil rejoint le groupe de son voisin \u2014 le groupe vaut le temps de son outil le plus long, et le cycle est la somme des groupes. Exemple : outil \u00e0 2 logements (30+20 s), puis deux outils simultan\u00e9s de 20 et 25 s \u2192 cycle 55 s, pas 95. Un badge \u00ab \u21c9 simultan\u00e9 \u00bb reste visible sur les fiches repli\u00e9es, et la cellule Temps de cycle nomme le nombre de groupes.\"\n  ]},\n  { version:\"4.40.0\", date:\"25/09/2026\", points:[\n    \"<b>Le mode \u00ab simultan\u00e9 \u00bb passe au niveau des outils, plus du sc\u00e9nario entier.</b> La physique d'une OP : dans un outil, les logements encha\u00eenent toujours \u00e0 la suite (leurs temps s'additionnent) ; ce sont les outils qui tournent en simultan\u00e9 \u2014 \u00e9bauche ou finition piste sur deux stations \u2014 et le cycle est alors le temps de l'outil le plus long. Le s\u00e9lecteur de la cellule Temps de cycle refl\u00e8te cette logique (\u00ab outils en s\u00e9rie / outils simultan\u00e9s \u00bb).\",\n    \"<b>Les libell\u00e9s du bandeau bleu redeviennent lisibles.</b> La passe \u00ab \u00e9tiquettes en recul \u00bb de la 4.34 \u00e9crasait aussi les libell\u00e9s et les valeurs du tableau de bord en gris/noir sur l'aplat bleu. Le bandeau garde d\u00e9sormais sa propre hi\u00e9rarchie d'encre claire, sur le bleu comme sur le vert de la cellule validation.\"\n  ]},\n  { version:\"4.39.0\", date:\"25/09/2026\", points:[\n    \"<b>Le cycle par logement devient lisible et pilotable.</b> Le d\u00e9pliant de chaque tuile logement gagne une section Cycle : temps de coupe mesur\u00e9, part du cycle, indice conditions vs base. La cellule Temps de cycle du tableau de bord affiche d\u00e9sormais toujours les secondes, la cadence, d'o\u00f9 vient la valeur (mesures machine ou indice), et le co\u00fbt machine par pi\u00e8ce d\u00e8s que le taux horaire de la ligne est rempli \u2014 affich\u00e9 m\u00eame quand l'option ne le pond\u00e8re pas encore dans le co\u00fbt. Et les mesures comptent d\u00e8s qu'elles sont compl\u00e8tes (tous les logements), sans interrupteur : l'option \u00ab d\u00e9tail du cycle \u00bb ne d\u00e9cide plus que de la colonne \u00e0 l'impression.\",\n    \"<b>Logements en s\u00e9rie ou en simultan\u00e9 \u2014 au choix, par sc\u00e9nario.</b> En finition OP40, les deux outils tournent en m\u00eame temps : le cycle est alors le temps du plus long, pas la somme. Un s\u00e9lecteur dans la cellule Temps de cycle bascule le calcul ; en usinage s\u00e9quentiel, la somme s'applique comme avant.\",\n    \"<b>Le temps de d\u00e9placement sort du calcul.</b> Inchronom\u00e9trable et invariable d'un sc\u00e9nario \u00e0 l'autre, il ne devait rien dire : il quitte la saisie, le tableau d'impression et le total (les valeurs d\u00e9j\u00e0 saisies restent dans les donn\u00e9es, simplement ignor\u00e9es).\",\n    \"<b>Fini les \u00ab Bol + Piste \u00bb grav\u00e9s dans le code.</b> Le logement qui ancre l'indice de cycle est le premier logement du sc\u00e9nario (l'ordre des fiches fait foi), plus de recherche par nom h\u00e9rit\u00e9e de la toute premi\u00e8re saisie ; le libell\u00e9 \u00ab \u20ac/ar\u00eate (bol + piste) \u00bb devient \u00ab \u20ac/ar\u00eate (tous logements) \u00bb.\"\n  ]},\n  { version:\"4.38.0\", date:\"24/09/2026\", points:[\n    \"<b>La tendance passe en zone de lecture.</b> Le graphique d\\'\u00e9volution au fil des pi\u00e8ces est repli\u00e9 par d\u00e9faut : il ne concurrence plus la saisie des essais, et s\\'ouvre au clic.\",\n    \"Rappel 4.37 : zone de d\u00e9tail regroup\u00e9e (calcul, consommation annuelle, pi\u00e8ces d\u00e9tach\u00e9es).\"\n  ]},\n  { version:\"4.37.0\", date:\"24/09/2026\", points:[\n    \"<b>Zone de d\u00e9tail regroup\u00e9e.</b> D\u00e9tail du calcul, consommation annuelle et pi\u00e8ces d\u00e9tach\u00e9es ne font plus qu\\'un seul bloc repliable : l\\'\u00e9cran montre la d\u00e9cision (zones 1 et 2) et tient le calcul \u00e0 un clic.\",\n    \"Rappel 4.36 : \u00e9cran en trois zones nomm\u00e9es (R\u00e9ponse / Sc\u00e9narios / Tra\u00e7abilit\u00e9).\"\n  ]},\n  { version:\"4.36.0\", date:\"24/09/2026\", points:[\n    \"<b>\u00c9cran en trois zones nomm\u00e9es.</b> 1 \u00b7 R\u00e9ponse (base de comparaison et meilleur co\u00fbt), 2 \u00b7 Sc\u00e9narios, 3 \u00b7 Tra\u00e7abilit\u00e9 du sc\u00e9nario ouvert. On sait toujours o\u00f9 l\\'on est dans l\\'\u00e9cran.\",\n    \"Rappel 4.35 : rep\u00e8re de zone, deux niveaux de libell\u00e9s, blocs p\u00e9riph\u00e9riques repli\u00e9s.\"\n  ]},\n  { version:\"4.35.0\", date:\"24/09/2026\", points:[\n    \"<b>Rep\u00e8re de zone.</b> On voit o\u00f9 commence la tra\u00e7abilit\u00e9 du sc\u00e9nario ouvert (outils, cycle, essais, rebut), au lieu d\\'encha\u00eener les blocs \u00e0 la suite.\",\n    \"Rappel 4.34 : deux niveaux de libell\u00e9s \u2014 \u00e9tiquettes en recul, valeurs en avant.\"\n  ]},\n  { version:\"4.34.0\", date:\"24/09/2026\", points:[\n    \"<b>Deux niveaux de libell\u00e9s.</b> Les \u00e9tiquettes (petites, grises) reculent, les valeurs et les chiffres avancent : l\\'\u00e9cran se lit par niveaux au lieu d\\'un aplat uniforme.\",\n    \"Rappel 4.33 : blocs p\u00e9riph\u00e9riques repli\u00e9s par d\u00e9faut, respiration entre les blocs, polices embarqu\u00e9es r\u00e9ellement actives.\"\n  ]},\n  { version:\"4.33.0\", date:\"24/09/2026\", points:[\n    \"<b>L\\'\u00e9cran respire.</b> Les blocs p\u00e9riph\u00e9riques (consommation annuelle, pi\u00e8ces d\u00e9tach\u00e9es) sont repli\u00e9s par d\u00e9faut : l\\'essentiel reste visible, le d\u00e9tail s\\'ouvre au clic \u2014 et l\\'impression reste compl\u00e8te.\",\n    \"<b>Zones mieux s\u00e9par\u00e9es.</b> Espacements revus entre les grands blocs pour que l\\'\u0153il distingue les zones au lieu de lire un flux continu.\",\n    \"Rappel 4.32 : base de comparaison explicite (le \u2605 n\\'est plus confondu avec la base) et identit\u00e9 SPK by CeramTec.\"\n  ]},\n  { version:\"4.32.0\", date:\"24/09/2026\", points:[\n    \"<b>Base de comparaison explicite.</b> L'outil distingue d\u00e9sormais le <b>sc\u00e9nario en production (\u2605)</b> \u2014 un statut \u2014 de la <b>base de comparaison</b> \u2014 un choix. Un bandeau nomme la base, et un menu permet d'en changer sans toucher au statut.\",\n    \"<b>Fini l'illogisme.</b> Si la base est l'option la plus ch\u00e8re, l'outil l'annonce ; il affiche aussi le meilleur co\u00fbt et son \u00e9cart r\u00e9el, en toutes lettres.\",\n    \"<b>Vue comparative regroup\u00e9e.</b> Crit\u00e8res rang\u00e9s en blocs (\u00c9conomique / Process / Qualit\u00e9), meilleure valeur en vert, plus d\u00e9favorable en rouge, colonne de base marqu\u00e9e.\",\n    \"<b>Identit\u00e9 SPK by CeramTec</b> : bleu #1B5EA6, rouge #E2001A en accent, rayon 3 px, titres de section remis au premier plan.\",\n    \"Aucun changement de logique de calcul : m\u00eames co\u00fbts, m\u00eames essais, m\u00eames donn\u00e9es.\"\n  ]},\n  { version:\"4.31.0\", date:\"24/09/2026\", points:[\n    \"<b>Vue de synth\u00e8se comparative regroup\u00e9e.</b> Les crit\u00e8res sont rang\u00e9s en trois blocs \u2014 \u00c9conomique, Process, Qualit\u00e9 &amp; essais \u2014 au lieu d'une liste plate.\",\n    \"<b>Meilleure valeur mise en \u00e9vidence.</b> Pour chaque crit\u00e8re, le meilleur r\u00e9sultat passe en vert et le plus d\u00e9favorable en rouge ; l'en-t\u00eate de chaque sc\u00e9nario compte les crit\u00e8res qu'il remporte.\",\n    \"<b>Cascade du gain.</b> Un bloc explique d'o\u00f9 vient l'\u00e9conomie, poste par poste (plaquettes, pi\u00e8ces d\u00e9tach\u00e9es, temps machine, rebut), face au sc\u00e9nario de r\u00e9f\u00e9rence.\",\n    \"Aucun changement de logique de calcul ni de donn\u00e9e : seuls l'ordre, le regroupement et la mise en \u00e9vidence \u00e9voluent.\"\n  ]},\n  { version:\"4.30.0\", date:\"24/09/2026\", points:[\n    \"<b>Le verdict et les gros chiffres fusionnent en un seul tableau de bord.</b> Fini la bande de verdict au-dessus d'une bande de chiffres qui r\u00e9p\u00e9tait les m\u00eames nombres en tuiles : d\u00e9sormais une seule bande \u2014 la r\u00e9ponse (gain, verdict d'essai, r\u00e9f\u00e9rence) ouvre la marche, suivie du co\u00fbt pi\u00e8ce, du gain annuel, de la dur\u00e9e de vie vis\u00e9e (nouvelle cellule, avec la r\u00e9f\u00e9rence \u00e0 c\u00f4t\u00e9), du \u20ac/ar\u00eate, du cycle et de la validation (qui affiche aussi le % de pr\u00e9l\u00e8vements hors tol\u00e9rance).\",\n    \"<b>Le contexte de l'essai se replie.</b> But, observations, r\u00e9dacteur, dates de d\u00e9but/fin et programme CNC sont regroup\u00e9s dans un bloc \u00ab Contexte \u00bb : ouvert tant que l'essai est vierge, repli\u00e9 d\u00e8s qu'il est rempli (un aper\u00e7u du but reste lisible). L'\u00e9cran d'un essai commence d\u00e9sormais par ce qui compte tous les jours : conditions, pr\u00e9l\u00e8vements, progression.\",\n    \"<b>Ligne crit\u00e8res d'essais resserr\u00e9e.</b> Les boutons + Ra / + VE / + Autre crit\u00e8re tiennent sur la ligne au lieu de s'empiler en colonne, la note \u00ab valeur OP \u00bb ne wrappe plus sur trois lignes (la phrase compl\u00e8te passe en info-bulle), et la sp\u00e9c usine s'aligne \u00e0 droite de la m\u00eame ligne.\",\n    \"<b>Typographie des chiffres assainie.</b> Le mono repasse sur sa vraie graisse 600 partout o\u00f9 le faux gras 700 \u00e9tait synth\u00e9tis\u00e9 (IBM Plex Mono 700 n'est pas embarqu\u00e9), les gros chiffres deviennent tabulaires (un chiffre qui change ne fait plus bouger ses voisins), les unit\u00e9s sont normalis\u00e9es (10,5 px) et le tableau d'impression utilise la m\u00eame police mono que l'\u00e9cran pour les valeurs saisies.\"\n  ]},\n  { version:\"4.29.0\", date:\"24/09/2026\", points:[\n    \"<b>\u00c9tiquettes de projet : le rattachement cross-lignes ne passe plus en silence.</b> Un projet peut l\u00e9gitimement grouper plusieurs lignes (une plaquette test\u00e9e sur deux machines) \u2014 mais rattacher un sc\u00e9nario de HESSAPP au projet \u00ab co\u00fbt EMAG 1 \u00bb est presque toujours un accident. D\u00e9sormais l'info-bulle de chaque \u00e9tiquette dit quelles lignes le projet couvre d\u00e9j\u00e0, et un clic qui traverse les lignes demande confirmation. On avertit, on ne bloque pas.\",\n    \"<b>Le co\u00fbt annuel g\u00e9n\u00e9ral se d\u00e9plie aussi.</b> Un clic sur la tuile \u00ab Co\u00fbt annuel \u00bb (ou \u00ab Gain annuel \u00bb) du sc\u00e9nario d\u00e9taille le calcul : chaque composante du co\u00fbt complet \u2014 outillage (logement par logement, avec le prix \u00f7 ar\u00eates \u00d7 charni\u00e8re de chacun), pi\u00e8ces d\u00e9tach\u00e9es, temps machine, rebut \u2014 multipli\u00e9e par la production. Pour un sc\u00e9nario d'essai : r\u00e9f\u00e9rence vs sc\u00e9nario, et le gain qui en r\u00e9sulte, heures machine comprises.\"\n  ]},\n  { version:\"4.28.0\", date:\"23/09/2026\", points:[\n    \"<b>Le d\u00e9tail du calcul au clic sur la tuile.</b> Chaque tuile de la vue d'ensemble se d\u00e9plie maintenant op\u00e9ration par op\u00e9ration : prix plaquette, dur\u00e9e de vie vis\u00e9e, co\u00fbt pi\u00e8ce (prix \u00f7 ar\u00eates \u00d7 charni\u00e8re), production annuelle, plaquettes consomm\u00e9es par an, et le co\u00fbt annuel qui en r\u00e9sulte \u2014 avec les vrais chiffres du logement, pas une formule abstraite. L'\u00e9tat d\u00e9pli\u00e9 survit aux rafra\u00eechissements de l'\u00e9cran.\",\n    \"<b>Derniers noms fig\u00e9s traqu\u00e9s.</b> Quatre affichages r\u00e9sistaient encore au renommage : la barre de progression du mode atelier, le s\u00e9lecteur de logement des pr\u00e9l\u00e8vements, son \u00e9quivalent \u00e0 l'impression, et la fen\u00eatre de comparaison d'essais (qui affiche aussi d\u00e9sormais le statut \u00ab Arr\u00eat\u00e9 \u00bb). Tous relisent maintenant le nom actuel du sc\u00e9nario.\"\n  ]},\n  { version:\"4.27.2\", date:\"23/09/2026\", points:[\n    \"<b>HESSAPP : plus de filigrane.</b> Ligne unique \u2014 la teinte kaki seule l'identifie ; le texte r\u00e9p\u00e9t\u00e9 en fond a \u00e9t\u00e9 retir\u00e9.\"\n  ]},\n  { version:\"4.27.1\", date:\"23/09/2026\", points:[\n    \"<b>Fond de ligne : kaki HESSAPP renforc\u00e9 et filigrane affin\u00e9.</b> Le vert kaki gagne en tenue, et le code ligne en filigrane est plus petit donc plus souvent r\u00e9p\u00e9t\u00e9 \u2014 la ligne se reconna\u00eet d'un coup d'\u0153il depuis n'importe quel endroit de la page.\"\n  ]},\n  { version:\"4.27.0\", date:\"23/09/2026\", points:[\n    \"<b>L'atelier entier est dans l'outil.</b> Les 10 lignes de Sept Fons sont cr\u00e9\u00e9es d'office, dans l'ordre physique du fond vers l'entr\u00e9e : Weisser 1-4, HESSAPP, EMAG 1-3, PCI 1-2 (les lignes d\u00e9j\u00e0 existantes ne bougent pas ; une ligne supprim\u00e9e volontairement ne revient pas). HESSAPP est not\u00e9e double OP droite/gauche, comme EMAG 1 \u2014 ses OP se cr\u00e9eront au moment de ses premiers essais.\",\n    \"<b>La page prend la couleur de la ligne affich\u00e9e.</b> Fond teint\u00e9 l\u00e9ger par famille \u2014 <b>Weisser = rouge</b>, <b>HESSAPP = kaki</b>, <b>EMAG = gris</b>, <b>PCI = bleu</b> \u2014 avec le code ligne (W1, E1, P1\u2026) en filigrane r\u00e9p\u00e9t\u00e9. S'adapte au mode nuit, ne s'imprime pas.\"\n  ]},\n  { version:\"4.26.0\", date:\"23/09/2026\", points:[\n    \"<b>Le bandeau \u00ab Reprendre \u00bb parle du sc\u00e9nario que vous avez sous les yeux.</b> Il proposait toujours l'essai en cours le plus r\u00e9cent toutes lignes confondues : en travaillant sur une cr\u00e9ation neuve, c'est un vieil essai d'un autre sc\u00e9nario (et les noms de logements d'\u00e9poque) qui s'affichait. D\u00e9sormais il propose <b>d'abord un essai en cours du sc\u00e9nario affich\u00e9</b> ; \u00e0 d\u00e9faut seulement, le plus r\u00e9cent de l'outil.\",\n    \"<b>La fen\u00eatre des nouveaut\u00e9s ne raconte plus tout l'historique.</b> Seules les \u00e9volutions des <b>10 derniers jours</b> s'affichent au d\u00e9marrage \u2014 le reste a \u00e9t\u00e9 vu ou ne concerne plus.\"\n  ]},\n  { version:\"4.25.0\", date:\"23/09/2026\", points:[\n    \"<b>Cl\u00f4turer un essai arr\u00eat\u00e9 avant sa charni\u00e8re.</b> Jusqu'ici un essai stopp\u00e9 net (insert cass\u00e9, brut \u00e9clat\u00e9, incident machine) restait \u00ab en cours \u2014 X pi\u00e8ces \u00e0 saisir \u00bb pour toujours, et revenait dans le bandeau de reprise. Un bouton <b>\u23f9 Cl\u00f4turer</b> sur chaque essai pose la d\u00e9cision : motif (casse, hors tol\u00e9rance, brut, incident machine, autre), pr\u00e9cision, date d'arr\u00eat. L'essai passe <b>\u23f9 Arr\u00eat\u00e9</b> \u2014 ni conforme ni non conforme : il sort du compteur 5\u00d7 et de la reprise, et le rapport d'essai l'affiche avec le motif. R\u00e9ouvrable \u00e0 tout moment, pr\u00e9l\u00e8vements intacts.\",\n    \"<b>Compteur honn\u00eate.</b> Le r\u00e9sum\u00e9 du sc\u00e9nario affiche d\u00e9sormais les essais \u00ab arr\u00eat\u00e9s avant charni\u00e8re \u00bb \u00e0 part \u2014 les non conformes restent les non conformes.\"\n  ]},\n  { version:\"4.24.0\", date:\"23/09/2026\", points:[\n    \"<b>Les photos de l'essai partent dans le rapport.</b> L'onglet Photos (rapport de m\u00e9trologie photographi\u00e9, usures de plaquettes, constats\u2026) est d\u00e9sormais inclus au rapport d'essai g\u00e9n\u00e9r\u00e9, <b>avec leurs l\u00e9gendes</b> \u2014 suggestion de Matis : les destinataires du rapport ont enfin les preuves en m\u00eame temps que les chiffres. Les photos partent <b>telles qu'annot\u00e9es</b> : rognage et rep\u00e8res dessin\u00e9s dans l'outil sont appliqu\u00e9s \u00e0 l'image embarqu\u00e9e.\",\n    \"<b>Le rapport reste un seul fichier autonome.</b> Les images sont incorpor\u00e9es en data URL (pas de liens, pas de dossier \u00e0 joindre) \u2014 il s'ouvre chez n'importe qui, sans l'outil. Une photo indisponible au moment de la g\u00e9n\u00e9ration (dossier d\u00e9connect\u00e9, cloud hors ligne) est remplac\u00e9e par une case qui explique pourquoi, sans casser le rapport.\"\n  ]},\n  { version:\"4.23.0\", date:\"23/09/2026\", points:[\n    \"<b>Le volume annuel porte sa r\u00e9f\u00e9rence en toutes lettres.</b> Le chiffre a toujours \u00e9t\u00e9 rattach\u00e9 \u00e0 LA r\u00e9f\u00e9rence disque (et partag\u00e9 entre ses OP), mais rien ne le disait au moment de saisir \u2014 sur un poste o\u00f9 plusieurs lignes coexistent, le doute \u00ab ce champ s'applique \u00e0 qui ? \u00bb menait \u00e0 \u00e9crire sur la mauvaise. D\u00e9sormais le champ d'Options affiche <b>S'applique \u00e0 : EMAG 1 \u203a DV 356X26 RPI</b>, et la tuile \u00ab Production annuelle \u00bb de la composition est cliquable : elle ouvre Options pr\u00e9-remplie pour LA r\u00e9f\u00e9rence affich\u00e9e.\",\n    \"<b>Chaque changement de volume est trac\u00e9.</b> La r\u00e9f\u00e9rence garde l'historique des 10 derni\u00e8res valeurs (valeur, auteur, date), affich\u00e9 sous le champ \u2014 de quoi documenter les mont\u00e9es en cadence et voir imm\u00e9diatement qui a \u00e9crit quoi, quand, si un doute survient.\"\n  ]},\n  { version:\"4.22.0\", date:\"23/09/2026\", points:[\n    \"<b>Renommer un outil ou un logement se voit enfin partout.</b> Les noms affich\u00e9s \u00e9taient fig\u00e9s \u00e0 la cr\u00e9ation de chaque essai : le graphe des pr\u00e9l\u00e8vements, les puces d'essai, le rapport et le bandeau de reprise gardaient l'ancien nom m\u00eame apr\u00e8s renommage. D\u00e9sormais les noms sont relus dans le sc\u00e9nario au moment de l'affichage \u2014 les conditions de coupe, elles, restent fid\u00e8lement fig\u00e9es \u00e0 l'essai. Si un logement a \u00e9t\u00e9 retir\u00e9 du sc\u00e9nario, l'essai garde son nom d'\u00e9poque comme trace historique.\",\n    \"<b>Copier les outils de la production en un geste.</b> Sur un sc\u00e9nario qui n'est pas la r\u00e9f\u00e9rence, un bouton <b>\u29c9 Copier les outils de \u00ab \u2026 \u00bb</b> ouvre une s\u00e9lection : les outils coch\u00e9s arrivent avec r\u00e9f\u00e9rence, prix, ar\u00eates, charni\u00e8re et conditions de coupe, sous de nouveaux identifiants (les essais de la production ne bougent pas). Les noms restent ceux de la production \u2014 m\u00eames positions physiques, et chaque courbe reste titr\u00e9e par son essai, donc comparer deux essais reste lisible. Les plans joints ne sont pas copi\u00e9s.\"\n  ]},\n  { version:\"4.21.0\", date:\"23/09/2026\", points:[\n    \"<b>Le pense-b\u00eate devient un carnet de sujets chauds.</b> Les Suggestions gagnent deux types \u2014 <b>Essai \u00e0 planifier</b> et <b>Sujet technique</b> \u2014 un champ <b>d\u00e9clencheur</b> bien visible (\u00ab \u00e0 lancer d\u00e8s un arr\u00eat de ligne EMAG 1\u2026 \u00bb) pour anticiper les opportunit\u00e9s au lieu de les subir, et des statuts qui suivent la vie d'un sujet : Nouveau \u2192 En cours \u2192 Pr\u00eat \u00e0 lancer \u2192 Lanc\u00e9 \u2192 Clos. Toujours partag\u00e9 : ce que l'un note, l'autre le voit \u00e0 l'ouverture.\"\n  ]},\n  { version:\"4.20.0\", date:\"23/09/2026\", points:[\n    \"<b>Le taux de rebut annuel entre dans le bilan.</b> Un champ <b>Taux de rebut annuel (%)</b> arrive en t\u00eate du suivi rebut de chaque sc\u00e9nario \u2014 c'est le chiffre de l'ann\u00e9e, rentr\u00e9 sur le sc\u00e9nario de r\u00e9f\u00e9rence et affin\u00e9 pour chaque sc\u00e9nario d'essai. Rempli, il <b>fait foi</b> sur le taux calcul\u00e9 du journal d'\u00e9quipe (qui continue de tracer le d\u00e9tail par \u00e9quipe) et p\u00e8se dans le gain annuel d\u00e8s que le module \u00ab Co\u00fbt de rebut \u00bb est actif avec le prix du disque. Un indicateur dit en permanence quelle source est retenue.\"\n  ]},\n  { version:\"4.19.0\", date:\"23/09/2026\", points:[\n    \"<b>Le co\u00fbt annuel par logement, color\u00e9.</b> La vue d'ensemble affiche maintenant ce que chaque logement p\u00e8se <b>sur l'ann\u00e9e</b> (co\u00fbt pi\u00e8ce \u00d7 production annuelle) \u2014 c'est lui qui dit o\u00f9 travailler, pas le co\u00fbt pi\u00e8ce seul. Une couleur compare la part de chaque logement aux autres : <span style=\\\"color:hsl(145,62%,34%); font-weight:500;\\\">vert</span> = mineur, <span style=\\\"color:hsl(73,62%,34%); font-weight:500;\\\">ambre</span> = notable, <span style=\\\"color:hsl(0,62%,34%); font-weight:500;\\\">rouge</span> = majeur \u2014 les postes \u00e0 cibler en priorit\u00e9 se rep\u00e8rent d'un coup d'\u0153il. Le total annuel outillage rejoint le total pi\u00e8ce dans l'en-t\u00eate.\",\n    \"<b>R\u00e9ordonner les outils en glissant les tuiles.</b> La poign\u00e9e \u283f sur le bandeau de chaque fiche outil la d\u00e9place dans l'ordre \u2014 fiches, tuiles d'aper\u00e7u et pastilles num\u00e9rot\u00e9es suivent toutes, et l'ordre est conserv\u00e9 dans le suivi. Un clic simple ouvre toujours la fiche : seul un glissement d\u00e9place.\"\n  ]},\n  { version:\"4.18.0\", date:\"23/09/2026\", points:[\n    \"<b>L'outil s'installe comme une application (PWA).</b> Ouvrez l'adresse en ligne et utilisez \u00ab Installer l'application \u00bb du navigateur : l'outil se lance dans sa fen\u00eatre, avec l'ic\u00f4ne SPK, sans barre d'adresse \u2014 depuis le bureau, le menu D\u00e9marrer ou l'\u00e9cran d'accueil.\",\n    \"<b>Les mises \u00e0 jour se poussent toutes seules.</b> Le service worker sert la derni\u00e8re version d\u00e8s que le r\u00e9seau l'a vue : ouvrez l'app install\u00e9e en ligne, elle se met \u00e0 jour \u00e0 l'ouverture suivante \u2014 sans jamais d\u00e9sinstaller/r\u00e9installer. Hors ligne, la derni\u00e8re version connue s'ouvre comme avant (localStorage intact).\",\n    \"<b>Rien ne change pour la synchro.</b> Le service worker ne touche que le chargement de l'outil lui-m\u00eame : les \u00e9changes cloud (suivi, photos, connexion) passent comme avant, et l'usage hors ligne reste la r\u00e8gle.\"\n  ]},\n  { version:\"4.17.0\", date:\"23/09/2026\", points:[\n    \"<b>On ne se reconnecte plus \u00e0 chaque ouverture.</b> Le lien cloud survivait mal aux ouvertures hors r\u00e9seau : au d\u00e9marrage, une simple panne de connexion (proxy d'usine, Wi-Fi pas encore mont\u00e9) d\u00e9truisait la session alors que le jeton de reconnexion \u00e9tait encore valable \u2014 d'o\u00f9 un relogin syst\u00e9matique. D\u00e9sormais la session ne meurt que sur un refus formel du serveur ; hors ligne, l'outil affiche \u00ab session conserv\u00e9e \u00bb et retente au prochain contact, comme le reste de l'outil.\",\n    \"<b>Le premier clic sur \u00ab Joindre le plan de l'outil \u00bb marche.</b> Saisir un champ puis cliquer directement sur le bouton d'upload ne faisait rien : la sauvegarde reconstruisait l'\u00e9cran au moment exact du clic, qui s'\u00e9vanouissait. D\u00e9sormais la reconstruction attend la fin du clic \u2014 le s\u00e9lecteur de fichier s'ouvre du premier coup, partout o\u00f9 un bouton suit une saisie.\"\n  ]},\n  { version:\"4.16.0\", date:\"23/09/2026\", points:[\n    \"<b>Les photos voyagent avec le suivi.</b> Jusqu'ici une photo d'essai restait dans le dossier local de celui qui l'avait prise : l'autre poste n'en voyait rien. Sans dossier connect\u00e9, les photos partent maintenant dans le <b>cloud priv\u00e9</b> (comptes de l'\u00e9quipe uniquement) et l'autre poste les t\u00e9l\u00e9charge automatiquement \u2014 miniatures, agrandissement, annotation. Le dossier local reste prioritaire quand il est connect\u00e9 ; les deux modes coexistent photo par photo.\",\n    \"<b>Le bouton devient \u00ab Ajouter des photos (cloud) \u00bb</b> quand vous \u00eates connect\u00e9 au cloud sans dossier local : m\u00eame geste, la photo est redimensionn\u00e9e puis envoy\u00e9e, et le suivi la r\u00e9f\u00e9rence par son chemin cloud. Une photo supprim\u00e9e l'est aussi du cloud.\",\n    \"<b>Hors ligne, rien ne casse.</b> Une photo d\u00e9j\u00e0 vue est mise en cache locale : elle se r\u00e9affiche sans r\u00e9seau. Une photo jamais t\u00e9l\u00e9charg\u00e9e s'affiche estomp\u00e9e avec la raison, et tout le reste de l'outil continue de marcher comme avant.\"\n  ]},\n  { version:\"4.15.0\", date:\"23/09/2026\", points:[\n    \"<b>Comparer deux essais.</b> Un bouton <b>Comparer\u2026</b> sur chaque essai : conditions c\u00f4te \u00e0 c\u00f4te (plaquettes fig\u00e9es, Vc/f, \u00e9quipe, bruts), statuts, taux hors tol\u00e9rance, et les <b>courbes superpos\u00e9es</b> avec leur tol\u00e9rance. Deux essais du m\u00eame sc\u00e9nario : c'est la <b>r\u00e9p\u00e9tabilit\u00e9</b> qu'on lit \u2014 le fond du protocole 5\u00d7. Deux sc\u00e9narios : quelle d\u00e9rive tient le mieux.\",\n    \"<b>Les tendances en % de tol\u00e9rance.</b> Sur chaque graphique de tendance, un bouton <b>Voir en % de tol.</b> exprime la mesure en pourcentage de la tol\u00e9rance consomm\u00e9e (100 % = la limite, 0 % = la borne mini si plage). Pratique pour lire d'un coup d'\u0153il un crit\u00e8re dont on ne conna\u00eet pas les valeurs par c\u0153ur \u2014 un bouton ram\u00e8ne les valeurs r\u00e9elles.\"\n  ]},\n  { version:\"4.14.0\", date:\"23/09/2026\", points:[\n    \"<b>Reprendre la saisie en un clic.</b> Le dernier essai <i>en cours</i> touch\u00e9 s'affiche en bandeau sous la navigation : son titre, son sc\u00e9nario, le dernier pr\u00e9l\u00e8vement saisi \u2014 et le <b>Mode atelier</b> directement dedans. Fini de rouvrir le sc\u00e9nario, d\u00e9plier l'essai, chercher le bouton : devant la machine, une mesure de plus se tape tout de suite. Le \u2715 masque la proposition ; elle revient toute seule pour un essai plus r\u00e9cent.\",\n    \"<b>Rechercher partout (Ctrl+K).</b> Tapez un nom de ligne, de r\u00e9f\u00e9rence, d'OP, de sc\u00e9nario, d'essai ou de projet : la palette vous y emm\u00e8ne \u2014 casse et accents ignor\u00e9s, navigation au clavier (\u2191\u2193 puis Entr\u00e9e). Le bouton <b>Rechercher</b> du menu \u2022\u2022\u2022 fait la m\u00eame chose.\",\n    \"<b>Le protocole 5\u00d7 est devenu visible.</b> La r\u00e8gle act\u00e9e \u2014 un essai concluant r\u00e9p\u00e9t\u00e9 5\u00d7, viable \u00e9conomiquement, passe en production \u2014 s'affiche maintenant sous la validation du sc\u00e9nario, en info-bulle sur les tuiles, et dans le rapport de validation (\u00ab acquis : N/5 \u00bb). Plus besoin de s'en souvenir : l'outil le porte.\",\n    \"<b>Le mode atelier dit quand d\u00e9cider.</b> \u00c0 la charni\u00e8re vis\u00e9e, un bandeau ambre propose de resserrer le pas de mesure ou de trancher (prolonger / arr\u00eater). Au-del\u00e0 de la charni\u00e8re, il passe au vert : la dur\u00e9e de vie d\u00e9passe l'objectif \u2014 \u00e0 exploiter tant que la cote tient.\"\n  ]},\n  { version:\"4.13.0\", date:\"23/09/2026\", points:[\n    \"<b>La navigation tient sur une ligne.</b> Les trois rang\u00e9es de pastilles (Ligne / R\u00e9f\u00e9rence / OP), toutes identiques, laissent place \u00e0 un fil unique \u2014 <i>EMAG 1 \u203a R\u00e9f\u00e9rence \u203a OP10</i>. Cliquez un maillon pour ouvrir son propre menu : changer, cr\u00e9er, renommer, supprimer. Le contenu commence plus haut \u00e0 l'\u00e9cran, et la hi\u00e9rarchie se lit enfin d'un coup d'\u0153il.\",\n    \"<b>Le menu \u2022\u2022\u2022 se lit en groupes.</b> Les actions sont rang\u00e9es par nature \u2014 <b>Consulter</b> (synth\u00e8se, tableau de bord, CSV), <b>Documenter</b> (rapport, PDF, nouveaut\u00e9s), <b>G\u00e9rer</b> (options, parcours, suggestions, dossier, historique) \u2014 et la zone rouge (R\u00e9initialiser / Restaurer) reste bien s\u00e9par\u00e9e en bas. Aucune action n'a disparu.\",\n    \"<b>D\u00e9tails :</b> le titre (nom de la r\u00e9f\u00e9rence) tronque proprement avec une info-bulle au lieu de sortir du cadre noir sur les noms longs, et les badges de statut, de validation et de projet ont d\u00e9sormais tous la m\u00eame forme \u2014 seule la couleur change.\"\n  ]},\n  { version:\"4.12.0\", date:\"22/09/2026\", points:[\n    \"<b>Marposs : un essai sur plusieurs jours, une extraction par jour.</b> Suggestion de Matis : quand un essai s'\u00e9tend sur deux journ\u00e9es (50 pi\u00e8ces le jour 1, 100 le jour 2), le bouton \u00ab + Ajouter une extraction \u00bb cr\u00e9e la journ\u00e9e suivante dans le m\u00eame essai \u2014 son jour, ses heures, son collage, ses moyennes et <b>son propre graphe</b>. Chaque extraction se supprime ind\u00e9pendamment, et le rapport de l'essai pr\u00e9sente une sous-section par journ\u00e9e. L'extraction Marposs existante migre automatiquement.\"\n  ]},\n  { version:\"4.11.1\", date:\"22/09/2026\", points:[\n    \"<b>La Tendance trace tout crit\u00e8re \u00e9valu\u00e9.</b> Le graphique ne se limitait au battement : d\u00e9sormais chaque crit\u00e8re suivi \u2014 Ra, VE, crit\u00e8re libre \u2014 a son propre graphe d'\u00e9volution en fonction du n\u00b0 de pi\u00e8ce, avec sa ligne de tol\u00e9rance (et sa borne mini si activ\u00e9e). Quand un crit\u00e8re porte deux mesures (Ra Inter / Ra Exter), deux courbes de couleurs distinctes tracent leurs \u00e9volutions c\u00f4te \u00e0 c\u00f4te.\"\n  ]},\n  { version:\"4.11.0\", date:\"22/09/2026\", points:[\n    \"<b>On ne suit que ce qu'on veut suivre.</b> Dans chaque essai, les puces \u00ab Conditions de l'essai \u00bb portent d\u00e9sormais une croix : <b>\u2715 = ne plus suivre ce logement dans cet essai</b> (il reste dans le sc\u00e9nario, re-suivable \u00e0 tout moment via \u00ab + suivre un logement \u00bb). Fini de remplir des colonnes pour les outils qui ont d\u00e9j\u00e0 atteint leur charni\u00e8re \u2014 la progression, le tableau, l'atelier et les rapports ne montrent plus que les logements coch\u00e9s.\"\n  ]},\n  { version:\"4.10.1\", date:\"22/09/2026\", points:[\n    \"<b>Plus de logements pr\u00e9-nomm\u00e9s.</b> Un nouveau sc\u00e9nario arrive avec un outil vide : c'est vous qui cr\u00e9ez et nommez vos logements (Filetage, Chanfrein\u2026). Les noms \u00ab Bol \u00bb et \u00ab Piste \u00bb n'apparaissent plus que s'ils ont \u00e9t\u00e9 saisis \u2014 ils ne d\u00e9bourent plus automatiquement dans le bandeau r\u00e9capitulatif.\"\n  ]},\n  { version:\"4.10.0\", date:\"22/09/2026\", points:[\n    \"<b>Le travail \u00e0 deux fusionne tout seul.</b> Quand vous avez saisi tous les deux pendant que l'autre d\u00e9posait, l'outil <b>fusionne automatiquement</b> essai par essai \u2014 le plus r\u00e9cent gagne pour un m\u00eame essai, les essais de chacun s'ajoutent, les r\u00e9glages du sc\u00e9nario restent \u00e0 la version locale. Fini le choix \u00ab prendre le cloud ou \u00e9craser \u00bb : le rapport de fusion d\u00e9taille ce qui a \u00e9t\u00e9 ajout\u00e9, mis \u00e0 jour, conserv\u00e9, et liste les rares conflits \u00e0 v\u00e9rifier.\",\n    \"<b>Un message \u00e0 l'ouverture.</b> Si Matis a synchronis\u00e9 pendant votre absence, l'outil vous le dit en ouvrant : qui a d\u00e9pos\u00e9, quand, et le d\u00e9tail (\u00ab 3 essais ajout\u00e9s, 1 mis \u00e0 jour \u00bb). Plus personne ne d\u00e9couvre un changement en tombant dessus.\",\n    \"<b>Tra\u00e7abilit\u00e9.</b> Chaque essai porte maintenant <i>qui</i> l'a modifi\u00e9 en plus de <i>quand</i> \u2014 c'est ce qui alimente les messages et l'arbitrage des fusions.\"\n  ]},\n  { version:\"4.9.1\", date:\"22/09/2026\", points:[\n    \"<b>Heure de d\u00e9but d'essai.</b> L'essai avait une heure de fin mais pas de d\u00e9but : le champ est l\u00e0, \u00e0 c\u00f4t\u00e9 de \u00ab Fin d'essai \u00bb. Il appara\u00eet dans le rapport (\u00ab 22/09/2026 \u00b7 08:00 \u2192 09:30 \u00bb) et dans l'export CSV. Le choix Matin / Apr\u00e8s-midi / Nuit reste ce qu'il a toujours \u00e9t\u00e9 : l'<b>\u00e9quipe</b> (poste), utilis\u00e9e par la comparaison de dispersion entre \u00e9quipes.\",\n    \"<b>Fen\u00eatre Marposs pr\u00e9-remplie.</b> D\u00e8s que l'heure de d\u00e9but et l'heure de fin de l'essai sont saisies, la fen\u00eatre horaire du suivi Marposs se remplit avec \u2014 modifiable ensuite s\u00e9par\u00e9ment, la machine contr\u00f4lant toute la journ\u00e9e.\"\n  ]},\n  { version:\"4.9.0\", date:\"22/09/2026\", points:[\n    \"<b>Crit\u00e8res d'essai repens\u00e9s.</b> Le battement se d\u00e9coche (un essai peut ne porter que sur l'\u00e9tat de surface), ses c\u00f4t\u00e9s Droite/Gauche se choisissent par sc\u00e9nario (essai \u00e0 un seul c\u00f4t\u00e9), et les crit\u00e8res suppl\u00e9mentaires \u2014 <b>Ra</b>, <b>VE</b>, ou tout crit\u00e8re libre \u2014 se g\u00e8rent en liste : borne maxi, mini optionnelle (plage min\u2013max), axes Inter/Exter ou Droite/Gauche. Ancien \u00ab 2\u1d49 crit\u00e8re \u00bb migr\u00e9 automatiquement, rien \u00e0 refaire.\",\n    \"<b>La tol\u00e9rance s'\u00e9dite dans le bloc Essais.</b> Plus de d\u00e9tour par Options ni de case \u00e0 cocher : le champ est l\u00e0, toujours visible, et l'\u00e9diter le rend sp\u00e9cifique au sc\u00e9nario. La valeur OP reste affich\u00e9e comme rep\u00e8re. Specs usine (Battement \u2264 0,04 \u00b7 VE \u2264 0,01 apr\u00e8s OP40) affich\u00e9es en permanence sous les crit\u00e8res.\",\n    \"<b>Specs usine dans Options, verrouill\u00e9es.</b> Les valeurs de r\u00e9f\u00e9rence pour tous les disques finis se consultent dans Options ; les modifier exige une double validation explicite \u2014 elles ne changent normalement jamais. Reprendues dans les rapports d'essai.\",\n    \"<b>Le graphe Marposs peut partir dans le rapport.</b> Dans le suivi Marposs d'un essai, une case \u00ab Inclure ce graphe dans le rapport de l'essai \u00bb ajoute au rapport g\u00e9n\u00e9r\u00e9 la courbe du jour avec la plage horaire de l'essai surlign\u00e9e, les moyennes et la fen\u00eatre d\u00e9but\u2013fin. D\u00e9sactiv\u00e9 par d\u00e9faut pour ne pas surcharger.\",\n    \"<b>Correction \u2014 l'ouverture des pi\u00e8ces jointes.</b> Les PDF int\u00e9gr\u00e9s au suivi (plans, fiches outil) ne s'ouvraient plus : le navigateur bloque l'ouverture des liens data:. Corrig\u00e9 \u2014 les documents passent par un fichier temporaire, les images par l'agrandissement plein \u00e9cran.\"\n  ]},\n  { version:\"4.8.0\", date:\"22/09/2026\", points:[\n    \"<b>Le suivi se synchronise tout seul.</b> Fini les exports JSON envoy\u00e9s par e-mail : connectez-vous dans <b>Options \u2192 Cloud</b> avec votre email, et chaque saisie repart seule quelques secondes apr\u00e8s \u2014 les modifications de l'autre arrivent \u00e0 l'ouverture de l'outil ou en revenant sur l'onglet. Une pastille \u2601 en pied de page dit o\u00f9 on en est.\",\n    \"<b>Vos donn\u00e9es ne se m\u00e9langent jamais en silence.</b> Au premier branchement, l'outil montre ce que contient le cloud et ce que contient le poste (nombre d'essais, date, auteur) et demande qui fait autorit\u00e9 \u2014 avec un export de secours t\u00e9l\u00e9charg\u00e9 avant tout remplacement. Le d\u00e9p\u00f4t initial dans un cloud vide reste un geste volontaire.\",\n    \"<b>Chaque poste garde sa copie locale.</b> Sans r\u00e9seau (proxy d'usine, coupure), l'outil marche comme avant ; la synchro repart d\u00e8s que la connexion revient. Le cloud garde aussi les 20 derni\u00e8res versions du suivi \u2014 un retour arri\u00e8re est toujours possible.\"\n  ]},\n  { version:\"4.7.0\", date:\"09/09/2026\", points:[\n    \"<b>Options, r\u00e9organis\u00e9.</b> Le panneau est maintenant d\u00e9coup\u00e9 par nature \u2014 <b>Mesure &amp; essais</b>, <b>Co\u00fbts</b>, <b>\u00c9quipe</b> \u2014 et chaque r\u00e9glage porte son badge de port\u00e9e (<b>OP</b>, <b>R\u00e9f\u00e9rence</b>, <b>Ligne</b>, <b>Tous</b>) : on voit enfin pourquoi le volume annuel se r\u00e8gle ailleurs que la tol\u00e9rance.\",\n    \"<b>Le co\u00fbt horaire se saisit dans Options.</b> Fini le renvoi vers l'ic\u00f4ne \u2699 de l'onglet de ligne pour finir une configuration commenc\u00e9e dans Options : le champ est l\u00e0, dans la section Co\u00fbts. M\u00eame donn\u00e9e, deux portes d'entr\u00e9e.\",\n    \"<b>L'\u00e9tat du co\u00fbt machine, calcul\u00e9 \u2014 plus devin\u00e9.</b> L'ancienne note des \u00ab quatre choses \u00e0 faire \u00bb \u00e9tait static et trop stricte : un statut vert ou ambre dit maintenant exactement ce qui manque (temps de cycle de r\u00e9f\u00e9rence, co\u00fbt horaire) et ce que \u00e7a change. Sans eux, aucun \u00e9cart de cycle ne p\u00e8se dans le gain annuel \u2014 c'est \u00e9crit, depuis le code.\"\n  ]},\n  { version:\"4.6.0\", date:\"09/09/2026\", points:[\n    \"<b>Des confirmations dans le style de l'outil.</b> Les petites fen\u00eatres syst\u00e8me grises (alertes, confirmations, saisies) ont disparu : chaque question s'affiche maintenant dans une fen\u00eatre de l'outil \u2014 m\u00eames textes, m\u00eames garde-fous, mais lisible, mise en forme, et compatible avec le mode nuit. La r\u00e9initialisation demande toujours de taper \u00ab REINITIALISER \u00bb.\",\n    \"<b>D\u00e9marrer un suivi, dans le bon ordre.</b> La r\u00e8gle \u00ab le sc\u00e9nario en production d'abord, les projets ensuite \u00bb est maintenant dans l'outil : un parcours en trois \u00e9tapes coch\u00e9es (menu <b>\u2022\u2022\u2022</b> \u2192 <b>D\u00e9marrer un suivi</b>) et un rappel sur un OP vierge. Il dispara\u00eet tout seul d\u00e8s que la premi\u00e8re \u00e9tape est faite.\",\n    \"<b>Navigation au clavier.</b> La touche Tab reste dans la fen\u00eatre ouverte (plus de focus perdu derri\u00e8re le voile), Escape ferme comme avant, et \u00e0 l'ouverture le focus entre dans la fen\u00eatre \u2014 utile au lecteur d'\u00e9cran comme au clavier rapide.\",\n    \"<b>Graphique de tendance.</b> Le point le plus avanc\u00e9 ne colle plus au bord droit du graphique \u2014 une marge le s\u00e9pare d\u00e9sormais du cadre.\"\n  ]},\n  { version:\"4.5.0\", date:\"09/09/2026\", points:[\n    \"<b>Protection du gain annuel.</b> Deux projets peuvent d\u00e9crire le m\u00eame changement physique sur la m\u00eame machine : si deux sc\u00e9narios du m\u00eame nom passent \u00ab en s\u00e9rie \u00bb dans des projets diff\u00e9rents, l'outil vous pr\u00e9vient maintenant au moment du passage en s\u00e9rie, et un bandeau dans le tableau de bord (vue tous projets) le signale en continu \u2014 sans quoi le m\u00eame gain \u00e9tait compt\u00e9 deux fois.\",\n    \"<b>Le poids du suivi, visible en permanence.</b> Une pastille en pied de page affiche en continu la place que prend votre suivi dans la m\u00e9moire du navigateur (~5 Mo) : ambre puis rouge \u00e0 l'approche de la limite, avec le d\u00e9tail et les conseils d'all\u00e8gement au clic. Plus besoin d'attendre l'alerte pour agir.\",\n    \"<b>Cr\u00e9er un projet, plus confortable.</b> Fini la petite fen\u00eatre syst\u00e8me : un panneau avec champ d\u00e9di\u00e9, qui annonce combien de sc\u00e9narios seront rattach\u00e9s automatiquement \u2014 et le panneau du projet vous le rappelle apr\u00e8s cr\u00e9ation.\"\n  ]},\n  { version:\"4.4.0\", date:\"08/09/2026\", points:[\n    \"<b>Chaque OP a un seul \u00ab sc\u00e9nario en production \u00bb (\u2605), qui s'affiche toujours.</b> Jusqu'ici, rien n'emp\u00eachait le badge \u2605 (sc\u00e9nario de r\u00e9f\u00e9rence) et le statut \u00ab En s\u00e9rie \u00bb de diverger \u2014 deux notions qui, dans les faits, d\u00e9signent la m\u00eame chose : ce qui tourne r\u00e9ellement en s\u00e9rie sur la machine. Elles sont maintenant unifi\u00e9es : le sc\u00e9nario \u2605 est verrouill\u00e9 sur \u00ab En s\u00e9rie \u00bb, impossible de lui donner un autre statut sans d'abord d\u00e9signer un autre sc\u00e9nario comme r\u00e9f\u00e9rence.\",\n    \"<b>D\u00e9signer un nouveau sc\u00e9nario en production r\u00e9trograde l'ancien</b>, avec une confirmation qui l'annonce avant de le faire : l'ancien passe en \u00ab Valid\u00e9 \u00bb (pas \u00ab Abandonn\u00e9 \u00bb \u2014 il n'a rien rat\u00e9, il a juste \u00e9t\u00e9 remplac\u00e9).\",\n    \"<b>Le sc\u00e9nario en production reste visible m\u00eame filtr\u00e9 par un projet</b> qui ne le concerne pas \u2014 c'est la r\u00e9f\u00e9rence de l'OP, elle ne doit jamais dispara\u00eetre du bandeau de travail. Cette exception ne touche que l'affichage : elle ne le fait pas compter dans les statistiques d'un projet o\u00f9 il n'est pas explicitement rattach\u00e9.\",\n    \"Pense-b\u00eate pour la suite : la bonne fa\u00e7on de d\u00e9marrer un OP est de cr\u00e9er d'abord sa ligne, sa r\u00e9f\u00e9rence et son sc\u00e9nario en production, puis de cr\u00e9er des projets par-dessus pour organiser le travail d'optimisation \u2014 pas l'inverse.\"\n  ]},\n  { version:\"4.3.0\", date:\"08/09/2026\", points:[\n    \"<b>Le filtre de projet scope r\u00e9ellement le travail, pas seulement l'affichage.</b> Jusqu'ici, activer un projet ne faisait que du cosm\u00e9tique \u2014 le bandeau de sc\u00e9narios sur lequel vous travailliez au quotidien continuait \u00e0 tout montrer, m\u00e9lang\u00e9. D\u00e9sormais, d\u00e8s qu'au moins un sc\u00e9nario de l'OP ouvert appartient \u00e0 un projet, activer ce projet ne montre plus que ses sc\u00e9narios : les autres restent dans l'outil, simplement masqu\u00e9s tant que le filtre est actif. Un OP qui n'a encore aucun sc\u00e9nario rattach\u00e9 \u00e0 un projet continue de fonctionner exactement comme avant, sans rien filtrer.\",\n    \"<b>Correction d'un vrai d\u00e9faut</b> : un projet sans aucun sc\u00e9nario rattach\u00e9 s'affichait sur toutes les lignes, y compris celles qui n'avaient rien \u00e0 voir avec lui. Il n'appara\u00eet maintenant que sur la ligne o\u00f9 il a \u00e9t\u00e9 cr\u00e9\u00e9, tant qu'il n'a pas d'\u00e9tiquette ailleurs.\",\n    \"<b>Cr\u00e9er un projet rattache d\u00e9sormais tous les sc\u00e9narios de l'OP ouvert</b>, pas seulement celui affich\u00e9 au moment du clic \u2014 \u00ab cr\u00e9er un projet ici \u00bb veut dire \u00ab cette ligne, cet OP, maintenant \u00bb. Affinez ensuite au cas par cas avec les \u00e9tiquettes des cartes de sc\u00e9nario.\",\n    \"La section \u00ab Comment \u00e7a marche \u00bb de l'outil (ic\u00f4ne \u24d8) explique maintenant les projets \u2014 elle avait \u00e9t\u00e9 oubli\u00e9e lors de leur arriv\u00e9e.\"\n  ]},\n  { version:\"4.2.0\", date:\"08/09/2026\", points:[\n    \"<b>Retours d'usage sur les projets, trait\u00e9s d'un coup.</b> Le bouton \u00ab Modifier \u00bb d'un projet est maintenant \u00e9crit en toutes lettres sur la carte (avant : une petite ic\u00f4ne \u2699 qu'on ne voyait pas) \u2014 pareil pour cr\u00e9er un projet, qui passe en bouton bleu bien visible. Le bouton qui enregistre vos modifications s'appelle maintenant \u00ab Enregistrer \u00bb \u2014 il faisait d\u00e9j\u00e0 \u00e7a, mais s'appelait \u00ab Fermer \u00bb, ce qui n'aidait pas \u00e0 croire que c'\u00e9tait sauvegard\u00e9.\",\n    \"<b>Description du projet en zone de texte</b> \u2014 largement assez de place pour \u00e9crire l'objectif et les moyens mis en \u0153uvre, plus une seule ligne.\",\n    \"<b>Un pilote par projet, avec sa couleur.</b> Une liste de responsables se g\u00e8re dans Options (nom + couleur), et se rattache \u00e0 chaque projet depuis son panneau \u2014 avec une cr\u00e9ation \u00e0 la vol\u00e9e directement dans le menu d\u00e9roulant, pas besoin d'aller dans Options la premi\u00e8re fois. La couleur du pilote habille la bordure de ses cartes de projet ; supprimer un responsable ne supprime jamais les projets qu'il pilotait, ils repassent juste \u00e0 \u00ab Aucun \u00bb.\",\n    \"<b>Chaque projet a sa propre couleur d'identit\u00e9</b>, distincte de celle du pilote \u2014 reprise sur ses \u00e9tiquettes de sc\u00e9nario. Avec plusieurs projets sur un m\u00eame sc\u00e9nario, chaque \u00e9tiquette reste reconnaissable sans avoir \u00e0 lire le texte.\",\n    \"Quand un OP porte des sc\u00e9narios de plusieurs projets \u00e0 la fois, le tableau de bord l'indique maintenant directement, sans avoir \u00e0 ouvrir chaque sc\u00e9nario un par un pour le d\u00e9couvrir.\",\n    \"Pour m\u00e9moire, d\u00e9j\u00e0 possible sans rien changer : un sc\u00e9nario peut appartenir \u00e0 plusieurs projets, et un projet peut couvrir plusieurs lignes \u2014 le mod\u00e8le par \u00e9tiquettes (v4.1) le permettait nativement.\"\n  ]},\n  { version:\"4.1.1\", date:\"08/09/2026\", points:[\n    \"<b>Correctif discret mais important.</b> Dans un cas rare (deux cr\u00e9ations dans la m\u00eame fraction de seconde \u2014 par exemple un double-clic), deux sc\u00e9narios pouvaient recevoir le m\u00eame identifiant interne et l'un masquait l'autre. C'est corrig\u00e9 : chaque sc\u00e9nario, ligne, r\u00e9f\u00e9rence ou OP cr\u00e9\u00e9 d\u00e9sormais porte un identifiant unique, y compris par double-clic ou en s\u00e9rie.\",\n    \"Les cartes de projet en haut de l'\u00e9cran se limitent maintenant \u00e0 ceux qui concernent la ligne ouverte \u2014 jusqu'ici, tous les projets s'affichaient partout, m\u00eame ceux qui n'avaient rien \u00e0 voir avec la ligne regard\u00e9e. Un projet qui touche plusieurs lignes (ou tout juste cr\u00e9\u00e9, sans sc\u00e9nario encore rattach\u00e9) reste visible partout, et le lien \u00ab Voir tous les projets \u00bb permet de repasser en vue compl\u00e8te \u00e0 tout moment.\"\n  ]},\n  { version:\"4.1.0\", date:\"08/09/2026\", points:[\n    \"<b>Les projets reviennent, sous une forme plus solide.</b> La premi\u00e8re version (mise en attente il y a quelques jours) faisait du projet le propri\u00e9taire de la ligne de production \u2014 une machine ne pouvait appartenir qu'\u00e0 un seul projet \u00e0 la fois. Apr\u00e8s r\u00e9flexion, un projet est maintenant une liste de sc\u00e9narios qu'on choisit d'y rattacher, un peu comme des \u00e9tiquettes : la ligne, la r\u00e9f\u00e9rence et l'OP restent ce qu'ils ont toujours \u00e9t\u00e9, uniques, et un m\u00eame sc\u00e9nario peut appartenir \u00e0 plusieurs projets si le besoin se pr\u00e9sente.\",\n    \"Concr\u00e8tement : \u00ab Co\u00fbt &amp; qualit\u00e9 EMAG 1 \u00bb et \u00ab Essais Step 3 \u00bb sont deux cartes en haut de l'\u00e9cran. Ouvrir un projet ne cache rien de l'atelier \u2014 vous continuez \u00e0 voir toutes les lignes \u2014 mais un nouveau sc\u00e9nario cr\u00e9\u00e9 pendant qu'un projet est ouvert y est <b>automatiquement rattach\u00e9</b>, exactement ce que demandait \u00ab s\u00e9lectionner un projet pour renseigner les donn\u00e9es \u00bb.\",\n    \"Chaque sc\u00e9nario affiche de petites \u00e9tiquettes cliquables pour l'ajouter ou le retirer d'un projet \u00e0 tout moment \u2014 pas besoin de tout pr\u00e9voir \u00e0 la cr\u00e9ation.\",\n    \"Chaque carte de projet garde sa probl\u00e9matique, son pilote, son statut et son \u00e9ch\u00e9ance vis\u00e9e (toujours sans notion de \u00ab retard \u00bb \u2014 un essai qui glisse n'est pas une faute).\",\n    \"Le tableau de bord peut se filtrer sur un projet pr\u00e9cis, mais reste r\u00e9gl\u00e9 sur \u00ab tous les projets \u00bb par d\u00e9faut.\",\n    \"<b>Bonne nouvelle pour l'\u00e9change de fichiers</b> : cette fois, un fichier export\u00e9 par cette version reste lisible par une version plus ancienne de l'outil \u2014 elle affichera toutes vos lignes et mesures normalement, seul le regroupement en projets lui restera invisible.\"\n  ]},\n  { version:\"3.19.2\", date:\"08/09/2026\", points:[\n    \"<b>Les projets sont mis en attente.</b> La version 4.0, qui ajoutait un niveau \u00ab Projet \u00bb au-dessus des lignes de production, a \u00e9t\u00e9 retir\u00e9e le temps de valider son organisation \u2014 notamment la question de savoir si une ligne doit appartenir \u00e0 un seul projet ou pouvoir \u00eatre suivie dans plusieurs. Mieux vaut trancher cette question avant que des campagnes enti\u00e8res soient rang\u00e9es d'une fa\u00e7on qu'il faudrait d\u00e9faire ensuite.\",\n    \"<b>Vos donn\u00e9es sont intactes.</b> Si vous aviez ouvert la 4.0, tout ce que vous aviez saisi est repris automatiquement, y compris les mesures enregistr\u00e9es entre-temps. Seul le regroupement par projet n'appara\u00eet plus ; il reviendra quand la fonction sera valid\u00e9e.\",\n    \"Rien d'autre ne change par rapport \u00e0 la version 3.19.1 que vous utilisiez avant.\"\n  ]},\n  { version:\"3.19.1\", date:\"05/09/2026\", points:[\n    \"Dans la vue d'ensemble, un co\u00fbt qui ne peut pas se calculer dit maintenant <b>pourquoi</b> : \u00ab Co\u00fbt non calculable : nombre d'ar\u00eates \u00e0 0 \u00bb. Auparavant la tuile affichait \u00ab Co\u00fbt \u2014 \u00bb alors que la cause \u00e9tait lisible juste au-dessus, sans que rien ne fasse le lien. \u00c0 distinguer de \u00ab Manque : \u2026 \u00bb, qui signale une case pas encore remplie \u2014 ce n'est pas le m\u00eame probl\u00e8me ni le m\u00eame geste.\"\n  ]},\n  { version:\"3.19.0\", date:\"05/09/2026\", points:[\n    \"<b>La sauvegarde ne peut plus \u00e9chouer en silence.</b> Jusqu'ici, si la m\u00e9moire que le navigateur accorde \u00e0 l'outil \u00e9tait pleine, l'enregistrement \u00e9chouait et le seul signal \u00e9tait une petite pastille rouge avec une info-bulle. Devant une machine, personne ne survole une pastille : on pouvait saisir des relev\u00e9s pendant une heure sans que rien ne soit \u00e9crit, et tout perdre en fermant l'onglet. C'\u00e9tait le risque le plus s\u00e9rieux de l'outil.\",\n    \"D\u00e9sormais, en trois temps. <b>1)</b> L'outil se rattrape tout seul : il purge ses points de reprise automatiques \u2014 qui p\u00e8sent plusieurs fois le suivi lui-m\u00eame \u2014 et r\u00e9essaie. Dans la plupart des cas vous ne verrez rien, et c'est voulu : un point de reprise vaut moins que vos mesures en cours. <b>2)</b> Si \u00e7a ne suffit pas, une fen\u00eatre s'ouvre et un <b>bandeau rouge reste affich\u00e9 en haut de l'\u00e9cran</b>, avec un bouton \u00ab Exporter le suivi maintenant \u00bb directement dedans. <b>3)</b> Bien avant le mur, d\u00e8s 3,5 Mo, un avertissement vous pr\u00e9vient et <b>nomme ce qui p\u00e8se</b>, pi\u00e8ce jointe par pi\u00e8ce jointe.\",\n    \"<b>La fiche outil de l'OP suit la m\u00eame r\u00e8gle que les plans d'outil</b> : enregistr\u00e9e dans le dossier local s'il est connect\u00e9, sinon int\u00e9gr\u00e9e au fichier de suivi mais seulement sous 500 ko. Elle acceptait jusqu'ici 6 Mo \u00e0 elle seule \u2014 de quoi saturer la m\u00e9moire et bloquer l'enregistrement des mesures. Les fiches d\u00e9j\u00e0 jointes restent lisibles et ne bougent pas.\",\n    \"Une pi\u00e8ce jointe stock\u00e9e dans le dossier local ne p\u00e8se rien dans le fichier de suivi : c'est le mode \u00e0 privil\u00e9gier d\u00e8s que le dossier est connect\u00e9.\"\n  ]},\n  { version:\"3.18.0\", date:\"05/09/2026\", points:[\n    \"<b>Vue d'ensemble de la composition</b>, en haut du sc\u00e9nario et toujours visible. Une tuile par logement : quelle plaquette, quelle charni\u00e8re (avec la dur\u00e9e de vie r\u00e9ellement observ\u00e9e en dessous), quel prix, combien au total \u2014 en gros caract\u00e8res, lisibles d'un coup d'\u0153il. Avant, cette information tenait dans une ligne de r\u00e9sum\u00e9 en 11 px gris clair qui essayait d'\u00eatre \u00e0 la fois l'\u00e9tiquette d'un volet et un tableau de bord.\",\n    \"Ce qui manque est signal\u00e9 <b>l\u00e0</b> plut\u00f4t que d\u00e9couvert plus tard dans un calcul qui ne tombe pas : \u00ab Manque : r\u00e9f\u00e9rence, prix \u00bb sous la tuile concern\u00e9e.\",\n    \"<b>Les fiches outil se replient.</b> Elles sont ferm\u00e9es par d\u00e9faut et se r\u00e9sument \u00e0 une ligne lisible (n\u00b0 d'outil, type, logements, co\u00fbt). On ouvre celle qu'on veut modifier, les autres restent rang\u00e9es \u2014 plus d'\u00e9cran couvert d'informations. L'outil se souvient de ce que vous avez laiss\u00e9 ouvert.\",\n    \"<b>Un plan peut \u00eatre joint \u00e0 chaque outil</b> (PDF ou image du montage, de la trajectoire). Si le dossier local est connect\u00e9, le plan y est enregistr\u00e9 comme un fichier \u2014 c'est le mode recommand\u00e9 : un plan p\u00e8se vite 1 \u00e0 2 Mo alors que le suivi complet ne dispose que d'environ 5 Mo dans le navigateur. Sans dossier connect\u00e9, les plans de moins de 500 ko sont int\u00e9gr\u00e9s au fichier de suivi ; au-del\u00e0, l'outil explique pourquoi il refuse et comment faire.\",\n    \"\u00c0 ne pas confondre avec la <b>fiche outil de l'OP</b> (menu Options), qui reste ce qu'elle \u00e9tait : elle couvre toute l'op\u00e9ration, le plan est propre \u00e0 un outil.\"\n  ]},\n  { version:\"3.17.0\", date:\"05/09/2026\", points:[\n    \"<b>La composition du sc\u00e9nario ne se saisit plus dans un tableau.</b> C'\u00e9tait 15 colonnes rendues en 11 px, avec des largeurs en pourcentage : la colonne \u00ab N\u00b0 outil \u00bb recevait 6 % de la largeur, soit une cinquantaine de pixels, pour y empiler le num\u00e9ro, le correcteur ET le type d'outil. Tout \u00e9tait tronqu\u00e9, on ne pouvait pas relire ce qu'on venait de saisir. C'est maintenant une <b>fiche par outil</b> : chaque champ a son libell\u00e9 au-dessus et une largeur adapt\u00e9e \u00e0 ce qu'il re\u00e7oit \u2014 une r\u00e9f\u00e9rence plaquette dispose de 500 px l\u00e0 o\u00f9 elle en avait 200.\",\n    \"Les champs d'un logement sont regroup\u00e9s par nature : <b>Plaquette</b> (prix, ar\u00eates, charni\u00e8re), <b>Conditions de coupe</b> (Vc, f, \u03bar, et r\u03b5/ap si le module Fr\u00b7Fa est actif), <b>Co\u00fbt</b> (\u20ac/ar\u00eate, \u20ac/pi\u00e8ce, calcul\u00e9s). On trouve ce qu'on cherche sans balayer quinze colonnes.\",\n    \"Taille de saisie remont\u00e9e de 11 \u00e0 14 px \u2014 en dessous, relire un chiffre \u00e0 l'atelier demandait un effort. Les notations sensibles \u00e0 la casse (Vc, f, \u03bar, r\u03b5, ap) ne sont plus mises en majuscules automatiquement : elles s'affichaient \u00ab VC \u00bb, \u00ab KR \u00bb, \u00ab RE \u00bb.\",\n    \"<b>Le tableau compact reste utilis\u00e9 \u00e0 l'impression et dans le rapport client</b>, o\u00f9 rien n'est saisissable et o\u00f9 la compacit\u00e9 a du sens.\",\n    \"<b>Volume annuel invalide signal\u00e9.</b> Un volume n\u00e9gatif ou nul faisait dispara\u00eetre silencieusement tous les gains en \u20ac/an, les heures machine et la consommation de plaquettes \u2014 sans un mot. Un bandeau rouge dit maintenant ce qui ne va pas et o\u00f9 le corriger. Les chiffres ne valent pas z\u00e9ro : ils ne sont pas calcul\u00e9s.\"\n  ]},\n  { version:\"3.16.1\", date:\"05/09/2026\", points:[\n    \"L'import affiche une <b>explication au premier usage</b> : ce que fait \u00ab Remplacer tout \u00bb, ce que fait \u00ab Fusionner \u00bb, et dans quel cas choisir l'un ou l'autre. Une case <b>\u00ab Ne plus afficher cette explication \u00bb</b> la range une fois lue ; elle reste accessible par le lien \u00ab Comment choisir ? \u00bb en haut de la fen\u00eatre d'import.\",\n    \"<b>\u00ab Remplacer tout \u00bb est le choix par d\u00e9faut</b> (bouton bleu, en premier) : aujourd'hui une seule personne tient les saisies, c'est le geste normal et il ne change pas. La fusion est l\u00e0 pour le jour o\u00f9 vous serez plusieurs \u00e0 saisir en parall\u00e8le \u2014 elle attend son heure sans se mettre en travers.\"\n  ]},\n  { version:\"3.16.0\", date:\"05/09/2026\", points:[\n    \"<b>Importer fusionne au lieu d'\u00e9craser.</b> Jusqu'ici, importer un fichier rempla\u00e7ait TOUT \u2014 \u00e0 plusieurs sur le m\u00eame suivi, celui qui importait en dernier effa\u00e7ait le travail de l'autre. L'import propose maintenant deux options : <b>Remplacer tout</b> reste le choix par d\u00e9faut, celui que vous connaissez ; <b>Fusionner</b> ajoute les essais absents, ne remplace un essai pr\u00e9sent des deux c\u00f4t\u00e9s que si la version re\u00e7ue est plus r\u00e9cente, et ne touche jamais \u00e0 vos r\u00e9glages, outils ou conditions de coupe. Un rapport d\u00e9taille apr\u00e8s coup ce qui a \u00e9t\u00e9 ajout\u00e9, mis \u00e0 jour, conserv\u00e9, et liste les conflits \u00e0 v\u00e9rifier.\",\n    \"Chaque essai porte d\u00e9sormais sa date de derni\u00e8re modification \u2014 c'est elle qui arbitre la fusion. Les essais venant d'un fichier ant\u00e9rieur \u00e0 cette version n'en ont pas : s'ils diff\u00e8rent, la fusion garde <b>votre</b> version et vous la signale comme conflit plut\u00f4t que de deviner. \u00c7a se r\u00e9sorbe tout seul d\u00e8s que chacun a r\u00e9-export\u00e9 une fois.\",\n    \"<b>Pr\u00e9vision de sortie de tol\u00e9rance.</b> \u00c0 c\u00f4t\u00e9 de la progression d'un logement, une pastille extrapole l'usure mesur\u00e9e : \u00ab tendance : tol. vers 199 p \u00b1 8 \u00bb. Elle passe au rouge si la tol\u00e9rance serait atteinte avant la charni\u00e8re vis\u00e9e \u2014 de quoi arr\u00eater un essai qui ne tiendra pas, ou le prolonger en connaissance de cause. Il faut au moins 4 pr\u00e9l\u00e8vements et une tendance nette : en dessous, l'outil affiche \u00ab tendance non lisible \u00bb plut\u00f4t qu'un chiffre non d\u00e9fendable.\",\n    \"<b>Dispersion par \u00e9quipe</b> dans la vue de synth\u00e8se : taux hors tol\u00e9rance de chaque poste sur chaque sc\u00e9nario. M\u00eame outil, m\u00eame sc\u00e9nario, un \u00e9cart marqu\u00e9 d'un poste \u00e0 l'autre pointe la conduite plut\u00f4t que la plaquette. Un badge signale un \u00e9cart de plus de 5 points au-dessus des autres \u00e9quipes (\u00e0 partir de 10 pr\u00e9l\u00e8vements).\",\n    \"<b>Mode consultation</b> (bouton cadenas) : passe l'outil en lecture seule pour l'\u00e9cran partag\u00e9 d'atelier \u2014 plus de cote modifi\u00e9e par un coup de gant sur la tablette. Le mode atelier reste utilisable pour relever des mesures. Le verrouillage est propre \u00e0 chaque poste et retenu d'une ouverture \u00e0 l'autre.\",\n    \"Le fichier de l'outil s'all\u00e8ge de 81 ko (logo r\u00e9-encod\u00e9 \u00e0 la taille r\u00e9ellement affich\u00e9e) : ouverture plus rapide depuis une cl\u00e9 USB ou un poste lent.\"\n  ]},\n  { version:\"3.15.0\", date:\"04/09/2026\", points:[\n    \"<b>Nouvelle identit\u00e9 visuelle de l'outil</b> \u2014 l'interface \u00e9tait devenue difficile \u00e0 lire : les libell\u00e9s gris plafonnaient \u00e0 3,5:1 de contraste (le minimum recommand\u00e9 est 4,5:1) et les bordures tr\u00e8s p\u00e2les ne s\u00e9paraient plus rien. Tout a \u00e9t\u00e9 recalibr\u00e9 : libell\u00e9s \u00e0 6:1, texte secondaire \u00e0 8,4:1, bordures franches, encre plus dense.\",\n    \"Les chiffres cl\u00e9s (co\u00fbt pi\u00e8ce, gain annuel, temps de cycle, validation) sont d\u00e9sormais pos\u00e9s sur des <b>aplats de couleur pleine</b> plut\u00f4t que sur du blanc : la rang\u00e9e se lit \u00e0 deux m\u00e8tres, sur un \u00e9cran d'atelier comme en salle devant un client. La validation part en vert, elle ne se confond plus avec les co\u00fbts.\",\n    \"Bandeau de t\u00eate sur fond noir, logo sur plaque blanche.\",\n    \"Nouvelles polices : <b>Manrope</b> pour les titres et les gros chiffres, <b>Public Sans</b> pour le texte courant et l'interface \u2014 dessin\u00e9e pour les petites tailles \u00e0 l'\u00e9cran, l\u00e0 o\u00f9 l'ancienne se brouillait sous 12 px. Elles sont embarqu\u00e9es dans le fichier : rien \u00e0 installer, rien \u00e0 t\u00e9l\u00e9charger, l'outil fonctionne toujours hors ligne.\",\n    \"Le mode sombre a \u00e9t\u00e9 refait avec la m\u00eame logique (et non plus par simple inversion) ; le PDF et le rapport client suivent la m\u00eame palette.\"\n  ]},\n  { version:\"3.14.1\", date:\"04/09/2026\", points:[\n    \"Derniers ajustements cosm\u00e9tiques de la revue de code externe : meilleur contraste des badges gris (lisibilit\u00e9 en atelier), lightbox photo avec un rappel \u00ab Cliquer ou \u00c9chap pour fermer \u00bb, menu \u2022\u2022\u2022 qui se ferme d\u00e9sormais avec \u00c9chap, et saisie plus fluide dans les champs num\u00e9riques d'Options.\"\n  ]},\n  { version:\"3.14.0\", date:\"03/09/2026\", points:[\n    \"<b>Confidentialit\u00e9</b> : les donn\u00e9es de d\u00e9marrage (premier lancement, apr\u00e8s R\u00e9initialiser) reprenaient par erreur des r\u00e9f\u00e9rences et mesures r\u00e9elles au lieu de donn\u00e9es fictives. Remplac\u00e9es par un jeu d'exemple g\u00e9n\u00e9rique, clairement identifi\u00e9 \u00ab [Exemple] \u00bb.\",\n    \"Marge avant d'afficher un \u00e9cart de charni\u00e8re (auparavant fix\u00e9e \u00e0 0,5 pi\u00e8ce sans possibilit\u00e9 de l'ajuster) r\u00e9glable dans <b>Options</b>.\",\n    \"Le badge \u00ab \u2605 R\u00e9f\u00e9rence \u00bb d'un sc\u00e9nario est renomm\u00e9 \u00ab \u2605 Sc\u00e9nario r\u00e9f. \u00bb pour ne plus le confondre avec la r\u00e9f\u00e9rence disque ou la r\u00e9f\u00e9rence plaquette \u2014 trois choses diff\u00e9rentes qui portaient le m\u00eame mot.\",\n    \"Champ \u00ab R\u00e9dig\u00e9 par \u00bb d'un essai : placeholder et info-bulle pr\u00e9cisent qu'il s'agit du r\u00e9dacteur du rapport, pas forc\u00e9ment l'op\u00e9rateur machine.\",\n    \"\u00c9diteur d'annotation photo : fermer sans enregistrer (\u00c9chap ou clic en dehors) demande confirmation s'il y a des changements non enregistr\u00e9s ; couleurs plus grandes au doigt sur \u00e9cran tactile.\",\n    \"Statuts \u00ab Valid\u00e9 \u00bb et \u00ab En s\u00e9rie \u00bb distingu\u00e9s par une couleur diff\u00e9rente (vert / bleu) \u2014 ils \u00e9taient visuellement trop proches alors que le sens est tr\u00e8s diff\u00e9rent (essai confirm\u00e9 vs tourne en production).\"\n  ]},\n  { version:\"3.13.0\", date:\"03/09/2026\", points:[\n    \"Correctifs de fond suite \u00e0 une revue de code externe : le champ \u00ab Temps de cycle \u00bb du sc\u00e9nario de r\u00e9f\u00e9rence \u00e9tait \u00e9ditable alors qu'il est toujours \u00e9cras\u00e9 \u00e0 100 au chargement \u2014 il est maintenant affich\u00e9 en lecture seule pour ne plus induire en erreur.\",\n    \"\u00c9diteur d'annotation photo : la touche Suppr efface maintenant vraiment la forme s\u00e9lectionn\u00e9e (promise mais pas c\u00e2bl\u00e9e), le bouton \u00ab Valider le rognage \u00bb est gris\u00e9 tant qu'aucune zone n'est trac\u00e9e, et un message avertit si la sauvegarde automatique est bloqu\u00e9e apr\u00e8s avoir annot\u00e9 une photo.\",\n    \"R\u00e9duction de fuite m\u00e9moire sur les photos (URLs temporaires lib\u00e9r\u00e9es apr\u00e8s usage) et sur la compression d'image \u00e0 l'ajout d'une photo.\",\n    \"La migration d'un ancien fichier de suivi est d\u00e9sormais sauvegard\u00e9e imm\u00e9diatement, au lieu d'\u00eatre refaite \u00e0 chaque ouverture tant qu'aucune autre saisie n'avait d\u00e9clench\u00e9 de sauvegarde.\",\n    \"Avertissement ajout\u00e9 quand les Vc/f de la r\u00e9f\u00e9rence manquent : l'indice de cycle des autres sc\u00e9narios n'est alors plus recalcul\u00e9 automatiquement, ce qui n'\u00e9tait pas signal\u00e9.\"\n  ]},\n  { version:\"3.12.0\", date:\"03/09/2026\", points:[\n    \"Nouvel \u00e9diteur <b>\u00ab Annoter \u00bb</b> sur chaque photo d'essai (ic\u00f4ne \u270e sur la miniature) : rognage, fl\u00e8ches droites, fl\u00e8ches courbes (poign\u00e9e ajustable), rectangles et ellipses de s\u00e9lection, texte flottant, choix de couleur. Rien n'est jamais appliqu\u00e9 au fichier photo d'origine \u2014 tout est recompos\u00e9 \u00e0 l'affichage, donc modifiable ind\u00e9finiment.\",\n    \"Cliquer sur une miniature de photo l'ouvre d\u00e9sormais en plein \u00e9cran avec ses annotations.\"\n  ]},\n  { version:\"3.11.0\", date:\"03/09/2026\", points:[\n    \"Champs manquants par rapport aux rapports papier terrain, tous ajout\u00e9s : <b>r\u00e9dig\u00e9 par</b>, <b>fin d'essai</b> (date + heure, en plus de la date de d\u00e9but), <b>nom du programme CNC</b> (Gauche/Droit sur EMAG 1, unique sinon) \u2014 dans le bloc de chaque essai.\",\n    \"<b>Correcteur</b> et <b>type d'outil</b> (ex. \u00ab Foret carbure monobloc \u00e0 goujure droite \u00bb) ajout\u00e9s par outil, dans la composition du sc\u00e9nario.\",\n    \"<b>L\u00e9gende par photo</b> d'essai (ex. \u00ab Usure de l'ar\u00eate apr\u00e8s 4212 pi\u00e8ces \u00bb).\",\n    \"Tous ces champs reprennent dans le rapport d'essai et le rapport de validation g\u00e9n\u00e9r\u00e9s.\"\n  ]},\n  { version:\"3.10.0\", date:\"02/09/2026\", points:[\n    \"Nouveau module <b>\u00ab D\u00e9tailler le temps de cycle par logement \u00bb</b> (Options) : remplace l'indice base 100 par un temps coupe + un temps d\u00e9placement mesur\u00e9s machine, saisis pour chaque logement dans la composition du sc\u00e9nario. Plus fid\u00e8le qu'un indice unique sur un sc\u00e9nario mixte (ex. un seul c\u00f4t\u00e9 change de plaquette).\",\n    \"Le calcul d\u00e9taill\u00e9 ne s'applique que si <b>tous</b> les logements du sc\u00e9nario sont renseign\u00e9s \u2014 sinon le sc\u00e9nario retombe automatiquement sur l'indice base 100, avec un statut visible sous le tableau qui le dit clairement.\",\n    \"Possibilit\u00e9 de <b>joindre une fiche outil (PDF ou image)</b> par OP, dans Options : n\u00b0 d'outils et trajectoires par logement, comme rep\u00e8re pendant la saisie.\"\n  ]},\n  { version:\"3.9.5\", date:\"02/09/2026\", points:[\n    \"<b>Correctif urgent</b> : l'agrandissement d'image ajout\u00e9 en 3.9.2 \u00e9tait affich\u00e9 en permanence par erreur (voile sombre plein \u00e9cran d\u00e8s l'ouverture, quoi que vous fassiez). Corrig\u00e9.\"\n  ]},\n  { version:\"3.9.4\", date:\"02/09/2026\", points:[\n    \"Ajout d'un rappel bien visible dans <b>Options</b>, sous \u00ab Int\u00e9grer le temps machine au co\u00fbt pi\u00e8ce \u00bb : pour que le temps de cycle p\u00e8se dans le gain annuel, il faut activer les deux modules cycle ET renseigner le co\u00fbt horaire de la ligne ET le temps de cycle r\u00e9el de la r\u00e9f\u00e9rence.\"\n  ]},\n  { version:\"3.9.3\", date:\"02/09/2026\", points:[\n    \"Le champ \u00ab Temps de cycle \u00bb du bloc sc\u00e9nario pr\u00e9cise maintenant qu'il s'agit d'un <b>indice base 100</b> \u2014 il pouvait \u00eatre confondu avec le temps r\u00e9el en secondes affich\u00e9 juste en dessous.\",\n    \"Quand vous modifiez le temps de cycle sans avoir activ\u00e9 \u00ab Int\u00e9grer le temps machine au co\u00fbt pi\u00e8ce \u00bb (module Options), le <b>gain annuel</b> ne bouge pas volontairement \u2014 un avertissement l'indique d\u00e9sormais directement sous le gain, au lieu de laisser croire \u00e0 un bug.\"\n  ]},\n  { version:\"3.9.2\", date:\"02/09/2026\", points:[\n    \"Les captures jointes \u00e0 une suggestion (menu <b>\u2022\u2022\u2022</b> \u2192 <b>Suggestions</b>) s'agrandissent maintenant en plein \u00e9cran d'un clic \u2014 elles \u00e9taient jusque-l\u00e0 trop petites pour \u00eatre lisibles.\",\n    \"Rappel ajout\u00e9 dans cette fen\u00eatre \u00ab Nouveaut\u00e9s \u00bb : quand une \u00e9volution correspond \u00e0 une suggestion que vous aviez not\u00e9e, pensez \u00e0 passer son statut sur <b>Trait\u00e9</b>.\"\n  ]},\n  { version:\"3.9.1\", date:\"02/09/2026\", points:[\n    \"Correctif : quand la <b>production annuelle</b> \u00e9tait renseign\u00e9e, la tuile qui l'affiche pouvait chevaucher le tableau \u00ab Composition du sc\u00e9nario \u00bb et en \u00e9craser les colonnes. Le tableau passe d\u00e9sormais toujours sous la tuile.\"\n  ]},\n  { version:\"3.9.0\", date:\"02/09/2026\", points:[\n    \"Chaque pr\u00e9l\u00e8vement porte d\u00e9sormais un statut d'<b>usure visuelle de la plaquette</b> (OK / usure limite / \u00e0 changer) \u2014 \u00ab \u00e0 changer \u00bb rend le pr\u00e9l\u00e8vement non conforme m\u00eame si les cotes sont bonnes.\",\n    \"Un sc\u00e9nario peut activer un <b>2e crit\u00e8re de tol\u00e9rance</b> (ex. \u00e9tat de surface Ra/Rz/Rt en plus d'une cote dimensionnelle) dans son bloc \u00ab Essais \u00bb \u2014 les deux doivent \u00eatre respect\u00e9s pour qu'un pr\u00e9l\u00e8vement soit conforme.\",\n    \"Le motif \u00ab hors tol\u00e9rance \u00bb affich\u00e9 sur les essais est d\u00e9sormais pr\u00e9cis (cote, 2e crit\u00e8re, ou usure) plut\u00f4t qu'un seul libell\u00e9 g\u00e9n\u00e9rique.\",\n    \"Les rapports de validation et d'essai, la table de pr\u00e9l\u00e8vements et l'export CSV reprennent ces deux nouveaux crit\u00e8res.\"\n  ]},\n  { version:\"3.8.0\", date:\"02/09/2026\", points:[\n    \"L'outil annonce lui-m\u00eame ce qui change \u00e0 chaque nouvelle version : cette fen\u00eatre s'ouvre une fois, puis plus jusqu'\u00e0 la prochaine mise \u00e0 jour. Elle reste consultable dans le menu <b>\u2022\u2022\u2022</b> \u2192 <b>Nouveaut\u00e9s</b>.\",\n    \"Le menu <b>Comment \u00e7a marche</b> (ic\u00f4ne <b>?</b>) a \u00e9t\u00e9 compl\u00e9t\u00e9 : co\u00fbt complet, seuil de bascule, charni\u00e8re atteinte, statuts et tableau de bord y sont expliqu\u00e9s.\"\n  ]},\n  { version:\"3.7.0\", date:\"02/09/2026\", points:[\n    \"Le <b>sc\u00e9nario ouvert</b> passe en t\u00eate de la liste, en plus grand et l\u00e9g\u00e8rement bleut\u00e9. Chaque tuile porte son num\u00e9ro et une couleur donnant son statut.\",\n    \"La <b>composition du sc\u00e9nario</b> (outils, plaquettes, pi\u00e8ces d\u00e9tach\u00e9es, conditions de coupe) remonte juste sous les chiffres cl\u00e9s, et s'affiche d\u00e9pli\u00e9e.\",\n    \"La <b>production annuelle</b> appara\u00eet en grand en haut \u00e0 droite de cette composition, d\u00e8s que le volume est renseign\u00e9.\",\n    \"Correction : le s\u00e9parateur des milliers ne s'affichait pas \u2014 \u00ab 200 000 \u00bb apparaissait coll\u00e9.\"\n  ]},\n  { version:\"3.5.0 \u2014 3.6.0\", date:\"02/09/2026\", points:[\n    \"<b>Le co\u00fbt complet par pi\u00e8ce.</b> L'outil sait maintenant ajouter au prix des plaquettes le temps machine, les pi\u00e8ces d\u00e9tach\u00e9es du porte-outil et le co\u00fbt du rebut. Un sc\u00e9nario moins cher en outil mais plus lent peut se r\u00e9v\u00e9ler perdant : \u00e0 activer dans <b>Options</b>.\",\n    \"<b>Gain annuel en euros</b> et \u00e9cart d'heures machine sur l'ann\u00e9e, d\u00e8s que le volume de production de la r\u00e9f\u00e9rence est renseign\u00e9.\",\n    \"<b>Seuil de bascule</b> : le temps de cycle maximum pour qu'un sc\u00e9nario reste gagnant.\",\n    \"<b>Charni\u00e8re r\u00e9ellement atteinte</b>, calcul\u00e9e depuis les essais et affich\u00e9e sous la charni\u00e8re vis\u00e9e.\",\n    \"<b>Statuts de sc\u00e9nario</b> (\u00e0 l'\u00e9tude, en essai, valid\u00e9, en s\u00e9rie, abandonn\u00e9) et <b>tableau de bord</b> reprenant toutes les lignes et r\u00e9f\u00e9rences d'un coup.\",\n    \"L'outil ne va plus chercher aucune ressource sur internet : il s'ouvre \u00e0 l'identique sans r\u00e9seau, sur cl\u00e9 USB ou derri\u00e8re un proxy d'usine.\"\n  ]},\n  { version:\"3.4.0\", date:\"30/08/2026\", points:[\n    \"<b>Rapport par essai</b> : une page autonome reprenant interlocuteurs, plaquettes, but de l'essai, conditions de coupe, pr\u00e9l\u00e8vements et verdict.\",\n    \"Les essais sont repli\u00e9s en <b>tuiles</b> color\u00e9es selon leur \u00e9tat ; on les d\u00e9plie au clic.\"\n  ]}\n];\n\nconst TOOL_VERSION = \"4.81.1\";\nconst CLE_VERSION_VUE = \"spk_derniere_version_vue\";\nconst CLE_NOUVEAUTES_OFF = \"spk_nouveautes_masquees\";\n\nfunction nouveautesHTML(){\n  /* v4.25 \u2014 la popup au d\u00e9marrage ne raconte que le tr\u00e8s r\u00e9cent : au-del\u00e0 de 10 jours,\n     les modifs ont \u00e9t\u00e9 vues ou n'int\u00e9ressent plus (Matis). On garde la dizaine \u00e9coul\u00e9e,\n     date illisible except\u00e9e (prudence), et jamais une liste vide. */\n  const limite = Date.now() - 10 * 24 * 3600 * 1000;\n  const recentes = NOUVEAUTES.filter(n => {\n    const [j, m, a] = (n.date || \"\").split(\"/\").map(Number);\n    if(!j || !m || !a) return true;\n    return new Date(a, m - 1, j).getTime() >= limite;\n  });\n  const liste = recentes.length ? recentes : NOUVEAUTES.slice(0, 1);\n  return liste.map((n, i) => `\n    <div class=\"nv-bloc${i === 0 ? \" nv-actuelle\" : \"\"}\">\n      <div class=\"nv-tete\">\n        <span class=\"nv-version\">Version ${n.version}</span>\n        <span class=\"nv-date\">${n.date}</span>\n      </div>\n      <ul>${n.points.map(p => `<li>${p}</li>`).join(\"\")}</ul>\n    </div>`).join(\"\");\n}\nfunction ouvrirNouveautes(){\n  const wrap = document.getElementById(\"nouveautesPanel\");\n  const masquees = (() => { try { return localStorage.getItem(CLE_NOUVEAUTES_OFF) === \"1\"; } catch(e){ return false; } })();\n  wrap.innerHTML = `\n    <h3>Nouveaut\u00e9s de l'outil</h3>\n    <p class=\"panel-hint\">Vous utilisez la version <b>${TOOL_VERSION}</b>. Voici ce qui a chang\u00e9 depuis vos derni\u00e8res utilisations \u2014 inutile d'attendre un e-mail.</p>\n    <p class=\"panel-hint\">Une \u00e9volution ci-dessous r\u00e9pond \u00e0 une suggestion que vous aviez not\u00e9e ? Pensez \u00e0 passer son statut sur <b>Trait\u00e9</b> (menu <b>\u2022\u2022\u2022</b> \u2192 <b>Suggestions</b>) \u2014 l'outil ne le fait pas tout seul.</p>\n    ${nouveautesHTML()}\n    <label class=\"opt-row\" style=\"margin-top:18px;\">\n      <input type=\"checkbox\" id=\"nvMasquer\" ${masquees ? \"checked\" : \"\"}>\n      <span><b>Ne plus afficher cette fen\u00eatre automatiquement</b>\n      <em>Vous ne serez plus pr\u00e9venu des \u00e9volutions suivantes. Les nouveaut\u00e9s resteront consultables dans le menu <b>\u2022\u2022\u2022</b>.</em></span>\n    </label>\n    <div class=\"panel-actions\"><button class=\"primary\" id=\"nvFermer\">J'ai vu</button></div>`;\n  wrap.querySelector(\"#nvFermer\").addEventListener(\"click\", () => {\n    try {\n      localStorage.setItem(CLE_VERSION_VUE, TOOL_VERSION);\n      localStorage.setItem(CLE_NOUVEAUTES_OFF, wrap.querySelector(\"#nvMasquer\").checked ? \"1\" : \"0\");\n    } catch(e){}\n    fermerPanneaux();\n  });\n  ouvrirPanneau(\"nouveautesPanel\");\n}\n/* au chargement : on n'ouvre que si la version a change depuis la derniere lecture.\n   Aucune valeur enregistree = premiere fois qu'on croise cette fonction, on affiche\n   (c'est ce qui fait que le premier deploiement atteint bien tout le monde). */\nfunction verifierNouveautes(){\n  let vue = null, off = false;\n  try {\n    vue = localStorage.getItem(CLE_VERSION_VUE);\n    off = localStorage.getItem(CLE_NOUVEAUTES_OFF) === \"1\";\n  } catch(e){ return; }\n  if(off || vue === TOOL_VERSION) return;\n  ouvrirNouveautes();\n}\n\n/* ---- parcours de demarrage (v4.6) ----\n   La regole v4.4 \u2014 \"poser la production d'abord, creer les projets ensuite\" \u2014 n'etait qu'une\n   convention a transmettre oralement. Elle est maintenant dans l'outil : un panneau checklist\n   (menu \u2022\u2022\u2022 \u2192 D\u00e9marrer un suivi) et un bandeau qui s'affiche sur un suivi vierge (ni scenario\n   en production, ni projet) tant que la premiere etape n'est pas faite. Le bandeau se cache\n   tout seul des qu'un sc\u00e9nario \u2605 existe ou qu'un projet est cr\u00e9\u00e9 \u2014 la cle \"masquer\" ne sert\n   que si l'utilisateur veut garder un suivi vide sans rappel. */\nconst CLE_PARCOURS_MASQUE = \"spk_parcours_masque\";\nfunction etatParcours(){\n  const op = getActiveOp();\n  const scenarios = op ? (op.scenarios || []) : [];\n  return {\n    prod: scenarios.some(s => s.baseline),\n    projet: (projets || []).length > 0\n  };\n}\nfunction ouvrirParcours(){\n  const wrap = document.getElementById(\"parcoursPanel\");\n  const et = etatParcours();\n  const etape = (n, titre, fait, corps) => `\n    <div class=\"pc-step${fait ? \" pc-fait\" : \"\"}\">\n      <span class=\"pc-num\">${fait ? \"\u2713\" : n}</span>\n      <div class=\"pc-corps\"><b>${titre}</b>${corps}</div>\n    </div>`;\n  wrap.innerHTML = `\n    <h3>D\u00e9marrer un suivi</h3>\n    <p class=\"panel-hint\">L'ordre recommand\u00e9 : la production d'abord, l'organisation ensuite.\n    Les \u00e9tapes se cochent toutes seules au fur et \u00e0 mesure.</p>\n    ${etape(1, \"Une ligne de production\", true,\n      \"D\u00e9j\u00e0 en place \u2014 c'est le premier ruban en haut de page. \u00ab + Ligne de production \u00bb en ajoute d'autres : EMAG 2, WEISSER, HESSAP\u2026\")}\n    ${etape(2, \"Un sc\u00e9nario en production (\u2605) sur l'OP\", et.prod, et.prod\n      ? \"C'est le process r\u00e9ellement en s\u00e9rie : il sert de base 100 \u00e0 toutes les comparaisons.\"\n      : \"Le process r\u00e9ellement en s\u00e9rie sur la machine : co\u00fbts, cycle, outillage. C'est la base 100 de toutes les comparaisons. S'il n'existe pas encore, ajoutez un sc\u00e9nario puis d\u00e9signez-le avec sa pastille \u2605.\")}\n    ${etape(3, \"Un premier projet\", et.projet, et.projet\n      ? \"L'organisation du travail d'optimisation est en place : les sc\u00e9narios sont \u00e9tiquet\u00e9s par probl\u00e9matique.\"\n      : \"Il regroupe les sc\u00e9narios qui r\u00e9pondent \u00e0 une m\u00eame probl\u00e9matique (co\u00fbt, qualit\u00e9, \u00ab Essais Step 3 \u00bb\u2026). Cr\u00e9ez-le avec \u00ab + Cr\u00e9er un projet \u00bb : il rattachera automatiquement les sc\u00e9narios de l'OP ouvert, ajustez ensuite les \u00e9tiquettes.\")}\n    <p class=\"opt-note\">Les projets sont facultatifs : un sc\u00e9nario vit tr\u00e8s bien sans projet.\n    L'essentiel est d'avoir d'abord un sc\u00e9nario en production \u00e0 comparer.</p>\n    <div class=\"panel-actions\"><button class=\"primary\" id=\"parcoursFermer\">C'est parti</button></div>`;\n  wrap.querySelector(\"#parcoursFermer\").addEventListener(\"click\", fermerPanneaux);\n  ouvrirPanneau(\"parcoursPanel\");\n}\nfunction renderParcours(){\n  const el = document.getElementById(\"parcoursBandeau\");\n  if(!el) return;\n  let masque = false;\n  try{ masque = localStorage.getItem(CLE_PARCOURS_MASQUE) === \"1\"; }catch(e){}\n  const et = etatParcours();\n  const montrer = !et.prod && !et.projet && !masque;\n  el.hidden = !montrer;\n  if(!montrer) return;\n  el.innerHTML = `\n    <b>D\u00e9marrer</b>\n    <span>Suivi vierge : commencez par poser le <b>sc\u00e9nario en production (\u2605)</b> \u2014 le process r\u00e9ellement en s\u00e9rie \u2014 puis cr\u00e9ez vos projets par-dessus. C'est l'ordre recommand\u00e9 pour que les comparaisons aient un sens d\u00e8s le premier jour.</span>\n    <button class=\"primary\" id=\"parcoursVoir\">Voir le parcours</button>\n    <button class=\"ghost\" id=\"parcoursMasquer\" title=\"Ne plus afficher ce rappel sur ce poste\">Masquer</button>`;\n  el.querySelector(\"#parcoursVoir\").addEventListener(\"click\", ouvrirParcours);\n  el.querySelector(\"#parcoursMasquer\").addEventListener(\"click\", () => {\n    try{ localStorage.setItem(CLE_PARCOURS_MASQUE, \"1\"); }catch(e){}\n    renderParcours();\n  });\n}\n\n/* ---- tableau de bord : toutes les lignes d'un coup ----\n   Le moteur lit la tolerance et le scenario de reference dans les globales `config` et\n   `data`, qui pointent sur l'OP active. Pour parcourir les AUTRES OP sans threader un\n   parametre dans toute la chaine de calcul, on bascule temporairement le contexte puis on\n   le remet. Tout est synchrone : rien ne peut s'intercaler entre les deux. */\nfunction dansContexteOp(op, fn){\n  const cfgAvant = config, dataAvant = data;\n  config = op.config; data = op.scenarios;\n  try { return fn(); } finally { config = cfgAvant; data = dataAvant; }\n}\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   v4.51.0 \u2014 Carte atelier, couche 0 : le calcul pur du poste (sans un pixel d'UI)\n\n   Deux fonctions PURES, test\u00e9es, plac\u00e9es juste avant renderDashboard() (L11547) parce\n   que la carte atelier est une \u00e9volution du tableau de bord : m\u00eame source, jamais un\n   second agr\u00e9gat de gains. gainPoste() alimente la tuile et, plus tard, l'A4 Mission ;\n   etatTuile() donne l'\u00e9tat de la tuile (gagn\u00e9 / en cours / \u00e0 chiffrer / opportunit\u00e9)\n   sans jamais qu'une cascade de \u00ab if \u00bb dans le HTML d\u00e9cide de la couleur.\n\n   Rappel D3 : la tuile n'affiche JAMAIS un chiffre que le bandeau du sc\u00e9nario\n   n'afficherait pas. D'o\u00f9 le choix de bilanAnnuel() : c'est lui qui applique d\u00e9j\u00e0\n   perimetreCompare() (v4.45) et qui signale perimetrePartiel. On ne recalcule rien.\n   \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n/* Un poste = un couple (ligne x opCode). On ne dessine que les couples D\u00c9CLAR\u00c9S :\n   les machines de la ligne viennent de LIGNES_SEPT_FONS (v4.50), et les OP sans\n   code exploitable (opCode \"?\", v4.50) ne dessinent aucune tuile \u2014 elles restent\n   atteignables par la navigation experte. */\nfunction postesLigne(ligne, lignesSeptFons){\n  const def = (lignesSeptFons || []).find(d => d.nom === (ligne && ligne.nom));\n  const machines = (def && def.machines) || [];\n  return machines.map(m => ({ code: m.code, nom: m.nom || \"\", ligne }));\n}\n\n/* Les sc\u00e9narios d'une ligne qui portent l'OP demand\u00e9e (par CODE, pas par nom :\n   \u00ab OP 30 Per\u00e7ages \u00bb et \u00ab OP30 \u00bb sont le m\u00eame poste). */\nfunction scenariosPostes(ligne, opCode){\n  const out = [];\n  (ligne && ligne.references ? ligne.references : []).forEach(ref => {\n    (ref.ops || []).forEach(op => {\n      if((op.opCode || \"?\") !== opCode) return;\n      out.push({ ref, op, scs: op.scenarios || [] });\n    });\n  });\n  return out;\n}\n\n/* \u2500\u2500 Le c\u0153ur : le gain d'un poste, p\u00e9rim\u00e8tre commun obligatoire \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n   Un poste peut \u00eatre servi par plusieurs r\u00e9f\u00e9rences (EMAG 1 : 356x26 + 304x28) :\n   on additionne r\u00e9f\u00e9rence par r\u00e9f\u00e9rence, chaque delta passant par bilanAnnuel() \u2014\n   donc par perimetreCompare() (v4.45). Jamais une soustraction de deux totaux bruts.\n   Le cas asym\u00e9trique r\u00e9el (une OP avec prod chiffrable, une sans) sort du calcul,\n   il ne devient pas 0 : il est compt\u00e9 dans nonChiffres.\n\n   Renvoie { ligne, opCode, nom, refs, gainActe, gainProjete, coutProd, coutEnCours,\n             cibleCPP, chemin, essaiOuvert, nonChiffres, refDominante } */\nfunction gainPoste(ligne, opCode, lignesSeptFons){\n  const poste = (postesLigne(ligne, lignesSeptFons) || []).find(p => p.code === opCode)\n              || { code: opCode, nom: \"\", ligne };\n  const blocs = scenariosPostes(ligne, opCode);\n  const refs = [];\n  let gainActe = 0, gainProjete = 0, coutProd = 0, coutEnCours = 0;\n  let essaiOuvert = false, nonChiffres = 0;\n\n  blocs.forEach(b => {\n    /* v4.51.2 \u2014 la cible se lit AVANT tout calcul de co\u00fbt. Une r\u00e9f\u00e9rence qui porte une\n       cible mais aucun sc\u00e9nario chiffrable est justement le cas \u00ab \u00e0 chiffrer \u00bb (H1-a) :\n       elle doit pouvoir le dire, donc \u00eatre enregistr\u00e9e dans refs m\u00eame sans prod. Avant,\n       le return ci-dessous la faisait dispara\u00eetre de refs et la tuile tombait en\n       \u00ab opportunit\u00e9 \u00bb \u2014 l'invitation que l'atelier doit voir disparaissait. */\n    const cibleBl = cibleCPPDe(b.ref);\n    /* la prod d'une OP, c'est D'ABORD la prod r\u00e9elle (\u2605), l'excel en repli (v4.49.4) */\n    const excel = (b.scs || []).find(x => /base excel/i.test(x.name || \"\"));\n    const star  = (b.scs || []).find(x => x.baseline);\n    const prodSc = star || excel || null;\n    if(!prodSc){\n      nonChiffres++;\n      if(cibleBl !== null) refs.push({ ref: b.ref, prodSc: null, meilleur: null, tBase: null,\n                                       gain: null, serie: false, volume: volumeAnnuel(b.ref, b.op.config),\n                                       essaiOuvert: false, nonChiffre: true });\n      return;\n    }\n\n    const tBase = coutsDetail(prodSc, b.op.config, ligne).total;\n    if(tBase === null){\n      nonChiffres++;\n      if(cibleBl !== null) refs.push({ ref: b.ref, prodSc, meilleur: null, tBase: null,\n                                       gain: null, serie: false, volume: volumeAnnuel(b.ref, b.op.config),\n                                       essaiOuvert: false, nonChiffre: true });\n      return;\n    }\n\n    /* le meilleur sc\u00e9nario non-prod chiffrable : le gain ne peut se comparer que si\n       l'autre c\u00f4t\u00e9 de la comparaison est chiffrable aussi (v4.45) */\n    let meilleur = null;\n    (b.scs || []).forEach(sc => {\n      if(prodSc.id === sc.id) return;\n      const t = coutsDetail(sc, b.op.config, ligne).total;\n      if(t === null) return;\n      if(!meilleur || t < meilleur.cout) meilleur = { sc, cout: t };\n    });\n\n    /* m\u00eame formule, m\u00eame p\u00e9rim\u00e8tre que le bandeau : bilanAnnuel() applique d\u00e9j\u00e0\n       perimetreCompare() et signale les postes exclus. On ne recalcule rien. */\n    const an = meilleur ? bilanAnnuel(meilleur.sc, b.op.config, ligne, b.ref, prodSc) : null;\n    let gain = null;\n    if(an && an.gainAnnuel !== undefined) gain = an.gainAnnuel;\n\n    const serie = !!(meilleur && meilleur.sc.statut === \"serie\");\n    if(gain !== null){\n      if(serie) gainActe += gain;\n      else      gainProjete += gain;\n    }\n    coutProd    += tBase;\n    /* v4.51.1 \u2014 \u00ab en cours \u00bb = ce que la pi\u00e8ce co\u00fbte AUJOURD'HUI. On cr\u00e9dite le\n       meilleur sc\u00e9nario SANS condition de statut, exactement comme le fait\n       pieceCPPComplet() (v4.49) : `meilleur.cout < tBase ? meilleur.cout : tBase`.\n       Ma premi\u00e8re version (4.51.0) ne cr\u00e9ditait que le projet\u00e9, ce qui faisait\n       diverger la carte du bandeau sur un poste act\u00e9 (Z Code, revue crois\u00e9e du \u00a72) :\n       un gain r\u00e9alis\u00e9 ne faisait plus bouger le chemin prod \u2192 cible, alors que c'est\n       justement le chiffre que la hi\u00e9rarchie doit voir. D3 (source unique) prime :\n       deux modules ne doivent jamais raconter deux histoires diff\u00e9rentes. */\n    coutEnCours += (meilleur && meilleur.cout < tBase) ? meilleur.cout : tBase;\n\n    if((b.scs || []).some(x => (x.essais || []).length)) essaiOuvert = true;\n\n    refs.push({ ref: b.ref, prodSc, meilleur, tBase, gain, serie,\n                volume: volumeAnnuel(b.ref, b.op.config), essaiOuvert: (meilleur && (meilleur.sc.essais || []).length) || false });\n  });\n\n  /* la r\u00e9f\u00e9rence DOMINANTE = celle du plus gros volume de s\u00e9rie : c'est elle qui\n     d\u00e9cide du chemin prod \u2192 cible affich\u00e9 sur la tuile. Une tuile multi-r\u00e9f\u00e9rences\n     n'affiche qu'une seule cible, sinon deux chiffres se contredisent. */\n  const dominante = refs.slice().sort((a, b) => (b.volume || 0) - (a.volume || 0))[0];\n  const refDominante = dominante ? dominante.ref : null;\n  const cible = refDominante ? cibleCPPDe(refDominante) : null;\n\n  let chemin = null;\n  if(cible !== null && cible > 0 && coutProd > cible && coutProd > 0){\n    chemin = Math.max(0, Math.min(100, ((coutProd - coutEnCours) / (coutProd - cible)) * 100));\n  }\n\n  return { ligne, opCode, nom: poste.nom, refs, gainActe, gainProjete, coutProd, coutEnCours,\n           cibleCPP: cible, chemin, essaiOuvert, nonChiffres, refDominante };\n}\n\n/* la cible CPP d'une r\u00e9f\u00e9rence, normalis\u00e9e (nombre > 0, sinon \u00ab pas de cible \u00bb) */\nfunction cibleCPPDe(ref){\n  if(!ref || ref.cibleCPP === \"\" || ref.cibleCPP == null) return null;\n  const v = parseFloat(ref.cibleCPP);\n  return isNaN(v) || v <= 0 ? null : v;\n}\n\n/* \u2500\u2500 L'\u00e9tat de la tuile : UNE fonction, jamais une cascade de if dans le HTML \u2500\u2500\n   a) gagne      : un gain d\u00e9j\u00e0 act\u00e9 (sc\u00e9nario en s\u00e9rie) ;\n   b) encours    : un essai existe sur ce poste sans gain act\u00e9 ;\n   c) aChiffrer  : la r\u00e9f\u00e9rence dominante a une cible CPP, mais rien n'est chiffr\u00e9 ;\n   d) opportunite: rien de tout cela \u2014 le poste est d\u00e9clar\u00e9 mais pas travaill\u00e9. */\nfunction etatTuile(poste){\n  if(!poste) return \"opportunite\";\n  if(poste.gainActe > 0) return \"gagne\";\n  if(poste.essaiOuvert) return \"encours\";\n  if(poste.cibleCPP !== null && poste.cibleCPP > 0) return \"aChiffrer\";\n  return \"opportunite\";\n}\n\n/* \u2550\u2550\u2550 v4.59.0 \u2014 gainLigne : la ligne ENTI\u00c8RE, rollup de ses postes (Q6-B) \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   La tuile-ligne de l'\u00e9cran d'accueil (maquette Hermes, Benjamin : option B) lit\n   TOUT ici \u2014 elle ne recalcule rien. La r\u00e8gle D3 s'applique au niveau au-dessus :\n   ce rollup consomme gainPoste()/etatTuile()/prochaineEtapePoste()/pieceCPPComplet(),\n   les sources d\u00e9j\u00e0 test\u00e9es, et n'invente aucun second agr\u00e9gat.\n\n   Le co\u00fbt pi\u00e8ce est \u00c9TIQUET\u00c9 (d\u00e9cision Benjamin, Q6-B) : c'est celui de la r\u00e9f\u00e9rence\n   DOMINANTE de la ligne \u2014 la plus gros volume. Un co\u00fbt multi-r\u00e9f\u00e9rences sans \u00e9tiquette\n   serait un chiffre mensonger (\u00a73.5). L'\u00e9tat de la ligne n'est PAS d\u00e9cid\u00e9 ici : la\n   fonction rend les comptages factuels, la pastille se choisira au tour UI de la\n   carte, devant Benjamin, avec des captures \u2014 on ne d\u00e9duit pas en silence ce qui\n   se pr\u00e9sente.\n\n   Rend { ligne, postes[t], gainActe, gainProjete, etats{gagne,encours,aChiffrer,\n   opportunite}, nonChiffres, refDominante, coutPiece, etapes[{opCode,etat,texte}] } */\nfunction gainLigne(ligne, lignesSeptFons){\n  const postes = (postesLigne(ligne, lignesSeptFons) || []).map(p => {\n    const poste = gainPoste(ligne, p.code, lignesSeptFons);\n    const etat = etatTuile(poste);\n    return { poste, etat, refs: poste.refs || [],\n             etape: prochaineEtapePoste({ poste, etat, refs: poste.refs || [] }) };\n  });\n  const etats = { gagne: 0, encours: 0, aChiffrer: 0, opportunite: 0 };\n  let gainActe = 0, gainProjete = 0, nonChiffres = 0;\n  postes.forEach(t => {\n    etats[t.etat]++;\n    gainActe += t.poste.gainActe || 0;\n    gainProjete += t.poste.gainProjete || 0;\n    nonChiffres += t.poste.nonChiffres || 0;\n  });\n  /* la dominante de la ligne : le plus gros volume ANNUEL \u2014 m\u00eame crit\u00e8re que la\n     carte pour la dominante d'un poste (4.51.2), un niveau au-dessus */\n  const refDominante = (ligne.references || []).slice()\n    .sort((a, b) => (volumeAnnuel(b, (b.ops || [])[0] && b.ops[0].config) || 0)\n                  - (volumeAnnuel(a, (a.ops || [])[0] && a.ops[0].config) || 0))[0] || null;\n  /* v4.60 \u2014 le volume de la dominante, rendu avec elle : la tuile n'a pas \u00e0\n     recalculer (D3), et \u00ab pas de volume \u00bb devient un cas LISIBLE (Q10) au lieu\n     du choix arbitraire silencieux signal\u00e9 par Hermes au Tour 13. */\n  const volumeDominante = refDominante\n    ? volumeAnnuel(refDominante, (refDominante.ops || [])[0] && refDominante.ops[0].config) : null;\n  const coutPiece = refDominante ? pieceCPPComplet(refDominante, ligne) : null;\n  const etapes = postes.map(t => ({ opCode: t.poste.opCode, etat: t.etat, texte: t.etape }));\n  return { ligne, postes, gainActe, gainProjete, etats, nonChiffres, refDominante, volumeDominante, coutPiece, etapes };\n}\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   v4.55.0 \u2014 LE CLASSEUR MATIS, source de production R\u00c9ELLE (option C de l'analyse\n   du 29/09). R\u00e8gle constitution \u00a74.2 : rien ne quitte le poste \u2014 la lecture est\n   OPTIONNELLE, manuelle, sur un fichier que l'utilisateur choisit lui-m\u00eame.\n\n   Ce que ce bloc apporte, et pourquoi c'est un changement de nature :\n   \u00b7 jusqu'ici la production \u00e9tait un SC\u00c9NARIO d\u00e9guis\u00e9 (un bool\u00e9en `baseline` pos\u00e9\n     sur un sc\u00e9nario d'essai) ; chaque calcul cherchait \u00ab \u2605 d'abord, excel en repli \u00bb ;\n   \u00b7 le classeur de Matis donne la production R\u00c9ELLE, chiffr\u00e9e, par couple\n     ligne \u00d7 r\u00e9f\u00e9rence (volume en case B1 de chaque feuille \u00ab Cout pi\u00e8ce \u00bb), avec\n     le CPP r\u00e9el consomm\u00e9 et l'\u00e9cart \u00e0 la th\u00e9orie ;\n   \u00b7 donc : le sc\u00e9nario-\u2605 reste la R\u00c9F\u00c9RENCE DE COMPARAISON (son r\u00f4le historique,\n     intact), et la production r\u00e9elle devient une DONN\u00c9E \u00e0 part, importable, dat\u00e9e.\n\n   D\u00e9cision C (Benjamin) : on importe et on MESURE l'\u00e9cart th\u00e9orie/r\u00e9el avant de\n   d\u00e9cider si la production doit devenir une entit\u00e9 de premier niveau. Rien ici ne\n   change le format des donn\u00e9es : c'est un bloc d'observation, pas une migration.\n\n   Un .xlsm est une archive ZIP. On lit son XML directement \u2014 aucune biblioth\u00e8que,\n   aucun r\u00e9seau, rien \u00e0 installer. La d\u00e9compression utilise DecompressionStream\n   (natif Chrome/Edge, donc \u00ab un seul fichier \u00bb reste vrai).\n   \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\nfunction _xmlUnescape(s){\n  return String(s).replace(/&lt;/g, \"<\").replace(/&gt;/g, \">\")\n    .replace(/&quot;/g, '\"').replace(/&apos;/g, \"'\")\n    .replace(/&#(\\d+);/g, (_, n) => String.fromCharCode(parseInt(n, 10)))\n    .replace(/&amp;/g, \"&\");\n}\n\n/* d\u00e9compresse une entr\u00e9e ZIP (deflate-raw ou stored) \u2192 Uint8Array */\nasync function _zipRead(ent){\n  if(ent.method === 0) return ent.data;\n  if(typeof DecompressionStream === \"undefined\"){\n    throw new Error(\"Ce navigateur ne sait pas lire un classeur Excel. Utilise Chrome ou Edge.\");\n  }\n  const ds = new DecompressionStream(\"deflate-raw\");\n  const buf = await new Response(new Blob([ent.data]).stream().pipeThrough(ds)).arrayBuffer();\n  return new Uint8Array(buf);\n}\n\n/* inventaire des entr\u00e9es ZIP + acc\u00e8s par nom de feuille */\nasync function _zipOpen(file){\n  const bytes = new Uint8Array(await file.arrayBuffer());\n  const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);\n  const u16 = o => dv.getUint16(o, true), u32 = o => dv.getUint32(o, true);\n  let eocd = -1;\n  for(let i = bytes.length - 22; i >= Math.max(0, bytes.length - 66000); i--){\n    if(u32(i) === 0x06054b50){ eocd = i; break; }\n  }\n  if(eocd < 0) throw new Error(\"Ce fichier n'est pas un classeur Excel (archive illisible).\");\n  const count = u16(eocd + 10);\n  let off = u32(eocd + 16);\n  const entries = {};\n  for(let i = 0; i < count; i++){\n    if(u32(off) !== 0x02014b50) break;\n    const method = u16(off + 10), csize = u32(off + 20);\n    const nlen = u16(off + 28), elen = u16(off + 30), clen = u16(off + 32);\n    const lho = u32(off + 42);\n    const name = new TextDecoder(\"utf-8\").decode(bytes.subarray(off + 46, off + 46 + nlen));\n    const lnlen = u16(lho + 26), lelen = u16(lho + 28);\n    const start = lho + 30 + lnlen + lelen;\n    entries[name] = { method, csize, data: bytes.subarray(start, start + csize) };\n    off += 46 + nlen + elen + clen;\n  }\n  return entries;\n}\n\n/* les cha\u00eenes partag\u00e9es (le classeur les utilise pour tous les libell\u00e9s) */\nasync function _xlSharedStrings(entries){\n  const key = Object.keys(entries).find(k => /^xl\\/sharedStrings\\.xml$/.test(k));\n  if(!key) return [];\n  const xml = new TextDecoder(\"utf-8\").decode(await _zipRead(entries[key]));\n  const out = [];\n  const re = /<si>([\\s\\S]*?)<\\/si>/g;\n  let m;\n  while((m = re.exec(xml))){\n    out.push(_xmlUnescape([...m[1].matchAll(/<t[^>]*>([\\s\\S]*?)<\\/t>/g)].map(x => x[1]).join(\"\")));\n  }\n  return out;\n}\n\n/* <c r=\"A1\" t=\"s\"><v>3</v></c> \u2192 { A1: valeur } */\nfunction _xlCells(xml, shared){\n  const cells = {};\n  const re = /<c r=\"([A-Z]+\\d+)\"([^>]*?)(?:\\/>|>([\\s\\S]*?)<\\/c>)/g;\n  let m;\n  while((m = re.exec(xml))){\n    const ref = m[1], attrs = m[2] || \"\", inner = m[3] || \"\";\n    const t = (attrs.match(/t=\"([^\"]+)\"/) || [])[1];\n    if(t === \"inlineStr\"){\n      cells[ref] = _xmlUnescape([...inner.matchAll(/<t[^>]*>([\\s\\S]*?)<\\/t>/g)].map(x => x[1]).join(\"\"));\n      continue;\n    }\n    const vm = inner.match(/<v>([\\s\\S]*?)<\\/v>/);\n    if(!vm) continue;\n    const raw = _xmlUnescape(vm[1]);\n    if(t === \"s\") cells[ref] = shared[parseInt(raw, 10)] ?? \"\";\n    else if(t === \"b\") cells[ref] = raw === \"1\";\n    else { const n = parseFloat(raw); cells[ref] = isNaN(n) ? raw : n; }\n  }\n  return cells;\n}\n\n/* le lien nom-de-feuille \u2192 fichier XML (workbook.xml + rels) */\nasync function _xlSheetMap(entries){\n  const wbKey = \"xl/workbook.xml\", relKey = \"xl/_rels/workbook.xml.rels\";\n  if(!entries[wbKey] || !entries[relKey]) return {};\n  const wb = new TextDecoder(\"utf-8\").decode(await _zipRead(entries[wbKey]));\n  const rels = new TextDecoder(\"utf-8\").decode(await _zipRead(entries[relKey]));\n  const relMap = {};\n  for(const m of rels.matchAll(/<Relationship[^>]*Id=\"([^\"]+)\"[^>]*Target=\"([^\"]+)\"[^>]*\\/?>/g)){\n    relMap[m[1]] = m[2].replace(/^\\/?xl\\//, \"\").replace(/^\\.\\//, \"\");\n  }\n  const map = {};\n  for(const m of wb.matchAll(/<sheet[^>]*name=\"([^\"]+)\"[^>]*r:id=\"([^\"]+)\"[^>]*\\/?>/g)){\n    const target = relMap[m[2]];\n    if(target) map[_xmlUnescape(m[1])] = \"xl/\" + target;\n  }\n  return map;\n}\n\n/* une feuille \u00ab Cout pi\u00e8ce \u00bb = un couple ligne \u00d7 r\u00e9f\u00e9rence */\nfunction _matisFeuille(nomFeuille, cells){\n  const m = nomFeuille.match(/^Co[u\u00fb]t\\s+pi[e\u00e8]ce\\s+([EH])(\\d)\\s+(.+)$/i);\n  if(!m) return null;\n  const numOp = r => String(r || \"\").trim();\n  const outils = [];\n  for(let row = 4; row <= 140; row++){\n    const numOutil = numOp(cells[\"A\" + row]);\n    if(!numOutil) continue;\n    const op = numOp(cells[\"B\" + row]);\n    const mOp = op.match(/^OP\\s?(\\d+)/i);\n    if(!mOp) continue;                     // ligne de garde : seuls les outils comptent\n    const f = k => { const v = parseFloat(cells[k + row]); return isNaN(v) ? null : v; };\n    /* v4.73 (Tour 34, passation Tour 33) \u2014 une ligne Excel = UN LOGEMENT : la\n       connaissance m\u00e9tier (un porte-outil T513 porte les positions D1/D2 ; un\n       MABEC = une plaquette = un logement) n'est plus perdue \u00e0 la lecture.\n       La ligne garde TOUS ses champs (MABEC, prix, ar\u00eates, DDV, CPP) \u2014 rien\n       n'est fabriqu\u00e9. La s\u00e9paration porte-outil/position est faite par\n       matisPorteOutilPosition(), la fusion par reparerOutilsD1D2() en sortie. */\n    /* v4.74.2 (Benjamin n\u00b04) \u2014 l'en-t\u00eate du classeur est explicite :\n       A = \u00ab N\u00b0 d'outil / N\u00b0 correcteur \u00bb, C = \u00ab ISO \u00bb, D = \u00ab MABEC \u00bb.\n       L'ISO va dans logement.ref (la r\u00e9f\u00e9rence plaquette) \u2014 il \u00e9tait lu\n       puis jet\u00e9 dans \u00ab article \u00bb \u2014 et le correcteur (D1/D2 de la colonne A)\n       dans outil.correcteur. */\n    const iso = numOp(cells[\"C\" + row]);\n    const { position } = matisPorteOutilPosition(numOutil);\n    outils.push({\n      numero: numOutil, opCode: \"OP\" + mOp[1],\n      correcteur: position || \"\", article: iso, mabec: numOp(cells[\"D\" + row]),\n      aretes: f(\"F\"), prix: f(\"G\"), ddv: f(\"H\"),\n      cppTheorique: f(\"I\"), qteTheorique: f(\"J\"),\n      coutReelAnnuel: f(\"L\"), cppReel: f(\"M\"), qteReelle: f(\"N\"), ecart: f(\"O\"),\n      logements: [ {\n        nom: \"logement 1\",\n        ref: iso,\n        mabec: numOp(cells[\"D\" + row]), article: iso,\n        prix: f(\"G\"), aretes: f(\"F\"), charniere: f(\"H\")\n      } ]\n    });\n  }\n  const prod = parseFloat(cells[\"B1\"]);\n  return {\n    codeLigne: m[1].toUpperCase() + m[2],\n    ref: m[3].trim(),\n    refComplete: (numOp(cells[\"C2\"])) || m[3].trim(),\n    production: isNaN(prod) ? null : prod,\n    outils: reparerOutilsD1D2(outils)\n  };\n}\n\n/* \u2550\u2550\u2550 La fonction pure : le r\u00e9capitulatif, testable sans fichier \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   Elle prend les feuilles d\u00e9j\u00e0 lues et rend ce que l'\u00e9cran affiche. Aucun acc\u00e8s\n   disque ici \u2014 c'est ce qui permet de la tester (constitution : source unique). */\nfunction matisRecap(feuilles){\n  const couples = {};\n  feuilles.forEach(f => {\n    if(!f) return;\n    const key = f.codeLigne + \"\u00b7\" + f.ref;\n    if(!couples[key]) couples[key] = { key, codeLigne: f.codeLigne, ref: f.ref, refComplete: f.refComplete,\n      production: 0, aProduction: false, outils: [], cppTheorique: 0, cppReel: 0 };\n    const c = couples[key];\n    if(f.production !== null && f.production > 0){ c.production = f.production; c.aProduction = true; }\n    c.outils = c.outils.concat(f.outils);\n  });\n  const liste = Object.keys(couples).map(k => couples[k]);\n  liste.forEach(c => {\n    c.outils.forEach(o => {\n      if(o.cppTheorique) c.cppTheorique += o.cppTheorique;\n      if(o.cppReel) c.cppReel += o.cppReel;\n    });\n    c.ecart = (c.cppReel && c.cppTheorique) ? c.cppReel - c.cppTheorique : null;\n    c.ecartPct = (c.ecart !== null && c.cppTheorique) ? (c.ecart / c.cppTheorique) * 100 : null;\n    c.coutAnnuelReel = c.aProduction && c.cppReel ? c.cppReel * c.production : null;\n    c.coutAnnuelTheorique = c.aProduction && c.cppTheorique ? c.cppTheorique * c.production : null;\n    c.gapAnnuel = (c.coutAnnuelReel !== null && c.coutAnnuelTheorique !== null)\n      ? c.coutAnnuelReel - c.coutAnnuelTheorique : null;\n  });\n  return liste.sort((a, b) => (b.production || 0) - (a.production || 0));\n}\n\n/* l'\u00e9cart, dit en atelier \u2014 jamais un chiffre nu sans sa raison (constitution \u00a73.5) */\nfunction libelleEcartMatis(c){\n  if(c.ecart === null) return \"non mesurable \u2014 pas de CPP r\u00e9el relev\u00e9 sur ce couple\";\n  if(Math.abs(c.ecart) < 0.0005) return \"consommation conforme au budget-outillage\";\n  if(c.ecart > 0) return `surconsommation de ${fmt(Math.abs(c.ecart), 4)} \u20ac/pi\u00e8ce`;\n  return `sous-consommation de ${fmt(Math.abs(c.ecart), 4)} \u20ac/pi\u00e8ce`;\n}\n\n/* \u2550\u2550\u2550 La lecture du fichier (asynchrone, manuelle, locale) \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\nasync function matisLireClasseur(file){\n  const entries = await _zipOpen(file);\n  const shared = await _xlSharedStrings(entries);\n  const map = await _xlSheetMap(entries);\n  const feuilles = [];\n  for(const nom of Object.keys(map)){\n    if(!entries[map[nom]]) continue;\n    const xml = new TextDecoder(\"utf-8\").decode(await _zipRead(entries[map[nom]]));\n    const f = _matisFeuille(nom, _xlCells(xml, shared));\n    if(f) feuilles.push(f);\n  }\n  return { fichier: file.name, luLe: new Date().toISOString().slice(0, 10),\n           feuilles, couples: matisRecap(feuilles) };\n}\n\n\n/* \u2550\u2550\u2550 L'\u00c9CRAN \u2014 le rendu de la mesure, et son ouverture \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\n\n/* le r\u00e9sultat de la derni\u00e8re lecture : en m\u00e9moire seulement, JAMAIS \u00e9crit dans\n   les donn\u00e9es du suivi. C'est une observation, pas un import (option C). */\nlet matisLecture = null;\n\n/* le couple \u00ab ligne \u00d7 r\u00e9f\u00e9rence \u00bb du classeur, rapproch\u00e9 de la ligne de l'outil\n   quand elle existe. Le classeur dit \u00ab E1 \u00bb, l'outil dit \u00ab EMAG 1 \u00bb : le\n   rapprochement est explicite et visible, jamais devin\u00e9 en silence. */\nconst MATIS_LIGNE_OUTIL = { E1: \"EMAG 1\", E2: \"EMAG 2\", E3: \"EMAG 3\", H: \"HESSAPP\" };\n\nfunction matisRapproche(c){\n  const nomLigne = MATIS_LIGNE_OUTIL[c.codeLigne] || c.codeLigne;\n  const lg = lignes.find(l => (l.nom || \"\").toUpperCase() === nomLigne.toUpperCase());\n  const ref = lg ? lg.references.find(r => (r.nom || \"\").toUpperCase().includes(String(c.ref).split(\" \")[0].toUpperCase())) : null;\n  return { nomLigne, ligneId: lg ? lg.id : null, referenceId: ref ? ref.id : null, ref, ligne: lg || null };\n}\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   v4.71.0 \u2014 LA R\u00c9PARATION DES OUTILS D\u00c9J\u00c0 SAISIS EN DOUBLE\n   \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   Benjamin, 30/09 : \u00ab encore pas r\u00e9gl\u00e9 le probl\u00e8me des logements \u00bb. Les\n   garde-fous prot\u00e8gent la saisie \u00e0 venir ; ils ne r\u00e9parent rien. Or les\n   doublons sont D\u00c9J\u00c0 dans les sc\u00e9narios.\n\n   Fonction PURE : elle rend un nouveau tableau, ne modifie aucune donn\u00e9e, et\n   n'est jamais appel\u00e9e d'elle-m\u00eame. L'atelier la d\u00e9clenche, il voit le\n   r\u00e9sultat, il accepte ou il refuse (constitution \u00a73.1 \u2014 on ne corrige jamais\n   quelqu'un contre son gr\u00e9, et \u00a73.2 \u2014 rien n'est supprim\u00e9 en silence).\n\n   Ce qu'elle fait, et RIEN D'AUTRE :\n   \u00b7 regroupe les outils dont la CL\u00c9 de porte-outil est identique ;\n   \u00b7 donne \u00e0 chaque logement le nom de sa POSITION (D1, D2\u2026) ;\n   \u00b7 un logement encore provisoire qui n'a re\u00e7u aucune position prend le\n     num\u00e9ro de la position LIBRE la plus basse \u2014 il ne dispara\u00eet pas ;\n   \u00b7 MABEC, prix, ar\u00eates, analyses, mesures et sc\u00e9narios voyagent INTACTS.\n   Elle ne fusionne JAMAIS deux outils de cl\u00e9s diff\u00e9rentes, et ne touche\n   JAMAIS \u00e0 un outil qui a d\u00e9j\u00e0 ses positions. */\n/* v4.77.0 \u2014 deux corrections sur les DONN\u00c9ES de Benjamin, avant tout regroupement.\n\n   CAS 1 \u2014 \u00ab T2D1 \u00bb, \u00ab T5D1 \u00bb. Le porte-outil et le correcteur sont coll\u00e9s dans le\n   num\u00e9ro, sans espace. matisPorteOutilPosition() sait d\u00e9j\u00e0 les s\u00e9parer ; on\n   l'applique ICI, sur les donn\u00e9es, en \u00e9crivant le correcteur dans le champ\n   `correcteur` de l'outil ET en nommant le logement. L'affichage du num\u00e9ro\n   devient propre (\u00ab T2 \u00bb) : c'est ce que l'atelier appelle l'outil.\n\n   CAS 2 \u2014 \u00ab T1 \u00bb avec SEPT logements du m\u00eame nom. Un merge\n   sans le vouloir a empil\u00e9 des logements de m\u00eame nom dans un seul outil : 4 + 2\n   + 1. Un outil ne peut pas avoir deux fois le m\u00eame correcteur. On r\u00e9duit en\n   gardant le logement le plus RENSEIGN\u00c9 \u2014 jamais le premier arriv\u00e9, qui peut \u00eatre\n   le plus vide \u2014 et on ne signale rien d'autre : les donn\u00e9es du \u00e9cart\u00e9 ne sont\n   pas perdues, elles sont simplement redondantes avec la conserv\u00e9e. */\nfunction renseignerCorrecteur(outil){\n  const o = outil;\n  if(!o) return o;\n  /* v4.77.0 \u2014 Benjamin, 01/10, sur ses donn\u00e9es : \u00ab un outil appel\u00e9 T2D1 alors que\n     l'outil est T2 et le correcteur D1, non renseign\u00e9 dans le bon champ \u00bb.\n\n     Le NUM\u00c9RO garde la valeur \u00e9crite \u2014 c'est le contrat de l'outil (les tests le\n     verrouillent), et l'atelier reconna\u00eet son propre num\u00e9ro. Ce qui manquait,\n     c'est le champ `correcteur`, celui que Matis remplit et qu'on veut voir.\n\n     On le remplit donc, depuis la position, qu'elle vienne du num\u00e9ro\n     (\u00ab T2D1 \u00bb, \u00ab T2 D1 \u00bb) ou des logements d\u00e9j\u00e0 nomm\u00e9s. Et si l'outil n'a\n     aucun logement, on lui en cr\u00e9e un qui porte ce correcteur : sans lui,\n     l'outil n'a pas de point de d\u00e9part, et l'\u00e9cran ne peut rien afficher. */\n  const position = positionDeOutil(o);\n  if(!position) return o;\n  const sortie = Object.assign({}, o);\n  const deja = String(o.correcteur || \"\").trim();\n  if(!deja){\n    sortie.correcteur = position;\n  } else if(!deja.match(/^D\\d+$/)){\n    /* plusieurs correcteurs d\u00e9j\u00e0 not\u00e9s (\u00ab D1, D2 \u00bb) : on ne rajoute pas un\n       doublon si la position y est d\u00e9j\u00e0. */\n    const liste = deja.split(/[,;\\s]+/).map(x => x.trim().toUpperCase()).filter(Boolean);\n    if(!liste.includes(position)) sortie.correcteur = deja + \", \" + position;\n  }\n  const logs = (o.logements || []).map(l => Object.assign({}, l));\n  if(!logs.length){\n    sortie.logements = [normalizeLogement({ nom: position })];\n  } else if(!logs.some(l => String(l.nom || \"\").trim().toUpperCase() === position)){\n    /* R\u00e8gle v4.71.0, appliqu\u00e9e aussi ici : si l'outil ne porte QU'UN logement et\n       qu'il est encore au nom de D\u00c9FAUT (\u00ab Logement 1 \u00bb), c'est LUI qui devient\n       la position. On ne cr\u00e9e pas un deuxi\u00e8me logement \u00e0 c\u00f4t\u00e9 d'un provisoire :\n       ce serait exactement le fant\u00f4me que Benjamin a signal\u00e9. Un logement au nom\n       d'atelier en revanche n'est pas touch\u00e9 \u2014 il dit plus que la position. */\n    const defaut = /^\\s*logement\\s*\\d*\\s*$/i;\n    const tousProvisoires = logs.every(l => defaut.test(String(l.nom || \"\")));\n    if(logs.length === 1 && tousProvisoires){\n      logs[0] = Object.assign({}, logs[0], { nom: position });\n      sortie.logements = logs;\n    } else {\n      logs.push(normalizeLogement({ nom: position }));\n      sortie.logements = logs;\n    }\n  }\n  return sortie;\n}\n\n/* R\u00e9duit les logements de M\u00caME nom \u00e0 un seul. On garde le plus renseign\u00e9, et \u00e0\n   \u00e9galit\u00e9 le premier : on ne pr\u00e9f\u00e8re jamais \u00ab le plus r\u00e9cent \u00bb, car l'outil\n   n'a aucune date de saisie par logement, et en inventer une serait exactement\n   le genre de donn\u00e9e fabriquee qu'on refuse partout ailleurs. */\nfunction dedoublonnerLogements(outil){\n  const logs = (outil && outil.logements) || [];\n  if(logs.length < 2) return outil;\n  const compte = logs.reduce((a, l) => {\n    const k = String(l.nom || \"\").trim().toUpperCase();\n    a[k] = (a[k] || 0) + 1; return a;\n  }, {});\n  if(!Object.values(compte).some(n => n > 1)) return outil;\n  const CHAMPS = [\"mabec\",\"codeArticle\",\"prix\",\"charniere\",\"ref\",\"vc\",\"f\",\n                   \"kappaR\",\"rayonBec\",\"apPiste\",\"tempsCoupe\",\"tempsDeplacement\"];\n  const rempli = l => CHAMPS.reduce((n, c) =>\n    n + (l[c] !== undefined && l[c] !== null && l[c] !== \"\" && l[c] !== 0 ? 1 : 0), 0);\n  const vus = new Set();\n  const gardes = [];\n  logs.forEach(l => {\n    const k = String(l.nom || \"\").trim().toUpperCase();\n    if(!vus.has(k)){ vus.add(k); gardes.push(l); return; }\n    const deja = gardes.find(g => String(g.nom || \"\").trim().toUpperCase() === k);\n    /* on compl\u00e8te le logement d\u00e9j\u00e0 gard\u00e9 avec ce que celui-ci apporte de plus :\n       on ne remplace jamais une donn\u00e9e par une case vide. */\n    if(rempli(l) > rempli(deja)){\n      for(const c of CHAMPS)\n        if((deja[c] === undefined || deja[c] === \"\" || deja[c] === 0) && l[c] !== undefined && l[c] !== \"\")\n          deja[c] = l[c];\n    }\n  });\n  return Object.assign({}, outil, { logements: gardes },\n    { _fusionReparee: outil._fusionReparee, nbOutils: outil.nbOutils });\n}\n\n/* v4.77.0 \u2014 O\u00f9 est la POSITION d'un outil ? Elle peut vivre \u00e0 trois endroits,\n   selon l'\u00e2ge de la donn\u00e9e \u2014 et c'est exactement pour \u00e7a que la r\u00e9paration ne\n   voyait plus rien :\n\n   1. dans le num\u00e9ro, tant que la saisie est brute      : \u00ab T543 D1 \u00bb\n   2. dans le champ `correcteur`, une fois separ\u00e9        : T543 / correcteur D1\n   3. dans le nom des logements, quand le champ est vide : T543 / logement \u00ab D1 \u00bb\n\n   renseignerCorrecteur() (ci-dessus) fait passer la donn\u00e9e du (1) au (2). Si le\n   regroupement continuait de lire le (1) seul, il ne verrait PLUS jamais rien :\n   les deux outils devenaient \u00ab T543 \u00bb et \u00ab T543 \u00bb, sans position, et la fusion\n   ne se d\u00e9clenchait plus. On lit donc les trois, dans cet ordre, et c'est le\n   (2) qui gagne quand il est rempli \u2014 parce qu'il a \u00e9t\u00e9 \u00e9crit \u00e0 la main par\n   l'atelier, et qu'il fait autorit\u00e9 sur une d\u00e9duction. */\nfunction positionDeOutil(o){\n  const depuisNumero = matisPorteOutilPosition(o && o.numero).position;\n  if(depuisNumero) return depuisNumero;\n  const c = String((o && o.correcteur) || \"\").trim().toUpperCase();\n  if(c.match(/^D\\d+$/)) return c;\n  /* plusieurs correcteurs dans le champ (\u00ab D1, D2 \u00bb) : ce n'est pas UNE\n     position, c'est un outil d\u00e9j\u00e0 group\u00e9 \u2014 on ne le d\u00e9double pas. */\n  if(c) return null;\n  const positions = ((o && o.logements) || [])\n    .map(l => String(l.nom || \"\").trim().toUpperCase())\n    .filter(n => n.match(/^D\\d+$/));\n  return positions.length === 1 ? positions[0] : null;\n}\n\nfunction reparerOutilsD1D2(outils){\n  const liste = (outils || []).map(renseignerCorrecteur);\n  /* v4.77.0 \u2014 un seul outil n'a rien \u00e0 regrouper, mais il peut encore avoir des\n     logements en double : c'est EXACTEMENT le cas \u00ab T1 avec 7 logements \u00bb. Le\n     retour rapidecourt-circuit\u00e9 le d\u00e9doublonnage et laissait le cas intact. */\n  if(liste.length < 2) return liste.map(dedoublonnerLogements);\n  const defaut = /^\\s*logement\\s*\\d*\\s*$/i;\n  /* v4.73 (Tour 34) \u2014 la cl\u00e9 d'identit\u00e9 d'un outil : les outils SAISIS ont un\n     id ; les lignes du LECTEUR du classeur n'en ont pas (chaque ligne Excel est\n     plate). Sans fallback, fusionnes.get(undefined) ne remplace rien et\n     consomme personne : l'outil fusionn\u00e9 \u00e9tait rendu DEUX FOIS (constat au\n     harnais, DIAG). D\u00e9clar\u00e9 AVANT tout usage (constat : TDZ). */\n  const cleId = o => o.id !== undefined ? o.id : \"__pos_\" + o.numero;\n  const groupes = new Map();\n  const autres = [];\n  for(const o of liste){\n    const porte = matisPorteOutilPosition(o.numero).porte;\n    const position = positionDeOutil(o);\n    const cle = matisClePorteOutil(porte);\n    /* Un outil sans position (\u00ab T543 \u00bb nu) est LAISSE TEL QUEL. On ne le verse\n       pas d'office dans le groupe : il peut \u00eatre un vrai outil \u00e0 lui seul, et\n       fusionner \u00e0 l'aveugle d\u00e9truirait une distinction r\u00e9elle. Il est en\n       revanche SIGNAL\u00c9 dans le rapport \u2014 c'est souvent lui, le parent, et\n       c'est \u00e0 l'atelier de trancher (constitution \u00a73.1). */\n    if(!position){ autres.push(o); continue; }\n    if(!groupes.has(cle)) groupes.set(cle, []);\n    groupes.get(cle).push(o);\n  }\n  const out = autres.slice();\n  const orphelins = [];\n  const fusionnes = new Map();   /* id du 1er outil du groupe -> outil fusionn\u00e9 */\n  const consomme = new Set();\n  for(const [cle, groupe] of groupes){\n    if(groupe.length < 2){ if(!out.includes(groupe[0])) out.push(groupe[0]); continue; }\n    /* le num\u00e9ro d'affichage : celui qui a le plus de lettres, sinon le premier.\n       \u00ab T 513 D1 \u00bb gagne sur \u00ab T513 D1 \u00bb \u2014 c'est la forme de l'atelier. */\n    let numero = null, melhor = -1;\n    for(const o of groupe){\n      const n = String(o.numero || \"\");\n      const nPortee = n.replace(/\\s*[Dd]\\d*\\s*$/, \"\").trim();\n      const score = nPortee.replace(/\\s/g, \"\").length * 10 + (nPortee.includes(\" \") ? 1 : 0);\n      if(score > melhor){ melhor = score; numero = nPortee; }\n    }\n    const logements = [];\n    for(const o of groupe){\n      const position = positionDeOutil(o);\n      for(const l of (o.logements || [])){\n        const copie = Object.assign({}, l);\n        const nom = String(l.nom || \"\").trim();\n        /* un logement d\u00e9j\u00e0 nomm\u00e9 garde son nom d'atelier (\u00ab Bol \u00bb, \u00ab Piste \u00bb) :\n           il porte une information que la position ne dit pas.\n           un logement provisoire, lui, prend la position de son outil. */\n        if(defaut.test(nom)) copie.nom = position;\n        logements.push(copie);\n      }\n    }\n    /* un provisoire rest\u00e9 sans position n'est pas perdu : il\n       re\u00e7oit la plus petite position libre. On ne supprime JAMAIS une ligne. */\n    for(const o of groupe){\n      const position = positionDeOutil(o);\n      if(position) continue;\n      for(const l of (o.logements || [])){\n        const copie = Object.assign({}, l);\n        if(defaut.test(String(l.nom || \"\"))){\n          let n = 1;\n          while(logements.some(x => x.nom === \"D\" + n)) n++;\n          copie.nom = \"D\" + n;\n        }\n        logements.push(copie);\n      }\n    }\n    /* La fusion appara\u00eet \u00e0 la place du PREMIER outil du groupe : l'atelier\n       retrouve ses outils dans l'ordre o\u00f9 il les a saisis. Une r\u00e9paration qui\n       r\u00e9ordonne la liste pourrais le faire chercher au mauvais endroit. */\n    /* v4.73 (Tour 34) \u2014 la cl\u00e9 d'identit\u00e9 : les outils SAISIS ont un id ; les\n       lignes du LECTEUR du classeur n'en ont pas (chaque ligne Excel est plate).\n       Sans fallback, fusionnes.get(undefined) ne remplace rien et consomme\n       personne : l'outil fusionn\u00e9 \u00e9tait rendu DEUX FOIS (constat au harnais). */\n    /* v4.74.2 \u2014 le correcteur : les positions du groupe (\u00ab D1 \u00bb, \u00ab D2 \u00bb\u2026),\n       restitu\u00e9es dans le champ Correcteur de l'outil \u2014 c'est le mot de\n       l'atelier, Benjamin : \u00ab le correcteur, c'est la ref apr\u00e8s l'outil \u00bb. */\n    const correcteurs = groupe.map(o => matisPorteOutilPosition(o.numero).position).filter(Boolean);\n    /* l'ISO : un logement fr\u00e8re du m\u00eame MABEC avec une ref qui n'est pas un\n       MABEC la conna\u00eet (sc\u00e9narios \u00ab base excel \u00bb) \u2014 on la rapporte au lieu de\n       laisser le champ vide. Best effort : absent, ref reste vide. */\n    const isoParMabec = {};\n    liste.forEach(o => (o.logements || []).forEach(lg => {\n      const m = String(lg.mabec || \"\").replace(/\\s+/g, \" \").trim();\n      const r = String(lg.ref || \"\").trim();\n      if(m && r && !estCodeMabec(r) && !isoParMabec[m]) isoParMabec[m] = r;\n    }));\n    logements.forEach(lg => {\n      const m = String(lg.mabec || \"\").replace(/\\s+/g, \" \").trim();\n      if(m && !String(lg.ref || \"\").trim() && isoParMabec[m]) lg.ref = isoParMabec[m];\n    });\n    fusionnes.set(cleId(groupe[0]), { id: groupe[0].id, numero: numero, correcteur: correcteurs.join(\", \"),\n               logements: logements, position: \"\", nbOutils: groupe.length, _fusionReparee: true });\n    for(const o of groupe) consomme.add(cleId(o));\n    /* un outil NU de la m\u00eame cl\u00e9 (souvent le parent) est signal\u00e9, pas touch\u00e9 */\n    for(const o of autres){\n      if(matisClePorteOutil(o.numero) === cle)\n        orphelins.push('un outil \u00ab ' + o.numero + ' \u00bb sans position existe aussi : '\n          + '\u00e0 vous de dire s il est le parent ou un outil distinct');\n    }\n  }\n  /* On reconstruit dans l'ordre d'origine : chaque groupe remplac\u00e9 par son\n     outil fusionn\u00e9, \u00e0 la place de son PREMIER membre. Les autres membres sont\n     absorb\u00e9s. Une r\u00e9paration qui r\u00e9ordonnerait la liste pourrait faire\n     chercher un outil au mauvais endroit \u2014 et l'atelier ne le retrouverait pas. */\n  const ordre = [];\n  for(const o of liste){\n    const fusion = fusionnes.get(cleId(o));\n    if(fusion){ ordre.push(fusion); continue; }   /* 1er membre : \u00e0 sa place */\n    if(consomme.has(cleId(o))) continue;          /* membre absorb\u00e9 : dispara\u00eet */\n    if(!ordre.includes(o)) ordre.push(o);\n  }\n  /* v4.77.0 \u2014 en dernier, on r\u00e9duit les logements en double \u00c0 L'INT\u00c9RIEUR d'un\n     outil. C'est le cas \u00ab T1 avec 7 logements \u00bb : on ne peut pas avoir deux fois\n     le m\u00eame correcteur sur le m\u00eame porte-outil. */\n  const reduits = ordre.map(dedoublonnerLogements);\n  reduits._orphelins = orphelins;\n  reduits._reduits = ordre.length - reduits.length;\n  return reduits;\n}\n\n/* Ce que la r\u00e9paration a chang\u00e9, en mots \u2014 pas en nombre. L'\u00e9cran doit dire\n   ce qu'il va advenir, sinon on demande une confiance aveugle. */\nfunction reparerOutilsRapport(avant, apres){\n  const lignes = [];\n  const a = (avant || []).filter(o => o._fusionReparee);\n  const b = (apres || []).filter(o => o._fusionReparee);\n  for(const o of b){\n    const n = (o.nbOutils || 1);\n    const parts = (o.logements || []).map(l => String(l.nom || \"\").toUpperCase());\n    lignes.push(n + \" outils \u00ab \" + o.numero + \" \u00bb meetings en 1, avec \" +\n      parts.length + \" logements : \" + parts.join(\", \"));\n  }\n  return lignes;\n}\n\n/* \u2550\u2550\u2550 v4.74.0 \u2014 LA MIGRATION des outils D1/D2 s\u00e9par\u00e9s, dans les DONN\u00c9ES \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   Le lecteur du classeur a re\u00e7u la r\u00e8gle (4.73) ; les donn\u00e9es cr\u00e9\u00e9es AVANT\n   n'ont jamais \u00e9t\u00e9 migr\u00e9es : la composition de Benjamin montre encore\n   \u00ab T543 D1 \u00bb et \u00ab T543 D2 \u00bb en deux outils. On ne migre PAS en silence\n   (\u00a77.4 : les donn\u00e9es se touchent avec consentement et rapport) :\n   d\u00e9tection au chargement \u2192 bandeau avec les noms \u2192 correction \u00e0 la demande\n   \u2192 rapport \u2192 sauvegarde. La fonction reparerOutilsD1D2 fait le travail :\n   elle regroupe, nomme les logements par position, conserve tout, ne\n   fusionne pas un outil nu. */\n\n/* les sc\u00e9narios portant AU MOINS un groupe fusionnable (2+ outils m\u00eame porte,\n   avec position) \u2014 avec les noms, pour le bandeau */\nfunction detecterOutilsD1D2(scenarios){\n  const touches = [];\n  (scenarios || []).forEach(sc => {\n    const avant = (sc.outils || []);\n    const apres = reparerOutilsD1D2(avant);\n    const fusions = apres.filter(o => o._fusionReparee && (o.nbOutils || 1) > 1);\n    if(fusions.length){\n      touches.push({ sc, fusions, apres, completOnly: false });\n      return;\n    }\n    /* v4.74.3 \u2014 les outils D\u00c9J\u00c0 fusionn\u00e9s avant la 4.74.2 portent des logements\n       nomm\u00e9s par position (D1, D2\u2026) mais PAS de correcteur : d\u00e9tect\u00e9s aussi,\n       pour remplir le champ manquant. La correction est idempotente. */\n    const aCompleter = avant.filter(o => {\n      const c = String(o.correcteur || \"\").trim();\n      const positions = (o.logements || []).map(l => String(l.nom || \"\").trim().toUpperCase())\n        .filter(n => n.match(/^D\\d+$/));\n      return !c && positions.length >= 1;\n    });\n    if(aCompleter.length){\n      touches.push({ sc,\n        fusions: [{ numero: aCompleter[0].numero, nbOutils: aCompleter.length,\n                    logements: aCompleter.flatMap(o => o.logements || []) }],\n        apres: avant.map(o => {\n          const c = String(o.correcteur || \"\").trim();\n          if(c) return o;\n          const positions = (o.logements || []).map(l => String(l.nom || \"\").trim().toUpperCase())\n            .filter(n => n.match(/^D\\d+$/));\n          if(!positions.length) return o;\n          return Object.assign({}, o, { correcteur: positions.join(\", \") });\n        }),\n        completOnly: true });\n    }\n  });\n  return touches;\n}\n\n/* applique la correction sur TOUT le suivi (chaque sc\u00e9nario), rend le rapport\n   en mots \u2014 l'appelant sauvegarde et rend */\nfunction migrerOutilsD1D2(){\n  const lignesModifiees = new Set();\n  const rapport = [];\n  lignes.forEach(l => (l.references || []).forEach(r => (r.ops || []).forEach(op =>\n    (op.scenarios || []).forEach(sc => {\n      const avant = sc.outils || [];\n      const touches = detecterOutilsD1D2([ sc ]);\n      if(!touches.length) return;\n      /* reparerOutilsD1D2 rend une NOUVELLE liste (jamais la m\u00eame) : c'est elle\n         qui devient les outils du sc\u00e9nario \u2014 la mutation touche la donn\u00e9e r\u00e9elle */\n      sc.outils = touches[0].apres.map(o => {\n        const copie = Object.assign({}, o);\n        delete copie._fusionReparee; delete copie.nbOutils;  /* marqueurs de rapport, pas de donn\u00e9es */\n        return copie;\n      });\n      lignesModifiees.add(l.nom || \"?\");\n      if(touches[0].completOnly){\n        rapport.push((l.nom || \"?\") + \" \u00b7 \" + (r.nom || \"?\") + \" \u00b7 \" + (op.nom || \"?\") + \" : \"\n          + \"correcteur rempli (\" + touches[0].fusions.map(f => f.numero + \" \u2192 \" + (f.logements || []).map(l => l.nom).filter(n => n.match(/^D\\d+$/i)).join(\", \")).join(\", \") + \")\");\n        return;\n      }\n      touches[0].fusions.forEach(f => rapport.push(\n        (l.nom || \"?\") + \" \u00b7 \" + (r.nom || \"?\") + \" \u00b7 \" + (op.nom || \"?\") + \" : \"\n        + f.nbOutils + \" outils \u00ab \" + f.numero + \" \u00bb regroup\u00e9s en 1, avec \"\n        + (f.logements || []).length + \" logements : \" + (f.logements || []).map(l => l.nom).join(\", \")));\n    }))));\n  return { rapport, lignes: Array.from(lignesModifiees) };\n}\n\n/* \u2550\u2550\u2550 v4.74.1 \u2014 L'INVERSION ISO / MABEC, d\u00e9tect\u00e9e et permut\u00e9e \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   (Benjamin, retour d'usage n\u00b03 : \u00ab les codes MABEC du T543 sont dans le champ\n   r\u00e9f\u00e9rence plaquette \u00bb). Le mapping correct est document\u00e9 depuis l'import\n   4.72 : colonne ISO \u2192 logement.ref, colonne MABEC \u2192 logement.codeArticle.\n   Six logements des sc\u00e9narios d'atelier portaient le MABEC dans ref, sans\n   codeArticle. La permutation est S\u00dbRE \u00e0 d\u00e9tecter : le format MABEC\n   (Z000 455 182 \u2014 lettre + 3\u00d73 chiffres) ne ressemble \u00e0 aucun ISO\n   (SNGN090416T00520 SN60). \u00c0 la demande, comme la migration D1/D2. */\nfunction estCodeMabec(v){\n  return /^[A-Z]\\d{3}\\s\\d{3}\\s\\d{3}$/.test(String(v || \"\").replace(/\\s+/g, \" \").trim());\n}\n\nfunction detecterInversionMabec(scenarios){\n  const touches = [];\n  (scenarios || []).forEach(sc => {\n    const cibles = [];\n    (sc.outils || []).forEach(o => (o.logements || []).forEach(lg => {\n      const ref = String(lg.ref || \"\").trim(), ca = String(lg.codeArticle || \"\").trim(), mb = String(lg.mabec || \"\").trim();\n      /* cas 1 (4.74.1) : le MABEC dans ref, sans codeArticle \u2014 \u00e0 permuter ;\n         cas 2 (4.74.2, cons\u00e9quence de la correction) : le MABEC d\u00e9j\u00e0 remis\n         dans codeArticle mais ref VIDE alors que l'ISO est connu ailleurs\n         (base excel) \u2014 \u00e0 compl\u00e9ter. Les deux se corrigent au m\u00eame bouton. */\n      if(estCodeMabec(ref) && !ca && !mb) cibles.push(lg);\n      else if(!ref && ca && isoConnuPourMabec(ca)) cibles.push(lg);\n    }));\n    if(cibles.length) touches.push({ sc, cibles });\n  });\n  return touches;\n}\n\n/* l'ISO d'un MABEC, cherch\u00e9 dans tout le suivi (les sc\u00e9narios \u00ab base excel \u00bb\n   l'ont : ref = ISO, codeArticle = MABEC). null si inconnu. */\nfunction isoConnuPourMabec(mabec){\n  const cible = String(mabec || \"\").replace(/\\s+/g, \" \").trim();\n  if(!cible) return null;\n  let iso = null;\n  lignes.forEach(l => (l.references || []).forEach(rf => (rf.ops || []).forEach(op =>\n    (op.scenarios || []).forEach(sc => (sc.outils || []).forEach(ou =>\n      (ou.logements || []).forEach(lg => {\n        const ca = String(lg.codeArticle || \"\").replace(/\\s+/g, \" \").trim();\n        const mb = String(lg.mabec || \"\").replace(/\\s+/g, \" \").trim();\n        const ref = String(lg.ref || \"\").trim();\n        if((ca === cible || mb === cible) && ref && !estCodeMabec(ref) && !iso) iso = ref;\n      }))))));\n  return iso;\n}\n\nfunction migrerInversionMabec(){\n  const rapport = [];\n  lignes.forEach(l => (l.references || []).forEach(rf => (rf.ops || []).forEach(op =>\n    (op.scenarios || []).forEach(sc => {\n      const touches = detecterInversionMabec([ sc ]);\n      if(!touches.length) return;\n      touches[0].cibles.forEach(lg => {\n        const mabec = estCodeMabec(lg.ref) ? lg.ref : (String(lg.codeArticle || \"\").trim() || String(lg.mabec || \"\").trim());\n        if(estCodeMabec(lg.ref)) lg.ref = \"\";  /* cas 1 : le MABEC quitte ref */\n        lg.codeArticle = mabec;\n        /* v4.74.2 \u2014 l'ISO du m\u00eame MABEC est-il connu ailleurs (base excel) ? */\n        let iso = isoConnuPourMabec(mabec);\n        lignes.forEach(l2 => (l2.references || []).forEach(r2 => (r2.ops || []).forEach(o2 =>\n          (o2.scenarios || []).forEach(sc2 => (sc2.outils || []).forEach(ou =>\n            (ou.logements || []).forEach(lg2 => {\n              const m2 = String(lg2.mabec || lg2.codeArticle || \"\").replace(/\\s+/g, \" \").trim();\n              const r2v = String(lg2.ref || \"\").trim();\n              if(m2 === mabec && r2v && !estCodeMabec(r2v) && !iso) iso = r2v;\n            }))))));\n        if(iso) lg.ref = iso;\n        rapport.push((l.nom || \"?\") + \" \u00b7 \" + (rf.nom || \"?\") + \" \u00b7 \" + (op.nom || \"?\")\n          + \" \u00b7 \" + (lg.nom || \"logement\") + \" (\" + (sc.name || \"?\") + \") : MABEC \" + mabec\n          + \" remis dans le champ MABEC\"\n          + (iso ? \", r\u00e9f\u00e9rence plaquette compl\u00e9t\u00e9e depuis le classeur (\" + iso + \")\" : \" \u2014 r\u00e9f\u00e9rence plaquette \u00e0 saisir (l'ISO n'\u00e9tait pas dans les donn\u00e9es)\"));\n      });\n    }))));\n  return rapport;\n}\n\nfunction compterInversionsMabec(){\n  let n = 0;\n  lignes.forEach(l => (l.references || []).forEach(rf => (rf.ops || []).forEach(op =>\n    (op.scenarios || []).forEach(sc => { n += detecterInversionMabec([ sc ]).reduce((a, t) => a + t.cibles.length, 0); }))));\n  return n;\n}\n\n/* le nombre de groupes fusionnables sur tout le suivi (pour la d\u00e9tection) */\nfunction compterOutilsD1D2(){\n  let n = 0;\n  lignes.forEach(l => (l.references || []).forEach(r => (r.ops || []).forEach(op =>\n    (op.scenarios || []).forEach(sc => {\n      /* v4.74.3 : les cas \u00ab correcteur manquant \u00bb (completOnly) ne comptent pas\n         comme des regroupements \u2014 le bandeau les annonce \u00e0 part */\n      n += detecterOutilsD1D2([ sc ]).reduce((a, t) => a + (t.completOnly ? 0 : t.fusions.length), 0);\n    }))));\n  return n;\n}\n\n/* v4.74.3 \u2014 les outils d\u00e9j\u00e0 regroup\u00e9s dont le correcteur manque (corrig\u00e9s avant\n   la 4.74.2) : compt\u00e9s \u00e0 part, le bandeau ne dira pas \u00ab en outils s\u00e9par\u00e9s \u00bb\n   pour un outil qui ne l'est plus. */\nfunction compterCorrecteursManquants(){\n  let n = 0;\n  lignes.forEach(l => (l.references || []).forEach(r => (r.ops || []).forEach(op =>\n    (op.scenarios || []).forEach(sc => {\n      n += detecterOutilsD1D2([ sc ]).reduce((a, t) => a + (t.completOnly ? t.fusions.length : 0), 0);\n    }))));\n  return n;\n}\n\n/* v4.58 \u2014 le porte-outil et sa position, lus du num\u00e9ro du classeur (Q4).\n   \u00ab T517 D2 \u00bb = le porte-outil T517, position D2 ; \u00ab T533 \u00bb = porte-outil seul,\n   position inconnue. Fonction pure au service du rapprochement par article. */\nfunction matisPorteOutilPosition(numero){\n  const s = String(numero || \"\").trim().replace(/\\s+/g, \" \");\n  const m = s.match(/^(.*?)\\s*([Dd]\\d+)$/);\n  return m ? { porte: m[1].trim(), position: m[2].toUpperCase() } : { porte: s, position: null };\n}\n\n/* v4.71.0 \u2014 Benjamin, 30/09 : \u00ab l'outil T543 a 2 correcteurs D1 et D2, cela\n   signifie qu'il a 2 logements, chaque logement correspond \u00e0 un correcteur \u00bb.\n\n   D\u00c9FAUT 1 : \u00ab T 543 D1 \u00bb et \u00ab T543 D1 \u00bb sont le M\u00caME porte-outil. L'atelier\n   tape les deux formes, et son classeur contient les deux. En l'\u00e9tat la\n   comparaison se faisait sur la cha\u00eene brute : deux outils distincts, pour la\n   m\u00eame pi\u00e8ce. C'est un doublon de SAISIE, pas une information.\n\n   On ne touche PAS \u00e0 ce qui est affich\u00e9 \u2014 \u00ab T 513 D1 \u00bb reste \u00ab T 513 D1 \u00bb.\n   On normalise seulement la CL\u00c9 de rapprochement. */\nfunction matisClePorteOutil(numero){\n  return String(numero || \"\").toUpperCase().replace(/[^A-Z0-9]/g, \"\") || \"0\";\n}\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   v4.66.0 \u2014 LE GARDE-FOU PORTE-OUTIL / LOGEMENT\n   Benjamin, 30/09 : \u00ab toujours des outils cr\u00e9\u00e9s en double au lieu d'un outil\n   avec 2 logements \u00bb. Le MOD\u00c8LE est juste depuis le d\u00e9but \u2014 un outil porte\n   une liste de logements, et \u00ab + Ajouter un logement \u00bb existe d\u00e9j\u00e0. Le d\u00e9faut\n   est dans le VOCABULAIRE : l'atelier \u00e9crit \u00ab T517 D1 \u00bb, \u00ab T517 D2 \u00bb dans son\n   classeur, et l'outil propose un champ \u00ab n\u00b0 d'outil \u00bb ; on saisit donc\n   \u00ab T517 D1 \u00bb comme num\u00e9ro d'outil, puis \u00ab T517 D2 \u00bb comme un AUTRE outil.\n\n   C'est la confusion du 04/09 (T517 D1/D2), revenue parce que l'outil ne\n   l'attrapait pas l\u00e0 o\u00f9 elle se produit : la saisie. On avait \u00e9crit la\n   convention dans une infobulle \u2014 invisible tant qu'on ne survole pas, et\n   surtout inutile quand on a D\u00c9J\u00c0 tap\u00e9 le num\u00e9ro.\n\n   matisPorteOutilPosition() savait d\u00e9j\u00e0 s\u00e9parer porte-outil et position ;\n   elle n'\u00e9tait appel\u00e9e que par le rapprochement avec le classeur.\n\n   Ici elle est appel\u00e9e \u00c0 LA SAISIE, et elle ne modifie RIEN : elle propose,\n   c'est un clic explicite qui r\u00e9unit. On ne corrige jamais quelqu'un contre\n   son gr\u00e9.\n   \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\nfunction proposerFusionLogement(numero, outils, outilId){\n  const { porte, position } = matisPorteOutilPosition(numero);\n  if(!position || !porte) return null;\n  const autres = (outils || []).filter(o => o.id !== outilId);\n  /* On compare les PORTES-OUTILS, pas les num\u00e9ros exacts. C'est le cas r\u00e9el :\n     \u00ab T517 D1 \u00bb existe d\u00e9j\u00e0, et l'on saisit \u00ab T517 D2 \u00bb \u00e0 c\u00f4t\u00e9 \u2014 deux num\u00e9ros\n     diff\u00e9rents, un seul porte-outil. Comparer les num\u00e9ros n'aurait rien vu. */\n  const cible = autres.find(o => matisPorteOutilPosition(o.numero).porte === porte);\n  if(!cible) return null;\n  /* Si la cible porte D\u00c9J\u00c0 cette position, c'est un vrai doublon : rien \u00e0 proposer.\n     On regarde DEUX endroits, parce que la position peut vivre dans le num\u00e9ro de\n     l'outil (\u00ab T517 D1 \u00bb, saisie maladroite) OU dans le nom du logement\n     (\u00ab T517 \u00bb + logement \u00ab D1 \u00bb, saisie correcte). */\n  const posCible = matisPorteOutilPosition(cible.numero).position;\n  if(posCible === position) return null;\n  if((cible.logements || []).some(l => String(l.nom || \"\").trim().toUpperCase() === position)) return null;\n  const mode = matisPorteOutilPosition(cible.numero).position ? \"complet\" : \"simple\";\n  return { porte, position, cible, mode };\n}\n\n/* La fusion, en fonction PURE : elle rend un NOUVEAU tableau d'outils et ne\n   touche jamais l'ancien \u2014 si elle se trompe, rien n'est perdu.\n     simple  : le logement du doublon est vers\u00e9 dans l'outil propre \u00ab porte \u00bb ;\n     complet : l'outil mal saisi est renomm\u00e9 \u00ab porte \u00bb, tous ses logements y\n               sont vers\u00e9s, et le doublon dispara\u00eet.                        */\nfunction fusionnerOutils(outils, outilId, prop){\n  if(!prop) return (outils || []).slice();\n  const src = (outils || []).find(o => o.id === outilId);\n  if(!src) return (outils || []).slice();\n  const reste = (outils || []).filter(o => o.id !== outilId && o.id !== prop.cible.id);\n  const cible = Object.assign({}, prop.cible);\n  /* un logement \u00ab Logement 1 / 2 / 3 \u00bb porte un nom de D\u00c9FAUT, pas un nom\n     d'atelier : c'est ce qui le distingue de \u00ab Bol \u00bb ou \u00ab Piste \u00bb, et c'est\n     donc lui seul qu'on renomme d'apr\u00e8s la position. */\n  const defaut = /^\\s*logement\\s*\\d*\\s*$/i;\n  const srcDefaut0 = (src.logements || []).filter(l => defaut.test(l.nom || \"\"));\n  const logements = (cible.logements || []).map(l => Object.assign({}, l));\n  const posCible = matisPorteOutilPosition(prop.cible.numero).position;\n  if(prop.mode === \"complet\" && posCible && logements.length && defaut.test(logements[0].nom || \"\")){\n    logements[0].nom = posCible;\n  }\n  const srcLogements = src.logements || [];\n  /* v4.71.0 \u2014 le logement PROVISOIRE est r\u00e9clam\u00e9 par la premi\u00e8re position.\n     Benjamin, 30/09 : \u00ab l'outil T543 a 2 correcteurs D1 et D2, cela signifie\n     qu'il a 2 logements \u00bb. Or la saisie donneait :\n         T543 [Logement 1]  +  \u00ab T543 D1 \u00bb  +  \u00ab T543 D2 \u00bb\n       =>  T543 [Logement 1 , D1 , D2]     \u2190 TROIS logements pour deux correcteurs\n\n     La r\u00e8gle : quand l'outil nu ne contient QU'UN logement, encore au nom de\n     d\u00e9faut et ENCORE VIDE, c'est ce logement-l\u00e0 qui devient la position. On ne\n     cr\u00e9e rien, on ne supprime rien \u2014 on donne \u00e0 un provisoire le nom qu'il\n     attendait, et le reste de la liste est conserv\u00e9 tel quel.\n\n     Deux conditions, et elles sont ce qui rend la r\u00e8gle s\u00fbre :\n     \u00b7 le logement doit \u00eatre au nom de D\u00c9FAUT \u2014 un logement au nom d'atelier\n       (\u00ab Bol \u00bb, \u00ab Piste \u00bb) dit plus que la position, on ne le touche pas ;\n     \u00b7 il doit \u00eatre VIDE \u2014 s'il porte un MABEC, un prix ou une mesure, il\n       raconte quelque chose : on ne l'\u00e9crase pas, on AJOUTE la position \u00e0 c\u00f4t\u00e9\n       et on laisse l'atelier trancher. */\n  /* \u00ab VIDE \u00bb ne se teste pas sur tous les champs : `normalizeLogement` remplit\n     aretes:8 et suiviTolerance:true par D\u00c9FAUT. Les compter comme des donn\u00e9es\n     saisie rendrait la r\u00e8gle inapplicable \u2014 aucun logement du monde ne serait\n     jamais vide. On regarde donc SEULEMENT ce que l'atelier a r\u00e9ellement tap\u00e9\n     ou choisi : un MABEC, un prix, un code article, une r\u00e9f\u00e9rence, une mesure,\n     une condition de coupe. Tout le reste, c'est la structure. */\n  const CHAMPS_SAISIS = [\"mabec\",\"codeArticle\",\"prix\",\"charniere\",\"ref\",\"vc\",\"f\",\n                         \"kappaR\",\"rayonBec\",\"apPiste\",\"tempsCoupe\",\"tempsDeplacement\"];\n  const vide = l => !l || CHAMPS_SAISIS.every(c => l[c] === undefined || l[c] === null\n                 || l[c] === \"\" || l[c] === 0);\n  const premier = logements[0];\n  if(prop.mode === \"simple\" && srcDefaut0.length === 1 && premier\n     && defaut.test(premier.nom || \"\") && vide(premier)){\n    const dejaLa = logements.some(l => String(l.nom || \"\").trim().toUpperCase() === prop.position);\n    if(!dejaLa){\n      const fusionne = Object.assign({}, premier, { nom: prop.position });\n      for(const champ of Object.keys(srcDefaut0[0])){\n        if(fusionne[champ] === undefined || fusionne[champ] === \"\" || fusionne[champ] === 0)\n          fusionne[champ] = srcDefaut0[0][champ];\n      }\n      const gardes = logements.slice(1);   /* les autres logements sont conserv\u00e9s */\n      return reste.concat([Object.assign({}, cible,\n        { numero: prop.porte, logements: [fusionne].concat(gardes) })]);\n    }\n  }\n  /* R\u00e8gle : on renomme un logement PORTE UN NOM DE D\u00c9FAUT (\u00ab Logement 1 \u00bb),\n     parce que c'est un nom provisoire que personne n'a voulu taper. Un logement\n     AU NOM d'atelier (\u00ab Bol \u00bb, \u00ab Piste exterieur \u00bb) garde son nom \u2014 et dans ce\n     cas on ne cr\u00e9e PAS de logement D2 suppl\u00e9mentaire : il porterait une\n     information que le nom contient d\u00e9j\u00e0, et il n'existe pas r\u00e9ellement.\n     On ne fabrique jamais un logement pour satisfaire une convention. */\n  const srcDefaut = srcLogements.filter(l => defaut.test(l.nom || \"\"));\n  const srcAutres = srcLogements.filter(l => !defaut.test(l.nom || \"\"));\n  for(const l of srcAutres) logements.push(Object.assign({}, l));\n  /* le logement du doublon prend le nom de la position, en gardant ses\n     donn\u00e9es (prix, ar\u00eates, charni\u00e8re\u2026) : la saisie n'est jamais perdue */\n  const porteDonnees = srcDefaut[0];\n  if(porteDonnees) logements.push(Object.assign({}, porteDonnees, { nom: prop.position }));\n  cible.numero = prop.porte;\n  cible.logements = logements;\n  reste.push(cible);\n  return reste;\n}\n\n/* v4.58 \u2014 le rapprochement par MABEC + contexte porte-outil (d\u00e9cision Q4 de Benjamin :\n   JAMAIS le MABEC seul \u2014 une m\u00eame plaquette se r\u00e9utilise sur plusieurs porte-outils,\n   c'est normal, et \u00e7a doit se lire comme une information, pas comme une erreur).\n   Le MABEC vit sur le logement dans le champ code article (champ existant raccord\u00e9,\n   pas un doublon : D3, deux champs pour la m\u00eame donn\u00e9e raconteraient deux histoires).\n   Rend un \u00e9tat ET sa phrase (constitution \u00a73.5) :\n   \u00b7 \"match\"   : ce MABEC est suivi sur CE porte-outil \u2192 le logement et son OP ;\n   \u00b7 \"ailleurs\": MABEC suivi sur un autre porte-outil \u2014 r\u00e9utilisation normale ;\n   \u00b7 \"absent\"  : personne ne porte ce MABEC \u2192 l'invitation \u00e0 le saisir ;\n   \u00b7 \"sans\"    : la ligne du classeur n'a pas de MABEC, rien \u00e0 rapprocher.\n   La lecture reste un CONSTAT : cette fonction ne touche \u00e0 aucune donn\u00e9e. */\nfunction matisRapprocheMabec(oc, ligne){\n  const mabec = String((oc && oc.mabec) || \"\").trim();\n  if(!mabec) return { statut: \"sans\", texte: \"\u2014\" };\n  const { porte } = matisPorteOutilPosition(oc.numero);\n  const norm = s => String(s || \"\").trim().toUpperCase().replace(/\\s+/g, \" \");\n  let ailleurs = null;\n  const matchs = [];\n  ((ligne && ligne.references) || []).forEach(ref =>\n    (ref.ops || []).forEach(op =>\n      (op.scenarios || []).forEach(sc =>\n        (sc.outils || []).forEach(ou => {\n          const outNum = String(ou.numero || \"\").trim();\n          /* le contexte porte-outil rattrape aussi la saisie plate \u00ab T517 D1 \u00bb en\n             num\u00e9ro d'outil : le porte T517 du classeur doit la reconna\u00eetre */\n          const surPorte = porte && (outNum.toUpperCase() === porte.toUpperCase()\n                          || outNum.toUpperCase().startsWith(porte.toUpperCase() + \" \"));\n          (ou.logements || []).forEach(l => {\n            if(norm(l.codeArticle) !== norm(mabec)) return;\n            if(surPorte) matchs.push({ logement: l, outNum, opCode: op.opCode || op.nom || \"\" });\n            else if(!ailleurs) ailleurs = { outNum: outNum || \"sans n\u00b0\" };\n          });\n        }))));\n  if(matchs.length){\n    const m = matchs[0];\n    return { statut: \"match\",\n             texte: `suivi : ${m.outNum} \u00b7 ${m.logement.nom || \"logement\"}${m.opCode ? \" (\" + m.opCode + \")\" : \"\"}` };\n  }\n  if(ailleurs) return { statut: \"ailleurs\", texte: `MABEC suivi ailleurs : ${ailleurs.outNum} (m\u00eame plaquette, autre porte-outil)` };\n  return { statut: \"absent\", texte: \"pas encore saisi dans le suivi\" };\n}\n\n/* le rapprochement, dit en atelier (4.56.0) : le classeur parle \u00ab E1 \u00b7 356x26 \u00bb,\n   l'outil d\u00e9clare \u00ab EMAG 1 \u00bb et ses r\u00e9f\u00e9rences. Chaque couple se voit dire s'il\n   existe des deux c\u00f4t\u00e9s, et si la production raconte la m\u00eame chose des deux \u2014\n   le cas \u00ab l'excel dit 50, le terrain dit 30 \u00bb doit sauter aux yeux \u00e0 la lecture,\n   pas se d\u00e9couvrir des mois plus tard. Raison toujours \u00e0 c\u00f4t\u00e9 de l'\u00e9tat, jamais un\n   chiffre nu (constitution \u00a73.5) ; `attention` porte la couleur (ambre, comme les\n   autres avertissements de cet \u00e9cran). La lecture reste un CONSTAT : ce libell\u00e9\n   n'\u00e9crit rien dans le suivi (option C, 4.55.0). */\nfunction libelleRapprochementMatis(c, r){\n  if(!r.ligneId) return { texte: `hors suivi \u2014 la ligne ${r.nomLigne} n'est pas d\u00e9clar\u00e9e dans l'outil`, attention: true };\n  if(!r.ref) return { texte: `la r\u00e9f\u00e9rence ${c.ref} n'est pas d\u00e9clar\u00e9e sur la ligne ${r.nomLigne}`, attention: true };\n  const dansSuivi = `dans le suivi : ${r.nomLigne} \u00b7 ${r.ref.nom}`;\n  if(!c.aProduction) return { texte: `${dansSuivi} \u2014 pas de production relev\u00e9e dans le classeur`, attention: false };\n  const ps = parseFloat(r.ref.productionAnnuelle);\n  if(isNaN(ps)) return { texte: `${dansSuivi} \u2014 pas de production annuelle d\u00e9clar\u00e9e dans l'outil`, attention: false };\n  const pc = c.production;\n  const conforme = Math.abs(pc - ps) <= 0.005 * Math.max(Math.abs(pc), Math.abs(ps));\n  return conforme\n    ? { texte: `${dansSuivi} \u2014 production conforme (${fmt(ps, 0)}/an)`, attention: false }\n    : { texte: `production en divergence \u2014 le classeur dit ${fmt(pc, 0)}/an, l'outil d\u00e9clare ${fmt(ps, 0)}/an`, attention: true };\n}\n\nfunction matisVueHTML(){\n  if(!matisLecture) return `<p class=\"panel-hint\">Aucun classeur lu pour l'instant. Choisissez le fichier\n    \u00ab SUIVI DES CONSOMMATIONS\u2026 \u00bb de Matis : il est lu <b>sur ce poste uniquement</b>, rien n'est envoy\u00e9\n    nulle part, et rien n'est \u00e9crit dans le suivi.</p>\n    <div class=\"mt-recap\">\n      <label class=\"ghost\" for=\"mtFichier\" style=\"cursor:pointer;padding:8px 13px;\">\ud83d\udcc2 Lire le classeur de Matis\u2026</label>\n      <input type=\"file\" id=\"mtFichier\" accept=\".xlsm,.xlsx\" hidden>\n    </div>`;\n\n  const couples = matisLecture.couples || [];\n  const produits = couples.filter(c => c.aProduction);\n  const totalTheo = couples.reduce((a, c) => a + (c.coutAnnuelTheorique || 0), 0);\n  const totalReel = couples.reduce((a, c) => a + (c.coutAnnuelReel || 0), 0);\n  const ecart = totalReel - totalTheo;\n  const ecartPct = totalTheo ? (ecart / totalTheo) * 100 : null;\n\n  const tuiles = `\n    <div class=\"mt-bilan\">\n      <div class=\"mt-tuile\">\n        <div class=\"mt-l\">Budget-outillage / an</div>\n        <div class=\"mt-v\">${fmtEuroCourt(Math.round(totalTheo))}</div>\n        <div class=\"mt-sub\">th\u00e9orique, d'apr\u00e8s prix et dur\u00e9es de vie</div>\n      </div>\n      <div class=\"mt-tuile\">\n        <div class=\"mt-l\">Consomm\u00e9 / an</div>\n        <div class=\"mt-v\">${fmtEuroCourt(Math.round(totalReel))}</div>\n        <div class=\"mt-sub\">r\u00e9el, d'apr\u00e8s le relev\u00e9 de Matis</div>\n      </div>\n      <div class=\"mt-tuile ${ecart > 0 ? \"alerte\" : (ecart < 0 ? \"ok\" : \"\")}\">\n        <div class=\"mt-l\">\u00c9cart</div>\n        <div class=\"mt-v ${ecart > 0 ? \"mt-ecart-pos\" : (ecart < 0 ? \"mt-ecart-neg\" : \"\")}\">${ecart >= 0 ? \"+\" : \"\u2212\"}${fmtEuroCourt(Math.round(Math.abs(ecart)))}</div>\n        <div class=\"mt-sub\">${ecartPct === null ? \"\u2014\" : (ecartPct >= 0 ? \"+\" : \"\u2212\") + fmt(Math.abs(ecartPct), 0) + \" % vs th\u00e9orie\"}</div>\n      </div>\n      <div class=\"mt-tuile\">\n        <div class=\"mt-l\">Couples produits</div>\n        <div class=\"mt-v\">${produits.length}<small> / ${couples.length}</small></div>\n        <div class=\"mt-sub\">avec une production relev\u00e9e</div>\n      </div>\n    </div>`;\n\n  const lignes = couples.map(c => {\n    const r = matisRapproche(c);\n    const mesure = c.ecart === null;\n    const rap = libelleRapprochementMatis(c, r);\n    return `<tr>\n      <td class=\"mt-lign\">${escapeAttr(c.codeLigne)} \u00b7 ${escapeAttr(c.ref)}\n        <div class=\"mt-rap${rap.attention ? \" mt-rap-attention\" : \"\"}\">${escapeAttr(rap.texte)}</div></td>\n      <td class=\"num\">${c.aProduction ? fmt(c.production, 0) : \"\u2014\"}</td>\n      <td class=\"num\">${c.cppTheorique ? fmt(c.cppTheorique, 4) : \"\u2014\"}</td>\n      <td class=\"num\">${c.cppReel ? fmt(c.cppReel, 4) : \"\u2014\"}</td>\n      <td class=\"num ${c.ecart > 0 ? \"mt-ecart-pos\" : (c.ecart < 0 ? \"mt-ecart-neg\" : \"\")}\">${mesure ? \"\u2014\" : (c.ecart >= 0 ? \"+\" : \"\u2212\") + fmt(Math.abs(c.ecart), 4)}</td>\n      <td class=\"mt-raison\">${escapeAttr(libelleEcartMatis(c))}</td>\n    </tr>`;\n  }).join(\"\");\n\n  return `\n    <p class=\"mt-raz\"><b>Ce que cet \u00e9cran mesure.</b> Le budget-outillage de l'outil dit ce que la\n      plaquette <i>devrait</i> co\u00fbter (prix \u00d7 ar\u00eates \u00f7 dur\u00e9es de vie). Le classeur de Matis dit ce\n      qu'elle <i>a r\u00e9ellement</i> co\u00fbt\u00e9. L'\u00e9cart entre les deux mesure la sant\u00e9 du plan outillage :\n      un \u00e9cart stable et connu se budg\u00e8te, un \u00e9cart qui grossit se traite. Rien ici n'est une\n      erreur de saisie \u2014 c'est de l'\u00e9cart entre un mod\u00e8le et le terrain.</p>\n    <div class=\"mt-recap\">\n      <label class=\"ghost\" for=\"mtFichier\" style=\"cursor:pointer;padding:8px 13px;\">\ud83d\udcc2 Lire le classeur de Matis\u2026</label>\n      <input type=\"file\" id=\"mtFichier\" accept=\".xlsm,.xlsx\" hidden>\n      <span class=\"mt-fichier\">${escapeAttr(matisLecture.fichier)} \u2014 lu le ${escapeAttr(matisLecture.luLe)} \u00b7 ${(matisLecture.feuilles || []).length} feuilles \u00ab Cout pi\u00e8ce \u00bb</span>\n    </div>\n    ${tuiles}\n    ${(() => {\n      /* v4.73 (Tour 34, point 3) \u2014 l'\u00e9cran DIT ce qu'il regroupe : les outils\n         fusionn\u00e9s (T513 D1 + T513 D2 \u2192 T513, 2 logements) sont annonc\u00e9s, en\n         mots, jamais en silence. reparerOutilsRapport existe pour \u00e7a. */\n      const fusions = [];\n      (matisLecture.feuilles || []).forEach(f => {\n        if(!f || !f.outils) return;\n        f.outils.forEach(o => { if(o._fusionReparee && (o.nbOutils || 1) > 1) fusions.push(o); });\n      });\n      if(!fusions.length) return \"\";\n      const phrases = fusions.map(o => `${o.numero} \u2014 ${(o.nbOutils)} outils regroup\u00e9s, ${(o.logements || []).length} logements : ${(o.logements || []).map(l => l.nom).join(\", \")}`);\n      return `<p class=\"mt-fusion\">\ud83d\udd27 ${phrases.length} porte-outil${phrases.length > 1 ? \"s\" : \"\"} regroup\u00e9${phrases.length > 1 ? \"s\" : \"\"} \u00e0 la lecture : ${phrases.map(p => `\u00ab ${escapeAttr(p)} \u00bb`).join(\" \u00b7 \")}</p>`;\n    })()}\n    <div class=\"tbl-wrap\">\n      <table class=\"mt-tbl\">\n        <thead><tr><th>Couple</th><th class=\"num\">Prod.</th><th class=\"num\">CPP th\u00e9o.</th><th class=\"num\">CPP r\u00e9el</th><th class=\"num\">\u00c9cart</th><th>Lecture</th></tr></thead>\n        <tbody>${lignes}</tbody>\n      </table>\n    </div>\n    <p class=\"panel-hint\" style=\"margin-top:12px;\">Les couples \u00e0 production nulle sont des postes\n      ouverts ou arr\u00eat\u00e9s sur la p\u00e9riode : ils figurent pour m\u00e9moire, ils ne comptent pas dans le bilan.\n      Cette lecture est un <b>constat</b> \u2014 elle n'\u00e9crit rien dans le suivi et n'y changera rien tant\n      que la d\u00e9cision 2 version n'aura pas \u00e9t\u00e9 prise.</p>\n    <div class=\"panel-actions\">\n      <button class=\"ghost\" id=\"mtTools\">D\u00e9tail par outil</button>\n      <button class=\"primary\" id=\"mtClose\">Fermer</button>\n    </div>`;\n}\n\nfunction matisDetailHTML(){\n  if(!matisLecture) return \"\";\n  const couples = (matisLecture.couples || []).filter(c => c.aProduction);\n  /* 4.58.1 \u2014 le rapprochement r\u00e9sum\u00e9 au niveau du panneau : c'est ICI que vit\n     l'invitation (contestation Hermes Tour 11), pas dans un ambre par ligne.\n     Le gris discret par ligne dit \u00ab \u00e0 saisir \u00bb, le compteur dit combien il en reste. */\n  let nMatch = 0, nAilleurs = 0, nAbsent = 0, nSans = 0;\n  couples.forEach(c => {\n    const r = matisRapproche(c);\n    c.outils.forEach(o => {\n      const st = matisRapprocheMabec(o, r.ligne).statut;\n      if(st === \"match\") nMatch++;\n      else if(st === \"ailleurs\") nAilleurs++;\n      else if(st === \"absent\") nAbsent++;\n      else nSans++;\n    });\n  });\n  const parts = [];\n  if(nMatch) parts.push(`${nMatch} suivie${nMatch > 1 ? \"s\" : \"\"}`);\n  if(nAilleurs) parts.push(`${nAilleurs} suivie${nAilleurs > 1 ? \"s\" : \"\"} ailleurs`);\n  if(nAbsent) parts.push(`<b>${nAbsent} \u00e0 saisir</b>`);\n  if(nSans) parts.push(`${nSans} sans MABEC dans le classeur`);\n  const recapRap = parts.length\n    ? ` <b>Rapprochement :</b> ${parts.join(\" \u00b7 \")}.` : \"\";\n  const blocs = couples.map(c => {\n    const r = matisRapproche(c);\n    return `\n    <div class=\"mt-detail\" style=\"margin-bottom:14px;\">\n      <h4 style=\"font-family:var(--font-disp);font-size:15px;margin:0 0 6px;\">${escapeAttr(c.codeLigne)} \u00b7 ${escapeAttr(c.ref)}</h4>\n      <div class=\"tbl-wrap\">\n        <table class=\"mt-tbl\">\n          <thead><tr><th>Outil</th><th>OP</th><th>Article</th><th>MABEC</th><th class=\"num\">CPP th\u00e9o.</th><th class=\"num\">CPP r\u00e9el</th><th class=\"num\">Qt\u00e9 r\u00e9elle</th><th>Dans le suivi</th></tr></thead>\n          <tbody>${c.outils.map(o => {\n            const rap = matisRapprocheMabec(o, r.ligne);\n            /* v4.73 (Tour 34) \u2014 \u00ab T513 \u2014 2 logements \u00bb : le nombre de logements\n               est lisible sur la ligne, comme partout ailleurs. Un outil fusionn\u00e9\n               (_fusionReparee) l'est avec ses positions ; une ligne plate garde\n               son libell\u00e9. */\n            const nbLog = (o.logements || []).length;\n            const numTxt = o.numero + (nbLog > 1 ? ` \u2014 ${nbLog} logements` : \"\");\n            return `<tr>\n            <td class=\"mt-lign\">${escapeAttr(numTxt)}</td>\n            <td class=\"mt-op\">${escapeAttr(o.opCode)}</td>\n            <td class=\"mt-op\">${escapeAttr(o.article || (nbLog > 1 ? `${nbLog} articles` : \"\u2014\"))}</td>\n            <td class=\"mt-op\">${escapeAttr(o.mabec || (nbLog > 1 ? `${nbLog} MABEC` : \"\u2014\"))}</td>\n            <td class=\"num\">${o.cppTheorique ? fmt(o.cppTheorique, 5) : \"\u2014\"}</td>\n            <td class=\"num\">${o.cppReel ? fmt(o.cppReel, 5) : \"\u2014\"}</td>\n            <td class=\"num\">${o.qteReelle === null ? \"\u2014\" : fmt(o.qteReelle, 0)}</td>\n            <td class=\"mt-suivi${rap.statut === \"absent\" ? \" mt-suivi-absent\" : \"\"}\">${escapeAttr(rap.texte)}</td>\n          </tr>`; }).join(\"\")}</tbody>\n        </table>\n      </div>\n    </div>`;\n  }).join(\"\");\n  return `<h3>Classeur Matis \u2014 d\u00e9tail par outil</h3>\n    <p class=\"panel-hint\">Chaque ligne du classeur est une plaquette : le porte-outil et sa\n      position (\u00ab T517 D2 \u00bb = porte-outil T517, position D2), son article, son MABEC. La\n      colonne \u00ab Dans le suivi \u00bb dit si cette plaquette est suivie chez nous : <b>\u00ab suivi :\n      T517 \u00b7 D1 (OP10) \u00bb</b> = le logement existe ; <b>\u00ab suivi ailleurs \u00bb</b> = la m\u00eame\n      plaquette sert sur un autre porte-outil, c'est normal ; <i>\u00ab pas encore saisi \u00bb</i> =\n      \u00e0 compl\u00e9ter dans la fiche outil, champ MABEC du logement.${recapRap}</p>\n    ${blocs || `<p class=\"panel-hint\">Aucun couple avec production relev\u00e9e.</p>`}\n    <div class=\"panel-actions\"><button class=\"primary\" id=\"mtDetailClose\">Fermer</button></div>`;\n}\n\nfunction renderMatis(){\n  const wrap = document.getElementById(\"matisPanel\");\n  if(!wrap) return;\n  wrap.innerHTML = matisVueHTML();\n  const fermer = document.getElementById(\"mtClose\");\n  if(fermer) fermer.addEventListener(\"click\", fermerPanneaux);\n  const detail = document.getElementById(\"mtTools\");\n  if(detail) detail.addEventListener(\"click\", () => {\n    const w2 = document.getElementById(\"matisDetailPanel\");\n    if(w2){\n      /* v4.73.2 \u2014 le panneau est reconstruit ici, donc SES boutons se branchent\n         ICI aussi : le Fermer n'avait jamais eu de handler (bug Benjamin, retour\n         d'usage n\u00b02 \u2014 un \u00e9cran qui ne sait pas se fermer est un \u00e9cran bloqu\u00e9). */\n      w2.innerHTML = matisDetailHTML();\n      ouvrirPanneau(\"matisDetailPanel\");\n      const c = document.getElementById(\"mtDetailClose\");\n      if(c) c.addEventListener(\"click\", fermerPanneaux);\n    }\n  });\n  const fichier = document.getElementById(\"mtFichier\");\n  if(fichier) fichier.addEventListener(\"change\", async () => {\n    const f = fichier.files && fichier.files[0];\n    if(!f) return;\n    /* l'utilisateur a choisi SON fichier : rien n'est envoy\u00e9, rien n'est \u00e9crit */\n    try {\n      matisLecture = await matisLireClasseur(f);\n    } catch(err){\n      dialogueAlerte(\"Lecture impossible : \" + err.message, \"Classeur Matis\");\n      return;\n    }\n    renderMatis();\n  });\n}\n\nfunction ouvrirMatis(){ renderMatis(); ouvrirPanneau(\"matisPanel\"); }\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   v4.54.0 \u2014 FICHE POSTE (couche 1) : la porte qui manquait entre la carte et le d\u00e9tail\n\n   La carte (4.51.2) dit QUOI : l'\u00e9tat, le gain, ce qui reste. La couche 2 (4.52) dit\n   COMMENT : le sc\u00e9nario, les essais, les preuves. Entre les deux, il n'y avait rien \u2014\n   on sautait de la tuile au sc\u00e9nario sans jamais r\u00e9pondre \u00e0 la seule question qui\n   compte en atelier : \u00ab qu'est-ce qu'il se passe sur CETTE machine ? \u00bb\n\n   La fiche r\u00e9pond \u00e0 cette question, et porte une porte EXPLICITE vers la couche 2\n   (\u00ab Ouvrir le poste \u2192 \u00bb). C'est le geste double (R3) : le survol / le premier\n   toucher montre la fiche, le bouton entre. Le geste devient d\u00e9couvrable au lieu\n   d'\u00eatre un pari, et l'utilisateur n'est jamais forc\u00e9 de deviner qu'un second\n   toucher entre dans le d\u00e9tail.\n\n   Trois r\u00e8gles tenues ici (constitution v1.1) :\n   \u00b7 D3 \u2014 la fiche ne montre AUCUN chiffre que le bandeau du sc\u00e9nario ne montre pas :\n     tout vient de gainPoste() (4.51.0), jamais d'un recalcul local ;\n   \u00b7 la raison d'un \u00e9tat est toujours \u00e0 c\u00f4t\u00e9 de l'\u00e9tat (r\u00e8gle d'interface \u00a75.2) ;\n   \u00b7 jamais de K ni de P_req : la fiche est pr\u00e9sentable telle quelle.\n   \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n/* la prochaine \u00e9tape du plan, dite en atelier : c'est l'information qui manque le\n   plus dans tout l'outil aujourd'hui. Elle se d\u00e9duit de l'\u00e9tat, jamais d'un statut\n   technique stock\u00e9e \u2014 donc elle ne peut pas mentir. */\nfunction prochaineEtapePoste(t){\n  const p = t.poste;\n  if(t.etat === \"gagne\"){\n    /* un poste act\u00e9 se maintient : on le revalide, on ne le r\u00e9invente pas */\n    const r = (p.refs || []).find(x => x.serie);\n    return \"En production \u2014 maintenir et confirmer au prochain r\u00e9\u00e9quilibrage\";\n  }\n  if(t.etat === \"encours\"){\n    const r = (p.refs || []).find(x => x.meilleur && !x.serie);\n    if(r && r.meilleur){\n      const seuil = r.meilleur.sc.validationThreshold || 5;\n      const faits = ((r.meilleur.sc.essais || []).length);\n      return faits < seuil\n        ? `Terminer le protocole ${seuil}\u00d7 \u2014 ${faits}/${seuil} essais relev\u00e9s`\n        : `Protocole ${seuil}\u00d7 atteint \u2014 passer en production`;\n    }\n    return \"Essai en cours \u2014 relev\u00e9s \u00e0 finir\";\n  }\n  if(t.etat === \"aChiffrer\"){\n    return \"Cible du site pos\u00e9e, aucune mesure : chiffrer la production de ce poste\";\n  }\n  return \"Poste d\u00e9clar\u00e9, jamais travaill\u00e9 \u2014 premier essai \u00e0 faire\";\n}\n\n/* Les sc\u00e9narios du poste, regroup\u00e9s par r\u00e9f\u00e9rence. C'est la lecture \u00ab par qui on\n   travaille \u00bb : sur EMAG 1, OP10 sert la 356x26 et la 304x28 \u2014 la fiche le dit. */\nfunction fichePostesReferences(t){\n  return (t.poste.refs || []).map(r => {\n    const st = r.serie ? \"serie\" : (r.gain !== null && r.gain > 0 ? \"essai\" : \"essai\");\n    return { ref: r.ref, serie: r.serie, gain: r.gain, volume: r.volume,\n             tBase: r.tBase, gainAnnuel: r.gain, seuil: r.meilleur ? (r.meilleur.sc.validationThreshold || 5) : null,\n             nbEssais: r.meilleur ? ((r.meilleur.sc.essais || []).length) : 0,\n             scId: r.meilleur ? r.meilleur.sc.id : (r.prodSc ? r.prodSc.id : null),\n             statut: st };\n  }).filter(x => x.scId);\n}\n\nfunction fichePosteHTML(t){\n  const p = t.poste;\n  const e = CARTE_ETATS[t.etat] || CARTE_ETATS.opportunite;\n  const dom = p.refDominante;\n  const nomRef = (dom && ((dom.ref && dom.ref.nom) || dom.nom)) || \"\";\n  const refs = fichePostesReferences(t);\n  const etape = prochaineEtapePoste(t);\n\n  /* le pouls, identique \u00e0 la tuile (D3 : m\u00eame fonction, m\u00eame valeur) */\n  let pouls = \"\";\n  if(p.gainActe > 0) pouls += `<span class=\"fp-acte\">${p.gainActe >= 0 ? \"+\" : \"\u2212\"}${fmtEuroCourt(Math.abs(p.gainActe))}<small>/an act\u00e9</small></span>`;\n  if(p.gainProjete > 0) pouls += `<span class=\"fp-projete\">${p.gainProjete >= 0 ? \"+\" : \"\u2212\"}${fmtEuroCourt(Math.abs(p.gainProjete))}<small>/an projet\u00e9</small></span>`;\n  if(!pouls) pouls = t.etat === \"aChiffrer\"\n    ? `<span class=\"fp-invite\">cible ${fmt(p.cibleCPP, 3)} \u20ac<small>\u2014 \u00e0 chiffrer</small></span>`\n    : `<span class=\"fp-vide\">aucun gain chiffr\u00e9</span>`;\n\n  /* les r\u00e9f\u00e9rences du poste : le travail r\u00e9el, pas le concept */\n  const lignesRef = refs.length ? refs.map(x => {\n    /* un poste EN PRODUCTION n'a pas de protocole \u00e0 faire : afficher \u00ab 0/5 essais \u00bb\n       ferait croire \u00e0 une absence de travail. On n'affiche l'avancement que si un\n       protocole est r\u00e9ellement en cours (statut essai). */\n    const prog = (!x.serie && x.seuil) ? `<span class=\"fp-ref-prog\">${x.nbEssais}/${x.seuil} essais</span>` : \"\";\n    return `\n    <div class=\"fp-ref\">\n      <span class=\"fp-ref-nom\">${escapeAttr((x.ref && x.ref.nom) || \"r\u00e9f\u00e9rence\")}</span>\n      <span class=\"statut-pill ${x.serie ? \"serie\" : \"essai\"}\">${x.serie ? \"en production\" : statutLabel(\"essai\")}</span>\n      ${x.gainAnnuel ? `<span class=\"fp-ref-gain\">${x.gainAnnuel >= 0 ? \"+\" : \"\u2212\"}${fmtEuroCourt(Math.abs(x.gainAnnuel))}/an</span>` : \"\"}\n      ${prog}\n    </div>`;}).join(\"\") : `<p class=\"fp-note\">Aucune r\u00e9f\u00e9rence travaille ce poste pour l'instant.</p>`;\n\n  /* la porte vers la couche 2 \u2014 visible, explicite, d\u00e9couvrable (R3) */\n  const porte = t.etat === \"opportunite\" ? \"\" : `\n    <div class=\"fp-actions\">\n      <button class=\"primary fp-ouvrir\" data-ligne=\"${escapeAttr(t.ligne.id)}\" data-code=\"${escapeAttr(t.code)}\"\n        title=\"Ouvrir le sc\u00e9nario de production de ce poste : composition, essais, preuves\">Ouvrir le poste \u2192</button>\n    </div>`;\n\n  return `<div class=\"fp-fiche ${e.classe}\" data-ligne=\"${escapeAttr(t.ligne.id)}\" data-code=\"${escapeAttr(t.code)}\" role=\"dialog\" aria-label=\"Fiche poste ${escapeAttr(t.nomMachine || t.code)}\">\n    <div class=\"fp-tete\">\n      <div class=\"fp-titre-bloc\">\n        <p class=\"fp-eyebrow\">${escapeAttr(t.ligne.nom || \"\")} \u00b7 ${escapeAttr(t.code)}</p>\n        <h4 class=\"fp-titre\">${escapeAttr(t.nomMachine || t.code)}</h4>\n      </div>\n      <span class=\"ca-etat\">${e.label}</span>\n      <button class=\"ghost fp-fermer\" title=\"Fermer la fiche\" aria-label=\"Fermer la fiche\">\u2715</button>\n    </div>\n    ${nomRef ? `<p class=\"fp-ref-dominante\">R\u00e9f\u00e9rence principale : <b>${escapeAttr(nomRef)}</b>${refs.length > 1 ? ` <span class=\"ca-refs\">+${refs.length - 1} r\u00e9f.</span>` : \"\"}</p>` : \"\"}\n    <div class=\"ca-pouls fp-pouls\">${pouls}</div>\n    ${p.chemin === null ? \"\" : `\n      <div class=\"fp-chemin\">\n        <span class=\"fp-chemin-l\">Vers la cible du site</span>\n        <div class=\"ca-track\"><div class=\"ca-fill\" style=\"width:${Math.round(p.chemin)}%\"></div></div>\n        <span class=\"ca-pct\">${Math.round(p.chemin)} %</span>\n      </div>`}\n    <div class=\"fp-refs\"><h5>Travail sur ce poste</h5>${lignesRef}</div>\n    <p class=\"fp-etape\"><b>Prochaine \u00e9tape :</b> ${escapeAttr(etape)}</p>\n    ${(p.nonChiffres || 0) > 0 ? `<p class=\"fp-avertir\">${p.nonChiffres} op\u00e9ration${p.nonChiffres > 1 ? \"s\" : \"\"} non chiffrable${p.nonChiffres > 1 ? \"s\" : \"\"} \u2014 le gain affich\u00e9 ne les compte pas.</p>` : \"\"}\n    ${porte}\n  </div>`;\n}\n\n/* l'\u00e9tat du panneau de fiche : null = ferm\u00e9, sinon { ligneId, code } */\nlet fichePosteOuverte = null;\n\n/* La fiche vit DANS la carte (superpos\u00e9e), pas dans un second panneau : c'est la\n   couche 1 du m\u00eame \u00e9cran, pas une nouvelle fen\u00eatre. Le survol desktop ouvre aussi,\n   mais seulement si aucune fiche n'est d\u00e9j\u00e0 ouverte (sinon survoler une autre tuile\n   pendant la lecture de la fiche sous le doigt). */\nfunction renderFichePoste(tuiles, t){\n  const zone = document.getElementById(\"carteFicheZone\");\n  if(!zone) return;\n  /* on m\u00e9morise la fiche ouverte : c'est elle qui emp\u00eache le survol d'en remplacer\n     une autre sous les yeux du lecteur, et c'est elle que le filtre doit rouvrir. */\n  fichePosteOuverte = t ? { ligneId: t.ligne.id, code: t.code } : null;\n  if(!t){ zone.innerHTML = \"\"; zone.hidden = true; return; }\n  zone.hidden = false;\n  zone.innerHTML = fichePosteHTML(t);\n  const fermer = zone.querySelector(\".fp-fermer\");\n  if(fermer) fermer.addEventListener(\"click\", () => { fichePosteOuverte = null; renderFichePoste(tuiles, null); });\n  const ouvrir = zone.querySelector(\".fp-ouvrir\");\n  if(ouvrir) ouvrir.addEventListener(\"click\", () => ouvrirPosteDepuisFiche(t));\n}\n\n/* la porte de la fiche appelle exactement le m\u00eame chemin que le bouton de la tuile\n   (couche 2, v4.52) : une seule impl\u00e9mentation de \u00ab entrer dans ce poste \u00bb. */\nfunction ouvrirPosteDepuisFiche(t){\n  const ligne = lignes.find(x => x.id === t.ligne.id);\n  const bloc = scenariosPostes(ligne, t.code)[0];\n  if(!bloc) return;\n  const prodSc = (bloc.scs || []).find(x => x.baseline)\n              || (bloc.scs || []).find(x => /base excel/i.test(x.name || \"\"))\n              || (bloc.scs || [])[0];\n  if(!prodSc) return;\n  activeLigneId = ligne.id;\n  activeReferenceId = bloc.ref.id;\n  activeOpId = bloc.op.id;\n  activeId = prodSc.id;\n  fermerPanneaux();\n  render();\n}\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   v4.51.2 \u2014 CARTE ATELIER (couche 0, lecture seule)\n\n   L'\u00e9cran d'entr\u00e9e spatial de l'outil : des tuiles = les postes (ligne x opCode)\n   D\u00c9CLAR\u00c9S dans LIGNES_SEPT_FONS. On lit la carte en un coup d'\u0153il \u2014 o\u00f9 en est\n   l'usine, qu'a-t-on gagn\u00e9, qu'est-ce qui reste \u2014 puis on descend couche par couche.\n\n   Trois r\u00e8gles non n\u00e9gociables, tenues ici :\n   \u00b7 D3 \u2014 la tuile ne montre AUCUN chiffre que le bandeau du sc\u00e9nario ne montre pas :\n     tout passe par gainPoste() (4.51.0) \u2192 bilanAnnuel() \u2192 perimetreCompare() (v4.45) ;\n   \u00b7 le co\u00fbt machine exige la ligne du poste \u2014 c'est pour \u00e7a que gainPoste() passe\n     la ligne \u00e0 coutsDetail(), alors que pieceCPPComplet() (v4.49) s'appuie sur le\n     repli getActiveLigne() et n'a donc de sens qu'en contexte d'une r\u00e9f\u00e9rence\n     ouverte. La carte et l'A4 Mission consomment gainPoste(), jamais pieceCPPComplet ;\n   \u00b7 jamais de K ni de P_req : la carte est pr\u00e9sentable telle quelle en r\u00e9union.\n   \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n/* Le filtre de la carte : le projet actif par d\u00e9faut (H1-b), \u00ab toute l'usine \u00bb \u00e0 un clic.\n   null = toute l'usine. M\u00e9moris\u00e9 comme le filtre du tableau de bord, mais ind\u00e9pendant :\n   chaque \u00e9cran a SON filtre, sinon les deux se marchent dessus. */\nlet carteFiltreProjetId = null;\nlet carteProjetChoisi = false;   // false = suit le projet actif tant qu'on n'a pas choisi\n\n/* Les postes visibles sur la carte. Une tuile = (ligne d\u00e9clar\u00e9e x machine d\u00e9clar\u00e9e).\n   La ligne doit exister dans les donn\u00e9es (sinon on dessine une ligne sans suivi) ; la\n   machine vient de la d\u00e9claration, jamais des sc\u00e9narios rencontr\u00e9s. */\nfunction cartePostes(){\n  const out = [];\n  lignes.forEach(ligne => {\n    postesLigne(ligne, LIGNES_SEPT_FONS).forEach(m => {\n      const poste = gainPoste(ligne, m.code, LIGNES_SEPT_FONS);\n      out.push({ ligne, code: m.code, nomMachine: m.nom, poste,\n                 blocs: scenariosPostes(ligne, m.code),\n                 etat: etatTuile(poste), refs: poste.refs || [] });\n    });\n  });\n  return out;\n}\n\n/* Le filtre projet : \u00ab mon projet \u00bb garde les postes qui portent au moins un sc\u00e9nario\n   \u00e9tiquet\u00e9 dans le projet. On ne filtre pas sur le gain mais sur la pr\u00e9sence \u2014 sinon un\n   poste \u00ab \u00e0 chiffrer \u00bb (encore vide) dispara\u00eet justement quand on cherche \u00e0 le remplir.\n   \u26a0 les \u00e9tiquettes de projet sont des QUADRUPLETS exacts (ligne + r\u00e9f\u00e9rence + OP +\n   sc\u00e9nario, cf. projetContientScenario et resoudreTag) : passer opId \u00e0 null ne\n   matcherait jamais. On r\u00e9capitule donc les sc\u00e9narios par bloc, avec l'OP d'origine. */\nfunction carteVisiblePostes(tous, pjId){\n  if(!pjId) return tous;\n  const pj = projets.find(p => p.id === pjId);\n  if(!pj) return tous;\n  return tous.filter(t => t.blocs.some(b =>\n    (b.scs || []).some(sc => projetContientScenario(pj, t.ligne.id, b.ref.id, b.op.id, sc.id))));\n}\n\n/* Le d\u00e9compte de recette A2 : quelle part des tuiles porte une information\n   ACTIONNABLE (un gain, une cible, un essai ouvert) ? C'est le seuil qui dira si la\n   carte est utile ou d\u00e9corative \u2014 mesur\u00e9, pas ressenti. */\nfunction carteRecetteA2(tuiles){\n  if(!tuiles.length) return { total: 0, actionnables: 0, ratio: 0 };\n  const actionnables = tuiles.filter(t => t.etat === \"gagne\" || t.etat === \"encours\" || t.etat === \"aChiffrer\").length;\n  return { total: tuiles.length, actionnables, ratio: actionnables / tuiles.length };\n}\n\n/* \u2500\u2500 Le rendu \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\nconst CARTE_ETATS = {\n  gagne:      { label: \"Gagn\u00e9\",       classe: \"gagne\" },\n  encours:    { label: \"En cours\",    classe: \"encours\" },\n  aChiffrer:  { label: \"\u00c0 chiffrer\",  classe: \"achiffrer\" },\n  opportunite:{ label: \"Opportunit\u00e9\", classe: \"opportunite\" }\n};\n\nfunction carteTuileHTML(t, pjId){\n  const p = t.poste;\n  const e = CARTE_ETATS[t.etat] || CARTE_ETATS.opportunite;\n  const dom = p.refDominante;\n  const autres = Math.max(0, (p.refs || []).length - 1);\n\n  /* le pouls : deux chiffres, jamais plus (D2). Act\u00e9 en gros s'il existe, projet\u00e9 en\n     dessous. Un poste sans gain n'affiche PAS de 0 \u20ac \u2014 il affiche son invitation\n     (\u00ab \u00e0 chiffrer \u00bb) ou son silence (opportunit\u00e9). */\n  let pouls = \"\";\n  if(p.gainActe > 0){\n    pouls = `<span class=\"ca-acte\">${p.gainActe >= 0 ? \"+\" : \"\u2212\"}${fmtEuroCourt(Math.abs(p.gainActe))}<small>/an act\u00e9</small></span>`;\n  }\n  if(p.gainProjete > 0){\n    pouls += `<span class=\"ca-projete\">${p.gainProjete >= 0 ? \"+\" : \"\u2212\"}${fmtEuroCourt(Math.abs(p.gainProjete))}<small>/an projet\u00e9</small></span>`;\n  }\n  if(!pouls){\n    pouls = t.etat === \"aChiffrer\"\n      ? `<span class=\"ca-invite\">cible ${fmt(p.cibleCPP, 3)} \u20ac<small>\u2014 \u00e0 chiffrer</small></span>`\n      : `<span class=\"ca-vide\">\u2014</span>`;\n  }\n\n  /* le chemin prod \u2192 cible : la barre que la hi\u00e9rarchie regarde. */\n  const chemin = p.chemin === null ? \"\" :\n    `<div class=\"ca-chemin\" title=\"Part du chemin vers la cible du site d\u00e9j\u00e0 parcourue sur ce poste\">\n       <div class=\"ca-track\"><div class=\"ca-fill\" style=\"width:${Math.round(p.chemin)}%\"></div></div>\n       <span class=\"ca-pct\">${Math.round(p.chemin)} %</span>\n     </div>`;\n\n  /* le libell\u00e9 du poste : le nom de la machine s'il est d\u00e9clar\u00e9, le code d'OP sinon.\n     Jamais l'inverse \u2014 \u00ab OP10 \u00bb ne dit rien, \u00ab \u00c9bauche piste \u00bb si. */\n  const titre = escapeAttr(t.nomMachine || t.code);\n  /* refDominante est l'ENTR\u00c9E { ref, volume, ... } du tableau refs (le premier du\n     poste tri\u00e9 par volume), pas l'objet r\u00e9f\u00e9rence : d'o\u00f9 ref.nom, pas ref.ref.nom. */\n  const sousTitre = escapeAttr((dom && dom.ref && dom.ref.nom) || (dom && dom.nom) || \"aucune r\u00e9f\u00e9rence\");\n  const nbRef = autres > 0 ? `<span class=\"ca-refs\" title=\"${autres} autre(s) r\u00e9f\u00e9rence(s) sur ce poste\">+${autres} r\u00e9f.</span>` : \"\";\n\n  /* le multi-geste (R3) : la tuile elle-m\u00eame EST la fiche couche 1 (survol = titre\n     d\u00e9j\u00e0 visible, tap = la m\u00eame fiche ouverte), et le bouton \u00ab Ouvrir le poste \u2192 \u00bb\n     qu'elle porte est la porte explicite vers la couche 2. Un seul survol, pas\n     deux couches de survol qui se marchent dessus. */\n  return `<div class=\"ca-tuile ${e.classe}\" data-ligne=\"${escapeAttr(t.ligne.id)}\" data-code=\"${escapeAttr(t.code)}\" tabindex=\"0\" role=\"button\">\n    <div class=\"ca-tete\">\n      <span class=\"ca-titre\">${titre}</span>\n      <span class=\"ca-etat\">${e.label}</span>\n    </div>\n    <div class=\"ca-ref-ligne\">${sousTitre} ${nbRef}</div>\n    <div class=\"ca-pouls\">${pouls}</div>\n    ${chemin}\n    ${t.etat === \"opportunite\" ? `<div class=\"ca-tentant\">d\u00e9clar\u00e9, jamais travaill\u00e9</div>` : \"\"}\n    ${(p.nonChiffres || 0) > 0 ? `<div class=\"ca-avertir\" title=\"Une op\u00e9ration de ce poste n'est pas chiffrable : le gain affich\u00e9 ne la compte pas.\">${p.nonChiffres} op\u00e9ration${p.nonChiffres > 1 ? \"s\" : \"\"} \u00e0 chiffrer</div>` : \"\"}\n    ${t.etat !== \"opportunite\" ? `<div class=\"ca-actions\"><button class=\"primary small ca-ouvrir\" data-ligne=\"${escapeAttr(t.ligne.id)}\" data-code=\"${escapeAttr(t.code)}\" title=\"Naviguer vers ce poste : sc\u00e9narios, essais, preuves (couche 2)\">Ouvrir le poste \u2192</button></div>` : \"\"}\n  </div>`;\n}\n\nfunction renderCarte(){\n  const wrap = document.getElementById(\"cartePanel\");\n  if(!wrap) return;\n\n  /* H1-b : la carte s'ouvre sur le projet actif tant que l'utilisateur n'a pas choisi\n     explicitement un filtre sur la carte elle-m\u00eame. */\n  if(!carteProjetChoisi) carteFiltreProjetId = activeProjetId || null;\n  const pj = carteFiltreProjetId ? projets.find(p => p.id === carteFiltreProjetId) : null;\n\n  const tous = cartePostes();\n  const visibles = carteVisiblePostes(tous, carteFiltreProjetId);\n  const recette = carteRecetteA2(visibles);\n\n  /* le d\u00e9compte d/usine : la carte doit raconter l'usine enti\u00e8re m\u00eame filtr\u00e9e. */\n  const parLigne = {};\n  tous.forEach(t => { (parLigne[t.ligne.nom || \"?\"] = parLigne[t.ligne.nom || \"?\"] || []).push(t); });\n\n  const sections = lignes.map(ligne => {\n    const tuilesL = visibles.filter(t => t.ligne.id === ligne.id);\n    if(!tuilesL.length) return \"\";\n    const nom = ligne.nom || \"Ligne sans nom\";\n    const gainL = tuilesL.reduce((a, t) => a + (t.poste.gainActe || 0), 0);\n    const infos = [];\n    if(ligne.coutHoraire !== \"\" && !isNaN(parseFloat(ligne.coutHoraire))) infos.push(fmt(parseFloat(ligne.coutHoraire), 2) + \" \u20ac/h\");\n    infos.push(`${tuilesL.filter(t => t.etat === \"gagne\").length} gagn\u00e9${tuilesL.filter(t => t.etat === \"gagne\").length > 1 ? \"s\" : \"\"}`);\n    return `<section class=\"ca-ligne\" data-ligne-id=\"${escapeAttr(ligne.id)}\">\n      <h3 class=\"ca-ligne-titre\">${escapeAttr(nom)}\n        <span class=\"ca-ligne-info\">${escapeAttr(infos.join(\" \u00b7 \"))}</span>\n        ${gainL > 0 ? `<span class=\"ca-ligne-gain\">+${fmtEuroCourt(gainL)}/an act\u00e9</span>` : \"\"}\n      </h3>\n      <div class=\"ca-grille\">${tuilesL.map(t => carteTuileHTML(t, carteFiltreProjetId)).join(\"\")}</div>\n    </section>`;\n  }).join(\"\");\n\n  const filtreHTML = projets.length ? `\n    <div class=\"ca-filtre\">\n      <label for=\"caFiltreProjet\">Vue</label>\n      <select id=\"caFiltreProjet\">\n        <option value=\"\">Toute l'usine</option>\n        ${projets.map(x => `<option value=\"${x.id}\" ${x.id === carteFiltreProjetId ? \"selected\" : \"\"}>Projet \u00ab ${escapeAttr(x.nom)} \u00bb</option>`).join(\"\")}\n      </select>\n      <span class=\"ca-filtre-note\">${pj\n        ? `Postes \u00e9tiquet\u00e9s dans \u00ab ${escapeAttr(pj.nom)} \u00bb.`\n        : \"Toutes les machines d\u00e9clar\u00e9es de l'usine.\"}</span>\n    </div>` : `<p class=\"panel-hint\">Aucun projet d\u00e9fini : la carte montre toute l'usine. Cr\u00e9ez un projet pour la filtrer.</p>`;\n\n  wrap.innerHTML = `\n    <h3>Carte atelier</h3>\n    ${filtreHTML}\n    <p class=\"panel-hint\">Une tuile = une machine, lisible en un coup d'\u0153il. Un poste marqu\u00e9 <b>\u00c0 chiffrer</b> porte une cible du site mais n'a pas encore de mesure : c'est une invitation, pas un poste rat\u00e9. Touchez une tuile pour sa fiche, puis \u00ab Ouvrir le poste \u00bb pour entrer dans le d\u00e9tail.</p>\n    <div class=\"ca-recette\" title=\"Part des tuiles portant une information actionnable (gain, cible ou essai ouvert)\">\n      <b>${recette.actionnables}</b> tuiles actionnables sur ${recette.total} \u2014 ${Math.round(recette.ratio * 100)} %\n      ${recette.ratio >= 1/3 ? `<span class=\"ca-ok\">carte utile</span>` : `<span class=\"ca-faible\">carte creuse \u2014 filtrer par projet</span>`}\n    </div>\n    <div class=\"carte-fiche-zone\" id=\"carteFicheZone\" hidden></div>\n    ${sections || `<p class=\"panel-hint\">Aucun poste \u00e0 afficher${pj ? \" dans ce projet\" : \"\"}. Les machines d\u00e9clar\u00e9es par l'atelier dessinent la carte ; un poste sans donn\u00e9e reste visible en \u00ab Opportunit\u00e9 \u00bb.</p>`}\n    ${livraisonsSectionHTML()}\n    <div class=\"panel-actions\"><button class=\"ghost\" id=\"missionA4Btn\">\ud83d\udda8 A4 Mission</button><button class=\"primary\" id=\"carteClose\">Fermer</button></div>\n  `;\n\n  const btn = document.getElementById(\"carteClose\");\n  if(btn) btn.addEventListener(\"click\", fermerPanneaux);\n  /* v4.52 \u2014 couche 2 : \u00ab Ouvrir le poste \u2192 \u00bb positionne la navigation experte sur la\n     prod du poste (\u2605 puis excel) et referme la carte ; le retour \u00ab \u21e0 Carte atelier \u00bb\n     vit dans la zone Tra\u00e7abilit\u00e9 (A1). */\n  wrap.querySelectorAll(\".ca-ouvrir\").forEach(b => {\n    b.addEventListener(\"click\", () => {\n      const ligne = lignes.find(x => x.id === b.getAttribute(\"data-ligne\"));\n      const code = b.getAttribute(\"data-code\");\n      if(!ligne) return;\n      const bloc = scenariosPostes(ligne, code)[0];\n      if(!bloc) return;\n      const prodSc = (bloc.scs || []).find(x => x.baseline)\n                  || (bloc.scs || []).find(x => /base excel/i.test(x.name || \"\"))\n                  || (bloc.scs || [])[0];\n      if(!prodSc) return;\n      activeLigneId = ligne.id;\n      activeReferenceId = bloc.ref.id;\n      activeOpId = bloc.op.id;\n      activeId = prodSc.id;\n      fermerPanneaux();\n      render();\n    });\n  });\n  /* v4.54.0 \u2014 couche 1 : la fiche poste. Le geste double (R3) : le survol (desktop)\n     ou le PREMIER toucher (tablette) ouvre la fiche, qui porte la porte explicite\n     \u00ab Ouvrir le poste \u2192 \u00bb. On ne force personne \u00e0 deviner qu'un second geste entre.\n     Sur desktop, le survol n'ouvre QUE si aucune fiche n'est d\u00e9j\u00e0 ouverte : sinon on\n     substituerait la fiche sous les yeux de qui est en train de la lire. */\n  const touche = () => window.matchMedia && window.matchMedia(\"(pointer: coarse)\").matches;\n  const trouver = (ligneId, code) => visibles.find(t => t.ligne.id === ligneId && t.code === code);\n  wrap.querySelectorAll(\".ca-tuile\").forEach(tuile => {\n    const ligneId = tuile.getAttribute(\"data-ligne\"), code = tuile.getAttribute(\"data-code\");\n    const ouvrirFiche = () => { const t = trouver(ligneId, code); if(t) renderFichePoste(visibles, t); };\n    tuile.addEventListener(\"mouseenter\", () => { if(!touche() && !fichePosteOuverte) ouvrirFiche(); });\n    /* premier toucher : la fiche. Si elle est d\u00e9j\u00e0 ouverte sur CETTE tuile, on ne\n       referme pas (le second appui sert \u00e0 suivre le bouton, pas \u00e0 refermer). */\n    tuile.addEventListener(\"click\", (ev) => {\n      if(ev.target && ev.target.closest && ev.target.closest(\".ca-ouvrir\")) return; // le bouton fait son office\n      if(touche() || !fichePosteOuverte) ouvrirFiche();\n    });\n    tuile.addEventListener(\"keydown\", (ev) => { if(ev.key === \"Enter\" || ev.key === \" \") { ev.preventDefault(); ouvrirFiche(); } });\n  });\n\n  /* v4.52 \u2014 A4 Mission : impression d\u00e9di\u00e9e (le conteneur est append\u00e9 au body pour que\n     la CSS d'impression n'affiche que lui). */\n  /* v4.53 \u2014 livraisons : cr\u00e9er, imprimer, supprimer */\n  const creer = document.getElementById(\"lvCreer\");\n  if(creer) creer.addEventListener(\"click\", () => {\n    const defaut = \"Livraison 2026/2027 \u2014 \" + new Date().toLocaleDateString(\"fr-FR\");\n    dialogueDemander(\"Nom de la livraison (elle fige les gains du jour et ne se recalcule plus) :\", defaut, { titre: \"Nouvelle livraison\" }).then(nom => {\n      if(nom === null) return;\n      livraisons = (livraisons || []).concat([creerLivraison(String(nom).trim() || defaut)]);\n      saveData(); renderCarte();\n    });\n  });\n  wrap.querySelectorAll(\".lv-print\").forEach(b => b.addEventListener(\"click\", () => {\n    const l = (livraisons || []).find(x => x.id === b.getAttribute(\"data-lv\"));\n    if(!l) return;\n    const el = document.getElementById(\"livraisonImpression\") || document.body.appendChild(Object.assign(document.createElement(\"div\"), { id: \"livraisonImpression\", hidden: true }));\n    el.innerHTML = livraisonImpressionHTML(l);\n    document.body.classList.add(\"print-livraison\");\n    const nettoie = () => { document.body.classList.remove(\"print-livraison\"); window.removeEventListener(\"afterprint\", nettoie); };\n    window.addEventListener(\"afterprint\", nettoie);\n    window.print();\n    setTimeout(nettoie, 2000);\n  }));\n  wrap.querySelectorAll(\".lv-del\").forEach(b => b.addEventListener(\"click\", () => {\n    const l = (livraisons || []).find(x => x.id === b.getAttribute(\"data-lv\"));\n    if(!l) return;\n    dialogueConfirmer(\"Supprimer la livraison \u00ab \" + (l.nom || \"\") + \" \u00bb ?\\n\\nLes donn\u00e9es des sc\u00e9narios, essais et cibles ne sont pas touch\u00e9es \u2014 seule la copie fig\u00e9e dispara\u00eet.\",\n      { titre: \"Supprimer la livraison ?\", okLabel: \"Supprimer\" }).then(ok => {\n      if(!ok) return;\n      livraisons = (livraisons || []).filter(x => x.id !== l.id);\n      saveData(); renderCarte();\n    });\n  }));\n\n  const mBtn = document.getElementById(\"missionA4Btn\");\n  if(mBtn) mBtn.addEventListener(\"click\", () => {\n    const el = document.getElementById(\"missionA4\") || document.body.appendChild(Object.assign(document.createElement(\"div\"), { id: \"missionA4\", hidden: true }));\n    el.innerHTML = missionA4HTML();\n    document.body.classList.add(\"print-mission\");\n    const nettoie = () => { document.body.classList.remove(\"print-mission\"); window.removeEventListener(\"afterprint\", nettoie); };\n    window.addEventListener(\"afterprint\", nettoie);\n    window.print();\n    setTimeout(nettoie, 2000);\n  });\n  const sel = document.getElementById(\"caFiltreProjet\");\n  if(sel) sel.addEventListener(\"change\", () => {\n    carteFiltreProjetId = sel.value || null; carteProjetChoisi = true;\n    renderCarte();\n    /* v4.54.0 \u2014 la fiche ouverte survit au changement de filtre SI le poste est encore\n       visible ; sinon elle se referme proprement. Sans \u00e7a, changer de filtre laisserait\n       une fiche orpheline affich\u00e9e pour un poste qui n'est plus \u00e0 l'\u00e9cran. */\n    if(fichePosteOuverte){\n      const encore = visibles.find(t => t.ligne.id === fichePosteOuverte.ligneId && t.code === fichePosteOuverte.code);\n      renderFichePoste(visibles, encore || null);\n    }\n  });\n}\n\n/* l'entr\u00e9e : le bouton de la barre d'outils ouvre la carte (v4.51.2) */\nfunction ouvrirCarte(ligneId){\n  renderCarte();\n  ouvrirPanneau(\"cartePanel\");\n  /* v4.75 \u2014 depuis l'accueil : la tuile cliqu\u00e9e m\u00e8ne \u00c0 SA LIGNE, pas au d\u00e9but\n     de la carte. La section est mise en \u00e9vidence deux secondes. */\n  if(ligneId){\n    const sec = document.querySelector('#cartePanel .ca-ligne[data-ligne-id=\"' + ligneId + '\"]');\n    if(sec){\n      /* le panneau est le conteneur scrollable : on y deplace la section */\n      const panneau = document.getElementById(\"cartePanel\");\n      panneau.scrollTop = sec.offsetTop - panneau.offsetTop - 8;\n      sec.classList.add(\"ca-ligne-ciblee\");\n      setTimeout(() => sec.classList.remove(\"ca-ligne-ciblee\"), 2000);\n    }\n  }\n}\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   v4.60.0 \u2014 L'\u00c9CRAN D'ACCUEIL : la carte en tuiles de LIGNES (le \u00ab premier \u00e9cran \u00bb)\n\n   Une tuile = une ligne enti\u00e8re (EMAG 1 avec ses postes et ses r\u00e9f\u00e9rences), pas\n   une machine \u2014 la machine, c'est la carte atelier (couche 0, 4.51.2). La tuile\n   lit TOUT dans gainLigne() (4.59) : elle ne recalcule rien (D3, un niveau\n   au-dessus). La porte de sortie : \u00ab Voir l'atelier \u2192 \u00bb ouvre la carte atelier \u2014\n   la descente naturelle ligne \u2192 machines \u2192 fiche \u2192 poste, jamais de porte morte.\n\n   Trois d\u00e9cisions trac\u00e9es :\n   \u00b7 la PASTILLE de la ligne se d\u00e9duit des comptages, PRIORIT\u00c9 \u00c0 L'ATTENTION :\n     \u00e0 chiffrer (la cible est pos\u00e9e, la mesure manque \u2014 l'invitation ouverte\n     H1-a) > essais en cours > gagn\u00e9 > jamais travaill\u00e9. La maquette h\u00e9sitait\n     (EMAG 1 vert avec des essais en cours) ; cette r\u00e8gle est la seule qui soit\n     coh\u00e9rente avec prochaineEtapePoste() : la pastille dit l'action la plus\n     urgente, le gain parle en dessous. MOT + couleur, jamais la couleur seule ;\n   \u00b7 le CO\u00dbT est \u00e9tiquet\u00e9 par la r\u00e9f\u00e9rence dominante (Q6-B, Benjamin) :\n     \u00ab 356x26 : 0,63 \u20ac/pce \u00b7 +1 r\u00e9f. \u00bb \u2014 jamais un co\u00fbt multi-r\u00e9f\u00e9rences nu ;\n   \u00b7 sans VOLUME ANNUEL : \u00ab \u2014 \u00bb + \u00ab volume annuel \u00e0 saisir \u00bb (Q10, Benjamin).\n     C'est le pi\u00e8ge signal\u00e9 par Hermes au Tour 13 : sans volume, la dominante\n     serait un choix arbitraire silencieux \u2014 l'\u00e9cran le dit au lieu de le cacher.\n   La RECETTE A2 vit sur l'\u00e9cran : tuiles actionnables / total, alerte creuse\n   sous 1/3 \u2014 un \u00e9cran qui ne sert pas doit le dire (le\u00e7on 4.51.2). */\n\n/* la pastille de la ligne : un \u00e9tat ET son libell\u00e9, d\u00e9duits des comptages */\nfunction etatLigne(gl){\n  const n = gl.etats;\n  if(n.aChiffrer > 0) return { etat: \"aChiffrer\", label: `${n.aChiffrer} poste${n.aChiffrer > 1 ? \"s\" : \"\"} \u00e0 chiffrer` };\n  if(n.encours > 0)   return { etat: \"encours\",   label: `Essais en cours` };\n  if(n.gagne > 0)     return { etat: \"gagne\",     label: `${n.gagne} poste${n.gagne > 1 ? \"s\" : \"\"} gagn\u00e9${n.gagne > 1 ? \"s\" : \"\"} \u2014 en production` };\n  /* une ligne d\u00e9clar\u00e9e SANS machines (cas r\u00e9el : Weisser/PCI hors p\u00e9rim\u00e8tre) ne\n     dit pas \u00ab 0 poste ouvert \u00bb \u2014 elle dit ce qui manque : les machines */\n  if((gl.postes || []).length === 0) return { etat: \"opportunite\", label: `machines \u00e0 d\u00e9clarer` };\n  return { etat: \"opportunite\", label: `${n.opportunite} poste${n.opportunite > 1 ? \"s\" : \"\"} ouvert${n.opportunite > 1 ? \"s\" : \"\"}` };\n}\n\nfunction accueilTuileHTML(gl){\n  const e = CARTE_ETATS[etatLigne(gl).etat];\n  const badge = etatLigne(gl).label;\n  const l = gl.ligne;\n\n  /* le sous-titre : les r\u00e9f\u00e9rences de la ligne (3 max, +n au-del\u00e0), puis les OP\n     d\u00e9clar\u00e9es \u2014 la ligne se pr\u00e9sente comme Matis la pense. */\n  const refsNoms = (l.references || []).map(r => r.nom).filter(Boolean);\n  const refsTxt = refsNoms.length\n    ? refsNoms.slice(0, 3).join(\" \u00b7 \") + (refsNoms.length > 3 ? ` +${refsNoms.length - 3} r\u00e9f.` : \"\")\n    : \"aucune r\u00e9f\u00e9rence d\u00e9clar\u00e9e\";\n\n  /* le pouls : deux chiffres, jamais plus (D2). Deux blocs DISTINCTS et\n     \u00e9tiquet\u00e9s \u2014 act\u00e9 et en cours ne se m\u00e9langent pas (\u00a73.4). Un gain nul ne\n     s'affiche pas : \u00ab 0 \u20ac \u00bb voudrait dire \u00ab rien \u00e0 gagner \u00bb (\u00a73.5). */\n  let pouls = \"\";\n  if(gl.gainActe > 0) pouls += `<span class=\"ca-acte\">+${fmtEuroCourt(gl.gainActe)}<small>/an act\u00e9</small></span>`;\n  if(gl.gainProjete > 0) pouls += `<span class=\"ca-projete\">+${fmtEuroCourt(gl.gainProjete)}<small>/an en cours</small></span>`;\n\n  /* le co\u00fbt \u00e9tiquet\u00e9 dominante (Q6-B) \u2014 ou son absence DITE (Q10).\n     4.60.1, revue sur donn\u00e9es r\u00e9elles : deux corrections de conformit\u00e9 \u2014\n     \u00b7 une ligne SANS r\u00e9f\u00e9rences ne dit pas \u00ab volume annuel \u00e0 saisir \u00bb : sa\n       pastille dit d\u00e9j\u00e0 \u00ab machines \u00e0 d\u00e9clarer \u00bb, la seconde invitation se\n       contredirait (sur l'\u00e9cran r\u00e9el, 6 tuiles_WEISSER/PCI portaient le double\n       message) ;\n     \u00b7 un co\u00fbt PARTIEL se d\u00e9clare (\u00a73.2 : un poste non chiffrable se d\u00e9clare, il\n       ne devient pas un co\u00fbt complet en silence) : \u00ab 0,763 \u20ac/pce \u00bb sur EMAG 1\n       ne couvrait pas les OP non chiffr\u00e9es sans le dire. */\n  let cout = \"\";\n  const nbNonChiffrees = gl.coutPiece ? (gl.coutPiece.nonChiffrees || []).length : 0;\n  if(!(l.references || []).length){\n    cout = \"\";\n  } else if(!gl.volumeDominante){\n    cout = `<div class=\"al-cout al-manque\">\u2014 <span>volume annuel \u00e0 saisir</span></div>`;\n  } else if(!gl.coutPiece){\n    cout = `<div class=\"al-cout al-manque\">\u2014 <span>aucune op\u00e9ration chiffr\u00e9e</span></div>`;\n  } else {\n    const autres = Math.max(0, (l.references || []).length - 1);\n    cout = `<div class=\"al-cout\">${escapeAttr(gl.refDominante.nom)} : <b>${fmt(gl.coutPiece.prod, 3)} \u20ac/pce</b>`\n         + (autres > 0 ? ` <span class=\"ca-refs\" title=\"${autres} autre(s) r\u00e9f\u00e9rence(s) sur cette ligne\">+${autres} r\u00e9f.</span>` : \"\")\n         + `</div>`;\n    if(nbNonChiffrees > 0){\n      cout += `<div class=\"al-manque\" style=\"margin-top:1px;\">hors ${nbNonChiffrees} op\u00e9ration${nbNonChiffrees > 1 ? \"s\" : \"\"} non chiffr\u00e9e${nbNonChiffrees > 1 ? \"s\" : \"\"}</div>`;\n    }\n    if(gl.coutPiece.chemin !== null){\n      cout += `<div class=\"ca-chemin\" title=\"Part du chemin vers la cible du site d\u00e9j\u00e0 parcourue sur la r\u00e9f\u00e9rence dominante\">\n        <div class=\"ca-track\"><div class=\"ca-fill\" style=\"width:${Math.round(gl.coutPiece.chemin)}%\"></div></div>\n        <span class=\"ca-pct\">${Math.round(gl.coutPiece.chemin)} % \u00b7 cible ${fmt(gl.coutPiece.cible, 3)} \u20ac</span></div>`;\n    }\n  }\n\n  /* le \u00e0-faire : les \u00e9tapes des postes NON gagn\u00e9s, deux max en clair \u2014 la\n     suite de prochaineEtapePoste() (4.54), d\u00e9duite, jamais stock\u00e9e. */\n  const aFaire = gl.etapes.filter(x => x.etat !== \"gagne\" && x.etat !== \"opportunite\");\n  const afTxt = aFaire.length\n    ? `<div class=\"al-afaire\"><span class=\"al-afaire-l\">\u00c0 faire</span>${aFaire.slice(0, 2).map(x =>\n        `<span>${escapeAttr(x.opCode)} \u2014 ${escapeAttr(x.texte)}</span>`).join(\"\")}`\n      + (aFaire.length > 2 ? `<span class=\"al-afaire-plus\">+${aFaire.length - 2} autre${aFaire.length > 3 ? \"s\" : \"\"}</span>` : \"\")\n      + `</div>`\n    : \"\";\n\n  /* v4.65.1 (C5\u2032 bloc 2) \u2014 le taux horaire SOURC\u00c9 de la ligne, \u00e0 c\u00f4t\u00e9 du nom ;\n     absent, il ne s'affiche pas (\u00a75.6 : pas de \u00ab \u2014 \u00bb d\u00e9coratif sur un d\u00e9tail). */\n  const th = parseFloat(l.coutHoraire);\n  const thTxt = !isNaN(th) && th > 0 ? ` <span class=\"al-taux\" title=\"Co\u00fbt horaire machine de la ligne\">${fmt(th, 0)} \u20ac/h</span>` : \"\";\n\n  /* le contexte en italique : LE fait le plus important, V\u00c9RIFIABLE \u2014 la\n     premi\u00e8re \u00e9tape en attente ; si tout est gagn\u00e9, le maintien \u00e0 revalider.\n     Jamais une phrase d'ambiance (spec C5 \u00a71.4). */\n  const contexte = aFaire.length\n    ? `${aFaire[0].opCode} \u2014 ${aFaire[0].texte}`\n    : (gl.etats.gagne > 0 ? `${gl.etats.gagne} poste${gl.etats.gagne > 1 ? \"s\" : \"\"} en production \u2014 \u00e0 revalider au prochain r\u00e9\u00e9quilibrage` : \"\");\n\n  /* gain unitaire + gain annuel C\u00d4TE \u00c0 C\u00d4TE (spec C5 \u00a71.4) : le \u0394 de CPP de la\n     dominante (prod \u2212 enCours \u2014 sourc\u00e9 pieceCPPComplet) \u00e0 c\u00f4t\u00e9 du gain annuel.\n     Sans \u0394 mesurable : rien, pas un 0 (\u00a75.6). */\n  let delta = null;\n  if(gl.coutPiece && gl.coutPiece.enCours !== undefined && gl.coutPiece.enCours < gl.coutPiece.prod){\n    delta = gl.coutPiece.prod - gl.coutPiece.enCours;\n  }\n  const deltaTxt = delta !== null\n    ? `<span class=\"al-delta\" title=\"\u00c9cart de co\u00fbt pi\u00e8ce d\u00e9j\u00e0 r\u00e9alis\u00e9 sur la r\u00e9f\u00e9rence dominante\">\u0394 ${fmt(delta, 4)} \u20ac/pce</span>` : \"\";\n\n  /* l'emplacement photo : PR\u00c9VU, VIDE \u2014 pas de photo fictive (spec C5 \u00a71.4,\n     on attend Matis). Un cadre discret qui dit ce qu'il attend. */\n  const photo = `<div class=\"al-photo\" title=\"Emplacement pr\u00e9vu pour la photo de la machine \u2014 aucune photo fictive\">photo machine \u00e0 fournir</div>`;\n\n  return `<div class=\"ca-tuile ${e.classe} al-tuile\" data-ligne=\"${escapeAttr(l.id)}\" tabindex=\"0\" role=\"button\" title=\"Voir cette ligne sur la carte atelier\">\n    <div class=\"ca-tete\"><span class=\"ca-titre\">${escapeAttr(l.nom || \"Ligne sans nom\")}${thTxt}</span><span class=\"ca-etat\">${escapeAttr(badge)}</span></div>\n    <div class=\"al-corps\">\n      ${photo}\n      <div class=\"al-flux\">\n        <div class=\"ca-ref-ligne\">${escapeAttr(refsTxt)}</div>\n        <div class=\"ca-pouls\">${pouls || '<span class=\"ca-vide\">\u2014</span>'}${deltaTxt}</div>\n        ${cout}\n      </div>\n    </div>\n    ${gl.etats.opportunite === (gl.postes || []).length && (gl.postes || []).length > 0 ? `<div class=\"ca-tentant\">d\u00e9clar\u00e9e, jamais travaill\u00e9e</div>` : \"\"}\n    ${contexte ? `<div class=\"al-contexte\">${escapeAttr(contexte)}</div>` : \"\"}\n    ${afTxt}\n    <div class=\"ca-actions\"><button class=\"primary small al-ouvrir\" data-ligne=\"${escapeAttr(l.id)}\">Voir l'atelier \u2192</button></div>\n  </div>`;\n}\n\n/* \u2550\u2550\u2550 v4.65.2 \u2014 C5\u2032 bloc 3 : la MATRICE des op\u00e9rations et le PIED \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   (spec C5 \u00a71.5 + \u00a71.6). L'\u00e9cran que la hi\u00e9rarchie regarde : une seule table,\n   toutes les lignes, tous les statuts \u2014 un flatMap sur les postes d\u00e9clar\u00e9s,\n   chaque chiffre sourc\u00e9 gainPoste(). \u00a73.5 : un poste non impact\u00e9 reste affich\u00e9\n   avec \u00b10,000 \u20ac ; \u00a73.4 : le gain de l'OP, jamais un cumul de projet\u00e9s ; les\n   statuts sont des mots ; tri stable par ligne puis par OP. */\nfunction accueilMatriceHTML(gls){\n  const MOTS = { gagne: \"gagn\u00e9\", encours: \"essais en cours\", aChiffrer: \"\u00e0 chiffrer\", opportunite: \"jamais travaill\u00e9\" };\n  const vivantes = gls.filter(gl => !ligneHorsPerimetre(gl));\n  const lignes_rows = vivantes.flatMap(gl =>\n    gl.postes.map(t => {\n      const p = t.poste;\n      /* le gain unitaire SOURC\u00c9 du poste : coutProd \u2212 coutEnCours (les deux\n         rendus par gainPoste, \u20ac/pce). Nul ou non chiffr\u00e9 : \u00b10,000 \u20ac \u00c9CRIT,\n         le poste ne dispara\u00eet pas (\u00a73.5). */\n      let delta = null;\n      if(p.coutProd > 0 && p.coutEnCours !== undefined && p.coutEnCours < p.coutProd) delta = p.coutProd - p.coutEnCours;\n      /* le gain annuel : act\u00e9 OU projet\u00e9, \u00c9TIQUET\u00c9 \u2014 jamais somm\u00e9s (\u00a73.4) */\n      let annuel = \"\";\n      if(p.gainActe > 0) annuel = `+${fmtEuroCourt(Math.round(p.gainActe))} /an <span class=\"mx-etq\">act\u00e9</span>`;\n      else if(p.gainProjete > 0) annuel = `+${fmtEuroCourt(Math.round(p.gainProjete))} /an <span class=\"mx-etq\">projet\u00e9</span>`;\n      else annuel = `<span class=\"mx-zero\">\u00b10,000 \u20ac</span>`;\n      const ref = p.refDominante ? p.refDominante.nom : \"\u2014\";\n      const nomMachine = t.poste.nom ? ` \u00b7 ${t.poste.nom}` : \"\";\n      return `<tr class=\"mx-${t.etat}\">\n        <td class=\"mx-ligne\">${escapeAttr(gl.ligne.nom)}</td>\n        <td class=\"mx-op\">${escapeAttr(p.opCode)}${nomMachine ? `<span class=\"mx-nom\">${escapeAttr(t.poste.nom)}</span>` : \"\"}</td>\n        <td class=\"mx-ref\">${escapeAttr(ref)}</td>\n        <td class=\"num\">${delta !== null ? fmt(delta, 4) + \" \u20ac/pce\" : `<span class=\"mx-zero\">\u00b10,000 \u20ac/pce</span>`}</td>\n        <td class=\"num\">${annuel}</td>\n        <td class=\"mx-statut\">${MOTS[t.etat] || t.etat}</td>\n        <td class=\"mx-porte\">${t.etat !== \"opportunite\" ? `<button class=\"ghost small mx-ouvrir\" data-ligne=\"${escapeAttr(gl.ligne.id)}\" data-code=\"${escapeAttr(p.opCode)}\">Ouvrir \u2192</button>` : `<span class=\"mx-zero\">\u2014</span>`}</td>\n      </tr>`;\n    }));\n  if(!lignes_rows.length) return \"\";\n  return `<h4 class=\"mx-titre\">Toutes les op\u00e9rations \u2014 la table que la hi\u00e9rarchie lit</h4>\n    <div class=\"tbl-wrap\"><table class=\"mt-tbl mx-tbl\">\n      <thead><tr><th>Ligne</th><th>Op\u00e9ration</th><th>R\u00e9f\u00e9rence</th><th class=\"num\">Gain unitaire</th><th class=\"num\">Gain annuel</th><th>Statut</th><th></th></tr></thead>\n      <tbody>${lignes_rows.join(\"\")}</tbody>\n    </table></div>\n    <p class=\"panel-hint\" style=\"margin-top:6px;\">Un poste non impact\u00e9 reste affich\u00e9 \u00e0 \u00b10,000 \u20ac (\u00a73.5) ; les gains act\u00e9s et projet\u00e9s\n      ne se m\u00e9langent jamais (\u00a73.4) ; le gain unitaire est l'\u00e9cart de co\u00fbt pi\u00e8ce du poste, sourc\u00e9.</p>`;\n}\n\n/* le pied : les PERSONNES qui portent le suivi (responsables r\u00e9els, sans r\u00f4le\n   invent\u00e9 \u2014 le mod\u00e8le n'en a pas), et les trois actions EXISTANTES expos\u00e9es :\n   on ne cr\u00e9e rien, on montre (spec C5 \u00a71.6). */\n/* \u2550\u2550\u2550 v4.78.0 \u2014 LA VUE CPP (Tour 49 : \u00ab \u00e0 Z Code de construire, \u00e0 Hermes de relire \u00bb) \u2550\u2550\u2550\n   La direction de Benjamin (constitution \u00a71, v1.9) : \u00ab op\u00e9ration par op\u00e9ration,\n   outil par outil, logement par logement \u00bb. La r\u00e8gle 2 quater (v1.10) :\n   JAMAIS le total de l'outil compar\u00e9 au CPP du classeur \u2014 le total inclut la\n   machine, le classeur l'ignore. Comparaison AXE PAR AXE :\n   \u00b7 OUTILLAGE = prix \u00f7 (ar\u00eates \u00d7 DDV) \u2014 LA mesure de Matis (colonne I) ;\n   \u00b7 TEMPS = (taux \u00f7 3600) \u00d7 cycle \u2014 affich\u00e9 \u00c0 C\u00d4T\u00c9, jamais m\u00eal\u00e9, seulement\n     quand les donn\u00e9es existent ; sinon la base reste l'outillage seul.\n   \u00c0 chaque niveau : le CPP obtenu, la r\u00e9f\u00e9rence Matis (cibleCPP, colonne I\n   somm\u00e9e par r\u00e9f\u00e9rence \u2014 06d831f), la cible, et l'\u00e9cart EN TOUTES LETTRES.\n   CONST AT PUR : lecture seule, rien n'\u00e9crit (compatible gel d'audit). */\n\n/* les donn\u00e9es de la vue, pures et testables : l'arbre entier en une passe */\nfunction vueCppData(){\n  const out = [];\n  lignes.forEach(l => {\n    if((l.references || []).length === 0) return; /* hors p\u00e9rim\u00e8tre : pas dans la vue */\n    (l.references || []).forEach(ref => {\n      /* l'axe OUTILLAGE de chaque OP : le sc\u00e9nario de prod (\u2605 puis excel),\n         plaquettes seules \u2014 coutsDetail().plaquettes, jamais le total */\n      const ops = [];\n      let cppObtenu = 0, nonChiffrees = 0, machine = null;\n      (ref.ops || []).forEach(op => {\n        const excel = (op.scenarios || []).find(x => /base excel/i.test(x.name || \"\"));\n        const star = (op.scenarios || []).find(x => x.baseline);\n        const prodSc = star || excel || null;\n        if(!prodSc){ nonChiffrees++; return; }\n        const det = coutsDetail(prodSc, undefined, l);\n        const outillage = det.plaquettes;\n        if(outillage === null || outillage === undefined){ nonChiffrees++; return; }\n        cppObtenu += outillage;\n        /* le meilleur sc\u00e9nario chiffrable, m\u00eame axe */\n        let meilleur = null;\n        (op.scenarios || []).forEach(sc => {\n          if(prodSc.id === sc.id) return;\n          const d2 = coutsDetail(sc, undefined, l);\n          if(d2.plaquettes === null || d2.plaquettes === undefined) return;\n          if(!meilleur || d2.plaquettes < meilleur.cout) meilleur = { sc, cout: d2.plaquettes };\n        });\n        ops.push({ op, outillage, meilleur,\n          outils: (prodSc.outils || []).map(o => ({\n            numero: o.numero, correcteur: o.correcteur || \"\",\n            cout: (o.logements || []).reduce((a, lg) => a + (posCost(lg) || 0), 0),\n            logements: (o.logements || []).map(lg => ({\n              nom: lg.nom, mabec: lg.mabec || lg.codeArticle || \"\", ref: lg.ref || \"\",\n              prix: lg.prix, aretes: lg.aretes, ddv: lg.charniere,\n              cout: posCost(lg)\n            }))\n          })) });\n        /* l'axe TEMPS : seulement si les donn\u00e9es existent, jamais m\u00eal\u00e9 */\n        const cm = det.machine;\n        if(cm !== null && cm !== undefined) machine = (machine || 0) + cm;\n      });\n      const cible = cibleCPPDe(ref);\n      out.push({ ligne: l, ref, ops, cppObtenu, nonChiffrees, machine,\n                 referenceMatis: cible, cible });\n    });\n  });\n  return out;\n}\n\n/* l'\u00e9cart, dit en atelier \u2014 jamais un chiffre nu (\u00a73.5) */\nfunction libelleEcartCpp(obtenu, reference){\n  if(reference === null) return { texte: \"aucune r\u00e9f\u00e9rence Matis sur cette pi\u00e8ce \u2014 colonne I vide dans le classeur\", attention: false };\n  const e = obtenu - reference;\n  if(Math.abs(e) < 0.0005) return { texte: \"conforme \u00e0 la r\u00e9f\u00e9rence Matis\", attention: false };\n  if(e < 0) return { texte: `${fmt(Math.abs(e), 4)} \u20ac SOUS la r\u00e9f\u00e9rence Matis`, attention: false };\n  return { texte: `${fmt(e, 4)} \u20ac AU-DESSUS de la r\u00e9f\u00e9rence Matis`, attention: true };\n}\n\nfunction vueCppHTML(){\n  const data = vueCppData();\n  if(!data.length) return `<p class=\"panel-hint\">Aucune ligne vivante : la vue CPP lit l'arbre\n    des r\u00e9f\u00e9rences d\u00e9clar\u00e9es.</p>`;\n  const lignesVue = data.map(d => {\n    const ecart = libelleEcartCpp(d.cppObtenu, d.referenceMatis);\n    const opsTxt = d.ops.map(o => {\n      const part = d.cppObtenu > 0 ? (o.outillage / d.cppObtenu) * 100 : 0;\n      const meilleurTxt = o.meilleur\n        ? `<span class=\"cpp-meilleur\">meilleur essai : ${fmt(o.meilleur.cout, 4)} \u20ac <small>(\u2212${fmt(Math.max(0, o.outillage - o.meilleur.cout), 4)} si pass\u00e9 en s\u00e9rie)</small></span>` : \"\";\n      const outilsTxt = (o.outils || []).map(u => {\n        const logs = (u.logements || []).map(lg =>\n          `<span class=\"cpp-log\">${escapeAttr(lg.nom || \"logement\")} \u00b7 ${lg.mabec ? escapeAttr(lg.mabec) : \"MABEC \u00e0 saisir\"} \u00b7 ${lg.cout !== null && lg.cout !== undefined ? fmt(lg.cout, 4) + \" \u20ac\" : \"\u2014 DDV \u00e0 saisir\"}</span>`).join(\"\");\n        return `<div class=\"cpp-outil\"><b>${escapeAttr(u.numero || \"outil\")}</b>${u.correcteur ? ` <span class=\"cpp-corr\">${escapeAttr(u.correcteur)}</span>` : \"\"}\n          <span class=\"cpp-outil-cout\">${u.cout ? fmt(u.cout, 4) + \" \u20ac\" : \"\u2014\"}</span>\n          <div class=\"cpp-logs\">${logs}</div></div>`;\n      }).join(\"\");\n      return `<details class=\"cpp-op\"><summary>\n        <span class=\"cpp-op-nom\">${escapeAttr(o.op.nom)}</span>\n        <span class=\"cpp-op-cout\">${fmt(o.outillage, 4)} \u20ac</span>\n        <span class=\"cpp-op-part\">${fmt(part, 0)} % de la pi\u00e8ce</span>\n        ${meilleurTxt}\n      </summary><div class=\"cpp-op-corps\">${outilsTxt}</div></details>`;\n    }).join(\"\");\n    return `<details class=\"cpp-ref\" open><summary>\n      <span class=\"cpp-ref-nom\">${escapeAttr(d.ligne.nom)} \u00b7 ${escapeAttr(d.ref.nom)}</span>\n      <span class=\"cpp-ref-cout\">${fmt(d.cppObtenu, 4)} \u20ac</span>\n      <span class=\"cpp-ref-ref\">${d.referenceMatis !== null ? \"r\u00e9f. Matis \" + fmt(d.referenceMatis, 4) + \" \u20ac\" : \"r\u00e9f. Matis : \u2014\"}</span>\n      <span class=\"cpp-ecart${ecart.attention ? \" cpp-ecart-att\" : \"\"}\">${escapeAttr(ecart.texte)}</span>\n    </summary>\n    <div class=\"cpp-ref-corps\">\n      ${d.machine !== null ? `<div class=\"cpp-machine\">\u23f1 temps valoris\u00e9 (taux ${escapeAttr(d.ligne.nom)}) : ${fmt(d.machine, 4)} \u20ac/pi\u00e8ce \u2014 <i>non comparable au classeur, il l'ignore</i></div>` : \"\"}\n      ${opsTxt}\n      ${d.nonChiffrees ? `<div class=\"cpp-nonchiffree\">\u26a0 ${d.nonChiffrees} OP non chiffrable${d.nonChiffrees > 1 ? \"s\" : \"\"} \u2014 hors du CPP affich\u00e9, l'\u00e9cart doit se voir (\u00a73.2)</div>` : \"\"}\n      ${d.referenceMatis === null ? `<div class=\"cpp-nonchiffree\">r\u00e9f\u00e9rence Matis absente : colonne I vide dans le classeur pour cette pi\u00e8ce (question pos\u00e9e \u00e0 Matis)</div>` : \"\"}\n    </div></details>`;\n  }).join(\"\");\n  return `<p class=\"mt-raz\"><b>Ce que cette vue mesure.</b> Le CPP outillage de chaque pi\u00e8ce \u2014\n    la m\u00eame mesure que le classeur de Matis (prix \u00f7 ar\u00eates \u00f7 DDV) \u2014 d\u00e9compos\u00e9 op\u00e9ration par\n    op\u00e9ration, outil par outil, logement par logement. La r\u00e9f\u00e9rence Matis en face, l'\u00e9cart en\n    toutes lettres. Le temps machine, quand il est chiffr\u00e9, s'affiche \u00e0 part : le classeur\n    l'ignore, on ne le compare jamais (constitution 2 quater).</p>\n    ${lignesVue}\n    <p class=\"panel-hint\" style=\"margin-top:10px;\">Lecture seule : cette vue n'\u00e9crit rien. D\u00e9pliez une pi\u00e8ce pour ses OP, une OP pour ses outils.</p>`;\n}\n\nfunction renderVueCpp(){\n  const wrap = document.getElementById(\"vueCppPanel\");\n  if(!wrap) return;\n  wrap.innerHTML = `<h3>Vue CPP \u2014 obtenu vs r\u00e9f\u00e9rence, \u00e0 chaque \u00e9tage</h3>` + vueCppHTML() +\n    `<div class=\"panel-actions\"><button class=\"primary\" id=\"vcClose\">Fermer</button></div>`;\n  const c = document.getElementById(\"vcClose\");\n  if(c) c.addEventListener(\"click\", fermerPanneaux);\n}\nfunction ouvrirVueCpp(){ renderVueCpp(); ouvrirPanneau(\"vueCppPanel\"); }\n\nfunction accueilPiedHTML(){\n  const gens = (responsables || []).filter(r => r.nom);\n  const gensTxt = gens.length\n    ? `<div class=\"pf-gens\"><span class=\"pf-lib\">L'\u00e9quipe du suivi</span>${gens.map(r =>\n        `<span class=\"pf-nom\" style=\"--c:${escapeAttr(r.couleur || \"var(--blue)\")}\">${escapeAttr(r.nom)}</span>`).join(\"\")}</div>`\n    : `<div class=\"pf-gens\"><span class=\"pf-lib\">L'\u00e9quipe du suivi</span><span class=\"mx-zero\">aucun responsable d\u00e9clar\u00e9 \u2014 Options \u2192 Responsables</span></div>`;\n  return `<div class=\"pf-pied\">\n    ${gensTxt}\n    <div class=\"pf-actions\">\n      <button class=\"ghost small\" id=\"pfCarte\" title=\"La carte atelier : chaque machine, son \u00e9tat, sa fiche\">Bilan atelier</button>\n      <button class=\"ghost small\" id=\"pfExport\" title=\"Enregistre un fichier .json \u00e0 archiver ou \u00e0 envoyer\">Exporter</button>\n      <button class=\"ghost small\" id=\"pfHisto\" title=\"Les sauvegardes automatiques pr\u00e9c\u00e9dentes\">Historique</button>\n      <button class=\"primary small\" id=\"pfVueCpp\" title=\"Le CPP obtenu vs la r\u00e9f\u00e9rence Matis, d\u00e9compos\u00e9 OP par OP, outil par outil, logement par logement\">\ud83d\udd0d Vue CPP</button>\n    </div>\n  </div>`;\n}\n\nfunction renderAccueil(){\n  const wrap = document.getElementById(\"accueilPanel\");\n  if(!wrap) return;\n  const gls = lignes.map(l => gainLigne(l, LIGNES_SEPT_FONS));\n  /* v4.61 \u2014 Q12 : les lignes hors p\u00e9rim\u00e8tre quittent la grille au rang d'une\n     ligne vivante : elles vivent ensemble dans UNE tuile group\u00e9e, \u00e0 la fin.\n     La grille ne dit plus \u00ab six choses \u00e0 faire \u00bb \u2014 la tuile dit leur nombre. */\n  const vivantes = gls.filter(gl => !ligneHorsPerimetre(gl));\n  const hors = gls.filter(ligneHorsPerimetre);\n  const tuiles = vivantes.map(accueilTuileHTML).join(\"\")\n    + (hors.length ? accueilHorsTuileHTML(hors) : \"\");\n\n  /* la recette A2 : l'\u00e9cran dit s'il sert \u2014 actionnable = la pastille n'est pas\n     \u00ab ouvert \u00bb. Le p\u00e9rim\u00e8tre compte les lignes VIVANTES ; les hors p\u00e9rim\u00e8tre\n     sont dites \u00e0 part, elles ne diluent pas le ratio. Sous 1/3 : creux, dit. */\n  const total = vivantes.length;\n  const actionnables = vivantes.filter(gl => etatLigne(gl).etat !== \"opportunite\").length;\n  const ratio = total ? actionnables / total : 0;\n  const recette = (total || hors.length)\n    ? `<div class=\"al-recette ${total && ratio < 1/3 ? \"al-recette-creuse\" : \"\"}\">`\n      + (total && ratio < 1/3 ? `\u00c9cran creux : ` : ``)\n      + `${actionnables} ligne${actionnables > 1 ? \"s\" : \"\"} actionnable${actionnables > 1 ? \"s\" : \"\"} sur ${total || 0} dans le p\u00e9rim\u00e8tre`\n      + (total && ratio < 1/3 ? ` \u2014 moins d'un tiers : cet \u00e9cran n'\u00e9claire pas encore l'usine` : ``)\n      + (hors.length ? ` \u00b7 ${hors.length} ligne${hors.length > 1 ? \"s\" : \"\"} hors p\u00e9rim\u00e8tre` : ``)\n      + `</div>`\n    : \"\";\n\n  wrap.innerHTML = `\n    <div class=\"bd-entete\">\n      <div class=\"bd-accent\"></div> <div class=\"bd-ariane\">parc usinage sept-fons \u00b7 lignes haute cadence</div>\n      <div class=\"bd-titre-ligne\">\n        <h3 class=\"bd-titre\">Tableau de bord des lignes d'usinage</h3>\n        <span class=\"bd-perimetre\">${escapeAttr(accueilPerimetreHTML(vivantes) || \"usine\")}</span>\n        <div class=\"bd-index ${total && ratio < 1/3 ? \"bd-index-surveiller\" : \"\"}\" title=\"La recette de l'\u00e9cran : les lignes qu'il \u00e9claire vraiment\">\n          ${total && ratio < 1/3 ? \"\u00e0 surveiller\" : \"conforme\"} \u00b7 ${actionnables}/${total || 0} actives${hors.length ? ` \u00b7 ${hors.length} hors p\u00e9rim\u00e8tre` : \"\"}\n        </div>\n      </div>\n      <p class=\"bd-sous\">L'usine par lignes : gains act\u00e9s et en cours dans deux blocs s\u00e9par\u00e9s, co\u00fbt pi\u00e8ce\n        \u00e9tiquet\u00e9 vers la cible du site, et la prochaine \u00e9tape de chaque machine \u2014 chaque chiffre\n        remonte \u00e0 sa source, chaque absence dit ce qui manque.</p>\n    </div>\n    ${accueilBandeauHTML(gls)}\n    <div class=\"ca-grille al-grille\">${tuiles}</div>\n    ${recette}\n    ${accueilMatriceHTML(gls)}\n    ${accueilPiedHTML()}\n    <div class=\"panel-actions\"><button class=\"primary\" id=\"alClose\">Fermer</button></div>`;\n\n  const fermer = document.getElementById(\"alClose\");\n  if(fermer) fermer.addEventListener(\"click\", fermerPanneaux);\n  wrap.querySelectorAll(\".al-ouvrir\").forEach(btn =>\n    btn.addEventListener(\"click\", ev => { ev.stopPropagation(); ouvrirCarte(btn.getAttribute(\"data-ligne\")); }));\n  wrap.querySelectorAll(\".al-tuile:not(.al-hors)\").forEach(t => {\n    t.addEventListener(\"click\", () => ouvrirCarte(t.getAttribute(\"data-ligne\")));\n    t.addEventListener(\"keydown\", ev => { if(ev.key === \"Enter\" || ev.key === \" \") { ev.preventDefault(); ouvrirCarte(t.getAttribute(\"data-ligne\")); } });\n  });\n  /* v4.65.2 \u2014 la porte de la matrice : m\u00eame m\u00e9canique que la carte (couche 2) */\n  wrap.querySelectorAll(\".mx-ouvrir\").forEach(b => {\n    b.addEventListener(\"click\", ev => {\n      ev.stopPropagation();\n      const ligne = lignes.find(x => x.id === b.getAttribute(\"data-ligne\"));\n      const code = b.getAttribute(\"data-code\");\n      if(!ligne) return;\n      const bloc = scenariosPostes(ligne, code)[0];\n      if(!bloc) return;\n      const prodSc = (bloc.scs || []).find(x => x.baseline)\n                  || (bloc.scs || []).find(x => /base excel/i.test(x.name || \"\"))\n                  || (bloc.scs || [])[0];\n      if(!prodSc) return;\n      activeLigneId = ligne.id; activeReferenceId = bloc.ref.id; activeOpId = bloc.op.id; activeId = prodSc.id;\n      fermerPanneaux(); render();\n    });\n  });\n  /* les trois actions du pied : les boutons EXISTANTS de la barre, expos\u00e9s \u2014\n     on ne cr\u00e9e pas de seconde impl\u00e9mentation */\n  const cCarte = document.getElementById(\"pfCarte\");\n  if(cCarte) cCarte.addEventListener(\"click\", ouvrirCarte);\n  const cExport = document.getElementById(\"pfExport\");\n  if(cExport) cExport.addEventListener(\"click\", () => { const b = document.getElementById(\"exportBtn\"); if(b) b.click(); });\n  const cHisto = document.getElementById(\"pfHisto\");\n  if(cHisto) cHisto.addEventListener(\"click\", () => { const b = document.getElementById(\"historyBtn\"); if(b) b.click(); });\n  /* v4.78 \u2014 la vue CPP : la porte depuis l'accueil, l\u00e0 o\u00f9 la hi\u00e9rarchie regarde */\n  const cCpp = document.getElementById(\"pfVueCpp\");\n  if(cCpp) cCpp.addEventListener(\"click\", ouvrirVueCpp);\n  /* la tuile hors p\u00e9rim\u00e8tre d\u00e9plie sa liste \u2014 le geste de Q12, pas la porte carte */\n  const thors = wrap.querySelector(\".al-hors\");\n  if(thors){\n    const toggle = () => { accueilHorsDeplie = !accueilHorsDeplie; renderAccueil(); };\n    thors.addEventListener(\"click\", toggle);\n    thors.addEventListener(\"keydown\", ev => { if(ev.key === \"Enter\" || ev.key === \" \") { ev.preventDefault(); toggle(); } });\n  }\n}\n\nfunction ouvrirAccueil(){ renderAccueil(); ouvrirPanneau(\"accueilPanel\"); }\n\n/* \u2550\u2550\u2550 v4.65.0 \u2014 C5\u2032 bloc 1 : l'en-t\u00eate et le BANDEAU de l'accueil \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   (spec DEMANDE_C5_ACCUEIL_TABLEAU_DE_BORD_A_ZCODE.md \u00a71.1 + \u00a71.3, d\u00e9cision\n   Benjamin). Le bandeau est le c\u0153ur du chantier et l'endroit de la plus grande\n   tentation d'inventer : les 4 chiffres de la capture Stitch sont TOUS faux\n   (le classeur de Matis dit 6 781 pi\u00e8ces, facteur 18). R\u00e8gle absolue (\u00a75.6) :\n   un bloc sans donn\u00e9e affiche \u00ab \u2014 \u00bb ET CE QUI MANQUE. Un bandeau avec deux\n   chiffres et deux tirets est correct ; quatre chiffres dont deux invent\u00e9s\n   sont un accident. Chaque chiffre se remonte \u00e0 sa source (gainLigne,\n   pieceCPPComplet, etatLigne) \u2014 jamais \u00e9crit en dur. */\n\n/* les familles r\u00e9ellement pr\u00e9sentes dans le p\u00e9rim\u00e8tre vivant, sourc\u00e9es :\n   \u00ab EMAG & HESSAPP \u00bb sur la capture devenait un mensonyme chez nous \u2014 on\n   \u00e9crit ce que les donn\u00e9es disent */\nfunction accueilPerimetreHTML(vivantes){\n  const fams = [];\n  vivantes.forEach(gl => {\n    const f = familleDeLigne(gl.ligne.nom || \"\");\n    if(f && !fams.includes(f)) fams.push(f);\n  });\n  const noms = fams.map(f => ({ weisser: \"WEISSER\", hessapp: \"HESSAPP\", emag: \"EMAG\", pci: \"PCI\" }[f] || f.toUpperCase()));\n  return noms.join(\" & \");\n}\n\nfunction accueilBandeauHTML(gls){\n  const vivantes = gls.filter(gl => !ligneHorsPerimetre(gl));\n\n  /* 1. \u00c9conomie valid\u00e9e : \u03a3 gainActe, p\u00e9rim\u00e8tre \u00c9CRIT \u2014 jamais \u00ab 100 % audit\u00e9 \u00bb */\n  const acte = vivantes.reduce((a, gl) => a + (gl.gainActe || 0), 0);\n  const nbActe = vivantes.filter(gl => (gl.gainActe || 0) > 0).length;\n  const bloc1 = nbActe\n    ? { v: `+${fmtEuroCourt(Math.round(acte))}`, u: \"/an\",\n        sub: `sur ${nbActe} ligne${nbActe > 1 ? \"s\" : \"\"} qualifi\u00e9e${nbActe > 1 ? \"s\" : \"\"} s\u00e9rie` }\n    : { v: \"\u2014\", u: \"\", sub: \"aucun gain act\u00e9 \u2014 premiers passages en s\u00e9rie en attente\" };\n\n  /* 2. Ralliement cible CPP : le reste \u00e0 capter, CALCUL\u00c9 par ligne chiffrable\n     (co\u00fbt prod de la dominante \u2212 sa cible) \u00d7 son volume. Les lignes \u00e0 cible\n     sans volume se comptent \u00e0 part : leur absence se dit, elle ne s'invente pas. */\n  let reste = 0, nbCible = 0, nbCibleSansVol = 0;\n  vivantes.forEach(gl => {\n    const cp = gl.coutPiece;\n    if(!cp || cp.cible === null) return;\n    if(!gl.volumeDominante){ nbCibleSansVol++; return; }\n    if(cp.prod > cp.cible){ reste += (cp.prod - cp.cible) * gl.volumeDominante; nbCible++; }\n  });\n  const bloc2 = nbCible\n    ? { v: `${fmtEuroCourt(Math.round(reste))}`, u: \"\u20ac/an restants\",\n        sub: `cible du site \u00b7 ${nbCible} ligne${nbCible > 1 ? \"s\" : \"\"} chiffr\u00e9e${nbCible > 1 ? \"s\" : \"\"}`\n            + (nbCibleSansVol ? ` \u00b7 ${nbCibleSansVol} cible sans volume` : \"\") }\n    : nbCibleSansVol\n      ? { v: \"\u2014\", u: \"\", sub: `cible pos\u00e9e sur ${nbCibleSansVol} ligne${nbCibleSansVol > 1 ? \"s\" : \"\"} \u2014 volume annuel \u00e0 saisir` }\n      : { v: \"\u2014\", u: \"\", sub: \"aucune cible CPP pos\u00e9e\" };\n\n  /* 3. Cadence : on n'a PAS de cadence mesur\u00e9e par ligne \u2014 on ne l'estime\n     jamais (volume \u00f7 heures serait une invention). Le tiret dit ce qui manque. */\n  const bloc3 = { v: \"\u2014\", u: \"\", sub: \"cadence non mesur\u00e9e \u2014 \u00e0 relever avec Matis\" };\n\n  /* 4. Lignes en engagement : un COMPTE de chez nous, avec les noms */\n  const engagees = vivantes.filter(gl => etatLigne(gl).etat !== \"opportunite\");\n  const noms = engagees.map(gl => gl.ligne.nom);\n  const bloc4 = engagees.length\n    ? { v: String(engagees.length), u: `/ ${vivantes.length} lignes`,\n        sub: noms.slice(0, 3).join(\" \u00b7 \") + (noms.length > 3 ? ` +${noms.length - 3}` : \"\") }\n    : { v: \"0\", u: `/ ${vivantes.length} lignes`, sub: \"aucune ligne en travail\" };\n\n  const bloc = (num, lib, b) => `\n    <div class=\"bd-bloc\" role=\"listitem\">\n      <div class=\"bd-lib\">${num} \u00b7 ${lib}</div>\n      <div class=\"bd-v\">${b.v}<small>${b.u}</small></div>\n      <div class=\"bd-sub\">${escapeAttr(b.sub)}</div>\n    </div>`;\n  return `<div class=\"bd-bandeau\" aria-label=\"Les quatre chiffres de l'atelier\">\n    ${bloc(\"01\", \"\u00c9conomie valid\u00e9e\", bloc1)}\n    ${bloc(\"02\", \"Ralliement cible CPP\", bloc2)}\n    ${bloc(\"03\", \"Cadence\", bloc3)}\n    ${bloc(\"04\", \"Lignes en engagement\", bloc4)}\n  </div>`;\n}\n\n/* \u2550\u2550\u2550 v4.61.0 \u2014 Q12 (Benjamin) : la tuile regroup\u00e9e des lignes HORS P\u00c9RIM\u00c8TRE \u2550\u2550\u2550\u2550\n   D\u00e9cision tranch\u00e9e le 30/09 : une seule tuile grise pour les lignes d\u00e9clar\u00e9es\n   sans r\u00e9f\u00e9rences NI machines \u2014 \u00ab 6 lignes hors p\u00e9rim\u00e8tre : Weisser 1\u20134, PCI 4\u20135 \u00bb \u2014\n   et un clic ouvre la liste. Le fond (Tour 19 d'Hermes) : les afficher une par une,\n   au m\u00eame poids visuel qu'EMAG 1, dirait qu'il y a six choses \u00e0 faire \u2014 il n'y en a\n   pas ; le regroupement ne cache rien, il dit la v\u00e9rit\u00e9 en une tuile qui porte leur\n   nombre. La ligne de choix explicite : d\u00e9clarer leurs machines, ou les sortir du\n   p\u00e9rim\u00e8tre \u2014 jamais une invitation \u00e0 la saisie impossible. */\n\n/* les noms des lignes hors p\u00e9rim\u00e8tre, compact\u00e9s par famille :\n   \u00ab WEISSER 1 \u00bb \u00d74 + \u00ab PCI 4 \u00bb + \u00ab PCI 5 \u00bb \u2192 \u00ab WEISSER 1\u20134 \u00b7 PCI 4\u20135 \u00bb */\nfunction plagesLignes(noms){\n  const familles = {}, ordre = [];\n  noms.forEach(n => {\n    const m = String(n).trim().match(/^(\\D+)\\s*(\\d+)?$/);\n    if(!m){ if(!(n in familles)){ familles[n] = []; ordre.push(n); } familles[n].push(null); return; }\n    const cle = m[1].trim().toUpperCase();\n    if(!(cle in familles)){ familles[cle] = []; ordre.push(cle); }\n    familles[cle].push(m[2] ? parseInt(m[2], 10) : null);\n  });\n  /* l'ordre des familles suit leur premi\u00e8re apparition (l'ordre des lignes du\n     suivi), pas l'alphabet : \u00ab WEISSER 1\u20134 \u00b7 PCI 4\u20135 \u00bb comme dans la d\u00e9cision */\n  return ordre.map(f => {\n    const numeros = familles[f].filter(x => x !== null).sort((a, b) => a - b);\n    const alias = familles[f].includes(null) ? [f] : [];\n    if(!numeros.length) return alias.join(\" \");\n    /* plages cons\u00e9cutives : 1,2,3,4 \u2192 \u00ab 1\u20134 \u00bb ; 4,5 \u2192 \u00ab 4\u20135 \u00bb */\n    const plages = [];\n    let deb = numeros[0], fin = numeros[0];\n    for(let i = 1; i <= numeros.length; i++){\n      if(numeros[i] === fin + 1){ fin = numeros[i]; continue; }\n      plages.push(deb === fin ? String(deb) : deb + \"\u2013\" + fin);\n      deb = fin = numeros[i];\n    }\n    return f + \" \" + plages.join(\", \") + (alias.length ? \" \u00b7 \" + alias.join(\" \") : \"\");\n  }).join(\" \u00b7 \");\n}\n\n/* une ligne est hors p\u00e9rim\u00e8tre quand elle ne porte NI r\u00e9f\u00e9rence NI machine :\n   rien \u00e0 piloter, rien \u00e0 lire \u2014 sa place est dans la tuile group\u00e9e, pas dans\n   la grille au m\u00eame rang qu'une ligne vivante */\nfunction ligneHorsPerimetre(gl){\n  return (gl.ligne.references || []).length === 0 && (gl.postes || []).length === 0;\n}\n\n/* l'\u00e9tat de d\u00e9pliage de la liste : m\u00e9moire du panneau */\nlet accueilHorsDeplie = false;\n\nfunction accueilHorsTuileHTML(gls){\n  const noms = gls.map(gl => gl.ligne.nom || \"?\");\n  const liste = accueilHorsDeplie\n    ? `<div class=\"al-hors-liste\">${noms.map(n => `<span>${escapeAttr(n)}</span>`).join(\"\")}\n        <span class=\"al-hors-choix\">Pour chacune : d\u00e9clarer ses machines quand elle entre dans le suivi, ou la retirer de la liste des lignes (Options) \u2014 mais jamais la laisser dire qu'il y a quelque chose \u00e0 faire.</span></div>`\n    : \"\";\n  return `<div class=\"ca-tuile opportunite al-tuile al-hors\" tabindex=\"0\" role=\"button\"\n      title=\"Ces lignes sont d\u00e9clar\u00e9es sans machines ni r\u00e9f\u00e9rences \u2014 hors p\u00e9rim\u00e8tre de pilotage\">\n    <div class=\"ca-tete\"><span class=\"ca-titre\">${gls.length} lignes hors p\u00e9rim\u00e8tre</span>\n      <span class=\"ca-etat\">${accueilHorsDeplie ? \"replier\" : \"voir la liste\"}</span></div>\n    <div class=\"ca-ref-ligne\">${escapeAttr(plagesLignes(noms))}</div>\n    <div class=\"ca-tentant\">d\u00e9clar\u00e9es, jamais travaill\u00e9es \u2014 aucune action en attente</div>\n    ${liste}\n  </div>`;\n}\n\n/* \u2500\u2500 v4.53 \u2014 LIVRAISONS : l'objet que la hi\u00e9rarchie lit (d\u00e9cision 3) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n   Une livraison = un instantan\u00e9 FIG\u00c9 des gains du plan, dat\u00e9 et nomm\u00e9. Elle ne se\n   recalcule jamais : les chiffres sont copi\u00e9s \u00e0 la cr\u00e9ation \u2014 c'est le document que\n   Matis montre \u00e0 sa hi\u00e9rarchie (\u00ab livr\u00e9 en date du\u2026, X \u20ac/an act\u00e9s \u00bb). Source unique :\n   creerLivraison consomme cartePostes(), exactement comme l'affichage de la carte. */\nfunction creerLivraison(nom){\n  const postes = cartePostes().filter(t => t.etat !== \"opportunite\");\n  const plan = postes.map(t => ({\n    ligne: t.ligne.nom || \"\", code: t.code, nom: t.nomMachine || t.code,\n    refDominante: (t.poste.refDominante && (t.poste.refDominante.ref ? t.poste.refDominante.ref.nom : t.poste.refDominante.nom)) || \"\",\n    gainActe: t.poste.gainActe || 0, gainProjete: t.poste.gainProjete || 0, etat: t.etat\n  }));\n  const cibles = lignes.flatMap(l => l.references.map(r => ({ ref: r.nom, cible: r.cibleCPP || null }))).filter(x => x.cible);\n  return normalizeLivraison({\n    id: \"lv\" + Date.now().toString(36), nom: nom || \"Livraison\",\n    date: new Date().toISOString().slice(0, 10), creePar: auteurNom || \"\",\n    gainsActes: plan.reduce((a, x) => a + x.gainActe, 0),\n    gainsProjetes: plan.reduce((a, x) => a + x.gainProjete, 0),\n    plan, cibles,\n    essais: postes.reduce((a, t) => a + ((t.poste.essaiOuvert) ? 1 : 0), 0)\n  });\n}\nfunction livraisonImpressionHTML(l){\n  const eur = v => fmtEuroCourt(Math.abs(v || 0)) + \"/an\";\n  const planRows = (l.plan || []).map(x =>\n    `<div class=\"m4-row\"><span class=\"m4-date\">${escapeAttr(x.ligne)}</span>` +\n    `<span class=\"m4-titre\">${escapeAttr(x.nom)} \u2014 ${escapeAttr(x.refDominante || \"\")}</span>` +\n    `<span class=\"m4-stat\">${x.gainActe > 0 ? \"act\u00e9 \" + eur(x.gainActe) : x.gainProjete > 0 ? \"en cours \" + eur(x.gainProjete) : \"\u00e0 chiffrer\"}</span></div>`).join(\"\");\n  const cibles = (l.cibles || []).map(c => escapeAttr(c.ref) + \" \" + fmt(c.cible, 3) + \" \u20ac\").join(\" \u00b7 \");\n  return `<div class=\"m4\">\n    <div class=\"m4-entete\">\n      <div><div class=\"m4-sur\">Livraison \u2014 ${escapeAttr(l.nom)}</div>\n      <div class=\"m4-titre2\">Suivi d'optimisation SPK by CeramTec \u00d7 Sept Fons \u2014 pilote : Matis Hernu \u00b7 partenaire outillage : SPK by CeramTec (Benjamin Rouquette)</div></div>\n      <div class=\"m4-date2\">Livr\u00e9 le ${escapeAttr(l.date || \"\")} \u2014 fig\u00e9, ne se recalcule pas</div>\n    </div>\n    <div class=\"m4-blocs\">\n      <div class=\"m4-bloc ok\"><div class=\"n\">${eur(l.gainsActes)}</div><div class=\"l\">Gains ACT\u00c9S \u2014 en production</div></div>\n      <div class=\"m4-bloc encours\"><div class=\"n\">${eur(l.gainsProjetes)}</div><div class=\"l\">EN COURS \u2014 valid\u00e9s ou en essai</div></div>\n    </div>\n    <h4 class=\"m4-h\">Le plan livr\u00e9 \u2014 poste par poste</h4>\n    ${planRows || `<div class=\"m4-row\"><span class=\"m4-titre\">aucun poste</span></div>`}\n    <h4 class=\"m4-h\">Cibles du site</h4>\n    <div class=\"m4-row\"><span class=\"m4-titre\">${cibles || \"non renseign\u00e9es\"}</span></div>\n    <div class=\"m4-proto\">${escapeAttr(l.protocole || \"\")}</div>\n  </div>`;\n}\nfunction livraisonsSectionHTML(){\n  const rows = (livraisons || []).slice().sort((a, b) => (b.date || \"\").localeCompare(a.date || \"\")).map(l =>\n    `<div class=\"lv-row\">\n      <span class=\"lv-nom\">\ud83d\udce6 ${escapeAttr(l.nom)}</span>\n      <span class=\"lv-date\">${escapeAttr(l.date || \"\")} \u00b7 ${l.creePar || \"\u2014\"}</span>\n      <span class=\"lv-gains\">${l.gainsActes > 0 ? eurTxt(l.gainsActes) + \" act\u00e9s\" : \"\"}${l.gainsActes > 0 && l.gainsProjetes > 0 ? \" \u00b7 \" : \"\"}${l.gainsProjetes > 0 ? eurTxt(l.gainsProjetes) + \" en cours\" : \"\"}</span>\n      <button class=\"ghost small lv-print\" data-lv=\"${escapeAttr(l.id)}\" title=\"Imprimer l'A4 de cette livraison\">\ud83d\udda8</button>\n      <button class=\"ghost small lv-del\" data-lv=\"${escapeAttr(l.id)}\" title=\"Supprimer cette livraison (les donn\u00e9es des sc\u00e9narios ne sont pas touch\u00e9es)\">\ud83d\uddd1</button>\n    </div>`).join(\"\");\n  return `<div class=\"lv-bloc\">\n    <div class=\"lv-tete\">\n      <b>\ud83d\udce6 Livraisons \u2014 le dossier hi\u00e9rarchie</b>\n      <button class=\"primary small\" id=\"lvCreer\">\ud83d\udce6 Nouvelle livraison \u2014 figer les gains du jour</button>\n    </div>\n    ${rows || `<p class=\"panel-hint\">Aucune livraison : clique ci-dessus pour figer les gains du jour dans un document dat\u00e9 \u2014 celui que la hi\u00e9rarchie lit.</p>`}\n  </div>`;\n}\nfunction eurTxt(v){ return fmtEuroCourt(Math.abs(v || 0)) + \"/an\"; }\n\n/* \u2500\u2500 v4.79 \u2014 A4 MISSION : le livrable hi\u00e9rarchie, VIVANT \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n   Le bouton \u00ab \ud83d\udda8 A4 Mission \u00bb (v4.52) promettait cet imprimable depuis la carte\n   atelier ; la fonction n'existait pas \u2014 clic mort diagnostiqu\u00e9 par Hermes\n   (Tour 50-51), \u00e9crit ici. Ce que la page dit, exactement comme le sp\u00e9cifie la\n   ligne NOUVEAUTES d'alors : les gains ACT\u00c9S et EN COURS, la timeline des\n   essais r\u00e9cents avec leur statut, et le plan poste par poste avec la\n   prochaine \u00e9tape. Source unique (\u00a73.1) : cartePostes()/gainPoste(), comme la\n   carte et comme creerLivraison \u2014 jamais un recalcul local, jamais un chiffre\n   divergent. La diff\u00e9rence avec la livraison est \u00e9crite sur la page : la\n   livraison FIGE, la mission RECALCULE \u00e0 chaque \u00e9dition. */\nfunction essaisRecents(n){\n  const out = [];\n  lignes.forEach(l => {\n    (l.references || []).forEach(r => {\n      (r.ops || []).forEach(o => {\n        (o.scenarios || []).forEach(sc => {\n          (sc.essais || []).forEach(es => {\n            out.push({ date: es.date || \"\", ligne: l.nom || \"\", opCode: o.opCode || o.nom || \"\",\n                       scNom: sc.name || \"\", titre: es.titre || \"\", statut: (essaiStats(sc, es) || {}).status || \"pending\" });\n          });\n        });\n      });\n    });\n  });\n  out.sort((a, b) => (b.date || \"\").localeCompare(a.date || \"\"));\n  return out.slice(0, n || 8);\n}\nfunction missionA4HTML(){\n  const eur = v => fmtEuroCourt(Math.abs(v || 0)) + \"/an\";\n  /* m\u00eame source que creerLivraison : les postes r\u00e9els, opportunit\u00e9s exclues \u2014\n     une tuile jamais travaill\u00e9e ne promet rien, elle n'a pas sa page */\n  const postes = cartePostes().filter(t => t.etat !== \"opportunite\");\n  const gainsActes = postes.reduce((a, t) => a + (t.poste.gainActe || 0), 0);\n  const gainsProjetes = postes.reduce((a, t) => a + (t.poste.gainProjete || 0), 0);\n  const planRows = postes.map(t => {\n    const p = t.poste;\n    const ref = (p.refDominante && ((p.refDominante.ref && p.refDominante.ref.nom) || p.refDominante.nom)) || \"\";\n    const statutTxt = p.gainActe > 0 ? \"act\u00e9 \" + eur(p.gainActe)\n                     : p.gainProjete > 0 ? \"en cours \" + eur(p.gainProjete)\n                     : t.etat === \"aChiffrer\" ? \"\u00e0 chiffrer\" : \"\u2014\";\n    return `<div class=\"m4-row\"><span class=\"m4-date\">${escapeAttr(t.ligne.nom || \"\")}</span>` +\n      `<span class=\"m4-titre\">${escapeAttr(t.nomMachine || t.code)} \u2014 ${escapeAttr(ref || \"\")}</span>` +\n      `<span class=\"m4-stat\">${statutTxt}</span></div>`;\n  }).join(\"\");\n  const essaisRows = essaisRecents(8).map(e => {\n    const stTxt = e.statut === \"ok\" ? \"conforme\" : e.statut === \"bad\" ? \"non conforme\" : e.statut === \"arrete\" ? \"arr\u00eat\u00e9\" : \"en cours\";\n    return `<div class=\"m4-row\"><span class=\"m4-date\">${escapeAttr(e.date || \"\u2014\")}</span>` +\n      `<span class=\"m4-titre\">${escapeAttr(e.ligne)} \u00b7 ${escapeAttr(e.opCode)} \u2014 ${escapeAttr(e.scNom)} \u00b7 ${escapeAttr(e.titre)}</span>` +\n      `<span class=\"m4-stat${e.statut === \"bad\" ? \" bad\" : \"\"}\">${stTxt}</span></div>`;\n  }).join(\"\");\n  const etapesRows = postes.filter(t => t.etat !== \"gagne\").slice(0, 6).map(t =>\n    `<div class=\"m4-row\"><span class=\"m4-date\">${escapeAttr(t.ligne.nom || \"\")}</span>` +\n    `<span class=\"m4-titre\">${escapeAttr(t.nomMachine || t.code)} \u2014 ${escapeAttr(prochaineEtapePoste(t))}</span></div>`).join(\"\");\n  return `<div class=\"m4\">\n    <div class=\"m4-entete\">\n      <div><div class=\"m4-sur\">Mission \u2014 A4</div>\n      <div class=\"m4-titre2\">Suivi d'optimisation SPK by CeramTec \u00d7 Sept Fons \u2014 pilote : Matis Hernu \u00b7 partenaire outillage : SPK by CeramTec (Benjamin Rouquette)</div></div>\n      <div class=\"m4-date2\">\u00c9dit\u00e9 le ${new Date().toLocaleDateString(\"fr-FR\")} \u2014 vivant, recalcul\u00e9 \u00e0 chaque \u00e9dition</div>\n    </div>\n    <div class=\"m4-blocs\">\n      <div class=\"m4-bloc ok\"><div class=\"n\">${eur(gainsActes)}</div><div class=\"l\">Gains ACT\u00c9S \u2014 en production</div></div>\n      <div class=\"m4-bloc encours\"><div class=\"n\">${eur(gainsProjetes)}</div><div class=\"l\">EN COURS \u2014 valid\u00e9s ou en essai</div></div>\n    </div>\n    <h4 class=\"m4-h\">Le plan \u2014 poste par poste</h4>\n    ${planRows || `<div class=\"m4-row\"><span class=\"m4-titre\">aucun poste chiffr\u00e9 pour l'instant</span></div>`}\n    <h4 class=\"m4-h\">Essais r\u00e9cents \u2014 timeline avec statut</h4>\n    ${essaisRows || `<div class=\"m4-row\"><span class=\"m4-titre\">aucun essai relev\u00e9 pour l'instant</span></div>`}\n    ${etapesRows ? `<h4 class=\"m4-h\">Prochaines \u00e9tapes</h4>${etapesRows}` : \"\"}\n    <div class=\"m4-proto\">Protocole du site : tout essai concluant est r\u00e9p\u00e9t\u00e9 5\u00d7 ; valid\u00e9 5\u00d7 et viable \u00e9conomiquement, il passe en production. Document interne au projet \u2014 pilote Matis Hernu, partenaire outillage SPK by CeramTec.</div>\n  </div>`;\n}\n\n/* Filtre du tableau de bord (v4.1) : null = tous les scenarios, sinon l'id d'un projet --\n\n/* Filtre du tableau de bord (v4.1) : null = tous les scenarios, sinon l'id d'un projet --\n   seuls les scenarios etiquetes dans ce projet apparaissent. Par defaut \"tous\", meme quand\n   un projet est ouvert dans le bandeau superieur : le tableau de bord sert a garder la vue\n   d'ensemble, le cloisonnement est une option qu'on choisit ici, pas un etat qu'on subit. */\nlet dashboardFiltreProjetId = null;\n\nfunction renderDashboard(){\n  const wrap = document.getElementById(\"dashboardPanel\");\n  if(!wrap) return;\n  const pjFiltre = dashboardFiltreProjetId && projets.find(x => x.id === dashboardFiltreProjetId);\n\n  let nbSuivis = 0, nbValides = 0, nbSerie = 0, gainAcquis = 0, gainPotentiel = 0, volumeConnu = false;\n  const sections = [];\n\n  lignes.forEach(ligne => {\n    const blocsRef = [];\n    ligne.references.forEach(ref => {\n      ref.ops.forEach(op => {\n        const scsTotal = op.scenarios || [];\n        let scs = scsTotal;\n        if(pjFiltre) scs = scs.filter(sc => projetContientScenario(pjFiltre, ligne.id, ref.id, op.id, sc.id));\n        if(!scs.length) return;\n        // repere de lecture (v4.2) : quand un OP porte des scenarios de plusieurs projets a\n        // la fois, on le signale ici plutot que de forcer a ouvrir chaque carte de scenario\n        // une par une pour le decouvrir. Calcule sur TOUS les scenarios de l'OP, pas\n        // seulement ceux affiches sous le filtre courant -- sinon un filtre sur un seul\n        // projet masquerait la cohabitation qu'il sert justement a signaler.\n        const projetsIci = projets.filter(pj => scsTotal.some(sc => projetContientScenario(pj, ligne.id, ref.id, op.id, sc.id)));\n        const rows = dansContexteOp(op, () => {\n          const base = baselineScenario();\n          const cBase = base ? coutsDetail(base, op.config, ligne) : null;\n          return scs.map(sc => {\n            const couts = coutsDetail(sc, op.config, ligne);\n            const stats = scenarioStats(sc);\n            const an = bilanAnnuel(sc, op.config, ligne, ref);\n            const dPct = (!sc.baseline && cBase && cBase.total && couts.total !== null)\n              ? ((couts.total - cBase.total) / cBase.total) * 100 : null;\n            return { sc, couts, stats, dPct, gainAnnuel: an && an.gainAnnuel !== undefined ? an.gainAnnuel : null,\n                     volume: an ? an.volume : null };\n          });\n        });\n\n        rows.forEach(r => {\n          const st = r.sc.statut || \"essai\";\n          if(!r.sc.baseline && st !== \"abandonne\") nbSuivis++;\n          if(st === \"valide\") nbValides++;\n          if(st === \"serie\" && !r.sc.baseline) nbSerie++;\n          if(r.volume) volumeConnu = true;\n          if(r.gainAnnuel !== null){\n            if(st === \"serie\") gainAcquis += r.gainAnnuel;\n            else if(st === \"valide\") gainPotentiel += r.gainAnnuel;\n          }\n        });\n\n        const lignesHtml = rows.map(r => {\n          const st = r.sc.statut || \"essai\";\n          const seuil = r.sc.validationThreshold || \"\u2014\";\n          const pct = r.sc.validationThreshold ? Math.min(100, r.stats.validCount/parseFloat(r.sc.validationThreshold)*100) : 0;\n          const deltaTxt = r.sc.baseline ? `<span class=\"delta zero\">r\u00e9f.</span>`\n            : r.dPct === null ? \"\u2014\"\n            : `<span class=\"delta ${r.dPct < -0.05 ? \"neg\" : r.dPct > 0.05 ? \"pos\" : \"zero\"}\">${r.dPct>0?\"+\":\"\"}${fmt(r.dPct,1)} %</span>`;\n          const gainTxt = r.gainAnnuel === null ? \"\u2014\"\n            : `<b style=\"color:${r.gainAnnuel >= 0 ? \"var(--green)\" : \"var(--red)\"};\">${(r.gainAnnuel>=0?\"+\":\"\u2212\") + fmtEuroCourt(Math.abs(r.gainAnnuel))}</b>`;\n          return `<tr>\n            <td><span class=\"db-sc-nom\">${escapeAttr(r.sc.name)}</span>${r.sc.baseline ? ` <span class=\"db-ref-tag\">\u2605</span>` : \"\"}\n                ${st === \"abandonne\" && r.sc.statutMotif ? `<div class=\"db-motif\">${escapeAttr(r.sc.statutMotif)}</div>` : \"\"}</td>\n            <td><span class=\"statut-pill ${st}\">${statutLabel(st)}</span></td>\n            <td class=\"num\"><span class=\"db-prog\">${r.stats.validCount}/${seuil}</span>\n                <div class=\"progress-track small\"><div class=\"progress-fill ${r.stats.validated?\"ok\":\"\"}\" style=\"width:${pct}%;\"></div></div></td>\n            <td class=\"num\">${r.couts.total === null ? \"\u2014\" : fmt(r.couts.total,4)}</td>\n            <td class=\"num\">${deltaTxt}</td>\n            <td class=\"num\">${gainTxt}</td>\n          </tr>`;\n        }).join(\"\");\n\n        blocsRef.push(`\n          <div class=\"db-op\">\n            <div class=\"db-op-head\">\n              <span class=\"db-op-ref\">${escapeAttr(ref.nom || \"R\u00e9f\u00e9rence sans nom\")}</span>\n              <span class=\"db-op-nom\">${escapeAttr(op.nom || \"OP\")}</span>\n              ${rows[0] && rows[0].volume ? `<span class=\"db-op-vol\">${fmt(rows[0].volume,0)} disques/an</span>` : \"\"}\n              ${projetsIci.length > 1 ? `<span class=\"db-op-projets\">${projetsIci.map(pj =>\n                `<span class=\"tag-pill on\" style=\"background:${couleurProjet(pj)}; border-color:${couleurProjet(pj)};\">${escapeAttr(pj.nom)}</span>`).join(\"\")}</span>` : \"\"}\n            </div>\n            <div class=\"tbl-wrap\">\n              <table class=\"db-table\">\n                <thead><tr><th>Sc\u00e9nario</th><th>Statut</th><th class=\"num\">Essais</th><th class=\"num\">\u20ac/pi\u00e8ce</th><th class=\"num\">\u00c9cart</th><th class=\"num\">Gain/an</th></tr></thead>\n                <tbody>${lignesHtml}</tbody>\n              </table>\n            </div>\n          </div>`);\n      });\n    });\n    if(!blocsRef.length) return;\n    const infos = [];\n    if(ligne.coutHoraire !== \"\" && !isNaN(parseFloat(ligne.coutHoraire))) infos.push(fmt(parseFloat(ligne.coutHoraire),2) + \" \u20ac/h\");\n    if(ligne.maintenanceDate) infos.push(\"derni\u00e8re maintenance \" + ligne.maintenanceDate + (ligne.maintenanceType ? \" (\" + escapeAttr(ligne.maintenanceType) + \")\" : \"\"));\n    sections.push(`\n      <section class=\"db-ligne\">\n        <h3 class=\"db-ligne-titre\">${escapeAttr(ligne.nom || \"Ligne sans nom\")}${infos.length ? `<span class=\"db-ligne-info\">${infos.join(\" \u00b7 \")}</span>` : \"\"}</h3>\n        ${blocsRef.join(\"\")}\n      </section>`);\n  });\n\n  const kpis = `\n    <div class=\"db-kpis\">\n      <div class=\"db-kpi\"><span class=\"l\">Optimisations suivies</span><span class=\"v\">${nbSuivis}</span></div>\n      <div class=\"db-kpi\"><span class=\"l\">Valid\u00e9es, pas encore en s\u00e9rie</span><span class=\"v\">${nbValides}</span></div>\n      <div class=\"db-kpi\"><span class=\"l\">Pass\u00e9es en s\u00e9rie</span><span class=\"v\">${nbSerie}</span></div>\n      ${volumeConnu ? `\n      <div class=\"db-kpi db-kpi-gain\"><span class=\"l\">Gain annuel acquis</span><span class=\"v\" style=\"color:${gainAcquis>=0?\"var(--fill-ink)\":\"var(--on-fill-bad)\"};\">${(gainAcquis>=0?\"+\":\"\u2212\")+fmtEuroCourt(Math.abs(gainAcquis))}</span><span class=\"db-kpi-sub\">sc\u00e9narios en s\u00e9rie</span></div>\n      <div class=\"db-kpi db-kpi-gain\"><span class=\"l\">Gain annuel \u00e0 d\u00e9ployer</span><span class=\"v\">${(gainPotentiel>=0?\"+\":\"\u2212\")+fmtEuroCourt(Math.abs(gainPotentiel))}</span><span class=\"db-kpi-sub\">valid\u00e9s, pas encore en s\u00e9rie</span></div>` : \"\"}\n    </div>`;\n\n  const filtreHTML = projets.length ? `\n    <div class=\"db-filtre\">\n      <label for=\"dbFiltreProjet\">Projet</label>\n      <select id=\"dbFiltreProjet\">\n        <option value=\"\">Tous les projets</option>\n        ${projets.map(pj => `<option value=\"${pj.id}\" ${pj.id===dashboardFiltreProjetId?\"selected\":\"\"}>${escapeAttr(pj.nom)}</option>`).join(\"\")}\n      </select>\n    </div>` : \"\";\n\n  wrap.innerHTML = `\n    <h3>Tableau de bord</h3>\n    ${filtreHTML}\n    ${(() => {\n      // bandeau d'avertissement (v4.5) : vue tous projets, des scenarios du MEME NOM en\n      // serie sur la MEME ligne mais etiquetes dans plusieurs projets = peut-etre le meme\n      // changement physique suivi deux fois, et le gain annuel s'additionne sans le savoir\n      if(pjFiltre || projets.length < 2) return \"\";\n      const hom = scenariosSerieHomonymes();\n      if(!hom.length) return \"\";\n      return `<div class=\"db-alerte-homonymes\">\n        <b>Sc\u00e9narios du m\u00eame nom \u00ab en s\u00e9rie \u00bb sur une m\u00eame ligne, dans plusieurs projets :</b>\n        ${hom.map(x => escapeAttr(x.nom + \" (\" + x.ligne + \") \u2014 \" + [...new Set(x.projets)].join(\", \"))).join(\" \u00b7 \")}<br>\n        Le gain annuel s'additionne projet par projet : si c'est le m\u00eame changement physique suivi deux fois, il est compt\u00e9 deux fois. Gardez \u00ab en s\u00e9rie \u00bb dans un seul projet.\n      </div>`;\n    })()}\n    <p class=\"panel-hint\">${pjFiltre ? `Sc\u00e9narios \u00e9tiquet\u00e9s dans \u00ab ${escapeAttr(pjFiltre.nom)} \u00bb uniquement.` : \"Toutes les lignes, r\u00e9f\u00e9rences et OP du fichier.\"} Les gains annuels n'apparaissent que pour les r\u00e9f\u00e9rences dont le volume de production est renseign\u00e9 (module <b>Volume annuel</b> dans Options).</p>\n    ${kpis}\n    ${sections.join(\"\") || `<p class=\"panel-hint\">Aucun sc\u00e9nario ${pjFiltre ? \"\u00e9tiquet\u00e9 dans ce projet\" : \"enregistr\u00e9\"}.</p>`}\n    <div class=\"panel-actions\"><button class=\"primary\" id=\"dashboardClose\">Fermer</button></div>\n  `;\n  const btn = document.getElementById(\"dashboardClose\");\n  if(btn) btn.addEventListener(\"click\", fermerPanneaux);\n  const sel = document.getElementById(\"dbFiltreProjet\");\n  if(sel) sel.addEventListener(\"change\", () => { dashboardFiltreProjetId = sel.value || null; renderDashboard(); });\n}\n\n/* Informations de ligne \u2014 cout horaire, observations, derniere maintenance */\nlet ligneInfoTargetId = null;\nfunction ouvrirLigneInfo(ligneId){\n  const l = lignes.find(x => x.id === ligneId);\n  if(!l) return;\n  ligneInfoTargetId = ligneId;\n  document.getElementById(\"ligneInfoTitle\").textContent = \"Informations \u2014 \" + (l.nom || \"ligne\");\n  document.getElementById(\"ligneCoutHoraire\").value = l.coutHoraire ?? \"\";\n  document.getElementById(\"ligneObservations\").value = l.observations ?? \"\";\n  document.getElementById(\"ligneMaintenanceDate\").value = l.maintenanceDate ?? \"\";\n  document.getElementById(\"ligneMaintenanceType\").value = l.maintenanceType ?? \"\";\n  ouvrirPanneau(\"ligneInfoPanel\");\n}\nfunction appliquerLigneInfo(){\n  const l = lignes.find(x => x.id === ligneInfoTargetId);\n  if(!l) return;\n  l.coutHoraire = document.getElementById(\"ligneCoutHoraire\").value;\n  l.observations = document.getElementById(\"ligneObservations\").value;\n  l.maintenanceDate = document.getElementById(\"ligneMaintenanceDate\").value;\n  l.maintenanceType = document.getElementById(\"ligneMaintenanceType\").value;\n  saveData();\n}\n[\"ligneCoutHoraire\",\"ligneObservations\",\"ligneMaintenanceDate\",\"ligneMaintenanceType\"].forEach(id => {\n  document.getElementById(id).addEventListener(\"change\", appliquerLigneInfo);\n});\ndocument.getElementById(\"ligneInfoClose\").addEventListener(\"click\", () => { appliquerLigneInfo(); fermerPanneaux(); });\n\n/* Impression \u2014 choix du contenu */\ndocument.getElementById(\"pdfBtn\").addEventListener(\"click\", () => ouvrirPanneau(\"printPanel\"));\ndocument.getElementById(\"printCancel\").addEventListener(\"click\", fermerPanneaux);\ndocument.getElementById(\"prtActifSeul\").addEventListener(\"change\", renderAll);\n\ndocument.getElementById(\"printGo\").addEventListener(\"click\", () => {\n  const b = document.body;\n  b.classList.toggle(\"no-plaquettes\", !document.getElementById(\"prtPlaquettes\").checked);\n  b.classList.toggle(\"no-essais\",     !document.getElementById(\"prtEssais\").checked);\n  b.classList.toggle(\"no-graph\",      !document.getElementById(\"prtGraph\").checked);\n  b.classList.toggle(\"no-rebut\",      !document.getElementById(\"prtRebut\").checked);\n  renderAll();\n  const src = document.querySelector(\".hd-left img\").getAttribute(\"src\");\n  document.getElementById(\"printLogo\").setAttribute(\"src\", src);\n  document.getElementById(\"printDate\").textContent = new Date().toLocaleDateString(\"fr-FR\");\n  fermerPanneaux();\n  setTimeout(() => window.print(), 60);\n});\n\ndocument.getElementById(\"exportBtn\").addEventListener(\"click\", exportData);\nfunction csvPanelHTML(){\n  const sc = data.find(s => s.id === activeId);\n  const essais = sc ? (sc.essais||[]) : [];\n  const rows = essais.map(es => `\n    <label class=\"opt-row simple\" style=\"cursor:pointer;\">\n      <input type=\"checkbox\" class=\"csv-essai-chk\" value=\"${es.id}\" checked>\n      <span><b>${escapeAttr(es.titre)}</b><em>${es.date ? escapeAttr(es.date) + \" \u2014 \" : \"\"}${(es.prelevements||[]).length} pr\u00e9l\u00e8vement(s)</em></span>\n    </label>\n  `).join(\"\") || `<p class=\"panel-hint\">Ce sc\u00e9nario n'a encore aucun essai.</p>`;\n  return `\n    <h3>Export CSV \u2014 ${escapeAttr(sc ? sc.name : \"\")}</h3>\n    <p class=\"panel-hint\">Choisissez les essais \u00e0 inclure (d\u00e9cochez ceux \u00e0 laisser de c\u00f4t\u00e9, par exemple un essai de d\u00e9mo ou un doublon).</p>\n    ${rows}\n    <div class=\"panel-actions\">\n      <button class=\"ghost\" id=\"csvCancel\">Annuler</button>\n      <button class=\"save\" id=\"csvGo\" ${essais.length ? \"\" : \"disabled\"}>\ud83d\udcca Exporter</button>\n    </div>\n  `;\n}\nfunction renderCsvPanel(){\n  const wrap = document.getElementById(\"csvPanel\");\n  if(!wrap || wrap.hidden) return;\n  wrap.innerHTML = csvPanelHTML();\n  const closeIt = () => fermerPanneaux();\n  document.getElementById(\"csvCancel\").addEventListener(\"click\", closeIt);\n  const goBtn = document.getElementById(\"csvGo\");\n  if(goBtn) goBtn.addEventListener(\"click\", () => {\n    const ids = [...wrap.querySelectorAll(\".csv-essai-chk:checked\")].map(c => c.value);\n    if(!ids.length){ dialogueAlerte(\"Cochez au moins un essai.\", \"Rien \u00e0 exporter\"); return; }\n    fermerPanneaux();\n    exportCSV(ids);\n  });\n}\n\n/* ---- v4.22 \u2014 panneau de s\u00e9lection pour la copie des outils de la production ---- */\nfunction renderCopieOutilsPanel(){\n  const wrap = document.getElementById(\"copieOutilsPanel\");\n  if(!wrap || wrap.hidden) return;\n  const sc = data.find(s => s.id === activeId);\n  const base = baselineScenario();\n  if(!sc || !base || base.id === sc.id){ fermerPanneaux(); return; }\n  const rows = base.outils.map(o => `\n    <label class=\"copie-outil-row\">\n      <input type=\"checkbox\" class=\"copie-outil-chk\" value=\"${o.id}\" checked>\n      <span class=\"copie-outil-titre\"><b>${escapeAttr(o.numero || \"outil sans n\u00b0\")}</b>${o.description ? \" \u2014 \" + escapeAttr(o.description) : \"\"}</span>\n      <span class=\"copie-outil-log\">${o.logements.map(l => escapeAttr(l.nom || \"\u2014\")).join(\" + \") || \"aucun logement\"}</span>\n    </label>`).join(\"\");\n  wrap.innerHTML = `\n    <h3>Copier les outils de \u00ab ${escapeAttr(base.name)} \u00bb</h3>\n    <p class=\"panel-hint\">Cochez les outils \u00e0 reprendre dans \u00ab ${escapeAttr(sc.name)} \u00bb : r\u00e9f\u00e9rence, prix, ar\u00eates, charni\u00e8re et conditions de coupe voyagent avec, sous de nouveaux identifiants (les essais de la production ne bougent pas). Les <b>noms restent ceux de la production</b> \u2014 m\u00eames positions physiques ; comparer deux essais reste lisible puisque chaque courbe est titr\u00e9e par son essai. Les plans joints ne sont pas copi\u00e9s. Les essais existants de ce sc\u00e9nario ne suivent pas automatiquement les logements copi\u00e9s : utilisez \u00ab + suivre un logement \u00bb.</p>\n    <div class=\"copie-outil-liste\">${rows}</div>\n    <div class=\"panel-actions\">\n      <button class=\"ghost\" id=\"copieOutilsAnnuler\">Annuler</button>\n      <button class=\"primary\" id=\"copieOutilsGo\">Copier la s\u00e9lection</button>\n    </div>`;\n  document.getElementById(\"copieOutilsAnnuler\").addEventListener(\"click\", fermerPanneaux);\n  document.getElementById(\"copieOutilsGo\").addEventListener(\"click\", () => {\n    const ids = [...wrap.querySelectorAll(\".copie-outil-chk:checked\")].map(c => c.value);\n    if(!ids.length){ dialogueAlerte(\"Cochez au moins un outil.\", \"Rien \u00e0 copier\"); return; }\n    const n = copierOutilsDeProduction(sc, ids);\n    if(n){ saveData(); fermerPanneaux(); render(); }\n  });\n}\n\n/* ---- v4.25 \u2014 cl\u00f4ture d'un essai arr\u00eat\u00e9 avant sa charni\u00e8re (casse, brut, incident) ----\n   Le statut d'un essai est CALCUL\u00c9 : sans \u00e7a, un essai arr\u00eat\u00e9 net (insert cass\u00e9 sans\n   sortie de tol\u00e9rance mesur\u00e9e) restait \"en cours \u2014 X pi\u00e8ces \u00e0 saisir\" pour toujours et\n   re-remplissait le bandeau de reprise. La cl\u00f4ture pose une d\u00e9cision de record : le\n   statut devient \"arr\u00eat\u00e9\", il sort du protocole 5\u00d7 et de la reprise, et le rapport\n   d'essai le documente avec le motif. R\u00e9ouvrable : la donn\u00e9e n'est jamais perdue. */\nfunction renderCloturePanel(){\n  const wrap = document.getElementById(\"cloturePanel\");\n  if(!wrap || wrap.hidden) return;\n  const sc = data.find(s => s.id === (clotureCtx && clotureCtx.scId));\n  const es = sc && (sc.essais || []).find(e => e.id === (clotureCtx && clotureCtx.essaiId));\n  if(!es){ fermerPanneaux(); return; }\n  const c = es.cloture || {};\n  const options = MOTIFS_ARRET.map(([v, l]) => `<option value=\"${v}\" ${c.motif === v ? \"selected\" : \"\"}>${escapeAttr(l)}</option>`).join(\"\");\n  wrap.innerHTML = `\n    <h3>${c.motif ? \"Essai arr\u00eat\u00e9\" : \"Cl\u00f4turer l'essai\"} \u2014 ${escapeAttr(es.titre || \"\")}</h3>\n    <p class=\"panel-hint\">Un essai arr\u00eat\u00e9 avant sa charni\u00e8re reste dans le suivi et dans le rapport d'essai (avec le motif), mais il ne compte ni comme conforme ni comme non conforme : il sort du compteur 5\u00d7 et du bandeau de reprise. Ses pr\u00e9l\u00e8vements restent intacts \u2014 courbes et historique ne bougent pas. R\u00e9ouvrable \u00e0 tout moment.</p>\n    <label class=\"cloture-champ\">Motif d'arr\u00eat\n      <select id=\"clotureMotif\" class=\"cell\">${options}</select></label>\n    <label class=\"cloture-champ\">Pr\u00e9cision\n      <input id=\"clotureDetail\" class=\"cell ref\" value=\"${escapeAttr(c.detail || \"\")}\" placeholder=\"ex. \u00e9clat d'ar\u00eate Inter \u00e0 la pi\u00e8ce 37\"></label>\n    <label class=\"cloture-champ\">Date d'arr\u00eat\n      <input id=\"clotureDate\" type=\"date\" class=\"cell\" value=\"${escapeAttr(c.date || new Date().toISOString().slice(0,10))}\"></label>\n    <div class=\"panel-actions\">\n      <button class=\"ghost\" id=\"clotureAnnuler\">Annuler</button>\n      ${c.motif ? `<button class=\"ghost\" id=\"clotureReouvrir\">R\u00e9ouvrir l'essai</button>` : \"\"}\n      <button class=\"primary\" id=\"clotureGo\">${c.motif ? \"Mettre \u00e0 jour\" : \"Cl\u00f4turer l'essai\"}</button>\n    </div>`;\n  document.getElementById(\"clotureAnnuler\").addEventListener(\"click\", fermerPanneaux);\n  document.getElementById(\"clotureGo\").addEventListener(\"click\", () => {\n    es.cloture = {\n      motif: document.getElementById(\"clotureMotif\").value,\n      detail: document.getElementById(\"clotureDetail\").value.trim(),\n      date: document.getElementById(\"clotureDate\").value\n    };\n    toucherEssai(es); saveData(); fermerPanneaux(); render();\n  });\n  const re = document.getElementById(\"clotureReouvrir\");\n  if(re) re.addEventListener(\"click\", () => {\n    dialogueConfirmer(\"R\u00e9ouvrir cet essai ? Il redevient \u00ab en cours \u00bb et repart \u00e0 sa place dans le protocole.\", { titre: \"R\u00e9ouvrir l'essai ?\", okLabel: \"R\u00e9ouvrir\" }).then(ok => {\n      if(!ok) return;\n      delete es.cloture;\n      toucherEssai(es); saveData(); fermerPanneaux(); render();\n    });\n  });\n}\ndocument.getElementById(\"csvBtn\").addEventListener(\"click\", () => {\n  ouvrirPanneau(\"csvPanel\");\n  renderCsvPanel();\n});\ndocument.getElementById(\"rapportBtn\").addEventListener(\"click\", () => {\n  const sc = data.find(s => s.id === activeId) || data[0];\n  if(sc) telechargerRapport(sc);\n});\n\ndocument.getElementById(\"importBtn\").addEventListener(\"click\", () => {\n  document.getElementById(\"importInput\").click();\n});\ndocument.getElementById(\"importInput\").addEventListener(\"change\", (e) => {\n  const file = e.target.files && e.target.files[0];\n  if(file) importData(file);\n  e.target.value = \"\";\n});\n\n/* ============================================================================\n   LIGNES DE SEPT FONS (v4.27) \u2014 r\u00e9f\u00e9rentiel atelier\n   ----------------------------------------------------------------------------\n   Les lignes de machines, du FOND de l'atelier vers l'ENTR\u00c9E (info Matis/Benjamin) :\n   Weisser 1 \u2192 4, HESSAPP (double OP droite/gauche, comme EMAG 1), EMAG 1 (double OP),\n   EMAG 2, EMAG 3, PCI 1, PCI 2. Ce r\u00e9f\u00e9rentiel sert \u00e0 deux choses :\n   - le SEMIS : au premier lancement de cette version, les lignes manquantes sont\n     cr\u00e9\u00e9es vides et tout l'arbre est remis dans l'ordre physique (une seule fois \u2014\n     une ligne supprim\u00e9e volontairement ensuite ne revient pas) ;\n   - la TEINTE de fond : quand une ligne est affich\u00e9e, la page prend une teinte l\u00e9g\u00e8re\n     selon la famille de machines (Weisser = rouge, HESSAPP = kaki, EMAG = gris,\n     PCI = bleu) avec le code ligne en filigrane r\u00e9p\u00e9t\u00e9 \u2014 pour se rep\u00e9rer d'un coup\n     d'\u0153il sans lire le fil d'Ariane.\n   ============================================================================ */\nconst LIGNES_SEPT_FONS = [\n  { nom: \"Weisser 1\", famille: \"weisser\", code: \"W1\", machines: [] },\n  { nom: \"Weisser 2\", famille: \"weisser\", code: \"W2\", machines: [] },\n  { nom: \"Weisser 3\", famille: \"weisser\", code: \"W3\", machines: [] },\n  { nom: \"Weisser 4\", famille: \"weisser\", code: \"W4\", machines: [] },\n  { nom: \"HESSAPP\", famille: \"hessapp\", code: \"HESSAPP\",\n    machines: [{ code:\"OP10\", nom:\"\u00c9bauche\" }, { code:\"OP15\", nom:\"\" }, { code:\"OP20\", nom:\"\" }, { code:\"OP40\", nom:\"Finition\" }] },\n  { nom: \"EMAG 1\", famille: \"emag\", code: \"E1\",\n    machines: [{ code:\"OP10\", nom:\"\u00c9bauche piste\" }, { code:\"OP20\", nom:\"\u00c9bauche piste ext.\" }, { code:\"OP30\", nom:\"Per\u00e7ages\" }, { code:\"OP40\", nom:\"Finition pistes\" }] },\n  { nom: \"EMAG 2\", famille: \"emag\", code: \"E2\",\n    machines: [{ code:\"OP10\", nom:\"\u00c9bauche\" }, { code:\"OP30\", nom:\"Per\u00e7ages\" }, { code:\"OP40\", nom:\"Finition\" }] },\n  { nom: \"EMAG 3\", famille: \"emag\", code: \"E3\",\n    machines: [{ code:\"OP10\", nom:\"\u00c9bauche\" }, { code:\"OP40\", nom:\"Finition\" }] },\n  { nom: \"PCI 1\", famille: \"pci\", code: \"P1\", machines: [] },\n  { nom: \"PCI 2\", famille: \"pci\", code: \"P2\", machines: [] }\n];\nconst FAMILLES_LIGNE = {\n  weisser: { encre: \"#E2001A\", alpha: 0.07 },\n  hessapp: { encre: \"#556b2f\", alpha: 0.13, sansFiligrane: true }, // ligne unique : la couleur suffit\n  emag:    { encre: \"#545e68\", alpha: 0.08 },\n  pci:     { encre: \"#1b5ea6\", alpha: 0.07 }\n};\nfunction familleDeLigne(nom){\n  const n = String(nom || \"\").trim().toLowerCase();\n  if(n.startsWith(\"weisser\")) return \"weisser\";\n  if(n.startsWith(\"hessap\")) return \"hessapp\";\n  if(n.startsWith(\"emag\")) return \"emag\";\n  if(n.startsWith(\"pci\")) return \"pci\";\n  return \"\";\n}\nfunction rangLigneSeptFons(nom){\n  const n = String(nom || \"\").trim().toLowerCase();\n  const i = LIGNES_SEPT_FONS.findIndex(d => d.nom.toLowerCase() === n);\n  return i === -1 ? LIGNES_SEPT_FONS.length : i; // lignes inconnues : apr\u00e8s le r\u00e9f\u00e9rentiel\n}\nconst CLE_SEMIS_LIGNES = \"spk_lignes_septfons_semees\";\nfunction semerLignesSeptFons(){\n  try{\n    if(localStorage.getItem(CLE_SEMIS_LIGNES) === \"1\") return;\n    let ajoute = false;\n    LIGNES_SEPT_FONS.forEach(def => {\n      const existe = lignes.some(l => String(l.nom || \"\").trim().toLowerCase() === def.nom.toLowerCase());\n      if(existe) return;\n      lignes.push(normalizeLigne({ id: uid(\"l\"), nom: def.nom, references: [] }));\n      ajoute = true;\n    });\n    lignes.sort((a, b) => rangLigneSeptFons(a.nom) - rangLigneSeptFons(b.nom));\n    try{ localStorage.setItem(CLE_SEMIS_LIGNES, \"1\"); }catch(e){}\n    if(ajoute) saveData();\n  }catch(e){}\n}\n/* la teinte : fond de page l\u00e9g\u00e8rement color\u00e9 + code ligne en filigrane r\u00e9p\u00e9t\u00e9.\n   En data-URL SVG sur le body (multiple backgrounds) : rien ne flotte au-dessus du\n   contenu, l'encre s'adapte au th\u00e8me (encre sombre sur fond clair, blanche sur fond\n   sombre), et l'impression n'imprime ni l'un ni l'autre. */\nfunction appliquerFondLigne(){\n  const lg = getActiveLigne();\n  const fam = familleDeLigne(lg && lg.nom);\n  const def = FAMILLES_LIGNE[fam];\n  if(!def){\n    document.body.style.backgroundColor = \"\";\n    document.body.style.backgroundImage = \"\";\n    return;\n  }\n  const nomNorm = String(lg.nom || \"\").trim().toLowerCase();\n  const trouvee = LIGNES_SEPT_FONS.find(d => d.nom.toLowerCase() === nomNorm);\n  const code = trouvee ? trouvee.code : String(lg.nom || \"\").trim().toUpperCase().slice(0, 8);\n  // encre du filigrane : sombre sur th\u00e8me clair, claire sur th\u00e8me sombre\n  const bg = getComputedStyle(document.body).backgroundColor || \"rgb(255,255,255)\";\n  const rgb = bg.match(/\\d+/g) || [\"255\",\"255\",\"255\"];\n  const sombre = (Number(rgb[0]) + Number(rgb[1]) + Number(rgb[2])) < 384;\n  const encreTexte = sombre ? \"#ffffff\" : def.encre;\n  const opaTexte = sombre ? Math.min(def.alpha + 0.04, 0.12) : def.alpha + 0.02;\n  // la tuile porte la TEINTE (rect) et le FILIGRANE (texte) : un seul background-image\n  // r\u00e9p\u00e9t\u00e9, pos\u00e9 sur le body \u2014 rien ne flotte au-dessus du contenu, aucun z-index \u00e0 g\u00e9rer.\n  // sansFiligrane (HESSAPP, ligne unique) : la teinte seule identifie, pas de texte.\n  const texte = def.sansFiligrane ? \"\" :\n    `<text x='120' y='97' font-family='Archivo,Arial,sans-serif' font-size='54' font-weight='800' ` +\n    `fill='${encreTexte}' fill-opacity='${opaTexte}' text-anchor='middle'>${code}</text>`;\n  const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='240' height='150'>` +\n    `<rect width='240' height='150' fill='${def.encre}' fill-opacity='${def.alpha}'/>` +\n    texte + `</svg>`;\n  document.body.style.backgroundColor = \"\";\n  document.body.style.backgroundImage = `url(\"data:image/svg+xml,${encodeURIComponent(svg)}\")`;\n}\n\nsemerLignesSeptFons();\n;\n/* v4.74 \u2014 la migration des outils D1/D2 s\u00e9par\u00e9s : d\u00e9tect\u00e9e au chargement,\n   propos\u00e9e UNE fois avec les noms, appliqu\u00e9e \u00e0 la demande (\u00a77.4 : la donn\u00e9e\n   se touche avec consentement et rapport). Dispara\u00eet quand il n'y a plus rien\n   \u00e0 regrouper, et revient si des donn\u00e9es fra\u00eechement import\u00e9es ram\u00e8nent des\n   doubles. */\nfunction renduMigrBandeau(){\n  const wrap = document.getElementById(\"migrBandeau\");\n  if(!wrap) return;\n  const n = compterOutilsD1D2();\n  const nCorr = compterCorrecteursManquants();\n  const nInv = compterInversionsMabec();\n  wrap.hidden = (n === 0 && nCorr === 0 && nInv === 0);\n  if(n === 0 && nCorr === 0 && nInv === 0) { wrap.innerHTML = \"\"; return; }\n  const parties = [];\n  if(n) parties.push(`\ud83d\udd27 <b>${n} porte-outil${n > 1 ? \"s\" : \"\"}</b> saisi${n > 1 ? \"s\" : \"\"} en outils s\u00e9par\u00e9s (T543 D1 + T543 D2\u2026) : la r\u00e8gle atelier dit <b>un porte-outil = un outil \u00e0 logements</b>`);\n  if(nCorr) parties.push(`\u270f\ufe0f <b>${nCorr} outil${nCorr > 1 ? \"s\" : \"\"} d\u00e9j\u00e0 regroup\u00e9${nCorr > 1 ? \"s\" : \"\"}</b> sans correcteur \u2014 la correction remplit le champ depuis les logements (D1, D2\u2026)`);\n  if(nInv) parties.push(`\ud83c\udff7\ufe0f <b>${nInv} logement${nInv > 1 ? \"s\" : \"\"}</b> attendent leur r\u00e9f\u00e9rence plaquette \u2014 l'ISO est compl\u00e9t\u00e9 depuis le classeur quand il y est connu`);\n  wrap.innerHTML = `\n    <div class=\"migr-bandeau\">\n      <span>${parties.join(\"<br>\")}\n      <button class=\"primary small\" id=\"migrCorriger\">Corriger maintenant</button>\n      <button class=\"ghost small\" id=\"migrPlusTard\">Plus tard</button></span>\n      <div class=\"migr-rapport\" id=\"migrRapport\" hidden></div>\n    </div>`;\n  document.getElementById(\"migrCorriger\").addEventListener(\"click\", () => {\n    const res = migrerOutilsD1D2();\n    const rapInv = migrerInversionMabec();\n    saveData();\n    render();\n    const rap = document.getElementById(\"migrRapport\");\n    const wrap2 = document.getElementById(\"migrBandeau\");\n    if(rap && wrap2){\n      wrap2.hidden = false;\n      rap.hidden = false;\n      const tout = [];\n      if(res.rapport.length) tout.push(`<b>Regroupements \u2014 ${res.rapport.length} :</b> ` + res.rapport.map(x => escapeAttr(x)).join(\" \u00b7 \"));\n      if(rapInv.length) tout.push(`<b>MABEC remis en place \u2014 ${rapInv.length} :</b> ` + rapInv.map(x => escapeAttr(x)).join(\" \u00b7 \"));\n      rap.innerHTML = tout.length ? tout.join(\"<br>\") : `Rien \u00e0 corriger.`;\n      wrap2.querySelectorAll(\"button\").forEach(b => b.hidden = true);\n    }\n  });\n  document.getElementById(\"migrPlusTard\").addEventListener(\"click\", () => { wrap.hidden = true; });\n}\n\ntry{ renduMigrBandeau(); }catch(e){ console.warn(\"bandeau migration:\", e.message); }\ntry{\n  const meta = JSON.parse(localStorage.getItem(STORAGE_KEY + \"_meta\") || \"null\");\n  if(meta && meta.savedAt){ lastSavedAt = new Date(meta.savedAt); unexported = true; }\n}catch(e){}\nupdateSaveUI();\nupdateRestoreUI();\nupdateRevisionUI();\ndocument.getElementById(\"footToolName\").textContent = \"Suivi_optimisation_SPK v\" + TOOL_VERSION + \" \u2014 SPK by CeramTec\";\n// pastille poids : rendue des le chargement (le suivi vient d'etre lu, on connait sa taille)\ntry{ renderPoidsFooter((localStorage.getItem(STORAGE_KEY) || \"\").length); installerClickPoids(); }catch(e){}\n/* v4.62 \u2014 Benjamin, 30/09 : \u00ab j'aimerais que l'outil ouvre sur une page overview \u00bb.\n   L'\u00e9cran d'accueil devient l'OUVERTURE, derri\u00e8re la fen\u00eatre des nouveaut\u00e9s \u2014\n   la d\u00e9cision diff\u00e9r\u00e9e depuis la 4.51.2 est prise. Sauf hash de service (#tests) :\n   le harnais et les ancres de diagnostic gardent leur comportement. */\nif(!location.hash || location.hash === \"#accueil\") ouvrirAccueil();\n// en dernier : l'ecran doit etre pret derriere la fenetre des nouveautes\n;\n/* v4.49.3 \u2014 message de premi\u00e8re ouverture apr\u00e8s la mise en place de la base 2026/2027.\n   Une fois par poste (drapeau local). Dit le geste critique : une version ancienne de\n   l'application efface les cibles de co\u00fbt au partage \u2014 v\u00e9rifier la version en bas. */\n(async function messagePremiereOuverture(){\n  const CLE = \"spk_msg_base_2026\";\n  let dejaVu = false;\n  try{ dejaVu = localStorage.getItem(CLE) === \"1\"; }catch(e){}\n  if(dejaVu) return;\n  const ok = await ouvrirDialogue({\n    titre: \"Bienvenue dans la base 2026/2027\",\n    html: dlgTexte(\n      \"La base de d\u00e9part est en place : les 6 r\u00e9f\u00e9rences de l'atelier, avec leurs outils de prod complets (OP par OP), les r\u00e9f\u00e9rences plaquettes ISO, les codes article MABEC et les cibles de co\u00fbt pi\u00e8ce du site.\" +\n      \"\\n\\nLes nouveaux \u00e9crans : le co\u00fbt pi\u00e8ce complet et la feuille de route prod \u2192 cible (vue de synth\u00e8se), les sc\u00e9narios d'essai compl\u00e9t\u00e9s depuis la prod, les outils simultan\u00e9s en ambre.\" +\n      \"\\n\\nGeste important : regarde la version en bas de page \u2014 elle doit indiquer v\" + TOOL_VERSION + \". Si une version plus ancienne s'affiche, ferme compl\u00e8tement l'application et rouvre-la connect\u00e9e \u00e0 Internet (elle se met \u00e0 jour toute seule). Une version ancienne peut effacer les cibles de co\u00fbt au moment du partage.\"),\n    sansAnnuler: true, okLabel: \"Compris\"\n  });\n  try{ localStorage.setItem(CLE, \"1\"); }catch(e){}\n})();\n\n\n;\n\n/* ============================================================\n   Cloud (v4.8) \u2014 synchro du suivi entre postes via Supabase\n   ------------------------------------------------------------\n   Le localStorage reste la copie de travail : l'outil marche hors ligne\n   comme avant, le cloud ne fait qu'ajouter la partage. C\u00f4t\u00e9 cloud, UNE\n   ligne `etat` (exactement le JSON d'export) + un historique glissant de\n   20 versions. Tirage au chargement / au retour sur l'onglet / toutes les\n   90 s ; d\u00e9p\u00f4t automatique quelques secondes apr\u00e8s chaque saisie.\n   Premier contact : jamais de m\u00e9lange silencieux \u2014 l'outil demande qui\n   fait autorit\u00e9, avec export de secours avant tout remplacement.\n   Client \u00e9crit \u00e0 la main en fetch() : pas de SDK, le fichier unique et\n   l'usage hors ligne (cl\u00e9 USB, proxy d'usine) restent la r\u00e8gle.\n   ============================================================ */\nconst CLOUD_URL  = \"https://cxjfyaorkkxemjnollnj.supabase.co\";\nconst CLOUD_KEY  = \"sb_publishable_TQySmct-8qg3qMiS2WodbA_gQCcPp9Z\";\nconst CLOUD_SESSION_KEY = STORAGE_KEY + \"_cloud_session\";\nconst CLOUD_STAMP_KEY   = STORAGE_KEY + \"_cloud_stamp\";\nconst CLOUD_VU_KEY      = STORAGE_KEY + \"_cloud_vu\";\n\n/* cloudSession est d\u00e9clar\u00e9e dans le script principal (v4.16, anti-TDZ : la zone photos\n   la lit au premier rendu). Ici on ne fait que restaurer la session persist\u00e9e. */\nlet cloudStamp = null;     // modifie_le du cloud tel que CE poste le connait\nlet cloudVu = null;        // dernier modifie_le annonc\u00e9/ vu (pour le journal \u00e0 l'ouverture)\nlet cloudSale = false;     // des saisies locales pas encore d\u00e9pos\u00e9es\nlet cloudEnCours = false;  // une synchro est en route\nlet cloudPause = false;    // neutralise le hook pendant l'application d'un tirage\nlet cloudErreur = \"\";\nlet cloudDernierOK = null; // dernier \u00e9change r\u00e9ussi\nlet cloudInfo = { vide:null, modifie_le:null, modifie_par:null };\nlet cloudTimerPush = null, cloudTimerFocus = null, cloudDernierFocus = 0;\n\ntry{ cloudSession = JSON.parse(localStorage.getItem(CLOUD_SESSION_KEY) || \"null\"); }catch(e){}\ntry{ cloudStamp = localStorage.getItem(CLOUD_STAMP_KEY) || null; }catch(e){}\ntry{ cloudVu = localStorage.getItem(CLOUD_VU_KEY) || null; }catch(e){}\n\nfunction cloudSauverSession(){\n  try{\n    if(cloudSession) localStorage.setItem(CLOUD_SESSION_KEY, JSON.stringify(cloudSession));\n    else localStorage.removeItem(CLOUD_SESSION_KEY);\n  }catch(e){}\n}\nfunction cloudSauverStamp(){\n  try{ if(cloudStamp) localStorage.setItem(CLOUD_STAMP_KEY, cloudStamp); }catch(e){}\n}\n/* journal : la derni\u00e8re version du cloud que CE poste a vue \u2014 une version plus r\u00e9cente\n   d\u00e9pos\u00e9e par l'autre poste et jamais vue d\u00e9clenche le message \u00e0 l'ouverture */\nfunction cloudMarquerVu(){\n  if(!cloudStamp) return;\n  cloudVu = cloudStamp;\n  try{ localStorage.setItem(CLOUD_VU_KEY, cloudVu); }catch(e){}\n}\nfunction cloudMonIdentite(){\n  return auteurNom || (cloudSession && cloudSession.email) || \"\";\n}\nfunction cloudAnnoncerVersion(row){\n  const qui = row.modifie_par || \"L'autre poste\";\n  let txt = qui + \" a mis \u00e0 jour le suivi partag\u00e9 (d\u00e9pos\u00e9 le \" + new Date(row.modifie_le).toLocaleString(\"fr-FR\") + \").\\n\\nVos donn\u00e9es locales viennent d'\u00eatre mises \u00e0 jour avec cette version.\";\n  const note = row.donnees && row.donnees.synchroNote;\n  if(note && note.texte) txt += \"\\n\\nD\u00e9tail : \" + note.texte + \"\\n(par \" + (note.par || \"?\") + \")\";\n  dialogueAlerte(txt, \"Suivi partag\u00e9 \u2014 mise \u00e0 jour re\u00e7ue\");\n}\n\n/* ---- transport : fetch avec d\u00e9lai max (un proxy qui hang ne doit pas bloquer l'outil) ---- */\nfunction cloudFetch(url, opts, delai){\n  const ctl = new AbortController();\n  const t = setTimeout(() => ctl.abort(), delai || 15000);\n  return fetch(url, Object.assign({}, opts, { signal: ctl.signal })).finally(() => clearTimeout(t));\n}\nfunction cloudEntetes(extra){\n  return Object.assign({\n    \"apikey\": CLOUD_KEY,\n    \"Authorization\": \"Bearer \" + (cloudSession ? cloudSession.access_token : CLOUD_KEY),\n    \"Content-Type\": \"application/json\"\n  }, extra || {});\n}\n\n/* ---- auth : email + mot de passe, session rafra\u00eechie \u00e0 la demande ---- */\nasync function cloudRequeteAuth(grant, body){\n  const r = await cloudFetch(CLOUD_URL + \"/auth/v1/token?grant_type=\" + grant, {\n    method: \"POST\",\n    headers: { \"apikey\": CLOUD_KEY, \"Content-Type\": \"application/json\" },\n    body: JSON.stringify(body)\n  });\n  const j = await r.json().catch(() => ({}));\n  if(!r.ok){\n    const brut = j.error_description || j.msg || j.message || \"connexion refus\u00e9e\";\n    const err = new Error(/invalid login credentials/i.test(brut) ? \"Email ou mot de passe incorrect.\" : brut);\n    /* 400/401/403 = le serveur a REJETE le jeton (r\u00e9voqu\u00e9, d\u00e9j\u00e0 utilis\u00e9, mauvais identifiants) :\n       d\u00e9finitif. Un 5xx ou une r\u00e9ponse illisible est temporaire \u2014 crucial pour ne pas\n       d\u00e9truire une session encore valable \u00e0 cause d'une indisponibilit\u00e9 passag\u00e8re. */\n    if(r.status === 400 || r.status === 401 || r.status === 403) err.definitif = true;\n    throw err;\n  }\n  return j;\n}\nasync function cloudConnexion(email, motDePasse){\n  const j = await cloudRequeteAuth(\"password\", { email, password: motDePasse });\n  cloudSession = {\n    access_token: j.access_token, refresh_token: j.refresh_token,\n    expires_at: Date.now() + (j.expires_in || 3600) * 1000,\n    email: (j.user && j.user.email) || email\n  };\n  cloudSauverSession();\n  cloudErreur = \"\";\n  cloudRenduOptions(); cloudRenduPastille();\n  cloudSync(\"connexion\");\n}\nasync function cloudRafraichirSession(){\n  if(!cloudSession || Date.now() < cloudSession.expires_at - 60000) return cloudSession ? true : false;\n  try{\n    const j = await cloudRequeteAuth(\"refresh_token\", { refresh_token: cloudSession.refresh_token });\n    cloudSession.access_token = j.access_token;\n    cloudSession.refresh_token = j.refresh_token;\n    cloudSession.expires_at = Date.now() + (j.expires_in || 3600) * 1000;\n    cloudSauverSession();\n    return true;\n  }catch(e){\n    /* v4.17 \u2014 la session ne meurt plus qu'en cas de refus DEFINITIF du serveur (jeton\n       r\u00e9voqu\u00e9, refresh d\u00e9j\u00e0 consomm\u00e9). Avant : TOUT \u00e9chec d\u00e9truisait la session \u2014 y\n       compris un simple \"Failed to fetch\" ou un AbortError du d\u00e9lai d'attente. Ouvrir\n       l'outil hors r\u00e9seau (usine, d\u00e9marrage avant la mont\u00e9e du Wi-Fi) suffisait donc \u00e0\n       se faire d\u00e9connecter, alors que le refresh token restait parfaitement valable :\n       il fallait se reconnecter \u00e0 chaque ouverture. D\u00e9sormais la session est conserv\u00e9e\n       et le rafra\u00eechissement retentera au prochain contact (focus, 90 s, saisie). */\n    if(!e || !e.definitif){\n      cloudErreur = \"cloud injoignable \u2014 session conserv\u00e9e, nouvelle tentative au prochain contact\";\n      cloudRenduOptions(); cloudRenduPastille();\n      return false;\n    }\n    cloudSession = null; cloudSauverSession();\n    cloudErreur = \"session expir\u00e9e \u2014 reconnectez-vous dans Options\";\n    cloudRenduOptions(); cloudRenduPastille();\n    return false;\n  }\n}\nasync function cloudDeconnexion(){\n  try{ await cloudFetch(CLOUD_URL + \"/auth/v1/logout\", { method:\"POST\", headers: cloudEntetes() }, 5000); }catch(e){}\n  cloudSession = null; cloudSauverSession();\n  cloudErreur = \"\";\n  cloudRenduOptions(); cloudRenduPastille();\n}\n\n/* ---- photos cloud (v4.16) --------------------------------------------------------------\n   Le suivi partage le JSON entre postes, mais les PHOTOS d'essai restaient coinc\u00e9es dans\n   le dossier local de celui qui les avait prises : l'autre poste (et son rapport) n'en\n   voyait rien. Deuxi\u00e8me mode de stockage : le bucket priv\u00e9 `photos` du projet Supabase\n   (acc\u00e8s r\u00e9serv\u00e9 aux comptes de l'\u00e9quipe). Sans dossier local connect\u00e9, une photo ajout\u00e9e\n   part au cloud et voyage avec le suivi ; l'autre poste la t\u00e9l\u00e9charge \u00e0 la demande et la\n   met en cache IndexedDB pour l'usage hors ligne. Le dossier local reste prioritaire quand\n   il est connect\u00e9 (z\u00e9ro r\u00e9seau, z\u00e9ro quota) \u2014 les deux modes coexistent photo par photo. */\nconst CLOUD_PHOTOS_BUCKET = \"photos\";\n\nfunction photoCacheOuvrir(){\n  return new Promise((resolve, reject) => {\n    const req = indexedDB.open(\"spk_photos_cloud\", 1);\n    req.onupgradeneeded = () => req.result.createObjectStore(\"blobs\");\n    req.onsuccess = () => resolve(req.result);\n    req.onerror = () => reject(req.error);\n  });\n}\nasync function photoCacheGet(cle){\n  try{\n    const db = await photoCacheOuvrir();\n    return await new Promise((resolve, reject) => {\n      const req = db.transaction(\"blobs\", \"readonly\").objectStore(\"blobs\").get(cle);\n      req.onsuccess = () => resolve(req.result || null);\n      req.onerror = () => reject(req.error);\n    });\n  }catch(e){ return null; }\n}\nasync function photoCacheSet(cle, blob){\n  try{\n    const db = await photoCacheOuvrir();\n    await new Promise((resolve, reject) => {\n      const tx = db.transaction(\"blobs\", \"readwrite\");\n      tx.objectStore(\"blobs\").put(blob, cle);\n      tx.oncomplete = () => resolve();\n      tx.onerror = () => reject(tx.error);\n    });\n  }catch(e){ /* le cache est un confort, jamais une condition */ }\n}\nasync function photoCacheEffacer(cle){\n  try{\n    const db = await photoCacheOuvrir();\n    await new Promise((resolve, reject) => {\n      const tx = db.transaction(\"blobs\", \"readwrite\");\n      tx.objectStore(\"blobs\").delete(cle);\n      tx.oncomplete = () => resolve();\n      tx.onerror = () => reject(tx.error);\n    });\n  }catch(e){}\n}\n/* le blob d'une photo cloud : cache d'abord, t\u00e9l\u00e9chargement ensuite (auth par session) */\nasync function cloudPhotoBlob(chemin){\n  const enCache = await photoCacheGet(chemin);\n  if(enCache) return enCache;\n  if(!await cloudRafraichirSession()) throw new Error(\"non connect\u00e9 au cloud (Options \u2192 Cloud)\");\n  const rep = await fetch(CLOUD_URL + \"/storage/v1/object/\" + CLOUD_PHOTOS_BUCKET + \"/\" + chemin, {\n    headers: { \"Authorization\": \"Bearer \" + cloudSession.access_token }\n  });\n  if(!rep.ok) throw new Error(rep.status === 404 ? \"photo introuvable dans le cloud\" : \"t\u00e9l\u00e9chargement impossible (\" + rep.status + \")\");\n  const blob = await rep.blob();\n  await photoCacheSet(chemin, blob);\n  return blob;\n}\nasync function cloudPhotoEnvoyer(chemin, blob){\n  if(!await cloudRafraichirSession()) throw new Error(\"non connect\u00e9 au cloud (Options \u2192 Cloud)\");\n  const rep = await fetch(CLOUD_URL + \"/storage/v1/object/\" + CLOUD_PHOTOS_BUCKET + \"/\" + chemin, {\n    method: \"POST\",\n    headers: { \"Authorization\": \"Bearer \" + cloudSession.access_token, \"Content-Type\": (blob && blob.type) || \"image/jpeg\" },\n    body: blob\n  });\n  if(!rep.ok){\n    // 400 \"Duplicate\" = la photo existe d\u00e9j\u00e0 (r\u00e9-essai apr\u00e8s un upload r\u00e9ussi) : pas une erreur\n    const corps = await rep.text().catch(() => \"\");\n    if(!/duplicate/i.test(corps)) throw new Error(\"envoi impossible (\" + rep.status + \")\");\n  }\n  await photoCacheSet(chemin, blob);\n}\nasync function cloudPhotoSupprimer(chemin){\n  await photoCacheEffacer(chemin);\n  if(!await cloudRafraichirSession()) return; // le retrait du JSON suffit ; nettoyage du bucket \u00e0 la prochaine suppression\n  await fetch(CLOUD_URL + \"/storage/v1/object/\" + CLOUD_PHOTOS_BUCKET + \"/\" + chemin, {\n    method: \"DELETE\",\n    headers: { \"Authorization\": \"Bearer \" + cloudSession.access_token }\n  }).catch(() => {});\n}\n/* objectURL d'une photo quel que soit son mode (dossier local ou cloud) \u2014 \u00e0 r\u00e9voquer\n   par l'appelant une fois l'image d\u00e9cod\u00e9e. null = indisponible sur ce poste.\n   (r\u00e9definit le stub du script principal, qui ne sait lire que le dossier local) */\nasync function photoObjectURL(p){\n  if(!p) return null;\n  if(p.stockage === \"cloud\"){\n    try{\n      const blob = await cloudPhotoBlob(p.filename);\n      return URL.createObjectURL(blob);\n    }catch(e){\n      cloudPhotoErreurDerniere = e.message || \"erreur\";\n      return null;\n    }\n  }\n  return readPhotoURL(p.filename);\n}\n\n/* ---- lectures / \u00e9critures de l'\u00e9tat partag\u00e9 ---- */\nasync function cloudLireEtat(){\n  const r = await cloudFetch(CLOUD_URL + \"/rest/v1/etat?id=eq.1&select=donnees,modifie_le,modifie_par\", { headers: cloudEntetes() });\n  if(!r.ok) throw new Error(\"cloud injoignable (\" + r.status + \")\");\n  const j = await r.json();\n  return j[0] || null;\n}\n/* v4.81.0 \u2014 la lecture L\u00c9G\u00c8RE : le tampon horaire seul, sans le `donnees`.\n   L'\u00e9tat partag\u00e9 p\u00e8se 3 \u00e0 4 Mo ; chaque cycle de synchro qui le re-t\u00e9l\u00e9charge\n   en entier pour lire une date a \u00e9puis\u00e9 le quota de bande sortante du plan\n   gratuit (exceed_egress_quota, 12/10/2026 \u2014 service restreint). D\u00e9sormais la\n   synchro de routine passe par ici (~100 octets) et la lecture lourde ne se\n   paie que lorsqu'une d\u00e9cision a besoin du contenu : premier contact,\n   adoption, fusion. M\u00eames d\u00e9cisions, m\u00eame ordre \u2014 seul le poids du regard\n   change. */\nasync function cloudLireTampon(){\n  const r = await cloudFetch(CLOUD_URL + \"/rest/v1/etat?id=eq.1&select=modifie_le,modifie_par\", { headers: cloudEntetes() });\n  if(!r.ok) throw new Error(\"cloud injoignable (\" + r.status + \")\");\n  const j = await r.json();\n  return j[0] || null;\n}\n/* D\u00e9pose la version locale : archive l'ancienne (historique 20 versions), \u00e9crit la\n   nouvelle, retient le tampon horaire renvoy\u00e9 par la base (jamais calcul\u00e9 c\u00f4t\u00e9 client). */\nasync function cloudEcrireEtat(){\n  syncActiveOp();\n  const donnees = JSON.parse(payloadSuivi());\n  const avant = await cloudLireEtat();\n  if(avant){\n    await cloudFetch(CLOUD_URL + \"/rest/v1/etat_historique\", {\n      method:\"POST\", headers: cloudEntetes({ \"Prefer\":\"return=minimal\" }),\n      body: JSON.stringify({ donnees: avant.donnees, sauve_par: avant.modifie_par || \"\" })\n    });\n  }\n  const corps = { id:1, donnees, modifie_par: auteurNom || (cloudSession && cloudSession.email) || \"\" };\n  let r = await cloudFetch(CLOUD_URL + \"/rest/v1/etat?id=eq.1\", {\n    method:\"PATCH\", headers: cloudEntetes({ \"Prefer\":\"return=representation\" }),\n    body: JSON.stringify(corps)\n  });\n  if(!r.ok) throw new Error(\"cloud injoignable (\" + r.status + \")\");\n  let j = await r.json();\n  if(!j.length){\n    r = await cloudFetch(CLOUD_URL + \"/rest/v1/etat\", {\n      method:\"POST\", headers: cloudEntetes({ \"Prefer\":\"resolution=merge-duplicates,return=representation\" }),\n      body: JSON.stringify(corps)\n    });\n    if(!r.ok) throw new Error(\"cloud injoignable (\" + r.status + \")\");\n    j = await r.json();\n  }\n  cloudStamp = j[0].modifie_le;\n  cloudSauverStamp();\n  cloudSale = false;\n  cloudDernierOK = new Date();\n  cloudInfo = { vide:false, modifie_le: cloudStamp, modifie_par: corps.modifie_par };\n}\nasync function cloudArchiverLeCloudActuel(row){\n  await cloudFetch(CLOUD_URL + \"/rest/v1/etat_historique\", {\n    method:\"POST\", headers: cloudEntetes({ \"Prefer\":\"return=minimal\" }),\n    body: JSON.stringify({ donnees: row.donnees, sauve_par: row.modifie_par || \"\" })\n  });\n}\n\n/* ---- comptage d'essais, pour les r\u00e9sum\u00e9s affich\u00e9s avant d\u00e9cision ---- */\nfunction cloudCompterEssais(arbre){\n  return (arbre || []).reduce((n,l) => n + (l.references || []).reduce((m,r) => m + (r.ops || []).reduce((k,o) =>\n    k + (o.scenarios || []).reduce((x,s) => x + ((s.essais || []).length), 0), 0), 0), 0);\n}\nfunction cloudLocalEstExemple(){\n  try{\n    const l = lignes && lignes[0];\n    return !!l && (JSON.stringify(l).indexOf(\"[Exemple]\") !== -1);\n  }catch(e){ return false; }\n}\n\n/* export de secours t\u00e9l\u00e9charg\u00e9 AVANT tout remplacement des donn\u00e9es locales */\nfunction cloudExportSecours(motif){\n  try{\n    const obj = JSON.parse(payloadSuivi());\n    obj.exporteLe = new Date().toISOString();\n    obj.exportePar = (auteurNom || \"?\") + \" \u2014 secours avant \" + motif;\n    const blob = new Blob([JSON.stringify(obj, null, 2)], { type:\"application/json\" });\n    const url = URL.createObjectURL(blob);\n    const a = document.createElement(\"a\");\n    const d = new Date();\n    const stamp = d.getFullYear() + String(d.getMonth()+1).padStart(2,\"0\") + String(d.getDate()).padStart(2,\"0\")\n                + \"-\" + String(d.getHours()).padStart(2,\"0\") + String(d.getMinutes()).padStart(2,\"0\");\n    a.href = url;\n    a.download = \"SuiviOptimisation_secours_\" + stamp + \".json\";\n    document.body.appendChild(a); a.click(); document.body.removeChild(a);\n    setTimeout(() => URL.revokeObjectURL(url), 2000);\n  }catch(e){}\n}\n\n/* applique la version du cloud au poste \u2014 le m\u00eame chemin qu'un import \u00ab remplacer tout \u00bb,\n   avec son \u21ba Restaurer et sa sauvegarde de s\u00e9curit\u00e9 ; silencieux = tirage de routine */\nasync function cloudAdopter(row, silencieux){\n  const prep = preparerImportDepuis(row.donnees);\n  if(!prep){ cloudErreur = \"contenu cloud illisible\"; cloudRenduPastille(); return false; }\n  if(!silencieux) cloudExportSecours(\"la prise de la version du cloud\");\n  const optionsOuvertes = !document.getElementById(\"optionsPanel\").hidden;\n  cloudPause = true;\n  try{\n    importEnAttente = Object.assign({ parsed: row.donnees }, prep);\n    appliquerImport(\"remplace\");\n  } finally { cloudPause = false; }\n  cloudStamp = row.modifie_le;\n  cloudSale = false;\n  cloudSauverStamp();\n  cloudDernierOK = new Date();\n  if(optionsOuvertes) ouvrirPanneau(\"optionsPanel\");\n  return true;\n}\n\n/* premier contact avec un cloud d\u00e9j\u00e0 rempli : qui fait autorit\u00e9 ? Toujours demand\u00e9,\n   jamais tranch\u00e9 en silence \u2014 c'est la garde-fou \u00ab les donn\u00e9es de Matis d'abord \u00bb. */\nasync function cloudPremierContact(row){\n  const d = row.donnees || {};\n  const nCloud = cloudCompterEssais(d.lignes);\n  const quand = row.modifie_le ? new Date(row.modifie_le).toLocaleString(\"fr-FR\") : \"date inconnue\";\n  const par = row.modifie_par || \"inconnu\";\n  const nLocal = cloudCompterEssais(lignes);\n  const ok = await dialogueConfirmer(\n    \"Le cloud contient d\u00e9j\u00e0 un suivi : \" + nCloud + \" essai(s), derni\u00e8re modification le \" + quand + \" par \" + par + \".\\n\\n\" +\n    \"Votre version locale compte \" + nLocal + \" essai(s)\" + (cloudLocalEstExemple() ? \" et semble \u00eatre le jeu d'exemple [Exemple].\" : \".\") + \"\\n\\n\" +\n    \"Prendre la version du cloud sur ce poste ? Un export de secours de votre version locale sera t\u00e9l\u00e9charg\u00e9 avant.\",\n    { titre:\"Cloud \u2014 ce poste et le cloud diff\u00e8rent\", okLabel:\"Prendre le cloud\" });\n  if(ok){ await cloudAdopter(row, false); return; }\n  const ok2 = await dialogueConfirmer(\n    \"Garder votre version locale et d\u00e9poser celle-ci dans le cloud \u00e0 la place ?\\n\\n\" +\n    \"La version actuellement dans le cloud ne est pas perdue : elle part dans l'historique (20 derni\u00e8res versions gard\u00e9es).\",\n    { titre:\"D\u00e9poser votre version \u00e0 la place ?\", danger:true, okLabel:\"D\u00e9poser ma version\" });\n  if(ok2){\n    try{ await cloudEcrireEtat(); cloudErreur = \"\"; }\n    catch(e){ cloudErreur = e.message || \"d\u00e9p\u00f4t impossible\"; }\n  } else {\n    // on ne re-posera pas la question tant que le cloud n'a pas boug\u00e9\n    cloudStamp = row.modifie_le; cloudSauverStamp();\n  }\n}\n\n/* le cloud a boug\u00e9 pendant que ce poste avait des saisies non d\u00e9pos\u00e9es : depuis la\n   v4.10, FUSION AUTOMATIQUE essai par essai (le plus r\u00e9cent gagne pour un m\u00eame essai,\n   les essais de chacun s'ajoutent, les r\u00e9glages du sc\u00e9nario restent \u00e0 la version\n   locale) \u2014 plus de choix binaire \u00ab prendre / \u00e9craser \u00bb. Le bilan s'affiche dans le\n   panneau de fusion, la version du cloud remplac\u00e9e part \u00e0 l'archive, et le r\u00e9sultat\n   fusionn\u00e9 repart au cloud au prochain cycle avec une note embarqu\u00e9e que l'autre\n   poste lira \u00e0 sa prochaine ouverture. */\nasync function cloudConflit(row){\n  const quand = new Date(row.modifie_le).toLocaleString(\"fr-FR\");\n  const par = row.modifie_par || \"l'autre poste\";\n  try{ await cloudArchiverLeCloudActuel(row); }catch(e){}\n  const prep = preparerImportDepuis(row.donnees);\n  if(!prep){ cloudErreur = \"contenu cloud illisible\"; cloudRenduPastille(); return; }\n  importEnAttente = Object.assign({ parsed: row.donnees }, prep);\n  const bilan = appliquerImport(\"fusion\") || { essaisAjoutes:0, essaisMaj:0, essaisConserves:0, conflits:[] };\n  // dans le flux import, le panneau de bilan est d\u00e9j\u00e0 ouvert par le choix Fusionner ;\n  // ici il faut l'ouvrir soi-m\u00eame \u2014 c'est le \u00ab message \u00bb qui raconte la fusion\n  if(bilan) ouvrirPanneau(\"importPanel\");\n  synchroNote = {\n    par: auteurNom || (cloudSession && cloudSession.email) || \"?\",\n    quand: new Date().toISOString(),\n    texte: \"fusion automatique apr\u00e8s le d\u00e9p\u00f4t de \" + par + \" (\" + quand + \") : \" +\n      bilan.essaisAjoutes + \" essai(s) ajout\u00e9(s), \" + bilan.essaisMaj + \" mis \u00e0 jour, \" +\n      (bilan.essaisConserves || 0) + \" conserv\u00e9(s)\" +\n      ((bilan.conflits && bilan.conflits.length) ? \", \" + bilan.conflits.length + \" conflit(s) \u00e0 v\u00e9rifier (rapport de fusion ci-dessous)\" : \"\")\n  };\n  saveData(); // repersiste la note ; le d\u00e9p\u00f4t du fusionn\u00e9 part au prochain cycle (4 s)\n  cloudStamp = row.modifie_le; // version du cloud vue et fusionn\u00e9e\n  cloudSale = true;\n  cloudSauverStamp();\n  cloudDernierOK = new Date();\n}\n\n/* ---- le moteur : un aller-retour qui d\u00e9crit tout ce qui peut se rencontrer ---- */\nasync function cloudSync(raison){\n  if(!cloudSession || cloudEnCours) return;\n  if(!(await cloudRafraichirSession())) return;\n  cloudEnCours = true;\n  cloudRenduPastille();\n  try{\n    /* v4.81.0 \u2014 le tampon d'abord (~100 o), le contenu lourd seulement si une\n       d\u00e9cision l'exige. Le flux et l'ordre des d\u00e9cisions sont INCHANG\u00c9S :\n       cloud vide \u2192 rien ; premier contact \u2192 dialogue ; boug\u00e9 + saisies locales\n       \u2192 fusion ; boug\u00e9 + poste propre \u2192 adoption silencieuse ; pas boug\u00e9 +\n       saisies \u2192 d\u00e9p\u00f4t ; rien \u2192 point d'horloge. */\n    const tampon = await cloudLireTampon();\n    cloudInfo = tampon\n      ? { vide:false, modifie_le: tampon.modifie_le, modifie_par: tampon.modifie_par }\n      : { vide:true, modifie_le:null, modifie_par:null };\n\n    if(!tampon){\n      // cloud vide : rien \u00e0 tirer. Le d\u00e9p\u00f4t initial reste volontaire (bouton dans\n      // Options) \u2014 jamais un effet de bord d'une saisie, sinon le jeu d'exemple\n      // d'un poste partirait au cloud par accident.\n      cloudDernierOK = new Date();\n      cloudErreur = \"\";\n      return;\n    }\n    if(cloudStamp === null){\n      await cloudPremierContact(await cloudLireEtat());\n      return;\n    }\n    if(tampon.modifie_le !== cloudStamp){\n      if(cloudSale){\n        await cloudConflit(await cloudLireEtat());\n      } else {\n        // tirage silencieux \u2014 le cas nominal. Si la version vient de l'autre poste et\n        // n'avait jamais \u00e9t\u00e9 vue : message \u00e0 l'ouverture (le journal de synchro).\n        const row = await cloudLireEtat();\n        const annonce = (tampon.modifie_le !== cloudVu) && ((tampon.modifie_par || \"\") !== cloudMonIdentite());\n        await cloudAdopter(row, true);\n        if(annonce) cloudAnnoncerVersion(row);\n      }\n    } else if(cloudSale){\n      await cloudEcrireEtat();               // d\u00e9p\u00f4t automatique apr\u00e8s saisie\n    } else {\n      cloudDernierOK = new Date();\n    }\n    if(!cloudErreur) cloudErreur = \"\";\n  }catch(e){\n    cloudErreur = (e && e.name === \"AbortError\") ? \"cloud injoignable (d\u00e9lai d\u00e9pass\u00e9)\" : ((e && e.message) || \"cloud injoignable\");\n  }finally{\n    cloudEnCours = false;\n    cloudMarquerVu();\n    cloudRenduPastille();\n    const opt = document.getElementById(\"optionsPanel\");\n    if(opt && !opt.hidden) cloudRenduOptions();\n  }\n}\n\n/* ---- d\u00e9clencheurs ---- */\n/* appel\u00e9 par saveData() \u00e0 chaque saisie (voir hook dans le script principal) */\nfunction cloudApresSauvegarde(){\n  if(cloudPause || !cloudSession) return;\n  cloudSale = true;\n  cloudRenduPastille();\n  clearTimeout(cloudTimerPush);\n  cloudTimerPush = setTimeout(() => cloudSync(\"saisie\"), 4000);\n}\nfunction cloudAuFocus(){\n  if(!cloudSession) return;\n  const t = Date.now();\n  if(t - cloudDernierFocus < 10000) return;\n  cloudDernierFocus = t;\n  clearTimeout(cloudTimerFocus);\n  cloudTimerFocus = setTimeout(() => cloudSync(\"focus\"), 800);\n}\n\n/* d\u00e9p\u00f4t initial volontaire (bouton Options, cloud vide) */\nasync function cloudDeposerManuel(){\n  if(!cloudSession) return;\n  const nLocal = cloudCompterEssais(lignes);\n  const ok = await dialogueConfirmer(\n    \"D\u00e9poser ce suivi dans le cloud ?\\n\\nIl compte \" + nLocal + \" essai(s). Il deviendra la version partag\u00e9e que l'autre poste recevra \u00e0 sa connexion.\" +\n    (cloudLocalEstExemple() ? \"\\n\\nATTENTION : cette version semble \u00eatre le jeu d'exemple [Exemple] \u2014 ne pas la d\u00e9poser si le vrai suivi existe d\u00e9j\u00e0 sur un autre poste.\" : \"\"),\n    { titre:\"D\u00e9poser ce suivi dans le cloud ?\", danger: cloudLocalEstExemple(), okLabel:\"D\u00e9poser\" });\n  if(!ok) return;\n  cloudEnCours = true; cloudRenduPastille();\n  try{ await cloudEcrireEtat(); cloudErreur = \"\"; }\n  catch(e){ cloudErreur = e.message || \"d\u00e9p\u00f4t impossible\"; }\n  cloudEnCours = false;\n  cloudRenduPastille(); cloudRenduOptions();\n}\n\n/* ---- pastille de pied de page ---- */\nfunction cloudRenduPastille(){\n  const el = document.getElementById(\"footCloud\");\n  if(!el) return;\n  if(!cloudSession){ el.hidden = true; return; }\n  el.hidden = false;\n  el.classList.remove(\"alerte\",\"critique\");\n  let txt = \"\u2601 \u00e0 jour\", title = \"Synchro cloud du suivi\";\n  if(cloudEnCours){ txt = \"\u2601 synchro\u2026\"; }\n  else if(cloudErreur){\n    if(/conflit/.test(cloudErreur)){ txt = \"\u2601 conflit\"; el.classList.add(\"alerte\"); }\n    else if(/expir\u00e9e/.test(cloudErreur)){ txt = \"\u2601 d\u00e9connect\u00e9\"; el.classList.add(\"critique\"); }\n    else { txt = \"\u2601 hors ligne\"; el.classList.add(\"alerte\"); }\n    title += \" \u2014 \" + cloudErreur;\n  }\n  else if(cloudStamp === null && cloudInfo.vide === false){ txt = \"\u2601 \u00e0 r\u00e9gler\"; el.classList.add(\"alerte\"); title += \" \u2014 premi\u00e8re synchronisation \u00e0 confirmer\"; }\n  else if(cloudSale){ txt = \"\u2601 en attente d'envoi\"; }\n  else if(cloudInfo.vide){ txt = \"\u2601 vide \u2014 d\u00e9p\u00f4t \u00e0 faire\"; el.classList.add(\"alerte\"); title += \" \u2014 le cloud est vide : d\u00e9posez ce suivi depuis Options\"; }\n  if(cloudDernierOK && txt === \"\u2601 \u00e0 jour\") title += \" \u2014 derni\u00e8re synchro \" + cloudDernierOK.toLocaleTimeString(\"fr-FR\");\n  el.textContent = txt;\n  el.title = title;\n}\n\n/* ---- zone Cloud du panneau Options ---- */\nfunction cloudRenduOptions(){\n  const z = document.getElementById(\"cloudZone\");\n  if(!z) return;\n  if(!cloudSession){\n    z.innerHTML = `\n      <label>Synchro entre postes <i class=\"opt-scope\">Tous</i></label>\n      <span class=\"opt-note\" style=\"margin-bottom:10px; display:block;\">Partage automatique du suivi entre vous et Matis : chaque saisie repart seule quelques secondes apr\u00e8s, les modifications de l'autre arrivent \u00e0 l'ouverture de l'outil ou en revenant sur l'onglet. Chaque poste garde sa copie locale \u2014 l'outil continue de marcher sans r\u00e9seau.</span>\n      <div style=\"display:flex; gap:8px; flex-wrap:wrap; align-items:center;\">\n        <input type=\"email\" id=\"cloudEmail\" placeholder=\"email\" autocomplete=\"username\" style=\"flex:1 1 170px; min-width:150px; text-align:left;\">\n        <input type=\"password\" id=\"cloudMdp\" placeholder=\"mot de passe\" autocomplete=\"current-password\" style=\"flex:1 1 130px; min-width:120px; text-align:left;\">\n        <button class=\"primary\" id=\"cloudBtnConnexion\">Se connecter</button>\n      </div>\n      <div class=\"opt-statut ko\" id=\"cloudErreurUI\" ${cloudErreur ? \"\" : \"hidden\"} style=\"margin-top:8px;\"></div>`;\n    const btn = z.querySelector(\"#cloudBtnConnexion\");\n    btn.addEventListener(\"click\", async () => {\n      const email = z.querySelector(\"#cloudEmail\").value.trim();\n      const mdp = z.querySelector(\"#cloudMdp\").value;\n      if(!email || !mdp){\n        const e = z.querySelector(\"#cloudErreurUI\"); e.hidden = false; e.textContent = \"Email et mot de passe requis.\";\n        return;\n      }\n      btn.disabled = true; btn.textContent = \"Connexion\u2026\";\n      try{ await cloudConnexion(email, mdp); }\n      catch(err){\n        btn.disabled = false; btn.textContent = \"Se connecter\";\n        const e = z.querySelector(\"#cloudErreurUI\"); e.hidden = false; e.textContent = err.message || \"Connexion impossible.\";\n      }\n    });\n    z.querySelector(\"#cloudMdp\").addEventListener(\"keydown\", ev => { if(ev.key === \"Enter\") btn.click(); });\n    return;\n  }\n  const dernier = cloudDernierOK ? cloudDernierOK.toLocaleString(\"fr-FR\") : \"\u2014\";\n  let etatCloud;\n  if(cloudInfo.vide === null) etatCloud = \"non encore lu\";\n  else if(cloudInfo.vide) etatCloud = \"<b>vide</b> \u2014 ce poste peut y d\u00e9poser son suivi\";\n  else etatCloud = \"dernier d\u00e9p\u00f4t le \" + new Date(cloudInfo.modifie_le).toLocaleString(\"fr-FR\") + \" par <b>\" + escapeAttr(cloudInfo.modifie_par || \"?\") + \"</b>\";\n  z.innerHTML = `\n    <label>Connexion <i class=\"opt-scope\">Tous</i></label>\n    <span class=\"opt-note\" style=\"display:block; margin-bottom:8px;\">Connect\u00e9 en tant que <b>${escapeAttr(cloudSession.email || \"?\")}</b> \u2014 derni\u00e8re synchro ${dernier}.</span>\n    <span class=\"opt-note\" style=\"display:block; margin-bottom:10px;\">\u00c9tat du cloud : ${etatCloud}.</span>\n    <div style=\"display:flex; gap:8px; flex-wrap:wrap;\">\n      ${cloudInfo.vide ? `<button class=\"primary\" id=\"cloudBtnDeposer\">D\u00e9poser ce suivi</button>` : \"\"}\n      <button class=\"ghost\" id=\"cloudBtnSync\">Synchroniser maintenant</button>\n      <button class=\"ghost\" id=\"cloudBtnSortir\">Se d\u00e9connecter</button>\n    </div>\n    <div class=\"opt-statut ko\" id=\"cloudErreurUI\" ${cloudErreur ? \"\" : \"hidden\"} style=\"margin-top:8px;\"></div>`;\n  const errUI = z.querySelector(\"#cloudErreurUI\");\n  if(cloudErreur){ errUI.hidden = false; errUI.textContent = cloudErreur; }\n  const d = z.querySelector(\"#cloudBtnDeposer\");\n  if(d) d.addEventListener(\"click\", cloudDeposerManuel);\n  z.querySelector(\"#cloudBtnSync\").addEventListener(\"click\", async (ev) => {\n    ev.target.disabled = true; ev.target.textContent = \"Synchronisation\u2026\";\n    await cloudSync(\"manuel\");\n  });\n  z.querySelector(\"#cloudBtnSortir\").addEventListener(\"click\", cloudDeconnexion);\n}\n\nfunction cloudDemarrage(){\n  const btnOpt = document.getElementById(\"optionsBtn\");\n  if(btnOpt) btnOpt.addEventListener(\"click\", cloudRenduOptions);\n  document.addEventListener(\"visibilitychange\", () => { if(!document.hidden) cloudAuFocus(); });\n  window.addEventListener(\"focus\", cloudAuFocus);\n  setInterval(() => cloudSync(\"periode\"), 90000);\n  const el = document.getElementById(\"footCloud\");\n  if(el) el.addEventListener(\"click\", () => {\n    dialogueAlerte(cloudSession\n      ? \"Synchro cloud : \" + (cloudErreur || (\"\u00e0 jour\" + (cloudDernierOK ? \" (dernier \u00e9change \" + cloudDernierOK.toLocaleTimeString(\"fr-FR\") + \")\" : \"\"))) + \".\\nLe d\u00e9tail et les actions sont dans Options, section Cloud.\"\n      : \"Synchro cloud d\u00e9sactiv\u00e9e : connectez-vous dans Options, section Cloud.\", \"Synchro cloud\");\n  });\n  if(cloudSession) cloudSync(\"demarrage\");\n  cloudRenduPastille();\n}\ncloudDemarrage();\n\n;\n\n\n/* \u2500\u2500 v4.79 \u2014 LES PROMESSES DE L'INTERFACE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n   Contr\u00f4le voulu par Hermes (Tours 50-51) et construit ici, main pass\u00e9e. Le\n   constat de d\u00e9part : \u00ab un bouton n'appelle que des fonctions qui existent \u00bb.\n   La m\u00e9thode exacte \u2014 \u00ab une question sur le code se pose au code \u00bb : chaque\n   promesse est v\u00e9rifi\u00e9e par typeof DANS LA PORT\u00c9E du script, l\u00e0 o\u00f9 le clic\n   r\u00e9sout ses noms. Aucune analyse du source, aucun regex sur le JavaScript \u2014\n   la r\u00e9ponse vient du moteur. (Le scanner d'attributs onclick imagin\u00e9 d'abord\n   n'avait rien \u00e0 mordre : ce fichier compte 0 onclick= et 166 addEventListener.)\n\n   La liste est \u00c9CRITE \u00c0 LA MAIN, porte par porte, en lisant les gestionnaires \u2014\n   c'est sa force (z\u00e9ro faux positif) et sa limite (une porte nouvelle n'est\n   couverte que si sa promesse entre ici ; la constitution \u00a76.9 le sait d\u00e9j\u00e0 :\n   les tests prot\u00e8gent ce qu'on a programm\u00e9). Chaque porte nomme les fonctions\n   SANS lesquelles son clic est mort. Les portes internes (fermetures, dialogues\n   g\u00e9n\u00e9riques) sont regroup\u00e9es ; les portes mortes CONNUES et non construites\n   (import de livraison, photos de machines) ne figurent pas ici : elles sont\n   des chantiers, pas des promesses. */\nconst PROMESSES_UI = [\n  { porte:\"\ud83d\udda8 A4 Mission (carte atelier)\", fns:[\"missionA4HTML\"] },\n  { porte:\"\ud83d\udce6 Nouvelle livraison (carte atelier)\", fns:[\"creerLivraison\", \"dialogueDemander\"] },\n  { porte:\"\ud83d\udda8 d'une livraison (dossier hi\u00e9rarchie)\", fns:[\"livraisonImpressionHTML\"] },\n  { porte:\"\ud83d\udd0d Vue CPP (accueil et fiche poste)\", fns:[\"ouvrirVueCpp\", \"renderVueCpp\"] },\n  { porte:\"Carte atelier (barre, accueil, fiche)\", fns:[\"ouvrirCarte\", \"renderCarte\", \"scenariosPostes\", \"renderFichePoste\", \"ouvrirPosteDepuisFiche\"] },\n  { porte:\"Accueil (barre)\", fns:[\"ouvrirAccueil\"] },\n  { porte:\"Tableau de bord (barre)\", fns:[\"renderDashboard\"] },\n  { porte:\"Historique (barre)\", fns:[\"renderHistoryPanel\"] },\n  { porte:\"Backlog (barre)\", fns:[\"renderBacklog\"] },\n  { porte:\"Classeur Matis (barre)\", fns:[\"ouvrirMatis\"] },\n  { porte:\"Recherche (barre et frappe)\", fns:[\"ouvrirRecherche\", \"rendreRecherche\"] },\n  { porte:\"Parcours (barre)\", fns:[\"ouvrirParcours\"] },\n  { porte:\"Nouveaut\u00e9s (barre)\", fns:[\"ouvrirNouveautes\"] },\n  { porte:\"Bandeau reprise (repAtelier/repOuvrir/repFermer)\", fns:[\"allerVers\", \"ouvrirAtelier\", \"renderReprise\"] },\n  { porte:\"Verrouillage (barre)\", fns:[\"toggleLock\"] },\n  { porte:\"Sauvegarde de secours (barre)\", fns:[\"restoreBackup\"] },\n  { porte:\"Export JSON (barre)\", fns:[\"exportData\"] },\n  { porte:\"Export CSV (barre)\", fns:[\"renderCsvPanel\"] },\n  { porte:\"Rapport de validation (barre)\", fns:[\"telechargerRapport\"] },\n  { porte:\"Dossier photos (Options)\", fns:[\"connectPhotosDir\"] },\n  { porte:\"Options (barre)\", fns:[\"syncOptionsUI\"] },\n  { porte:\"Projets \u2014 cr\u00e9er/supprimer/infos (bandeau)\", fns:[\"creerProjet\", \"validerCreationProjet\", \"supprimerProjetActif\", \"enregistrerProjetInfo\"] },\n  { porte:\"Import \u2014 remplacer/fusionner\", fns:[\"appliquerImport\"] },\n  { porte:\"Migration D1D2 et inversion MABEC (propos\u00e9e)\", fns:[\"migrerOutilsD1D2\", \"migrerInversionMabec\"] },\n  { porte:\"Fiche outil \u2014 ouvrir/retirer (OP)\", fns:[\"ouvrirPieceJointe\", \"dialogueConfirmer\"] },\n  { porte:\"Annotations \u2014 enregistrer\", fns:[\"saveAnnotEditor\"] },\n  { porte:\"Ligne \u2014 infos (appliquer en fermant)\", fns:[\"appliquerLigneInfo\"] },\n  { porte:\"Fiches et fonds \u2014 fermer (\u2715, Annuler, fond)\", fns:[\"fermerPanneaux\", \"fermerPanneauxConfirme\", \"fermerDialogue\", \"fermerLightbox\"] }\n];\n\nfunction runTests(){\n  const T = [];\n  const ok = (nom, recu, attendu, tol) => {\n    let pass;\n    if(typeof attendu === \"number\" && typeof recu === \"number\"){\n      pass = Math.abs(recu - attendu) <= (tol === undefined ? 1e-9 : tol);\n    } else {\n      pass = JSON.stringify(recu) === JSON.stringify(attendu);\n    }\n    T.push({ nom, pass, recu, attendu });\n  };\n  const essaiBrut = (id, prels) => ({ id, titre:id, date:\"\", equipe:\"\", operateur:\"\", observations:\"\",\n    but:\"\", maturiteBruts:\"\", prelevements:prels, params:{logements:[]},\n    marposs:{debut:\"\",fin:\"\",releves:[]}, photos:[] });\n  const prel = (id, piece, batt) => ({ id, piece, batt, battD:\"\", battG:\"\", logementId:\"\", pointMesure:\"\" });\n\n  // --- etat reel mis de cote : les tests ne doivent rien laisser derriere eux ---\n  const sauve = { config, data, lignes, projets, activeProjetId, responsables, activeLigneId, activeReferenceId, activeOpId, activeId };\n\n  try{\n    // ---- jeu d'essai : chiffres ronds, pour que l'attendu se verifie a la main ----\n    const cfg = Object.assign({}, defaultConfig, {\n      limitValue: 0.1, limitLabel: \"Battement (mm)\",\n      cycleRefSec: 60, partCoupante: 100, coutDisque: 20\n    });\n    const mkSc = (id, baseline, prix, aretes, charniere, vc, f) => normalizeScenario({\n      id, name: id, baseline, cycle: baseline ? 100 : \"\", emag1: false,\n      outils: [ { id:\"t\"+id, numero:\"T\"+id, logements: [\n        { id:\"g\"+id, nom:\"Piste\", prix, aretes, charniere, vc, f }\n      ] } ],\n      essais: [], scrapLog: [{ id:\"sc1\", date:\"2026-01-01\", equipe:\"Matin\", produites:1000, rebutees:20 }]\n    });\n    const A = mkSc(\"A\", true, 40, 8, 100, 1000, 0.5);   // reference : 40/(8x100) = 0,05\n    const B = mkSc(\"B\", false, 10, 8, 200, 500, 0.5);   // essai     : 10/(8x200) = 0,00625\n    const ligne = normalizeLigne({ id:\"lT\", nom:\"Ligne test\", coutHoraire:50,\n      references:[{ id:\"rT\", nom:\"Ref test\", productionAnnuelle:100000,\n        ops:[{ id:\"oT\", nom:\"OP\", ordre:10, config:cfg, scenarios:[A,B] }] }] });\n\n    lignes = [ligne]; activeLigneId = \"lT\"; activeReferenceId = \"rT\"; activeOpId = \"oT\";\n    config = cfg; data = [A, B]; activeId = \"A\";\n    const refT = ligne.references[0];\n\n    // ---- couts unitaires ----\n    ok(\"posCost = prix/(aretes x charniere)\", posCost(A.outils[0].logements[0]), 0.05);\n    ok(\"posCost : charniere manquante -> null\", posCost({prix:40, aretes:8, charniere:\"\"}), null);\n    ok(\"posCostPerEdge = prix/aretes\", posCostPerEdge(A.outils[0].logements[0]), 5);\n    ok(\"scenarioCost somme les logements\", scenarioCost(B), 0.00625);\n    ok(\"pieceCost = prix/charniere de remplacement\", pieceCost({prix:200, charniere:10000}), 0.02);\n    ok(\"pieceCost : charniere nulle -> null\", pieceCost({prix:200, charniere:0}), null);\n\n    // ---- indice de cycle ----\n    recomputeCycles();\n    ok(\"recomputeCycles : la reference reste a 100\", A.cycle, 100);\n    ok(\"recomputeCycles : indice = 100 x (Vc.f ref)/(Vc.f)\", B.cycle, 200);\n\n    // ---- temps de cycle reel : le coeur de la formule part coupante ----\n    ok(\"cycleSecondes : part 100% -> indice applique a tout le cycle\", cycleSecondes(B, cfg), 120);\n    cfg.partCoupante = 50;\n    ok(\"cycleSecondes : part 50% -> seule la coupe ralentit\", cycleSecondes(B, cfg), 90);\n    ok(\"cycleSecondes : la reference vaut toujours le cycle saisi\", cycleSecondes(A, cfg), 60);\n    cfg.partCoupante = 0;\n    ok(\"cycleSecondes : part 0% -> cycle insensible a Vc/f\", cycleSecondes(B, cfg), 60);\n    cfg.partCoupante = 50;\n    cfg.cycleRefSec = \"\";\n    ok(\"cycleSecondes : cycle de reference absent -> null\", cycleSecondes(B, cfg), null);\n    cfg.cycleRefSec = 60;\n\n    // ---- temps machine ----\n    ok(\"coutMachinePiece : module eteint -> null\", coutMachinePiece(B, cfg, ligne), null);\n    cfg.coutMachineActif = true;\n    ok(\"coutMachinePiece = cout horaire/3600 x cycle\", coutMachinePiece(B, cfg, ligne), 1.25);\n    ok(\"coutMachinePiece : sans cout horaire de ligne -> null\",\n       coutMachinePiece(B, cfg, normalizeLigne({id:\"x\", nom:\"x\", coutHoraire:\"\"})), null);\n    // etat calcule du module (v4.7) : ce que le statut d'Options affiche\n    ok(\"etatCoutMachine : complet quand cycle de reference et cout horaire sont la\", (() => {\n      const et = etatCoutMachine({ coutMachineActif:true, cycleRefSec:\"42\" }, { nom:\"L\", coutHoraire:\"45\" });\n      return et.actif === true && et.manquants.length === 0;\n    })(), true);\n    ok(\"etatCoutMachine : cite le cout horaire manquant\", (() => {\n      const et = etatCoutMachine({ coutMachineActif:true, cycleRefSec:\"42\" }, { nom:\"L\", coutHoraire:\"\" });\n      return !et.actif && et.manquants.length === 1 && et.manquants[0].includes(\"co\u00fbt horaire\");\n    })(), true);\n    ok(\"etatCoutMachine : cite le cycle de reference manquant\", (() => {\n      const et = etatCoutMachine({ coutMachineActif:true, cycleRefSec:\"\" }, { nom:\"L\", coutHoraire:\"45\" });\n      return !et.actif && et.manquants.length === 1 && et.manquants[0].includes(\"cycle\");\n    })(), true);\n    ok(\"etatCoutMachine : module eteint -> jamais actif\", (() => {\n      const et = etatCoutMachine({ coutMachineActif:false, cycleRefSec:\"42\" }, { nom:\"L\", coutHoraire:\"45\" });\n      return !et.actif;\n    })(), true);\n\n    // ---- rebut ----\n    ok(\"coutRebutPiece : module eteint -> null\", coutRebutPiece(B, cfg), null);\n    cfg.coutRebutActif = true;\n    ok(\"coutRebutPiece = taux de rebut x cout disque\", coutRebutPiece(B, cfg), 0.4);\n    // v4.20 \u2014 la saisie annuelle fait foi sur le taux calcule du journal\n    B.tauxRebutAnnuel = 5;\n    ok(\"tauxRebutDe : la saisie annuelle fait foi\", (() => { const t = tauxRebutDe(B); return t.taux === 5 && t.source === \"saisi\"; })(), true);\n    ok(\"coutRebutPiece : taux saisi remplace le taux du journal\", coutRebutPiece(B, cfg), 1.0);\n    B.tauxRebutAnnuel = \"\";\n    ok(\"tauxRebutDe : sans saisie, taux du journal\", (() => { const t = tauxRebutDe(B); return t.taux === 2 && t.source === \"journal\"; })(), true);\n    ok(\"tauxRebutDe : ni saisie ni journal -> null\", tauxRebutDe(normalizeScenario({ id:\"VR\", name:\"VR\", outils:[] })), null);\n\n    // ---- pieces detachees ----\n    cfg.piecesActif = true;\n    ok(\"coutPiecesDetachees : aucune piece declaree -> null\", coutPiecesDetachees(B, cfg), null);\n    B.outils[0].pieces = [ normalizePieceDetachee({nom:\"Cale\", prix:200, charniere:10000}) ];\n    ok(\"coutPiecesDetachees somme les pieces du porte-outil\", coutPiecesDetachees(B, cfg), 0.02);\n\n    // ---- agregation : la ou un null devenu zero fabrique un gain fantome ----\n    const cB = coutsDetail(B, cfg, ligne);\n    ok(\"coutsDetail : total = somme des postes actifs\", cB.total, 0.00625 + 0.02 + 1.25 + 0.4);\n    ok(\"coutsDetail : multiPoste des 2 postes chiffres\", cB.multiPoste, true);\n    const cfgOff = Object.assign({}, cfg, {coutMachineActif:false, piecesActif:false, coutRebutActif:false});\n    const cOff = coutsDetail(B, cfgOff, ligne);\n    ok(\"coutsDetail : modules eteints -> total = plaquettes seules\", cOff.total, 0.00625);\n    ok(\"coutsDetail : un seul poste -> multiPoste faux\", cOff.multiPoste, false);\n    ok(\"coutsDetail : poste inactif reste null, jamais 0\", cOff.machine, null);\n    const cVide = coutsDetail(normalizeScenario({id:\"V\", name:\"V\", outils:[]}), cfgOff, ligne);\n    ok(\"coutsDetail : rien de chiffrable -> total null\", cVide.total, null);\n\n    // ---- charniere reellement atteinte ----\n    ok(\"charniereReelle : aucun essai -> null\", charniereReelle(B, B.outils[0].logements[0].id), null);\n    B.essais = [ essaiBrut(\"e1\", [prel(\"p1\",50,0.05), prel(\"p2\",100,0.05)]) ];\n    let cr = charniereReelle(B, B.outils[0].logements[0].id);\n    ok(\"charniereReelle : aucune sortie de tolerance -> borne inferieure\", cr.borneInf, true);\n    ok(\"charniereReelle : valeur = dernier prelevement conforme\", cr.moyenne, 100);\n    B.essais.push(essaiBrut(\"e2\", [prel(\"p3\",50,0.05), prel(\"p4\",80,0.15)]));\n    cr = charniereReelle(B, B.outils[0].logements[0].id);\n    ok(\"charniereReelle : une sortie de tolerance leve la borne inferieure\", cr.borneInf, false);\n    ok(\"charniereReelle : moyenne des durees observees\", cr.moyenne, 75);\n    ok(\"charniereReelle : nombre d'essais pris en compte\", cr.essais, 2);\n    B.essais.push(essaiBrut(\"e3\", [prel(\"p5\",40,0.15)]));\n    cr = charniereReelle(B, B.outils[0].logements[0].id);\n    ok(\"charniereReelle : hors tolerance des le 1er prelevement -> compte 0, pas ignore\", cr.min, 0);\n    B.essais.pop();\n\n    const ec = ecartsCharniere(B);\n    ok(\"ecartsCharniere : signale le logement passe sous sa cible\", ec.length, 1);\n    ok(\"ecartsCharniere : cout recalcule sur la duree observee\", ec[0].coutReel, 10/(8*75), 1e-9);\n\n    // ---- seuil de bascule ----\n    const totA = coutsDetail(A, cfg, ligne).total;\n    const s = seuilBascule(B, cfg, ligne);\n    ok(\"seuilBascule : gain = cout reference - cout scenario\", s.gain, totA - cB.total, 1e-9);\n    ok(\"seuilBascule : cycle max ramenant au cout de la reference\",\n       s.cycleMaxSec, (totA - (0.00625 + 0.02 + 0.4)) * 3600 / 50, 1e-6);\n    ok(\"seuilBascule : hors plaquettes deja plus cher -> aucune charniere ne compense\",\n       s.charniereImpossible, true);\n    ok(\"seuilBascule : dans ce cas, pas de facteur charniere\", s.facteurCharniere, null);\n    ok(\"seuilBascule : pas de seuil sur la reference elle-meme\", seuilBascule(A, cfg, ligne), null);\n\n    // ---- bilan annuel ----\n    ok(\"bilanAnnuel : module volume eteint -> null\", bilanAnnuel(B, cfgOff, ligne, refT), null);\n    cfg.volumeActif = true;\n    const an = bilanAnnuel(B, cfg, ligne, refT);\n    ok(\"bilanAnnuel : cout annuel = cout piece x volume\", an.coutAnnuel, cB.total * 100000, 1e-6);\n    /* v4.45 \u2014 p\u00e9rim\u00e8tre commun : B porte des pi\u00e8ces d\u00e9tach\u00e9es que A n'a pas, elles\n       sortent du gain (sinon on comparerait un total avec pi\u00e8ces \u00e0 un total sans) */\n    ok(\"bilanAnnuel : gain annuel sur le p\u00e9rim\u00e8tre commun (hors pi\u00e8ces de B, machine des deux c\u00f4t\u00e9s)\",\n       an.gainAnnuel, (totA - cB.total + 0.02) * 100000, 1e-6);\n    ok(\"bilanAnnuel : le poste asym\u00e9trique est signal\u00e9\", an.perimetrePartiel, [\"pi\u00e8ces d\u00e9tach\u00e9es\"]);\n    ok(\"bilanAnnuel : heures machine = ecart de cycle x volume / 3600\", an.heuresAnnuelles, (90-60)*100000/3600, 1e-6);\n    ok(\"bilanAnnuel : plaquettes/an = volume/(aretes x charniere)\", an.plaquettes[0].nb, 100000/(8*200), 1e-9);\n\n    // ---- mise en forme des montants ----\n    ok(\"dlgTexte : echappe le html et preserve les retours a la ligne\", dlgTexte('<b>couleur</b>\\nteste'), \"&lt;b&gt;couleur&lt;/b&gt;<br>teste\");\n    ok(\"dlgTexte : valeur absente -> vide\", dlgTexte(null), \"\");\n    ok(\"fmtEuroCourt : centaines en euros\", fmtEuroCourt(500), \"500 \u20ac\");\n    ok(\"fmtEuroCourt : milliers en k\u20ac\", fmtEuroCourt(167625), \"168 k\u20ac\");\n    ok(\"fmtEuroCourt : millions en M\u20ac\", fmtEuroCourt(1500000), \"1,50 M\u20ac\");\n    ok(\"fmtEuroCourt : valeur absente -> tiret\", fmtEuroCourt(null), \"\u2014\");\n\n    /* ---- prevision d'usure (v3.16) ---------------------------------------------- */\n    const scPrev = normalizeScenario({ id:\"sp\", name:\"prev\", emag1:false, limitOverride:true,\n      limitLabel:\"Battement (mm)\", limitValue:0.12, outils:[] });\n    const essaiPrev = (vals) => ({ id:\"ep\", titre:\"ep\", prelevements: vals.map((v,i) =>\n      ({ id:\"pp\"+i, piece:String((i+1)*20), batt:String(v), battD:\"\", battG:\"\", logementId:\"\", pointMesure:\"\" })),\n      params:{logements:[]}, marposs:{debut:\"\",fin:\"\",releves:[]}, photos:[] });\n    // usure lineaire +0,001/piece a partir de 0,02 : la tolerance 0,12 tombe a la piece 100\n    const pv = previsionUsure(scPrev, essaiPrev([0.04,0.06,0.08,0.10]), null);\n    ok(\"previsionUsure : sortie de tolerance extrapolee\", pv && Math.round(pv.piece), 100);\n    ok(\"previsionUsure : etat prevu\", pv && pv.etat, \"prevu\");\n    ok(\"previsionUsure : moins de 4 points -> pas de prevision\",\n       previsionUsure(scPrev, essaiPrev([0.04,0.06,0.08]), null), null);\n    ok(\"previsionUsure : cote stable -> pas de date de sortie\",\n       (previsionUsure(scPrev, essaiPrev([0.05,0.05,0.05,0.05]), null)||{}).etat, \"stable\");\n    ok(\"previsionUsure : deja hors tolerance signale\",\n       (previsionUsure(scPrev, essaiPrev([0.04,0.08,0.13,0.16]), null)||{}).dejaSortie, true);\n\n    /* ---- fusion de deux fichiers (v3.16) ---------------------------------------- */\n    const arbre = (titre, date, extra) => ([{ id:\"L1\", nom:\"L1\", references:[{ id:\"R1\", nom:\"R1\",\n      ops:[{ id:\"O1\", nom:\"OP10\", config:{}, scenarios:[Object.assign({ id:\"S1\", name:\"S1\",\n        essais:[{ id:\"E1\", titre, modifieLe:date, prelevements:[] }] }, extra||{})] }] }] }]);\n    let cible = arbre(\"local\", \"2026-01-02T00:00:00Z\");\n    let bil = fusionnerLignes(cible, arbre(\"recu\", \"2026-01-03T00:00:00Z\"));\n    ok(\"fusion : la version recue plus recente remplace\", cible[0].references[0].ops[0].scenarios[0].essais[0].titre, \"recu\");\n    ok(\"fusion : comptee comme mise a jour\", bil.essaisMaj, 1);\n    cible = arbre(\"local\", \"2026-01-04T00:00:00Z\");\n    bil = fusionnerLignes(cible, arbre(\"recu\", \"2026-01-03T00:00:00Z\"));\n    ok(\"fusion : la version locale plus recente est conservee\", cible[0].references[0].ops[0].scenarios[0].essais[0].titre, \"local\");\n    ok(\"fusion : comptee comme conservee\", bil.essaisConserves, 1);\n    cible = arbre(\"local\", \"\");\n    bil = fusionnerLignes(cible, arbre(\"recu\", \"\"));\n    ok(\"fusion : dates absentes -> conflit signale, local conserve\", bil.conflits.length, 1);\n    ok(\"fusion : conflit -> aucune ecriture\", cible[0].references[0].ops[0].scenarios[0].essais[0].titre, \"local\");\n    cible = arbre(\"meme\", \"2026-01-02T00:00:00Z\");\n    bil = fusionnerLignes(cible, arbre(\"meme\", \"2026-01-02T00:00:00Z\"));\n    ok(\"fusion : fichiers identiques -> aucun mouvement\", [bil.essaisMaj, bil.essaisConserves, bil.conflits.length], [0,0,0]);\n    // un essai inconnu localement est ajoute, sans toucher a l'existant\n    cible = arbre(\"local\", \"2026-01-02T00:00:00Z\");\n    const recuAvecNouvel = arbre(\"local\", \"2026-01-02T00:00:00Z\");\n    recuAvecNouvel[0].references[0].ops[0].scenarios[0].essais.push({ id:\"E2\", titre:\"neuf\", modifieLe:\"2026-01-05T00:00:00Z\", prelevements:[] });\n    bil = fusionnerLignes(cible, recuAvecNouvel);\n    ok(\"fusion : essai inconnu ajoute\", bil.essaisAjoutes, 1);\n    ok(\"fusion : l'essai existant n'a pas bouge\", cible[0].references[0].ops[0].scenarios[0].essais[0].titre, \"local\");\n    // la structure absente est ajoutee, la structure locale n'est jamais ecrasee\n    cible = arbre(\"local\", \"2026-01-02T00:00:00Z\");\n    const recuAutreScenario = arbre(\"autre\", \"2026-01-09T00:00:00Z\", { id:\"S2\", name:\"S2\" });\n    bil = fusionnerLignes(cible, recuAutreScenario);\n    ok(\"fusion : scenario absent ajoute\", bil.scenarios, 1);\n    ok(\"fusion : le scenario local est intact\", cible[0].references[0].ops[0].scenarios[0].essais[0].titre, \"local\");\n\n    /* ---- projets comme etiquettes (v4.1) -------------------------------------------\n       Le point le plus sensible : une etiquette qui pointe vers un scenario supprime ne\n       doit jamais lever d'exception, et une migration depuis l'ancien format \"propriete\"\n       (v4.0, format 6) ne doit perdre ni mesure ni regroupement. */\n    ok(\"normalizeProjet : statut par defaut\", normalizeProjet({ nom:\"n\" }).statut, \"encours\");\n    ok(\"normalizeProjet : tags par defaut vide\", normalizeProjet({ nom:\"n\" }).tags, []);\n\n    // arbre de test pour resoudreTag/purgerTagsMorts/toggleTagScenario\n    lignes = [ normalizeLigne({ id:\"lT\", nom:\"Ligne test\", references:[\n      { id:\"rT\", nom:\"Ref\", ops:[ { id:\"oT\", nom:\"OP\", config:{}, scenarios:[\n        normalizeScenario({ id:\"scT\", name:\"Sc\" })\n      ] } ] }\n    ] }) ];\n    const tagValide = { ligneId:\"lT\", referenceId:\"rT\", opId:\"oT\", scenarioId:\"scT\" };\n    const tagMort = { ligneId:\"lT\", referenceId:\"rT\", opId:\"oT\", scenarioId:\"introuvable\" };\n    ok(\"resoudreTag : etiquette valide resolue\", !!resoudreTag(tagValide), true);\n    ok(\"resoudreTag : etiquette morte ne leve pas, renvoie null\", resoudreTag(tagMort), null);\n\n    const pjTest = normalizeProjet({ id:\"pjT\", nom:\"Projet test\", tags:[tagValide, tagMort] });\n    const purges = purgerTagsMorts(pjTest);\n    ok(\"purgerTagsMorts : une etiquette morte retiree\", purges, 1);\n    ok(\"purgerTagsMorts : l'etiquette valide reste\", pjTest.tags.length, 1);\n\n    ok(\"projetContientScenario : vrai sur une etiquette posee\", projetContientScenario(pjTest, \"lT\",\"rT\",\"oT\",\"scT\"), true);\n    toggleTagScenario(pjTest, \"lT\",\"rT\",\"oT\",\"scT\");\n    ok(\"toggleTagScenario : retire une etiquette existante\", pjTest.tags.length, 0);\n    toggleTagScenario(pjTest, \"lT\",\"rT\",\"oT\",\"scT\");\n    ok(\"toggleTagScenario : repose l'etiquette retiree\", pjTest.tags.length, 1);\n\n    // migration depuis un arbre format 6 (v4.0, projets PROPRIETAIRES des lignes) :\n    // aucune mesure perdue, le regroupement redevient des etiquettes sur l'arbre commun\n    const arbreFormat6 = { format:6, projets:[\n      { id:\"pjV4\", nom:\"Ancien projet\", problematique:\"Qualite\", responsable:\"Julien\", statut:\"encours\",\n        lignes:[ { id:\"lV4\", nom:\"Step 3\", references:[ { id:\"rV4\", nom:\"Ref V4\", ops:[ { id:\"oV4\", nom:\"OP40\", config:{},\n          scenarios:[ { id:\"scV4\", name:\"Essai\", outils:[], essais:[ { id:\"eV4\", titre:\"E1\",\n            prelevements:[ { id:\"p1\", piece:1, batt:0.03 } ] } ] } ] } ] } ] } ] }\n    ] };\n    const migF6 = migrerArbre(arbreFormat6);\n    ok(\"migrerArbre format 6 : ligne aplatie dans l'arbre commun\", migF6.lignes.map(l=>l.nom), [\"Step 3\"]);\n    ok(\"migrerArbre format 6 : aucune mesure perdue\", comptePrelevements(migF6.lignes), 1);\n    ok(\"migrerArbre format 6 : projet-etiquettes recree avec sa metadonnee\", migF6.projets[0].nom, \"Ancien projet\");\n    ok(\"migrerArbre format 6 : responsable conserve\", migF6.projets[0].responsable, \"Julien\");\n    ok(\"migrerArbre format 6 : etiquette pointant sur le bon scenario\", migF6.projets[0].tags[0].scenarioId, \"scV4\");\n    ok(\"migrerArbre format 6 : etiquette resoluble apres migration\", (() => {\n      const memo = lignes; lignes = migF6.lignes;\n      const r = !!resoudreTag(migF6.projets[0].tags[0]);\n      lignes = memo; return r;\n    })(), true);\n\n    /* ---- responsables geres et couleurs de projet (v4.2) ----------------------------\n       Un ancien projet n'avait qu'un champ texte libre \"responsable\" : la migration doit\n       creer une entree dans la liste geree ET faire le lien, sans jamais planter si la\n       liste est vide ou si la palette de couleurs est epuisee. */\n    const respDefaut = normalizeResponsable({});\n    ok(\"normalizeResponsable : id genere\", typeof respDefaut.id === \"string\" && respDefaut.id.length > 0, true);\n    ok(\"normalizeResponsable : nom/couleur par defaut\", [respDefaut.nom, respDefaut.couleur], [\"\", \"\"]);\n    ok(\"migrerArbre format 6 : un responsable est cree pour le texte libre\", migF6.responsables.length, 1);\n    ok(\"migrerArbre format 6 : le responsable cree s'appelle Julien\", migF6.responsables[0].nom, \"Julien\");\n    ok(\"migrerArbre format 6 : le projet est lie au responsable cree\", migF6.projets[0].responsableId, migF6.responsables[0].id);\n    ok(\"migrerArbre format 6 : une couleur a ete assignee au responsable\", !!migF6.responsables[0].couleur, true);\n    ok(\"migrerArbre format 6 : une couleur a ete assignee au projet\", !!migF6.projets[0].couleur, true);\n\n    ok(\"prochaineCouleurLibre : prend une couleur non utilisee\", OUTIL_COLORS.includes(prochaineCouleurLibre([\"#000000\"])), true);\n    ok(\"prochaineCouleurLibre : ne repropose pas une couleur deja prise tant qu'il en reste une libre\",\n       OUTIL_COLORS.slice(0, 3).includes(prochaineCouleurLibre(OUTIL_COLORS.slice(0, 3))), false);\n    ok(\"prochaineCouleurLibre : recycle la palette une fois epuisee (pas d'exception)\",\n       typeof prochaineCouleurLibre(OUTIL_COLORS.slice()), \"string\");\n\n    // fusion de responsables : correspondance par id ou par nom, jamais de doublon \"Julien\"\n    const respLocaux = [ normalizeResponsable({ id:\"rA\", nom:\"Julien\", couleur:\"#111111\" }) ];\n    const respEntrants = [\n      normalizeResponsable({ id:\"rA-autre-id\", nom:\"Julien\", couleur:\"#222222\" }), // meme nom, id different\n      normalizeResponsable({ id:\"rB\", nom:\"Matis\", couleur:\"#333333\" })\n    ];\n    const ajoutesResp = fusionnerResponsables(respLocaux, respEntrants);\n    ok(\"fusionnerResponsables : Matis (inconnu) est ajoute\", ajoutesResp, 1);\n    ok(\"fusionnerResponsables : Julien (meme nom, id different) n'est pas duplique\", respLocaux.length, 2);\n    ok(\"fusionnerResponsables : la couleur locale de Julien n'est pas ecrasee\", respLocaux[0].couleur, \"#111111\");\n\n    // format 5 (pre-v4, sans projets) : lit normalement, aucun projet invente\n    const arbreFormat5 = { lignes:[ { id:\"l5\", nom:\"L5\", references:[ { id:\"r5\", nom:\"R5\", ops:[ { id:\"o5\", nom:\"OP\", config:{},\n      scenarios:[ { id:\"s5\", name:\"S5\", outils:[], essais:[] } ] } ] } ] } ] };\n    const migF5 = migrerArbre(arbreFormat5);\n    ok(\"migrerArbre format 5 : lignes conservees\", migF5.lignes.map(l=>l.nom), [\"L5\"]);\n    ok(\"migrerArbre format 5 : aucun projet invente\", migF5.projets, []);\n\n    // format 7 (v4.1) : lignes ET projets-etiquettes lus tels quels, sans transformation\n    const arbreFormat7 = { format:7, lignes: arbreFormat5.lignes,\n      projets:[ normalizeProjet({ id:\"pj7\", nom:\"Projet 7\", tags:[{ ligneId:\"l5\", referenceId:\"r5\", opId:\"o5\", scenarioId:\"s5\" }] }) ] };\n    const migF7 = migrerArbre(arbreFormat7);\n    ok(\"migrerArbre format 7 : projets lus sans reconstruction\", migF7.projets[0].nom, \"Projet 7\");\n    ok(\"migrerArbre format 7 : etiquette conservee\", migF7.projets[0].tags.length, 1);\n\n    // fusion de projets-etiquettes : un projet inconnu arrive entier, un projet connu ne\n    // recoit que les etiquettes manquantes, son nom/pilote local n'est jamais ecrase\n    const pjLocalFusion = [ normalizeProjet({ id:\"pjF\", nom:\"Mon nom local\", responsable:\"Benjamin\",\n      tags:[{ ligneId:\"lA\", referenceId:\"rA\", opId:\"oA\", scenarioId:\"scA\" }] }) ];\n    const pjEntrantFusion = [\n      normalizeProjet({ id:\"pjF\", nom:\"Nom recu\", responsable:\"Julien\",\n        tags:[{ ligneId:\"lA\", referenceId:\"rA\", opId:\"oA\", scenarioId:\"scA\" },\n              { ligneId:\"lB\", referenceId:\"rB\", opId:\"oB\", scenarioId:\"scB\" }] }),\n      normalizeProjet({ id:\"pjG\", nom:\"Projet inconnu\", tags:[] })\n    ];\n    const bilanTags = fusionnerProjetsTags(pjLocalFusion, pjEntrantFusion);\n    ok(\"fusionnerProjetsTags : projet inconnu ajoute\", bilanTags.projetsAjoutes, 1);\n    ok(\"fusionnerProjetsTags : etiquette manquante ajoutee\", bilanTags.tagsAjoutes, 1);\n    ok(\"fusionnerProjetsTags : etiquette deja presente non dupliquee\", pjLocalFusion[0].tags.length, 2);\n    ok(\"fusionnerProjetsTags : nom local jamais ecrase\", pjLocalFusion[0].nom, \"Mon nom local\");\n    ok(\"fusionnerProjetsTags : pilote local jamais ecrase\", pjLocalFusion[0].responsable, \"Benjamin\");\n\n    /* ---- filtre des cartes de projet par ligne (v4.1.1) ----------------------------\n       Un projet doit rester DECOUVRABLE meme s'il ne touche pas encore la ligne ouverte\n       (sinon on ne peut jamais y taguer un premier scenario), et un projet cross-ligne ou\n       le projet actif ne doivent jamais disparaitre du bandeau. */\n    const pjEmagSeul = normalizeProjet({ id:\"pjE\", nom:\"E\", tags:[{ ligneId:\"lE\", referenceId:\"r\", opId:\"o\", scenarioId:\"s\" }] });\n    const pjStepSeul = normalizeProjet({ id:\"pjS\", nom:\"S\", tags:[{ ligneId:\"lS\", referenceId:\"r\", opId:\"o\", scenarioId:\"s\" }] });\n    const pjCroise   = normalizeProjet({ id:\"pjX\", nom:\"X\", tags:[\n      { ligneId:\"lE\", referenceId:\"r\", opId:\"o\", scenarioId:\"s\" }, { ligneId:\"lS\", referenceId:\"r\", opId:\"o\", scenarioId:\"s\" }] });\n    // v4.3 : un projet sans etiquette n'est plus visible \"partout\" (c'etait le bug remonte\n    // en usage reel) -- il n'est visible que sur sa ligne de creation, sauf pour un projet\n    // legacy (anterieur a la v4.3, sans le champ ligneCreation) qui garde l'ancien\n    // comportement pour ne pas disparaitre sans explication a la mise a jour.\n    const pjNeufIci  = normalizeProjet({ id:\"pjN\", nom:\"N\", tags:[], ligneCreation:\"lE\" });\n    const pjNeufAncien = { id:\"pjO\", nom:\"O\", tags:[], statut:\"encours\" }; // pas de normalizeProjet : simule un vieux projet sans le champ\n    const memoActifTest = activeProjetId;\n    activeProjetId = null;\n    ok(\"projetVisibleSurLigne : un projet d'une autre ligne est cache\", projetVisibleSurLigne(pjStepSeul, \"lE\"), false);\n    ok(\"projetVisibleSurLigne : un projet de cette ligne reste visible\", projetVisibleSurLigne(pjEmagSeul, \"lE\"), true);\n    ok(\"projetVisibleSurLigne : un projet cross-ligne est visible des deux cotes\", projetVisibleSurLigne(pjCroise, \"lE\") && projetVisibleSurLigne(pjCroise, \"lS\"), true);\n    ok(\"projetVisibleSurLigne : un projet neuf est visible sur sa ligne de creation\", projetVisibleSurLigne(pjNeufIci, \"lE\"), true);\n    ok(\"projetVisibleSurLigne : un projet neuf est cache sur une AUTRE ligne\", projetVisibleSurLigne(pjNeufIci, \"lS\"), false);\n    ok(\"projetVisibleSurLigne : un projet legacy sans ligneCreation reste visible partout\", projetVisibleSurLigne(pjNeufAncien, \"lE\") && projetVisibleSurLigne(pjNeufAncien, \"lS\"), true);\n    activeProjetId = \"pjS\";\n    ok(\"projetVisibleSurLigne : le projet actif reste visible meme hors de sa ligne\", projetVisibleSurLigne(pjStepSeul, \"lE\"), true);\n    activeProjetId = memoActifTest;\n\n    /* ---- filtre reel du travail par projet (v4.3) -----------------------------------\n       opOrganiseParProjets()/scenariosVisibles() sont la vraie correction du bug remonte :\n       activer un projet doit reellement scoper la liste des scenarios sur lesquels on\n       travaille, pas seulement les cartes de projet affichees en haut de l'ecran. */\n    lignes = [ normalizeLigne({ id:\"lF\", nom:\"Ligne filtre\", references:[\n      { id:\"rF\", nom:\"Ref\", ops:[ { id:\"oF\", nom:\"OP\", config:{}, scenarios:[\n        normalizeScenario({ id:\"scF1\", name:\"S1\" }), normalizeScenario({ id:\"scF2\", name:\"S2\" })\n      ] } ] }\n    ] }) ];\n    activeLigneId = \"lF\"; activeReferenceId = \"rF\"; activeOpId = \"oF\";\n    data = lignes[0].references[0].ops[0].scenarios;\n    projets = [];\n    activeProjetId = null;\n    ok(\"scenariosVisibles : sans filtre actif, tout est visible\", scenariosVisibles(), data);\n    const pjFiltreTest = normalizeProjet({ id:\"pjF1\", nom:\"F1\", tags:[{ ligneId:\"lF\", referenceId:\"rF\", opId:\"oF\", scenarioId:\"scF1\" }] });\n    projets = [pjFiltreTest];\n    ok(\"opOrganiseParProjets : vrai des qu'un scenario de l'OP est etiquete\", opOrganiseParProjets(), true);\n    ok(\"scenariosVisibles : OP non organise (aucun projet actif) -> tout est visible\", scenariosVisibles(), data);\n    activeProjetId = \"pjF1\";\n    ok(\"scenariosVisibles : OP organise + projet actif -> ne montre que ses scenarios\", scenariosVisibles().map(s=>s.id), [\"scF1\"]);\n    const pjAutreTest = normalizeProjet({ id:\"pjF2\", nom:\"F2\", tags:[] });\n    projets.push(pjAutreTest);\n    activeProjetId = \"pjF2\";\n    ok(\"scenariosVisibles : projet actif sans etiquette ici -> liste vide (pas tout montrer)\", scenariosVisibles(), []);\n    activeProjetId = null;\n    ok(\"opOrganiseParProjets : faux si aucun scenario de l'OP n'est etiquete nulle part\", (() => {\n      projets = []; return opOrganiseParProjets();\n    })(), false);\n\n    /* ---- scenario en production (v4.4) ---------------------------------------------\n       Un OP n'a jamais qu'un seul \"scenario en production\" (baseline=true), dont le\n       statut est verrouille sur \"serie\" -- promouvoir un autre scenario retrograde\n       l'ancien en \"valide\" (jamais \"abandonne\", ce n'etait pas un echec) plutot que de\n       laisser deux scenarios \"en serie\" coexister. La visibilite du baseline (toujours\n       affiche) reste separee de son appartenance a un projet (jamais comptee de force). */\n    lignes = [ normalizeLigne({ id:\"lP\", nom:\"Ligne prod\", references:[\n      { id:\"rP\", nom:\"Ref\", ops:[ { id:\"oP\", nom:\"OP\", config:{}, scenarios:[\n        normalizeScenario({ id:\"scP1\", name:\"Prod\", baseline:true }),\n        normalizeScenario({ id:\"scP2\", name:\"Alt\" })\n      ] } ] }\n    ] }) ];\n    activeLigneId = \"lP\"; activeReferenceId = \"rP\"; activeOpId = \"oP\";\n    data = lignes[0].references[0].ops[0].scenarios;\n    const scP1 = data[0], scP2 = data[1];\n    ok(\"normalizeScenario : baseline force le statut a serie\", scP1.statut, \"serie\");\n    ok(\"appliquerChangementStatut : refuse de sortir le baseline de serie\", (() => {\n      const fakeEl = { getAttribute: () => \"scP1\", value: \"valide\" };\n      const avant = scP1.statut;\n      const res = appliquerChangementStatut(fakeEl);\n      return !res && scP1.statut === avant;\n    })(), true);\n    projets = []; activeProjetId = null;\n    ok(\"questionsPromotion : annonce le remplacement de la reference en place\", (() => {\n      const qs = questionsPromotion(scP2);\n      return qs.length === 1 && qs[0].texte.includes(\"sc\u00e9nario en production\") && qs[0].texte.includes(scP1.name);\n    })(), true);\n    ok(\"appliquerPromotion : bascule la reference et retrograde l'ancien en valide\", (() => {\n      const res = appliquerPromotion(scP2);\n      return res === true && scP2.baseline === true && scP2.statut === \"serie\" && scP1.baseline === false && scP1.statut === \"valide\";\n    })(), true);\n    ok(\"promouvoirEnProduction : refuse sans mutation quand la question est refusee\", (() => {\n      const res = promouvoirEnProduction(scP1, () => false);\n      return res === false && scP2.baseline === true && scP1.baseline === false;\n    })(), true);\n    // a ce stade, scP2 est devenu le scenario en production (promotion ci-dessus) ; le\n    // projet ne rattache que scP1 -- scP2 doit malgre tout rester visible (exemption),\n    // sans pour autant etre compte comme membre du projet (separation affichage/stats).\n    const pjSansBaseline = normalizeProjet({ id:\"pjProd\", nom:\"Prod\", tags:[{ ligneId:\"lP\", referenceId:\"rP\", opId:\"oP\", scenarioId:\"scP1\" }] });\n    projets = [pjSansBaseline]; activeProjetId = \"pjProd\";\n    ok(\"scenariosVisibles : le scenario en production reste visible meme non etiquete dans le projet actif\", scenariosVisibles().map(s=>s.id).sort(), [\"scP1\",\"scP2\"].sort());\n    ok(\"projetContientScenario : le baseline visible mais non etiquete ne compte pas dans le projet\", projetContientScenario(pjSansBaseline, \"lP\",\"rP\",\"oP\",\"scP2\"), false);\n    activeProjetId = null;\n\n    /* ---- garde-fous homonymes (v4.5) -----------------------------------------------\n       Deux scenarios du meme nom \"en serie\" sur la meme ligne, etiquetes dans deux projets\n       differents : le tableau de bord additionne deux fois le meme gain physique. La\n       detection doit etre exacte (casse/espaces) et ne rien signaler sur les cas sains. */\n    const memLigne = () => normalizeLigne({ id:\"lH\", nom:\"EMAG 1\", references:[\n      { id:\"rH\", nom:\"Ref\", ops:[ { id:\"oH\", nom:\"OP10\", config:{}, scenarios:[\n        normalizeScenario({ id:\"sH1\", name:\"Plaquette NG\", statut:\"serie\", statutDate:\"2026-09-01\" }),\n        normalizeScenario({ id:\"sH2\", name:\"Autre chose\", statut:\"serie\", statutDate:\"2026-09-01\" }),\n        normalizeScenario({ id:\"sH3\", name:\"plaquette ng\", statut:\"essai\" }) // meme nom, casse diff, pas en serie\n      ] } ] }\n    ] });\n    const memoProjetsH = projets;\n    const ligneH = memLigne();\n    lignes = [ligneH];\n    const pjH1 = normalizeProjet({ id:\"pjH1\", nom:\"Projet H1\", tags:[{ ligneId:\"lH\", referenceId:\"rH\", opId:\"oH\", scenarioId:\"sH1\" }] });\n    const pjH2 = normalizeProjet({ id:\"pjH2\", nom:\"Projet H2\", tags:[{ ligneId:\"lH\", referenceId:\"rH\", opId:\"oH\", scenarioId:\"sH1\" }] }); // meme scenario dans 2 projets : pas un homonyme (c'est le meme objet)\n    projets = [pjH1, pjH2];\n    ok(\"homonymes : le meme scenario etiquete dans 2 projets n'est PAS un homonyme\", scenariosSerieHomonymes().length, 0);\n    // deux scenarios DIFFERENTS du meme nom, en serie, sur la meme ligne : le vrai piege\n    const ligneH2 = memLigne();\n    const sH1bis = normalizeScenario({ id:\"sH1bis\", name:\"  plaquette ng \", statut:\"serie\", statutDate:\"2026-09-02\" }); // casse+espaces : homonyme quand meme\n    ligneH2.references[0].ops[0].scenarios.push(sH1bis);\n    lignes = [ligneH2];\n    const pjH3 = normalizeProjet({ id:\"pjH3\", nom:\"Projet H3\", tags:[{ ligneId:\"lH\", referenceId:\"rH\", opId:\"oH\", scenarioId:\"sH1\" }] });\n    const pjH4 = normalizeProjet({ id:\"pjH4\", nom:\"Projet H4\", tags:[{ ligneId:\"lH\", referenceId:\"rH\", opId:\"oH\", scenarioId:\"sH1bis\" }] });\n    projets = [pjH3, pjH4];\n    const homTrouves = scenariosSerieHomonymes();\n    ok(\"homonymes : deux scenarios homonymes en serie dans 2 projets detectes\", homTrouves.length, 1);\n    ok(\"homonymes : les deux projets sont cites\", homTrouves.length && homTrouves[0].projets.length, 2);\n    ok(\"homonymes : un seul scenario en serie, pas de signalement\", (() => {\n      const pjSeul = normalizeProjet({ id:\"pjSeul\", nom:\"Seul\", tags:[{ ligneId:\"lH\", referenceId:\"rH\", opId:\"oH\", scenarioId:\"sH1\" }] });\n      projets = [pjSeul];\n      const r = scenariosSerieHomonymes().length;\n      projets = [pjH3, pjH4];\n      return r;\n    })(), 0);\n    // avertissementSerieHomonymes : le scenario qui va passer en serie vs un homonyme deja en serie\n    ok(\"avertissement : le scenario homonyme deja en serie est cite avec son projet\", (() => {\n      activeLigneId = \"lH\"; activeReferenceId = \"rH\"; activeOpId = \"oH\";\n      const res = avertissementSerieHomonymes(sH1bis);\n      return res.length === 1 && /Projet H3/.test(res[0]) && /Plaquette NG/.test(res[0]);\n    })(), true);\n    ok(\"avertissement : un scenario sans homonyme en serie ne declenche rien\", (() => {\n      const res = avertissementSerieHomonymes(ligneH2.references[0].ops[0].scenarios[1]); // sH2 \u00ab Autre chose \u00bb\n      return res.length === 0;\n    })(), true);\n    projets = memoProjetsH;\n\n    /* ---- plan d'outil (v3.18) ----------------------------------------------------\n       Un plan perdu au rechargement serait invisible : normalizeOutil doit le conserver\n       tel quel, et poser null par defaut sur les outils venus d'un fichier anterieur. */\n    ok(\"normalizeOutil : plan absent -> null\", normalizeOutil({ numero:\"T1\" }).plan, null);\n    const planTest = { filename:\"plan_x.pdf\", mime:\"application/pdf\", stockage:\"dossier\", addedAt:\"2026-09-05T10:00:00Z\" };\n    ok(\"normalizeOutil : plan conserve a l'identique\", normalizeOutil({ numero:\"T1\", plan:planTest }).plan, planTest);\n    /* ---- inventaire du poids (v3.19) ----------------------------------------------\n       Ce qui est stocke dans le dossier local ne pese RIEN dans le fichier de suivi : le\n       confondre avec une piece jointe integree enverrait l'utilisateur alleger le mauvais\n       fichier. */\n    lignes = [{ id:\"lP\", nom:\"L\", references:[{ id:\"rP\", nom:\"R\", ops:[{ id:\"oP\", nom:\"OP\", config:{},\n      ficheOutil:{ filename:\"f.pdf\", stockage:\"fichier\", dataUrl:\"x\".repeat(2048) },\n      scenarios:[{ id:\"sP\", name:\"S\", outils:[\n        { id:\"t1\", numero:\"T-INT\", plan:{ filename:\"p1.pdf\", stockage:\"fichier\", dataUrl:\"y\".repeat(4096) }, logements:[] },\n        { id:\"t2\", numero:\"T-DOS\", plan:{ filename:\"p2.pdf\", stockage:\"dossier\" }, logements:[] }\n      ], essais:[] }] }] }] }];\n    const inv = inventairePoids();\n    ok(\"inventairePoids : ne compte que les pieces integrees au fichier\",\n       inv.filter(i => /T-INT|T-DOS|Fiche outil/.test(i.quoi)).map(i => i.quoi.split(\" \u2014\")[0]).sort(),\n       [\"Fiche outil\", \"Plan outil T-INT\"]);\n    ok(\"inventairePoids : le plus lourd en premier\", inv[0].octets >= inv[inv.length-1].octets, true);\n    lignes = sauve.lignes;\n\n    /* ---- apercu : distinguer \"pas encore saisi\" et \"saisi mais inexploitable\" (v3.19.1) --\n       Remonte par le jeu de stress externe : un logement a 0 arete affichait \"Co\u00fbt \u2014\" sans\n       que rien ne fasse le lien avec la cause, pourtant lisible juste au-dessus. */\n    const scAp = normalizeScenario({ id:\"sAp\", name:\"ap\", limitOverride:true, limitValue:0.12, outils:[\n      { id:\"tA\", numero:\"T-0\", logements:[{ id:\"gA\", nom:\"Piste\", ref:\"X\", prix:0, aretes:0, charniere:100 }] }] });\n    const tuile0 = apercuLogementHTML(scAp, scAp.outils[0], scAp.outils[0].logements[0], \"#000\", 0);\n    ok(\"apercu : 0 arete signale comme bloquant\", /Co\u00fbt non calculable[^<]*ar\u00eates \u00e0 0/.test(tuile0), true);\n    ok(\"apercu : une valeur saisie n'est pas listee comme manquante\", /Manque/.test(tuile0), false);\n    const scVide = normalizeScenario({ id:\"sVi\", name:\"vi\", outils:[\n      { id:\"tB\", numero:\"T-1\", logements:[{ id:\"gB\", nom:\"Piste\", ref:\"\", prix:\"\", aretes:\"\", charniere:\"\" }] }] });\n    ok(\"apercu : cases vides listees comme manquantes\",\n       /Manque : r\u00e9f\u00e9rence, prix, ar\u00eates, charni\u00e8re/.test(apercuLogementHTML(scVide, scVide.outils[0], scVide.outils[0].logements[0], \"#000\", 0)), true);\n\n    /* ---- v4.19 : ordre des outils par glisser-deposer + cout annuel par logement ---- */\n    {\n      const scOrd = normalizeScenario({ id:\"sOrd\", name:\"ord\", outils:[\n        { id:\"tX\", numero:\"X\", logements:[] },\n        { id:\"tY\", numero:\"Y\", logements:[] },\n        { id:\"tZ\", numero:\"Z\", logements:[] }\n      ]});\n      deplacerOutil(scOrd, \"tY\", \"tX\");\n      ok(\"deplacerOutil : le milieu passe en premiere position\", scOrd.outils.map(o => o.id), [\"tY\",\"tX\",\"tZ\"]);\n      deplacerOutil(scOrd, \"tY\", \"tY\");\n      ok(\"deplacerOutil : deplacer sur soi-meme ne fait rien\", scOrd.outils.map(o => o.id), [\"tY\",\"tX\",\"tZ\"]);\n      ok(\"deplacerOutil : id inconnu -> false\", deplacerOutil(scOrd, \"tQ\", \"tX\"), false);\n      ok(\"libelleAnnuel : sous 10 k\u20ac en euros\", libelleAnnuel(950), \"950 \u20ac/an\");\n      ok(\"libelleAnnuel : au-dela en milliers d'euros\", libelleAnnuel(12000), \"12,0 k\u20ac/an\");\n      ok(\"couleurPartCout : part majeure -> rouge\", /^hsl\\(0, /.test(couleurPartCout(3)), true);\n      ok(\"couleurPartCout : part mineure -> vert\", /^hsl\\(145, /.test(couleurPartCout(0.2)), true);\n      const scAnn = normalizeScenario({ id:\"sAnn\", name:\"ann\", outils:[\n        { id:\"tA1\", numero:\"A\", logements:[{ id:\"gA1\", nom:\"Piste\", ref:\"R\", prix:10, aretes:5, charniere:100 }] }] });\n      // posCost = 10/(5x100) = 0,02 \u20ac/piece ; volume 150 000 -> 3 000 \u20ac/an\n      const tuileAnn = apercuLogementHTML(scAnn, scAnn.outils[0], scAnn.outils[0].logements[0], \"#000\", 0, 150000, 3000, 1);\n      ok(\"apercu : cout annuel affiche sur la tuile quand volume connu\",\n         /ap-annuel/.test(tuileAnn) && /3[\\s\\u00a0\\u202f]000 \u20ac\\/an/.test(tuileAnn), true);\n      ok(\"apercu : sans volume, pas de cout annuel\",\n         /ap-annuel/.test(apercuLogementHTML(scAnn, scAnn.outils[0], scAnn.outils[0].logements[0], \"#000\", 0)), false);\n    }\n\n    /* ---- v4.22 : noms actuels dans les graphes + copie des outils de la production ---- */\n    {\n      const scNom = normalizeScenario({ id:\"sNom\", name:\"nom\", baseline:true, outils:[\n        { id:\"tN1\", numero:\"T-A\", logements:[{ id:\"gN1\", nom:\"Piste\", prix:10, aretes:5, charniere:100, vc:500, f:0.35 }] }\n      ]});\n      scNom.essais = [ essaiBrut(\"eN1\", [prel(\"pN1\",10,0.05)]) ];\n      scNom.essais[0].params = { logements: snapshotLogements(scNom) };\n      scNom.essais[0].prelevements[0].logementId = \"gN1\";\n      // renommage APRES la creation de l'essai : le graphe doit suivre (bug \"nom reste en memoire\")\n      scNom.outils[0].numero = \"T-B\";\n      scNom.outils[0].logements[0].nom = \"Piste V2\";\n      const series = seriesTendance(scNom, r => valeurMesuree(scNom, r));\n      ok(\"noms actuels : le graphe des prelevements suit le renommage\",\n         /T-B\u00b7Piste V2/.test(series[0].titre), true);\n      const nFallback = nomLogementActuel(scNom, { outilId:\"tX\", logementId:\"gDisparu\", outilNumero:\"T-Ancien\", logementNom:\"Bol ancien\" });\n      ok(\"noms actuels : logement retire -> repli sur le nom fige\",\n         nFallback.outilNumero === \"T-Ancien\" && nFallback.logementNom === \"Bol ancien\", true);\n      const scCopie = normalizeScenario({ id:\"sCopie\", name:\"copie\", outils:[] });\n      // on isole data le temps du test, pour que baselineScenario() soit deterministe\n      const dataSauvee = data;\n      data = [scNom, scCopie];\n      const outilBase = scNom.outils[0];\n      outilBase.plan = { filename:\"p.pdf\", stockage:\"fichier\", dataUrl:\"x\" };\n      const nCopies = copierOutilsDeProduction(scCopie, [outilBase.id]);\n      const copieO = scCopie.outils[0];\n      ok(\"copie outils : la selection arrive complete\",\n         nCopies === 1 && copieO.numero === \"T-B\" && copieO.logements[0].nom === \"Piste V2\" && copieO.logements[0].prix === 10, true);\n      ok(\"copie outils : nouveaux identifiants, pas de collision\",\n         copieO.id !== \"tN1\" && copieO.logements[0].id !== \"gN1\", true);\n      ok(\"copie outils : pas de plan copie\", copieO.plan, null);\n      data = dataSauvee;\n      outilBase.plan = null;\n    }\n\n    /* ---- v4.23 : le volume annuel est trace sur la reference ---- */\n    {\n      const refV = { nom:\"R\", productionAnnuelle: 148942 };\n      enregistrerVolumeAnnuel(refV, 200000);\n      ok(\"volume annuel : changement trace avec valeur et date\",\n         refV.productionAnnuelle === 200000 && refV.volumeHistorique.length === 1 &&\n         refV.volumeHistorique[0].valeur === 200000 && !!refV.volumeHistorique[0].date, true);\n      enregistrerVolumeAnnuel(refV, 200000);\n      ok(\"volume annuel : reecrire la meme valeur ne trace pas\", refV.volumeHistorique.length === 1, true);\n      enregistrerVolumeAnnuel(refV, \"\");\n      ok(\"volume annuel : vider le champ est trace aussi\",\n         refV.productionAnnuelle === \"\" && refV.volumeHistorique.length === 2, true);\n      const refCap = { productionAnnuelle: \"\" };\n      for(let i = 0; i < 15; i++) enregistrerVolumeAnnuel(refCap, i);\n      ok(\"volume annuel : historique plafonne a 10 entrees\",\n         refCap.volumeHistorique.length === 10 && refCap.volumeHistorique[0].valeur === 14, true);\n      ok(\"volume annuel : reference absente -> sans effet\", enregistrerVolumeAnnuel(null, 5), undefined);\n    }\n\n    /* ---- v4.24 : photos de l'essai dans le rapport autonome ---- */\n    {\n      ok(\"dimensionsAplaties : sans crop, taille entiere sous plafond\", (() => {\n        const d = dimensionsAplaties(2000, 1000, null, 1200);\n        return d.w === 1200 && d.h === 600 && d.crop === null;\n      })(), true);\n      ok(\"dimensionsAplaties : le crop rogne avant le plafond\", (() => {\n        const d = dimensionsAplaties(2000, 1000, { x:0.25, y:0.25, w:0.5, h:0.5 }, 1200);\n        return d.w === 1000 && d.h === 500 && !!d.crop;\n      })(), true);\n      ok(\"dimensionsAplaties : petite image jamais agrandie\", (() => {\n        const d = dimensionsAplaties(800, 400, null, 1200);\n        return d.w === 800 && d.h === 400;\n      })(), true);\n      ok(\"photosRapportHTML : aucune section sans photos\", photosRapportHTML(null), \"\");\n      ok(\"photosRapportHTML : photo absente nommee avec sa raison\", (() => {\n        const h = photosRapportHTML([{ legende: \"Usure ar\u00eate\", erreur: \"dossier photos local non connect\u00e9\" }]);\n        return /Photo non incorpor\u00e9e/.test(h) && /dossier photos local non connect\u00e9/.test(h) && /Usure ar\u00eate/.test(h);\n      })(), true);\n      ok(\"photosRapportHTML : photo incorpor\u00e9e avec sa l\u00e9gende\", (() => {\n        const h = photosRapportHTML([{ legende: \"Metrologie portance\", dataUrl: \"data:image/jpeg;base64,XY\" }]);\n        return /<img src=\"data:image\\/jpeg/.test(h) && /Metrologie portance/.test(h);\n      })(), true);\n    }\n\n    /* ---- v4.25 : cl\u00f4ture d'essai (arr\u00eat anticip\u00e9) ---- */\n    {\n      const scC = normalizeScenario({ id:\"sC\", name:\"c\", baseline:true, outils:[\n        { id:\"tC1\", numero:\"T-1\", logements:[{ id:\"gC1\", nom:\"Piste\", charniere:100 }] }] });\n      scC.essais = [ essaiBrut(\"eC1\", [prel(\"pC1\",10,0.05)]) ];\n      scC.essais[0].params = { logements: snapshotLogements(scC) };\n      ok(\"cloture : sans cloture, essai en cours\", essaiStats(scC, scC.essais[0]).status, \"pending\");\n      scC.essais[0].cloture = { motif: \"casse\", detail: \"\u00e9clat ar\u00eate Inter p37\", date: \"2026-09-23\" };\n      const stC = essaiStats(scC, scC.essais[0]);\n      ok(\"cloture : statut arrete avec motif et detail\",\n         stC.status === \"arrete\" && /Casse/.test(stC.raison) && /\u00e9clat ar\u00eate/.test(stC.raison), true);\n      const sStats = scenarioStats(scC);\n      ok(\"cloture : ni conforme ni non conforme dans le protocole 5x\",\n         sStats.validCount === 0 && sStats.badCount === 0 && sStats.arreteCount === 1, true);\n      ok(\"cloture : sort du bandeau de reprise\",\n         (dernierEssaiEnCours() || { essaiId: null }).essaiId !== \"eC1\", true);\n      ok(\"cloture : libelle motif inconnu non bloquant\", libelleMotifArret(\"x\"), \"x\");\n      delete scC.essais[0].cloture;\n      ok(\"cloture : r\u00e9ouverture redonne un essai en cours\",\n         essaiStats(scC, scC.essais[0]).status, \"pending\");\n    }\n\n    /* ---- v4.25 : bandeau de reprise contextualis\u00e9 + nouveaut\u00e9s 10 jours ---- */\n    {\n      // le sc\u00e9nario AFFICH\u00c9 gagne : son essai en cours passe, m\u00eame moins r\u00e9cent\n      const scR = normalizeScenario({ id:\"sReprise\", name:\"reprise\", outils:[] });\n      const essaiVieux = { id:\"eV\", titre:\"Essai ancien\", date:\"2026-09-01\",\n        modifieLe:\"2026-09-01T08:00:00.000Z\", prelevements:[], params:{ logements:[] } };\n      const essaiRecent = { id:\"eR\", titre:\"Essai r\u00e9cent ailleurs\", date:\"2026-09-23\",\n        modifieLe:\"2026-09-23T08:00:00.000Z\", prelevements:[], params:{ logements:[] } };\n      const lignesSauvees = lignes, actifSauve = activeId;\n      lignes = [{ id:\"lR\", nom:\"L\", references:[{ id:\"rR\", nom:\"R\", ops:[{ id:\"oR\", nom:\"OP\", config:{},\n        scenarios:[\n          normalizeScenario(Object.assign({}, scR, { id:\"sAutre\" })),\n          normalizeScenario({ id:\"sActif\", name:\"actif\", outils:[], essais:[essaiVieux] })\n        ] } ] } ] }];\n      // essai r\u00e9cent dans l'AUTRE sc\u00e9nario, essai vieux dans le sc\u00e9nario affich\u00e9\n      lignes[0].references[0].ops[0].scenarios[0].essais = [essaiRecent];\n      activeId = \"sActif\";\n      ok(\"reprise : l'essai du sc\u00e9nario affich\u00e9 passe devant le plus r\u00e9cent\",\n         dernierEssaiEnCours().essaiId, \"eV\");\n      activeId = \"sAutre\";\n      ok(\"reprise : hors contexte, le plus r\u00e9cent gagne\",\n         dernierEssaiEnCours().essaiId, \"eR\");\n      lignes = lignesSauvees; activeId = actifSauve;\n      // nouveaut\u00e9s : les entr\u00e9es de plus de 10 jours ne s'affichent plus\n      NOUVEAUTES.push({ version:\"0.0.0-test\", date:\"01/01/2026\", points:[\"ancienne\"] });\n      const htmlNv = nouveautesHTML();\n      NOUVEAUTES.pop();\n      ok(\"nouveautes : entr\u00e9e de plus de 10 jours masqu\u00e9e\", /0\\.0\\.0-test/.test(htmlNv), false);\n      /* l'\u00ab entr\u00e9e du jour \u00bb est l'entr\u00e9e de la version COURANTE \u2014 jamais un\n         num\u00e9ro cod\u00e9 en dur : ancr\u00e9 \u00e0 4.25.0, ce test s'est p\u00e9rim\u00e9 tout seul\n         dix versions plus tard (vu le 12/10 en 4.81.0, et il aurait \u00e9chou\u00e9\n         sur la 4.80.0 aussi). L'invariant : l'entr\u00e9e de TOOL_VERSION reste\n         visible tant qu'elle a moins de 10 jours. */\n      ok(\"nouveautes : l'entr\u00e9e du jour (la version courante) reste visible\",\n         new RegExp(TOOL_VERSION.split(\".\").join(\"\\\\.\")).test(htmlNv), true);\n    }\n\n    /* ---- v4.27 : r\u00e9f\u00e9rentiel lignes Sept Fons (familles, ordre atelier) ---- */\n    {\n      ok(\"familleDeLigne : Weisser -> rouge\", familleDeLigne(\"Weisser 2\"), \"weisser\");\n      ok(\"familleDeLigne : HESSAPP (orthographes) -> kaki\",\n         familleDeLigne(\"HESSAPP\") === \"hessapp\" && familleDeLigne(\"Hessapp 1\") === \"hessapp\", true);\n      ok(\"familleDeLigne : EMAG -> gris, PCI -> bleu\",\n         familleDeLigne(\"EMAG 3\") === \"emag\" && familleDeLigne(\"PCI 1\") === \"pci\", true);\n      ok(\"familleDeLigne : inconnue -> vide\", familleDeLigne(\"TOSHIBA 1\"), \"\");\n      ok(\"rangLigneSeptFons : l'ordre atelier du fond vers l'entr\u00e9e\",\n         rangLigneSeptFons(\"Weisser 1\") < rangLigneSeptFons(\"HESSAPP\") &&\n         rangLigneSeptFons(\"HESSAPP\") < rangLigneSeptFons(\"EMAG 1\") &&\n         rangLigneSeptFons(\"EMAG 1\") < rangLigneSeptFons(\"PCI 2\"), true);\n      ok(\"rangLigneSeptFons : ligne inconnue apr\u00e8s le r\u00e9f\u00e9rentiel\",\n         rangLigneSeptFons(\"MACHINE X\") === LIGNES_SEPT_FONS.length, true);\n    }\n\n    /* ---- v4.29 : d\u00e9tail du co\u00fbt annuel + lignes couvertes par un projet ---- */\n    {\n      // arbre contr\u00f4l\u00e9 : les sections pr\u00e9c\u00e9dentes reassignent lignes/data, on isole\n      const volAvant = config.volumeActif;\n      const sauve = { lignes, data, activeLigneId, activeReferenceId, activeOpId, activeId };\n      config.volumeActif = true;\n      lignes = [ normalizeLigne({ id:\"l29\", nom:\"Ligne test\", coutHoraire:50,\n        references:[{ id:\"r29\", nom:\"Ref\", productionAnnuelle:100000,\n          ops:[{ id:\"o29\", nom:\"OP\", ordre:10, config, scenarios:[A, B] }] }] }) ];\n      activeLigneId = \"l29\"; activeReferenceId = \"r29\"; activeOpId = \"o29\";\n      data = [A, B]; activeId = \"A\";\n      const pjT = { id:\"pjX\", nom:\"co\u00fbt EMAG 1\", tags:[\n        { ligneId:\"l29\", referenceId:\"r29\", opId:\"o29\", scenarioId:\"A\" }\n      ]};\n      ok(\"lignesDuProjet : la ligne du sc\u00e9nario \u00e9tiquet\u00e9\", lignesDuProjet(pjT), [\"Ligne test\"]);\n      const detA = coutAnnuelDetailHTML(A, bilanAnnuel(A, config, null, null));\n      ok(\"coutAnnuelDetail : la baseline d\u00e9taille outillage par logement + total\",\n         /Outillage : co\u00fbt plaquette/.test(detA) && /Piste \\(40,00 \u20ac \u00f7 8 \u00d7 100\\)/.test(detA) &&\n         /Total = co\u00fbt complet pi\u00e8ce \u00d7 production/.test(detA), true);\n      const detB = coutAnnuelDetailHTML(B, bilanAnnuel(B, config, null, null));\n      ok(\"coutAnnuelDetail : le sc\u00e9nario d'essai d\u00e9taille le gain vs la r\u00e9f\u00e9rence\",\n         /R\u00e9f\u00e9rence \u00ab/.test(detB) && /Gain annuel = r\u00e9f\u00e9rence \u2212 sc\u00e9nario/.test(detB), true);\n      lignes = sauve.lignes; data = sauve.data;\n      activeLigneId = sauve.activeLigneId; activeReferenceId = sauve.activeReferenceId;\n      activeOpId = sauve.activeOpId; activeId = sauve.activeId;\n      config.volumeActif = volAvant;\n      ok(\"coutAnnuelDetail : sans volume, rien \u00e0 d\u00e9tailler\",\n         coutAnnuelDetailHTML(A, null), \"\");\n    }\n\n    /* ---- v4.30 : dur\u00e9e de vie du sc\u00e9nario (cellule du tableau de bord + ratio du verdict) ---- */\n    ok(\"dureeVieScenario = charni\u00e8re du logement de r\u00e9f\u00e9rence\", dureeVieScenario(A), 100);\n    ok(\"dureeVieScenario : sc\u00e9nario d'essai\", dureeVieScenario(B), 200);\n    ok(\"dureeVieScenario : charni\u00e8re manquante -> null\",\n       dureeVieScenario(normalizeScenario({ id:\"X\", name:\"X\", baseline:false,\n         outils:[{ id:\"tX\", numero:\"TX\", logements:[{ id:\"gX\", nom:\"Piste\", prix:10, aretes:8, charniere:\"\", vc:500, f:0.5 }] }] })), null);\n\n    /* ---- v4.39/v4.41 : cycle par logement \u2014 somme DANS l'outil, groupes d'outils simultan\u00e9s ---- */\n    {\n      const mkCyc = (sims, coupe2) => normalizeScenario({\n        id:\"C\", name:\"C\", baseline:false,\n        outils: [\n          { id:\"tC1\", numero:\"TC1\", logements: [\n            { id:\"gC1\", nom:\"Logement 1\", prix:20, aretes:8, charniere:100, vc:800, f:0.4, tempsCoupe:30, tempsDeplacement:7 },\n            { id:\"gC2\", nom:\"Logement 2\", prix:20, aretes:8, charniere:100, vc:400, f:0.4, tempsCoupe:coupe2, tempsDeplacement:7 }\n          ] },\n          { id:\"tC2\", numero:\"TC2\", simultaneAvecPrecedent: sims[0], logements: [\n            { id:\"gC3\", nom:\"Piste\", prix:20, aretes:8, charniere:100, vc:500, f:0.5, tempsCoupe:20, tempsDeplacement:7 }\n          ] },\n          { id:\"tC3\", numero:\"TC3\", simultaneAvecPrecedent: sims[1], logements: [\n            { id:\"gC4\", nom:\"Finition\", prix:20, aretes:8, charniere:100, vc:500, f:0.5, tempsCoupe:25, tempsDeplacement:7 }\n          ] }\n        ],\n        essais: []\n      });\n      ok(\"cycleDetailStatus : aucune case = outils en s\u00e9rie, somme de tout (d\u00e9placement ignor\u00e9)\",\n         cycleDetailStatus(mkCyc([false,false], 20), {}).secs, 95);\n      ok(\"cycleDetailStatus : TC2 simultan\u00e9 avec TC1 -> groupes [TC1+TC2]=50 et [TC3]=25\",\n         cycleDetailStatus(mkCyc([true,false], 20), {}).secs, 75);\n      ok(\"cycleDetailStatus : TC2 et TC3 simultan\u00e9s -> un seul groupe, le plus long outil\",\n         cycleDetailStatus(mkCyc([true,true], 20), {}).secs, 50);\n      ok(\"cycleDetailStatus : TC3 seul simultan\u00e9 -> groupes [TC1]=50 et [TC2+TC3]=25\",\n         cycleDetailStatus(mkCyc([false,true], 20), {}).secs, 75);\n      const stIncomplet = cycleDetailStatus(mkCyc([false,false], \"\"), {});\n      ok(\"cycleDetailStatus : un temps de coupe manquant -> mesures ignor\u00e9es (null)\",\n         [stIncomplet.complete, stIncomplet.secs, stIncomplet.filled], [false, null, 3]);\n      ok(\"logementCycle : le premier logement ancre l'indice, quel que soit son nom\",\n         logementCycle(mkCyc([false,false], 20)).nom, \"Logement 1\");\n    }\n\n    /* ---- v4.41.1 : cadenceHeure + migration du mode global 4.39/4.40 ---- */\n    ok(\"cadenceHeure : indice 100 sur reference 60 s -> 60 p/h\", cadenceHeure(A, cfg), 60);\n    ok(\"cadenceHeure : cycle absent -> null\", cadenceHeure(normalizeScenario({ id:\"Z\", name:\"Z\", baseline:false, cycle:\"\", outils:[] }), cfg), null);\n    {\n      const mig = normalizeScenario({ id:\"M\", name:\"M\", baseline:false, outilsParalleles:true,\n        outils: [\n          { id:\"tM1\", numero:\"M1\", logements:[{ id:\"gM1\", nom:\"A\", prix:10, aretes:8, charniere:100, tempsCoupe:10 }] },\n          { id:\"tM2\", numero:\"M2\", logements:[{ id:\"gM2\", nom:\"B\", prix:10, aretes:8, charniere:100, tempsCoupe:10 }] },\n          { id:\"tM3\", numero:\"M3\", logements:[{ id:\"gM3\", nom:\"C\", prix:10, aretes:8, charniere:100, tempsCoupe:10 }] }\n        ] });\n      ok(\"migration 4.41 : le mode global coche tous les outils sauf le premier\",\n         mig.outils.map(o => !!o.simultaneAvecPrecedent), [false, true, true]);\n      ok(\"cycleDetailStatusHTML : nomme le nombre de groupes d'outils simultanes\",\n         /1 groupe d.outils simultan\u00e9s/.test(cycleDetailStatusHTML(mig)), true);\n    }\n\n    /* ---- v4.49.1 : fusion insensible a l'ordre des cl\u00e9s ---- */\n    {\n      const a = { id:\"e1\", titre:\"Essai\", batt: 0.05, prelevements:[{ id:\"p1\", piece: 5 }] };\n      const b = { prelevements:[{ piece: 5, id:\"p1\" }], batt: 0.05, titre:\"Essai\", id:\"e1\" };\n      ok(\"memeContenu canonique : ordre des cl\u00e9s indiff\u00e9rent (v4.49.1)\", true, true);\n      const canon = (() => { const c = (o) => {\n        if(Array.isArray(o)) return o.map(c);\n        if(o && typeof o === \"object\"){ const t = {}; Object.keys(o).sort().forEach(k => t[k] = c(o[k])); return t; }\n        return o; }; return c; })();\n      ok(\"comparaison canonique : objets r\u00e9ordonn\u00e9s = identiques\",\n         JSON.stringify(canon(a)) === JSON.stringify(canon(b)), true);\n    }\n\n    /* ---- v4.53 : livraisons \u2014 instantan\u00e9 fig\u00e9, insensible au recalcul ---- */\n    {\n      const dLignesAvant = lignes;\n      const lCC = normalizeLigne({ id:\"lCC\", nom:\"EMAG 1\", coutHoraire:50,\n        references:[{ id:\"rCC\", nom:\"DV 356x26 RPI\", productionAnnuelle:100000, cibleCPP:0.575,\n          ops:[{ id:\"oCC\", nom:\"OP10 Ebauche\", ordre:10, config:cfg,\n            scenarios:[\n              normalizeScenario({ id:\"sCC1\", name:\"Prod actuelle\", baseline:true, cycle:100, statut:\"serie\",\n                outils:[{ id:\"tCC1\", numero:\"T1\", logements:[{ id:\"gCC1\", nom:\"Piste\", prix:10, aretes:8, charniere:100 }] }], essais:[], scrapLog:[] }),\n              normalizeScenario({ id:\"sCC2\", name:\"Essai optimisant\", baseline:false, cycle:150, statut:\"valide\",\n                outils:[{ id:\"tCC2\", numero:\"T2\", logements:[{ id:\"gCC2\", nom:\"Piste\", prix:5, aretes:8, charniere:150 }] }], essais:[], scrapLog:[] })\n            ] }]\n        }] });\n      const lSauve = lignes;\n      lignes = [lCC];\n      const lv = creerLivraison(\"Test LB\");\n      ok(\"creerLivraison : le plan porte les postes\", lv.plan.length, 1);\n      ok(\"creerLivraison : gains sont des nombres (pas NaN)\", [typeof lv.gainsActes, typeof lv.gainsProjetes], [\"number\", \"number\"]);\n      ok(\"creerLivraison : protocole embarqu\u00e9\", /5/.test(lv.protocole), true);\n      lignes = lSauve;\n    }\n\n    /* ---- v4.79 : A4 Mission \u2014 le clic mort \u00e9crit, et ce qu'il promet ---- */\n    {\n      const lSauve = lignes;\n      const scP = normalizeScenario({ id:\"sM1\", name:\"Prod actuelle\", baseline:true, cycle:100, statut:\"serie\",\n        outils:[{ id:\"tM1\", numero:\"T1\", logements:[{ id:\"gM1\", nom:\"Piste\", prix:10, aretes:8, charniere:100 }] }], essais:[], scrapLog:[] });\n      const scE = normalizeScenario({ id:\"sM2\", name:\"Essai optimisant\", baseline:false, cycle:150, statut:\"valide\",\n        outils:[{ id:\"tM2\", numero:\"T2\", logements:[{ id:\"gM2\", nom:\"Piste\", prix:5, aretes:8, charniere:150 }] }], scrapLog:[] });\n      scE.essais = [ essaiBrut(\"eM1\", [prel(\"pM1\", 10, 0.05)]) ];\n      scE.essais[0].params = { logements: snapshotLogements(scE) };\n      scE.essais[0].date = \"2026-09-28\";\n      const scAr = normalizeScenario({ id:\"sM3\", name:\"Essai arr\u00eat\u00e9\", baseline:false, statut:\"essai\",\n        outils:[{ id:\"tM3\", numero:\"T3\", logements:[{ id:\"gM3\", nom:\"Piste\", prix:7, aretes:8, charniere:120 }] }], scrapLog:[] });\n      scAr.essais = [ essaiBrut(\"eM2\", [prel(\"pM2\", 5, 0.05)]) ];\n      scAr.essais[0].params = { logements: snapshotLogements(scAr) };\n      scAr.essais[0].date = \"2026-09-30\";\n      scAr.essais[0].cloture = { motif: \"casse\", detail: \"\u00e9clat ar\u00eate\", date: \"2026-09-30\" };\n      const lM = normalizeLigne({ id:\"lM\", nom:\"EMAG 1\", coutHoraire:50,\n        references:[{ id:\"rM\", nom:\"DV 356x26 RPI\", productionAnnuelle:100000, cibleCPP:0.575,\n          ops:[{ id:\"oM\", nom:\"OP10 Ebauche\", ordre:10, config:cfg, scenarios:[scP, scE] },\n               { id:\"oM2\", nom:\"OP20 Finition\", ordre:20, config:cfg, scenarios:[scAr] }] }] });\n      lignes = [lM];\n      /* si la fonction manque (clic mort), la suite doit continuer jusqu'au bout\n         et le dire \u2014 pas s'arr\u00eater net (v1.7) : les tests de contenu \u00e9chouent\n         sur du vide, et la promesse \u00e9choue s\u00e9par\u00e9ment */\n      const htmlM = (typeof missionA4HTML === \"function\") ? missionA4HTML() : \"\";\n      ok(\"missionA4HTML : la page se titre Mission \u2014 A4\", /Mission \u2014 A4/.test(htmlM), true);\n      ok(\"missionA4HTML : vivante \u2014 dit qu'elle se recalcule (vs livraison fig\u00e9e)\",\n         /recalcul\u00e9 \u00e0 chaque \u00e9dition/.test(htmlM) && !/fig\u00e9/.test(htmlM), true);\n      ok(\"missionA4HTML : act\u00e9s et en cours en DEUX blocs, jamais somm\u00e9s (\u00a73.4)\",\n         /Gains ACT\u00c9S/.test(htmlM) && /EN COURS \u2014 valid\u00e9s ou en essai/.test(htmlM), true);\n      ok(\"missionA4HTML : le plan porte le poste chiffr\u00e9 et sa r\u00e9f\u00e9rence dominante\",\n         /DV 356x26 RPI/.test(htmlM) && /en cours/.test(htmlM), true);\n      ok(\"missionA4HTML : la timeline \u00e9crit les statuts \u2014 arr\u00eat\u00e9 et en cours\",\n         /arr\u00eat\u00e9/.test(htmlM) && /en cours/.test(htmlM), true);\n      ok(\"missionA4HTML : la timeline range le plus r\u00e9cent d'abord (eM2 du 30/09 avant eM1 du 28/09)\",\n         (() => { const iA = htmlM.indexOf(\"eM2\"), iB = htmlM.indexOf(\"eM1\");\n                  return iA !== -1 && iB !== -1 && iA < iB; })(), true);\n      ok(\"missionA4HTML : la timeline cite le sc\u00e9nario et la ligne de chaque essai\",\n         /Essai optimisant/.test(htmlM) && /EMAG 1/.test(htmlM), true);\n      ok(\"missionA4HTML : le protocole 5\u00d7 est \u00e9crit sur la page\", /r\u00e9p\u00e9t\u00e9 5\u00d7/.test(htmlM), true);\n      ok(\"essaisRecents : les essais sans date passent apr\u00e8s les dat\u00e9s\",\n         essaisRecents(10)[0].date !== \"\", true);\n      lignes = lSauve;\n    }\n\n    /* ---- v4.79 : les promesses de l'interface \u2014 typeof, la r\u00e9ponse du moteur ----\n       Hermes, Tour 50 : \u00ab une boucle sur les gestionnaires de clic, un typeof par\n       fonction appel\u00e9e, un ok() par r\u00e9sultat \u00bb. Le typeof est r\u00e9solu par eval direct\n       DANS la port\u00e9e du script \u2014 exactement l\u00e0 o\u00f9 un gestionnaire r\u00e9soudrait le\n       nom. Une promesse non tenue = un clic mort, exactement comme missionA4HTML\n       l'a \u00e9t\u00e9 de la 4.52 \u00e0 la 4.78. */\n    PROMESSES_UI.forEach(p => p.fns.forEach(f => {\n      let t;\n      try { t = eval(\"typeof \" + f); } catch(e){ t = \"erreur: \" + e.message; }\n      ok(\"promesse UI \u2014 \" + p.porte + \" \u2192 \" + f + \"()\", t, \"function\");\n    }));\n\n    /* ---- v4.48 : compl\u00e9ter depuis la prod \u2014 rapprochement par pr\u00e9fixe ---- */\n    {\n      const dAvant = data;\n      const mk = (nom, base, outils) => normalizeScenario({ id:\"cc-\"+nom, name:nom, baseline:base, cycle: base?100:\"\", outils, essais:[], scrapLog:[] });\n      data = [\n        mk(\"Prod actuelle (base excel 2026/2027)\", true, [\n          { id:\"te1\", numero:\"T548 D1\", logements:[{ id:\"ge1\", nom:\"Plaquette\", prix:9.56, aretes:8, charniere:50 }] },\n          { id:\"te2\", numero:\"T543 D1\", logements:[{ id:\"ge2\", nom:\"Plaquette\", prix:11.87, aretes:6, charniere:30 }] },\n          { id:\"te3\", numero:\"T546 D1\", logements:[{ id:\"ge3\", nom:\"Plaquette\", prix:3.68, aretes:4, charniere:60 }] }\n        ]),\n        mk(\"Essai SL500\", false, [\n          { id:\"tt1\", numero:\"T548\", logements:[{ id:\"gt1\", nom:\"Piste ext.\", prix:9.56, aretes:8, charniere:50 }] }\n        ])\n      ];\n      ok(\"outilsManquants : T548 rapproch\u00e9 par pr\u00e9fixe -> non propos\u00e9 ; T543/T546 manquants\",\n         outilsManquants(data[1]).map(t => t.numero), [\"T543 D1\", \"T546 D1\"]);\n      ok(\"outilsManquants : sur la base elle-m\u00eame -> rien (baseline)\",\n         outilsManquants(data[0]).length, 0);\n      data = dAvant;\n    }\n\n    /* ---- v4.46.1 : cibleCPP de r\u00e9f\u00e9rence persist\u00e9e \u00e0 la normalisation ---- */\n    ok(\"normalizeReference : cibleCPP pr\u00e9serv\u00e9e\",\n       normalizeReference({ id:\"rT2\", nom:\"T\", cibleCPP:0.212, ops:[] }).cibleCPP, 0.212);\n    ok(\"normalizeReference : cibleCPP absente -> cha\u00eene vide\",\n       normalizeReference({ id:\"rT3\", nom:\"T2\", ops:[] }).cibleCPP, \"\");\n\n    /* ---- v4.45 : p\u00e9rim\u00e8tre de comparaison synchronis\u00e9 (fini les deltas mixtes) ---- */\n    {\n      const un = { plaquettes:0.05, machine:null, rebut:null, pieces:null };\n      const deux = { plaquettes:0.075, machine:0.7, rebut:null, pieces:null };\n      const peri = perimetreCompare(deux, un);\n      ok(\"perimetreCompare : la machine chiffrable d'un seul c\u00f4t\u00e9 -> exclue du delta\",\n         peri.exclus, [\"temps machine\"]);\n      ok(\"perimetreCompare : totaux sur le p\u00e9rim\u00e8tre commun (plaquettes)\",\n         [peri.sc, peri.base], [0.075, 0.05]);\n      ok(\"perimetreCompare : tout chiffrable des deux c\u00f4t\u00e9s -> p\u00e9rim\u00e8tre complet\",\n         perimetreCompare({plaquettes:1,machine:0.5,rebut:null,pieces:null},\n                          {plaquettes:2,machine:0.4,rebut:null,pieces:null}).exclus, []);\n      const volAvant = config.volumeActif;\n      config.volumeActif = true;\n      const cfgM = Object.assign({}, cfg, { coutMachineActif:true, cycleRefSec:\"\" });\n      ligne.coutHoraire = 50;\n      const Bmes = normalizeScenario({ id:\"BM\", name:\"BM\", baseline:false,\n        outils:[ { id:\"tBM\", numero:\"TBM\", logements:[ { id:\"gBM\", nom:\"Piste\", prix:10, aretes:8, charniere:200, vc:500, f:0.5, tempsCoupe:50 } ] } ], essais: [] });\n      const ann = bilanAnnuel(Bmes, cfgM, ligne, refT, A);\n      ok(\"bilanAnnuel : gain hors temps machine + rebut (Bmes n'a pas de journal) quand la r\u00e9f\u00e9rence n'est pas chiffrable\",\n         [ann.perimetrePartiel, Math.round(ann.gainAnnuel)], [[\"temps machine\", \"co\u00fbt du rebut\"], 4375]);\n      config.volumeActif = volAvant;\n    }\n\n    /* ---- v4.42 : botte secrete K \u2014 sortie conditionnee, impression jamais ---- */\n    A.outils[0].logements[0].kappaR = 85; // le widget n'existe que si un \u03bar est saisi\n    ok(\"kvfWidgetHTML : sans autorisation, aucun K en sortie\",\n       kvfWidgetHTML(A, false).includes(\"\u2014 K\"), false);\n    ok(\"kvfWidgetHTML : avec autorisation, le K apparait\",\n       kvfWidgetHTML(A, true).includes(\"\u2014 K\"), true);\n    ok(\"kvfWidgetHTML : Fr/Fa reste quelle que soit l'autorisation\",\n       [kvfWidgetHTML(A, false).includes(\"Fr/Fa\"), kvfWidgetHTML(A, true).includes(\"Fr/Fa\")],\n       [config.forceRatioActif, config.forceRatioActif]);\n\n    ok(\"normalizeScenario : plan conserve a travers l'arbre\",\n       normalizeScenario({ id:\"sp2\", name:\"p\", outils:[{ id:\"t9\", numero:\"T9\", plan:planTest, logements:[] }] }).outils[0].plan, planTest);\n\n    /* ---- uid() : pas de collision d'identifiants (v4.4.1) --------------------------\n       Date.now() seul produisait le meme id pour deux objets crees dans la meme\n       milliseconde (double-clic, import) : la collision ecrasait des donnees en silence. */\n    {\n      const ids = Array.from({ length: 200 }, () => uid(\"s\"));\n      ok(\"uid : 200 identifiants generes dans la meme milliseconde sont uniques\",\n         new Set(ids).size, 200);\n      ok(\"uid : le prefixe est respecte\", /^s[a-z0-9]+$/.test(ids[0]), true);\n    }\n\n    /* ---- pourcentageTolerance : la vue % des tendances (v4.15) --------------------- */\n    ok(\"pctTol : borne maxi seule -> y/limite\", pourcentageTolerance(0.05, 0.1), 50, 1e-9);\n    ok(\"pctTol : plage min-max -> (y-min)/(max-min)\",\n       pourcentageTolerance(1.0, 1.6, 0.8), 25, 1e-9);\n    ok(\"pctTol : hors tolerance -> au-dela de 100\", pourcentageTolerance(0.12, 0.1), 120, 1e-9);\n    ok(\"pctTol : pas de limite exploitable -> null\", pourcentageTolerance(0.05, NaN), null);\n\n    /* ---- v4.55.0 \u2014 le classeur Matis : la mesure de l'\u00e9cart r\u00e9el / th\u00e9orique ----\n       Le classeur de Matis donne la production R\u00c9ELLE par couple ligne \u00d7 r\u00e9f\u00e9rence\n       et le CPP r\u00e9ellement consomm\u00e9. L'outil, lui, budg\u00e8te un CPP. L'\u00e9cart entre\n       les deux mesure la sant\u00e9 du plan outillage \u2014 c'est tout ce que cet \u00e9cran\n       fait, et c'est d\u00e9j\u00e0 beaucoup. */\n    {\n      /* --- la fonction pure : matisRecap, test\u00e9e sans fichier --- */\n      const f = (nom, codeLigne, ref, prod, outils) => ({ codeLigne, ref, refComplete: ref, production: prod, outils });\n      const o = (theo, reel, qte) => ({ cppTheorique: theo, cppReel: reel, qteReelle: qte, numero: \"T\", opCode: \"OP10\" });\n      const feuilles = [\n        f(\"f1\", \"E1\", \"356x26 RPI\", 6781, [ o(0.0158, 0.0280, 5), o(0.0233, 0.0010, 1), o(0.0079, 0.0224, 4) ]),\n        f(\"f2\", \"E2\", \"290x12\", 2234, [ o(0.2235, 0.3045, 12) ]),\n        /* un poste non produit : production nulle, il ne doit rien compter */\n        f(\"f3\", \"E3\", \"330x14\", 0, [ o(0.3154, null, null) ])\n      ];\n      const recap = matisRecap(feuilles);\n      ok(\"matis : un couple ligne \u00d7 r\u00e9f\u00e9rence = une ligne du r\u00e9capitulatif\", recap.length, 3);\n\n      const e1 = recap.find(c => c.ref.includes(\"356x26\"));\n      ok(\"matis : la production r\u00e9elle est lue du classeur (B1)\", e1.production, 6781);\n      ok(\"matis : le CPP th\u00e9orique est la somme des outils\", e1.cppTheorique, 0.0158 + 0.0233 + 0.0079, 1e-9);\n      ok(\"matis : le CPP r\u00e9el est la somme des consommations\", e1.cppReel, 0.0280 + 0.0010 + 0.0224, 1e-9);\n      ok(\"matis : l'\u00e9cart = r\u00e9el \u2212 th\u00e9orique (positif = surconsommation)\",\n         [e1.ecart > 0, e1.ecart], [true, (0.0280 + 0.0010 + 0.0224) - (0.0158 + 0.0233 + 0.0079)]);\n      ok(\"matis : l'\u00e9cart annuel = CPP r\u00e9el \u00d7 production r\u00e9elle\",\n         e1.gapAnnuel, e1.ecart * 6781, 1e-6);\n\n      /* un poste non produit ne compte dans aucun total \u2014 et le \u00ab non mesurable \u00bb reste\n         null, jamais 0 : 0 dirait \u00ab rien \u00e0 consommer \u00bb, null dit \u00ab pas de mesure \u00bb. */\n      const e3 = recap.find(c => c.ref.includes(\"330x14\"));\n      ok(\"matis : un couple sans production n'a ni co\u00fbt annuel r\u00e9el ni \u00e9cart (null, pas 0)\",\n         [e3.aProduction, e3.coutAnnuelReel, e3.coutAnnuelTheorique, e3.gapAnnuel], [false, null, null, null]);\n\n      /* le libell\u00e9 d'\u00e9cart : toujours une raison, jamais un chiffre nu (constitution \u00a73.5) */\n      ok(\"matis : un \u00e9cart positif se lit comme une surconsommation, avec son montant\",\n         libelleEcartMatis(e1).includes(\"surconsommation\") && libelleEcartMatis(e1).includes(\"\u20ac/pi\u00e8ce\"), true);\n      ok(\"matis : un couple non mesur\u00e9 le dit, plut\u00f4t que d'afficher un \u00e9cart faux\",\n         libelleEcartMatis(e3).includes(\"non mesurable\"), true);\n      ok(\"matis : le r\u00e9capitulatif est tri\u00e9 par production d\u00e9croissante\",\n         recap[0].production >= recap[1].production, true);\n\n      /* la lecture est un CONSTAT : elle n'\u00e9crit rien dans le suivi */\n      ok(\"matis : la lecture ne touche ni les lignes ni les projets\",\n         [typeof matisRecap, lignes.length, projets.length] , [\"function\", lignes.length, projets.length]);\n    }\n\n    /* ---- v4.56.0 \u2014 le rapprochement classeur <-> suivi, dit en toutes lettres ----\n       Le classeur parle \u00ab E1 \u00b7 356x26 \u00bb, l'outil d\u00e9clare \u00ab EMAG 1 \u00bb et ses r\u00e9f\u00e9rences.\n       Jusqu'ici le rapprochement \u00e9tait calcul\u00e9 mais muet : seul survivait l'avertissement\n       \u00ab ligne hors suivi \u00bb. D\u00e9sormais chaque couple se voit dire s'il existe des deux\n       c\u00f4t\u00e9s, et si la production raconte la m\u00eame chose des deux \u2014 le cas \u00ab l'excel dit\n       50, le terrain dit 30 \u00bb doit sauter aux yeux \u00e0 la lecture, pas se d\u00e9couvrir des\n       mois plus tard. Toujours un constat : le libell\u00e9 n'\u00e9crit rien. */\n    {\n      const lE1 = normalizeLigne({ id:\"l-e1\", nom:\"EMAG 1\" });\n      lE1.references.push(normalizeReference({ id:\"r-356\", nom:\"356x26 RPI\", productionAnnuelle:6781,\n        ops:[{ id:\"o-356\", nom:\"OP10\", scenarios:[{ id:\"sc-356\", name:\"R\u00e9f\", baseline:true, outils:[] }] }] }));\n      lE1.references.push(normalizeReference({ id:\"r-290\", nom:\"290x12\",\n        ops:[{ id:\"o-290\", nom:\"OP10\", scenarios:[{ id:\"sc-290\", name:\"R\u00e9f\", baseline:true, outils:[] }] }] }));\n      const lignesB = lignes, lectureB = matisLecture;\n      lignes = [lE1];\n      try {\n        const cOk = { codeLigne:\"E1\", ref:\"356x26 RPI\", production:6781, aProduction:true };\n        const rOk = matisRapproche(cOk);\n        ok(\"matis : le rapprochement rend d\u00e9sormais la r\u00e9f\u00e9rence trouv\u00e9e, pas seulement son id\",\n           [rOk.ligneId, rOk.ref && rOk.ref.nom], [\"l-e1\", \"356x26 RPI\"]);\n\n        ok(\"matis : production identique des deux c\u00f4t\u00e9s -> conforme, chiffr\u00e9e en toutes lettres\",\n           [libelleRapprochementMatis(cOk, rOk).attention,\n            libelleRapprochementMatis(cOk, rOk).texte.includes(\"production conforme\"),\n            libelleRapprochementMatis(cOk, rOk).texte.includes(fmt(6781, 0))],\n           [false, true, true]);\n\n        /* le cas qui justifie l'\u00e9cran : l'excel dit 50, le terrain dit 6 781. Les deux\n           chiffres sont cit\u00e9s \u2014 jamais un \u00ab divergence \u00bb nu sans ses nombres. */\n        const cDiv = { codeLigne:\"E1\", ref:\"356x26 RPI\", production:50, aProduction:true };\n        const rDiv = libelleRapprochementMatis(cDiv, rOk);\n        ok(\"matis : production en divergence -> ambre, les deux chiffres cit\u00e9s\",\n           [rDiv.attention, rDiv.texte.includes(\"divergence\"),\n            rDiv.texte.includes(fmt(50, 0)), rDiv.texte.includes(fmt(6781, 0))],\n           [true, true, true, true]);\n\n        ok(\"matis : la ligne n'est pas d\u00e9clar\u00e9e -> \u00ab hors suivi \u00bb, dit avec son nom\",\n           libelleRapprochementMatis({ codeLigne:\"W9\", ref:\"123x45\", production:10, aProduction:true },\n                                     matisRapproche({ codeLigne:\"W9\", ref:\"123x45\" })),\n           { texte: \"hors suivi \u2014 la ligne W9 n'est pas d\u00e9clar\u00e9e dans l'outil\", attention: true });\n\n        ok(\"matis : la ligne existe mais pas la r\u00e9f\u00e9rence -> dit les deux\",\n           libelleRapprochementMatis({ codeLigne:\"E1\", ref:\"999x11\" }, matisRapproche({ codeLigne:\"E1\", ref:\"999x11\" })),\n           { texte: \"la r\u00e9f\u00e9rence 999x11 n'est pas d\u00e9clar\u00e9e sur la ligne EMAG 1\", attention: true });\n\n        ok(\"matis : pas de production relev\u00e9e dans le classeur -> dit, sans inventer de comparaison\",\n           libelleRapprochementMatis({ codeLigne:\"E1\", ref:\"356x26 RPI\", production:0, aProduction:false }, rOk),\n           { texte: \"dans le suivi : EMAG 1 \u00b7 356x26 RPI \u2014 pas de production relev\u00e9e dans le classeur\", attention: false });\n\n        ok(\"matis : pas de production annuelle d\u00e9clar\u00e9e dans l'outil -> dit, sans inventer de comparaison\",\n           libelleRapprochementMatis({ codeLigne:\"E1\", ref:\"290x12\", production:2234, aProduction:true },\n                                     matisRapproche({ codeLigne:\"E1\", ref:\"290x12\" })).texte.includes(\"pas de production annuelle d\u00e9clar\u00e9e dans l'outil\"),\n           true);\n\n        /* le RENDU : la phrase vit sous le nom du couple, et l'ancien avertissement\n           redondant de la colonne Lecture a disparu (le\u00e7on 4.51.2 : verrouiller le rendu) */\n        matisLecture = { fichier:\"classeur-test.xlsx\", luLe:\"2026-09-30\", feuilles:[],\n          couples:[ cOk, { codeLigne:\"W9\", ref:\"123x45\", production:10, aProduction:true,\n                           cppTheorique:0, cppReel:0, ecart:null } ] };\n        const htmlMatis = matisVueHTML();\n        ok(\"matis : le rendu affiche le rapprochement sous le couple, conforme en clair\",\n           [htmlMatis.includes(\"mt-rap\"), htmlMatis.includes(\"production conforme\")], [true, true]);\n        ok(\"matis : le rendu passe en ambre sur la divergence et l'ancien avertissement redondant a disparu\",\n           [htmlMatis.includes(\"mt-rap-attention\"), htmlMatis.includes(\"(ligne hors suivi :\")], [true, false]);\n      } finally { lignes = lignesB; matisLecture = lectureB; }\n    }\n\n    /* ---- v4.58.0 \u2014 le MABEC raccord\u00e9 au logement, et le rapprochement par article ----\n       D\u00e9cision Q4 de Benjamin : le MABEC vit sur le logement, dans le champ code article\n       existant (raccord\u00e9, pas doubl\u00e9 : D3). Et un m\u00eame MABEC peut servir sur plusieurs\n       porte-outils \u2014 c'est la r\u00e9utilisation normale d'une m\u00eame plaquette, donc le\n       rapprochement se fait par MABEC + contexte porte-outil, JAMAIS par MABEC seul. */\n    {\n      ok(\"matis : \u00ab T517 D2 \u00bb = porte-outil T517, position D2 (le vocabulaire du classeur)\",\n         matisPorteOutilPosition(\"T517 D2\"), { porte: \"T517\", position: \"D2\" });\n      ok(\"matis : \u00ab T533 \u00bb sans suffixe = porte-outil seul, position inconnue\",\n         matisPorteOutilPosition(\"T533\"), { porte: \"T533\", position: null });\n\n      const lE1b = normalizeLigne({ id:\"l-e1b\", nom:\"EMAG 1\" });\n      const scB = normalizeScenario({ id:\"sc-b\", name:\"Prod\", baseline:true, outils:[\n        { id:\"t-b1\", numero:\"T517\", logements:[\n          { id:\"g-b1\", nom:\"D1\", codeArticle:\"IM02 198 054\", prix:20, aretes:4, charniere:100 },\n          { id:\"g-b2\", nom:\"D2\", codeArticle:\"IM02 209 560\", prix:23, aretes:4, charniere:100 } ] },\n        { id:\"t-b2\", numero:\"T519\", logements:[\n          { id:\"g-b3\", nom:\"D2\", codeArticle:\"IM02 209 560\", prix:23, aretes:4, charniere:100 } ] } ] });\n      lE1b.references.push(normalizeReference({ id:\"r-b\", nom:\"356x26 RPI\", ops:[\n        { id:\"o-b\", nom:\"OP10\", scenarios:[ scB ] } ] }));\n      const lignesC = lignes, lectureC = matisLecture;\n      lignes = [lE1b];\n      try {\n        /* le match : le MABEC suivi sur le porte-outil lu du classeur, avec l'OP */\n        ok(\"matis : MABEC suivi sur le bon porte-outil -> \u00ab suivi : T517 \u00b7 D1 (OP10) \u00bb\",\n           matisRapprocheMabec({ numero:\"T517 D1\", mabec:\"IM02 198 054\" }, lE1b),\n           { statut: \"match\", texte: \"suivi : T517 \u00b7 D1 (OP10)\" });\n\n        /* la r\u00e9utilisation normale : m\u00eame plaquette, autre porte-outil (pr\u00e9cision Benjamin) */\n        ok(\"matis : m\u00eame MABEC sur un autre porte-outil -> r\u00e9utilisation dite comme telle, pas une erreur\",\n           matisRapprocheMabec({ numero:\"T533\", mabec:\"IM02 209 560\" }, lE1b).statut, \"ailleurs\");\n\n        /* la saisie plate \u00ab T517 D1 \u00bb en num\u00e9ro d'outil reste rattrap\u00e9e par le contexte */\n        const lPlat = normalizeLigne({ id:\"l-plat\", nom:\"EMAG 1\" });\n        const scP = normalizeScenario({ id:\"sc-p\", name:\"Prod\", baseline:true, outils:[\n          { id:\"t-p1\", numero:\"T517 D1\", logements:[\n            { id:\"g-p1\", nom:\"Plaquette\", codeArticle:\"im02 198 054\", prix:20, aretes:4, charniere:100 } ] } ] });\n        lPlat.references.push(normalizeReference({ id:\"r-p\", nom:\"356x26 RPI\", ops:[\n          { id:\"o-p\", nom:\"OP10\", scenarios:[ scP ] } ] }));\n        ok(\"matis : la saisie plate \u00ab T517 D1 \u00bb en n\u00b0 d'outil et le MABEC en casse libre restent rattrap\u00e9s\",\n           matisRapprocheMabec({ numero:\"T517 D1\", mabec:\"IM02 198 054\" }, lPlat).statut, \"match\");\n\n        /* l'absence : l'invitation, jamais un blanc muet */\n        ok(\"matis : MABEC inconnu du suivi -> \u00ab pas encore saisi \u00bb, l'invitation\",\n           matisRapprocheMabec({ numero:\"T546 D1\", mabec:\"IM02 000 000\" }, lE1b),\n           { statut: \"absent\", texte: \"pas encore saisi dans le suivi\" });\n\n        /* ligne du classeur sans MABEC : rien \u00e0 rapprocher, dit \u00ab \u2014 \u00bb */\n        ok(\"matis : ligne du classeur sans MABEC -> rien \u00e0 rapprocher\",\n           matisRapprocheMabec({ numero:\"T549 D1\", mabec:\"\" }, lE1b), { statut: \"sans\", texte: \"\u2014\" });\n\n        /* le RENDU : la colonne vit dans le d\u00e9tail par outil, l'invitation en ambre (le\u00e7on 4.51.2) */\n        matisLecture = { fichier:\"t.xlsx\", luLe:\"2026-09-30\", feuilles:[], couples:[\n          { key:\"E1\u00b7356x26 RPI\", codeLigne:\"E1\", ref:\"356x26 RPI\", production:6781, aProduction:true,\n            cppTheorique:0.04, cppReel:0.05, ecart:0.01, outils:[\n              { numero:\"T517 D1\", opCode:\"OP10\", article:\"SNGX\", mabec:\"IM02 198 054\", cppTheorique:0.02, cppReel:0.02, qteReelle:3 },\n              { numero:\"T546 D1\", opCode:\"OP20\", article:\"\u2014\", mabec:\"IM02 000 000\", cppTheorique:0.01, cppReel:0.01, qteReelle:1 } ] } ] };\n        const htmlDet = matisDetailHTML();\n        ok(\"matis : le d\u00e9tail par outil porte la colonne \u00ab Dans le suivi \u00bb et la phrase de rapprochement\",\n           [htmlDet.includes(\"Dans le suivi\"), htmlDet.includes(\"suivi : T517 \u00b7 D1 (OP10)\")], [true, true]);\n        ok(\"matis : \u00ab pas encore saisi \u00bb reste dit, en gris (4.58.1 \u2014 plus d'ambre), et le compteur d'en-t\u00eate agr\u00e8ge l'invitation\",\n           [htmlDet.includes(\"mt-suivi-absent\"), htmlDet.includes(\"pas encore saisi\"),\n            htmlDet.includes(\"Rapprochement :\"), htmlDet.includes(\"\u00e0 saisir\")], [true, true, true, true]);\n      } finally { lignes = lignesC; matisLecture = lectureC; }\n    }\n\n    /* ---- v4.59.0 \u2014 gainLigne (le rollup par ligne, Q6-B) + pieceCPPComplet \u00e9tendu (Q7) ----\n       La tuile-ligne de l'\u00e9cran d'accueil lira TOUT ici sans recalculer. D3 au niveau\n       au-dessus : ce rollup consomme gainPoste/etatTuile/prochaineEtapePoste/pieceCPPComplet\n       et n'invente aucun second agr\u00e9gat. L'\u00e9tat-ligne n'est PAS d\u00e9cid\u00e9 dans la fonction \u2014\n       les comptages sont factuels, la pastille se choisira au tour UI, devant Benjamin. */\n    {\n      const opCfg = (extra) => Object.assign({}, defaultConfig, { volumeActif: true }, extra || {});\n      const LS2 = [ { nom: \"EMAG 1\", machines: [\n        { code: \"OP10\", nom: \"\u00c9bauche\" }, { code: \"OP20\", nom: \"Per\u00e7ages\" },\n        { code: \"OP30\", nom: \"Finition\" }, { code: \"OP40\", nom: \"Fraisurage\" } ] } ];\n      const refG = normalizeReference({ id: \"rG\", nom: \"356x26\", productionAnnuelle: \"100000\", cibleCPP: \"0.300\", ops: [\n        { id: \"oG10\", nom: \"OP10 Ebauche\", config: opCfg(), scenarios: [\n          { id: \"pG10\", name: \"Prod\", baseline: true, outils: [ { id: \"uG1\", numero: \"T1\", logements: [ { id: \"lG1\", nom: \"Bol\", prix: 30, aretes: 8, charniere: 100 } ] } ] },\n          { id: \"eG10\", name: \"Essai SL500\", statut: \"serie\", outils: [ { id: \"uG2\", numero: \"T2\", logements: [ { id: \"lG2\", nom: \"Bol\", prix: 10, aretes: 8, charniere: 100 } ] } ] } ] },\n        { id: \"oG20\", nom: \"OP20 Per\u00e7ages\", config: opCfg(), scenarios: [\n          { id: \"pG20\", name: \"Prod\", baseline: true, outils: [ { id: \"uG3\", numero: \"T3\", logements: [ { id: \"lG3\", nom: \"Bol\", prix: \"\", aretes: 8, charniere: \"\" } ] } ] } ] },\n        { id: \"oG30\", nom: \"OP30\", config: opCfg(), scenarios: [] } ] });\n      const refP = normalizeReference({ id: \"rP\", nom: \"304x28\", productionAnnuelle: \"50000\", cibleCPP: \"\", ops: [\n        { id: \"oP10\", nom: \"OP10\", config: opCfg(), scenarios: [\n          { id: \"pP10\", name: \"Prod\", baseline: true, outils: [ { id: \"uP1\", numero: \"T1\", logements: [ { id: \"lP1\", nom: \"Bol\", prix: 40, aretes: 8, charniere: 100 } ] } ] } ] } ] });\n      const lG = normalizeLigne({ id: \"lG\", nom: \"EMAG 1\", coutHoraire: \"\", references: [ refG, refP ] });\n\n      /* l'extension Q7 : lecture explicite, la ligne passe au co\u00fbt machine */\n      const cp = pieceCPPComplet(refG, lG);\n      ok(\"gainLigne : pieceCPPComplet(ref, ligne) lit LA r\u00e9f\u00e9rence demand\u00e9e, cible comprise\",\n         [cp && cp.ref.id, cp && cp.cible, cp && cp.prod], [\"rG\", 0.3, 0.0375]);\n      ok(\"gainLigne : les OP non chiffrables restent list\u00e9es \u2014 l'\u00e9cart se voit, il ne dispara\u00eet pas\",\n         [cp.nonChiffrees.length, cp.nonChiffrees.map(o => o.op.nom)],\n         [2, [\"OP20 Per\u00e7ages\", \"OP30\"]]);\n      /* le comportement sans argument se teste en posant l'\u00e9tat actif soi-m\u00eame :\n         le harnais ne garantit PAS ce que les blocs pr\u00e9c\u00e9dents ont laiss\u00e9 dans les\n         actifs \u2014 un test qui d\u00e9pend de cet h\u00e9ritage est un test fragile */\n      const lAv = lignes, alAv = activeLigneId, arAv = activeReferenceId;\n      lignes = [lG]; activeLigneId = \"lG\"; activeReferenceId = \"rG\";\n      const cpSans = pieceCPPComplet();\n      lignes = lAv; activeLigneId = alAv; activeReferenceId = arAv;\n      ok(\"gainLigne : sans arguments, pieceCPPComplet retombe sur le couple ligne \u00d7 r\u00e9f\u00e9rence actif (inchang\u00e9)\",\n         cpSans && cpSans.ref.id, \"rG\");\n\n      /* le rollup */\n      const gl = gainLigne(lG, LS2);\n      ok(\"gainLigne : quatre machines d\u00e9clar\u00e9es = quatre postes, m\u00eame jamais travaill\u00e9es\",\n         gl.postes.map(t => t.poste.opCode), [\"OP10\", \"OP20\", \"OP30\", \"OP40\"]);\n      ok(\"gainLigne : les \u00e9tats se comptent \u2014 1 gagn\u00e9, 2 \u00e0 chiffrer (cible pos\u00e9e), 1 opportunit\u00e9 (OP40 jamais servie)\",\n         gl.etats, { gagne: 1, encours: 0, aChiffrer: 2, opportunite: 1 });\n      ok(\"gainLigne : le gain act\u00e9 du poste remonte tel quel (2 500 \u20ac/an, p\u00e9rim\u00e8tre commun)\",\n         gl.gainActe, 2500, 1e-6);\n      ok(\"gainLigne : la dominante est le plus gros volume (356x26), pas la premi\u00e8re saisie\",\n         gl.refDominante.nom, \"356x26\");\n      ok(\"gainLigne : le co\u00fbt pi\u00e8ce est \u00c9TIQUET\u00c9 dominante (Q6-B) \u2014 jamais un co\u00fbt multi-r\u00e9fs nu\",\n         [gl.coutPiece.ref.nom, gl.coutPiece.prod, gl.coutPiece.enCours], [\"356x26\", 0.0375, 0.0125]);\n      ok(\"gainLigne : chaque poste porte sa prochaine \u00e9tape en toutes lettres (4.54) \u2014 rien \u00e0 inventer pour la tuile\",\n         [gl.etapes.length, gl.etapes.map(e => e.texte).some(t => String(t).includes(\"maintenir\"))],\n         [4, true]);\n      /* une ligne jamais travaill\u00e9e : des postes, aucun gain, AUCUN co\u00fbt \u2014 pas un 0 mensonger */\n      const lVide = normalizeLigne({ id: \"lV\", nom: \"Weisser 1\", references: [] });\n      const glVide = gainLigne(lVide, [ { nom: \"Weisser 1\", machines: [ { code: \"OP10\", nom: \"\" } ] } ]);\n      ok(\"gainLigne : une ligne d\u00e9clar\u00e9e jamais travaill\u00e9e = opportunit\u00e9, co\u00fbt null (pas 0), aucune \u00e9tape calcul\u00e9e en vain\",\n         [glVide.etats.opportunite, glVide.gainActe, glVide.coutPiece], [1, 0, null]);\n    }\n\n    /* ---- v4.60.0 \u2014 l'\u00e9cran d'accueil : la carte en tuiles de LIGNES --------------\n       La tuile lit tout dans gainLigne() : elle ne recalcule rien (D3). La pastille\n       se d\u00e9duit des comptages, PRIORIT\u00c9 \u00c0 L'ATTENTION : \u00e0 chiffrer > en cours >\n       gagn\u00e9 > jamais travaill\u00e9 \u2014 coh\u00e9rent avec prochaineEtapePoste(). Le co\u00fbt est\n       \u00e9tiquet\u00e9 dominante (Q6-B) ; sans volume, l'absence est DITE (Q10) \u2014 le pi\u00e8ge\n       du choix arbitraire silencieux signal\u00e9 par Hermes au Tour 13. */\n    {\n      const opCfg = (extra) => Object.assign({}, defaultConfig, { volumeActif: true }, extra || {});\n      const LS3 = [ { nom: \"EMAG 1\", machines: [ { code: \"OP10\", nom: \"\u00c9bauche\" }, { code: \"OP20\", nom: \"Per\u00e7ages\" } ] } ];\n      const refM = normalizeReference({ id: \"rM\", nom: \"356x26\", productionAnnuelle: \"100000\", cibleCPP: \"0.300\", ops: [\n        { id: \"oM10\", nom: \"OP10\", config: opCfg(), scenarios: [\n          { id: \"pM10\", name: \"Prod\", baseline: true, outils: [ { id: \"uM1\", numero: \"T1\", logements: [ { id: \"lM1\", nom: \"Bol\", prix: 30, aretes: 8, charniere: 100 } ] } ] },\n          { id: \"eM10\", name: \"Essai SL500\", statut: \"serie\", outils: [ { id: \"uM2\", numero: \"T2\", logements: [ { id: \"lM2\", nom: \"Bol\", prix: 10, aretes: 8, charniere: 100 } ] } ] } ] },\n        { id: \"oM20\", nom: \"OP20 Per\u00e7ages\", config: opCfg(), scenarios: [\n          { id: \"pM20\", name: \"Prod\", baseline: true, outils: [ { id: \"uM3\", numero: \"T3\", logements: [ { id: \"lM3\", nom: \"Bol\", prix: \"\", aretes: 8, charniere: \"\" } ] } ] } ] } ] });\n      const refN = normalizeReference({ id: \"rN\", nom: \"304x28\", productionAnnuelle: \"50000\", cibleCPP: \"\", ops: [\n        { id: \"oN10\", nom: \"OP10\", config: opCfg(), scenarios: [\n          { id: \"pN10\", name: \"Prod\", baseline: true, outils: [ { id: \"uN1\", numero: \"T1\", logements: [ { id: \"lN1\", nom: \"Bol\", prix: 40, aretes: 8, charniere: 100 } ] } ] },\n          { id: \"eN10\", name: \"Essai SL506\", outils: [ { id: \"uN2\", numero: \"T2\", logements: [ { id: \"lN2\", nom: \"Bol\", prix: 35, aretes: 8, charniere: 100 } ] } ] } ] } ] });\n      const lM = normalizeLigne({ id: \"lM\", nom: \"EMAG 1\", coutHoraire: \"\", references: [ refM, refN ] });\n\n      /* la pastille : priorit\u00e9 \u00e0 l'attention */\n      const glM = gainLigne(lM, LS3);\n      ok(\"accueil : la pastille priorise l'attention \u2014 un poste \u00e0 chiffrer passe avant le poste gagn\u00e9\",\n         [etatLigne(glM).etat, etatLigne(glM).label], [\"aChiffrer\", \"1 poste \u00e0 chiffrer\"]);\n      ok(\"accueil : sans aChiffrer, la ligne en travail est \u00ab Essais en cours \u00bb\",\n         etatLigne({ etats: { gagne: 1, encours: 2, aChiffrer: 0, opportunite: 0 } }).etat, \"encours\");\n      ok(\"accueil : tout gagn\u00e9, plus rien en attente = \u00ab en production \u00bb\",\n         etatLigne({ etats: { gagne: 3, encours: 0, aChiffrer: 0, opportunite: 0 } }).label, \"3 postes gagn\u00e9s \u2014 en production\");\n      ok(\"accueil : rien que des postes ouverts = la ligne attend\",\n         etatLigne({ etats: { gagne: 0, encours: 0, aChiffrer: 0, opportunite: 4 }, postes: [1,2,3,4] }).etat, \"opportunite\");\n      ok(\"accueil : une ligne d\u00e9clar\u00e9e sans machines dit \u00ab machines \u00e0 d\u00e9clarer \u00bb, pas \u00ab 0 poste ouvert \u00bb\",\n         etatLigne({ etats: { gagne: 0, encours: 0, aChiffrer: 0, opportunite: 0 }, postes: [] }).label, \"machines \u00e0 d\u00e9clarer\");\n\n      /* le volume de la dominante est rendu par gainLigne (D3 : la tuile ne recalcule pas) */\n      ok(\"accueil : gainLigne rend le volume de la dominante\",\n         glM.volumeDominante, 100000);\n\n      /* le rendu de la tuile : tout y est, \u00e9tiquet\u00e9 */\n      const hM = accueilTuileHTML(glM);\n      ok(\"accueil : la tuile porte le badge MOT + classe (jamais la couleur seule)\",\n         [hM.includes(\"ca-tuile achiffrer\"), hM.includes(\"1 poste \u00e0 chiffrer\")], [true, true]);\n      ok(\"accueil : le co\u00fbt est \u00e9tiquet\u00e9 dominante (Q6-B) avec son +n r\u00e9f.\",\n         [hM.includes(\"356x26 :\"), hM.includes(\"\u20ac/pce\"), hM.includes(\"+1 r\u00e9f.\")], [true, true, true]);\n      ok(\"accueil : les gains act\u00e9 et en cours vivent dans deux blocs \u00e9tiquet\u00e9s (\u00a73.4)\",\n         [hM.includes(\"/an act\u00e9\"), hM.includes(\"/an en cours\")], [true, true]);\n      ok(\"accueil : le \u00e0-faire cite l'OP et l'\u00e9tape d\u00e9duite (4.54)\",\n         [hM.includes(\"\u00c0 faire\"), hM.includes(\"OP20\")], [true, true]);\n\n      /* Q10 : pas de volume = l'absence DITE, jamais un co\u00fbt silencieux */\n      const refV = normalizeReference({ id: \"rV\", nom: \"290x12\", productionAnnuelle: \"\", cibleCPP: \"\", ops: [\n        { id: \"oV10\", nom: \"OP10\", config: opCfg(), scenarios: [\n          { id: \"pV10\", name: \"Prod\", baseline: true, outils: [ { id: \"uV1\", numero: \"T1\", logements: [ { id: \"lV1\", nom: \"Bol\", prix: 25, aretes: 8, charniere: 100 } ] } ] } ] } ] });\n      const lV2 = normalizeLigne({ id: \"lV2\", nom: \"EMAG 1\", coutHoraire: \"\", references: [ refV ] });\n      const glV2 = gainLigne(lV2, LS3);\n      const hV2 = accueilTuileHTML(glV2);\n      ok(\"accueil : sans volume annuel (Q10), la tuile dit \u00ab volume annuel \u00e0 saisir \u00bb et ne montre AUCUN co\u00fbt\",\n         [glV2.volumeDominante, hV2.includes(\"volume annuel \u00e0 saisir\"), hV2.includes(\"\u20ac/pce\")],\n         [null, true, false]);\n\n      /* l'opportunit\u00e9 pure : aucune chiffre, l'invitation */\n      const lO = normalizeLigne({ id: \"lO\", nom: \"EMAG 1\", references: [] });\n      const glO = gainLigne(lO, LS3);\n      const hO = accueilTuileHTML(glO);\n      ok(\"accueil : une ligne jamais travaill\u00e9e ne montre aucun chiffre \u2014 son invitation seulement\",\n         [hO.includes(\"d\u00e9clar\u00e9e, jamais travaill\u00e9e\"), hO.includes(\"/an\"), hO.includes(\"\u20ac/pce\")], [true, false, false]);\n      /* pour \u00ab machines \u00e0 d\u00e9clarer \u00bb il faut une ligne NON d\u00e9clar\u00e9e dans l'usine\n         (pas seulement vide de donn\u00e9es) : LS3 ne conna\u00eet pas \u00ab Weisser 9 \u00bb */\n      const lO9 = normalizeLigne({ id: \"lO9\", nom: \"Weisser 9\", references: [] });\n      const hO9 = accueilTuileHTML(gainLigne(lO9, LS3));\n      ok(\"accueil : une ligne sans r\u00e9f\u00e9rences ni machines ne dit PAS \u00ab volume annuel \u00e0 saisir \u00bb \u2014 la pastille \u00ab machines \u00e0 d\u00e9clarer \u00bb suffit, pas de double invitation (4.60.1)\",\n         [hO9.includes(\"volume annuel \u00e0 saisir\"), hO9.includes(\"machines \u00e0 d\u00e9clarer\")], [false, true]);\n\n      /* 4.60.1 \u2014 un co\u00fbt PARTIEL se d\u00e9clare (\u00a73.2) : EMAG 1 r\u00e9el affichait 0,763 \u20ac/pce\n         sans dire que des OP n'\u00e9taient pas chiffr\u00e9es. Ici refM a UNE op non chiffrable. */\n      ok(\"accueil : un co\u00fbt partiel dit \u00ab hors n op\u00e9ration non chiffr\u00e9e \u00bb, il ne passe pas pour complet\",\n         [hM.includes(\"hors 1 op\u00e9ration non chiffr\u00e9e\")], [true]);\n\n      /* la recette A2 : l'\u00e9cran dit s'il sert. Depuis la 4.61, une ligne SANS\n         r\u00e9f\u00e9rences vit dans la tuile hors p\u00e9rim\u00e8tre \u2014 le \u00ab creux \u00bb se teste\n         avec une ligne VIVANTE mais non actionnable (des r\u00e9f\u00e9rences, aucune\n         cible, aucun essai). */\n      const lignesA = lignes;\n      try {\n        const refCreuse = normalizeReference({ id: \"rc\", nom: \"290x12\", productionAnnuelle: \"10000\", cibleCPP: \"\", ops: [\n          { id: \"oc\", nom: \"OP10\", config: opCfg(), scenarios: [\n            { id: \"pc\", name: \"Prod\", baseline: true, outils: [ { id: \"uc\", numero: \"T\", logements: [ { id: \"lc\", nom: \"Bol\", prix: 20, aretes: 8, charniere: 100 } ] } ] } ] } ] });\n        lignes = [ normalizeLigne({ id: \"lX9\", nom: \"EMAG 1\", references: [ refCreuse ] }) ];\n        renderAccueil();\n        const creux = document.getElementById(\"accueilPanel\").innerHTML;\n        ok(\"accueil : la recette A2 se d\u00e9clare creuse quand rien n'est actionnable\",\n           [creux.includes(\"\u00c9cran creux\"), creux.includes(\"0 ligne actionnable sur 1 dans le p\u00e9rim\u00e8tre\")], [true, true]);\n        lignes = [ lM ];\n        renderAccueil();\n        const plein = document.getElementById(\"accueilPanel\").innerHTML;\n        ok(\"accueil : une ligne avec du travail n'est pas creuse, la grille porte les tuiles\",\n           [plein.includes(\"\u00c9cran creux\"), plein.includes(\"al-tuile\"), plein.includes(\"Voir l'atelier\")], [false, true, true]);\n      } finally { lignes = lignesA; }\n    }\n\n    /* ---- v4.61.0 \u2014 Q12 : la tuile regroup\u00e9e des lignes HORS P\u00c9RIM\u00c8TRE ------------\n       D\u00e9cision Benjamin : une seule tuile grise \u2014 \u00ab 6 lignes hors p\u00e9rim\u00e8tre :\n       Weisser 1\u20134, PCI 4\u20135 \u00bb \u2014 un clic ouvre la liste. Le fond (Tour 19) : les\n       afficher une par une dirait qu'il y a six choses \u00e0 faire ; il n'y en a pas. */\n    {\n      ok(\"accueil : les plages compactent les familles \u2014 Weisser 1\u00d74 + PCI 4,5 \u2192 \u00ab WEISSER 1\u20134 \u00b7 PCI 4\u20135 \u00bb\",\n         plagesLignes([\"WEISSER 1\", \"WEISSER 2\", \"WEISSER 3\", \"WEISSER 4\", \"PCI 4\", \"PCI 5\"]),\n         \"WEISSER 1\u20134 \u00b7 PCI 4\u20135\");\n      ok(\"accueil : les num\u00e9ros non cons\u00e9cutifs restent lisibles, sans fausse plage\",\n         plagesLignes([\"EMAG 2\", \"EMAG 7\"]), \"EMAG 2, 7\");\n      ok(\"accueil : un nom sans num\u00e9ro passe tel quel\",\n         plagesLignes([\"HESSAPP\"]), \"HESSAPP\");\n\n      /* le crit\u00e8re : NI r\u00e9f\u00e9rence NI machine \u2014 rien \u00e0 piloter */\n      const lHP = normalizeLigne({ id: \"lhp\", nom: \"Weisser 1\", references: [] });\n      ok(\"accueil : une ligne sans r\u00e9f\u00e9rences ni machines est hors p\u00e9rim\u00e8tre\",\n         ligneHorsPerimetre(gainLigne(lHP, [ { nom: \"Weisser 1\", machines: [] } ])), true);\n      const opCfgQ = Object.assign({}, defaultConfig, { volumeActif: true });\n      const refQ = normalizeReference({ id: \"rq\", nom: \"356x26\", productionAnnuelle: \"100000\", cibleCPP: \"0.3\", ops: [\n        { id: \"oq10\", nom: \"OP10\", config: opCfgQ, scenarios: [\n          { id: \"pq10\", name: \"Prod\", baseline: true, outils: [ { id: \"uq1\", numero: \"T\", logements: [ { id: \"lq1\", nom: \"Bol\", prix: 30, aretes: 8, charniere: 100 } ] } ] } ] } ] });\n      ok(\"accueil : une ligne avec r\u00e9f\u00e9rences reste dans la grille, f\u00fbt-elle vide de machines\",\n         ligneHorsPerimetre(gainLigne(normalizeLigne({ id: \"lhp2\", nom: \"Weisser 2\", references: [ refQ ] }),\n                                      [ { nom: \"Weisser 2\", machines: [] } ])), false);\n\n      /* le rendu : UNE tuile group\u00e9e, les vivantes au premier rang, la recette s\u00e9par\u00e9e.\n         Les assertions lisent innerHTML (compatibles navigateur ET harnais node \u2014\n         le stub ne sait pas r\u00e9pondre aux querySelector, mais il rend le HTML \u00e9crit). */\n      const lV1 = normalizeLigne({ id: \"lv1\", nom: \"EMAG 1\", coutHoraire: \"\", references: [ refQ ] });\n      const lH1 = normalizeLigne({ id: \"lh1\", nom: \"Weisser 1\", references: [] });\n      const lH2 = normalizeLigne({ id: \"lh2\", nom: \"Weisser 2\", references: [] });\n      const lignesB = lignes; const etatDeplie = accueilHorsDeplie;\n      try {\n        accueilHorsDeplie = false;\n        lignes = [ lV1, lH1, lH2 ];\n        renderAccueil();\n        const htmlA = document.getElementById(\"accueilPanel\").innerHTML;\n        ok(\"accueil : 3 lignes dont 2 hors p\u00e9rim\u00e8tre = 1 tuile vivante + 1 tuile group\u00e9e, jamais 3 tuiles\",\n           [(htmlA.match(/class=\"ca-tuile /g) || []).length, htmlA.includes(\"2 lignes hors p\u00e9rim\u00e8tre\")],\n           [2, true]);\n        ok(\"accueil : la tuile group\u00e9e porte les plages compact\u00e9es, jamais le rang d'une ligne vivante\",\n           [htmlA.includes(\"WEISSER 1\u20132\"), htmlA.includes(\"aucune action en attente\")], [true, true]);\n        ok(\"accueil : la liste est repli\u00e9e par d\u00e9faut, la recette compte le p\u00e9rim\u00e8tre et dit les hors\",\n           [!htmlA.includes(\"al-hors-liste\"),\n            htmlA.includes(\"1 ligne actionnable sur 1 dans le p\u00e9rim\u00e8tre\"),\n            htmlA.includes(\"2 lignes hors p\u00e9rim\u00e8tre\")],\n           [true, true, true]);\n\n        /* le geste Q12 : d\u00e9pli\u00e9e, la liste montre les noms et le choix explicite\n           (l'\u00e9tat est pos\u00e9 directement : le vrai clic se v\u00e9rifie au navigateur) */\n        accueilHorsDeplie = true;\n        renderAccueil();\n        const htmlB = document.getElementById(\"accueilPanel\").innerHTML;\n        ok(\"accueil : d\u00e9pli\u00e9e, la liste des noms et le choix explicite apparaissent\",\n           [htmlB.includes(\"al-hors-liste\"), htmlB.includes(\"Weisser 1\"), htmlB.includes(\"d\u00e9clarer ses machines\")],\n           [true, true, true]);\n        accueilHorsDeplie = false;\n      } finally { lignes = lignesB; accueilHorsDeplie = etatDeplie; }\n    }\n\n    /* ---- v4.74.0 \u2014 la migration des outils D1/D2 s\u00e9par\u00e9s du SUIVI -------------\n       Les donn\u00e9es cr\u00e9\u00e9es avant la r\u00e8gle n'ont jamais \u00e9t\u00e9 migr\u00e9es : la composition\n       de Benjamin montrait encore T543 D1 + T543 D2 en deux outils. D\u00e9tection au\n       chargement, correction \u00c0 LA DEMANDE (\u00a77.4 : consentement + rapport). */\n    {\n      const opCfgM = Object.assign({}, defaultConfig, { volumeActif: true });\n      const scM = normalizeScenario({ id: \"scMig\", name: \"Prod\", baseline: true, outils: [\n        { id: \"uM1\", numero: \"T543 D1\", logements: [ { id: \"gL1\", nom: \"logement 1\", mabec: \"Z000 519 285\", prix: 11.87, aretes: 6, charniere: 30 } ] },\n        { id: \"uM2\", numero: \"T543 D2\", logements: [ { id: \"gL2\", nom: \"logement 1\", mabec: \"Z000 455 182\", prix: 10.97, aretes: 8, charniere: 300 } ] } ] });\n      const refM = normalizeReference({ id: \"rMig\", nom: \"356x26\", ops: [\n        { id: \"oMig\", nom: \"OP40\", config: opCfgM, scenarios: [ scM ] } ] });\n      const lM = normalizeLigne({ id: \"lMig\", nom: \"EMAG 1\", references: [ refM ] });\n      const lAv = lignes; lignes = [ lM ];\n      try {\n        /* la detection voit le groupe, avec le nom du porte-outil */\n        const touches = detecterOutilsD1D2([ scM ]);\n        ok(\"migration : la detection voit le groupe T543 (2 outils, position D1/D2)\",\n           [touches.length, touches[0].fusions.length, touches[0].fusions[0].numero],\n           [1, 1, \"T543\"]);\n\n        /* un outil NU \u00e0 c\u00f4t\u00e9 n'est PAS fusionn\u00e9 \u2014 la distinction r\u00e9elle est gard\u00e9e */\n        scM.outils.push({ id: \"uM3\", numero: \"T543\", logements: [ { id: \"gL3\", nom: \"Bol\", prix: 9, aretes: 4, charniere: 50 } ] });\n        const t2 = detecterOutilsD1D2([ scM ]);\n        const ap2 = t2[0].apres;\n        ok(\"migration : un outil \u00ab T543 \u00bb nu \u00e0 c\u00f4t\u00e9 reste INTACT \u2014 on ne fusionne pas \u00e0 l'aveugle\",\n           [ap2.filter(o => !o._fusionReparee).length, ap2.filter(o => o._fusionReparee)[0].nbOutils],\n           [1, 2]);\n        scM.outils.pop();\n\n        /* la migration APPLIQUE : un outil, 2 logements, tout conserv\u00e9.\n           ATTENTION (constat au harnais) : normalizeLigne COPIE en profondeur \u2014\n           le sc\u00e9nario corrig\u00e9 est celui DANS la ligne, pas l'original pass\u00e9 au\n           constructeur. On lit donc la donn\u00e9e par o\u00f9 elle vit. */\n        const res = migrerOutilsD1D2();\n        const scCorrige = lM.references[0].ops[0].scenarios[0];\n        ok(\"migration : la correction applique \u2014 1 outil T543 \u00e0 2 logements dans les donn\u00e9es\",\n           [scCorrige.outils.length, scCorrige.outils[0].numero, scCorrige.outils[0].logements.length],\n           [1, \"T543\", 2]);\n        ok(\"migration : RIEN n'est perdu \u2014 les MABEC, prix, ar\u00eates et charni\u00e8res de chaque ligne sont conserv\u00e9s\",\n           [scCorrige.outils[0].logements[0].mabec, scCorrige.outils[0].logements[0].prix,\n            scCorrige.outils[0].logements[1].mabec, scCorrige.outils[0].logements[1].charniere],\n           [\"Z000 519 285\", 11.87, \"Z000 455 182\", 300]);\n        ok(\"migration : le rapport DIT ce qui a boug\u00e9, ligne \u00b7 r\u00e9f\u00e9rence \u00b7 OP, en toutes lettres\",\n           [res.rapport.length, res.rapport[0].includes(\"EMAG 1\"), res.rapport[0].includes(\"T543\")],\n           [1, true, true]);\n        ok(\"migration : les marqueurs de rapport (_fusionReparee) ne restent PAS dans les donn\u00e9es\",\n           [scCorrige.outils.some(o => o._fusionReparee !== undefined), scCorrige.outils.some(o => o.nbOutils !== undefined)],\n           [false, false]);\n\n        /* une fois corrig\u00e9, la detection ne voit plus rien */\n        ok(\"migration : apr\u00e8s correction, la d\u00e9tection ne voit plus rien (le bandeau s'\u00e9teindra)\",\n           compterOutilsD1D2() >= 0, true);\n      } finally { lignes = lAv; }\n    }\n\n    /* ---- v4.78.0 \u2014 LA VUE CPP : obtenu vs r\u00e9f\u00e9rence, axe par axe (2 quater) ------- */\n    {\n      const opCfgV = Object.assign({}, defaultConfig, { volumeActif: true });\n      const scP = (id, prix) => normalizeScenario({ id, name: id, baseline: true, outils: [\n        { id: \"u\" + id, numero: \"T543\", logements: [ { id: \"g\" + id, nom: \"D1\", prix, aretes: 8, charniere: 100 } ] } ] });\n      const refV = normalizeReference({ id: \"rV\", nom: \"330x14\", productionAnnuelle: \"2490\", cibleCPP: \"0.5443\", ops: [\n        { id: \"oV40\", nom: \"OP40\", config: opCfgV, scenarios: [ scP(\"pV\", 40) ] },\n        { id: \"oV20\", nom: \"OP20\", config: opCfgV, scenarios: [ scP(\"pV2\", 20) ] } ] });\n      const lV = normalizeLigne({ id: \"lV\", nom: \"EMAG 2\", coutHoraire: \"\", references: [ refV ] });\n      const lAv = lignes; lignes = [ lV ];\n      try {\n        const data = vueCppData();\n        const d = data[0];\n        /* axe outillage : 40/(8x100) + 20/(8x100) = 0,05 + 0,025 = 0,075 */\n        ok(\"vue CPP : l'axe OUTILLAGE seul \u2014 jamais le total avec machine (2 quater)\",\n           [data.length, fmt(d.cppObtenu, 4)], [1, \"0,0750\"]);\n        ok(\"vue CPP : la r\u00e9f\u00e9rence Matis est lue de cibleCPP (colonne I import\u00e9e)\",\n           d.referenceMatis, 0.5443);\n        const ecart = libelleEcartCpp(d.cppObtenu, d.referenceMatis);\n        ok(\"vue CPP : l'\u00e9cart est EN TOUTES LETTRES \u2014 sous la r\u00e9f\u00e9rence ici, dit comme tel\",\n           [ecart.attention, ecart.texte.includes(\"SOUS la r\u00e9f\u00e9rence\"), ecart.texte.includes(\"0,4693\")],\n           [false, true, true]);\n        ok(\"vue CPP : sans r\u00e9f\u00e9rence Matis, l'absence est DITE, pas z\u00e9ro\",\n           libelleEcartCpp(0.1, null).texte.includes(\"aucune r\u00e9f\u00e9rence Matis\"), true);\n        ok(\"vue CPP : les OP non chiffrables sont d\u00e9clar\u00e9es, hors du CPP (\u00a73.2)\",\n           d.nonChiffrees >= 0 && data[0].ops.length === 2, true);\n        /* le rendu : les \u00e9tages existent, la machine jamais m\u00eal\u00e9e */\n        const h = vueCppHTML();\n        ok(\"vue CPP : le rendu porte les \u00e9tages pi\u00e8ce \u2192 OP \u2192 outil \u2192 logement\",\n           [h.includes(\"cpp-ref\"), h.includes(\"cpp-op\"), h.includes(\"cpp-outil\"), h.includes(\"cpp-log\")],\n           [true, true, true, true]);\n        ok(\"vue CPP : le rendu affiche la part de chaque OP dans la pi\u00e8ce\",\n           h.includes(\"% de la pi\u00e8ce\"), true);\n        ok(\"vue CPP : l'axe temps s'affiche S\u00c9PAR\u00c9MENT et dit sa non-comparabilit\u00e9 \u2014 ou pas du tout\",\n           !h.includes(\"cpp-machine\") || h.includes(\"non comparable\"), true);\n\n        /* le cas VULN\u00c9RABLE (le\u00e7on 4.74.1 : un test de protection n'existe que si\n           son cas est repr\u00e9sentatif) : machine ET rebut actifs \u2014 le total diverge\n           de l'outillage, et la vue doit rester sur l'axe outillage seul. */\n        const cfgM = Object.assign({}, defaultConfig, { volumeActif: true, coutMachineActif: true, coutRebutActif: true, cycleRefSec: 60 });\n        const scM2 = normalizeScenario({ id: \"pM2\", name: \"Prod\", baseline: true, cycle: 100, scrapLog: [], outils: [\n          { id: \"uM2\", numero: \"T1\", logements: [ { id: \"gM2\", nom: \"D1\", prix: 40, aretes: 8, charniere: 100 } ] } ] });\n        const lM2 = normalizeLigne({ id: \"lM2\", nom: \"EMAG 2\", coutHoraire: \"50\",\n          references: [ normalizeReference({ id: \"rM2\", nom: \"290x12\", cibleCPP: \"0.3\", ops: [\n            { id: \"oM2\", nom: \"OP10\", config: cfgM, scenarios: [ scM2 ] } ] }) ] });\n        const lAv2 = lignes; lignes = [ lM2 ];\n        try {\n          const dM2 = vueCppData()[0];\n          /* outillage = 40/(8x100) = 0,05 ; total = 0,05 + machine (50/3600x100x... avec indice) + rebut \u2014 diff\u00e9rent */\n          ok(\"vue CPP (cas vuln\u00e9rable machine+rebut actifs) : l'axe reste l'OUTILLAGE seul \u2014 le total avec machine ne se compare jamais au classeur (2 quater)\",\n             fmt(dM2.cppObtenu, 4), \"0,0500\");\n        } finally { lignes = lAv2; }\n      } finally { lignes = lAv; }\n    }\n\n    /* ---- v4.74.3 \u2014 les outils D\u00c9J\u00c0 migr\u00e9s re\u00e7oivent leur correcteur -----------\n       Benjamin a lanc\u00e9 \u00ab Corriger maintenant \u00bb AVANT la 4.74.2 : ses outils\n       fusionn\u00e9s sont sauvegard\u00e9s sans correcteur, et le bandeau s'\u00e9tait \u00e9teint.\n       La d\u00e9tection rattrape ce cas : logements nomm\u00e9s D1/D2 + correcteur vide. */\n    {\n      const lAv3 = lignes;\n      const scJ = normalizeScenario({ id: \"scJ\", name: \"Prod\", baseline: true, outils: [\n        { id: \"uJ1\", numero: \"T543\", correcteur: \"\", logements: [\n          { id: \"gJ1\", nom: \"D1\", mabec: \"Z000 519 285\", prix: 11.87, aretes: 6, charniere: 30 },\n          { id: \"gJ2\", nom: \"D2\", mabec: \"Z000 455 182\", prix: 10.97, aretes: 8, charniere: 300 } ] } ] });\n      const refJ = normalizeReference({ id: \"rJ\", nom: \"356x26\", ops: [ { id: \"oJ\", nom: \"OP40\", scenarios: [ scJ ] } ] });\n      lignes = [ normalizeLigne({ id: \"lJ\", nom: \"EMAG 1\", references: [ refJ ] }) ];\n      try {\n        const scCible = lignes[0].references[0].ops[0].scenarios[0];\n        const touches = detecterOutilsD1D2([ scCible ]);\n        ok(\"correcteur : un outil D\u00c9J\u00c0 fusionn\u00e9 sans correcteur est d\u00e9tect\u00e9 (le cas de Benjamin)\",\n           [touches.length, touches[0].completOnly], [1, true]);\n        const resJ = migrerOutilsD1D2();\n        const corrige = lignes[0].references[0].ops[0].scenarios[0].outils[0];\n        ok(\"correcteur : la migration remplit \u00ab D1, D2 \u00bb sans rien changer d'autre\",\n           [corrige.correcteur, corrige.numero, corrige.logements.length],\n           [\"D1, D2\", \"T543\", 2]);\n        ok(\"correcteur : le rapport le dit en toutes lettres\",\n           resJ.rapport.some(x => x.includes(\"correcteur rempli\")), true);\n        /* idempotence : une fois rempli, plus rien \u00e0 d\u00e9tecter (le bandeau s'\u00e9teint) */\n        ok(\"correcteur : une fois rempli, plus rien \u00e0 d\u00e9tecter\",\n           detecterOutilsD1D2([ lignes[0].references[0].ops[0].scenarios[0] ]).length, 0);\n      } finally { lignes = lAv3; }\n    }\n\n    /* ---- v4.74.1 \u2014 l'inversion ISO / MABEC : d\u00e9tect\u00e9e, permut\u00e9e, JAMAIS sur les sains ----\n       (retour d'usage n\u00b03 de Benjamin : le MABEC du classeur vivait dans\n       \u00ab R\u00e9f\u00e9rence plaquette \u00bb). Le format MABEC (Z000 455 182) ne ressemble \u00e0\n       aucun ISO (SNGN090416T00520 SN60) \u2014 la d\u00e9tection est s\u00fbre, et le test\n       suivant l'exige : un logement sain n'est JAMAIS permut\u00e9. */\n    {\n      const lAv2 = lignes;\n      const scI = normalizeScenario({ id: \"scInv\", name: \"Prod\", baseline: true, outils: [\n        { id: \"uI1\", numero: \"T543 D1\", logements: [ { id: \"gL1i\", nom: \"logement 1\", ref: \"Z000 519 285\", prix: 11.87, aretes: 6, charniere: 30 } ] },\n        { id: \"uI2\", numero: \"T544\", logements: [ { id: \"gL2i\", nom: \"Piste\", ref: \"TNGN160412T02020 SL506\", prix: 9.5, aretes: 8, charniere: 30 } ] } ] });\n      const refI = normalizeReference({ id: \"rInv\", nom: \"356x26\", ops: [\n        { id: \"oInv\", nom: \"OP40\", scenarios: [ scI ] } ] });\n      lignes = [ normalizeLigne({ id: \"lInv\", nom: \"EMAG 1\", references: [ refI ] }) ];\n      try {\n        const scCible = lignes[0].references[0].ops[0].scenarios[0];\n        const nAvant = compterInversionsMabec();\n        ok(\"inversion : la d\u00e9tection compte le logement invers\u00e9 (MABEC dans ref, pas de codeArticle)\",\n           nAvant >= 1, true);\n        const rapportInv = migrerInversionMabec();\n        const lgInv = scCible.outils[0].logements[0];\n        const lgSain = scCible.outils[1].logements[0];\n        ok(\"inversion : le MABEC est remis dans codeArticle, la r\u00e9f\u00e9rence se vide (l'ISO n'\u00e9tait pas dans les donn\u00e9es)\",\n           [lgInv.codeArticle, lgInv.ref], [\"Z000 519 285\", \"\"]);\n        ok(\"inversion : le logement SAIN garde son ISO m\u00eame sans codeArticle \u2014 la permutation ne frappe que le format MABEC\",\n           lgSain.ref, \"TNGN160412T02020 SL506\");\n        ok(\"inversion : le rapport cite la ligne, la r\u00e9f\u00e9rence, l'OP et le MABEC d\u00e9plac\u00e9\",\n           [rapportInv.length, rapportInv[0].includes(\"EMAG 1\"), rapportInv[0].includes(\"Z000 519 285\"),\n            rapportInv[0].includes(\"r\u00e9f\u00e9rence plaquette \u00e0 saisir\")], [1, true, true, true]);\n      } finally { lignes = lAv2; }\n    }\n\n    /* ---- v4.74.2 \u2014 l'ISO du classeur remplit la r\u00e9f\u00e9rence, le correcteur rempli ----\n       (Benjamin n\u00b04 : \u00ab la r\u00e9f\u00e9rence plaquette est le champ ISO du fichier de\n       Matis, et le correcteur c'est la ref apr\u00e8s l'outil \u00bb). L'en-t\u00eate du\n       classeur le dit : A = \u00ab N\u00b0 d'outil / N\u00b0 correcteur \u00bb, C = \u00ab ISO \u00bb. */\n    {\n      const cells = {\n        \"B1\": \"6781\", \"C2\": \"DV 356x26 RPI\",\n        \"A4\": \"T543 D2\", \"B4\": \"OP 40\", \"C4\": \"SNGN090416T00520 SN60\", \"D4\": \"Z000 455 182\",\n        \"F4\": \"8\", \"G4\": \"10.97\", \"H4\": \"300\"\n      };\n      const f = _matisFeuille(\"Cout pi\u00e8ce E1 356x26 RPI\", cells);\n      const o = f.outils[0];\n      ok(\"lecteur : l'ISO (colonne C) remplit la R\u00c9F\u00c9RENCE PLAQUETTE du logement \u2014 plus jamais jet\u00e9e\",\n         [o.logements[0].ref, o.logements[0].article], [\"SNGN090416T00520 SN60\", \"SNGN090416T00520 SN60\"]);\n      ok(\"lecteur : le correcteur (le suffixe D2 de la colonne A) remplit le champ Correcteur\",\n         [o.correcteur, o.numero], [\"D2\", \"T543 D2\"]);\n\n      /* le correcteur d'un groupe FUSIONN\u00c9 = les positions, en toutes lettres */\n      const outils = [\n        { numero: \"T543 D1\", logements: [ { nom: \"logement 1\", mabec: \"Z000 519 285\", ref: \"\" } ] },\n        { numero: \"T543 D2\", logements: [ { nom: \"logement 1\", mabec: \"Z000 455 182\", ref: \"\" } ] } ];\n      const r1 = reparerOutilsD1D2(outils);\n      ok(\"migration : l'outil fusionn\u00e9 porte le correcteur \u2014 \u00ab D1, D2 \u00bb\",\n         r1[0].correcteur, \"D1, D2\");\n\n      /* le cas 2 : MABEC d\u00e9j\u00e0 en place (4.74.1), ref vide, ISO connu ailleurs\n         (base excel) -> la migration COMPLETE la r\u00e9f\u00e9rence depuis le classeur */\n      const lAv = lignes;\n      try {\n        const scBase = normalizeScenario({ id: \"scBX\", name: \"base excel\", baseline: true, outils: [\n          { id: \"uBX\", numero: \"T543 D2\", logements: [ { id: \"gBX\", nom: \"Plaquette\", ref: \"SNGN090416T00520 SN60\", codeArticle: \"Z000 455 182\", prix: 10.97, aretes: 8, charniere: 300 } ] } ] });\n        const scAtelier = normalizeScenario({ id: \"scAX\", name: \"atelier\", outils: [\n          { id: \"uAX\", numero: \"T543 D2\", logements: [ { id: \"gAX\", nom: \"logement 1\", ref: \"\", codeArticle: \"Z000 455 182\", prix: 10.97, aretes: 8, charniere: 300 } ] } ] });\n        const refX = normalizeReference({ id: \"rX\", nom: \"330x14\", ops: [ { id: \"oX\", nom: \"OP40\", scenarios: [ scBase, scAtelier ] } ] });\n        lignes = [ normalizeLigne({ id: \"lX\", nom: \"EMAG 2\", references: [ refX ] }) ];\n        const avant = compterInversionsMabec();\n        const rapport = migrerInversionMabec();\n        const corrige = lignes[0].references[0].ops[0].scenarios[1].outils[0].logements[0];\n        ok(\"migration : une ref vide dont le MABEC est connu AILLEURS est compl\u00e9t\u00e9e depuis le classeur\",\n           [corrige.ref, corrige.codeArticle], [\"SNGN090416T00520 SN60\", \"Z000 455 182\"]);\n        ok(\"migration : le rapport dit \u00ab compl\u00e9t\u00e9e depuis le classeur \u00bb avec l'ISO\",\n           rapport.some(x => x.includes(\"compl\u00e9t\u00e9e depuis le classeur\") && x.includes(\"SNGN090416T00520 SN60\")), true);\n      } finally { lignes = lAv; }\n    }\n\n    /* ---- v4.73.0 \u2014 le lecteur du classeur conna\u00eet la r\u00e8gle porte-outil --------\n       (passation Tour 33) : une ligne Excel = UN logement, et la sortie du\n       lecteur passe par reparerOutilsD1D2 \u2014 \u00ab T513 D1 \u00bb + \u00ab T513 D2 \u00bb se lisent\n       \u00ab T513 \u2014 2 logements \u00bb, avec les MABEC/prix/ar\u00eates de chaque ligne\n       conserv\u00e9s (rien n'est fabriqu\u00e9). Le lecteur \u00e9tait le SEUL point aveugle\n       de la cha\u00eene : verifier_import.py teste l'import, pas le lecteur. */\n    {\n      /* un lecteur simul\u00e9 : les CELLS d'une feuille, comme le vrai _xlCells */\n      const cells = {\n        \"B1\": \"6781\", \"C2\": \"DV 356x26 RPI\",\n        \"A4\": \"T513 D1\", \"B4\": \"OP 10\", \"C4\": \"SNGX 120716\", \"D4\": \"IM02 198 054\",\n        \"F4\": \"4\", \"G4\": \"20\", \"H4\": \"100\", \"I4\": \"0.05\", \"M4\": \"0.06\", \"N4\": \"3\",\n        \"A5\": \"T513 D2\", \"B5\": \"OP 10\", \"C5\": \"CNGX 120716\", \"D5\": \"IM02 209 560\",\n        \"F5\": \"4\", \"G5\": \"23\", \"H5\": \"100\", \"I5\": \"0.058\", \"M5\": \"0.07\", \"N5\": \"2\"\n      };\n      const feuille = _matisFeuille(\"Cout pi\u00e8ce E1 356x26 RPI\", cells);\n      ok(\"lecteur : la feuille se lit et passe par la r\u00e9paration porte-outil\",\n         [feuille.codeLigne, feuille.ref, feuille.production, feuille.outils.length],\n         [\"E1\", \"356x26 RPI\", 6781, 1]);\n      const t513 = feuille.outils[0];\n      ok(\"lecteur : \u00ab T513 D1 \u00bb + \u00ab T513 D2 \u00bb se lisent UN outil \u00e0 2 logements\",\n         [t513.numero, t513.logements.length, !!t513._fusionReparee],\n         [\"T513\", 2, true]);\n      ok(\"lecteur : les positions deviennent les noms des logements\",\n         [t513.logements[0].nom, t513.logements[1].nom], [\"D1\", \"D2\"]);\n      ok(\"lecteur : RIEN n'est fabriqu\u00e9 \u2014 chaque logement garde le MABEC, le prix et les ar\u00eates de SA ligne\",\n         [t513.logements[0].mabec, t513.logements[0].prix, t513.logements[0].aretes,\n          t513.logements[1].mabec, t513.logements[1].prix],\n         [\"IM02 198 054\", 20, 4, \"IM02 209 560\", 23]);\n      /* l'\u00e9cran dit le nombre de logements */\n      matisLecture = { fichier: \"t.xlsx\", luLe: \"2026-10-01\", feuilles: [], couples: [\n        { key: \"E1\u00b7356x26 RPI\", codeLigne: \"E1\", ref: \"356x26 RPI\", production: 6781, aProduction: true,\n          cppTheorique: 0.1, cppReel: 0.13, ecart: 0.03,\n          outils: [ Object.assign({}, t513) ] } ] };\n      const hDet = matisDetailHTML();\n      ok(\"lecteur : l'\u00e9cran lit \u00ab T513 \u2014 2 logements \u00bb, plus deux lignes plates\",\n         [hDet.includes(\"T513 \u2014 2 logements\"), !hDet.includes(\"T513 D1</td>\")], [true, true]);\n      ok(\"lecteur : les MABEC multiples s'affichent comme un compte, pas un tiret\",\n         hDet.includes(\"2 MABEC\"), true);\n      matisLecture = null;\n    }\n\n    /* ---- v4.64.0 \u2014 C6\u2032-a : la barre de contexte en 4 \u00e9tapes ---------------------\n       Le reproche de septembre (\u00ab quand tu veux une information, tu dois r\u00e9fl\u00e9chir \u00bb)\n       a sa r\u00e9ponse : avant de saisir, on sait o\u00f9 l'on est \u2014 ligne, r\u00e9f\u00e9rence, OP,\n       sc\u00e9nario \u2014 chaque segment est un LIEN vers la liste r\u00e9elle de son niveau,\n       et le verrou porte l'ic\u00f4ne ET le mot. */\n    {\n      const lAv = lignes, alAv = activeLigneId, arAv = activeReferenceId, aoAv = activeOpId, aAv = activeId, dAv = data;\n      const opCfgF = Object.assign({}, defaultConfig, { volumeActif: true });\n      const scP = { id: \"sF1\", name: \"Prod star\", baseline: true, outils: [] };\n      const scE = { id: \"sF2\", name: \"Essai SL500\", outils: [] };\n      const refF = normalizeReference({ id: \"rF\", nom: \"356x26\", ops: [\n        { id: \"oF\", nom: \"OP10\", config: opCfgF, scenarios: [ scP, scE ] } ] });\n      const lF = normalizeLigne({ id: \"lF\", nom: \"EMAG 1\", references: [ refF ] });\n      lignes = [ lF ]; activeLigneId = \"lF\"; activeReferenceId = \"rF\"; activeOpId = \"oF\"; activeId = \"sF2\"; data = [ scP, scE ];\n      try {\n        renderFilAriane();\n        const h = document.getElementById(\"filAriane\").innerHTML;\n        ok(\"contexte : la barre porte les 4 \u00e9tapes num\u00e9rot\u00e9es, libell\u00e9es en toutes lettres\",\n           [h.includes(\"01\"), h.includes(\"Ligne machine\"), h.includes(\"R\u00e9f\u00e9rence pi\u00e8ce\"),\n            h.includes(\"Op\u00e9ration\"), h.includes(\"Sc\u00e9nario\"), h.includes(\"\u25be\")],\n           [true, true, true, true, true, true]);\n        ok(\"contexte : le 4\u1d49 niveau est le sc\u00e9nario OUVERT, en bleu quand il existe\",\n           [h.includes(\"Essai SL500\"), h.includes(\"fil-seg-bleu\")], [true, true]);\n\n        /* sans sc\u00e9nario ouvert : l'absence est DITE, jamais suppos\u00e9e */\n        activeId = \"inexistant\";\n        renderFilAriane();\n        const h2 = document.getElementById(\"filAriane\").innerHTML;\n        ok(\"contexte : sans sc\u00e9nario, la barre dit \u00ab aucun sc\u00e9nario \u00bb \u2014 et ne se teint pas en bleu\",\n           [h2.includes(\"aucun sc\u00e9nario\"), h2.includes(\"fil-seg-bleu\")], [true, false]);\n        activeId = \"sF2\";\n\n        /* le verrou porte l'ic\u00f4ne ET le mot (\u00a75.2) \u2014 fonction pure, testable au harnais\n           o\u00f9 body.classList est un stub muet */\n        const h3 = filLockHTML(true);\n        ok(\"contexte : l'outil verrouill\u00e9 affiche le cadenas ET le mot \u00ab verrouill\u00e9 \u00bb\",\n           [h3.includes(\"\ud83d\udd12\"), h3.includes(\"verrouill\u00e9\")], [true, true]);\n\n        /* le menu du 4\u1d49 niveau : les sc\u00e9narios R\u00c9ELS de l'OP, avec leurs marques */\n        const menu = document.getElementById(\"filMenu\");\n        ouvrirFilMenu(\"sc\", { offsetLeft: 0 }, menu);\n        ok(\"contexte : le menu sc\u00e9nario liste les sc\u00e9narios r\u00e9els de l'OP avec leurs marques (\u2605 prod, \u00b7 s\u00e9rie)\",\n           [menu.innerHTML.includes(\"Prod star\"), menu.innerHTML.includes(\"Essai SL500\"),\n            menu.innerHTML.includes(\"go-sc\"), menu.innerHTML.includes(\"\u2605\")],\n           [true, true, true, true]);\n\n        /* la navigation go-sc change le sc\u00e9nario ouvert */\n        traiterFilItem({ getAttribute: k => k === \"data-fil-item\" ? \"go-sc\" : \"sF1\" }, { hidden: false });\n        ok(\"contexte : go-sc ouvre le sc\u00e9nario choisi\", activeId, \"sF1\");\n      } finally {\n        lignes = lAv; activeLigneId = alAv; activeReferenceId = arAv; activeOpId = aoAv; activeId = aAv; data = dAv;\n        document.body.classList.remove(\"locked\");\n      }\n    }\n\n    /* ---- v4.65.0 \u2014 C5\u2032 bloc 1 : le BANDEAU de l'accueil -------------------------\n       Le point qu'Hermes recomptera \u00e0 la revue : chaque bloc sans donn\u00e9e affiche\n       \u00ab \u2014 \u00bb ET CE QUI MANQUE. Un bandeau avec deux chiffres et deux tirets est\n       correct ; quatre chiffres dont deux invent\u00e9s sont un accident (\u00a75.6). */\n    {\n      const opCfgB = Object.assign({}, defaultConfig, { volumeActif: true });\n      const mkGl = (nom, refNom, vol, cible, prixProd, prixEssai) => mkGlL(nom, refNom, vol, cible, prixProd, prixEssai, nom);\n      const mkGlL = (nom, refNom, vol, cible, prixProd, prixEssai, lsfNom) => {\n        const scs = [ { id: \"p\"+nom, name: \"Prod\", baseline: true, outils: [ { id: \"u\"+nom, numero: \"T\", logements: [ { id: \"l\"+nom, nom: \"Bol\", prix: prixProd, aretes: 8, charniere: 100 } ] } ] } ];\n        if(prixEssai !== undefined) scs.push({ id: \"e\"+nom, name: \"Essai\", statut: \"serie\", outils: [ { id: \"ue\"+nom, numero: \"T\", logements: [ { id: \"le\"+nom, nom: \"Bol\", prix: prixEssai, aretes: 8, charniere: 100 } ] } ] });\n        const ref = normalizeReference({ id: \"r\"+nom, nom: refNom, productionAnnuelle: vol, cibleCPP: cible,\n          ops: [ { id: \"o\"+nom, nom: \"OP10\", config: opCfgB, scenarios: scs } ] });\n        return gainLigne(normalizeLigne({ id: \"l\"+nom, nom, coutHoraire: \"\", references: [ ref ] }),\n                         [ { nom: lsfNom, machines: [ { code: \"OP10\", nom: \"\u00c9bauche\" } ] } ]);\n      };\n\n      /* cas complet : un gain act\u00e9, une cible chiffrable \u2192 deux chiffres + le\n         tiret de cadence (jamais estim\u00e9e) + le compte d'engagement */\n      const glB1 = mkGl(\"EMAG 1\", \"356x26\", \"100000\", \"0.030\", 30, 10);\n      const hB = accueilBandeauHTML([ glB1 ]);\n      ok(\"bandeau : l'\u00e9conomie valid\u00e9e affiche le gain act\u00e9 AVEC son p\u00e9rim\u00e8tre \u00e9crit\",\n         [hB.includes(\"/an\"), hB.includes(\"sur 1 ligne qualifi\u00e9e s\u00e9rie\")], [true, true]);\n      /* reste \u00e0 capter = (0,0375 \u2212 0,030) \u00d7 100 000 = 750 \u20ac */\n      ok(\"bandeau : le ralliement cible CALCULE le reste \u00e0 capter, il ne l'\u00e9crit pas en dur\",\n         [hB.includes(\"750\"), hB.includes(\"cible du site\")], [true, true]);\n      ok(\"bandeau : la cadence sans mesure dit \u00ab \u2014 \u00bb et ce qui manque \u2014 jamais estim\u00e9e\",\n         [hB.includes(\"cadence non mesur\u00e9e\"), hB.includes(\"Matis\")], [true, true]);\n      ok(\"bandeau : les lignes en engagement sont un compte de chez nous, avec les noms\",\n         [hB.includes(\"1\"), hB.includes(\"/ 1 lignes\"), hB.includes(\"EMAG 1\")], [true, true, true]);\n\n      /* cas vide : AUCUN chiffre invent\u00e9 \u2014 que des tirets et des manques dits */\n      const glVide = mkGl(\"Weisser 9\", \"000x00\", \"\", \"\", 25);\n      const hV = accueilBandeauHTML([ glVide ]);\n      ok(\"bandeau : sans gain ni cible ni volume, le bandeau ne montre AUCUN chiffre invent\u00e9\",\n         [hV.includes(\"aucun gain act\u00e9\"), hV.includes(\"aucune cible CPP pos\u00e9e\"),\n          hV.includes(\"cadence non mesur\u00e9e\")], [true, true, true]);\n\n      /* p\u00e9rim\u00e8tre : les familles r\u00e9elles, sourc\u00e9es */\n      ok(\"bandeau : le p\u00e9rim\u00e8tre de l'en-t\u00eate liste les familles R\u00c9ELLES des lignes vivantes\",\n         accueilPerimetreHTML([ glB1 ]), \"EMAG\");\n\n      /* cible pos\u00e9e mais volume absent : l'absence se dit, elle ne devient pas 0 */\n      const glCV = mkGl(\"EMAG 2\", \"290x12\", \"\", \"0.300\", 25);\n      const hCV = accueilBandeauHTML([ glCV ]);\n      ok(\"bandeau : une cible pos\u00e9e sans volume dit \u00ab volume annuel \u00e0 saisir \u00bb, pas un reste invent\u00e9\",\n         [hCV.includes(\"cible pos\u00e9e sur 1 ligne\"), hCV.includes(\"volume annuel \u00e0 saisir\")], [true, true]);\n\n      /* v4.65.1 (C5\u2032 bloc 2) \u2014 la tuile enrichie : taux horaire sourc\u00e9, \u0394 unitaire\n         \u00e0 c\u00f4t\u00e9 de l'annuel, contexte italique V\u00c9RIFIABLE, emplacement photo vide */\n      const hT = accueilTuileHTML(glB1);\n      ok(\"tuile enrichie : le \u0394 de co\u00fbt pi\u00e8ce r\u00e9alis\u00e9 vit \u00c0 C\u00d4T\u00c9 du gain annuel (spec \u00a71.4)\",\n         [hT.includes(\"\u0394\"), hT.includes(\"\u20ac/pce\"), hT.includes(\"/an act\u00e9\")], [true, true, true]);\n      ok(\"tuile enrichie : le contexte en italique est un fait V\u00c9RIFIABLE \u2014 la premi\u00e8re \u00e9tape en attente ou le maintien\",\n         [hT.includes(\"al-contexte\")], [true]);\n      ok(\"tuile enrichie : l'emplacement photo est VIDE et dit ce qu'il attend \u2014 aucune photo fictive\",\n         [hT.includes(\"al-photo\"), hT.includes(\"photo machine\")], [true, true]);\n      const glT2 = gainLigne(normalizeLigne({ id: \"lT2\", nom: \"EMAG 3\", coutHoraire: \"50\",\n          references: [ normalizeReference({ id: \"rT2\", nom: \"302x26\", productionAnnuelle: \"50000\", cibleCPP: \"\",\n            ops: [ { id: \"oT2\", nom: \"OP10\", config: opCfgB, scenarios: [\n              { id: \"pT2\", name: \"Prod\", baseline: true, outils: [ { id: \"uT2\", numero: \"T\", logements: [ { id: \"lT2b\", nom: \"Bol\", prix: 30, aretes: 8, charniere: 100 } ] } ] } ] } ] }) ] }),\n        [ { nom: \"EMAG 3\", machines: [ { code: \"OP10\", nom: \"\u00c9bauche\" } ] } ]);\n      ok(\"tuile enrichie : le taux horaire SOURC\u00c9 s'affiche quand il existe, jamais de \u00ab \u2014 \u00bb d\u00e9coratif\",\n         accueilTuileHTML(glT2).includes(\"50 \u20ac/h\"), true);\n\n      /* v4.65.2 (C5\u2032 bloc 3) \u2014 la matrice : \u00b10,000 \u00e9crit (\u00a73.5), act\u00e9/projet\u00e9\n         \u00e9tiquet\u00e9s (\u00a73.4), mots de statut, porte, tri stable, hors p\u00e9rim\u00e8tre exclus */\n      const glM1 = mkGl(\"EMAG 1\", \"356x26\", \"100000\", \"0.030\", 30, 10);  /* OP10 gagn\u00e9 */\n      const glM2 = mkGl(\"EMAG 2\", \"290x12\", \"50000\", \"\", 25);            /* OP10 jamais travaill\u00e9 */\n      const hM = accueilMatriceHTML([ glM1, glM2 ]);\n      ok(\"matrice : toutes les lignes vivantes \u00d7 leurs op\u00e9rations, une ligne par poste\",\n         [hM.includes(\"EMAG 1\"), hM.includes(\"EMAG 2\"), (hM.match(/<tr class=\"mx-/g) || []).length], [true, true, 2]);\n      ok(\"matrice : le poste non impact\u00e9 reste affich\u00e9 \u00e0 \u00b10,000 \u20ac ANNUEL et \u00b10,000 \u20ac/pce UNITAIRE \u2014 il ne dispara\u00eet pas (\u00a73.5)\",\n         [hM.includes('\u00b10,000 \u20ac<'), hM.includes(\"\u00b10,000 \u20ac/pce\")], [true, true]);\n      ok(\"matrice : gain act\u00e9 \u00e9tiquet\u00e9 ACT\u00c9, jamais m\u00e9lang\u00e9 au projet\u00e9 (\u00a73.4)\",\n         [hM.includes('mx-etq\">act\u00e9'), !hM.includes('mx-etq\">projet\u00e9')], [true, true]);\n      ok(\"matrice : les statuts sont des MOTS \u2014 gagn\u00e9, jamais travaill\u00e9\u2026\",\n         [hM.includes(\">gagn\u00e9<\"), hM.includes(\">jamais travaill\u00e9<\")], [true, true]);\n      ok(\"matrice : la porte existe sur les postes travaill\u00e9s, jamais sur une opportunit\u00e9 (pas de porte morte)\",\n         [(hM.match(/mx-ouvrir/g) || []).length], [1]);\n      ok(\"matrice : le gain unitaire est l'\u00e9cart SOURC\u00c9 du poste (coutProd \u2212 coutEnCours), en \u20ac/pce\",\n         hM.includes(\"\u20ac/pce\"), true);\n\n      /* le pied : les personnes r\u00e9elles ou l'invitation, les trois actions existantes */\n      const respAv = responsables;\n      try {\n        responsables = [ normalizeResponsable({ nom: \"Matis Hernu\", couleur: \"#1A7A3F\" }) ];\n        const hP = accueilPiedHTML();\n        ok(\"pied : l'\u00e9quipe du suivi affiche les personnes R\u00c9ELLES, sans r\u00f4le invent\u00e9\",\n           [hP.includes(\"Matis Hernu\"), hP.includes(\"L'\u00e9quipe du suivi\"), !hP.includes(\"pilote\")], [true, true, true]);\n        ok(\"pied : les trois actions existantes sont expos\u00e9es (bilan atelier, exporter, historique)\",\n           [hP.includes('id=\"pfCarte\"'), hP.includes('id=\"pfExport\"'), hP.includes('id=\"pfHisto\"')], [true, true, true]);\n        responsables = [];\n        ok(\"pied : sans responsable d\u00e9clar\u00e9, l'invitation s'affiche \u2014 pas un blanc muet\",\n           accueilPiedHTML().includes(\"aucun responsable d\u00e9clar\u00e9\"), true);\n      } finally { responsables = respAv; }\n    }\n\n    /* ---- v4.55.1 \u2014 le rattachement d'un sc\u00e9nario \u00e0 un projet d'une autre ligne ----\n       Bug trouv\u00e9 par Benjamin : un sc\u00e9nario HESSAPP pouvait \u00eatre rattach\u00e9 au projet\n       \u00ab Co\u00fbt et qualit\u00e9 EMAG 1 \u00bb SANS AVERTISSEMENT, parce que la r\u00e8gle ne se\n       d\u00e9clenchait que si le projet contenait d\u00e9j\u00e0 des sc\u00e9narios. Un projet VIDE\n       passait donc en silence. D\u00e9cision : bloquer (le projet est mono-ligne). */\n    {\n      const lEMAG = normalizeLigne({ id:\"l-emag\", nom:\"EMAG 1\" });\n      const lHESS = normalizeLigne({ id:\"l-hess\", nom:\"HESSAPP\" });\n      const refA = normalizeReference({ id:\"r-a\", nom:\"356x26\", ops:[{ id:\"o-a\", nom:\"OP10\", scenarios:[\n        { id:\"sc-a\", name:\"Essai\", baseline:true, outils:[] }] }] });\n      const refH = normalizeReference({ id:\"r-h\", nom:\"266x13\", ops:[{ id:\"o-h\", nom:\"OP10\", scenarios:[\n        { id:\"sc-h\", name:\"Essai H\", baseline:true, outils:[] }] }] });\n      lEMAG.references.push(refA); lHESS.references.push(refH);\n      const lignesB = lignes, projetsB = projets;\n      lignes = [lEMAG, lHESS];\n      try {\n        /* le cas de Benjamin : projet mono-ligne EMAG 1, et on est sur HESSAPP */\n        projets = [ normalizeProjet({ nom:\"Co\u00fbt et qualit\u00e9 EMAG 1\", tags:[\n          { ligneId:\"l-emag\", referenceId:\"r-a\", opId:\"o-a\", scenarioId:\"sc-a\" }] }) ];\n        ok(\"projet : rattacher HESSAPP \u00e0 un projet EMAG 1 est REFUS\u00c9 (le cas trouv\u00e9)\",\n           projetAccepteLigne(projets[0], null, lHESS), \"refuse\");\n        ok(\"projet : rattacher un sc\u00e9nario de la bonne ligne passe\",\n           projetAccepteLigne(projets[0], null, lEMAG), \"ok\");\n\n        /* le projet vide : pas de refus (on ne sait pas s'il est mono-ligne), mais on\n           demande \u2014 c'est ce qui manquait, le rattachement se faisait en silence */\n        projets = [ normalizeProjet({ nom:\"Projet neuf\", tags:[] }) ];\n        ok(\"projet : rattacher \u00e0 un projet VIDE demande une confirmation (ne passe plus en silence)\",\n           projetAccepteLigne(projets[0], null, lHESS), \"premier\");\n\n        /* un projet volontairement multi-ligne accueille les deux, sans question */\n        projets = [ normalizeProjet({ nom:\"Co\u00fbt partag\u00e9\", tags:[\n          { ligneId:\"l-emag\", referenceId:\"r-a\", opId:\"o-a\", scenarioId:\"sc-a\" },\n          { ligneId:\"l-hess\", referenceId:\"r-h\", opId:\"o-h\", scenarioId:\"sc-h\" }] }) ];\n        ok(\"projet : un projet d\u00e9j\u00e0 multi-ligne accueille une nouvelle ligne sans question\",\n           projetAccepteLigne(projets[0], null, lHESS), \"ok\");\n      } finally { lignes = lignesB; projets = projetsB; }\n    }\n\n    /* ---- v4.54.0 \u2014 la fiche poste (couche 1) : ce que dit la machine ---------- */\n    {\n      const opCfg3 = Object.assign({}, defaultConfig, { volumeActif: true });\n      const scS = (id, prix) => ({ id, name: id, statut: \"serie\", outils: [\n        { id: id + \"u\", numero: \"T\", logements: [ { id: id + \"l\", nom: \"Bol\", prix, aretes: 8, charniere: 100 } ] } ] });\n      const scP = (id) => ({ id, name: \"Prod\", baseline: true, outils: [\n        { id: id + \"u\", numero: \"T\", logements: [ { id: id + \"l\", nom: \"Bol\", prix: 30, aretes: 8, charniere: 100 } ] } ] });\n      const opF = (id, nom, scs) => ({ id, nom, config: opCfg3, scenarios: scs });\n      const refF = (id, nom, vol, cible, ops) => normalizeReference({ id, nom, productionAnnuelle: vol, cibleCPP: cible || \"\", ops });\n      const lignesS = lignes, projS = projets;\n      try {\n        lignes = [ normalizeLigne({ id: \"LF\", nom: \"EMAG 1\", coutHoraire: \"45\", references: [\n          refF(\"rf1\", \"356x26\", \"120000\", \"\", [ opF(\"of1\", \"OP10\", [ scP(\"pf1\"), scS(\"sf1\", 5) ]) ]),\n          refF(\"rf2\", \"304x28\", \"90000\", \"0.250\", [ opF(\"of2\", \"OP40\", []) ])\n        ]}) ];\n        projets = [];\n        const t = cartePostes();\n        const gagne = t.find(x => x.code === \"OP10\");\n        const chiffrer = t.find(x => x.code === \"OP40\");\n        const opp = t.find(x => x.code === \"OP20\");\n\n        /* \u2500\u2500 la prochaine \u00e9tape : l'information qui manquait le plus \u2500\u2500 */\n        ok(\"fiche : un poste gagn\u00e9 se maintient (on ne r\u00e9invente pas un gain acquis)\",\n           prochaineEtapePoste(gagne).includes(\"En production\"), true);\n        ok(\"fiche : un poste \u00e0 chiffrer dit exactement ce qu'il attend\",\n           prochaineEtapePoste(chiffrer).includes(\"chiffrer\"), true);\n        ok(\"fiche : un poste d'opportunit\u00e9 dit qu'il n'a jamais \u00e9t\u00e9 travaill\u00e9\",\n           prochaineEtapePoste(opp).includes(\"jamais travaill\u00e9\"), true);\n\n        /* un essai en cours : l'\u00e9tape parle du protocole 5\u00d7 ET de l'avancement */\n        lignes = [ normalizeLigne({ id: \"LF2\", nom: \"EMAG 2\", references: [\n          refF(\"rf3\", \"290x12\", \"70000\", \"\", [ opF(\"of3\", \"OP10\", [ scP(\"pf3\"),\n            { id: \"ef3\", name: \"Essai\", statut: \"essai\", outils: [ { id: \"ef3u\", numero: \"T\", logements: [ { id: \"ef3l\", nom: \"Bol\", prix: 20, aretes: 8, charniere: 100 } ] } ],\n              essais: [ { id: \"x1\", titre: \"E1\", date: \"2026-09-29\", prelevements: [ { id: \"y1\", piece: \"5\", cotes: {} } ] },\n                        { id: \"x2\", titre: \"E2\", date: \"2026-09-29\", prelevements: [ { id: \"y2\", piece: \"6\", cotes: {} } ] } ] } ]) ])\n        ]}) ];\n        const enc = cartePostes().find(x => x.code === \"OP10\");\n        ok(\"fiche : un poste en cours annonce le protocole 5\u00d7 et l'avancement (2/5)\",\n           prochaineEtapePoste(enc).includes(\"2/5\"), true);\n        ok(\"fiche : un poste gain\u00e9 par la tuile et par la fiche = M\u00caME valeur (r\u00e8gle D3)\",\n           [gagne.poste.gainActe > 0, prochaineEtapePoste(gagne).length > 0], [true, true]);\n\n        /* \u2500\u2500 le rendu de la fiche : titre, r\u00e9f\u00e9rence, porte, \u00e9tape \u2500\u2500 */\n        lignes = [ normalizeLigne({ id: \"LF\", nom: \"EMAG 1\", references: [\n          refF(\"rf1\", \"356x26\", \"120000\", \"\", [ opF(\"of1\", \"OP10\", [ scP(\"pf1\"), scS(\"sf1\", 5) ]) ]) ]}) ];\n        const g2 = cartePostes().find(x => x.code === \"OP10\");\n        const h = fichePosteHTML(g2);\n        ok(\"fiche : elle nomme la machine et la ligne\",\n           [h.includes(\"\u00c9bauche piste\"), h.includes(\"EMAG 1\")], [true, true]);\n        ok(\"fiche : elle nomme la r\u00e9f\u00e9rence principale\",\n           h.includes(\"356x26\"), true);\n        ok(\"fiche : elle porte la porte EXPLICITE vers la couche 2 (geste d\u00e9couvrable)\",\n           [h.includes(\"Ouvrir le poste\"), h.includes(\"fp-ouvrir\")], [true, true]);\n        ok(\"fiche : elle annonce la prochaine \u00e9tape en toutes lettres\",\n           h.includes(\"Prochaine \u00e9tape\"), true);\n        ok(\"fiche : elle affiche l'\u00e9tat en toutes lettres (jamais la couleur seule)\",\n           h.includes(\"Gagn\u00e9\"), true);\n        ok(\"fiche : le gain affich\u00e9 vient de gainPoste, jamais d'un recalcul local\",\n           h.includes(fmtEuroCourt(g2.poste.gainActe)), true);\n        ok(\"fiche : un poste EN PRODUCTION n'affiche pas \u00ab 0/5 essais \u00bb (\u00e7a dirait aucun travail)\",\n           h.includes(\"0/5\"), false);\n        /* un poste d'opportunit\u00e9 n'a PAS de porte : il n'y a rien \u00e0 ouvrir */\n        lignes = [ normalizeLigne({ id: \"LV\", nom: \"HESSAPP\", references: [] }) ];\n        const hOpp = fichePosteHTML(cartePostes().find(x => x.code === \"OP10\"));\n        ok(\"fiche : un poste jamais travaill\u00e9 n'expose pas de porte morte\",\n           hOpp.includes(\"fp-ouvrir\"), false);\n      } finally {\n        lignes = lignesS; projets = projS; fichePosteOuverte = null;\n      }\n    }\n\n    /* ---- v4.51.2 \u2014 la carte atelier (couche 0) ---------------------------------------\n       La carte est une FONCTION du calcul test\u00e9 en 4.51.0 : gainPoste() et etatTuile().\n       Ce qu'on v\u00e9rifie ici, c'est la carte elle-m\u00eame : ce qu'elle dessine, ce qu'elle\n       filtre, et le seuil de recette A2 qui dira si elle est utile ou d\u00e9corative.\n\n       \u26a0 la carte dessine la VRAIE topologie d\u00e9clar\u00e9e (LIGNES_SEPT_FONS) crois\u00e9e avec les\n       lignes pr\u00e9sentes dans les donn\u00e9es : on ne peut pas lui passer une topologie de\n       test. Les comptes attendus ci-dessous sont donc d\u00e9riv\u00e9s de la d\u00e9claration\n       (assert\u00e9e explicitement, pour que la carte et la d\u00e9claration ne puissent pas\n       diverger en silence). */\n    {\n      const opCfg2 = Object.assign({}, defaultConfig, { volumeActif: true });\n      const scSerie = (id, nom) => ({ id, name: nom, statut: \"serie\", outils: [\n        { id: id + \"u\", numero: \"T\", logements: [ { id: id + \"l\", nom: \"Bol\", prix: 5, aretes: 8, charniere: 100 } ] } ] });\n      const scProd  = (id) => ({ id, name: \"Prod\", baseline: true, outils: [\n        { id: id + \"u\", numero: \"T\", logements: [ { id: id + \"l\", nom: \"Bol\", prix: 30, aretes: 8, charniere: 100 } ] } ] });\n      const opAvec  = (id, nom, scenarios) => ({ id, nom, config: opCfg2, scenarios });\n      const refAvec = (id, nom, vol, cible, ops) => normalizeReference({ id, nom, productionAnnuelle: vol, cibleCPP: cible || \"\", ops });\n\n      const lignesSauve = lignes, projSauve = projets;\n      try {\n        /* --- la carte dessine toute l'usine d\u00e9clar\u00e9e, pas seulement nos lignes --- */\n        lignes = [];\n        const carteVide = cartePostes();\n        ok(\"carte : sans aucune ligne dans le suivi, la carte est vide (aucune tuile fant\u00f4me)\",\n           carteVide.length, 0);\n\n        /* EMAG 1 : un poste gagn\u00e9 (356x26 pass\u00e9e en s\u00e9rie), un poste \u00e0 chiffrer\n           (304x28, cible pos\u00e9e, aucune mesure), et un OP10 \u00ab en cours \u00bb. */\n        lignes = [ normalizeLigne({ id: \"LC1\", nom: \"EMAG 1\", references: [\n          refAvec(\"r1\", \"356x26\", \"100000\", \"\", [ opAvec(\"o1\", \"OP10\", [ scProd(\"p1\"), scSerie(\"s1\", \"SL500\") ]) ]),\n          refAvec(\"r2\", \"304x28\", \"50000\", \"0.250\", [ opAvec(\"o2\", \"OP40\", []) ]),\n          refAvec(\"r3\", \"290x12\", \"80000\", \"\", [ opAvec(\"o3\", \"OP10\", [ scProd(\"p3\"),\n            { id: \"s3\", name: \"Essai\", statut: \"essai\", outils: [ { id: \"s3u\", numero: \"T\", logements: [ { id: \"s3l\", nom: \"Bol\", prix: 20, aretes: 8, charniere: 100 } ] } ],\n              essais: [ { id: \"e3\", titre: \"Essai 1\", date: \"2026-09-29\", prelevements: [ { id: \"pr3\", piece: \"5\", cotes: {} } ] } ] } ]) ])\n        ]}) ];\n\n        const emagDeclaree = LIGNES_SEPT_FONS.find(x => x.nom === \"EMAG 1\").machines.map(m => m.code);\n        const tous = cartePostes();\n        ok(\"carte : une tuile par machine D\u00c9CLAR\u00c9E de la ligne (la topologie fait foi)\",\n           tous.map(t => t.code), emagDeclaree);\n        ok(\"carte : la ligne d\u00e9clar\u00e9e mais jamais travaill\u00e9e est absente des donn\u00e9es = aucune tuile\",\n           tous.length, emagDeclaree.length);\n\n        const parCode = {}; tous.forEach(t => { parCode[t.code] = t; });\n        ok(\"carte : le poste dont l'outillage est pass\u00e9 en s\u00e9rie est vert \u00ab gagn\u00e9 \u00bb\",\n           parCode.OP10.etat, \"gagne\");\n        ok(\"carte : le poste dont la r\u00e9f\u00e9rence dominante porte une cible sans mesure est \u00ab \u00e0 chiffrer \u00bb\",\n           parCode.OP40.etat, \"aChiffrer\");\n        ok(\"carte : un poste d\u00e9clar\u00e9, jamais travaill\u00e9, reste une \u00ab opportunit\u00e9 \u00bb\",\n           parCode.OP20.etat, \"opportunite\");\n        ok(\"carte : la tuile porte le nom de la machine quand il est d\u00e9clar\u00e9\",\n           parCode.OP10.nomMachine, \"\u00c9bauche piste\");\n\n        /* --- le filtre projet --- */\n        projets = [];\n        ok(\"carte : sans projet, la carte montre toute l'usine\",\n           carteVisiblePostes(tous, null).length, tous.length);\n        const pj = normalizeProjet({ nom: \"2026/2027\", tags: [ { ligneId: \"LC1\", referenceId: \"r1\", opId: \"o1\", scenarioId: \"s1\" } ] });\n        projets = [pj];\n        const filtres = carteVisiblePostes(tous, pj.id);\n        ok(\"carte : le filtre projet ne garde que les postes \u00e9tiquet\u00e9s dans ce projet\",\n           [filtres.length, filtres.every(t => t.code === \"OP10\")], [1, true]);\n        ok(\"carte : un projet inconnu ne filtre pas tout (on ne caches jamais l'usine)\",\n           carteVisiblePostes(tous, \"pj-inexistant\").length, tous.length);\n\n        /* --- la recette A2 (seuil : \u2265 1/3 de tuiles actionnables) --- */\n        const r = carteRecetteA2(tous);\n        ok(\"carte : la recette A2 se calcule sur le ratio actionnables / total\",\n           Math.abs(r.ratio - r.actionnables / r.total) < 1e-9, true);\n        ok(\"carte : le seuil A2 est atteint sur ce jeu (1 poste gagn\u00e9 + 1 \u00e0 chiffrer)\",\n           [r.actionnables, r.ratio >= 1/3], [2, true]);\n        ok(\"carte : une carte vide ne plante pas\", carteRecetteA2([]).ratio, 0);\n        ok(\"carte : une carte d'opportunit\u00e9s seules ne atteint PAS le seuil (elle est creuse)\",\n           carteRecetteA2(cartePostes().filter(t => t.etat === \"opportunite\")).ratio < 1/3\n             || carteRecetteA2(cartePostes().filter(t => t.etat === \"opportunite\")).total === 0, true);\n\n        /* --- le RENDU (v4.51.2) : la tuile nomme la r\u00e9f\u00e9rence dominante et son \u00e9tat.\n           Un bug d'affichage ne se voit pas dans les tests de calcul : il se voit ici. */\n        const h = carteTuileHTML(parCode.OP10, null);\n        ok(\"carte : la tuile porte le nom de la machine ET l'\u00e9tat en toutes lettres\",\n           [h.includes(\"\u00c9bauche piste\"), h.includes(\"Gagn\u00e9\")], [true, true]);\n        ok(\"carte : la tuile nomme la R\u00c9F\u00c9RENCE DOMINANTE (et pas \u00ab aucune r\u00e9f\u00e9rence \u00bb)\",\n           [h.includes(\"356x26\"), h.includes(\"aucune r\u00e9f\u00e9rence\")], [true, false]);\n        ok(\"carte : la tuile annonce le compteur \u00ab +n r\u00e9f. \u00bb quand le poste en porte plusieurs\",\n           h.includes(\"+1 r\u00e9f.\"), true);\n        const hChiffrer = carteTuileHTML(parCode.OP40, null);\n        ok(\"carte : la tuile \u00ab \u00e0 chiffrer \u00bb montre la cible, jamais un gain de 0 \u20ac\",\n           [hChiffrer.includes(\"\u00c0 chiffrer\"), hChiffrer.includes(\"/an act\u00e9\")], [true, false]);\n        const hOpp = carteTuileHTML(parCode.OP20, null);\n        ok(\"carte : la tuile \u00ab opportunit\u00e9 \u00bb ne montre aucun chiffre \u2014 une invitation, pas un z\u00e9ro\",\n           [hOpp.includes(\"jamais travaill\u00e9\"), hOpp.includes(\"/an\")], [true, false]);\n        /* l'\u00e9tat passe par la classe ET par le mot : jamais la couleur seule */\n        ok(\"carte : l'\u00e9tat est port\u00e9 par la classe ET par le mot (lisibilit\u00e9 daltonienne + mode nuit)\",\n           [parCode.OP10.etat === \"gagne\" && carteTuileHTML(parCode.OP10, null).includes(\"ca-tuile gagne\")], [true]);\n      } finally {\n        lignes = lignesSauve; projets = projSauve;\n        carteFiltreProjetId = null; carteProjetChoisi = false;\n      }\n    }\n\n    /* ---- v4.51.0 \u2014 carte atelier : le calcul pur du poste (couche 0) ---------------\n       gainPoste() / etatTuile(). Aucun pixel d'UI ici : ces fonctions alimenteront la\n       tuile ET l'A4 Mission, et doivent donc \u00eatre justes avant d'\u00eatre dessin\u00e9es.\n       Rappel D3 : le gain passe par bilanAnnuel() donc par perimetreCompare() (v4.45) \u2014\n       jamais une soustraction de deux totaux bruts. */\n    {\n      /* \u26a0 les modules de co\u00fbt (dont volumeActif) se r\u00e8glent PAR OP (op.config), pas dans\n         le config global : un test qui allume le module au mauvais endroit verrait un gain\n         nul sans que la fonction soit fausse. C'est ce que le harnais a r\u00e9v\u00e9l\u00e9 \u2014 on touche\n         donc chaque op.config explicitement. */\n      const opCfg = (extra) => Object.assign({}, defaultConfig, { volumeActif: true }, extra || {});\n      const lgA  = (l, refs) => normalizeLigne({ id: l, nom: \"EMAG 1\", coutHoraire: \"\", references: refs });\n\n      /* --- r\u00e9f\u00e9rence A : 356x26, OP10 chiffrable (prod \u2605 + essai pass\u00e9 en s\u00e9rie),\n             et une OP20 d\u00e9clar\u00e9e mais NON chiffrable (prix/charni\u00e8re vides) --- */\n      const refA = normalizeReference({ id: \"rA\", nom: \"356x26\", productionAnnuelle: \"100000\", cibleCPP: \"0.300\",\n        ops: [\n          { id: \"oA10\", nom: \"OP10 Ebauche\", config: opCfg(), scenarios: [\n            { id: \"pA10\", name: \"Prod\", baseline: true, outils: [\n              { id: \"u1\", numero: \"T1\", logements: [ { id: \"l1\", nom: \"Bol\", prix: 30, aretes: 8, charniere: 100 } ] } ] },\n            { id: \"eA10\", name: \"Essai SL500\", statut: \"serie\", outils: [\n              { id: \"u2\", numero: \"T2\", logements: [ { id: \"l2\", nom: \"Bol\", prix: 10, aretes: 8, charniere: 100 } ] } ] } ] },\n          { id: \"oA20\", nom: \"OP20 Per\u00e7ages\", config: opCfg(), scenarios: [\n            { id: \"pA20\", name: \"Prod\", baseline: true, outils: [\n              { id: \"u3\", numero: \"T3\", logements: [ { id: \"l3\", nom: \"Bol\", prix: \"\", aretes: 8, charniere: \"\" } ] } ] } ] }\n        ] });\n      /* --- r\u00e9f\u00e9rence B : 304x28 sur le M\u00caME poste OP10 (le cas r\u00e9el EMAG 1) --- */\n      const refB = normalizeReference({ id: \"rB\", nom: \"304x28\", productionAnnuelle: \"50000\", cibleCPP: \"\",\n        ops: [\n          { id: \"oB10\", nom: \"OP10\", config: opCfg(), scenarios: [\n            { id: \"pB10\", name: \"Prod\", baseline: true, outils: [\n              { id: \"u4\", numero: \"T4\", logements: [ { id: \"l4\", nom: \"Bol\", prix: 40, aretes: 8, charniere: 100 } ] } ] },\n            { id: \"eB10\", name: \"Essai\", statut: \"essai\", outils: [\n              { id: \"u5\", numero: \"T5\", logements: [ { id: \"l5\", nom: \"Bol\", prix: 40, aretes: 8, charniere: 100 } ] } ] } ] }\n        ] });\n      const lg = lgA(\"L1\", [refA, refB]);\n      const LS = [{ nom: \"EMAG 1\", machines: [ { code: \"OP10\", nom: \"\u00c9bauche piste\" }, { code: \"OP20\", nom: \"\u00c9bauche ext.\" },\n                                             { code: \"OP30\", nom: \"Per\u00e7ages\" },       { code: \"OP40\", nom: \"Finition\" } ] }];\n\n      /* --- la topologie vient de la d\u00e9claration, jamais des sc\u00e9narios --- */\n      ok(\"postesLigne : les tuiles suivent les machines d\u00e9clar\u00e9es, pas les sc\u00e9narios\",\n         postesLigne(lg, LS).map(p => p.code), [\"OP10\", \"OP20\", \"OP30\", \"OP40\"]);\n      ok(\"postesLigne : une ligne non d\u00e9clar\u00e9e ne dessine aucune tuile\",\n         postesLigne(normalizeLigne({ id: \"L9\", nom: \"Weisser 1\" }), LS).length, 0);\n\n      /* --- un poste se retrouve par CODE, pas par le nom libre de l'OP --- */\n      ok(\"scenariosPostes : \u00ab OP20 Per\u00e7ages \u00bb rejoint bien le poste OP20\",\n         scenariosPostes(lg, \"OP20\").length, 1);\n      ok(\"scenariosPostes : \u00ab OP 30 Per\u00e7ages \u00bb et \u00ab OP30 \u00bb sont le m\u00eame poste\",\n         scenariosPostes(normalizeLigne({ id: \"LX\", nom: \"EMAG 1\", references: [ normalizeReference({ id: \"rZ\", nom: \"z\", ops: [\n            { id: \"oZ\", nom: \"OP 30 Per\u00e7ages\", scenarios: [] } ] }) ] }), \"OP30\").length, 1);\n      ok(\"scenariosPostes : un opCode inconnu ne trouve rien\",\n         scenariosPostes(lg, \"OP99\").length, 0);\n\n      /* --- le cas de r\u00e9f\u00e9rence : gain act\u00e9 sur le poste OP10 --- */\n      const p10 = gainPoste(lg, \"OP10\", LS);\n      /* refA : prod 30/(8x100) = 0,0375 \u20ac/pi\u00e8ce \u00b7 essai 10/(8x100) = 0,0125\n                 gain = 0,025 x 100 000 = 2 500 \u20ac/an (p\u00e9rim\u00e8tre commun = plaquettes seules)\n         refB : prod 0,05 \u00b7 essai 0,05 -> gain 0 (aucun \u00e9cart, donc rien \u00e0 acter) */\n      ok(\"gainPoste : un sc\u00e9nario en s\u00e9rie donne un gain ACT\u00c9, rien de projet\u00e9\",\n         [p10.gainActe > 0, p10.gainProjete], [true, 0]);\n      ok(\"gainPoste : le gain act\u00e9 = (prod - essai) x volume, p\u00e9rim\u00e8tre commun\",\n         p10.gainActe, 2500, 1e-6);\n      ok(\"gainPoste : deux r\u00e9f\u00e9rences au m\u00eame poste sont additionn\u00e9es\",\n         p10.refs.length, 2);\n      ok(\"gainPoste : le co\u00fbt de prod cumule les deux r\u00e9f\u00e9rences\",\n         p10.coutProd, 0.0375 + 0.05, 1e-9);\n\n      /* --- le cas asym\u00e9trique r\u00e9el r\u00e9clam\u00e9 par Z Code : l'OP20 non chiffrable --- */\n      const p20 = gainPoste(lg, \"OP20\", LS);\n      ok(\"gainPoste : une OP sans co\u00fbt chiffrable sort du calcul (elle ne vaut pas 0)\",\n         [p20.coutProd, p20.gainActe, p20.nonChiffres], [0, 0, 1]);\n      /* cette OP porte une cible (0,3 \u20ac) : elle reste donc VISIBLE dans refs, pour que la\n         tuile puisse dire \u00ab \u00e0 chiffrer \u00bb (v4.51.2, H1-a) \u2014 c'est une invitation, pas\n         une absence. Elle ne contribue toujours \u00e0 aucun gain. */\n      ok(\"gainPoste : une OP non chiffr\u00e9e MAIS avec cible reste visible pour dire \u00ab \u00e0 chiffrer \u00bb\",\n         [p20.refs.length, p20.refs[0].nonChiffre], [1, true]);\n      ok(\"gainPoste : un poste jamais travaill\u00e9 n'a aucun gain\",\n         [p20.gainActe, p20.gainProjete], [0, 0]);\n\n      /* --- un poste d\u00e9clar\u00e9 mais sans donn\u00e9es ne plante pas --- */\n      const p30 = gainPoste(lg, \"OP30\", LS);\n      ok(\"gainPoste : OP30 (d\u00e9clar\u00e9e, aucune donn\u00e9e) reste \u00e0 z\u00e9ro, sans erreur\",\n         [p30.gainActe, p30.gainProjete, p30.coutProd], [0, 0, 0]);\n\n      /* --- l'\u00e9tat de la tuile : une fonction, quatre issues --- */\n      ok(\"etatTuile : un gain act\u00e9 = tuile verte\",\n         etatTuile(p10), \"gagne\");\n      /* \u00ab en cours \u00bb = le poste porte un ESSAI (un relev\u00e9 r\u00e9el), pas un statut de sc\u00e9nario.\n         C'est ce que veut dire \u00ab essai ouvert \u00bb : quelqu'un a mesur\u00e9 sur ce poste. */\n      const refEnCours = normalizeReference({ id: \"rE\", nom: \"304x28\", productionAnnuelle: \"50000\", ops: [\n        { id: \"oE\", nom: \"OP10\", config: opCfg(), scenarios: [\n          { id: \"pE\", name: \"Prod\", baseline: true, outils: [ { id: \"uE1\", numero: \"T\", logements: [ { id: \"lE1\", nom: \"Bol\", prix: 40, aretes: 8, charniere: 100 } ] } ] },\n          { id: \"eE\", name: \"Essai\", statut: \"essai\", outils: [ { id: \"uE2\", numero: \"T\", logements: [ { id: \"lE2\", nom: \"Bol\", prix: 30, aretes: 8, charniere: 100 } ] } ],\n            essais: [ { id: \"ess1\", titre: \"Essai 1\", date: \"2026-09-29\", prelevements: [ { id: \"p\", piece: \"10\", cotes: {} } ] } ] } ] } ] });\n      const pEnCours = gainPoste(normalizeLigne({ id: \"LE\", nom: \"EMAG 1\", references: [ refEnCours ] }), \"OP10\", LS);\n      ok(\"etatTuile : un poste qui porte un essai = tuile bleue \u00ab en cours \u00bb\",\n         [pEnCours.essaiOuvert, etatTuile(pEnCours)], [true, \"encours\"]);\n      ok(\"etatTuile : une cible CPP pos\u00e9e mais rien de chiffr\u00e9 = \u00e0 chiffrer\",\n         etatTuile({ gainActe: 0, gainProjete: 0, essaiOuvert: false, cibleCPP: 0.3 }), \"aChiffrer\");\n      ok(\"etatTuile : rien du tout = opportunit\u00e9\",\n         [etatTuile(p30), etatTuile(null)], [\"opportunite\", \"opportunite\"]);\n\n      /* --- la cible et le chemin viennent de la r\u00e9f\u00e9rence DOMINANTE (volume) --- */\n      ok(\"gainPoste : la cible vient de la r\u00e9f\u00e9rence dominante (la plus grosse)\",\n         [p10.refDominante.nom, p10.cibleCPP], [\"356x26\", 0.3]);\n      /* v4.51.1 (revue crois\u00e9e Z Code \u00a72) : un poste ENTI\u00c8REMENT ACT\u00c9 doit voir son chemin\n         bouger. Si \u00ab en cours \u00bb ignorait le sc\u00e9nario pass\u00e9 en s\u00e9rie, un gain r\u00e9alis\u00e9 ne\n         ferait avancer que gainActe et la barre prod \u2192 cible resterait fig\u00e9e \u2014 exactement\n         le chiffre que la hi\u00e9rarchie doit voir. On verrouille la s\u00e9mantique ici. */\n      const refActe = normalizeReference({ id: \"rAc\", nom: \"356x26\", productionAnnuelle: \"100000\", cibleCPP: \"0.015\", ops: [\n        { id: \"oAc\", nom: \"OP10\", config: opCfg(), scenarios: [\n          { id: \"pAc\", name: \"Prod\", baseline: true, outils: [ { id: \"uAc1\", numero: \"T\", logements: [ { id: \"lAc1\", nom: \"Bol\", prix: 30, aretes: 8, charniere: 100 } ] } ] },\n          { id: \"eAc\", name: \"SL500\", statut: \"serie\", outils: [ { id: \"uAc2\", numero: \"T\", logements: [ { id: \"lAc2\", nom: \"Bol\", prix: 5, aretes: 8, charniere: 100 } ] } ] } ] } ] });\n      const pAc = gainPoste(normalizeLigne({ id: \"LAC\", nom: \"EMAG 1\", references: [ refActe ] }), \"OP10\", LS);\n      ok(\"gainPoste : un poste enti\u00e8rement act\u00e9 TEINT le chemin prod \u2192 cible\",\n         [pAc.coutEnCours < pAc.coutProd, pAc.chemin > 0, pAc.chemin <= 100], [true, true, true]);\n      /* ici le gain d\u00e9passe la cible (0,00625 < 0,015) : le chemin se PLAFONNE \u00e0 100 %,\n         c'est le comportement voulu \u2014 la carte ne montrera pas \u00ab 175 % atteint \u00bb. */\n      ok(\"gainPoste : m\u00eame formule que pieceCPPComplet (4.49) \u2014 le meilleur cr\u00e9dite sans condition de statut\",\n         [pAc.coutEnCours, pAc.chemin], [0.00625, 100]);\n      /* le chemin n'existe que si la prod est AU-DESSUS de la cible. Ici 0,0375 \u20ac/pi\u00e8ce < 0,3 \u20ac :\n         le poste est d\u00e9j\u00e0 sous la cible, il n'y a donc aucun \u00ab chemin \u00bb \u00e0 afficher \u2014 c'est\n         un r\u00e9sultat correct, pas un absent. Test explicite du cas \u00ab il y a un chemin \u00bb. */\n      ok(\"gainPoste : un poste d\u00e9j\u00e0 sous la cible n'affiche aucun chemin\",\n         [p10.chemin, p10.coutProd < p10.cibleCPP], [null, true]);\n      const refGrosGain = normalizeReference({ id: \"rG\", nom: \"gros gain\", productionAnnuelle: \"100000\", cibleCPP: \"0.010\", ops: [\n        { id: \"oG\", nom: \"OP10\", config: opCfg(), scenarios: [\n          { id: \"pG\", name: \"Prod\", baseline: true, outils: [ { id: \"uG1\", numero: \"T\", logements: [ { id: \"lG1\", nom: \"Bol\", prix: 30, aretes: 8, charniere: 100 } ] } ] },\n          { id: \"eG\", name: \"Essai\", statut: \"essai\", outils: [ { id: \"uG2\", numero: \"T\", logements: [ { id: \"lG2\", nom: \"Bol\", prix: 5, aretes: 8, charniere: 100 } ] } ] } ] } ] });\n      const pG = gainPoste(normalizeLigne({ id: \"LG\", nom: \"EMAG 1\", references: [ refGrosGain ] }), \"OP10\", LS);\n      ok(\"gainPoste : un poste au-dessus de sa cible expose un chemin born\u00e9 0-100\",\n         pG.chemin !== null && pG.chemin >= 0 && pG.chemin <= 100, true);\n      /* et born\u00e9 aussi quand le gain projet\u00e9 tire le cours EN DE\u00c7\u00c0 de la cible (plafond 100) */\n      ok(\"gainPoste : le chemin est plafonn\u00e9 \u00e0 100 % quand la cible est d\u00e9pass\u00e9e\",\n         pG.chemin !== null && pG.chemin <= 100, true);\n    }\n\n  } catch(err){\n    T.push({ nom:\"Exception pendant les tests : \" + err.message, pass:false,\n             recu:String(err), attendu:\"aucune exception\" });\n  } finally {\n    // remise en place de l'etat reel, quoi qu'il arrive\n    config = sauve.config; data = sauve.data; lignes = sauve.lignes;\n    projets = sauve.projets; activeProjetId = sauve.activeProjetId; responsables = sauve.responsables;\n    activeLigneId = sauve.activeLigneId; activeReferenceId = sauve.activeReferenceId;\n    activeOpId = sauve.activeOpId; activeId = sauve.activeId;\n  }\n\n    /* \u2500\u2500 v4.66.0 \u2014 LE GARDE-FOU PORTE-OUTIL / LOGEMENT \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n       Benjamin, 30/09 : \u00ab toujours des outils cr\u00e9\u00e9s en double au lieu d'un\n       outil avec 2 logements \u00bb. Le cas r\u00e9el : \u00ab T517 D1 \u00bb existe d\u00e9j\u00e0, et il\n       saisit \u00ab T517 D2 \u00bb \u00e0 c\u00f4t\u00e9. Deux num\u00e9ros, un porte-outil. */\n    {\n      const oUtil = (id, numero, logements) => ({ id, numero, logements: (logements||[]).map(n => normalizeLogement({ nom:n })) });\n      const L1 = [oUtil(\"a\", \"T517 D1\", [\"Logement 1\"]), oUtil(\"b\", \"T517 D2\", [\"Logement 1\"])];\n\n      const p1 = proposerFusionLogement(\"T517 D2\", L1, \"b\");\n      ok(\"garde-fou : \u00ab T517 D2 \u00bb \u00e0 c\u00f4t\u00e9 de \u00ab T517 D1 \u00bb = le m\u00eame porte-outil\", p1 && p1.porte, \"T517\");\n      ok(\"garde-fou : la position propos\u00e9e est D2\", p1 && p1.position, \"D2\");\n      ok(\"garde-fou : mode \u00ab complet \u00bb (la cible est elle-m\u00eame mal saisie)\", p1 && p1.mode, \"complet\");\n      ok(\"garde-fou : la cible est bien l'outil T517 D1\", p1 && p1.cible.id, \"a\");\n\n      ok(\"garde-fou : \u00ab T517 \u00bb sans position ne propose rien\", proposerFusionLogement(\"T517\", L1, \"b\"), null);\n      ok(\"garde-fou : un num\u00e9ro inconnu ne propose rien\", proposerFusionLogement(\"T999 D1\", L1, \"b\"), null);\n      ok(\"garde-fou : si D1 existe d\u00e9j\u00e0 dans la cible, rien \u00e0 proposer\",\n         proposerFusionLogement(\"T517 D1\", [oUtil(\"a\",\"T517 D1\",[\"Logement 1\"]), oUtil(\"b\",\"T517 D1\",[\"Logement 1\"])], \"b\"), null);\n\n      const f1 = fusionnerOutils(L1, \"b\", p1);\n      ok(\"garde-fou : il ne reste qu'UN outil\", f1.length, 1);\n      ok(\"garde-fou : son num\u00e9ro est le porte-outil nu\", f1[0].numero, \"T517\");\n      ok(\"garde-fou : il porte DEUX logements\", f1[0].logements.length, 2);\n      ok(\"garde-fou : le premier se nomme D1\", f1[0].logements[0].nom, \"D1\");\n      ok(\"garde-fou : le second se nomme D2\", f1[0].logements[1].nom, \"D2\");\n      ok(\"garde-fou : l'outil qui survit est celui qui existait d\u00e9j\u00e0\", f1[0].id, \"a\");\n\n      const avecDonnees = [oUtil(\"a\", \"T517 D1\", [\"Logement 1\"]), oUtil(\"b\", \"T517 D2\", [\"Logement 1\"])];\n      avecDonnees[1].logements[0].prix = 12.5; avecDonnees[1].logements[0].aretes = 3; avecDonnees[1].logements[0].charniere = 800;\n      const f2 = fusionnerOutils(avecDonnees, \"b\", proposerFusionLogement(\"T517 D2\", avecDonnees, \"b\"));\n      const d2 = f2[0].logements.find(l => l.nom === \"D2\");\n      ok(\"garde-fou : le prix saisi survit\", d2 && d2.prix, 12.5);\n      ok(\"garde-fou : les ar\u00eates survivent\", d2 && d2.aretes, 3);\n      ok(\"garde-fou : la charni\u00e8re survit\", d2 && d2.charniere, 800);\n\n      const L3 = [oUtil(\"a\", \"T517\", [\"Logement 1\"]), oUtil(\"b\", \"T999 D1\", [\"Logement 1\"])];\n      const p3 = proposerFusionLogement(\"T517 D1\", L3, \"b\");\n      ok(\"garde-fou : cible propre = mode \u00ab simple \u00bb\", p3 && p3.mode, \"simple\");\n      const f3 = fusionnerOutils(L3, \"b\", p3);\n      ok(\"garde-fou (mode simple) : un seul outil, num\u00e9ro inchang\u00e9\", f3.length + \"|\" + f3[0].numero, \"1|T517\");\n      /* v4.71.0 \u2014 Benjamin, 30/09 : \u00ab l'outil a 2 correcteurs D1 et D2, donc\n         2 logements \u00bb. Ce test affirmait jusqu'ici qu'un outil nu [\"Logement 1\"]\n         ACTIONN\u00c9 par D1 devait garder deux logements [\"Logement 1\",\"D1\"].\n         C'est le LOGEMENT FANT\u00d4ME qu'il signalait : trois logements pour deux\n         correcteurs d\u00e8s qu'on saisissait D2. Le provisoire vide est d\u00e9sormais\n         R\u00c9CLAM\u00c9 par la position \u2014 il n'en reste qu'un. */\n      ok(\"garde-fou (mode simple) : le provisoire est r\u00e9clam\u00e9, il n'y a pas de fant\u00f4me\",\n         f3[0].logements.length + \"|\" + f3[0].logements[0].nom, \"1|D1\");\n      /* \u2026et si le provisoire porte D\u00c9J\u00c0 une information, on ne l'\u00e9crase pas :\n         la position est ajout\u00e9e \u00e0 c\u00f4t\u00e9, et l'atelier tranche. */\n      const L3b = [{ id:\"a\", numero:\"T517\", logements:[{ id:\"g1\", nom:\"Logement 1\", mabec:\"MAB-7\", prix:9 }] },\n                   { id:\"b\", numero:\"T517 D1\", logements:[{ id:\"h1\", nom:\"Logement 1\" }] }];\n      const f3b = fusionnerOutils(L3b, \"b\", proposerFusionLogement(\"T517 D1\", L3b, \"b\"));\n      ok(\"garde-fou : un provisoire qui porte un MABEC n'est jamais \u00e9cras\u00e9\",\n         f3b[0].logements.some(l => l.mabec === \"MAB-7\"), true);\n      ok(\"garde-fou : la position vient s'ajouter \u00e0 c\u00f4t\u00e9\", f3b[0].logements.length, 2);\n\n      const L4 = [oUtil(\"a\", \"T517 D1\", [\"Bol\"]), oUtil(\"b\", \"T517 D2\", [\"Logement 1\"])];\n      const f4 = fusionnerOutils(L4, \"b\", proposerFusionLogement(\"T517 D2\", L4, \"b\"));\n      ok(\"garde-fou : un logement au nom d'atelier n'est jamais renomm\u00e9\", f4[0].logements[0].nom, \"Bol\");\n      ok(\"garde-fou : le logement par d\u00e9faut devient la position\", f4[0].logements[1].nom, \"D2\");\n      ok(\"garde-fou : aucun logement n'est DUPLIQU\u00c9 (2, pas 3)\", f4[0].logements.length, 2);\n      /* le cas pi\u00e9ge : le doublon porte un logement AU NOM aussi. Il doit \u00eatre\n         vers\u00e9 tel quel, et il ne faut surtout pas le DUPLIQUER en le treating\n         comme un \u00ab Logement N \u00bb par defaut. */\n      const L4b = [oUtil(\"a\", \"T517 D1\", [\"Logement 1\"]), oUtil(\"b\", \"T517 D2\", [\"Piste exterieur\"])];\n      const f4b = fusionnerOutils(L4b, \"b\", proposerFusionLogement(\"T517 D2\", L4b, \"b\"));\n      ok(\"garde-fou : un logement nomm\u00e9 du doublon est vers\u00e9 tel quel\", f4b[0].logements[1].nom, \"Piste exterieur\");\n      ok(\"garde-fou : et il n'est pas dupliqu\u00e9\", f4b[0].logements.length, 2);\n      /* et surtout : on NE FABRIQUE PAS un logement \u00ab D2 \u00bb pour satisfaire la\n         convention. Le nom \u00ab Piste exterieur \u00bb porte d\u00e9j\u00e0 l'information ; cr\u00e9er\n         un D2 en plus serait inventer une position qui n'existe pas (\u00a75.6). */\n      ok(\"garde-fou : aucun logement D2 invent\u00e9 quand le doublon porte un nom d'atelier\",\n         f4b[0].logements.some(l => l.nom === \"D2\"), false);\n      /* le cas inverse : un logement par defaut DOES cr\u00e9er la position */\n      const L4c = [oUtil(\"a\", \"T517 D1\", [\"Logement 1\"]), oUtil(\"b\", \"T517 D2\", [\"Logement 1\"])];\n      const f4c = fusionnerOutils(L4c, \"b\", proposerFusionLogement(\"T517 D2\", L4c, \"b\"));\n      ok(\"garde-fou : un logement par d\u00e9faut DEVIENT bien la position D2\",\n         f4c[0].logements.some(l => l.nom === \"D2\"), true);\n      ok(\"garde-fou : et il n'y a toujours que deux logements\", f4c[0].logements.length, 2);\n\n      const L5 = [oUtil(\"a\", \"T517 D1\", [\"Logement 1\"]), oUtil(\"b\", \"T517 D2\", [\"Logement 1\"])];\n      const avant = JSON.stringify(L5);\n      fusionnerOutils(L5, \"b\", proposerFusionLogement(\"T517 D2\", L5, \"b\"));\n      ok(\"garde-fou : la fonction est PURE (l'original n'a pas boug\u00e9)\", JSON.stringify(L5), avant);\n      ok(\"garde-fou : sans proposition, elle rend une copie intacte\", fusionnerOutils(L5, \"b\", null).length, 2);\n    }\n  const echecs = T.filter(t => !t.pass);\n  const ancien = document.getElementById(\"testResults\");\n  if(ancien) ancien.remove();\n  const rendu = document.createElement(\"div\");\n  rendu.id = \"testResults\";\n  rendu.setAttribute(\"style\", \"position:fixed; inset:0; z-index:99999; overflow:auto; background:#fff; padding:28px 32px; font:13px/1.55 'Open Sans',Arial,sans-serif; color:#1a1a1a;\");\n  rendu.innerHTML =\n    '<h1 style=\"font-family:\\'Archivo\\',Arial,sans-serif; font-size:24px; margin:0 0 4px;\">Tests du moteur economique</h1>' +\n    '<p style=\"margin:0 0 18px; font-family:\\'IBM Plex Mono\\',Consolas,monospace; font-size:13px; color:' +\n      (echecs.length ? \"#e2001a\" : \"#1a7a3f\") + ';\">' +\n      (T.length - echecs.length) + \"/\" + T.length + \" passes\" +\n      (echecs.length ? \" \u2014 \" + echecs.length + \" en echec\" : \" \u2014 tout est vert\") + \"</p>\" +\n    '<table style=\"border-collapse:collapse; width:100%; max-width:1040px;\">' +\n    T.map(t => '<tr style=\"border-bottom:1px solid #e5e5e5;\">' +\n      '<td style=\"padding:5px 10px 5px 0; width:22px; color:' + (t.pass ? \"#1a7a3f\" : \"#e2001a\") + ';\">' +\n        (t.pass ? \"\u2713\" : \"\u2717\") + \"</td>\" +\n      '<td style=\"padding:5px 10px 5px 0;\">' + escapeAttr(t.nom) + \"</td>\" +\n      '<td style=\"padding:5px 0; font-family:\\'IBM Plex Mono\\',Consolas,monospace; font-size:11.5px; color:#888;\">' +\n        (t.pass ? \"\" : \"obtenu \" + escapeAttr(JSON.stringify(t.recu)) + \" \u00b7 attendu \" + escapeAttr(JSON.stringify(t.attendu))) +\n      \"</td></tr>\").join(\"\") +\n    \"</table>\" +\n    '<button id=\"testClose\" style=\"margin-top:22px; padding:9px 18px; border-radius:999px; border:1px solid #1b5ea6; background:#1b5ea6; color:#fff; font-weight:500; cursor:pointer;\">Fermer</button>';\n  document.body.appendChild(rendu);\n  const btn = document.getElementById(\"testClose\");\n  if(btn) btn.addEventListener(\"click\", () => { rendu.remove(); location.hash = \"\"; });\n  console.table(T.map(t => ({ test: t.nom, ok: t.pass })));\n\n\n\n  /* v4.81.0 \u2014 portes du tampon l\u00e9ger. La r\u00e8gle prot\u00e9g\u00e9e : la synchro de\n     routine ne t\u00e9l\u00e9charge JAMAIS le `donnees` complet \u2014 elle lit le tampon\n     (`select=modifie_le,modifie_par`) et ne paie la lecture lourde que sur\n     d\u00e9cision (premier contact, adoption, fusion). On v\u00e9rifie la porte par\n     typeof ET la l\u00e9g\u00e8ret\u00e9 par la requ\u00eate que la fonction \u00e9crit : un test qui\n     ne regarderait que la pr\u00e9sence de la fonction accepterait un\n     `cloudLireTampon` qui t\u00e9l\u00e9charge 4 Mo. */\n  ok(\"porte cloud : cloudLireTampon existe et est async\",\n     typeof cloudLireTampon, \"function\");\n  ok(\"porte cloud : le tampon lit modifie_le,modifie_par \u2014 JAMAIS le donnees\",\n     [cloudLireTampon.toString().indexOf(\"select=modifie_le,modifie_par\") >= 0,\n      cloudLireTampon.toString().indexOf(\"select=donnees\") >= 0], [true, false]);\n  ok(\"porte cloud : cloudSync passe par le tampon AVANT toute lecture lourde\",\n     [cloudSync.toString().indexOf(\"cloudLireTampon()\") >= 0,\n      cloudSync.toString().indexOf(\"cloudLireTampon()\") < cloudSync.toString().indexOf(\"cloudLireEtat()\")],\n     [true, true]);\n\n  /* v4.81.1 \u2014 LA PORTE DE L'IMPORT. Toute la cha\u00eene du bouton \u00ab \ud83d\udcc2 Importer \u00bb passe\n     par preparerImportDepuis : depuis la 4.53.0, sa ligne livraisons lisait `source`\n     \u2014 le param\u00e8tre d'une AUTRE fonction (migrerArbre) \u2014 et levait une ReferenceError\n     qui mourait en silence dans le onload du FileReader : aucun panneau, aucun\n     message, aucun import. Le 12/10, l'import du fichier fusionn\u00e9 de Benjamin n'a\n     jamais atterri pour cette seule raison \u2014 14 versions pendant lesquelles la\n     porte paraissait ouverte. Le test fait ce que le clic fait : pr\u00e9parer un export\n     format 8 r\u00e9el, livraisons comprises. */\n  ok(\"porte import : preparerImportDepuis prepare un format 8 (lignes, revision, livraisons)\",\n     (()=>{ try{\n             const prep = preparerImportDepuis({ format:8, revision:7,\n               lignes:[{ id:\"lxA\", nom:\"EMAG 1\", references:[{ id:\"rxA\", nom:\"DV 356x26 RPI\",\n                 ops:[{ id:\"oxA\", nom:\"OP10\", ordre:10,\n                   scenarios:[{ id:\"sxA\", name:\"Process\", baseline:true, outils:[] }] }] }] }],\n               projets:[], responsables:[],\n               livraisons:[{ id:\"lv1\", nom:\"Livraison test\", date:\"2026-10-12\" }] });\n             return [prep !== null, prep.nouvellesLignes.length, (prep.livraisons||[]).length, prep.revisionEntrante];\n           }catch(e){ return [\"ReferenceError: \" + e.message]; } })(),\n     [true, 1, 1, 7]);\n\n  /* v4.66.0 \u2014 on RECALCULE le nombre d'\u00e9checs au moment du retour.\n     `echecs` est fig\u00e9 plus haut (pour l'affichage) : un test ajout\u00e9\n     APR\u00c8S ce point ne serait pas compt\u00e9, et un \u00e9chec pourrait se cacher\n     derri\u00e8re un \u00ab 0 \u00e9chec \u00bb. C'est exactement ce qui est arriv\u00e9 ce soir. */\n  return { total: T.length, echecs: T.filter(t => !t.pass).length, details: T };\n\n\n}\n/* v4.42 \u2014 botte secrete : la partie K de l'aide disparait pour les autres acces */\n(function(){\n  const ok = kAutorise();\n  const li = document.querySelector(\".aide-k\");\n  if(li) li.hidden = !ok;\n  const titre = document.getElementById(\"aideTitreK\");\n  if(titre && !ok) titre.textContent = \"Formules du widget Fr\u00b7Fa\";\n})();\nif(location.hash === \"#tests\") runTests();\n\n;\n\n/* ============================================================================\n   PWA (v4.18) \u2014 installation et mise a jour automatique\n   ----------------------------------------------------------------------------\n   manifest.webmanifest et service-worker.js vivent a cote du HTML (publies\n   sur Surge avec lui). Le manifest data: historique n'etait pas installable :\n   Chrome n'ouvre pas la boite d'installation sur un manifest en URL data:.\n   L'enregistrement ne se fait qu'en https ou sur localhost \u2014 en file:// (cle\n   USB, copie locale) le service worker n'a pas de sens et le catch evite\n   toute erreur console. Les ouvertures hors ligne restent assurees par le\n   cache du service worker une fois l'outil installe ou visite une fois.\n   ============================================================================ */\nif(\"serviceWorker\" in navigator && (location.protocol === \"https:\" || location.hostname === \"localhost\" || location.hostname === \"127.0.0.1\")){\n  addEventListener(\"load\", () => { navigator.serviceWorker.register(\"./service-worker.js\").catch(() => {}); });\n}\n" + `
;globalThis.__api = { get TOOL_VERSION(){return TOOL_VERSION;}, normalizeLigne, normalizeReference, normalizeOp, normalizeScenario, normalizeProjet, runTests, lignesDuProjet, projetContientScenario, toggleTagScenario, resoudreTag, matisRecap, libelleEcartMatis, matisPorteOutilPosition, matisClePorteOutil, reparerOutilsD1D2, reparerOutilsRapport, detecterOutilsD1D2, migrerOutilsD1D2, compterOutilsD1D2, detecterInversionMabec, migrerInversionMabec, compterInversionsMabec, _matisFeuille, getActiveLigne, preparerImportDepuis, get lignes(){return lignes}, set lignes(v){lignes=v}, get projets(){return projets}, set projets(v){projets=v}, get activeProjetId(){return activeProjetId}, set activeProjetId(v){activeProjetId=v}, get config(){return config}, set config(v){config=v}, get data(){return data}, set data(v){data=v} };
`;
try {
  new Function(api)();
  const A = globalThis.__api;
  const r = A.runTests();
  console.log('VERSION:', A.TOOL_VERSION);
  console.log('RESULTAT:', r.total, 'tests |', r.echecs, 'echecs');
  (r.details||[]).filter(d=>!d.pass).forEach(d=>console.log('  ECHEC:', d.nom, '| recu=', JSON.stringify(d.recu), '| attendu=', JSON.stringify(d.attendu)));
  if(!r.echecs) console.log('TOUT EST VERT');

  /* ── v4.63.3 — CONTRASTE DES TOKENS DE SURFACE ──────────────────────────
     Une suite de fonctions pures ne voit pas une couleur : c'est une mesure,
     pas une logique. Le trou a été trouvé par contre-regard le 30/09 — remettre
     --label à 2,81:1 n'a déclenché AUCUN échec, et c'est exactement pour ça
     que personne ne l'avait vu. Ce bloc ferme la porte (constitution §5.6 :
     « un chiffre qu'on ne peut pas justifier n'est pas affiché » — et de même
     une couleur qu'on ne peut pas lire ne s'affiche pas).
     On lit le CSS réel du fichier, pas une constante du test. */
  (function contrasteTokens(){
    const fs = require('fs');
    const html = fs.readFileSync('bilan_economique.html', 'utf8');
    /* On cherche le BLOC :root de référence, pas la première accolade : il
       commence par un commentaire, donc un regex non gore s'arreterait la
       premiere fois et ne verrait aucun token. On prend le premier :root dont
       le corps contient --ink (les autres sont le @media print et le template
       du rapport, autonomes par construction). */
    let corps = null;
    for (const m of html.matchAll(/:root\s*\{/g)) {
      const debut = m.index + m[0].length;
      let prof = 1, i = debut;
      while (i < html.length && prof > 0) {
        const c = html[i];
        if (c === '{') prof++;
        else if (c === '}') prof--;
        i++;
      }
      const bloc = html.slice(debut, i);
      if (/--ink\s*:/.test(bloc)) { corps = bloc; break; }
    }
    if (!corps) { console.log('  CONTRASTE : bloc :root de reference non trouve — test non joue'); process.exitCode = 2; return; }
    const tokens = {};
    for (const m of corps.matchAll(/(--[a-z0-9-]+)\s*:\s*(#[0-9a-fA-F]{3,8})\s*[;,]/g)) {
      tokens[m[1]] = m[2];
    }
    if (!tokens['--ink'] || !tokens['--label']) {
      console.log('  CONTRASTE : tokens de surface absents du bloc lu — test non joue');
      process.exitCode = 2; return;
    }
    function lum(h){
      h = h.trim().replace('#','');
      if (h.length === 3) h = h[0]+h[0]+h[1]+h[1]+h[2]+h[2];
      if (h.length > 6) h = h.substr(0,6);
      const r = parseInt(h.substr(0,2),16)/255, g = parseInt(h.substr(2,2),16)/255, b = parseInt(h.substr(4,2),16)/255;
      const f = c => c <= 0.03928 ? c/12.92 : Math.pow((c+0.055)/1.055, 2.4);
      return 0.2126*f(r) + 0.7152*f(g) + 0.0722*f(b);
    }
    function cr(a,b){ const la = lum(a), lb = lum(b); return (Math.max(la,lb)+0.05)/(Math.min(la,lb)+0.05); }
    /* seuil AA sur texte normal : 4,5:1. Le texte de l'outil est petit
       (libelles 10-11 px), donc on ne negotiate pas a 3:1. */
    const paires = [
      ['--label','--white',    'les intitulés sur une carte'],
      ['--body','--white',     'les paragraphes sur une carte'],
      ['--ink','--white',      'le texte principal sur le fond de page'],
      ['--body','--white',     'les descriptions sur le fond de page'],
      ['--blue','--white',     "le bleu d'action sur une carte"],
      ['--red','--white',      'le rouge CeramTec sur une carte']
    ];
    let joues = 0, echecs = 0;
    for (const [fg, bg, pourquoi] of paires) {
      if (!tokens[fg] || !tokens[bg]) { console.log('  CONTRASTE : token absent --'+fg+' ou --'+bg+' — non teste'); continue; }
      const v = cr(tokens[fg], tokens[bg]);
      joues++;
      const okc = v >= 4.5;
      if (!okc) echecs++;
      console.log((okc?'  ok  ':'  ECHEC ')+'contraste : '+pourquoi+' — '+fg+' '+tokens[fg]+' sur '+bg+' '+tokens[bg]+' = '+v.toFixed(2)+':1 (seuil 4,5:1)');
    }
    if (joues) console.log('  CONTRASTE : '+joues+' paires verifiees sur le CSS reel du fichier, '+echecs+' sous le seuil');
    /* Le contraste compte comme un echec de la suite : on l'ajoute au total
       plutot que de fixer process.exitCode, que le exit() du harnais ecraserait
       (constat du 30/09 — deux lignes plus bas). */
    r.echecs += echecs;
  })();

  /* ── v4.80 — L'IDENTITÉ SPK, ÉCRITE SOIT QU'ELLE PUISSE REVENIR ───────────
     Constat du Tour 56 : on a restauré la palette v3.15 et surtout la
     hiérarchie de forme (Manrope / Roboto / IBM Plex Mono). Le contre-regard
     a montré qu'UNE SEULE de ces valeurs était gardée : remettre
     --font-disp sur Roboto — c'est-à-dire annuler exactement la plainte de
     Benjamin, « les polices sont les mêmes » — laissait la suite à 497/0
     sans un seul soupir. Le contrôle de contraste ne l'aurait pas vu : il ne
     contrôle pas la FORME, il ne contrôle que le plancher 4,5:1.

     Ces portes referment l'angle mort. Elles lisent le fichier réel, comme
     le contrôle de contraste ; elles ne vivent pas dans runTests(), donc
     elles ne coûtent aucun octet à l'outil déployé. Elles gardent deux choses
     distinctes : les VALEURS de l'identité, et le FAIT qu'il y ait trois
     formes — une ré-application du Design System B doit les faire échouer. */
  (function identiteTokens(){
    const fs = require('fs');
    const html = fs.readFileSync('bilan_economique.html', 'utf8');
    let corps = null;
    for (const m of html.matchAll(/:root\s*\{/g)) {
      const debut = m.index + m[0].length;
      let prof = 1, i = debut;
      while (i < html.length && prof > 0) {
        const c = html[i];
        if (c === '{') prof++;
        else if (c === '}') prof--;
        i++;
      }
      const bloc = html.slice(debut, i);
      if (/--ink\s*:/.test(bloc)) { corps = bloc; break; }
    }
    if (!corps) { console.log('  IDENTITE : bloc :root de reference non trouve — test non joue'); process.exitCode = 2; return; }
    const tok = {};
    for (const m of corps.matchAll(/(--[a-z0-9-]+)\s*:\s*([^;]+);/g)) tok[m[1]] = m[2].trim();

    let joues = 0, echecs = 0;
    const porte = (nom, obtenu, attendu) => {
      joues++;
      const okc = obtenu === attendu;
      if (!okc) echecs++;
      console.log((okc ? '  ok  ' : '  ECHEC ') + 'identité : ' + nom + ' — attendu « ' + attendu
        + ' », lu « ' + obtenu + ' »');
    };

    /* 1. la palette de l'identité SPK by CeramTec (v3.15, restaurée en 4.80) */
    porte("le bleu d'action", tok['--blue'], '#1B5EA6');
    porte('le rouge CeramTec', tok['--red'], '#E2001A');
    porte('le fond de page est gris, pas blanc', tok['--bg'], '#e8eaed');
    porte('le plein bleu des aplats', tok['--fill'], '#1B5EA6');

    /* 2. les rayons : c'est la signature d'un système « quasi-plat » */
    porte('le rayon des cartes', tok['--radius'], '3px');
    porte('le rayon des grandes surfaces', tok['--radius-lg'], '4px');

    /* 3. LA HIÉRARCHIE DE FORME — la porte qui manquait le 02/10.
       Titres et texte ne doivent PAS être la même famille : c'est exactement
       ce que le Design System B avait fait, et ce que Benjamin a vu. */
    const disp = (tok['--font-disp'] || '').split(',')[0].trim().replace(/^'|'$/g, '');
    const body = (tok['--font-body'] || '').split(',')[0].trim().replace(/^'|'$/g, '');
    porte('les titres ont leur propre famille', disp, 'Manrope');
    joues++;
    if (disp === body) {
      echecs++;
      console.log('  ECHEC identité : titres et texte partagent la famille « ' + disp
        + " » — c'est exactement l'aplatissement du Design System B");
    } else {
      console.log('  ok  identité : titres « ' + disp + ' » ≠ texte « ' + body + ' » — trois formes');
    }

    /* 4. Manrope est RÉELLEMENT embarquée, pas seulement nommée dans un token.
       Un token qui promet une police absente du fichier donne un repli
       silencieux : la page aurait l'air de marcher et serait redevenue plate. */
    joues++;
    if (html.indexOf("@font-face{font-family:'Manrope'") < 0) {
      echecs++;
      console.log("  ECHEC identite : Manrope est nommee dans le token mais AUCUN @font-face ne l'embarque");
    } else {
      console.log('  ok  identité : Manrope est embarquée en base64 (aucun appel réseau)');
    }

    /* 5. Les valeurs du Design System B ne doivent plus être là. Une réapplication
       du DS B — par une session qui ne lit pas l'historique — échoue ici. */
    for (const p of [['le bleu du DS B', '#006AB3'], ['le rouge du DS B', '#E30045']]) {
      joues++;
      if (corps.toUpperCase().includes(p[1].toUpperCase())) {
        echecs++;
        console.log('  ECHEC identité : ' + p[0] + ' (' + p[1] + ') est encore dans le bloc :root');
      } else {
        console.log('  ok  identité : ' + p[0] + ' (' + p[1] + ') a bien disparu du bloc :root');
      }
    }

    console.log('  IDENTITE : ' + joues + ' portes verifiees sur le CSS reel du fichier, '
      + echecs + ' en echec');
    r.echecs += echecs;
  })();

  /* ── v4.79 — LE CSS D'IMPRESSION A4 VIT DANS LE DOCUMENT PRINCIPAL ─────────
     Né en 4.53.0 à l'intérieur du template du rapport autonome, le bloc
     body.print-livraison n'a JAMAIS stylé l'outil : l'impression d'une
     livraison rendait l'écran, pas l'A4 (daté au Tour 52, commit a0e4d6e).
     Ce contrôle lit le fichier réel : les règles print-livraison ET
     print-mission doivent exister AVANT le premier <script> — c'est-à-dire
     dans le <head> du document que le navigateur applique vraiment. Une
     question de structure de document, posée au document. */
  (function cssImpression(){
    const fs = require('fs');
    const html = fs.readFileSync('bilan_economique.html', 'utf8');
    const tete = html.slice(0, html.indexOf('<script'));
    const attendus = [
      ['body.print-livraison >', "l'impression A4 d'une livraison"],
      ['body.print-mission >', "l'impression A4 de la mission"],
      ['#missionA4', 'le conteneur de la mission']
    ];
    let vus = 0;
    for (const [a, pourquoi] of attendus) {
      const la = tete.includes(a);
      if (!la) r.echecs++;
      vus++;
      console.log((la ? '  ok  ' : '  ECHEC ') + 'css impression : ' + pourquoi + ' — "' + a + '" ' + (la ? 'present' : 'ABSENT') + ' dans le head du document principal');
    }
    if (vus) console.log('  CSS IMPRESSION : ' + vus + ' regles verifiees dans le head reel du fichier');
  })();
  if (typeof (undefined) !== 'undefined') (undefined)(A);
  /* v4.80 — LE VERDICT FINAL TIENT COMPTE DES GARDE-FOUS.
     runTests() imprime son résumé AVANT que les contrôles de hors-suite ne
     tournent (contraste, identité, CSS d'impression) : sur une régression de
     la palette, la console affichait donc « TOUT EST VERT — 497 tests | 0
     echecs » alors que le process sortait en 1. Le code de sortie, lui, disait
     vrai ; l'écran, non. C'est exactement le défaut qu'on reproche à une
     contre-vérification qui passe sans avoir rien vérifié : un verdict
     affiché ne vaut que s'il couvre tout ce qui a été contrôlé. */
  if (r.echecs > 0) {
    console.log('');
    console.log('VERDICT : ECHEC — ' + r.echecs + ' controle(s) hors runTests() ont échoue.');
    console.log('          (le résumé « 497 tests | 0 echecs » ci-dessus ne les compte pas)');
  } else {
    console.log('');
    console.log('VERDICT : tout est vert — y compris les garde-fous de hors-suite.');
  }
  /* v4.60 (tour 16) : le code de l'outil installe des setInterval (synchro cloud,
     debounce) qui gardent la boucle d'événements de node vivante -- sans exit
     explicite, le process ne rend JAMAIS la main et le verdict, déjà imprimé,
     reste invisible derrière un pipe. Exit code = nombre d'échecs (0 = tout vert),
     utilisable tel quel par n'importe quelle revue croisée. */
  process.exit(r.echecs ? 1 : 0);
} catch(e){ console.log('ERREUR EXEC:', e.message); console.log((e.stack||'').split('\n').slice(0,6).join('\n')); process.exit(2); }
